-- quest.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[10296] = {id=10296,name="The Black Morass",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=2366,description="The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending. You must venture through the timeway leading to the Black Morass . Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at .",rewardXP=430,ends={{npcID=20201}},questType="dungeon"},
[12431] = {id=12431,name="The Conquest Pit: Final Showdown",level=15,requiredLevel=15,faction="horde",expansion=8,zoneID=394,mapID=116,description="You must've really upset Krenna. She and Gorgonna have had a spat and you're wanted in the pit immediately. There are some wild rumors that it's a fight to the death! That would be bad news for you, but great news for our business venture! At any rate, you can't run away from fate... best get in there on the quick and get it over with.",rewardGold=315000,rewardXP=3135,rewardItems={39179,39180,39181,39182,39183},rewardChoices={39181,39183,39182,39179,39180},starts={{npcID=27719}},ends={{npcID=27102}},coords={x=0.224,y=0.638,source="quest_giver",mapID=116},questType="group"},
[12807] = {id=12807,name="The Story Thus Far...",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=210,mapID=118,description="We have much to do, but first I believe a short refresher is in order. We death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest. When you are ready for an earful, speak with me again and I shall provide enlightenment.",rewardXP=430,starts={{npcID=29344}},ends={{npcID=29344}},coords={x=0.196,y=0.48,source="quest_giver",mapID=118},questType="standard"},
[13161] = {id=13161,name="The Rider of the Unholy",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=210,mapID=118,description="It's time that we start cutting off the heads of the beast. I served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless. Rokir 's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious. Be nimble, , and do not take him lightly.",rewardGold=561800,rewardXP=4300,rewardItems={43873,43904,43940,43948},rewardChoices={43904,43948,43940,43873},starts={{npcID=30944}},ends={{npcID=30944}},coords={x=0.54,y=0.71,source="quest_giver",mapID=118},questType="group"},
[13175] = {id=13175,name="Regaining Control",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[13176] = {id=13176,name="Preparing the Delivery",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[13184] = {id=13184,name="Outliving Usefulness",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[24928] = {id=24928,name="To The Ground!",level=15,requiredLevel=15,faction="horde",expansion=8,zoneID=440,mapID=71,description="I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate. Luckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there. Try not to stand downwind.",rewardGold=124440,rewardXP=2090,rewardItems={51547},starts={{npcID=38703}},ends={{npcID=38703}},coords={x=0.718,y=0.454,source="quest_giver",mapID=71},questType="standard"},
[25053] = {id=25053,name="To The Ground!",level=15,requiredLevel=15,faction="alliance",expansion=8,zoneID=440,mapID=71,description="You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing. I mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!",rewardGold=117960,rewardXP=2090,rewardItems={51547},starts={{npcID=38704}},ends={{npcID=38704}},coords={x=0.722,y=0.452,source="quest_giver",mapID=71},questType="standard"},
[27141] = {id=27141,name="Exploding Through",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="What a find! Right here... exactly where my notes predicted it would be. With any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise. That's right, . It's not just a myth. I believe it truly exists. I'll explain more later. For now, just give me a hand with these explosives.",rewardGold=137400,rewardXP=4115,starts={{npcID=44860}},ends={{npcID=45180}},coords={x=0.644,y=0.224,source="quest_giver",mapID=249},questType="standard"},
[27760] = {id=27760,name="Artificial Intelligence",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="Emergency code: 55-729. Upper cerebral cortex functions in expedition members have been compromised. Please report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.",rewardGold=78750,rewardXP=3085,ends={{npcID=206293}},questType="standard"},
[27779] = {id=27779,name="Gnomebliteration",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="I have downloaded my program to the fusion core and have complete control over it. I've created a small pocket of air inside to avoid vaporizing user . I will yield control of all movement functions so I can dedicate my cycles to keeping the core stable. Go down the hill and neutralize as many of the expedition members as possible. My analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers. User , you must be assured that expedition members are without hope.",rewardGold=274800,rewardXP=5145,rewardItems={65773,65774,65775,65776},rewardChoices={65776,65775,65774,65773},starts={{npcID=46750}},ends={{npcID=46750}},coords={x=0.772,y=0.632,source="quest_giver",mapID=249},questType="standard"},
[27961] = {id=27961,name="Out of Place",level=15,requiredLevel=15,faction="both",expansion=8,zoneID=51,mapID=32,description="The gorge is an unforgiving place. We don't get a whole lot of fuzzy wildlife wandering around here. We tried bringing in some wild game, but they haven't fared well at all. There's just no food for them to eat. Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat. We'll never get rid of all the spiders, but we can salvage what few chickens remain. Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.",rewardGold=105000,rewardXP=2090,rewardItems={63212,63213,63214,63215},rewardChoices={63215,63214,63213,63212},starts={{npcID=47267}},ends={{npcID=47267}},coords={x=0.684,y=0.534,source="quest_giver",mapID=32},questType="standard"},
[28028] = {id=28028,name="Siege!",level=15,requiredLevel=15,faction="both",expansion=8,zoneID=51,mapID=32,description="That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight. My summit's already under siege! It's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge. Tell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer. Ye'll find 'em slinkin' around the flats to the east.",rewardGold=257400,rewardXP=2090,starts={{npcID=47393}},ends={{npcID=47393}},coords={x=0.408,y=0.518,source="quest_giver",mapID=32},questType="standard"},
[28404] = {id=28404,name="I'll Do It By Hand",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="Yes, this all looks familiar enough. Thanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction. As soon as I get started, you can count on that titan construct to try and stop me. That's where you come in. I don't need to remind you of what's riding on this. Take down that guardian!",rewardGold=274800,rewardXP=5145,rewardItems={65871,65873,65885},rewardChoices={65873,65885,65871},starts={{npcID=48558}},ends={{npcID=48558}},coords={x=0.39,y=0.232,source="quest_giver",mapID=249},questType="standard"},
[56030] = {id=56030,name="The Warchief's Order",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8499,mapID=862,description="Champion, the Dark Lady summons you. The time has come to set her plan into motion. Our warships are ready to embark. The key to victory over the Alliance is within our grasp. Meet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.",objectivesText="Meet with Nathanos Blightcaller on The Banshee's Wail.",rewardGold=23400,rewardXP=850,ends={{npcID=135691}},coords={mapID=862,source="quest_giver",x=0.584,y=0.626},questType="standard"},
[56031] = {id=56031,name="The Wolf's Offensive",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart. They will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all! Preparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!",objectivesText="Meet with Genn Greymane on the Wind's Redemption.",rewardGold=23400,rewardXP=850,starts={{npcID=153932}},ends={{npcID=153932}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[56034] = {id=56034,name="Re-sizing the Situation",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter! But if we do nothing, Wrathion will die! Desperate times call for massively experimental science, . Take the Re-Sizer v9.0.1 . I'll follow you around and calibrate it. We're going to whip up a giant boar!",objectivesText="Use the Re-Sizer v9.0.1 on 3 Wandering Boars. Progress: Be careful where you point the Re-Sizer v9.0.1 . Make sure you're only using it on the boars in the immediate area.",rewardGold=40,rewardXP=150,rewardItems={170557},starts={{npcID=149899}},ends={{npcID=156280}},coords={x=0.562,y=0.59,source="quest_giver",zoneID=10424},questType="standard"},
[56037] = {id=56037,name="Stealing the Naga's Secrets",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Azerite . Weapons of this power should never be in the hands of the naga.>",objectivesText="Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?",rewardGold=234000,rewardXP=6815,rewardItems={168515},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=327170}},ends={{npcID=153384}},coords={x=0.347,y=0.211,source="quest_giver",zoneID=10052},questType="standard"},
[56038] = {id=56038,name="Working with Purpose",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.",objectivesText="Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?",rewardGold=234000,rewardXP=6815,rewardItems={168810},starts={{npcID=153936}},ends={{npcID=153936}},coords={x=0.37,y=0.27,source="quest_giver",zoneID=10052},questType="standard"},
[56039] = {id=56039,name="We Can't Have Dull Weapons",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="For a squid head, you sure are making my life easier. I guess you get to live long enough to complete another task. Our new weapons are forged from some foreign material that I don't quite trust. You won't catch me sharpening any blades, but the work still needs to get done. Get to it!",objectivesText="Find the special weaponry within Zanj'ir Terrace.",rewardGold=23400,rewardXP=850,starts={{npcID=153936}},ends={{npcID=327170}},coords={x=0.37,y=0.27,source="quest_giver",zoneID=10052},questType="standard"},
[56042] = {id=56042,name="Blingtron 7000",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=16178,mapID=2371,rewardItems={168740,168790,170055,170056,170057,170058,170059,170060},starts={{npcID=153897}},ends={{npcID=153897}},coords={x=0.424,y=0.654,source="quest_giver",mapID=2371},questType="standard"},
[56043] = {id=56043,name="Send the Fleet",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1161,description="This war has cost us dearly, but victory will soon be in our grasp. What remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm. This is our chance, ! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all! The fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.",objectivesText="Speak to Harbormaster Cyrus Crestfall to set sail.",rewardGold=23400,rewardXP=850,starts={{npcID=153932}},ends={{npcID=150087}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[56044] = {id=56044,name="Send the Fleet",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=862,description="The Warchief has entrusted me with a mission of the highest priority, . The mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills. The Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.",objectivesText="Speak to Captain Rez'okun to set sail.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=150187}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[56045] = {id=56045,name="Stealing the Naga's Secrets",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Azerite . Weapons of this power should never be in the hands of the naga.>",objectivesText="Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?",rewardGold=234000,rewardXP=6815,rewardItems={168516},rewardCurrencies={{id=1553,amount=600}},starts={{npcID=327170}},ends={{npcID=153421}},coords={x=0.347,y=0.211,source="quest_giver",zoneID=10052},questType="standard"},
[56046] = {id=56046,name="Working with Purpose",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.",objectivesText="Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?",rewardGold=234000,rewardXP=6815,rewardItems={168810},starts={{npcID=153936}},ends={{npcID=153936}},coords={x=0.37,y=0.27,source="quest_giver",zoneID=10052},questType="standard"},
[56047] = {id=56047,name="We Can't Have Dull Weapons",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="For a squid head, you sure are making my life easier. I guess you get to live long enough to complete another task. Our new weapons are forged from some foreign material that I don't quite trust. You won't catch me sharpening any blades, but the work still needs to get done. Get to it!",objectivesText="Find the special weaponry within Zanj'ir Terrace.",rewardGold=117000,rewardXP=3410,starts={{npcID=153936}},ends={{npcID=327170}},coords={x=0.37,y=0.27,source="quest_giver",zoneID=10052},questType="standard"},
[56049] = {id=56049,name="Deck 'Em",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="That ooze seems really hungry! He ate my backpack, compass, pickaxe, and my hearthstone cards. Get my cards back!",objectivesText="Recover Adalin's Hearthstone Cards. Progress: I'm not leaving till I get my cards back!",rewardGold=257400,rewardXP=1415,rewardItems={168754},starts={{npcID=153538}},ends={{npcID=153538}},coords={x=0.752,y=0.698,source="quest_giver",zoneID=10290},questType="standard"},
[56050] = {id=56050,name="PvP Event: Battle for Nazjatar",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10052,mapID=1355,objectivesText="Clear Nazjatar of the opposing faction and slay Players",questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Clear Nazjatar of the opposing faction and slay Players"}},worldTaskTitle="PvP Event: Battle for Nazjatar",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[56053] = {id=56053,name="The Final Act",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Those of us with enough mechanization survived, but it didn't matter. Bondo Bigblock sold us out. In exchange for full mechanization, he built giant bots and attacked Rustbolt. He will continue to act against us, till those few of us left are dead. We must remove this threat immediately.",objectivesText="Kill Bondo Bigblock . Progress: Will you help me deal with this threat?",rewardGold=257400,rewardXP=1415,rewardItems={166846},starts={{npcID=153982}},ends={{npcID=153982}},coords={x=0.728,y=0.338,source="quest_giver",zoneID=10290},questType="standard"},
[56063] = {id=56063,name="Dark Tides",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="A Tidemistress leads the naga in this area. She is performing some damnable ritual outside, demanding sacrifices of our soldiers. Stop her before more of our own meet a cruel fate.",objectivesText="Slay Tidemistress Ethendriss .",rewardGold=468000,rewardXP=8520,rewardItems={163867,163868,163869,163872,163874,163876,163878,163880,170275},rewardChoices={163866,163867,163868,163869,163871,163872,163874,163876,163878,163880,170275},starts={{npcID=150196}},ends={{npcID=150196}},coords={x=0.42,y=0.806,source="quest_giver",zoneID=10052},questType="standard"},
[56070] = {id=56070,name="Vengeance for the Venthyr",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10472,description="Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand. We will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted.",objectivesText="Defeat the Jailer's lieutenants on floors 5 and 10 of the Jailer's Tower.",questType="standard"},
[56071] = {id=56071,name="De-Synced Vibro Blade",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10290,mapID=1462,description="The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.",objectivesText="Give the De-Synced Vibro Blade to Ricket in Rustbolt.",rewardGold=2000,rewardXP=1415,rewardItems={166846},questType="standard"},
[56072] = {id=56072,name="De-Synced Vibro Blade",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.",objectivesText="Give the De-Synced Vibro Blade to Sapphronetta Flivvers in Rustbolt. Provided item:",rewardGold=2000,rewardXP=1415,rewardItems={166846},questType="standard"},
[56086] = {id=56086,name="Blueprint: Holographic Digitalization Relay",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Pascal-K1N6 's database in Rustbolt.>",objectivesText="Upload the blueprint to Pascal-K1N6 's database. Provided item:",rewardGold=257400,ends={{npcID=150359}},coords={mapID=1462,source="quest_giver",x=0.714,y=0.325},questType="standard"},
[56087] = {id=56087,name="Blueprint: Experimental Adventurer Augment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Pascal-K1N6 's database in Rustbolt.>",objectivesText="Upload the blueprint to Pascal-K1N6 's database. Provided item:",rewardGold=309800,ends={{npcID=150359}},coords={mapID=1462,source="quest_giver",x=0.714,y=0.325},questType="standard"},
[56091] = {id=56091,name="Usurper's Scent Gland",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you. The Hivemother will be interested in this item.",objectivesText="Take the Usurper's Scent Gland to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172142},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56092] = {id=56092,name="Hivethief's Jelly Stash",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="This ettin was a well known and oft dreaded face among the bees of the Honeyback hive. Their jelly stores will benefit from his demise. The Hivemother will be interested in this item.",objectivesText="Take the Hivethief's Jelly Stash to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172147},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56095] = {id=56095,name="Legacy of Nar'anan",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="Hey there, . Mind helping me out? You see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago. I can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws... Can you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine! Oh, and be sure to write down what you see!",objectivesText="Activate the Memory Pylons in Nar'anan and witness what happened.",rewardGold=234000,rewardXP=6815,starts={{npcID=154143}},ends={{npcID=154143}},coords={x=0.664,y=0.474,source="quest_giver",zoneID=10052},questType="standard"},
[56097] = {id=56097,name="Grime-Coated Disc",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10290,mapID=1462,description="grime-coated disc .>",rewardGold=2000,rewardItems={168393},questType="standard"},
[56098] = {id=56098,name="Defensive in Death",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Instructor Ulooaka will have more insight on how to keep this herb from defending itself.>",objectivesText="Ask Instructor Ulooaka about the tentacles of the Zin'anthid. Provided item:",ends={{npcID=154257}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.53},questType="standard"},
[56103] = {id=56103,name="Ounces of Osmenite",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Instructor Ulooaka knows of still a better way to mine this ore.>",objectivesText="Ask Instructor Ulooaka about the Osmenite Shards . Provided item:",ends={{npcID=154257}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.53},questType="standard"},
[56108] = {id=56108,name="Leaving the Hive",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="Barry might know what's going on.",objectivesText="Speak to Barry in the Honeyback Hatchery.",rewardGold=702000,rewardXP=10225,rewardItems={170069},starts={{npcID=155744},{npcID=155745}},ends={{npcID=155742}},coords={x=0.626,y=0.264,source="quest_giver",zoneID=9042},questType="standard"},
[56116] = {id=56116,name="Even More Recycling",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,objectivesText="Progress: <WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>",rewardGold=128700,rewardItems={168264},starts={{npcID=326027}},ends={{npcID=326027}},coords={x=0.559,y=0.625,source="quest_giver",zoneID=10290},questType="standard"},
[56117] = {id=56117,name="Recyclable Parts",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This bundle of recycling could be valuable. The gnomes in the area appear to be dropping their scrap into some nearby contraptions.>",objectivesText="Collect 1 Bundle of Recyclable Parts Progress: <WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>",rewardGold=514800,rewardXP=1415,rewardItems={168264},ends={{npcID=326027}},questType="standard"},
[56118] = {id=56118,name="Snap Back",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="I have a favor to ask of you, if you would be so kind. Scrollsage Nola gave me this scroll to protect me on my adventures here in Nazjatar . She is a kind soul, but her scroll-work isn't always the most...accurate. You look like a brave adventurer who's seen a thing or two. Could you test out the scroll for me? While you're there you may as well cull their numbers a tad.",objectivesText="Use the Scroll of Busting Power on Snapdragon Terrormaws and slay snapdragons in Nar'anan.",rewardGold=234000,rewardXP=6815,rewardItems={168947},starts={{npcID=154143}},ends={{npcID=154143}},coords={x=0.664,y=0.474,source="quest_giver",zoneID=10052},questType="standard"},
[56119] = {id=56119,name="The Waveblade Ankoan",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Assist the Ankoan in Nazjatar by completing 4 world quests.",objectivesText="Complete any 4 world quests in Nazjatar . Progress: Return to me when you have finished aiding the Ankoan, <name>.",rewardCurrencies={{id=1553,amount=600},{id=1553,amount=3600},{id=1721,amount=35},{id=1721,amount=25}},ends={{npcID=154140}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.556},questType="standard"},
[56120] = {id=56120,name="The Unshackled",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Assist the Unshackled in Nazjatar by completing 4 world quests.",objectivesText="Complete any 4 world quests in Nazjatar . Progress: Return to me when you have finished aiding us, <name>.",rewardCurrencies={{id=1553,amount=600},{id=1553,amount=3600},{id=1721,amount=35},{id=1721,amount=25}},ends={{npcID=154002}},coords={mapID=1355,source="quest_giver",x=0.508,y=0.652},questType="standard"},
[56126] = {id=56126,name="Seams to be a Problem",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="It may be worth talking to Instructor Ulooaka to see if there's a way to prevent this loss from happening.>",objectivesText="Ask Instructor Ulooaka about the Osmenite Dust . Provided item:",ends={{npcID=154257}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.53},questType="standard"},
[56128] = {id=56128,name="Drowning the Horde",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We must strike now before the Horde have a chance to gain a secure foothold. Attack their champions and knock them on their heels.",objectivesText="Kill 25 Horde players in Nazjatar while in War Mode.",rewardItems={168850},starts={{npcID=154653}},ends={{npcID=154653}},coords={x=0.38,y=0.554,source="quest_giver",zoneID=10052},questType="standard"},
[56129] = {id=56129,name="Heroic: Battle for Stromgarde",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[56136] = {id=56136,name="Heroic Warfront: The Battle for Stromgarde",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall! Prepare yourself for battle.",objectivesText="Defeat the Horde at the Battle for Stromgarde.",rewardGold=468000,rewardXP=8520,rewardItems={169197},rewardCurrencies={{id=1717,amount=15},{id=1553,amount=1500}},starts={{npcID=142721}},ends={{npcID=142721}},coords={x=0.66,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[56137] = {id=56137,name="Heroic Warfront: The Battle for Stromgarde",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=1165,description="Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt! Take up arms. The Alliance is upon us.",objectivesText="Defeat the Alliance at the Battle for Stromgarde.",rewardGold=468000,rewardXP=8520,rewardItems={169196},rewardCurrencies={{id=1716,amount=15},{id=1553,amount=1500}},starts={{npcID=138949}},ends={{npcID=138949}},coords={x=0.528,y=0.944,source="quest_giver",zoneID=8670},questType="standard"},
[56142] = {id=56142,name="Adapt, Improve, Overcome!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her. There are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs. Help me obtain the following parts.",objectivesText="20 Pristine Hound Bolts , 4 Steel Tibia XS, and 2 Machined Heel Nut. Progress: We need to start searching!",rewardGold=257400,rewardXP=1415,rewardItems={169212,169213,169214},starts={{npcID=154214}},ends={{npcID=154214}},coords={x=0.718,y=0.358,source="quest_giver",zoneID=10290},questType="standard"},
[56143] = {id=56143,name="The Fate of Professor Elryna",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why! These things use memory cores , little crystals found within the center of the orb. I bet there's one in that old magi tower. There's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!",objectivesText="Defeat the Snapdragon Matriarch , collect the Memory Core , and activate the Memory Pylon to witness the fate of Professor Elryna. Progress: What happened that fateful day?",rewardGold=468000,rewardXP=8520,rewardItems={169207,169209},starts={{npcID=154143}},ends={{npcID=154143}},coords={x=0.664,y=0.474,source="quest_giver",zoneID=10052},questType="standard"},
[56144] = {id=56144,name="Old Nasha's Paw",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="The old bear's paw is sticky with honey. She likely ransacked a number of hives before you stopped her. The Hivemother will be interested in this item.",objectivesText="Take Old Nasha's paw to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172146},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56145] = {id=56145,name="Blueprint: Advanced Adventurer Augment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Pascal-K1N6 's database in Rustbolt.>",objectivesText="Upload the blueprint to Pascal-K1N6 's database. Provided item:",rewardGold=257400,ends={{npcID=150359}},coords={mapID=1462,source="quest_giver",x=0.714,y=0.325},questType="standard"},
[56148] = {id=56148,name="Call to Arms: Nazjatar",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=862,description="Our objectives in Nazjatar are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.",objectivesText="Slay Alliance within Nazjatar .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=75}},starts={{npcID=143536},{npcID=154641}},ends={{npcID=143536},{npcID=154641}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[56161] = {id=56161,name="Back Out to Sea",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Now that things're under control here, I'm sure they could use your help back in Nazjatar ! Why don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?",objectivesText="Return to Newhome in Nazjatar .",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=151848}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[56162] = {id=56162,name="Back Out to Sea",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Now that things're under control here, I'm sure they could use your help back in Nazjatar ! Why don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?",objectivesText="Return to Mezzamere in Nazjatar .",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=150101}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[56165] = {id=56165,name="Blueprint: Extraordinary Adventurer Augment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Pascal-K1N6 's database in Rustbolt.>",objectivesText="Upload the blueprint to Pascal-K1N6 's database. Provided item:",rewardGold=257400,ends={{npcID=150359}},coords={mapID=1462,source="quest_giver",x=0.714,y=0.325},questType="standard"},
[56166] = {id=56166,name="The Needs of the People",level=26,requiredLevel=26,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up. Be sure to report what you find to Speaker Utia.",objectivesText="Speak to people in Mezzamere about things they need.",rewardGold=234000,rewardXP=3575,questType="standard"},
[56167] = {id=56167,name="Investigating the Highlands",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=4922,mapID=114,description="When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold. Though I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest. She was last seen in the Vermillion Redoubt in Twilight Highlands. I fear she may be in trouble. We must hurry.",objectivesText="Meet Kalecgos in the Twilight Highlands.",rewardGold=23400,rewardXP=850,starts={{npcID=152365}},ends={{npcID=152720}},coords={x=0.524,y=0.69,source="quest_giver",zoneID=9667},questType="standard"},
[56168] = {id=56168,name="Factory Refurbished",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I need you to get us a Recycled Crawler Manifold . You should be able to get one up at Junkwatt Depot if you recycle parts found there.",objectivesText="Recycled Crawler Manifold obtained. Progress: Head up to the Junkwatt Depot and get working!",rewardGold=257400,rewardXP=1415,rewardItems={169153},starts={{npcID=150573}},ends={{npcID=150573}},coords={x=0.714,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[56172] = {id=56172,name="Other Interests",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Madam Goya is interested in many unusual items other than just rare metals. Keep your eyes out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.",objectivesText="Deliver 5 Curious Murloc Horn to Steelsage Gao . Progress: Have you found these items.",rewardGold=257400,rewardXP=1415,rewardItems={168222},starts={{npcID=152575}},ends={{npcID=152575}},coords={x=0.736,y=0.344,source="quest_giver",zoneID=10290},questType="standard"},
[56173] = {id=56173,name="Other Interests",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Madam Goya is interested in many unusual items other than just rare metals. Keep your eyes out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.",objectivesText="Deliver 5 Unidentified Mass to Steelsage Gao . Progress: Have you found these items.",rewardGold=257400,rewardXP=1415,rewardItems={168222},starts={{npcID=152575}},ends={{npcID=152575}},coords={x=0.736,y=0.344,source="quest_giver",zoneID=10290},questType="standard"},
[56174] = {id=56174,name="Other Interests",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Madam Goya is interested in many unusual items other than just rare metals. Keep your eyes out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.",objectivesText="Deliver 5 Disintegrating Sand Sculpture to Steelsage Gao . Progress: Have you found these items.",rewardGold=257400,rewardXP=1415,rewardItems={168222},starts={{npcID=152575}},ends={{npcID=152575}},coords={x=0.736,y=0.344,source="quest_giver",zoneID=10290},questType="standard"},
[56175] = {id=56175,name="Emission Free",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="We're going to need a few Empty Energy Cells to fill out the battery pack on the mount control assembly. See if you can find me these.",objectivesText="Collect 20 Empty Energy Cells Progress: We need to fix this battery pack.",rewardGold=257400,rewardXP=1415,starts={{npcID=150573}},ends={{npcID=150573}},coords={x=0.714,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[56181] = {id=56181,name="This One's on Me",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I'm sure you agree that Pascal -K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!",objectivesText="Speak to Pascal at Rustbolt in Mechagon .",rewardGold=257400,rewardXP=1415,starts={{npcID=152295}},ends={{npcID=152295}},questType="standard"},
[56184] = {id=56184,name="Pirates, Sea Monsters, Robots",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die. I've scouted the island, and found the locations of three chests that contain mementoes of my father. Do this for me and my family. Recover my father's sword , clothing, and bones from the three chests I've marked.",objectivesText="Recover DeMeza's father's Sword , Clothing and Bones. Progress: Help my recover the remains of my father.",rewardGold=257400,rewardXP=1415,rewardItems={169164,169165,169166},starts={{npcID=154335}},ends={{npcID=154335}},coords={x=0.716,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[56185] = {id=56185,name="Whispers of N'Zoth",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=1161,description="Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.",objectivesText="Speak to Kalecgos in the Chamber of Heart.",rewardGold=23400,rewardXP=850,starts={{npcID=154464},{npcID=155496}},ends={{npcID=152365}},coords={x=0.748,y=0.15,source="quest_giver",zoneID=8568},questType="standard"},
[56186] = {id=56186,name="Spies to the Left and Right",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6006,mapID=433,description="Ebonhorn cannot resist the whispers for long. The dark forces that once corrupted the black dragonflight seek to overwhelm the world once again. We need a way to fight back. While I am loathe to mention him, I do know of someone who has been studying the Old Gods in order to better combat their insidious power: Wrathion. The Black Prince has associates in Pandaria, in the Tavern of the Mists at the Veiled Stair. I suggest you begin your search there. Please hurry, $p.",objectivesText="Seek out Wrathion at the Tavern in the Mists. Progress: The Black Prince isn't here. But we might be able to help you find him.",rewardGold=234000,rewardXP=6815,rewardItems={170471},rewardCurrencies={{id=1553,amount=750}},starts={{npcID=152365}},ends={{npcID=154500}},coords={x=0.524,y=0.69,source="quest_giver",zoneID=9667},questType="standard"},
[56187] = {id=56187,name="Black Winged Shadow",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6006,mapID=433,description="Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find. If I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair. Wrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look. And <class>... it's clear you're not the only one searching for him. Watch your back.",objectivesText="Seek out Wrathion outside the entrance to Blackwing Descent. Progress: My head is still spinning... they showed me... such terrible... tempting things...",rewardItems={170483,171348},starts={{npcID=154500}},ends={{npcID=154874}},questType="standard"},
[56188] = {id=56188,name="To the Catacombs!",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=46,mapID=13,description="I held out as long as I could, but... the whispers were too strong. You must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs. Please, do not allow my failure to bring about his doom!",objectivesText="Seek out Wrathion outside the Karazhan Catacombs. Progress: <It seems the lookout gave his life in service to the Black Prince.>",rewardItems={170486},starts={{npcID=154874}},ends={{npcID=154870}},questType="standard"},
[56189] = {id=56189,name="On the Trail of the Black Prince",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=41,mapID=42,description="<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan. The dead lookout still has a set of keys on him. Perhaps they will unlock the door. With any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>",objectivesText="Enter the Karazhan Catacombs and search for a cure for Ebonhorn. Progress: <The note appears to have been left behind in a hurry, and deliberately placed where you would find it.>",rewardItems={169651,169652,170490,170491},starts={{npcID=154870}},ends={{npcID=154870}},questType="standard"},
[56190] = {id=56190,name="Save Ebonhorn",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="<The potion appears to be powerful and chaotic. It changes color seemingly at random. This must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity. You may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>",objectivesText="Return to the Chamber of Heart and treat Ebonhorn with the Potion of Mental Clarity .",rewardGold=234000,rewardXP=6815,rewardItems={169653},starts={{npcID=155191}},ends={{npcID=151964}},coords={x=0.692,y=0.174,source="quest_giver",zoneID=10638},questType="standard"},
[56205] = {id=56205,name="Just Ptrust Me On This",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8499,mapID=862,description="Ahhh, it is good to see you, . How is de defective one? Still pleased to be at your side? I have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies. I am asking you to trust me. I wish to try something. If I am correct then de two of you will find yourselves airborne as nature intended!",objectivesText="Place your faith in Pa'ku and Kua'fon.",rewardGold=234000,rewardXP=6815,starts={{npcID=127377}},ends={{npcID=127377}},coords={x=0.714,y=0.492,source="quest_giver",zoneID=8499},questType="standard"},
[56206] = {id=56206,name="Heroic: Battle for Stromgarde",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[56209] = {id=56209,name="The Halls of Origination",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types. We'll need tae get in there and re-activate the forge, or else Azeroth will be done for!",objectivesText="Defeat the Amathet forces and reactivate the forge in the Halls of Origination. Progress: Azeroth's gonna be done for if we dun get this thing back online!",rewardGold=468000,rewardXP=8520,starts={{npcID=154532}},ends={{npcID=154532}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[56210] = {id=56210,name="Scrying Stones",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="I have a gift for you, . It's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.",objectivesText="Find treasures hidden away by magic within Nazjatar .",rewardGold=234000,rewardXP=6815,rewardItems={167077,169817},starts={{npcID=153512}},ends={{npcID=153512}},coords={x=0.49,y=0.622,source="quest_giver",zoneID=10052},questType="standard"},
[56211] = {id=56211,name="Scrying Stones",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="I have a gift for you, . This stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.",objectivesText="Find treasures hidden away by magic within Nazjatar . Progress: Have you found any treasure?",rewardGold=234000,rewardXP=6815,rewardItems={167077,169817},starts={{npcID=153509}},ends={{npcID=153509}},coords={x=0.378,y=0.556,source="quest_giver",zoneID=10052},questType="standard"},
[56214] = {id=56214,name="Good Girl",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="I have learned so much by your side, I can't believe how many naga we've taken down! When you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope. But now, we see a way out of the darkness of the depths, finally! I took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her. She'll make a great mount... and loyal friend.",objectivesText="Accept a gift from your companion.",rewardItems={169199},starts={{npcID=151300}},ends={{npcID=151300}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56215] = {id=56215,name="Glittering Shell",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="Hi, friend. I just wanted you to know that traveling with you has been the best ever! I never thought I could learn so much about fighting, but now I feel like I can actually hold my own. I will protect all of the wee ones that can't protect themselves! Like this little one. I found him a while back, while we were out. He looked so scared. Hey, why don't you take him?",objectivesText="Accept a gift from your companion.",rewardItems={169353},starts={{npcID=151310}},ends={{npcID=151310}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56216] = {id=56216,name="Last Heirloom",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat. I will be honest with you, friend. I did not think I would live this long. My people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own. This is mine. I have none to pass it on to. I would like you to have it",objectivesText="Accept a gift from your companion.",rewardItems={170155},starts={{npcID=154304}},ends={{npcID=154304}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[56217] = {id=56217,name="Wild Tame",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="In our time together, I have learned much. Both about my own abilities, and about your people. You are selfless in the face of challenge, much like our own. I consider us kin. For some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter. Here, he is yours.",objectivesText="Accept a gift from your companion.",rewardItems={169200},starts={{npcID=150202}},ends={{npcID=150202}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56218] = {id=56218,name="Beauty in the Deeps",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side. Yet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed. There is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors. You see? There is beauty here, even now.",objectivesText="Accept a gift from your companion.",rewardItems={169354},starts={{npcID=154297}},ends={{npcID=154297}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56219] = {id=56219,name="Tome of Tears",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are. I have something to show you... Worst thing we can do is forget. So many names I've written in this book, each and every one of them an Unshackled. All of them gone, now. I will never forget their names. I want you to have it. Tell people. Tell them who they were, and what we have done here.",objectivesText="Accept a gift from your companion.",rewardItems={170154},starts={{npcID=151309}},ends={{npcID=151309}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56234] = {id=56234,name="Friends In Need",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns. We must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet. I fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!",objectivesText="Support your allies in Nazjatar by gaining 3000 experience combined between Farseer Ori, Hunter Akana, and Bladesman Inowari.",rewardGold=468000,rewardXP=8520,rewardItems={168847},starts={{npcID=150101}},ends={{npcID=150101}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[56235] = {id=56235,name="Down Into Nazjatar",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="We have much to do . However our troops are weary and need rest. Decisions made when tired are often the wrong ones. These \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies. Join one of their hunters and aid them in their tasks, we will remain here and discuss our next move.",objectivesText="Support your allies in Nazjatar by getting one to rank 3.",rewardGold=234000,rewardXP=6815,rewardItems={168846},rewardCurrencies={{id=1553,amount=200}},starts={{npcID=151848}},ends={{npcID=151848}},coords={x=0.484,y=0.622,source="quest_giver",zoneID=10052},questType="standard"},
[56236] = {id=56236,name="Down But Not Out",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Ashvane won't trouble us for now, but our situation remains perilous. I must consider our next move, . In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come. We will show them that through unity there are no obstacles that can stand in our way.",objectivesText="Support your allies in Nazjatar by gaining 2400 experience combined between Vim Brineheart, Poen Gillbrack, and Neri Sharpfin.",rewardGold=468000,rewardXP=8520,rewardItems={168847},starts={{npcID=151848}},ends={{npcID=151848}},coords={x=0.484,y=0.622,source="quest_giver",zoneID=10052},questType="standard"},
[56239] = {id=56239,name="Strange Silver Knife",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Ankoan may know more...>",objectivesText="Ask the Ankoan about the knife. Provided item:",rewardGold=23400,rewardXP=850,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56240] = {id=56240,name="Strange Silver Knife",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Unshackled may know more...>",objectivesText="Ask the Unshackled about the knife. Provided item:",rewardGold=23400,rewardXP=850,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56241] = {id=56241,name="Preserved Clues",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We have found similar chests, as you describe. We believe they were left behind by one that came before the naga. Some are even locked by odd arcane runes, the naga seem most interested in those. I know little about them, save that we find them most often in the city ruins. If you seek to decipher their history, I would begin there.",objectivesText="Search in Zin-Azshari for information about the strange arcane chests.",rewardGold=23400,rewardXP=850,starts={{npcID=153510}},ends={{npcID=327591}},coords={x=0.378,y=0.556,source="quest_giver",zoneID=10052},questType="standard"},
[56242] = {id=56242,name="Preserved Clues",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="If you find anything else in those chests that you don't need, you feel free to bring it on over my way. Found a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city. Some are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there. I don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.",objectivesText="Search in Zin-Azshari for information about the strange arcane chests.",rewardGold=23400,rewardXP=850,starts={{npcID=153514}},ends={{npcID=327591}},coords={x=0.492,y=0.62,source="quest_giver",zoneID=10052},questType="standard"},
[56243] = {id=56243,name="Diaries of the Dead",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and...",objectivesText="Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>",rewardGold=234000,rewardXP=6815,starts={{npcID=327591}},ends={{npcID=327592}},coords={x=0.814,y=0.454,source="quest_giver",zoneID=10052},questType="standard"},
[56244] = {id=56244,name="Diaries of the Dead",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and...",objectivesText="Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>",rewardGold=234000,rewardXP=6815,starts={{npcID=327591}},ends={{npcID=327592}},coords={x=0.814,y=0.454,source="quest_giver",zoneID=10052},questType="standard"},
[56245] = {id=56245,name="Enchanted Lock",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>",objectivesText="Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>",rewardGold=234000,rewardXP=6815,starts={{npcID=327592}},ends={{npcID=327592}},coords={x=0.789,y=0.412,source="quest_giver",zoneID=10052},questType="standard"},
[56246] = {id=56246,name="Enchanted Lock",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>",objectivesText="Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>",rewardGold=234000,rewardXP=6815,starts={{npcID=327592}},ends={{npcID=327592}},coords={x=0.789,y=0.412,source="quest_giver",zoneID=10052},questType="standard"},
[56247] = {id=56247,name="Treasure Tale",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Artisan Itanu will surely enjoy hearing the end of this tale.>",objectivesText="Return to Artisan Itanu in Nazjatar .",rewardGold=468000,rewardXP=8520,starts={{npcID=327592}},ends={{npcID=153510}},coords={x=0.789,y=0.412,source="quest_giver",zoneID=10052},questType="standard"},
[56248] = {id=56248,name="Treasure Tale",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Finder Palta will surely enjoy hearing the end of this tale.>",objectivesText="Return to Finder Palta in Newhome in Nazjatar .",rewardGold=468000,rewardXP=8520,starts={{npcID=327592}},ends={{npcID=153514}},coords={x=0.789,y=0.412,source="quest_giver",zoneID=10052},questType="standard"},
[56249] = {id=56249,name="I Am the Trashmaster",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10225,mapID=1165,description="Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...",objectivesText="Give Jani the Trashmaster's Mantle .",rewardGold=257400,rewardXP=1415,rewardItems={169394},starts={{npcID=126334}},ends={{npcID=126334}},coords={x=0.354,y=0.078,source="quest_giver",zoneID=8670},questType="standard"},
[56250] = {id=56250,name="I Am the Trashmaster",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=8501,mapID=864,description="Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...",objectivesText="Give Jani the Trashmaster's Mantle .",rewardItems={169394},starts={{npcID=136559}},ends={{npcID=136559}},questType="standard"},
[56256] = {id=56256,name="The Battle of Alterac",level=20,requiredLevel=20,faction="alliance",expansion=8,zoneID=267,mapID=25,description="The Explorers' League believes there are artifacts in Alterac Valley , but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar . With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley . Vanquish him, and then return to me.",objectivesText="Enter Alterac Valley , defeat the Horde general Drek'thar .",rewardGold=1024800,rewardXP=4150,rewardCurrencies={{id=1602,amount=250}},starts={{npcID=154478}},ends={{npcID=13816}},questType="pvp"},
[56257] = {id=56257,name="The Battle for Alterac",level=20,requiredLevel=20,faction="horde",expansion=8,zoneID=267,mapID=25,description="The Stormpike dwarves and their allies have invaded Alterac Valley , and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike ! You will find Vanndar in Dun Baldar, in the north of Alterac Valley . Destroy him, , and then return to me.",objectivesText="Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike .",rewardGold=1024800,rewardXP=4150,rewardCurrencies={{id=1602,amount=250},{id=1602,amount=150}},starts={{npcID=154473}},ends={{npcID=154473},{npcID=13817}},questType="pvp"},
[56258] = {id=56258,name="Ivus the Forest Lord",level=20,requiredLevel=20,faction="alliance",expansion=8,zoneID=10458,description="The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked. The damage has grown too great for the Circle to control! Ivus must be called to our aid. The Frostwolf soldiers carry elemental charms called storm crystals . We can use the charms to conjure Ivus. Venture forth and claim the crystals, !",objectivesText="Slay Horde and loot a Storm Crystal and return it to Archdruid Renferal in Alterac Valley . Progress: Have you brought us some crystals, <name>?",starts={{npcID=154476}},ends={{npcID=13442}},questType="pvp"},
[56259] = {id=56259,name="Lokholar the Ice Lord",level=20,requiredLevel=20,faction="horde",expansion=8,zoneID=10458,description="I come from Thunder Bluff, . Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times. But let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin. Victory will be assured when the elemental lord is loosed upon the Stormpike army.",objectivesText="Slay Alliance and loot Stormpike Blood and return it to Primalist Thurloga within Frostwolf Village in Alterac Valley . Progress: Have you come with an offering?",starts={{npcID=154474}},ends={{npcID=13236}},questType="pvp"},
[56260] = {id=56260,name="Unlocking the Power",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9667,mapID=1165,description="There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154465}},ends={{npcID=152206}},coords={x=0.51,y=0.888,source="quest_giver",zoneID=8670},questType="standard"},
[56261] = {id=56261,name="Return to the Heart",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=1161,description="Greetings, Champion of Azeroth. MOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger. At least, we think she's pleased. It's difficult tae tell at times. Regardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154464}},ends={{npcID=152206}},coords={x=0.748,y=0.15,source="quest_giver",zoneID=8568},questType="standard"},
[56262] = {id=56262,name="Back to the Chamber",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=1161,description="The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference. Make yer way tae the Chamber o' Heart, champion. Yer talents are needed.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154464}},ends={{npcID=152206}},coords={x=0.748,y=0.15,source="quest_giver",zoneID=8568},questType="standard"},
[56263] = {id=56263,name="Unlocking the Power",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=1161,description="There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,starts={{npcID=154464}},ends={{npcID=152206}},coords={x=0.748,y=0.15,source="quest_giver",zoneID=8568},questType="standard"},
[56267] = {id=56267,name="Whispers of N'Zoth",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9667,mapID=84,description="Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.",rewardGold=23400,rewardXP=850,starts={{npcID=154465},{npcID=155496}},ends={{npcID=152365}},coords={x=0.51,y=0.888,source="quest_giver",mapID=84},questType="standard"},
[56301] = {id=56301,name="Go For The Gold",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! If there's gold to be had here, it's in that fat chest the murlocs are guarding. Kill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.",objectivesText="Recover the Murloc Treasure Bag. Progress: Go get the gold!",rewardGold=22600,rewardXP=1415,rewardItems={169221,169222},starts={{npcID=154485}},ends={{npcID=154485}},coords={x=0.216,y=0.818,source="quest_giver",zoneID=10290},questType="standard"},
[56304] = {id=56304,name="The High Life",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="You there, I require some help. Everyone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. It pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?",objectivesText="Accompany Kelya Moonfall into the Highborne Estates to search for the spirit of her father.",rewardGold=234000,rewardXP=6815,starts={{npcID=154574}},ends={{npcID=154574}},coords={x=0.742,y=0.25,source="quest_giver",zoneID=10052},questType="standard"},
[56305] = {id=56305,name="Let's Fish!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="We may need the help of some friends to land this fish! Use the Hundred-Fathom Lure when you're ready to start.",objectivesText="Catch and kill the Deepwater Maw . Progress: Let's fish!",rewardGold=257400,rewardXP=1415,starts={{npcID=151462}},ends={{npcID=151462}},coords={x=0.37,y=0.472,source="quest_giver",zoneID=10290},questType="group"},
[56306] = {id=56306,name="The Family Jewels",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story! Point is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs. My mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.",objectivesText="Recover 75 Family Jewels Progress: Go steal those jewels back for my brother!",rewardGold=257400,rewardXP=1415,rewardItems={169241},starts={{npcID=154511}},ends={{npcID=154511}},coords={x=0.242,y=0.752,source="quest_giver",zoneID=10290},questType="standard"},
[56309] = {id=56309,name="City of Drowned Friends",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels. This... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me. When I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate. Will you help me search for signs?",objectivesText="Help Shandris Feathermoon search the Drowned Market.",rewardGold=234000,rewardXP=6815,starts={{npcID=154522}},ends={{npcID=154660}},coords={x=0.76,y=0.458,source="quest_giver",zoneID=10052},questType="standard"},
[56310] = {id=56310,name="City of Drowned Friends",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort. It has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them. Will you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.",objectivesText="Help First Arcanist Thalyssra search the Drowned Market.",rewardGold=468000,rewardXP=8520,starts={{npcID=154520}},ends={{npcID=154661}},coords={x=0.734,y=0.478,source="quest_giver",zoneID=10052},questType="standard"},
[56311] = {id=56311,name="The Ever Drowning",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known. I do not feel confident that these trinkets will hold back her power for long, or even be usable afterward. Speak with me when you are ready.",objectivesText="Escort Shandris Feathermoon through the Drowned Market.",rewardGold=234000,rewardXP=6815,starts={{npcID=154660}},ends={{npcID=155071}},coords={x=0.74,y=0.418,source="quest_giver",zoneID=10052},questType="standard"},
[56312] = {id=56312,name="The Ever Drowning",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Queen Azshara has her eye on us now. We must proceed with caution. I do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara. Speak with me when you are ready to proceed.",objectivesText="Escort First Arcanist Thalyssra through the Drowned Market.",rewardGold=234000,rewardXP=6815,starts={{npcID=154661}},ends={{npcID=155325}},coords={x=0.74,y=0.418,source="quest_giver",zoneID=10052},questType="standard"},
[56313] = {id=56313,name="The Warbringer",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.",objectivesText="Commune with the Memory of the Pact . Progress: Be ready for anything.",rewardGold=23400,rewardXP=850,starts={{npcID=155071}},ends={{npcID=155071}},coords={x=0.798,y=0.45,source="quest_giver",zoneID=10052},questType="standard"},
[56314] = {id=56314,name="The Warbringer",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.",objectivesText="Commune with the Memory of the Pact . Progress: Be ready for anything.",rewardGold=23400,rewardXP=850,starts={{npcID=155325}},ends={{npcID=155325}},coords={x=0.798,y=0.45,source="quest_giver",zoneID=10052},questType="standard"},
[56315] = {id=56315,name="They Made Their Choice",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10425,mapID=1355,description="It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid of what we will find if we do find my friend. Wait, did you hear something?",objectivesText="Aid Shandris Feathermoon . Progress: Thrice damned Azshara. Her evil knows no bounds.",rewardGold=468000,rewardXP=8520,starts={{npcID=155071}},ends={{npcID=155071},{npcID=155237}},coords={x=0.798,y=0.45,source="quest_giver",zoneID=10052},questType="standard"},
[56316] = {id=56316,name="They Made Their Choice",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10425,mapID=1355,description="It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid to find Sivara. Wait, did you hear something?",objectivesText="Aid First Arcanist Thalyssra . Progress: Thrice damned Azshara. Her evil knows no bounds.",rewardGold=468000,rewardXP=8520,starts={{npcID=155325}},ends={{npcID=155325},{npcID=155342}},coords={x=0.798,y=0.45,source="quest_giver",zoneID=10052},questType="standard"},
[56319] = {id=56319,name="The Quickcharge Contract",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Wondrous news, dear test subject! My dear brother and I have restored 65% of the functionality of our research laboratory. We are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits! If you're interested, you'll just need to agree to our standard verbal contract first...",objectivesText="Agree to the Quickcharge Contract. Progress: How can I help you, dear test subject?",rewardGold=257400,rewardXP=1415,starts={{npcID=150631}},ends={{npcID=150631}},coords={x=0.708,y=0.384,source="quest_giver",zoneID=10290},questType="standard"},
[56320] = {id=56320,name="Your First Charge is Free!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Do you feel the energy rippling through the ground here, my dear test subject? Without that constant bristle of electricity, nothing of any meaning would exist. My dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon ! If you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.",objectivesText="Gain access to the Charging Station in Bondo's Yard, then use it to charge an Empty Energy Cell.",rewardGold=257400,rewardXP=1415,starts={{npcID=150630}},ends={{npcID=150631}},coords={x=0.708,y=0.39,source="quest_giver",zoneID=10290},questType="standard"},
[56321] = {id=56321,name="Saving Corin",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="My father is being tortured by that naga! , I need you to help me save him. We can't let his spirit be a slave to the naga. Hurry, if we don't act now he will end up like the rest of them!",objectivesText="Defeat Shadowcaster Vixtris .",rewardGold=468000,rewardXP=8520,starts={{npcID=154514}},ends={{npcID=154601}},questType="standard"},
[56322] = {id=56322,name="Contained Alemental",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=1,mapID=27,description="Brewmaster Tsing knows more about such a strange occurrence.>",objectivesText="Talk to Brewmaster Tsing in the Brewfest grounds.",rewardGold=234000,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=327669}},ends={{npcID=73913}},coords={x=0.556,y=0.377,source="quest_giver",zoneID=1},questType="standard"},
[56324] = {id=56324,name="Your First Charge Ain't Free!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? Flux spits behind her.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. Deal? You ain't gettin' any other offers.",objectivesText="Pay Flux 's access fee, then use the Charging Station to charge an Empty Energy Cell. Progress: You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits over her shoulder.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. You ain't gettin' any other offers.",rewardGold=257400,rewardXP=1415,starts={{npcID=154534}},ends={{npcID=154534}},questType="standard"},
[56325] = {id=56325,name="Changing Tides",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it. The guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment. I would trust you with the Javelin of Suramar, . We will need your strength in the coming battle.",objectivesText="Assault the naga camp and seize control of the Tidestone of Golganneth. Progress: If we do not take the Tidestone, we are finished.",rewardGold=702000,rewardXP=10225,rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=150101}},ends={{npcID=153193}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[56335] = {id=56335,name="Wanna Charge? Gotta Pay!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? Flux spits behind her.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. Deal? You ain't gettin' any other offers.",objectivesText="Pay Flux 's access fee, then use the Charging Station to charge an Empty Energy Cell . Progress: You lookin' to charge some energy cells off our tower of power? Save your sob stories. Everyone pays. < Flux spits over her shoulder.> No exceptions.",starts={{npcID=154534}},ends={{npcID=154534}},questType="standard"},
[56336] = {id=56336,name="Uncovering the Artifact Fragments",level=0,requiredLevel=0,faction="alliance",expansion=8,zoneID=8485,mapID=588,description="The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran . Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.",objectivesText="Ecilam in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments . Progress: Are those Artifact Fragments , I see?",rewardGold=341600,starts={{npcID=82966},{npcID=155283}},ends={{npcID=82966},{npcID=155283}},coords={x=0.446,y=0.744,source="quest_giver",zoneID=6941},questType="pvp"},
[56337] = {id=56337,name="Uncovering the Artifact Fragments",level=0,requiredLevel=0,faction="horde",expansion=8,zoneID=8485,mapID=588,description="The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran . Go out and kill any you find and bring at least fifty Artifact Fragments to Fura the Mage in Warspear Outpost.",objectivesText="Fura in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments . Progress: Are those Artifact Fragments , I see?",rewardGold=341600,starts={{npcID=83995},{npcID=155286}},ends={{npcID=83995},{npcID=155286}},coords={x=0.452,y=0.272,source="quest_giver",zoneID=6941},questType="pvp"},
[56338] = {id=56338,name="Volrath Must Die",level=0,requiredLevel=0,faction="alliance",expansion=8,zoneID=8485,mapID=588,description="The Horde are getting in our way of completing our mission here in Ashran . Their leader is High Warlord Volrath. He must be put down. Push forth through the center road, enter Warspear and slay Volrath.",objectivesText="Slay High Warlord Volrath found in the Horde base Warspear within Ashran .",rewardCurrencies={{id=1602,amount=250},{id=1602,amount=150}},starts={{npcID=84173}},ends={{npcID=84173}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=6941},questType="pvp"},
[56339] = {id=56339,name="Tremblade Must Die",level=0,requiredLevel=0,faction="horde",expansion=8,zoneID=8485,mapID=588,description="This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble. Push forward through the center road, make your way into their keep and take down Tremblade. For the Horde!",objectivesText="Slay Grand Marshal Tremblade found in the Alliance base Stormshield Keep within Ashran .",rewardCurrencies={{id=1602,amount=250},{id=1602,amount=150}},starts={{npcID=84473}},ends={{npcID=84473}},coords={x=0.45,y=0.278,source="quest_giver",zoneID=6941},questType="pvp"},
[56341] = {id=56341,name="Direbrew Cog",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=1,mapID=27,description="<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines. Perhaps your Dark Iron allies would be interested in hearing of your victory.>",objectivesText="Talk to Verra Fireblood in the Brewfest grounds.",rewardGold=341600,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=328343}},ends={{npcID=152941}},coords={x=0.556,y=0.377,source="quest_giver",zoneID=1},questType="standard"},
[56344] = {id=56344,name="To Darkmaul Citadel",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel. Meredy has come up with an... interesting plan to rescue the captain. It may be our only chance. Come. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.",objectivesText="Meet Lady Jaina Proudmoore outside of Darkmaul Citadel.",rewardGold=510,rewardXP=505,starts={{npcID=156807},{npcID=245394}},ends={{npcID=156941},{npcID=245397}},coords={x=0.522,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[56346] = {id=56346,name="Ancient Technology",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Perhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>",objectivesText="Bring the Broken Power Core to Instructor Ulooaka in Mezzamere. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={169320},starts={{npcID=327596}},ends={{npcID=154257}},coords={x=0.381,y=0.369,source="quest_giver",zoneID=10052},questType="standard"},
[56347] = {id=56347,name="An Abyssal Opportunity",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="I believe, , we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level. But we're getting ahead of ourselves. The first thing we need to do is repair this device. It'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region. However, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.",objectivesText="Acquire 15 Abyssal Shards from Artisan Okata. Progress: How goes the hunt for the materials?",rewardGold=234000,rewardXP=6815,starts={{npcID=154257}},ends={{npcID=154257}},coords={x=0.38,y=0.53,source="quest_giver",zoneID=10052},questType="standard"},
[56348] = {id=56348,name="The Eternal Palace: We Can Make It Stronger...",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy. Of course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace. Azshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.",objectivesText="Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: How goes the search for those items?",rewardGold=936000,rewardXP=13630,starts={{npcID=154257}},ends={{npcID=154257}},coords={x=0.38,y=0.53,source="quest_giver",zoneID=10052},questType="raid"},
[56349] = {id=56349,name="The Eternal Palace: Pushing the Limits",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Now that we know how to increase the potency of this tool, I think we can push its capabilities even further. Bring me back more of those ornaments. LOTS of them. Let's see just how far we can make this go.",objectivesText="Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: Any luck on retrieving more of those ornaments?",rewardGold=936000,rewardXP=13630,starts={{npcID=154257}},ends={{npcID=154257}},coords={x=0.38,y=0.53,source="quest_giver",zoneID=10052},questType="raid"},
[56350] = {id=56350,name="Scouting the Palace",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We cannot hide here forever, . Azshara must be dealt with. It would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back. I'm getting concerned, . Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.",objectivesText="Speak with Lady Jaina Proudmoore to observe the scouting party. Progress: Are you ready?",rewardXP=10225,rewardItems={169482,169483,169485},rewardChoices={169482,169483,169485},rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=150101}},ends={{npcID=150101}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[56351] = {id=56351,name="The Eternal Palace: Pushing the Limits",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Now that we know how to increase the potency of this thing, I think we can push its capabilities even further. Bring me back more of those ornaments. LOTS of them. Let's see just how far we can make this go.",objectivesText="Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: Any luck on retrieving more of those ornaments?",rewardGold=936000,rewardXP=13630,starts={{npcID=154408}},ends={{npcID=154408}},coords={x=0.492,y=0.618,source="quest_giver",zoneID=10052},questType="raid"},
[56352] = {id=56352,name="The Eternal Palace: We Can Make It Stronger...",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy. Of course that'll require stronger materials to upgrade and the only place I can think of is in the Eternal Palace. Azshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.",objectivesText="Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: How goes the search for those items?",rewardGold=936000,rewardXP=13630,starts={{npcID=154408}},ends={{npcID=154408}},coords={x=0.492,y=0.618,source="quest_giver",zoneID=10052},questType="raid"},
[56353] = {id=56353,name="An Abyssal Opportunity",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="I believe, , we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level. But we're getting ahead of ourselves. The first thing we need to do is repair this device. It'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region. However, Finder Pruc is great at collecting materials like the ones we need. I'd check with him to see what he's got.",objectivesText="Acquire 15 Abyssal Shards from Finder Pruc. Progress: How goes the hunt for the materials?",rewardGold=234000,rewardXP=6815,starts={{npcID=154408}},ends={{npcID=154408}},coords={x=0.492,y=0.618,source="quest_giver",zoneID=10052},questType="standard"},
[56354] = {id=56354,name="Ancient Technology",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Perhaps Rolm back at Newhome could help you repair this core and put it to use against the naga invasion.>",objectivesText="Bring the Broken Power Core to Rolm in Newhome. Provided item:",rewardGold=23400,rewardXP=850,rewardItems={169320},starts={{npcID=327596}},ends={{npcID=154408}},coords={x=0.381,y=0.369,source="quest_giver",zoneID=10052},questType="standard"},
[56355] = {id=56355,name="Battle Tested",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="A weapon like this could really turn the tide against King Mechagons Troops. Let's go see how their gear matches up against our new toy. Take out King Mechagon 's Sentries wherever you can find them",objectivesText="Eliminate 10 Upgraded, Anodized, or Corroded Sentry wherever you find them. Progress: Go kill something!",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=151006}},ends={{npcID=151006}},coords={x=0.698,y=0.33,source="quest_giver",zoneID=10290},questType="standard"},
[56356] = {id=56356,name="The Eternal Palace: Queen's Gambit",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="The way is clear. The palace awaits, . Within the Vainglorious holds court with an old god. Defeating her will be no small feat. Make no mistake, Azshara is one of the most powerful sorceresses alive. We cannot underestimate her power or her planning, for she has had thousands of years to prepare for us. Nevertheless, she must be defeated. We are ready when you are. Shall we finally accept her invitation?",objectivesText="Defeat Queen Azshara in the Eternal Palace . Progress: We cannot rest easy knowing that she still holds power here.",rewardGold=936000,rewardXP=13630,rewardCurrencies={{id=1553,amount=3000}},starts={{npcID=153251}},ends={{npcID=153251}},coords={x=0.506,y=0.24,source="quest_giver",zoneID=10052},questType="raid"},
[56358] = {id=56358,name="The Eternal Palace: Queen's Gambit",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We have opened the way to the palace. We must end this. Queen Azshara is the most powerful sorceress in existence. She mastered magics thousands of years before our archmagi were even born. Still, we must prevail. If not, she and her dark patron will remake all of Azeroth to their desires. Champion, we must defeat Azshara. Are you with us?",objectivesText="Defeat Queen Azshara in the Eternal Palace . Progress: Such power, brought to ruin....",rewardGold=936000,rewardXP=13630,rewardCurrencies={{id=1553,amount=3000}},starts={{npcID=153253}},ends={{npcID=153253}},coords={x=0.504,y=0.24,source="quest_giver",zoneID=10052},questType="raid"},
[56361] = {id=56361,name="Rustbolt Requisitions: Tidespray Linen",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10290,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Gila Crosswire. Progress: I've received an urgent request from Tinkmaster Overspark. These supplies are needed!",rewardGold=257400,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=149813}},ends={{npcID=149813}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
[56362] = {id=56362,name="Rustbolt Requisitions: Tidespray Linen",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10290,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Skaggit . Progress: Gazlowe's orders are in: He wants these supplies ASAP. Ya got the goods?",rewardGold=257400,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=150563}},ends={{npcID=150563}},coords={x=0.738,y=0.258,source="quest_giver",zoneID=10290},questType="standard"},
[56363] = {id=56363,name="Rustbolt Requisitions: Frenzied Fangtooth",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10290,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Gila Crosswire. Progress: I've received an urgent request from Tinkmaster Overspark. These supplies are needed!",rewardGold=250380,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=149813}},ends={{npcID=149813}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
[56364] = {id=56364,name="Rustbolt Requisitions: Frenzied Fangtooth",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10290,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Skaggit . Progress: Gazlowe's orders are in: He wants these supplies ASAP. Ya got the goods?",rewardGold=250380,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=150563}},ends={{npcID=150563}},coords={x=0.738,y=0.258,source="quest_giver",zoneID=10290},questType="standard"},
[56365] = {id=56365,name="Be Kind, Rewind",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="You exist here due to a time anomaly, but you must return to your own time and help us there. The Visual Holo Sphere from the Vaultbot nearby contains the data necessary to defeat King Mechagon before he can use the Mechoriginator. Deliver the Visual Holo Sphere to me in your reality. With luck I will be able to rewind history and prevent this existence from ever happening.",objectivesText="Deliver the Visual Holo Sphere to Izira Geasworn in Rustbolt. Progress: You will have to return to your time period.",rewardGold=257400,rewardXP=1415,rewardItems={169867},starts={{npcID=153982}},ends={{npcID=153641}},coords={x=0.728,y=0.338,source="quest_giver",zoneID=10290},questType="standard"},
[56371] = {id=56371,name="Young Twilight Scale",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=4922,mapID=241,description="<A partially-grown scale from a young twilight whelp. More and more twilight dragons are appearing once again. This seems suspicious. You should show the scale to Eryna above Grim Batol in the Wetlands , perhaps she has seen something recently.>",objectivesText="Show the scale to Eryna above Grim Batol in the Wetlands . Provided item:",starts={{npcID=169346}},ends={{npcID=132888}},questType="standard"},
[56372] = {id=56372,name="Hozen Totem",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=1,mapID=27,description="<The hozen have been successfully chased away, and Brewfest saved once again. The question asks itself, though: How did hozen get to Dun Morogh? Perhaps you should ask somebody who has experience in navigation and travel.>",objectivesText="Talk to Arcti in the Brewfest grounds.",rewardGold=341600,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=328413}},ends={{npcID=152829}},coords={x=0.556,y=0.377,source="quest_giver",zoneID=1},questType="standard"},
[56374] = {id=56374,name="A Titanic Problem",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="We've no time tae waste. Without the Forge of Origination, Azeroth is left vulnerable tae N'Zoth's corruption. Not tae mention it holds a weapon capable of wipin' out all life on Azeroth! We'll need tae head over tae the forge right away. MOTHER can hold down the fort here. Hurry on, I'll meet ye there.",objectivesText="Meet Magni Bronzebeard at the Halls of Origination in Uldum.",rewardGold=34100,rewardXP=850,starts={{npcID=152206}},ends={{npcID=154532}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[56375] = {id=56375,name="To Ramkahen",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="It looks like we're gonna have tae wait a spell while MOTHER figures out what tae do with the forge. In the meantime we'll want tae try to make sure nobody tries tae do any more damage here. Ye should check in on the tol'vir in Ramkahen. I know ye've helped them in the past, so they might be able tae help us keep the forge out o' the wrong hands.",objectivesText="Meet King Phaoris in Ramkahen.",rewardGold=23400,rewardXP=850,starts={{npcID=154532}},ends={{npcID=155095}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[56376] = {id=56376,name="Surfacing Threats",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1527,description="The tol'vir take the protection of the titans' constructs here in Uldum as a sacred duty. However, our numbers have dwindled, and we face greater threats with each day. Even with the strength of our new allies, we will only be able to hold these enemies back for so long. Should any of them surge in power, they may still be able to overwhelm us and endanger the forge. This is where your assistance is needed. Speak to High Commander Kamses to assess our current situation.",objectivesText="Complete an Assault in Uldum.",rewardGold=468000,rewardXP=8520,rewardItems={173280},rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=155095}},ends={{npcID=155095}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="standard"},
[56377] = {id=56377,name="Forging Onward",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="Thanks fer helpin' me back there at the forge. It's vexin' that N'Zoth was able to infiltrate it so quickly, but at least we arrived in time tae keep it from bein' completely wrecked! Now comes the task of gettin' her back tae a hundred percent. MOTHER has been workin' on a solution, and we think we've got a plan.",objectivesText="Return to Magni Bronzebeard at the Chamber of Heart and learn about the fate of the Forge of Origination. Progress: Aye?",rewardGold=23400,rewardXP=850,ends={{npcID=152206}},coords={mapID=1527,x=0.549,y=0.331},questType="standard"},
[56378] = {id=56378,name="The Missing Crew",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1161,description="I can't believe it. Almost the entire fleet.. lost! We need to have ships out there on missions supporting our efforts, but how am I supposed to do that now? If we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.",objectivesText="Find and rescue the missing crew members.",starts={{npcID=135681}},ends={{npcID=135681}},coords={x=0.68,y=0.266,source="quest_giver",zoneID=8568},questType="standard"},
[56379] = {id=56379,name="The Missing Crew",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=862,description="I can't believe it. Almost the entire fleet... lost! We need to have ships out there on missions supporting our efforts, but how am I supposed to do that now? If we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.",objectivesText="Find and rescue the missing crew members.",starts={{npcID=135690}},ends={{npcID=135690}},coords={x=0.584,y=0.63,source="quest_giver",zoneID=8499},questType="standard"},
[56401] = {id=56401,name="A Bolt from the Blue",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=4922,mapID=114,description="You have done much to empower the Heart of Azeroth, and I am proud that the dragonflights have lent their strength to your cause. It is now time for the blue dragonflight to do the same. When I first learned of the essences, I knew that some remnant of my dragonflight's power must be out there, coalescing where we were once strong. That is exactly what I have found. The Kirin Tor have isolated its signature at the Nexus, but only the wielder of the Heart of Azeroth can claim it.",objectivesText="Meet Kalecgos at the Nexus and claim the Charged Scale of the Blue Aspect . Progress: The power of the Heart of Azeroth never ceases to amaze me.",rewardGold=23400,rewardItems={168614,169292},rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=152365}},ends={{npcID=152365},{npcID=152720}},coords={x=0.524,y=0.69,source="quest_giver",zoneID=9667},questType="standard"},
[56405] = {id=56405,name="Cogfrenzy's Construction Frenzy",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="You Rustbolt resisters inspire me. Tinkering, building, exploring. Letting your imagination run wild and then chasing after it, wherever it leads, with reckless abandon! I miss those days. I hope, someday, my conscience will allow me to stay on the surface with you all permanently... Before I return to Mechagon , we must build something incredible. Waren and I have identified a large number of extra construction project sites for today. Build with boldness!",objectivesText="Help build construction projects. Progress: Even the greatest builders are eventually forgotten, but their creations are not.",rewardGold=257400,rewardXP=1415,rewardItems={167844,167845,169470,169471},starts={{npcID=154967}},ends={{npcID=154967}},coords={x=0.734,y=0.334,source="quest_giver",zoneID=10290},questType="standard"},
[56406] = {id=56406,name="Activate Water Object",level=26,requiredLevel=26,faction="none",expansion=8,zoneID=10052,mapID=1355,questType="standard"},
[56410] = {id=56410,name="Discs of Norgannon",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="King Mechagon unit in possession of Norgannon disk. Data is corrupted, possession of such data is dangerous. Please aid in the recovery of Corrupted Disk Fragments that have been discarded via Mechagon waste systems. Deliver recovered Corrupted Disc Fragment to Data Analyzer R33-DR for purging.",objectivesText="Recover Corrupted Disc Fragment Progress: Recover Corrupted Disc Fragment.",rewardGold=257400,rewardXP=1415,rewardItems={169474,169591,169593},starts={{npcID=154982}},ends={{npcID=154122}},coords={x=0.718,y=0.366,source="quest_giver",zoneID=10290},questType="standard"},
[56411] = {id=56411,name="Activate Fire Object",level=26,requiredLevel=26,faction="none",expansion=8,zoneID=10052,mapID=1355,questType="standard"},
[56412] = {id=56412,name="Activate Earth Object",level=26,requiredLevel=26,faction="none",expansion=8,zoneID=10052,mapID=1355,questType="standard"},
[56421] = {id=56421,name="Cracked Numeric Cylinder",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="R33-DR is looking for this item.>",objectivesText="Deliver the item to R33-DR . Progress: Deliver the item to R33-DR .",rewardGold=64350,rewardXP=355,rewardItems={166846},ends={{npcID=154122}},coords={mapID=1462,source="quest_giver",x=0.634,y=0.568},questType="group"},
[56422] = {id=56422,name="On Ghostly Wings",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,description="We will meet you back where our journey began, . Corin and I have been separated for many years. We have so much to catch up on. As a token of our gratitude we will remain in the area to help you in your travels through this cursed land.",objectivesText="Return to Kelya Moonfall in Zin-Azshari.",rewardGold=23400,rewardXP=850,starts={{npcID=154601}},ends={{npcID=154574}},coords={x=0.802,y=0.318,source="quest_giver",zoneID=10052},questType="standard"},
[56423] = {id=56423,name="Large Storage Fragment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="R33-DR is looking for this item.>",objectivesText="Deliver the item to R33-DR . Progress: Deliver the item to R33-DR .",rewardGold=64350,rewardXP=355,rewardItems={166846},ends={{npcID=154122}},coords={mapID=1462,source="quest_giver",x=0.634,y=0.568},questType="group"},
[56424] = {id=56424,name="Rust Covered Disc",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="R33-DR is looking for this item.>",objectivesText="Deliver the item to R33-DR . Progress: Deliver the item to R33-DR .",rewardGold=64350,rewardXP=355,rewardItems={166846},ends={{npcID=154122}},coords={mapID=1462,source="quest_giver",x=0.634,y=0.568},questType="group"},
[56425] = {id=56425,name="Scorched Data Disc",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="R33-DR is looking for this item.>",objectivesText="Deliver the item to R33-DR . Progress: Deliver the item to R33-DR .",rewardGold=64350,rewardXP=355,rewardItems={169474},ends={{npcID=154122}},coords={mapID=1462,source="quest_giver",x=0.634,y=0.568},questType="group"},
[56429] = {id=56429,name="Up Against It",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="I don't like the sound of that... It sounds like an army! We need to investigate. Try not to draw too much attention as we take a look. If there's an army down there, we'll need to move quickly to find refuge.",objectivesText="Move deeper into Nazjatar with Lor'themar and Thalyssra. Progress: These naga move with a single purpose!",rewardGold=234000,rewardXP=6815,starts={{npcID=150196}},ends={{npcID=150196}},coords={x=0.42,y=0.806,source="quest_giver",zoneID=10052},questType="standard"},
[56430] = {id=56430,name="Defensive in Death",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Rolm will have more insight on how to keep this herb from defending itself.>",objectivesText="Ask Rolm about the tentacles of the Zin'anthid. Provided item:",ends={{npcID=154408}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.618},questType="standard"},
[56431] = {id=56431,name="Ounces of Osmenite",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Rolm knows of still a better way to mine this ore.>",objectivesText="Ask Rolm about the Osmenite Shards . Provided item:",ends={{npcID=154408}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.618},questType="standard"},
[56432] = {id=56432,name="Seams to be a Problem",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="It may be worth talking to Rolm to see if there's a way to prevent this loss from happening.>",objectivesText="Ask Rolm about the Osmenite Dust . Provided item:",ends={{npcID=154408}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.618},questType="standard"},
[56433] = {id=56433,name="Drowning the Alliance",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="The Alliance continue to pursue us, they will not disrupt our plans any further. Drive their champions into a watery grave.",objectivesText="Kill 25 Alliance players in Nazjatar while in War Mode.",rewardItems={168850},starts={{npcID=154652}},ends={{npcID=154652}},coords={x=0.488,y=0.608,source="quest_giver",zoneID=10052},questType="standard"},
[56436] = {id=56436,name="Small Skull",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<Inside of the gelatinous remains of the slime you find a small skeleton. Someone in Rustbolt might be missing. You pick up the skull, it might still be able to be identified.>",objectivesText="Show the Small Skull to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=309800,rewardXP=1415,rewardItems={166846,166970},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56437] = {id=56437,name="Rusty Tube",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<The malfunctioning junkbot is now a mere heap of metal, its signature tube poking out of the remains. You remove the tube. The citizens of Rustbolt seem to trade in junk, maybe someone will want it.>",objectivesText="Show the Rusty Tube to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=128700,rewardXP=710,rewardItems={169610},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56438] = {id=56438,name="Flashing Siren",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Mechagon . The citizens of Rustbolt will want to know of its demise.>",objectivesText="Show the Flashing Siren to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=309800,rewardXP=1415,rewardItems={166846,166970},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56439] = {id=56439,name="Mechanical Egg Sac",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="mechanical egg sac inside of the defunct spiderbot. This doesn't make any sense, robots don't reproduce this way. Or do they? Someone in Rustbolt might have the answers.>",objectivesText="Show the Mechanical Egg Sac to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=154900,rewardXP=710,rewardItems={166846,168327},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56440] = {id=56440,name="Can of Critter Spray",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Mechagon . Someone in Rustbolt might be able to provide additional insight.>",objectivesText="Show the Can of Critter Spray to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=309800,rewardXP=1415,rewardItems={166846,168832},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56441] = {id=56441,name="Cluckbox",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Cluckbox .\" This particular mechanical fowl was operating quite strangely. Someone in Rustbolt will probably want to investigate.>",objectivesText="Show the Cluckbox to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=309800,rewardXP=1415,rewardItems={169610},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56442] = {id=56442,name="Broken Unit 6",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<Unit 6 sits here, nonfunctional following your attack. There is something different and unsettling about this mechanical frog. It appeared to be mimicking frog behavior, but in a way that seemed wrong somehow. None of the other mechanical frogs in the area behave similarly. Instead of taking back only part of the unit for inspection, you pocket the entire frog. It's pretty small, after all.>",objectivesText="Show the Broken Unit 6 to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=309800,rewardXP=1415,rewardItems={166846,166971},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56443] = {id=56443,name="Mechanical Eye",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<As the mechanical body of Unit 17 crumples into a heap, one eye lights up. You hear a popping noise, and the eye flies from the head, aided by a small explosion. You pick up the eye and notice it twitch a few times, then power down. The citizens of Rustbolt seem to like junk, maybe they'll be interested in this.>",objectivesText="Show the Mechanical Eye to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:",rewardGold=257400,rewardXP=1415,rewardItems={168327},ends={{npcID=150629}},coords={mapID=1462,source="quest_giver",x=0.693333,y=0.306},questType="standard"},
[56444] = {id=56444,name="Wiggletail's Poking Fork",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Artisan Itanu would be interested?>",objectivesText="Show Wiggletail's Poking Fork to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56445] = {id=56445,name="Wiggletail's Poking Fork",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Finder Palta would be interested?>",objectivesText="Show Wiggletail's Poking Fork to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56446] = {id=56446,name="Leathery Venom Gland",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind. This toxin appears to be very potent. It would be best to bring it back to Mezzamere.>",objectivesText="Show the Leathery Venom Gland to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56447] = {id=56447,name="Half-Digested Deepcoral Pod",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Artisan Itanu might know more.>",objectivesText="Show the Half-Digested Deepcoral Pod to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56448] = {id=56448,name="Molted Spineshell",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Nazjatar . The spines that stick out from it are quite sharp. Artisan Itanu may have some use for this.>",objectivesText="Show the Molted Spineshell to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56449] = {id=56449,name="Pearlescent Shell",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<A large, hardened shell of a vanquished hermit crab. The shell itself was much larger than the crab, and shines in different colors when you look at it at different angles. Surely someone back at Mezzamere would be interested in this beautiful shell.>",objectivesText="Show the Pearlescent Shell to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56450] = {id=56450,name="Eel Jelly",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime. The slime coats your hands and arms, and seems quite difficult to remove. One of your deep sea allies may know more about it.>",objectivesText="Show the Eel Jelly to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56451] = {id=56451,name="Mottled Hydra Scale",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors. There appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>",objectivesText="Show the Mottled Hydra Scale to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56452] = {id=56452,name="Strange Organ",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb. The octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them. Someone in Mezzamere may know more.>",objectivesText="Show the Strange Organ to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56453] = {id=56453,name="Overgrown Stone",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants. You have not seen many such creatures in the deeps. Perhaps there is a story to them. One of your new undersea allies may know more.>",objectivesText="Show the Overgrown Stone to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56454] = {id=56454,name="Crackling Mandible",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<The mandible of a tidal guardian, still crackling with electricity. One of your new allies might have a use for this.>",objectivesText="Show the Crackling Mandible to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56455] = {id=56455,name="Frenzy Fang",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<You remove a fully-grown fang from the fallen frenzy. You have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find use for this?>",objectivesText="Show the Frenzy Fang to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56456] = {id=56456,name="Opaline Conch",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="<The conch slumps following your assault -- the battle appears to be over. It doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack. It appears to be dead, but intact. You consider bringing the entire conch back to your allies in Mezzamere.>",objectivesText="Show the Opaline Conch to Artisan Itanu in Mezzamere in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153510}},coords={mapID=1355,source="quest_giver",x=0.378,y=0.556},questType="standard"},
[56457] = {id=56457,name="Leathery Venom Gland",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind. This toxin appears to be very potent. It would be best to bring it back to Newhome.>",objectivesText="Show the Leathery Venom Gland to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56458] = {id=56458,name="Opaline Conch",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="<The conch slumps following your assault -- the battle appears to be over. It doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack. It appears to be dead, but intact. You consider bringing the entire conch back to your allies in Newhome.>",objectivesText="Show the Opaline Conch to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56459] = {id=56459,name="Half-Digested Deepcoral Pod",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Finder Palta might know more.>",objectivesText="Show the Half-Digested Deepcoral Pod to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56460] = {id=56460,name="Molted Spineshell",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Nazjatar . The spines that stick out from it are quite sharp. Finder Palta may have some use for this.>",objectivesText="Show the Molted Spineshell to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
