[56467] = {id=56467,name="Frenzy Fang",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="<You remove a fully-grown fang from the fallen frenzy. You have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find a use for this?>",objectivesText="Show the Frenzy Fang to Finder Palta in Newhome in Nazjatar . Provided item:",rewardGold=117000,rewardXP=3410,ends={{npcID=153514}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.62},questType="standard"},
[56469] = {id=56469,name="Pirates? I Hate Those Guys!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="old pirate hat . Seems out of place on this island, perhaps Reno Jackson will know what to make of it>",objectivesText="Deliver the old pirate hat to Reno Jackson . Provided item:",rewardGold=238680,rewardXP=1415,rewardItems={166846},ends={{npcID=152502}},coords={mapID=1462,source="quest_giver",x=0.705,y=0.312},questType="standard"},
[56470] = {id=56470,name="Give A Dog A Bone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Louison lent me Dog Bone to help uncover some marrowgrubs, but I'm busy here with the stoves. Could you be a dear and go hunting for me? Dog Bone loves to pounce on the smaller nibblers and makes a lot of noise doing it. That'll scare the larger marrowgrubs into making a run for it. That's when you'll need to make your move. Just use this bone to lure Dog Bone near the nibblers. Oh, and don't forget to harvest the flesh from the marrowgrubs! That's what you're really after.",objectivesText="Collect 12 Marrowgrub Flesh from Giant Marrowgrubs. Progress: Did you collect the meat?",rewardXP=8165,rewardItems={174270,183796},starts={{npcID=161678}},ends={{npcID=161678}},coords={x=0.552,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[56471] = {id=56471,name="Unprofitable Ventures",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="This land is already a monumental disaster, but it could get worse! The Venture Company is here, and will exploit this land for every ounce of profit they can make. We must make their venture here unprofitable, so they will leave. Destroy the three expensive security units with them, and they may leave for more profitable ventures.",objectivesText="Destroy Pummeller Red , Pummeller Orange , and Pummeller Grey",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=155187}},ends={{npcID=155187}},coords={x=0.72,y=0.372,source="quest_giver",zoneID=10290},questType="standard"},
[56472] = {id=56472,name="The Uldum Accord",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="You seek assistance defending the Forge of Origination? It would seem that our goals align. The Halls of Origination are but a small portion of the forge's true scope. Any threat to Uldum would be a potential threat to the forge, and Uldum has found itself with many new enemies of late. We were about to convene the High Council when these Wastewanders arrived unannounced. Perhaps you could join us in learning about these threats?",objectivesText="Learn about the threats facing Uldum in Ramkahen. Progress: We should learn all we can about the threats facing Uldum before we proceed.",rewardGold=23400,rewardXP=850,starts={{npcID=155095}},ends={{npcID=155095}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="standard"},
[56473] = {id=56473,name="Envenomed Spider Fang",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="Even wary bees have been known to fall prey to these enormous spiders. They lie in wait near flowerbeds and ambush them while they collect their harvest. Thanks to you, they have one less spider to worry about. The Hivemother will be interested in this item.",objectivesText="Take the Envenomed Spider Fang to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172145},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56474] = {id=56474,name="Hivekiller Stinger",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="Wasps are a bee's natural enemy, and none are more deadly than this highly specialized killer. It will terrorize the hive no longer, thanks to you. The Hivemother will be interested in this item.",objectivesText="Take the Hivekiller Stinger to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172144},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56475] = {id=56475,name="Spiral Yeti Horn",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="All manner of creatures are attracted to the sweet smell of fresh honey, but relatively few are willing to withstand the painful and often deadly stings of the largest of bees. This yeti, however, has been a persistent thorn in the hive's side, until now. The Hivemother will be interested in this item.",objectivesText="Take the Spiral Yeti Horn to the Honeyback Hivemother for a reward. Provided item:",rewardItems={172143},ends={{npcID=153365}},coords={mapID=942,source="quest_giver",x=0.626667,y=0.263333},questType="standard"},
[56489] = {id=56489,name="Restless Dead",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=139,mapID=1161,description="Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there. We have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.",objectivesText="Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.",rewardGold=23400,rewardXP=850,starts={{npcID=147645}},ends={{npcID=150987}},coords={x=0.5,y=0.468,source="quest_giver",zoneID=8568},questType="standard"},
[56490] = {id=56490,name="Restless Dead",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=139,mapID=1165,description="Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there. We have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.",objectivesText="Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.",rewardGold=23400,rewardXP=850,starts={{npcID=147641}},ends={{npcID=150987}},coords={x=0.562,y=0.31,source="quest_giver",zoneID=8670},questType="standard"},
[56491] = {id=56491,name="Tiny Terrors of Stratholme",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=139,mapID=23,description="Scourge activity inside of Stratholme has increased dramatically in the recent days. The air is thick with the stink of necromancy, and there are screams and shrieks coming from within these walls that will send chills down your spine for weeks to come. I haven't ventured in there yet myself, but there is definitely some new evil stirring from within. I have the keys to this entrance, and can bring you in there to see for yourself. Let me know when you are ready.",objectivesText="Defeat Blackmane . Progress: I can open these gates and bring us in, but it will be up to you to get out safely.",rewardGold=936000,rewardXP=13630,rewardItems={122457},starts={{npcID=150987}},ends={{npcID=150987}},coords={x=0.432,y=0.198,source="quest_giver",zoneID=139},questType="standard"},
[56492] = {id=56492,name="Pet Battle Challenge: Stratholme",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=139,mapID=23,description="The evil presence has returned to Stratholme yet again. That's the problem with necromancy and scourge, they keep reanimating themselves and coming right back! I can bring us in there again, but I suspect all of those evil forces have returned. Are you sure you want to go back in there? That place gives me the creeps. If you really want to head back in there, I will let you back in.",objectivesText="Defeat Blackmane. Progress: I can open this service entrance, but it is up to you to safely get out of Stratholme.",rewardGold=234000,rewardXP=6815,rewardItems={169665},starts={{npcID=150987}},ends={{npcID=150987}},coords={x=0.432,y=0.198,source="quest_giver",zoneID=139},questType="standard"},
[56493] = {id=56493,name="A Direct Approach",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Maokka has such a gentle heart. He is so good with the little ones, always playing games and telling stories. We do however really dislike these Venture Co. individuals, so I suggest a more direct approach. Try killing them all.",objectivesText="Eliminate 12 Venture Co. employees",rewardGold=257400,rewardXP=1415,rewardItems={169682},starts={{npcID=155188}},ends={{npcID=155188}},coords={x=0.72,y=0.372,source="quest_giver",zoneID=10290},questType="standard"},
[56494] = {id=56494,name="The Eve of Battle",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=11403,mapID=1161,description=". The time has come. We may have defeated Azshara, but we still have to deal with Sylvanas. Though our position is not ideal, we have mobilized our available forces and stand ready to finish this war. King Wrynn wanted me to brief you on the situation before we join him. There have been some... interesting developments.",objectivesText="Speak with Mathias Shaw.",rewardGold=23400,rewardXP=850,starts={{npcID=135614}},ends={{npcID=155784}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[56495] = {id=56495,name="They Move Against Us",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=3433,mapID=862,description="The Dark Lady requests your presence in Orgrimmar, . It seems the rats have finally come out of hiding. Which will make it all the easier to exterminate them. Do not delay. We have waited for this moment long enough.",objectivesText="Meet with Sylvanas in Orgrimmar. Progress: The pathetic fools.",rewardGold=23400,rewardXP=850,starts={{npcID=135691}},ends={{npcID=156423}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[56496] = {id=56496,name="The Eve of Battle",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=14,mapID=1165,description=", we must speak of the Horde... and the warchief. The war has proven costly, and the battle against Azshara drained what little resources we had left. The Horde is divided once more and the Alliance fares little better than we do. Sylvanas is now in a position to destroy everyone she considers an enemy. That means us, as well. I had hoped that my old friend would see reason, but now... High Overlord Saurfang is rallying those of us who remain--including some unlikely allies.",objectivesText="Speak with Lor'themar.",rewardGold=23400,rewardXP=850,starts={{npcID=155789}},ends={{npcID=155786}},coords={x=0.5,y=0.96,source="quest_giver",zoneID=8670},questType="standard"},
[56499] = {id=56499,name="Storming the Battlefields",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="We cannot afford to let up on any front, continue to press the war.",objectivesText="Win a PVP Island Expedition, Normal Battleground and Epic Battleground.",rewardItems={168442,168578,168920},rewardChoices={168442,168578,168920},starts={{npcID=143560}},ends={{npcID=143560}},coords={x=0.564,y=0.258,source="quest_giver",zoneID=8568},questType="standard"},
[56500] = {id=56500,name="Storming the Battlefields",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8499,mapID=862,description="We cannot afford to let up on any front, continue to press the war.",objectivesText="Win a PVP Island Expedition, Normal Battleground and Epic Battleground.",rewardItems={168442,168578,168920},rewardChoices={168442,168578,168920},starts={{npcID=143555}},ends={{npcID=143555}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[56501] = {id=56501,name="Taking The Air Out",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This box of rockets could just be used to take out the Venture Co. Balloons. That would really motivate Venture Co. to go somewhere else.>",objectivesText="Eliminate 5 Venture Co. Transports",rewardGold=257400,rewardXP=1415,rewardItems={169681},ends={{npcID=155188}},coords={mapID=1462,source="quest_giver",x=0.72,y=0.372},questType="standard"},
[56504] = {id=56504,name="Wrathion's Journal",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="The whispers ceased as soon as I drank the potion. Thank you, $p. Still, it is gravely concerning that N'Zoth's influence could reach me even within the Chamber of Heart. If Wrathion has found a way to resist the power of the Old Gods, then we can use it to reinforce the Chamber's defenses. Perhaps MOTHER can glean more information from Wrathion's journal .",objectivesText="Deliver Wrathion's incomplete journal to MOTHER . Progress: Awaiting information interface.",rewardGold=23400,rewardXP=850,rewardItems={170493},rewardCurrencies={{id=1553,amount=1000}},starts={{npcID=151964}},ends={{npcID=152194}},coords={x=0.49,y=0.388,source="quest_giver",zoneID=9667},questType="standard"},
[56508] = {id=56508,name="Waste Not",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<There's a variety of parts around this area that might be useful to Rustbolt. You should collect them before Venture Co takes them.>",objectivesText="Collect 20 Useful Bits and Pieces Progress: Grab what things you can!",rewardGold=89550,rewardXP=1415,rewardItems={169686},starts={{npcID=329715}},ends={{npcID=152747}},coords={x=0.408,y=0.387,source="quest_giver",zoneID=10290},questType="standard"},
[56515] = {id=56515,name="Vinyl: Gnomeregan Forever",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Gnomeregan Forever.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>",objectivesText="Install the vinyl into the Rustbolt Gramophone . Provided item:",rewardGold=257400,rewardXP=1415,ends={{npcID=151201}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},questType="standard"},
[56516] = {id=56516,name="Vinyl: Mimiron's Brainstorm",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Mimiron's Brainstorm.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>",objectivesText="Install the vinyl into the Rustbolt Gramophone . Provided item:",rewardGold=257400,rewardXP=1415,ends={{npcID=151201}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},questType="standard"},
[56517] = {id=56517,name="Vinyl: Battle of Gnomeregan",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Battle of Gnomeragan.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>",objectivesText="Install the vinyl into the Rustbolt Gramophone . Provided item:",rewardGold=257400,rewardXP=1415,ends={{npcID=151201}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},questType="standard"},
[56518] = {id=56518,name="Vinyl: Depths of Ulduar",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Depths of Ulduar.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>",objectivesText="Install the vinyl into the Rustbolt Gramophone . Provided item:",rewardGold=257400,rewardXP=1415,ends={{npcID=151201}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},questType="standard"},
[56519] = {id=56519,name="Vinyl: Triumph of Gnomeregan",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Triumph of Gnomeregan.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>",objectivesText="Install the vinyl into the Rustbolt Gramophone . Provided item:",rewardGold=309800,rewardXP=1415,ends={{npcID=151201}},coords={mapID=1462,source="quest_giver",x=0.702,y=0.305},questType="standard"},
[56523] = {id=56523,name="My Chickens are Not for Eating!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="If you've spent any time with that arrogant nitwit, Overspark, you know why I'm here. To silence his boasting and finally prove that my inventions are better! I've released countless mechanical chickens across this island to analyze the technology here, adopt it, and evolve their own circuitry. One of them will become my ultimate battle chicken! But those idiot troggs think my chickens are edible and keep bashing them. Protect them, so my techno-evolutionary experiment can run its course.",objectivesText="Collect 20 Mechanical Giblets and repair the OOX-Bomber/MG. Progress: Imagine being so dumb that you try to eat a mechanical chicken...",rewardGold=257400,rewardXP=1415,rewardItems={169381,169695},starts={{npcID=155254}},ends={{npcID=155254}},coords={x=0.728,y=0.378,source="quest_giver",zoneID=10290},questType="standard"},
[56533] = {id=56533,name="Worldvein Rumors",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="Gather intelligence to assist SI:7 in identifying the location of the Fluctuating Worldvein.",objectivesText="Collect 3 Worldvein Intelligence Reports . Progress: Have you gathered enough intelligence?",ends={{npcID=131290}},coords={mapID=1161,source="quest_giver",x=0.6665,y=0.33},questType="standard"},
[56534] = {id=56534,name="Worldvein Rumors",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=1165,description="Gather more intelligence to assist your followers in tracking down the location of the Fluctuating Worldvein.",objectivesText="Collect 3 Worldvein Intelligence Reports . Progress: Have you gathered enough intelligence?",ends={{npcID=123000}},coords={mapID=1165,source="quest_giver",x=0.445,y=0.955},questType="standard"},
[56536] = {id=56536,name="It's Never Easy",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="The last I heard, Mogu'shan Vaults was still abandoned. We shouldn't have too tough of a time reachin' the engine, since we've already defeated the mogu guardians in that place. Well, what are ye waitin' for? Let's get that engine turned on!",objectivesText="Meet Magni Bronzebeard outside Mogu'shan Vaults in Kun-Lai Summit. Progress: It's never easy, is it?",rewardGold=234000,rewardXP=6815,starts={{npcID=152206}},ends={{npcID=154532}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[56537] = {id=56537,name="The Mysterious Sigil",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=379,description="Lorewalker Cho is well known as font of lore for Pandaria. He may be able to track down the origins of the mogu's sigil.>",objectivesText="Bring the Mysterious Mogu Sigil to Lorewalker Cho at the Seat of Knowledge in Vale of Eternal Blossoms.",rewardGold=23400,rewardXP=850,starts={{npcID=155336}},ends={{npcID=156003}},coords={x=0.596,y=0.392,source="quest_giver",zoneID=5841},questType="standard"},
[56538] = {id=56538,name="Clans of the Mogu",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="You say a mogu asked for your help? This is quite uncharacteristic. I'd be happy to help you uncover the origins of this sigil. To be honest, the prospect of a mogu clan that isn't openly hostile interests me greatly. Just think of the possibilities! Let's get down to business. We'll need to consult the volumes on the various mogu clans in the vale to narrow it down.",objectivesText="Help Lorewalker Cho discover the origin of the Mysterious Mogu Sigil at the Seat of Knowledge. Progress: Why are you talking to me? The knowledge you seek is in the tomes.",rewardGold=117000,rewardXP=3410,starts={{npcID=156003}},ends={{npcID=156003}},coords={x=0.836,y=0.272,source="quest_giver",zoneID=9105},questType="standard"},
[56539] = {id=56539,name="Finding the Rajani",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="Now that we have an idea of who we're looking for, the next question is, where can we find them? With the constant infighting of the mogu, it is likely that each clan would keep tabs on the whereabouts of their competitors. If we can find such information, it may just lead us to the Rajani. Seek out the champions of the mogu. They would be the most likely to carry reports on their enemies' whereabouts.",objectivesText="Collect a Mogu Scouting Report from mogu in the Vale of Eternal Blossoms. Progress: Have you found a scouting report?",rewardGold=234000,rewardXP=6815,rewardItems={170384},starts={{npcID=156003}},ends={{npcID=156003}},coords={x=0.836,y=0.272,source="quest_giver",zoneID=9105},questType="standard"},
[56540] = {id=56540,name="Proof of Tenacity",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="If the Highkeeper is so convinced that we don't stand a chance against our enemies, perhaps a show of force would sway him. I am not sure how you would manage, but if you could bring proof of a victory against those who threaten the Vale, it may convince him that action should be taken.",objectivesText="Obtain a Conqueror's Trophy from the commander of an Assault in the Vale of Eternal Blossoms. Progress: What is it this time?",rewardGold=468000,rewardXP=8520,rewardItems={170385,173835,173836,173837,173838,173839,173840,173841,173842,173843,173844,173845,173846},rewardChoices={173835,173836,173837,173838,173839,173840,173841,173842,173843,173844,173845,173846},rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=154444}},ends={{npcID=154418}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="standard"},
[56541] = {id=56541,name="The Engine of Nalak'sha",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="Your kind have proved me wrong in the past, so I will give you a chance to do so again. The titan structure which houses the Engine of Nalak'sha spans the entirety of Pandaria. There are more ways to reach it than just the Mogu'shan Vaults. There are many such routes, but the closest would be through Mogu'shan Palace. The chambers beneath the palace are interconnected with the vaults. Seek your fate there, champion.",objectivesText="Follow the secret passage within Mogu'shan Palace and re-activate the Engine of Nalak'sha. Progress: Your courage is impressive. I only hope it is not wasted.",rewardGold=468000,rewardXP=8520,starts={{npcID=154418}},ends={{npcID=154418}},coords={x=0.45,y=0.744,source="quest_giver",zoneID=9105},questType="standard"},
[56542] = {id=56542,name="Restored Hope",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1530,description="Your persistence fills me with hope for this world. Let us return to your \"Chamber of Heart.\" As the caretaker of the Forge of Origination, I believe I can help your efforts to restore it. Speak to me when you are ready, and I will bring us there.",objectivesText="Speak with Ra-den to return to the Chamber of Heart.",rewardGold=117000,rewardXP=3410,rewardItems={168436,168573},rewardChoices={168573,168436},starts={{npcID=154418}},ends={{npcID=152206}},coords={x=0.45,y=0.744,source="quest_giver",zoneID=9105},questType="standard"},
[56552] = {id=56552,name="Off-the-Books Brawlin'",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10290,mapID=1462,description="Gazlowe hired you for protection too? I guess it's true that he only hires the best, eh? Ha! Pay's great, but the rules are dung: no fightin' in town, no exceptions. Bah! That tiny tender prince won't give us his tech unless he thinks we're good little angels... Ha! But Gazlowe didn't say nothin' about fightin' outside of town. I got my own squad on the outskirts, ready to brawl with Grumbol's guzzlers if they show their bearded faces. You want in?",objectivesText="Brawl with Grumbol Grimhammer's forces on Mechagon .",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=155355}},ends={{npcID=155355}},coords={x=0.702,y=0.312,source="quest_giver",zoneID=10290},questType="standard"},
[56557] = {id=56557,name="A Little Side Action",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10290,mapID=1462,description="There are only two things more fun than fighting, and the first is talking trash! That boar-beard runt over there's been a thorn in my backside since Alterac... Can't seem to shake him. We got a bet going about who's the best fighter on the island. You want to help me win this wager?",objectivesText="Slay 5 Alliance players in Mechagon .",rewardGold=257400,rewardXP=1415,rewardItems={166846},starts={{npcID=155355}},ends={{npcID=155355}},coords={x=0.702,y=0.312,source="quest_giver",zoneID=10290},questType="standard"},
[56558] = {id=56558,name="Off-the-Books Brawlin'",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="*buuuurrp* Arrrright, listen 'ere. We got ourselves a bit o' a predicament. Besides this dump's ale tastin' like oil, that pigheaded Usha here been sayin' some unfortunate stuff about our troops. Unfortunate FOR HER, 'cuz now *uuuuurp* gonna needya ta rough up any Horde swine ya end up runnin' into out there. Loosely speakin' we ain't supposed to be brawlin' out 'ere, so this ain't a formal order or nothin'...",objectivesText="Brawl with Usha Eyegouge's forces on Mechagon .",rewardGold=257400,rewardXP=1415,rewardItems={166846,166970,166971,246697},starts={{npcID=155357}},ends={{npcID=155357}},coords={x=0.702,y=0.306,source="quest_giver",zoneID=10290},questType="standard"},
[56559] = {id=56559,name="A Little Side Action",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="'Ey, , I could be usin' yer talents fer a little bet I got goin' on with Usha. I'm wagerin' you can beat up five 'o her pals around the island before her dog can beat up five o' ours. Ye up fer it me $ulad:lass;? 'O course ya are, ahahaha!",objectivesText="Slay 5 Horde players in Mechagon .",rewardGold=257400,rewardXP=1415,starts={{npcID=155357}},ends={{npcID=155357}},coords={x=0.702,y=0.306,source="quest_giver",zoneID=10290},questType="standard"},
[56560] = {id=56560,name="A Curious Discovery",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Perhaps the Unshackled would be able to tell you more about it.>",objectivesText="Bring the Enchanting Crystal to Narv in Newhome. Provided item:",rewardGold=234000,rewardXP=6815,rewardItems={167893,169778},starts={{npcID=329805}},ends={{npcID=154393}},coords={x=0.328,y=0.397,source="quest_giver",zoneID=10052},questType="standard"},
[56561] = {id=56561,name="A Curious Discovery",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Perhaps the Ankoan would be able to tell you more about it.>",objectivesText="Bring the Enchanting Crystal to Instructor Okanu in Mezzamere. Provided item:",rewardGold=234000,rewardXP=6815,rewardItems={167893,169778},starts={{npcID=329805}},ends={{npcID=153811}},coords={x=0.328,y=0.397,source="quest_giver",zoneID=10052},questType="standard"},
[56562] = {id=56562,name="The Problem with Shrinkage",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Instructor Ulooaka could share some of his insights.>",objectivesText="Ask Instructor Ulooaka about the shriveled leather hide . Provided item:",ends={{npcID=154257}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.53},questType="standard"},
[56563] = {id=56563,name="The Problem with Shrinkage",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Rolm could share some of his insights.>",objectivesText="Ask Rolm about the shriveled leather hide . Provided item:",ends={{npcID=154408}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.618},questType="standard"},
[56565] = {id=56565,name="Hanging by a Thread",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Instructor Ulooaka could share some of his insights.>",objectivesText="Ask Instructor Ulooaka about the deteriorating cragscales . Provided item:",ends={{npcID=154257}},coords={mapID=1355,source="quest_giver",x=0.38,y=0.53},questType="standard"},
[56566] = {id=56566,name="Hanging by a Thread",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Rolm could share some of his insights.>",objectivesText="Ask Rolm about the deteriorating cragscales . Provided item:",ends={{npcID=154408}},coords={mapID=1355,source="quest_giver",x=0.492,y=0.618},questType="standard"},
[56572] = {id=56572,name="Toys Like Us",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I must share the wonders of this place with all of Azeroth in a way that will entertain young and old alike. I will use the technology here to create a new line of toys unlike anything seen before! My Quasi-Faceted scanner can help construct perfect replicas of things here on the island. I just need a helpful individual such as yourself to scan a few things around this area.",objectivesText="Quasi-Facet scan creatures in Mechagon",rewardGold=257400,rewardXP=1415,rewardItems={169794,169796,169797,169816,169838,169841,169844},starts={{npcID=155450}},ends={{npcID=155450}},coords={x=0.702,y=0.328,source="quest_giver",zoneID=10290},questType="standard"},
[56573] = {id=56573,name="Certified Pre-Owned",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="First, let me say that you will ALWAYS be our favorite test subject. But our experiments require far more sacrifice than a single test subject can offer. And, from time to time, some of those test subjects require new limbs. My dear brother and I have a nascent concept for expanding the average lifespan of mechanical appendages. But we've run out of components to experiment on. Salvage some appendages from the heap outside town so we can continue our experiments.",objectivesText="Collect 15 Salvaged Mechagnome Appendages . Progress: Don't worry about any malfunctioning or missing parts. Gill will help us repair whatever you find.",rewardGold=309800,rewardXP=1415,rewardItems={166970,169807},starts={{npcID=150631}},ends={{npcID=150631}},coords={x=0.708,y=0.384,source="quest_giver",zoneID=10290},questType="standard"},
[56574] = {id=56574,name="Reflections in Amber",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="<A viscous dark ooze drips from this large chunk of amber. Attempting to wipe it off is futile, as the ooze is seemingly created by the amber itself. As you hold it, unintelligible whispers fill the back of your mind. The Shado-Pan will surely want to examine it.>",objectivesText="Bring the Ooze-Covered Amber to the Shado-Pan at the Serpent's Spine.",rewardGold=23400,rewardXP=850,ends={{npcID=155487}},coords={mapID=1530,source="quest_giver",x=0.1316,y=0.7916},questType="standard"},
[56575] = {id=56575,name="Once More Into Kor'vess",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="You found this on a member of the swarm? It seeps with corruption... and with power. We could be faced with a serious threat if the rest of the mantid's amber is similarly corrupted. Far to the west in the Dread Wastes lies Kor'vess, a large kypari tree that provides the swarm with most of its amber. From there, we can determine just how much of their stores have been infused with the energy of the Old Gods. I will meet you closer to the tree.",objectivesText="Investigate Kor'vess.",rewardGold=234000,rewardXP=6815,starts={{npcID=155487}},ends={{npcID=155487}},coords={x=0.118,y=0.938,source="quest_giver",zoneID=9105},questType="standard"},
[56576] = {id=56576,name="Aqir Extermination",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="There are too many of these things flyin' around for us to make a clean getaway. We're liable to get swarmed the second we start up them plane engines! These bugs are going straight back into the ground... one way or another. May as well expedite the process, know what I mean?",objectivesText="Kill 10 Aqir Impalers .",rewardGold=234000,rewardXP=6815,starts={{npcID=159920}},ends={{npcID=159920}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="standard"},
[56577] = {id=56577,name="Crippling the Hive",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6138,mapID=422,description="The mantid here are working feverishly to harvest amber from the tree. Perhaps killing a pawful of them will slow their efforts.",objectivesText="Kill 12 Kor'thik mantid in Kor'vess.",rewardGold=234000,rewardXP=6815,starts={{npcID=155562}},ends={{npcID=155562}},questType="standard"},
[56578] = {id=56578,name="Rotten at the Roots",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6138,mapID=422,description="Underneath Kypari Kor is a large chamber where the mantid tend to the tree. That must be where the source of the corruption lies. We need to get into that chamber and stop them. N'Zoth must not be allowed to empower the swarm.",objectivesText="Stop the source of the corruption within the Morrowchamber.",rewardGold=234000,rewardXP=6815,starts={{npcID=155562}},ends={{npcID=155582}},questType="standard"},
[56580] = {id=56580,name="Amber Secrets",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6138,mapID=422,description="The Morrowchamber houses a small section of the Zara'thik, mantid under immediate directive of the new empress. Some of them may have been given pieces of amber like the one you found. The Shado-Pan would be interested in any extra pieces we can acquire.",objectivesText="Collect 8 pieces of Corrupted Amber. Progress: We always feared this day would come...",rewardGold=234000,rewardXP=6815,rewardItems={169866},starts={{npcID=155582}},ends={{npcID=155582}},coords={x=0.454,y=0.166,source="quest_giver",zoneID=6138},questType="standard"},
[56616] = {id=56616,name="Old Faces, New Problems",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6138,mapID=422,description="One of N'Zoth's minions appears to have taken note of our presence. Shall we pay them a visit?",objectivesText="Kill Watcher Vl'thax . Progress: Is it done?",rewardGold=468000,rewardXP=8520,starts={{npcID=155582}},ends={{npcID=155582}},coords={x=0.454,y=0.166,source="quest_giver",zoneID=6138},questType="standard"},
[56617] = {id=56617,name="A Unified Swarm",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=6138,mapID=422,description="It seemed as though the mantid had been producing the corrupted amber for some time before our... intervention. It stands to reason that they are keeping a stockpile of it somewhere. The Shado-Pan's scouts have been reporting an increased presence of the swarm's warriors in Klaxxi'vess. I would wager that they are guarding the corrupted amber . Meet me there. If we have a chance to destroy that amber, then we need to take it.",objectivesText="Infiltrate Klaxxi'vess.",rewardGold=468000,rewardXP=8520,starts={{npcID=155582}},ends={{npcID=155707}},coords={x=0.454,y=0.166,source="quest_giver",zoneID=6138},questType="standard"},
[56621] = {id=56621,name="Real Ultimate Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="When I say that power is life, I'm not speaking figuratively, my dear test subject. Properly harnessed, power can create life itself--or at least a close enough facsimile for our purposes. There is a massive reserve of discarded technology lurking deep in the mucky depths of the Outflow. As usual, Mechagon 's trash is our treasure. I've finally perfected my device that will animate the sludge to bring that technology up to the surface for you. All you have to do is pop 'em and grab the tech!",objectivesText="Collect 15 discarded technologies from techno-animated sludge. Progress: Please thoroughly document any adverse side effects you experience while using the Spark-7143 .",rewardGold=257400,rewardXP=1415,rewardItems={166970,169824,169839},starts={{npcID=150630}},ends={{npcID=150630}},coords={x=0.708,y=0.39,source="quest_giver",zoneID=10290},questType="standard"},
[56622] = {id=56622,name="Ashran Dominance",level=0,requiredLevel=0,faction="horde",expansion=8,zoneID=8485,mapID=588,description="The Alliance refuse to back down in Ashran . Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.",objectivesText="Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade .",questType="standard"},
[56623] = {id=56623,name="Ashran Dominance",level=0,requiredLevel=0,faction="alliance",expansion=8,zoneID=8485,mapID=588,description="As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.",objectivesText="Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath .",questType="standard"},
[56640] = {id=56640,name="Fortunate Souls",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="You and I survived the attack and have thus far evaded capture by the enemy. Not all were as fortunate. There are many of our allies now under the control of the naga. We must free them before they are killed or suffer an even worse fate.",objectivesText="Rescue 7 captive soldiers in Spears of Azshara. Progress: We are outnumbered, but we are not outclassed.",starts={{npcID=155482}},ends={{npcID=155482}},questType="standard"},
[56641] = {id=56641,name="Disruption of Power",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="The naga are tapping into some latent power, infusing the energy into some manner of device. I do not know what purpose they have for this power, but it is surely in our interest to destroy the objects before they can be used against us.",objectivesText="Destroy 5 Ley Line Accumulators in Spears of Azshara. Progress: Can you feel the magic in this place?",starts={{npcID=155482}},ends={{npcID=155482}},questType="standard"},
[56642] = {id=56642,name="Dark Tides",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="A tidemistress leads some nefarious ritual above a pool. Do not look in the pool when we approach it, or you will be rewarded with a view of our drowned allies. We must put a stop to this ritual. The tidemistress is key.",objectivesText="Slay Tidemistress Ethendriss . Progress: We must not underestimate this tidemistress.",rewardItems={163881,163882,163885,163886,163887,163890,163892,163894,166336,170274},starts={{npcID=155482}},ends={{npcID=155482}},questType="standard"},
[56643] = {id=56643,name="In Deep",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="By now, King Greymane and Lady Proudmoore should be in the cave at which we are to meet. Let's not keep them waiting.",rewardGold=30900,rewardXP=850,ends={{npcID=150101}},questType="standard"},
[56644] = {id=56644,name="Up Against It",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="We must move quickly if we are to find safety for our people. This cave is barely defensible, and much of our army is in an even more precarious position. Let's search deeper.",objectivesText="Move deeper into Nazjatar with Jaina and Genn.",rewardGold=234000,rewardXP=6815,starts={{npcID=150101}},ends={{npcID=151000}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[56645] = {id=56645,name="Heart of the Swarm",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=422,description="We need to know what we're up against. Before we return to the Serpent's Spine, we should take the opportunity to scout the swarm. I will fly us over the Heart of Fear. We should be able to survey Empress Shek'zara's forces from above. Then we can determine the extent to which N'Zoth has bolstered their ranks with his own.",objectivesText="Fly with Taoshi on the Shado-Pan Kite .",rewardGold=468000,rewardXP=8520,starts={{npcID=155707}},ends={{npcID=155487}},coords={x=0.564,y=0.294,source="quest_giver",zoneID=6138},questType="standard"},
[56647] = {id=56647,name="The Mantid Threat",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="The mantid have been corrupting their kypari trees to imbue their amber with power from N'Zoth. The swarm is enough of a menace on its own. N'Zoth could transform them into something even more dire. The Shado-Pan need to hear about this. I suggest you bring this information to your other allies as well.",objectivesText="Return to Stormspeaker Qian at the Silent Sanctuary.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=155487}},ends={{npcID=154444}},coords={x=0.118,y=0.938,source="quest_giver",zoneID=9105},questType="standard"},
[56648] = {id=56648,name="Call to Arms: Nazjatar",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1161,description="Our mission in Nazjatar is being compromised by the Horde incursion. Get into Nazjatar and take out as many as you can.",objectivesText="Slay Horde within Nazjatar .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=75}},starts={{npcID=143559},{npcID=154640}},ends={{npcID=143559},{npcID=154640}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[56649] = {id=56649,name="Call to Arms: Mechagon",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1161,description="Our mission in Mechagon is being compromised by the Horde incursion. Get into Mechagon and take out as many as you can.",objectivesText="Slay Horde within Mechagon .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=75}},starts={{npcID=143559}},ends={{npcID=143559},{npcID=154640}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[56650] = {id=56650,name="Call to Arms: Mechagon",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=862,description="Our objectives in Mechagon are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.",objectivesText="Slay Alliance within Mechagon .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=75}},starts={{npcID=143536}},ends={{npcID=143536},{npcID=154641}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[56714] = {id=56714,name="Contained Alemental",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=14,mapID=1,description="Brewmaster Tao knows more about such a strange occurrence.>",objectivesText="Talk to Brewmaster Tao in the Brewfest grounds.",rewardGold=99850,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=330168}},ends={{npcID=73914}},coords={x=0.41,y=0.177,source="quest_giver",zoneID=14},questType="standard"},
[56715] = {id=56715,name="Hozen Totem",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=14,mapID=1,description="<The hozen have been successfully chased away, and Brewfest saved once again. The question asks itself, though: How did hozen get to Durotar? Perhaps somebody in the Brewfest grounds has experience with them.>",objectivesText="Talk to Zenda in the Brewfest grounds.",rewardGold=306800,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=330170}},ends={{npcID=152780}},coords={x=0.41,y=0.177,source="quest_giver",zoneID=14},questType="standard"},
[56716] = {id=56716,name="Direbrew Cog",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=14,mapID=1,description="<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines. You know they have attacked Brewfest before. Perhaps one of the goblins would be interested in hearing of your victory.>",objectivesText="Talk to Blix Fixwidget in the Brewfest grounds.",rewardGold=292100,rewardXP=200,rewardItems={37829},rewardCurrencies={{id=2245,amount=5}},starts={{npcID=330169}},ends={{npcID=24495}},coords={x=0.41,y=0.178,source="quest_giver",zoneID=14},questType="standard"},
[56719] = {id=56719,name="This Ain't Mine",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=11403,mapID=1,description="Your arrival is timely, . Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. We are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long. Tinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.",objectivesText="Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Thank the Light you were able to open the pass.",rewardGold=234000,rewardXP=6815,starts={{npcID=155784}},ends={{npcID=155784}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[56739] = {id=56739,name="The Power of Worship",level=50,requiredLevel=50,faction="alliance",expansion=8,description="I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place. There are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free. Destroy the orbs. Breaking the connection will allow us to gain strength and move on.",objectivesText="Destroy 3 Arcane Energy Transmuters . Progress: Have you found them all?",starts={{npcID=152238}},ends={{npcID=152238}},questType="standard"},
[56740] = {id=56740,name="S.P.A.R.E. Crates",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I'm sure you agree that Pascal -K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!",objectivesText="Craft $1oa Junkyard Tinkering items with Pascal -K1N6.",rewardGold=257400,rewardXP=1415,starts={{npcID=152295}},ends={{npcID=152295}},questType="standard"},
[56741] = {id=56741,name="The Spear of Destiny",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone. We must hurry back to Mezzamere, Lady Proudmoore needs to know of our success. This will change the entire course of our campaign here in Nazjatar , .",objectivesText="Return to Jaina Proudmoore in Mezzamere.",rewardGold=23400,rewardXP=850,starts={{npcID=153617}},ends={{npcID=150101}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[56746] = {id=56746,name="Our Direct Line",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!",objectivesText="Craft $1oa Junkyard Tinkering items with Pascal-K1N6. Provided item:",rewardGold=257400,rewardXP=1415,rewardItems={169176},starts={{npcID=152575}},ends={{npcID=152575}},questType="standard"},
[56747] = {id=56747,name="Rustbolt Requisitions: Akunda's Bite",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=9391,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Gila Crosswire. Progress: I've received an urgent request from Tinkmaster Overspark. These supplies are needed!",rewardGold=257400,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=149813}},ends={{npcID=149813}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
[56748] = {id=56748,name="Brewfest Chowdown",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=14,mapID=1,description="Mok-rah, ! I hope you came with an empty stomach! Back on Draenor, we often held eating contests at our festivals as a form of celebration. When we were put in charge of Brewfest, we could think of nothing better to add to the event! Take a seat and show us what you can eat. If you want more details before jumping in, just ask!",objectivesText="Participate in the Brewfest Chowdown. Progress: Eat a sausage, drink some brew, then eat some more!",rewardGold=341600,rewardXP=200,rewardItems={37829,169599},rewardCurrencies={{id=3008,amount=10}},starts={{npcID=155133}},ends={{npcID=155133}},coords={x=0.422,y=0.184,source="quest_giver",zoneID=14},questType="standard"},
[56749] = {id=56749,name="Rustbolt Requisitions: Akunda's Bite",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=9391,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Skaggit . Progress: Gazlowe's orders are in: He wants these supplies ASAP. Ya got the goods?",rewardGold=257400,rewardXP=1415,rewardItems={152668},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=150563}},ends={{npcID=150563}},coords={x=0.738,y=0.258,source="quest_giver",zoneID=10290},questType="standard"},
