[56756] = {id=56756,name="My Punkin, the Action Figure",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Heya, . I'm workin' on a surprise for Saffy. Hopin' you can help me out. I overheard her beggin' Jepetto Joybuzz to make her into one of his fancy new action figures. That ol' jerk told her no. Can you believe it? My Punkin! Well, we don't need him. I reverse engineered a few of his toys and found out what makes them tick. I got a blueprint ready to go. We can make Saffy's action figure ourselves and surprise her with it!",objectivesText="Craft the Sapphronetta Flivvers Action Figure at Pascal-K1N6. Progress: You've got the spark of discovery in your eyes!",rewardGold=257400,rewardXP=1415,rewardItems={169876,169882},starts={{npcID=149815}},ends={{npcID=151010}},coords={x=0.716,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[56757] = {id=56757,name="Rustbolt Requisitions: Winter's Kiss",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=9391,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Gila Crosswire. Progress: I've received an urgent request from Tinkmaster Overspark. These supplies are needed!",rewardGold=250380,rewardXP=1415,rewardItems={152668,166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=149813}},ends={{npcID=149813}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
