[56763] = {id=56763,name="Rustbolt Requisitions: Great Sea Catfish",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10052,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Gila Crosswire. Progress: I've received an urgent request from Tinkmaster Overspark. These supplies are needed!",rewardGold=22600,rewardXP=1415,rewardItems={166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=149813}},ends={{npcID=149813}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
[56764] = {id=56764,name="Brewfest Chowdown",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=1,mapID=27,description="Welcome, ! I hope you came with an empty stomach! What's better, or more Brewfest, than sausage and brew? The Brewfest Chowdown is our new celebration of the things that make this festival great. Take a seat and show us what you can eat. If you want more details before jumping in, just ask!",objectivesText="Participate in the Brewfest Chowdown. Progress: Eat a sausage, drink some brew, then eat some more!",rewardGold=137400,rewardXP=200,rewardItems={37829,169599},rewardCurrencies={{id=3008,amount=10}},starts={{npcID=153574}},ends={{npcID=153574}},coords={x=0.548,y=0.384,source="quest_giver",zoneID=1},questType="standard"},
[56765] = {id=56765,name="Rustbolt Requisitions: Lane Snapper",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10290,mapID=1462,objectivesText="Bring 20 Storm Silver Ore to Skaggit . Progress: Gazlowe's orders are in: He wants these supplies ASAP. Ya got the goods?",rewardGold=257400,rewardXP=1415,rewardItems={166846},rewardCurrencies={{id=1560,amount=40},{id=1560,amount=45},{id=1560,amount=50},{id=1560,amount=55}},starts={{npcID=150563}},ends={{npcID=150563}},coords={x=0.738,y=0.258,source="quest_giver",zoneID=10290},questType="standard"},
[56771] = {id=56771,name="Time-Lost Warriors",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="According to the scouting report ye found, the Rajani are holed up in the Silent Sanctuary, overlooking Mistfall Village. They are described in the report as seclusive and dangerous, so we'd had best take caution when approaching them. I'll meet ye there.",objectivesText="Meet with the Rajani at the Silent Sanctuary. Progress: What is it, outsider?",rewardGold=117000,rewardXP=3410,starts={{npcID=154532}},ends={{npcID=154444}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[56775] = {id=56775,name="Warming Up",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1156,description="Prepare yourself, . We're nearing the island where the previous expedition was lost. Warm up on these combat dummies. We need everyone ready for whatever we find on that island.",objectivesText="Warm up by fighting a Combat Dummy . Progress: Don't be shy. Just walk up to the target dummies, select them, and use your main attack.",rewardGold=565,rewardXP=200,starts={{npcID=156280}},ends={{npcID=156280}},coords={x=0.562,y=0.59,source="quest_giver",zoneID=10424},questType="standard"},
[56777] = {id=56777,name="A Gift From The Clan",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Speaker Utia has requested that I direct you back to Mezzamere when you have a chance, . Our clan has prepared a gift for you to show our appreciation for the courage and valor you have shown in battle against the naga. I am sure that you will find the gift of supplies to be a valuable addition to your arsenal as you continue your campaign against Azshara.",objectivesText="Meet with Speaker Utia .",rewardItems={169903},starts={{npcID=149804},{npcID=150202}},ends={{npcID=154140}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=10052},questType="standard"},
[56778] = {id=56778,name="A Glint in the Darkness",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="There are many treasures hidden throughout Nazjatar . Recently, I spotted an object glinting from within a cave not far from here. It appeared to be some sort of lockbox. I suggest we head back and investigate. There may be valuable items inside that will help us in our battle against the naga.",objectivesText="Loot the Lambent Lockbox.",rewardItems={169905},starts={{npcID=150202}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56779] = {id=56779,name="A Valorous Reward",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Your deeds on the battlefield have brought honor upon your Alliance, . Speaker Utia has requested your presence in Mezzamere to accept a reward on behalf of our clan. You should return to Mezzamere at your soonest convenience. It is an honor to fight at your side.",objectivesText="Meet with Speaker Utia .",rewardItems={169904},starts={{npcID=150202}},ends={{npcID=154140}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56780] = {id=56780,name="Hidden, But Dangerous",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="The naga have hidden many useful treasures throughout Nazjatar . I have heard tell that there is a treasure hoard not far from here. It will be dangerous, but it may be worth investigating. There may be untold valuables inside the cache that could aid us in our fight against the naga.",objectivesText="Loot the Mystic Chest.",rewardItems={169911},rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=150202}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56781] = {id=56781,name="Treasure In The Deep",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="There are many treasures to be found throughout the naga stronghold of Nazjatar . Some time ago, I noticed a mysterious looking chest. The area was heavily fortified with naga troops, so whatever it contains must be valuable. We should go back and investigate the chest. Whatever is inside is better used in our hands than the hands of the enemy.",objectivesText="Loot the Mysterious Cache.",rewardItems={169917},starts={{npcID=150202}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56782] = {id=56782,name="The Speaker's Gift",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Speaker Utia has requested your presence in Mezzamere, . I believe that the Speaker has prepared a collection of items to aid you in your journey. You should return to Mezzamere at your soonest convenience and accept the Speaker's gift.",objectivesText="Meet with Speaker Utia .",rewardItems={169903},starts={{npcID=149805},{npcID=154304}},ends={{npcID=154140}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=10052},questType="standard"},
[56783] = {id=56783,name="The Lambent Lockbox",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="There are many treasures to find throughout these ancient ruins. Sometime ago, I noticed a strange looking chest in a cave not far from here. There may be valuable items inside that can help us in our fight against Queen Azshara. We should go back and investigate the chest.",objectivesText="Loot the Lambent Lockbox.",rewardItems={169905},starts={{npcID=154304}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[56784] = {id=56784,name="Helpful Provisions",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Speaker Utia is awaiting your return to Mezzamere. The Speaker has bundled together some helpful provisions to aid you in your journey. Please accept this gift with the thanks of our clan.",objectivesText="Meet with Speaker Utia .",rewardItems={169904},starts={{npcID=154304}},ends={{npcID=154140}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[56785] = {id=56785,name="The Mystic Chest",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="We have uncovered many rare treasures while exploring Nazjatar . I believe that I have found yet another cache of valuable artifacts to retrieve. Some time ago, I noticed a strangely glowing object in the distance. I believe that it may have been a treasure chest. We should go and investigate the object. If it is a treasure chest, its contents may prove valuable in our quest to defeat the naga!",objectivesText="Loot the Mystic Chest.",rewardItems={169911},rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=154304}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[56786] = {id=56786,name="Naga Treasure",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="The naga have stashed away the spoils of their wars throughout Nazjatar . Earlier while we were adventuring, I noticed a mysterious looking cache. The chest is located deep within naga territory, so I imagine that whatever is inside is most likely extremely valuable. We should retrieve the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.",objectivesText="Loot the Mysterious Cache.",rewardItems={169917},starts={{npcID=154304}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[56787] = {id=56787,name="Additional Supplies",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Speaker Utia has asked me to send you back to Mezzamere when you have a moment, . The Speaker has some additional supplies that might aid you in your fight against the naga. Please return to Mezzamere at your soonest convenience and accept the Speaker's gift with the thanks of our entire clan.",objectivesText="Meet with Speaker Utia .",rewardItems={169903},starts={{npcID=149803},{npcID=154297}},ends={{npcID=154140}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56788] = {id=56788,name="Reclaimed Treasure",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="The naga have filled Nazjatar with the ill-gotten spoils of war. We should reclaim whatever we come across in our effort to put an end to their tyranny once and for all. I noticed a strange looking chest in a cave nearby. It appeared to be of naga make. We should claim the contents of the cache. There may be valuable items inside that will help us in our battle against the naga.",objectivesText="Loot the Lambent Lockbox.",rewardItems={169905},starts={{npcID=154297}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56789] = {id=56789,name="A Gift of Supplies",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Speaker Utia has asked that I send you back to Mezzamere at your soonest convenience. The Speaker has gathered together a gift of supplies to further aid you in your fight against the naga. You should return to Mezzamere at your soonest convenience. Please accept this gift with the thanks of our clan.",objectivesText="Meet with Speaker Utia .",rewardItems={169904},starts={{npcID=154297}},ends={{npcID=154140}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56790] = {id=56790,name="Treasure To Find",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="The naga have stashed away treasures all over Nazjatar . Not long ago, I noticed an ornately crafted treasure chest hidden in plain view. The area is heavily fortified, but such minor inconveniences have not stopped us yet. We should head back there and liberate the contents of the cache.",objectivesText="Loot the Mystic Chest.",rewardItems={169911},rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=154297}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56791] = {id=56791,name="Mysterious Treasure",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,description="We have located many treasure hoards while exploring Nazjatar . I believe that I have found yet another cache for us to liberate. Some time ago, I noticed a mysterious looking chest. It is held in an extremely dangerous area, so whatever it contains must be valuable. We should embark on a mission to liberate the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.",objectivesText="Loot the Mysterious Cache.",rewardItems={169917},starts={{npcID=154297}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[56803] = {id=56803,name="Just A Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Look, mudfoot, I need to make sure a slight current isn't going to knock you over. I asked Atolia to see if she could pull together some things to make you a little less useless here. After what I saw in that last fight, we should probably head back sooner rather than later.",objectivesText="Visit Atolia Seapearl in Newhome.",rewardItems={169903},starts={{npcID=149906},{npcID=151309}},ends={{npcID=154002}},coords={x=0.494,y=0.652,source="quest_giver",zoneID=10052},questType="standard"},
[56804] = {id=56804,name="With Friends Like You, Who Needs Anemones?",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="I sometimes amuse myself with excursions into Zanj'ir Terrace, where the naga tough guys hang out. I grab things that could be useful and stash them somewhere I can pick them up later. I haven't been down there in a while. I could have something in there you may find useful.",objectivesText="See what is in Vim's Cache .",rewardItems={169910,169942},starts={{npcID=151309}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56805] = {id=56805,name="That's What Friends Are For",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Hmm. I am not admitting to anything, but there is a very small chance that I could have possibly, but not definitely, been mistaken about your whole... thing. On the off chance we were still tolerating each other, Atolia mentioned she had another delivery for you. We should swing through Newhome.",objectivesText="Visit Atolia Seapearl in Newhome.",rewardItems={169919},starts={{npcID=151309}},ends={{npcID=154002}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56806] = {id=56806,name="Friends Through Eternity",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="You may have noticed by now that me and the sea giants get along great. They mostly just want to be left alone. They want to laugh, and they want to tell you stories that make no sense. A simple life. We do share one interest, aside from killing naga, that is sampling interesting brews. Maedin recently brought in a lovely new keg, I hid it away. When it is ready to be opened, that round will be on me! Come, take a look!",objectivesText="Visit Vim's Round .",rewardItems={169916},starts={{npcID=151309}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56807] = {id=56807,name="Real Friends Help Hide Bodies",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="Bodies... treasures... I've seen it all, but it was a long time before I found someone worth calling friend. I am glad I added you to that list. So, back to those friends... I have one more place I would like you to see.",objectivesText="Find Gorm's Lantern .",rewardItems={169922},starts={{npcID=151309}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56808] = {id=56808,name="We're Going To Be Friends",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="It is going to be fun getting to know you. You're not half bad! We kinda got a little gift for you, to welcome you to the neighborhood. I hope Atolia was able to put together something neat, she didn't have much time.",objectivesText="Visit Atolia Seapearl , in Newhome, for your gift.",rewardItems={169903},starts={{npcID=149902},{npcID=151310}},ends={{npcID=154002}},coords={x=0.5,y=0.652,source="quest_giver",zoneID=10052},questType="standard"},
[56809] = {id=56809,name="Super Friends",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="You are a super trooper duper friend! There is a place I go to visit some of my smaller buddies. I keep some neat things I find in a bag there. Would you like to see it? What am I asking? Of course you would, let's go!",objectivesText="See what's in Poen's Bag .",rewardItems={169909,169942},starts={{npcID=151310}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56810] = {id=56810,name="A Friend Indeed",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="My friend, every day with you is a new adventure. I am sorry your ships crashed, but I am so happy we met! I heard a rumor, that Atolia found some more goods! We should swing by and see what she has this time!",objectivesText="Visit Atolia Seapearl , in Newhome, for your gift.",rewardItems={169919},starts={{npcID=151310}},ends={{npcID=154002}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56811] = {id=56811,name="You've Got A Friend In Me",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="There are a few spots I enjoy checking out with my friends. I actually found this amazing... well, I don't know what it is. Think you could check it out with me?",objectivesText="Examine Poen's Hidey Hole .",rewardItems={169915},starts={{npcID=151310}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56812] = {id=56812,name="Friendship Is Magic",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="Every day with you, I feel like I am a better kelfin than I was the day before. You have no idea how much that means to me. I felt like I wanted to do more, be more... help more. Now, I'm starting to be a real contributing member of the Unshackled. It's all thanks to you.",objectivesText="Seek out Poen's Wonder .",rewardItems={169921},starts={{npcID=151310}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56813] = {id=56813,name="An Unexpected Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Oh, , I nearly forgot! To help you with your mission here in Nazjatar , Atolia and I put together some items you may need. We should swing by and grab them when we have the time!",objectivesText="Visit Atolia Seapearl , in Newhome, for your gift.",rewardItems={169903},starts={{npcID=149904},{npcID=151300}},ends={{npcID=154002}},coords={x=0.496,y=0.646,source="quest_giver",zoneID=10052},questType="standard"},
[56814] = {id=56814,name="Anytime You Need A Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="You're not that bad for a... what was it? ? I like when I am reminded to look past appearances. Ha! But, really, speaking of hiding things in plain sight, I put some things in a naga crate. It is close to one of their camps in the Spears of Azshara, so they will never suspect it belongs to me! Let's go see if it is still there.",objectivesText="Find Neri's Ruse .",rewardItems={169908},starts={{npcID=151300}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56815] = {id=56815,name="With A Little Help From My Friends",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="It has been so long since we have been able to trust anyone not in our little pack of survivors. I forgot how good it feels. Thank you for reminding me. Atolia should have the rest of your gift together by now. We should go check in with her!",objectivesText="Visit Atolia Seapearl , in Newhome, for your gift.",rewardItems={169919},starts={{npcID=151300}},ends={{npcID=154002}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56816] = {id=56816,name="A Kelfin's Best Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="There is no better weapon in our fight than knowledge. Knowing you is proof of that! I found this thing, it lets me see better than my eyes could ever do before. With the water gone, I can see far, too! I have been using it sometimes to see what is happening in Nazjatar . Let me show you!",objectivesText="Examine Neri's Find .",rewardItems={169914},starts={{npcID=151300}},ends={{npcID=151300}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56817] = {id=56817,name="Thank You For Being A Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,description="Since the waterwall appeared, so much has changed here. There is a little spot I found, where you can feel the sea spray on your face. Sometimes I just ride over there and relax. I will show it to you, if you'd like.",objectivesText="Enjoy Neri's Spot .",rewardItems={169920},starts={{npcID=151300}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56829] = {id=56829,name="Bottom Feeders",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh this is bad. This is really bad. Every time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another. Let's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.",objectivesText="Find Cudgelface and the Lord Chamberlain .",rewardGold=252720,rewardXP=1415,starts={{npcID=155668}},ends={{npcID=155668}},coords={x=0.652,y=0.662,source="quest_giver",zoneID=10413},questType="standard"},
[56830] = {id=56830,name="Summons from the Deep",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10052,mapID=1355,rewardGold=702000,rewardXP=10225,rewardItems={170079,170081},coords={mapID=1355,x=0.485,y=0.404},questType="standard"},
[56833] = {id=56833,name="Leaders of the Horde",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11402,mapID=1534,description="Saurfang has shown his true colors and now enlists the aid of the Alliance. Meet with those who have remained loyal to the Horde. They are to ready themselves for the battle against our enemies. And as for Eitrigg ... bring him to Nathanos. A quick death is too lenient a punishment for his treachery. Go, . Let us end this.",objectivesText="Order the Horde leaders in Orgrimmar to prepare for battle. Progress: There is no honor in this battle, <name>.",rewardGold=117000,rewardXP=3410,starts={{npcID=156423}},ends={{npcID=156124}},coords={x=0.486,y=0.71,source="quest_giver",zoneID=11402},questType="standard"},
[56839] = {id=56839,name="Killclaw the Terrible",level=7,requiredLevel=7,faction="both",expansion=8,zoneID=10424,mapID=1409,description="BIG bear! Bad! Big bear guard big ogre treasure! Kill after ritual! Get treasure, make more power!",objectivesText="Defeat Killclaw the Terrible .",rewardGold=3045,rewardXP=1515,rewardItems={175195,175196,175197,175198,175227,175228,175229,175230},rewardChoices={175197,175229,175195,175227,175198,175230,175196,175228},starts={{npcID=330627}},ends={{npcID=155733}},coords={x=0.488,y=0.543,source="quest_giver",zoneID=10424},questType="group"},
[56842] = {id=56842,name="Lunar Preservation",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=493,mapID=80,description="My staff has served me well for many years. It has stood by my side, been through many trials... and as I grow older I find myself leaning on it more and more. Its flowers bloom every Lunar Festival, basking in the Elune's might. They bring me so much joy, I wish for them to stay all year long. I know a way... but my bones are too old to make the trip. Perhaps you would take the journey for me? Empower my staff in the light of the moon at the moonwells around the world. Then my flowers can stay.",objectivesText="Perform the Rite of the Moon at the moonwells scattered around the world. You can find them in Ashenvale, Felwood, Feralas, Moonglade, Stonetalon Mountains, Duskwood, and Mount Hyjal. If you let the Blessing of the Moon expire, you will have to start over. Progress: Flowers flourish under Elune's light. She was always known to cherish them.",rewardGold=341600,rewardXP=200,rewardItems={21100,170083,170084},starts={{npcID=155759}},ends={{npcID=155759}},coords={x=0.532,y=0.36,source="quest_giver",zoneID=493},questType="standard"},
[56877] = {id=56877,name="An Extra Sticky Situation",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardGold=772200,rewardXP=2125,questType="standard"},
[56903] = {id=56903,name="Crown of Courage",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=493,mapID=80,description="I see you are a fan of pink flowers. It is a shame those that make up your crown will one day come to perish. Perhaps I can help with that. Though those are ordinary blossoms, I know similar flowers that bloom only during Lunar Festival. If you retrieve them for me, I can imbue them with Elune's power so that you may enjoy them throughout the year.",objectivesText="Gather blooms from Eversong Woods, the Hinterlands, and Mulgore. Progress: Not all flowers are equal. Those that bloom during Lunar Festival have a special bond with Elune.",rewardGold=341600,rewardXP=200,rewardItems={170205},starts={{npcID=155759}},ends={{npcID=155759}},coords={x=0.532,y=0.36,source="quest_giver",zoneID=493},questType="standard"},
[56904] = {id=56904,name="Crown of Prosperity",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=493,mapID=80,description="Your crown is so colorful! Such beautiful pinks and yellows and blues... if only it could last. Although those particular flowers cannot, I know some that can! Similar flowers to those bloom every Lunar Festival. They hold a special connection to Elune that I can empower, thanks to you. Retrieve them for me, and we can fashion a crown that you can enjoy year round!",objectivesText="Gather blooms from Un'goro Crater, Stranglethorn Vale, and Northern Barrens. Progress: Elune has a soft spot for flowers. Those that bloom during Lunar Festival are quite special.",rewardGold=341600,rewardXP=200,rewardItems={170206},starts={{npcID=155759}},ends={{npcID=155759}},coords={x=0.532,y=0.36,source="quest_giver",zoneID=493},questType="standard"},
[56905] = {id=56905,name="Crown of Dark Blossoms",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=493,mapID=80,description="Such somber flowers... but they hold a beauty of their own, don't you think? If only they could last. Allow me to lend my aid. Every Lunar Festival, similar flowers to yours bloom around the world. They hold a special connection to Elune... one that I can empower. If you bring them to me, I can preserve them so you may enjoy them long after an ordinary flower would die.",objectivesText="Gather blooms from Duskwood, Silverpine Forest, and Desolace. Progress: The flowers that bloom during Lunar Festival have special properties. I believe it is Elune's light watching over them.",rewardGold=341600,rewardXP=200,rewardItems={170207},starts={{npcID=155759}},ends={{npcID=155759}},coords={x=0.532,y=0.36,source="quest_giver",zoneID=493},questType="standard"},
[56906] = {id=56906,name="Crown of Good Fortune",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=493,mapID=80,description="Those flowers remind me of Elune herself! I wear similar ones year round, to remind me of her watchful grace. Perhaps you would like to as well? Your crown is made of ordinary blossoms that will one day wilt and die. It is an unfortunate fate for such delicate beauties, but my crown is made of similar flowers that I made to last year round! If you bring me specific flowers that bloom only during Lunar Festival, I can bless them so that you too can enjoy your crown all year long.",objectivesText="Gather blooms from Winterspring, Dun Morogh, and Hillsbrad Foothills. Progress: Between you and me, I believe these flowers are Elune's favorite. They mirror her lunar radiance so splendidly!",rewardGold=341600,rewardXP=200,rewardItems={169208},starts={{npcID=155759}},ends={{npcID=155759}},coords={x=0.532,y=0.36,source="quest_giver",zoneID=493},questType="standard"},
[56907] = {id=56907,name="Paint Bottle: Nukular Red",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Kram Kelada could make use of this item.>",objectivesText="Deliver the item to Kram Kelada . Provided item:",rewardGold=309800,ends={{npcID=155874}},coords={mapID=1462,source="quest_giver",x=0.63,y=0.416},questType="standard"},
[56908] = {id=56908,name="Paint Bottle: Goblin Green",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Kram Kelada could make use of this item.>",objectivesText="Deliver the item to Kram Kelada . Provided item:",rewardGold=309800,ends={{npcID=155874}},coords={mapID=1462,source="quest_giver",x=0.63,y=0.416},questType="standard"},
[56909] = {id=56909,name="Paint Bottle: Electric Blue",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10290,mapID=1462,description="Kram Kelada could make use of this item.>",objectivesText="Deliver the item to Kram Kelada . Provided item:",rewardGold=257400,ends={{npcID=155874}},coords={mapID=1462,source="quest_giver",x=0.63,y=0.416},questType="standard"},
[56914] = {id=56914,name="Angry Residents",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10451,objectivesText="Defeat Grixis Tinypop in a pet battle.",rewardItems={169665},questType="standard",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=155414,text="Defeat Ezra Grimm"}},worldTaskTitle="Angry Residents",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[56942] = {id=56942,name="On The Road Again",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Right lads! All aboard!",objectivesText="Ride the Carriage.",rewardGold=63180,rewardXP=355,starts={{npcID=155668}},ends={{npcID=155533}},coords={x=0.652,y=0.662,source="quest_giver",zoneID=10413},questType="standard"},
[56955] = {id=56955,name="Rebels on the Road",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. We need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. Carve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.",objectivesText="Slay 5 Stoneborn Rebels .",rewardGold=252720,rewardXP=1415,rewardItems={175438,175439,175440,175441},rewardChoices={175439,175441,175440,175438},starts={{npcID=155533}},ends={{npcID=155533}},coords={x=0.674,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[56969] = {id=56969,name="Ancient Reefwalker Bark",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,starts={{npcID=153510}},ends={{npcID=153510},{npcID=153514}},coords={x=0.378,y=0.556,source="quest_giver",zoneID=10052},questType="standard"},
[56970] = {id=56970,name="Reefwalker Bark",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,starts={{npcID=153510}},ends={{npcID=153510},{npcID=153514}},coords={x=0.378,y=0.556,source="quest_giver",zoneID=10052},questType="standard"},
[56971] = {id=56971,name="Eel Filet",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1746,amount=50}},starts={{npcID=151309}},ends={{npcID=149906},{npcID=151309}},coords={x=0.494,y=0.653,source="quest_giver",zoneID=10052},questType="standard"},
[56972] = {id=56972,name="Fathom Ray Wing",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1745,amount=50}},starts={{npcID=151300}},ends={{npcID=149904},{npcID=151300}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56973] = {id=56973,name="Giant Crab Leg",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1747,amount=50}},starts={{npcID=151310}},ends={{npcID=149902},{npcID=151310}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[56978] = {id=56978,name="To Darkhaven",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it. However, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.",objectivesText="Escort Lord Chamberlain to Darkhaven.",rewardGold=252720,rewardXP=1415,starts={{npcID=155533}},ends={{npcID=156374}},coords={x=0.674,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[56979] = {id=56979,name="Saving the Siege",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=11403,mapID=1,description="In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. Several of them have already been lost. We cannot afford to lose more.",objectivesText="Remove 8 Suspicious Crates.",rewardGold=234000,rewardXP=6815,starts={{npcID=155784}},ends={{npcID=155784}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[56980] = {id=56980,name="Already Among Us",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=11403,mapID=1,description="While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows. Stop any loyalists you encounter, before they can cause any harm.",objectivesText="Slay 10 Suspicious Technicians or Loyalist Assassins .",rewardGold=234000,rewardXP=6815,starts={{npcID=155784}},ends={{npcID=155784}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[56981] = {id=56981,name="Strategic Deployment",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1638,mapID=1,description="Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter. We must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here. Deliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.",objectivesText="Deliver Anduin's deployment orders.",rewardGold=234000,rewardXP=6815,starts={{npcID=155784}},ends={{npcID=155784}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[56982] = {id=56982,name="Before the Gates of Orgrimmar",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1,description="We have prepared for this battle as best we can, $p. I pray that we all survive what is to come.",objectivesText="Begin the battle at the gates of Orgrimmar.",rewardGold=234000,rewardXP=6815,starts={{npcID=155784}},ends={{npcID=155785}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[56993] = {id=56993,name="The Price of Victory",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=11403,mapID=1,description="Saurfang... how could this have happened.... The Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally. Anduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.",objectivesText="Recall the Alliance forces and inform them of what has transpired. Progress: He died a warrior's death, as he always wanted. I suppose there is some comfort in that.",rewardGold=234000,rewardXP=6815,starts={{npcID=155785}},ends={{npcID=155785}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57002] = {id=57002,name="Old Soldier",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1637,mapID=1,description="No matter what doubts he harbored, Saurfang was an honorable soldier. He prevented both a civil war within the Horde and the potential destruction of the Alliance. He brought an end to Sylvanas's reign and saved many lives at the cost of his own. We shall honor his sacrifice.",objectivesText="Speak with Jaina in front of the gates of Orgrimmar. Progress: Thank you for coming.",rewardGold=702000,rewardXP=10225,starts={{npcID=155785}},ends={{npcID=155785}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57003] = {id=57003,name="Create Your Own Strength",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="For something that has been sitting on the ocean floor, there is still power to be found in this item. Take your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity. Go ahead and humor the ethereal and let him have a look. Maybe he has something to offer.",objectivesText="Upgrade a piece of Benthic armor through Voidbinder Zorlan.",rewardGold=117000,rewardXP=3410,starts={{npcID=151848}},ends={{npcID=154002}},coords={x=0.484,y=0.622,source="quest_giver",zoneID=10052},questType="standard"},
[57004] = {id=57004,name="Create Your Own Strength",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="That Benthic armor you carry has been lost beneath the tides for too long. There is still power within it. Voidbinder Sturzah may be able to provide insight. Take your find to our intrepid ethereal friend, and see what he can do with it.",objectivesText="Upgrade a piece of Benthic armor through Voidbinder Sturzah. Progress: Were you successful?",rewardGold=117000,rewardXP=3410,starts={{npcID=150101}},ends={{npcID=153509}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[57005] = {id=57005,name="Becoming a Friend",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=1355,description="Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend. You will find they each have their own special interests and they will mark your map with different opportunities every day. Use the conch when you're ready, choose who you would like to join you, and explore Nazjatar ! Choose wisely! You may only select one friend per day.",objectivesText="Use the Calling Conch , choose an ally, and complete 3 ally quests.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{currencyID=1721,quantity=1}},starts={{npcID=154002}},ends={{npcID=154002}},coords={x=0.508,y=0.652,source="quest_giver",zoneID=10052},questType="standard"},
[57006] = {id=57006,name="A Worthy Ally",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,description="Some of our bravest ankoan have volunteered to join you on your expedition. You will find each have their own special interests and they will mark your map with different opportunities every day. Use the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar . Choose wisely! You may only select one friend per day.",objectivesText="Use the Deepflame Campfire , choose an ally, and complete 3 ally quests.",rewardGold=468000,rewardXP=8520,rewardCurrencies={{id=1721,amount=12}},starts={{npcID=153509}},ends={{npcID=153509}},coords={x=0.378,y=0.556,source="quest_giver",zoneID=10052},questType="standard"},
[57007] = {id=57007,name="Invitation of the Master",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The great Sire Denathrius, Master of Revendreth , and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. You should feel honored. Come, join me in the carriage and we shall ride to the castle in style.",objectivesText="Ride the Darkhaven Carriage .",rewardGold=63180,rewardXP=355,starts={{npcID=155533}},ends={{npcID=155668}},coords={x=0.674,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[57009] = {id=57009,name="Fame Waits for Gnome One",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="Tinkmaster Overspark requests your assistance on an important research expedition. Working with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!",objectivesText="Meet with Tinkmaster Overspark in Boralus.",rewardGold=5350,rewardXP=175,starts={{npcID=156179}},ends={{npcID=150208}},questType="standard"},
[57010] = {id=57010,name="Harnessing the Power",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="Heart Forge online. Initiate final attunement sequence. Awaiting input from champion unit .",objectivesText="Use the Petrified Ebony Scale atop the Heart Forge to infuse its power into the Heart of Azeroth. Progress: Standing by.",rewardGold=23400,rewardXP=850,rewardItems={168611},starts={{npcID=152194}},ends={{npcID=152206}},coords={x=0.482,y=0.71,source="quest_giver",zoneID=9667},questType="standard"},
[57022] = {id=57022,name="Assault: Amathet Advance",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=5034,mapID=249,questType="standard"},
[57024] = {id=57024,name="Rumors of Mechagon",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=8670,mapID=1355,description="I knew I should've taken that gig with the Greasemonkeys... Gazlowe 's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...",objectivesText="Meet Gazlowe outside the Great Seal in Dazar'alor.",rewardGold=309800,rewardXP=1415,starts={{npcID=156187}},ends={{npcID=152522}},coords={x=0.47,y=0.654,source="quest_giver",zoneID=9598},questType="standard"},
[57025] = {id=57025,name="A Plea to Revendreth",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. Know that while souls sometimes return from Revendreth , they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent. Their path, however, is not an easy one. Kah-Sher will assist you in opening the gateway to Revendreth . Meet him in the Ring of Transference.",objectivesText="Journey to Revendreth .",rewardGold=25270,rewardXP=175,starts={{npcID=159478}},ends={{npcID=155537}},questType="standard"},
[57026] = {id=57026,name="The Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes. Let's get you sorted out with your sinstone . This way, if you please.",objectivesText="Take the tour.",rewardGold=126360,rewardXP=710,starts={{npcID=155537}},ends={{npcID=155533}},coords={x=0.7,y=0.826,source="quest_giver",zoneID=10413},questType="standard"},
[57037] = {id=57037,name="A Once Sweet Sound",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The bells! That sound! Their song has been twisted! If their dire toll continues, we will all succumb. Eridia presses her hammer into your hands.> Find the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices! I will listen for their clarion call and meet you near the bridge. Go swiftly!",objectivesText="Cleanse the Vesper of Purity and the Vesper of Harmony . Progress: Such a bitter sound!",rewardGold=236340,rewardXP=1415,rewardItems={176333,176335},rewardChoices={176335,176333},starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[57043] = {id=57043,name="Old Friends, New Opportunities",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=5287,mapID=85,description="Greetings, . I have a... strange message for you from a group of goblins. Someone named Sassy Hardwrench is asking for your help for what was described as a, \"big job\". The word \"big\" was mentioned several times, followed by murmuring about time and money. Sassy is waiting for you over in Stranglethorn Vale.",objectivesText="Speak with Sassy Hardwrench in Stranglethorn Vale.",rewardGold=30900,rewardXP=850,starts={{npcID=156358}},ends={{npcID=156396}},coords={x=0.396,y=0.802,source="quest_giver",zoneID=1637},questType="standard"},
[57045] = {id=57045,name="A Special Delivery",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=210,description="I'm glad you're finally here, . I've got an important delivery to make and you're the goblin I trust most. Yeah, yeah. I know that's not sayin' much, but it's hard to find good help these days! This package is for Hobart Grapplehammer . He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately! Deliver the package and for the love of money... DON'T DROP IT! You have no idea how long it took me to locate this thing!",objectivesText="Deliver the package to Hobart Grapplehammer . Progress: Gallywix sure has some nerve threatening me in my own laboratory! He thinks he can just do whatever he wants to whoever he wants...",rewardGold=34100,rewardXP=850,rewardItems={170538},starts={{npcID=156396}},ends={{npcID=156520}},coords={x=0.346,y=0.286,source="quest_giver",zoneID=5287},questType="standard"},
[57047] = {id=57047,name="A Simple Experiment",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="Now that you've delivered the necessary parts, I can begin testing my latest prototype! I call it the X-52 Personnel Armor! It will be nearly indestructible! Gallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me! I could really use an extra set of hands with the experiments. Can I count on you, ?",objectivesText="Assist Hobart Grapplehammer . Progress: We need to complete the X-52 Personnel Armor before Gallywix finds a way to steal the prototype!",rewardGold=309800,rewardXP=6815,starts={{npcID=156520}},ends={{npcID=156520}},coords={x=0.52,y=0.594,source="quest_giver",zoneID=11455},questType="standard"},
[57048] = {id=57048,name="Shopping For Parts",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="I'm going to need some additional components in order to complete the next phase of testing. Right now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later... Crank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts. I don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!",objectivesText="Speak with Crank Greasefuse .",rewardGold=34100,rewardXP=850,starts={{npcID=156520}},ends={{npcID=156542}},coords={x=0.52,y=0.594,source="quest_giver",zoneID=11455},questType="standard"},
[57049] = {id=57049,name="Vault of Souls",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=9105,mapID=1530,questType="world",worldTaskTitle="Vault of Souls",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57051] = {id=57051,name="Debt Collection!",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="You need thermoplugs? Well, you came to the right place, kid. But I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time. Crank Greasefuse thinks for a moment.> Look, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment. You won't find a better deal than that!",objectivesText="Collect 8 Unpaid Debts . Progress: You got my money?",rewardGold=309800,rewardXP=6815,rewardItems={171089},starts={{npcID=156542}},ends={{npcID=156542}},coords={x=0.558,y=0.782,source="quest_giver",zoneID=11455},questType="standard"},
[57052] = {id=57052,name="I've Got What You Need",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="A deal's a deal, . Here's the thermoplugs you ordered! Be sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up. Anyway, it was a pleasure doing business with you... Now get lost!",objectivesText="Deliver the package to Hobart Grapplehammer .",rewardGold=30900,rewardXP=850,starts={{npcID=156542}},ends={{npcID=156520}},coords={x=0.558,y=0.782,source="quest_giver",zoneID=11455},questType="standard"},
[57053] = {id=57053,name="Blunt Force Testing",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="Now that we have the thermoplugs we're ready for our next test of the prototype X-52 Personnel Armor ! Unfortunately, my lab assistants have either quit or expired. What a pity! But their loss is your gain, ... now YOU get to wear the X-52 Personnel Armor ! How exciting! The next test will be conducted by my new mechanized lab assistant . Head over to the main workshop and press the big red button to begin. Don't worry, I'll be giving you directions over the X-52's built in intercom!",rewardGold=309800,rewardXP=6815,rewardItems={171114},starts={{npcID=156520}},ends={{npcID=156520}},coords={x=0.52,y=0.594,source="quest_giver",mapID=1532},questType="standard"},
[57058] = {id=57058,name="Fun With Landmines",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="The prototype X-52 Personnel Armor is ready for the final test! How are you with loud noises and sudden bursts of concussive energy, ? For the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield! I have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!",objectivesText="Retrieve the refreshing coconut beverage from the minefield. Progress: Ballistic testing... IS MY FAVORITE!",rewardGold=341600,rewardXP=6815,rewardItems={174059},starts={{npcID=156520}},ends={{npcID=156520}},coords={x=0.52,y=0.594,source="quest_giver",zoneID=11455},questType="standard"},
[57059] = {id=57059,name="Let's Rumble!",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="This is bad, ! Real bad! Gallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor! You've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!",objectivesText="Defeat 8 Hired Scoundrels . Progress: Hurry, <name>! Gallywix and his goons are destroying my worskshop!",rewardGold=309800,rewardXP=6815,starts={{npcID=156520}},ends={{npcID=156520}},coords={x=0.52,y=0.594,source="quest_giver",zoneID=11455},questType="standard"},
[57067] = {id=57067,name="Mogu at the Gates",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=1530,description="The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms . They will not conquer it. Some of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.",objectivesText="Meet Chen and Li Li Stormstout at the Gate of the August Celestials.",rewardGold=23400,rewardXP=850,starts={{npcID=154444}},ends={{npcID=156297}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="standard"},
[57068] = {id=57068,name="Kite Surveillance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="We heard for ourselves that there were mogu attacking, but I had no idea it would be this many! There must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers. We just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.",objectivesText="Ride Chen's Kite to scout the Mogu armies.",rewardGold=234000,rewardXP=6815,starts={{npcID=156297}},ends={{npcID=156391}},coords={x=0.554,y=0.91,source="quest_giver",zoneID=5841},questType="standard"},
[57069] = {id=57069,name="Cut Off the Heads",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet. It's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate! See if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.",objectivesText="Slay mogu commanders.",rewardGold=234000,rewardXP=6815,starts={{npcID=156391}},ends={{npcID=156391}},coords={x=0.6,y=0.756,source="quest_giver",zoneID=5841},questType="standard"},
[57070] = {id=57070,name="Mogu Massacre",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\" You know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!",objectivesText="Slay mogu in Kun-Lai Summit .",rewardGold=234000,rewardXP=6815,starts={{npcID=156391}},ends={{npcID=156391}},coords={x=0.6,y=0.756,source="quest_giver",zoneID=5841},questType="standard"},
[57071] = {id=57071,name="No Brew Left Behind",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="My head is... hurting. There can be only one solution. We flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength. Plus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.",objectivesText="Locate the abandoned brew barrels in Kun-Lai Summit .",rewardGold=23400,rewardXP=850,starts={{npcID=156390}},ends={{npcID=157180}},coords={x=0.6,y=0.756,source="quest_giver",zoneID=5841},questType="standard"},
[57072] = {id=57072,name="Yak of All Trades",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="<The brew barrels are too heavy and numerous to carry alone. Perhaps you can find something, or someone, to help you.>",objectivesText="Find something to help you carry the brew back to Chen in Mogujia.",rewardGold=234000,rewardXP=6815,starts={{npcID=157180}},ends={{npcID=156390}},coords={x=0.584,y=0.84,source="quest_giver",zoneID=5841},questType="standard"},
[57074] = {id=57074,name="Our Backs to the Gate",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="It is most fortuitous that you found this brew, and a yak to carry it on! But we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing. Let me know when you are ready to leave.",objectivesText="Ride Mobi with Chen and Li Li to the Gate of August Celestials.",rewardGold=23400,rewardXP=850,starts={{npcID=156390}},ends={{npcID=156938}},coords={x=0.6,y=0.756,source="quest_giver",zoneID=5841},questType="standard"},
[57075] = {id=57075,name="Liquid Courage",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5841,mapID=379,description="We have to do something about all these mogu. At least to thin their ranks before they invade the Vale! As much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!",objectivesText="Mount Mobi and defeat the mogu armies with the power of brew. Progress: Something must be done about all these mogu, or we will lose the Vale.",rewardGold=702000,rewardXP=10225,starts={{npcID=156938}},ends={{npcID=156937}},coords={x=0.554,y=0.912,source="quest_giver",zoneID=5841},questType="standard"},
[57076] = {id=57076,name="Return to Mistfall",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=379,description="We have done all we can here. We know how much the mogu are a clear threat. The forge is in great danger of falling into their hands if we lose our hold on the Vale. Let us return to Mistfall and report to the Rajani. They will want to know what we are up against.",objectivesText="Return to Stormspeaker Qian in the Silent Sanctuary in the Vale of Eternal Blossoms.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=156937}},ends={{npcID=154444}},coords={x=0.554,y=0.91,source="quest_giver",zoneID=5841},questType="standard"},
[57077] = {id=57077,name="Buyers Wanted!",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=5287,mapID=210,description="The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs! I've got you to thank for this, ! But we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder! Sassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!",objectivesText="Speak with Sassy Hardwrench in Stranglethorn Vale.",rewardGold=30900,rewardXP=850,starts={{npcID=156520}},ends={{npcID=156396}},coords={x=0.52,y=0.594,source="quest_giver",zoneID=11455},questType="standard"},
[57078] = {id=57078,name="The VIP List",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=5287,mapID=210,description="While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers! This is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it? I've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course! Head out and deliver these invitations while I finish up preparations for the auction!",objectivesText="Deliver the invitations to Grapplehammer's private auction. Progress: This will be an 'A' list event. Only Kezan's finest will be in attendance!",rewardGold=309800,rewardXP=6815,starts={{npcID=156396}},ends={{npcID=156396}},coords={x=0.346,y=0.286,source="quest_giver",zoneID=5287},questType="standard"},
[57079] = {id=57079,name="Beat The Crapopolis Outta Him!",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=5287,mapID=210,description="Boy am I glad to see you! We've got a bad situation on our hands... While you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor! You have to stop Gallywix before it's too late!",objectivesText="Complete the Crapopolis scenario.",rewardGold=683200,rewardXP=8520,starts={{npcID=156396}},ends={{npcID=156396}},coords={x=0.346,y=0.286,source="quest_giver",zoneID=5287},questType="standard"},
[57080] = {id=57080,name="A Fitting Reward",level=50,requiredLevel=50,faction="horde",expansion=8,mapID=1531,description="Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success! I doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all! Now that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his. He is a \"captive audience\" after all!",rewardItems={173974,173975,173977,173978,173979,173980,173981,173982,174077},starts={{npcID=157491}},ends={{npcID=157491}},questType="standard"},
[57086] = {id=57086,name="Legacy of the Mad Mage",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10052,description="<This rather large jewel has an inscription etched on its base: Property of Mardivas. If found please return to my laboratory. Perhaps this laboratory can still be found somewhere?>",objectivesText="Investigate Mardivas's Laboratory. Progress: <The chest appears to be simply constructed, but the locking mechanism hums with arcane energy.>",rewardGold=468000,rewardXP=8520,rewardItems={170547},rewardCurrencies={{currencyID=1721,quantity=1}},ends={{npcID=334100}},coords={mapID=1355,x=0.794,y=0.272},questType="standard"},
[57088] = {id=57088,name="This Ain't Mine",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11403,mapID=1,description="Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other. We need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts. Gazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.",objectivesText="Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Hmm. Maybe that goblin's gadgets have some use.",rewardGold=234000,rewardXP=6815,starts={{npcID=155786}},ends={{npcID=155786}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57090] = {id=57090,name="Saving the Siege",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11403,mapID=1,description="The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry. Get rid of those bombs.",objectivesText="Remove 8 Suspicious Crates.",rewardGold=234000,rewardXP=6815,starts={{npcID=155786}},ends={{npcID=155786}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57091] = {id=57091,name="Already Among Us",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11403,mapID=1,description="Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support. They do not yet see she will lead us to ruin, that her so-called victories are all hollow. Some of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.",objectivesText="Slay 10 Suspicious Technicians or Loyalist Assassins .",rewardGold=234000,rewardXP=6815,starts={{npcID=155786}},ends={{npcID=155786}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57092] = {id=57092,name="Strategic Deployment",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1638,mapID=1,description="For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory. Wrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack. Bring the orders to our commanders.",objectivesText="Deliver Saurfang's deployment orders.",rewardGold=234000,rewardXP=6815,starts={{npcID=155786}},ends={{npcID=155786}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57093] = {id=57093,name="Before the Gates of Orgrimmar",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=1,description="It is time. We have done all that we can to prepare. All that remains is the battle itself. I am not one for speeches. So I will say only this. Lok-tar ogar, . Victory. Or death.",objectivesText="Begin the battle at the gates of Orgrimmar.",rewardGold=234000,rewardXP=6815,starts={{npcID=155786}},ends={{npcID=155789}},coords={x=0.54,y=0.424,source="quest_giver",zoneID=14},questType="standard"},
[57094] = {id=57094,name="The Price of Victory",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1638,mapID=1165,description="Saurfang... I... ...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us. Recall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us. Speak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. Let us stand as a united Horde once more.",objectivesText="Inform Baine Bloodhoof of what has transpired. Progress: He earned the warrior's death he always sought. There is honor in that.",rewardGold=234000,rewardXP=6815,starts={{npcID=155789}},ends={{npcID=155789}},coords={x=0.5,y=0.96,source="quest_giver",zoneID=8670},questType="standard"},
[57095] = {id=57095,name="Old Soldier",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=1165,description="No matter what anyone says, he was an honorable orc. A legend in his own right, the ideal to which all warriors of the Horde aspired. He gave his life to heal the rift in the Horde and give us the chance to forge a new path forward. His was more than a death befitting a warrior. It was the death of a hero. We shall honor his sacrifice.",objectivesText="Honor High Overlord Saurfang.",rewardGold=702000,rewardXP=10225,starts={{npcID=155789}},ends={{npcID=155787}},coords={x=0.5,y=0.96,source="quest_giver",zoneID=8670},questType="standard"},
[57098] = {id=57098,name="The Grove of Terror",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. To celebrate, I must insist that you take part in a sacred tradition of Revendreth : The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls. Fear can be a very powerful motivator for change. Meet the Fearstalker in the Grove of Terror below. There you will prepare.",objectivesText="Meet the Fearstalker in the Grove of Terror.",rewardGold=23870,rewardXP=175,starts={{npcID=156381}},ends={{npcID=169087}},coords={x=0.534,y=0.64,source="quest_giver",zoneID=10413},questType="standard"},
[57099] = {id=57099,name="A Dreadful Roundup",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Welcome to The Banewood, Maw Walker. As Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt. In the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.",objectivesText="Collect 6 Condemned Souls .",rewardGold=257400,rewardXP=1415,questType="standard"},
[57100] = {id=57100,name="Feeding Time is Over",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast. Their fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. Go and collect some from their corpses. Their population is a bit large right now anyhow.",objectivesText="Kill Winged Terrorbeasts and collect 6 of their fangs.",rewardGold=257400,rewardXP=1415,questType="standard"},
[57102] = {id=57102,name="Pardon Our Dust",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ah yes, the Greeter. It seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all. There are some centurions nearby. A portion of their Anima could serve our needs. Ah! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort. Return when you have sufficient Anima and we will power the Greeter once more.",objectivesText="Collect anima from nearby centurions. Progress: <The centurion is unresponsive.>",rewardGold=118170,rewardXP=710,starts={{npcID=165107}},ends={{npcID=158281}},coords={x=0.482,y=0.726,source="quest_giver",zoneID=10534},questType="standard"},
[57113] = {id=57113,name="On Lysonia's Trail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility. As the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her. The disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.",objectivesText="Meet Kleia outside the Temple of Humility.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=156361}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[57114] = {id=57114,name="Aerial Reconnaissance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="The temple grounds are crawling with those loyal to the Forsworn. If I were still an aspirant, this task would be monumental. Luckily, that is no longer the case. Let us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.",objectivesText="Fly with Kleia to find the survivors.",rewardGold=25740,rewardXP=1020,starts={{npcID=156361}},ends={{npcID=156327}},coords={x=0.618,y=0.436,source="quest_giver",zoneID=10534},questType="standard"},
[57115] = {id=57115,name="Sacred Scrolls of Humility",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Forsworn are ransacking the library, looking for specific texts amongst our archives. We cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.",objectivesText="Collect 5 Sacred Scrolls . Progress: The scrolls throughout these temples cover many topics, from information on different worlds, to training pillars, to ancient rituals.",rewardGold=257400,rewardXP=8165,rewardItems={170550},starts={{npcID=156327}},ends={{npcID=156327}},coords={x=0.66,y=0.47,source="quest_giver",zoneID=10534},questType="standard"},
[57116] = {id=57116,name="Succumbing to Pride",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="The aspirants that spend the most time at this temple are those who must face their pride. I was one of them, once. During our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing. You must stop the Forsworn. Free the aspirants from a terrible fate.",objectivesText="Free 5 Burdened Aspirants by stopping Forsworn rituals.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=156361}},ends={{npcID=156361}},coords={x=0.618,y=0.436,source="quest_giver",zoneID=10534},questType="standard"},
[57117] = {id=57117,name="Fallen to Their Vices",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace. It pains me to say, but you must defeat them so they can no longer abuse our people. Take Compassion with you. You will find it more than helpful, now that its power has returned.",objectivesText="Defeat 15 Forsworn forces in the Terrace of Inner Grace.",rewardGold=257400,rewardXP=8165,rewardItems={181291},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=156327}},ends={{npcID=156361}},coords={x=0.66,y=0.47,source="quest_giver",zoneID=10534},questType="standard"},
[57118] = {id=57118,name="Distorted by the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own. The collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.",objectivesText="Destroy 3 Anima Collectors in the Terrace of Inner Grace.",rewardGold=257400,rewardXP=8165,starts={{npcID=156327}},ends={{npcID=156361}},coords={x=0.66,y=0.47,source="quest_giver",zoneID=10534},questType="standard"},
[57120] = {id=57120,name="Compassion, Blade of Humility",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia. It seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>",objectivesText="Charge Compassion, Blade of Humility by killing manifestations. Progress: The Paragon rarely uses his weapon. He prefers debate and reason over the use of force.",rewardGold=257400,rewardXP=8165,starts={{npcID=353472}},ends={{npcID=156327}},coords={x=0.648,y=0.457,source="quest_giver",zoneID=10534},questType="standard"},
[57121] = {id=57121,name="The Power of the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her. Take Kleia and my blade. She must be stopped.",objectivesText="Enter the Maw with Kleia , then meet her outside Perdition Hold.",rewardGold=128700,rewardXP=4085,starts={{npcID=156474}},ends={{npcID=156361}},coords={x=0.69,y=0.406,source="quest_giver",zoneID=10534},questType="standard"},
[57122] = {id=57122,name="A Step Too Far",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="My initial scouting revealed things I did not believe at first. The Mawsworn hold Forsworn captive here, transforming them against their will. Though the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.",objectivesText="Free 5 Captive Forsworn. Progress: I cannot stand idly by while my brothers and sisters are tormented.",starts={{npcID=170375}},ends={{npcID=170375}},questType="standard"},
[57123] = {id=57123,name="Kyrian No More",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Mawsworn kyrian... I have not seen one since that vision when we first met. I am not intimidated. They are enemies of Bastion , of the Archon, and it is our duty to defeat them.",objectivesText="Kill 15 Mawsworn forces.",starts={{npcID=170375}},ends={{npcID=170375}},questType="standard"},
[57124] = {id=57124,name="Her Will, Inflicted",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I feel myself drawn across the double bridges to the west... Lysonia must be there. Come, . We must confront her before she can escape again. Who knows what she plans.",objectivesText="Confront Lysonia in the Altar of Domination.",rewardGold=514800,rewardXP=10205,rewardItems={174290,177051,178154,179940},rewardChoices={178154,177051,179940,174290},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=170375}},ends={{npcID=169850}},questType="standard"},
[57125] = {id=57125,name="Time to Reflect",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1543,description="I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty. I have much to reflect on. We may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.",objectivesText="Speak to Kleia to exit the Maw, then return to Polemarch Adrestes in Elysian Hold.",rewardGold=25740,rewardXP=175,starts={{npcID=169850}},ends={{npcID=160037}},coords={x=0.256,y=0.652,source="quest_giver",zoneID=11400},questType="standard"},
[57126] = {id=57126,name="...And Following Seas",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=1161,description="My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family. He's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised-- Calia Menethil . She has guided him back from the brink of despair. I am on my way to pay them a visit. Care to join me?",objectivesText="Visit Derek Proudmoore and Calia Menethil .",rewardGold=23400,rewardXP=850,starts={{npcID=150633}},ends={{npcID=156513}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[57130] = {id=57130,name="Traitors In Our Midst",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=3433,mapID=95,description="There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!",objectivesText="Deal with this traitor.",rewardGold=234000,rewardXP=6815,starts={{npcID=156124}},ends={{npcID=156440}},coords={x=0.74,y=0.46,source="quest_giver",zoneID=11402},questType="standard"},
[57131] = {id=57131,name="Let the Hunt Begin",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="One step remains until we may begin the Penitent Hunt. You and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release. This anima helps us venthyr in tracking the prey's fear. I also ask that you do us the honor of signaling the hunt. The Fearstalker hands you an anima stake and a hollowed dredbat fang .> Use these to complete the task.",objectivesText="Complete the hunting ritual at Wanecrypt Hill. Progress: The ceremony must continue.",rewardGold=127530,rewardXP=710,rewardItems={178994},starts={{npcID=168664}},ends={{npcID=168664}},coords={x=0.478,y=0.7,source="quest_giver",zoneID=10413},questType="standard"},
[57136] = {id=57136,name="The Penitent Hunt",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter. The Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first. I will be able to guide you through your first hunt.",objectivesText="Speak to the Fearstalker in Wanecrypt Hill and participate in the Penitent Hunt. Progress: The souls must be hunted.",rewardGold=257400,rewardXP=1415,rewardItems={175715},rewardChoices={175715},starts={{npcID=168664}},ends={{npcID=168664}},coords={x=0.478,y=0.7,source="quest_giver",zoneID=10413},questType="standard"},
[57147] = {id=57147,name="Not My Warchief",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11403,mapID=1,description="There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision. We must make our way to the wyverns and take to the skies.",objectivesText="Escape with Eitrigg and meet up with Saurfang in Razor Hill.",rewardGold=48350,rewardXP=6815,starts={{npcID=156124}},ends={{npcID=155786}},coords={x=0.74,y=0.46,source="quest_giver",zoneID=11402},questType="standard"},
[57148] = {id=57148,name="Siegebreakers",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11401,mapID=95,description="The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates. Our operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half. Your task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.",objectivesText="Covertly place Suspicious Crates and slay guards.",rewardGold=234000,rewardXP=6815,rewardItems={171365},starts={{npcID=156440}},ends={{npcID=156440}},coords={x=0.188,y=0.584,source="quest_giver",zoneID=3433},questType="standard"},
[57149] = {id=57149,name="Propaganda Takedown",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11402,mapID=95,description="Recently, dissidents have been posting propaganda around the city and spreading all manner of lies. This is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers. Tear down the rubbish. It can only lead to panic in the streets. And should you encounter any... resistance... you are hereby authorized to respond with force.",objectivesText="Burn Dissident Propaganda in Orgrimmar.",rewardGold=234000,rewardXP=6815,starts={{npcID=156440}},ends={{npcID=156440}},coords={x=0.188,y=0.584,source="quest_giver",zoneID=3433},questType="standard"},
[57150] = {id=57150,name="Militia",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11402,mapID=95,description="The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield. Rally the citizens and form a militia! Remind them of their slain brothers and sisters!",objectivesText="Rally the citizens of Orgrimmar.",rewardGold=234000,rewardXP=6815,starts={{npcID=156440}},ends={{npcID=156440}},coords={x=0.188,y=0.584,source="quest_giver",zoneID=3433},questType="standard"},
[57151] = {id=57151,name="A Line in the Sand",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11402,mapID=95,description="Now that we have put our house in order, it is time to purge the filth before our gates. How thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop. Let us end this pitiful rebellion.",objectivesText="Speak with Nathanos.",rewardGold=468000,rewardXP=8520,starts={{npcID=156440}},ends={{npcID=156425}},coords={x=0.188,y=0.584,source="quest_giver",zoneID=3433},questType="standard"},
[57152] = {id=57152,name="Most Loyal",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11402,mapID=95,description="The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly. You are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. She will meet you near Windrunner Spire.",objectivesText="Speak with Sylvanas Windrunner.",rewardGold=468000,rewardXP=8520,rewardItems={172203},starts={{npcID=156425}},ends={{npcID=156425}},coords={x=0.186,y=0.584,source="quest_giver",zoneID=3433},questType="standard"},
[57155] = {id=57155,name="Blinding the Eye",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10266,description="Ah yes, just the I wanted to see. I can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection. Through my research I have learned a less painful way of removing the infection. Speak with me, and let's put an end to this nightmare.",objectivesText="Speak with Brother Pike to cleanse your \"gift\".",rewardGold=23400,rewardXP=850,questType="standard"},
[57156] = {id=57156,name="Blinding the Eye",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10266,description="You finally arrived . Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you. Dis won't hurt. Much. Tell me when you are ready to begin.",objectivesText="Speak with Nailok to cleanse your \"gift\".",rewardGold=23400,rewardXP=850,questType="standard"},
[57159] = {id=57159,name="A Reflection of Truth",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I sent the Fearstalker far from here with that trap--buying us some time. On the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place. Join me through the mirror, . You shall see the truth of this \"drought\" first hand.",objectivesText="Follow the Accuser through the mirror and witness the truth of Revendreth .",rewardGold=514800,rewardXP=1770,starts={{npcID=156554}},ends={{npcID=156554}},coords={x=0.516,y=0.592,source="quest_giver",zoneID=10413},questType="standard"},
[57161] = {id=57161,name="I Don't Get My Hands Dirty",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You heard Sire Denathrius. Today, I ascend to the Court of Harvesters. You are fortunate to have the honor of witnessing my rise to power. The traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed. Nothing can stand against me now that I have a Harvester's medallion. But I will not waste my power on this rabble.",objectivesText="Clear the bridge for Lord Chamberlain . Progress: Clear the way for Lord Chamberlain !",rewardGold=257400,rewardXP=1415,rewardItems={175714},rewardChoices={175714},starts={{npcID=156605}},ends={{npcID=156842}},coords={x=0.58,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57164] = {id=57164,name="Devour This",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Though the souls are our primary target, another challenge has arisen. The Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no? I should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.",objectivesText="Eliminate the devourers in the Banewood. Progress: Are the devourers finished?",rewardGold=238680,rewardXP=1415,starts={{npcID=168664}},ends={{npcID=168664}},coords={x=0.478,y=0.7,source="quest_giver",zoneID=10413},questType="standard"},
[57173] = {id=57173,name="The Accuser's Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Lord Chamberlain will cross the bridge when it pleases him. Before he arrives, you will seize the Accuser's sinstone. Wise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them. The Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see. Boasting of the many, many sins she's overcome. Proud. Arrogant. Most importantly, foolish. Her sinstone lies on the altar before us, seemingly unguarded. Retrieve it.",objectivesText="Investigate the Accuser's sinstone.",rewardGold=128700,rewardXP=710,starts={{npcID=156842}},ends={{npcID=156823}},coords={x=0.646,y=0.5,source="quest_giver",zoneID=10413},questType="standard"},
[57174] = {id=57174,name="The Stoneborn",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12842,mapID=1525,description="The Stone Legion is not even here yet? This is an outrage. If we do not do something quickly, the rebels will overrun this filthy hamlet. Here, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job. I will try to commune with the Master and see if he can send reinforcements.",objectivesText="Collect the Anima Cage and then awaken 6 Stoneborn Guardians . Progress: Darkhaven. Such a pitiful hamlet filled with unworthy supplicants.",rewardGold=128700,rewardXP=710,starts={{npcID=156374}},ends={{npcID=156822}},coords={x=0.606,y=0.608,source="quest_giver",zoneID=10413},questType="standard"},
[57175] = {id=57175,name="Inquisitor Vilhelm's Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone. Broken into several pieces and hidden from sight, he believed his sinstone would be safe from us. But his plan had the same weakness as most: he trusted weak-willed underlings. I \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone. Find all the fragments and bring them to me.",objectivesText="Collect the 3 Hidden Sinstone Fragments .",rewardGold=252720,rewardXP=1415,rewardItems={171100,171101,171102,171103},starts={{npcID=163576}},ends={{npcID=164166}},coords={x=0.674,y=0.536,source="quest_giver",zoneID=10413},questType="standard"},
[57176] = {id=57176,name="Sinstone Delivery",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone. But, thanks to your delays, our reinforcement of his position is overdue. I will collect the Accuser's sinstone and carry us to the battle.",objectivesText="Fly with Echelon and deliver the Accuser's Sinstone to Lord Chamberlain .",rewardGold=63180,rewardXP=355,starts={{npcID=164166}},ends={{npcID=157069}},coords={x=0.66,y=0.472,source="quest_giver",zoneID=10413},questType="standard"},
[57177] = {id=57177,name="A Fresh Start",expansion=8,mapID=1525,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Halls of Atonement purged"},{orderIndex=1,type=0,amount=34,objectID=164199,text="Small Enemy"},{orderIndex=2,type=0,amount=20,objectID=164200,text="Normal Enemy"},{orderIndex=3,type=0,amount=5,objectID=164201,text="Big Enemy"},{orderIndex=4,type=0,amount=34,objectID=164203,text="Small Interact"},{orderIndex=6,type=0,amount=34,objectID=164204,text="Normal Interact"},{orderIndex=5,type=0,amount=50,objectID=164260,text="Small Interact"},{orderIndex=7,type=0,amount=4,objectID=157065,text="Accuser Defeated"},{orderIndex=8,type=0,amount=50,objectID=163675,text="Burden of Pride"}},worldTaskTitle="A Fresh Start"},
[57178] = {id=57178,name="The Master Awaits",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Maw Walker, I am General Kaal . Those stoneborn who remember their oaths to the Master are under my command. The path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. Sire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.",objectivesText="Meet Sire Denathrius. Progress: Mind your manners when speaking to Sire Denathrius. He is a being older than your world.",rewardGold=25740,rewardXP=175,starts={{npcID=155541}},ends={{npcID=156374}},coords={x=0.604,y=0.608,source="quest_giver",zoneID=10413},questType="standard"},
[57179] = {id=57179,name="The Authority of Revendreth",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="$p, a proud . I know your name and your deeds. I can taste your regrets and your shame. More importantly, I know what you might become. You can be the beacon for the Shadowlands to rally behind. The symbol my people need to set aside these petty squabbles and help fix the problems that afflict all reality. Before you stands the Court of Harvesters, my most loyal and trusted venthyr. Where once there were seven, only four remain. Introduce yourself to them, for where they go, my power follows",objectivesText="Accept the Master's Boon. Progress: My eyes are everywhere.",rewardGold=189540,rewardXP=1060,starts={{npcID=156644}},ends={{npcID=156644}},coords={x=0.574,y=0.496,source="quest_giver",zoneID=10413},questType="standard"},
[57180] = {id=57180,name="The Accuser's Secret",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all! Protect me while I study this sinstone, and you will be rewarded as first among my retainers. After I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward. This feat heralds my own ascension to the Court of Harvesters!",objectivesText="Help Lord Chamberlain defeat the Accuser.",rewardGold=514800,rewardXP=1770,rewardItems={175732},rewardChoices={175732},starts={{npcID=157069}},ends={{npcID=157084}},coords={x=0.656,y=0.496,source="quest_giver",zoneID=10413},questType="standard"},
[57182] = {id=57182,name="The Accuser's Fate",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You now stand in the presence of a Harvester, Maw Walker. Lord Chamberlain breathes in deeply and smiles.> I will use the Accuser's medallion to solidify my foothold over the Halls of Atonement. Meanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me. Myskia will be along shortly to retrieve you. Do not keep the Master waiting.",objectivesText="Ride Myskia and deliver the Accuser to Sire Denathrius . Progress: I trust you have the medallion that I loaned to the Lord Chamberlain ?",rewardGold=64350,rewardXP=355,rewardItems={175756},starts={{npcID=157084}},ends={{npcID=156381}},coords={x=0.662,y=0.504,source="quest_giver",zoneID=10413},questType="standard"},
[57185] = {id=57185,name="Dutybound",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Welcome to the fight, . You're with us now. Take a moment and introduce yourself. I will meet you by Draven at the lodge.",objectivesText="Introduce yourself to General Draven , Nadjia the Mistblade , and Rendle .",rewardGold=128700,rewardXP=710,questType="standard"},
[57189] = {id=57189,name="Breaking the Hopebreakers",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, . Draven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention. The Accuser hands you a collection of bright red vials.> Throw these on her hunters. It should draw the attention of the devourers infesting this place.",objectivesText="Use the Concentrated Anima Vial to defeat the hopebreakers in Dredhollow.",rewardGold=514800,rewardXP=1770,rewardItems={177633,177634,177646,177648,177650,177651,177652,178873},rewardChoices={177646,177651,177650,177648,177652,177634,177633},starts={{npcID=168217}},ends={{npcID=168468}},coords={x=0.432,y=0.738,source="quest_giver",zoneID=10413},questType="standard"},
[57190] = {id=57190,name="They Won't Know What Hit Them",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. Plant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima. That should get the devourers infesting this place to flock to them like moths to a flame.",objectivesText="Plant 8 Rigged Anima Containers.",rewardGold=257400,rewardXP=1415,starts={{npcID=168217}},ends={{npcID=168468}},coords={x=0.432,y=0.738,source="quest_giver",zoneID=10413},questType="standard"},
[57198] = {id=57198,name="Sense of Obligation",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=862,description="Derek is free. I have to atone for much with him. There is a rumor of a meeting with Jaina and her brother. Head to Seabreeze Village in Stormsong Valley . I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus. If you find out anything of interest, I would be most appreciative. For now, let's keep this between the two of us.",objectivesText="Eavesdrop on Jaina Proudmoore's meeting.",rewardGold=23400,rewardXP=850,starts={{npcID=141961}},ends={{npcID=141961}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[57205] = {id=57205,name="A Few Bumps Along the Way",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="This territory is strategic to our defense, we can not allow these abominations to force our retreat! Seize control of two of the locations marked on your map. Defend them from enemy attack till the flag is planted and the location captured.",rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=2,objectID=156797,text="Artillery defended"}},worldTaskTitle="A Few Bumps Along the Way",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57207] = {id=57207,name="Lysonia's Plan",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent. We must stop her.",objectivesText="Confront Lysonia. Progress: <The Paragon of Humility clutches his body in pain.>",rewardGold=128700,rewardXP=4085,starts={{npcID=156361}},ends={{npcID=156474}},coords={x=0.618,y=0.436,source="quest_giver",zoneID=10534},questType="standard"},
[57220] = {id=57220,name="Power Protocol Initiation",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="We've come a long way, . Once the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics. All that's left is settin' the final pieces in place.",objectivesText="Relay power from the Chamber of Heart, Engine of Nalak'sha and Forge of Origination auxiliary systems, then speak with MOTHER to power up the Forge of Origination. Progress: Quite the journey so far.",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=152206}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[57221] = {id=57221,name="Re-Origination",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=84,description="If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination. We best get back tae investigate, .",objectivesText="Meet Magni Bronzebeard outside the Halls of Origination in Uldum.",rewardGold=34100,rewardXP=850,starts={{npcID=152206}},ends={{npcID=154532}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[57222] = {id=57222,name="Investigating the Halls",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers. Best check yer gear 'fore headin' in, . Who knows what's waitin' fer us in there.",objectivesText="Investigate the anomaly in the Halls of Origination.",rewardGold=234000,rewardXP=6815,starts={{npcID=154532}},ends={{npcID=155496}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[57225] = {id=57225,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[57226] = {id=57226,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",expansion=8,rewardItems={103533},questType="standard"},
[57228] = {id=57228,name="The Assault on Dredhollow",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us. We have done all we can do to prepare for their assault. Here. I fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces . The fight begins.",objectivesText="Defeat 12 of the Fearstalker's Forces .",rewardGold=257400,rewardXP=1415,questType="standard"},
[57240] = {id=57240,name="Where is Prince Renathal?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This is not victory, $p. If Prince Renathal does not return, we've merely delayed defeat. The Prince was last seen during an assault on the Master's keep alongside Duke Theotar. We don't know the Prince's fate, but we've learned that Duke Theotar was banished to the Ember Ward. The Ember Ward is a land of madness and torture. Blighted by the Light, the Master sends his most hated enemies there to suffer unending agony. Enter the Ember Ward, find Theotar, and discover the Prince's fate.",rewardGold=25740,rewardXP=175,starts={{npcID=168217}},ends={{npcID=157199}},coords={x=0.432,y=0.738,source="quest_giver",mapID=1525},questType="standard"},
[57245] = {id=57245,name="Ani-Matter Animator",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential. I've created what I call the \" Ani-Matter Orb ,\" with which you can reanimate the skeletal matter littered throughout the foundry. Let us see how many of the new animates would join our cause. As for those who don't... well, they should be quite accustomed to being slain by now.",objectivesText="Recruit 15 animates. Progress: Do we have enough animates?",rewardGold=257400,rewardXP=1415,rewardItems={175827,175841},starts={{npcID=157076}},ends={{npcID=157076}},coords={x=0.262,y=0.426,source="quest_giver",zoneID=11462},questType="standard"},
[57246] = {id=57246,name="Eel Filet",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1750,amount=50}},starts={{npcID=154304}},ends={{npcID=149805},{npcID=154304}},coords={x=0.393,y=0.535,source="quest_giver",zoneID=10052},questType="standard"},
[57247] = {id=57247,name="Fathom Ray Wing",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1749,amount=50}},starts={{npcID=150202}},ends={{npcID=149804},{npcID=150202}},coords={x=0.374,y=0.98,source="quest_giver",zoneID=10052},questType="standard"},
[57248] = {id=57248,name="Giant Crab Leg",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1355,objectivesText="Progress: Yes? What is it?",rewardGold=23400,rewardCurrencies={{id=1748,amount=50}},starts={{npcID=154297}},ends={{npcID=149803},{npcID=154297}},coords={x=0.394,y=0.534,source="quest_giver",zoneID=10052},questType="standard"},
[57249] = {id=57249,name="A Timely Invitation",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=440,description="The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. To commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! Come to the Caverns of Time and present this ticket to gain entry to the party!",objectivesText="Bring the Invitation from the Timewalkers to Chromie within the Caverns of Time.",coords={mapID=75,x=0.536,y=0.548},questType="standard"},
[57261] = {id=57261,name="Walk the Path, Aspirant",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times. Though you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek. Aspirant Kleia will show you the way. Archon's eyes upon you.",objectivesText="Travel with Kleia .",rewardGold=25740,rewardXP=175,starts={{npcID=166306}},ends={{npcID=165107}},coords={x=0.422,y=0.782,source="quest_giver",zoneID=10534},questType="standard"},
[57263] = {id=57263,name="The Cycle of Anima: Etherwyrms",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Forge is cold, yes? Need LOTS of anima to light. Sika references her scroll.> Times before now, anima is everywhere, yes? Now it hides. Small bits, weird places. We know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes? Maybe if we take what they have eaten, we can use it to light the forge. This will probably kill them. Sad, yes. But! We will not take too much. Just a little.",objectivesText="Slay Etherwyrms to collect 25 Glowing Viscera . Progress: Did you find anima? Small pieces, even?",rewardGold=236340,rewardXP=1415,rewardItems={172516},starts={{npcID=166577}},ends={{npcID=166577}},coords={x=0.526,y=0.826,source="quest_giver",zoneID=10534},questType="standard"},
[57264] = {id=57264,name="On the Edge of a Revelation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ah! Good. You answered the call. As you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others. Aspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention. You must push them, one way or another. Find the most vulnerable among your peers and do what you can to help them find the path forward.",objectivesText="Inspire 11 Vulnerable Aspirants to action. Progress: My disciples will be grateful for your aid, <name>.",rewardGold=236340,rewardXP=1415,starts={{npcID=157673},{npcID=160637}},ends={{npcID=159762}},coords={x=0.566,y=0.744,source="quest_giver",zoneID=10534},questType="standard"},
[57265] = {id=57265,name="The Cycle of Anima: Drought Conditions",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry. Now, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance. I am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains. Bring me the product it collects. Let us hope it is enough.",objectivesText="Collect a Condensed Anima Mote from the Anima Extractor . Progress: Is the extractor functional? How much were you able to acquire?",rewardGold=43200,rewardXP=1415,rewardItems={177954},starts={{npcID=158807}},ends={{npcID=158807}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57266] = {id=57266,name="The First Cleansing",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="This situation may feel familiar, . When you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence. This will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many. For you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself. Center yourself. When you are prepared, we will begin.",objectivesText="Undergo your first cleansing.",rewardGold=257400,rewardXP=1415,rewardItems={173321,173322,173323,173324},rewardChoices={173321,173322,173323,173324},starts={{npcID=159583}},ends={{npcID=158862}},coords={x=0.572,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[57267] = {id=57267,name="The Cycle of Anima: Flower Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="For forge to light, need more anima. Always more. Never too much, for forge! Sika consults her scroll and nods vigorously as she reads.> Out in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think. According to scrolls, it is called Adrima's Lily . We do not know who Adrima is. But the lily is good. Get flowers, too. Not just bulbs. Petals make stewards happy, too. Thank you!",objectivesText="Collect 6 Adrima's Lily . Progress: Do you have flower bulb things?",rewardGold=257400,rewardXP=1415,rewardItems={172518},starts={{npcID=166577}},ends={{npcID=166577}},coords={x=0.526,y=0.826,source="quest_giver",zoneID=10534},questType="standard"},
[57269] = {id=57269,name="The Hand of Doubt",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene. We will challenge Lysonia , and perhaps buy Eridia more time. This so-called Hand of Doubt will make no easy foe. Stand ready, .",objectivesText="Defeat Lysonia , Hand of Doubt.",rewardGold=257400,rewardXP=1415,rewardItems={176330,176332,176334,176336,176337,176338,176339,176388,176390},rewardChoices={176337,176388,176390,176339,176330,176334,176338,176336,176332},starts={{npcID=157673}},ends={{npcID=157687}},coords={x=0.566,y=0.744,source="quest_giver",zoneID=10534},questType="standard"},
[57270] = {id=57270,name="The Temple of Purity",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Greetings. I am Kosmas, Disciple to the Temple of Purity. The temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens. Of late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants. Your help is needed. Please report to the Hand of Purity at once.",objectivesText="Meet the Hand of Purity at the Temple of Purity.",rewardGold=25740,rewardXP=175,starts={{npcID=157673}},ends={{npcID=159762}},coords={x=0.566,y=0.744,source="quest_giver",zoneID=10534},questType="standard"},
[57274] = {id=57274,name="Quartermaster's Bounty",level=26,requiredLevel=26,faction="both",expansion=8,zoneID=8499,mapID=1161,objectivesText="Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.",rewardItems={171198},starts={{npcID=143560}},ends={{npcID=143560},{npcID=143555}},coords={x=0.564,y=0.258,source="quest_giver",zoneID=8568},questType="standard"},
[57275] = {id=57275,name="Something in Your Mind",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Wrathion knows more about it...>",objectivesText="Bring the Void Focus to Wrathion in the Chamber of Heart. Provided item:",rewardGold=23400,rewardXP=850,ends={{npcID=155496}},coords={mapID=84,source="quest_giver",x=0.846,y=0.3295},questType="standard"},
[57276] = {id=57276,name="Maintaining Focus",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9667,mapID=84,description="At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, , and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.",objectivesText="Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking upon a dangerous gambit, <name>. Caution is of the utmost importance.",rewardGold=936000,rewardXP=13630,starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57278] = {id=57278,name="Bring Me Their Heads",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. Though that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby. Slaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.",objectivesText="Collect 10 Traitor's Heads . Progress: Do you have the traitor's head ?",rewardGold=257400,rewardXP=1415,rewardItems={171204},starts={{npcID=157168}},ends={{npcID=157186}},coords={x=0.28,y=0.506,source="quest_giver",zoneID=11462},questType="standard"},
[57284] = {id=57284,name="Blade of Blades",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The finest sword in existence has been lost! Never in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves! I have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness! Once I find my weapon, that is. I insist you help me reclaim it. I know it's here somewhere!",objectivesText="Find Foe Cleaver amongst the forgotten weapons . Progress: Have you found Foe Cleaver ? Well? HAVE YOU?!",rewardGold=257400,rewardXP=1415,rewardItems={171205,171206},starts={{npcID=157168}},ends={{npcID=157186}},coords={x=0.28,y=0.506,source="quest_giver",zoneID=11462},questType="standard"},
[57288] = {id=57288,name="Assessing Your Strength",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The trial to come will test you in ways you can likely only imagine. I can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial. You will find three praetorian soldiers created for this purpose, each stronger than the last. Defeat them all and I will consider your strength sufficient to continue at this time.",objectivesText="Defeat the 3 Praetorian Sparring Assistants. Progress: How fares the combat?",rewardGold=48350,rewardXP=1415,starts={{npcID=158862}},ends={{npcID=158862}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[57290] = {id=57290,name="Beginning the Descent",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent. Until recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge. If we are to find answers, there is one place to look. Our journey continues, . Blackrock awaits.",objectivesText="Retrieve the Corrupt Black Dragonscale from Blackwing Descent atop Blackrock Mountain in Burning Steppes. Progress: Have you recovered what we discussed?",rewardGold=702000,rewardXP=10225,rewardItems={169223,171219,172072},rewardChoices={169223},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57291] = {id=57291,name="The Chamber of First Reflection",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ah, Athanos. It remains undefeated, as intended. Still, you have exceeded any expectation I might have had. You are stronger than many that have come before you. You have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite. Follow the path to the south and east. There you will find the entrance to the Chamber of First Reflection. Kleia will instruct you further. Go in service, .",objectivesText="Speak to Kleia in the Chamber of First Reflection.",rewardGold=23635,rewardXP=175,starts={{npcID=158807}},ends={{npcID=159583}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57298] = {id=57298,name="How Things \"Really\" Happened...",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=440,description="You've come a long way over the years, . From humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world. But why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! Don't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.",objectivesText="Embark from the Caverns of Time with Chromie to defeat villains of the past. Progress: Hey, did we win yet? Or have we begun? I'm maybe not yet sure. Keeping the timelines straight gets a bit difficult.",rewardCurrencies={{id=1166,amount=500}},starts={{npcID=157113}},ends={{npcID=157113}},questType="standard"},
[57300] = {id=57300,name="Soldier of Time",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=440,mapID=71,description="Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. Well, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.",objectivesText="Earn 500 honor in Korrak's Revenge. Progress: Did you have fun exploring Alterac Valley as it used to be?",rewardItems={137642,224556,232877,233014},rewardCurrencies={{id=1166,amount=400}},starts={{npcID=223882}},ends={{npcID=223882}},questType="pvp"},
[57301] = {id=57301,name="Callous Concoctions",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures! There are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge! Bring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities .",rewardGold=386100,rewardXP=1415,starts={{npcID=157313,x=0.586,y=0.734,zoneID=11462}},ends={{npcID=157313,x=0.586,y=0.734,zoneID=11462}},coords={x=0.586,y=0.734,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Callous Concoctions"},
[57302] = {id=57302,name="Alterac Valley Graveyards",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="The graveyards in Alterac Valley are prized territories. Both the Horde and the Alliance fight savagely for these sacred grounds. Are you, , ready to join that fight? I want you to assault an enemy graveyard. Find a graveyard with a Horde banner in its midst, and pull it from the ground! Do that, and your task will be complete.... But if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.",objectivesText="Assault a graveyard, then return to Sergeant Durgen Stormpike in Dun Baldar.",rewardGold=341600,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=159811}},ends={{npcID=159811}},questType="pvp"},
[57303] = {id=57303,name="The Quartermaster",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description=", our quartermaster charged me to direct new recruits to him. He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them. Follow the road. You'll find our quartermaster to the west.",objectivesText="Speak with the Stormpike Quartermaster .",rewardXP=175,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13797}},ends={{npcID=12096}},questType="pvp"},
[57304] = {id=57304,name="Capture a Mine",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="The mines in Alterac Valley hold more than just minerals. Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them! Capture a mine, then return to me. To capture a mine, enter one that we do not control and kill its leader. When you do that, the mine will be ours, and we'll send troops to protect it!",objectivesText="Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",rewardGold=683200,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=12096},{npcID=159811}},ends={{npcID=159811}},questType="pvp"},
[57305] = {id=57305,name="Armor Scraps",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!",objectivesText="Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar. Progress: Did you bring any armor scraps , <name>?",rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13257}},ends={{npcID=13257}},questType="pvp"},
[57306] = {id=57306,name="More Armor Scraps",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,objectivesText="Progress: <name>, we need more armor scraps to supply our troops!",rewardCurrencies={{id=1166,amount=1}},starts={{npcID=13257}},ends={{npcID=13257}},questType="pvp"},
[57307] = {id=57307,name="Towers and Bunkers",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="Towers and bunkers are key defensive positions, and so we must hold as many as possible! I want you to attack a tower or a bunker in Alterac Valley. To do that, enter a tower with a Horde banner atop it. You will see another enemy banner inside. Pull out that banner, and a white Alliance banner will appear in its place. Well done! At that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!",objectivesText="Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Dun Baldar.",rewardGold=341600,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=159811}},ends={{npcID=159811}},questType="pvp"},
[57309] = {id=57309,name="Begin the Attack!",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,objectivesText="Progress: My troops are supplied and ready to assault. We just need orders from Noreg Stormpike and I'll send them into the fray!",rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13446}},ends={{npcID=13446}},questType="pvp"},
[57310] = {id=57310,name="Irondeep Supplies",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine. The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, . Enter the mine and bring me a load of them.",objectivesText="Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Do you have the supplies, <name>? We can never have enough!",rewardGold=170800,rewardCurrencies={{id=1166,amount=2}},starts={{npcID=12096}},ends={{npcID=12096}},questType="pvp"},
[57311] = {id=57311,name="Coldtooth Supplies",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="The Coldtooth mine is a storage depot for the Horde. I can't stomach the food they give their troops, and the state of their arms and armor is atrocious! But... in times like these when supplies are so important, we can use what they have. Enter the Coldtooth mine and bring me back their supplies. That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors. Good luck, . The mine is to the distant south, deep in Horde territory.",objectivesText="Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Did you enter the Coldtooth mine in Horde territory, <name>? Did you raid their supplies?",rewardGold=309800,rewardCurrencies={{id=1166,amount=2}},starts={{npcID=12096}},ends={{npcID=12096}},questType="pvp"},
[57312] = {id=57312,name="The Graveyards of Alterac",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="The battle lines of Alterac Valley are ever shifting. Territories swing back and forth as we meet our opponents in deadly combat. And graveyards, , are where battles rage most fierce. I want you to attack an Alliance held graveyard! Find a graveyard with an Alliance banner in its midst and pull it from the ground. Do that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.",objectivesText="Assault a graveyard, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.",rewardGold=341600,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=158579}},ends={{npcID=158579}},questType="pvp"},
[57313] = {id=57313,name="Speak with our Quartermaster",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description=", the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley. Speak with him; he will tell you more. Follow the road west into the bunker, then take the west exit and you'll find our quartermaster.",objectivesText="Speak with the Frostwolf Quartermaster .",rewardXP=175,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13798}},ends={{npcID=12097}},questType="pvp"},
[57314] = {id=57314,name="Capture a Mine",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines. Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued! Help our war effort, ! Capture one of the mines for the Horde! To capture a mine, enter one that we do not control and kill its leader. When that is done, the mine will be ours and we'll send troops to protect it!",objectivesText="Capture a mine, then return to Corporal Teeka Bloodsnarl in Frostwolf Village. Progress: You haven't yet captured a mine, <name>! Find one that we do not control and defeat it's leader!",rewardGold=625600,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=12097},{npcID=158579}},ends={{npcID=158579}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[57315] = {id=57315,name="Towers and Bunkers",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="Towers and bunkers are important positions, and we must capture and hold them all! So to that end, I want you to attack a bunker that is controlled by the enemy. To do that, enter one with an Alliance banner. You will see another banner inside. Pull out that banner, and a white Horde banner will appear in its place. Well done! At that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!",objectivesText="Capture an enemy tower or bunker, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.",rewardGold=309800,rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=158579}},ends={{npcID=158579}},questType="pvp"},
[57316] = {id=57316,name="The Ladder",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Within the Theater of Pain, , legends rise like cream to the top. Listen to me, . If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions. Gather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!",objectivesText="Defeat 3 opponents within the Theater of Pain. Progress: Greetings, brother. Have you faced the madness of the arena?",rewardGold=368550,rewardXP=1415,rewardItems={176277,176278,176279,176280,176281,176282,176283,176284,176285,176286,176444,181529,181531,181534},rewardChoices={176277,181529,176278,176280,181531,176444,176282,176286,176281,176279,181534,176283,176285,176284},starts={{npcID=161733}},ends={{npcID=161733}},coords={x=0.504,y=0.516,source="quest_giver",zoneID=11462},questType="group"},
[57317] = {id=57317,name="Enemy Booty",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="When you fight the enemy, gather the scraps of their armor and bring them to me. I'll use those scraps to make armor for our own troops!",objectivesText="Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village. Progress: How goes the hunting, <name>. Do you have any armor scraps for me?",rewardXP=1415,rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13176}},ends={{npcID=13176}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="pvp"},
[57318] = {id=57318,name="More Booty!",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,objectivesText="Progress: I need more armor scraps , <name>! Do you have any?",rewardCurrencies={{id=1166,amount=1}},starts={{npcID=13176}},ends={{npcID=13176}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="pvp"},
[57320] = {id=57320,name="Launch the Attack!",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,objectivesText="Progress: My warriors are eager to attack! All I need are the assault orders...",rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13449}},ends={{npcID=13449}},questType="pvp"},
[57321] = {id=57321,name="Coldtooth Supplies",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it. And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, ! Go to the Coldtooth mine and bring me a load of them. And be wary of enemies as you go; the tides of battle shift quickly in that place...",objectivesText="Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Have you been to the Coldtooth mine, <name>? Do you have the supplies I asked for?",rewardGold=170800,rewardCurrencies={{id=1166,amount=2}},starts={{npcID=12097}},ends={{npcID=12097}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[57322] = {id=57322,name="Irondeep Supplies",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="The Stormpike dwarves are using the Irondeep mine as a storage depot. I want you to raid that mine and bring me its supplies. This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment! Be wary, . The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.",objectivesText="Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Did you enter the Irondeep mine, <name>? Did you raid its supplies?",rewardGold=341600,rewardCurrencies={{id=1166,amount=2}},starts={{npcID=12097}},ends={{npcID=12097}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[57324] = {id=57324,name="Sail With the Tide",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=1161,description="Hello, $p. I have received word from Calia asking that we meet with her once again. She has so much to offer those who feel lost, those seeking a better way. Once she is free of doubt, she will know what must be done. Will you join me?",objectivesText="Meet with Calia Menethil and Derek Proudmoore.",rewardGold=234000,rewardXP=6815,starts={{npcID=150633}},ends={{npcID=156513}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[57328] = {id=57328,name="Trashin' the Camp",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13575,mapID=1525,rewardXP=8165,rewardItems={171249,171310},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Stalker's Lodge assaulted"}},worldTaskTitle="Trashin' the Camp",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57362] = {id=57362,name="Deeper Into the Darkness",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="This recent change of events allows us to continue our journey to discover what darkness lies beyond the sands. It will not be easy, . We stand on the precipice of the unknown, but now the tables have turned. Wrathion glances at your new attire.> You do dress the part. Let's see what insights your return to the Halls of Origination bring to light.",objectivesText="Speak with MOTHER to return to the Halls of Origination in Uldum to discover the source behind the anomaly. Progress: I await your return.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=2000}},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57370] = {id=57370,name="Assault: The Black Empire",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=5034,mapID=249,questType="standard"},
[57371] = {id=57371,name="Assault: Aqir Unearthed",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=5034,mapID=249,questType="standard"},
[57372] = {id=57372,name="The Drag",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=15946,questType="standard"},
[57373] = {id=57373,name="Descending Into Madness",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead. Locate one of these incursions and see what happens when you peer beyond the dark veil.",objectivesText="Seek out a Vision of N'Zoth amidst the corruption in Vale of Eternal Blossoms or Uldum to discover what the future holds for Azeroth.",rewardGold=234000,rewardXP=6815,rewardItems={173431,173439,173447,173455,173812,173815,173818,173821},rewardChoices={173431,173439,173447,173455,173812,173815,173818,173821},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57374] = {id=57374,name="Into the Darkest Depths",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12905,mapID=84,description="With our connection secured, it is time for us to breach the veil and discover what lies beyond. What you find may provide us the key to unlocking our success.",objectivesText="Enter a Horrific Vision to discover what dark manifestations await in a world ruled by N'Zoth. Progress: Your expertise in these matters are invaluable.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1719,quantity=1}},starts={{npcID=155496}},ends={{npcID=161811}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57376] = {id=57376,name="The Hidden Need",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=85,mapID=862,description="Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. We cannot do that without accepting ourselves. So many feel lost, alone... abandoned. I have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness. Meet me in Tirisfal Glades , at the Calston Estate.",objectivesText="Meet Lilian Voss in Tirisfal Glades .",rewardGold=341600,rewardXP=6815,starts={{npcID=141961}},ends={{npcID=157230}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[57377] = {id=57377,name="A Hand Offered",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8044,description="Here begins the calia intro",questType="standard"},
[57378] = {id=57378,name="Remnants of a Shattered World",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences. Seek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings. In the meantime, MOTHER and I shall continue our research here in the chamber. We await your return, .",objectivesText="Recover a copy of \" The Curse of Stone \" from a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Find anything of interest?",rewardGold=309800,rewardXP=6815,rewardItems={171335,174777},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57380] = {id=57380,name="Sign Your Own Death Warrant",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Ember Ward only for bad buds! Stonehead squints at you and shakes head.> You not look like other bad buds! Bad buds come with bad paper!",rewardGold=257400,rewardXP=1415,rewardItems={171343,171344,171345},starts={{npcID=157199}},ends={{npcID=157199}},coords={x=0.39,y=0.66,source="quest_giver",mapID=1525},questType="standard"},
[57381] = {id=57381,name="The Greatest Duelist",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="A mortal in Revendreth . Well, well, well... you are primed to be at the head of high adventure. The name you may call me is Nadjia the Mistblade , and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword. This trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting. Do we have an accord?",objectivesText="Release Nadjia the Mistblade . Progress: That consecrated iron really leaves one feeling stiff afterward.",rewardGold=257400,rewardXP=1415,rewardItems={175730},rewardChoices={175730},starts={{npcID=157550}},ends={{npcID=157550}},coords={x=0.656,y=0.646,source="quest_giver",zoneID=10413},questType="standard"},
[57386] = {id=57386,name="If You Want Peace...",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor. If their honor has been tossed aside, then they may move their forces beyond just Bastion. Take care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.",objectivesText="Enter Maldraxxus .",rewardGold=24100,rewardXP=175,starts={{npcID=171338}},ends={{npcID=164244}},questType="standard"},
[57390] = {id=57390,name="To Die By the Sword",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="What's this? You fly no colors! Where is the pride in your house, gladiator? Bah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster! I remember the old days. The strongest souls arriving, then being divided among the five houses... No matter. The tournament beckons. Enter the arena! Fight for glory! By the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.",objectivesText="Defeat 30 contenders in the Theater of Pain. Progress: What are you waiting for? Put on a show!",rewardGold=241020,rewardXP=1415,starts={{npcID=164244}},ends={{npcID=164244}},coords={x=0.504,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[57391] = {id=57391,name="Reconstructing \"The Curse of Stone\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth. Mad ravings, intended to erode the reader's acceptance of reality. Still, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it. Bring as many pages from this tome as you can find.",objectivesText="Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: What have you been able to find?",rewardGold=210675,rewardXP=5110,rewardItems={171335,171353},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57392] = {id=57392,name="Reconstructing \"The Curse of Stone\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly. There remains much to learn, however. Continue your search for additional pages as you delve into the visions.",objectivesText="Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: Urgent matters require a great deal of attention. Unless it is of the utmost importance, I must see to my work.",rewardGold=232300,rewardXP=5110,rewardItems={171335,171353},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57393] = {id=57393,name="Stepping Through the Darkness",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. To further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power. Seek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.",objectivesText="Recover a copy of \" Fear and Flesh \" from the depths of a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Dark and deep are the shadows.",rewardGold=309800,rewardXP=6815,rewardItems={169223,171354},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57394] = {id=57394,name="Reconstructing \"Fear and Flesh\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it. But if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.",objectivesText="Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The missing pages must reside deeper within these visions. As dark and difficult these times may seem, we mustn't forget the possibility remains of a time of great success and discovery.",rewardGold=232300,rewardXP=5110,rewardItems={171354,174783},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57395] = {id=57395,name="Reconstructing \"Fear and Flesh\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.",objectivesText="Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Anything to share?",rewardGold=232300,rewardXP=5110,rewardItems={171354,174783},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57396] = {id=57396,name="Reconstructing \"Fear and Flesh\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.",objectivesText="Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Nearly halfway there, <name>. Have you found anything new?",rewardGold=232300,rewardXP=5110,rewardItems={171354,174783},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57397] = {id=57397,name="Reconstructing \"Fear and Flesh\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.",objectivesText="Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The darkness lingers. Never hurried. Never sleeping. Patiently waiting...",rewardGold=232300,rewardXP=5110,rewardItems={171354,174783},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57398] = {id=57398,name="Walking in the Darkness",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="The end nears. The darkest corners of these visions await. Our work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.",objectivesText="Recover a copy of \" The Final Truth \" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I await your return.",rewardGold=309800,rewardXP=6815,rewardItems={169223,171355},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57399] = {id=57399,name="Reconstructing \"The Final Truth\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages. Even incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting. That being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.",objectivesText="Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I often find my own thoughts wandering, weary of what lies ahead. How are you faring, <name>? Have you any news?",rewardGold=232300,rewardXP=5110,rewardItems={171355,174785},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57400] = {id=57400,name="Reconstructing \"The Final Truth\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness. This is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude. Keep looking for pages from the book, . But... leave the reading to me.",objectivesText="Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Your success has brought us this far, <name>. Perhaps you have something to share?",rewardGold=232300,rewardXP=5110,rewardItems={171355,174785},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57401] = {id=57401,name="Reconstructing \"The Final Truth\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come. No amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it. Find me the final pages of this accursed tome, . I wish to learn what I need from it and be done with it forever.",rewardGold=232300,rewardXP=5110,rewardItems={171355,174785},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",mapID=84},questType="standard"},
[57402] = {id=57402,name="Reconstructing \"The Curse of Stone\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we? The book is nearly complete. Continue retrieving its pages from within the visions.",objectivesText="Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: I believe we are on the precipice of a something grand.",rewardGold=232300,rewardXP=5110,rewardItems={171335,171353},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57403] = {id=57403,name="Reconstructing \"Fear and Flesh\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.",objectivesText="Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Making progress?",rewardGold=232300,rewardXP=5110,rewardItems={171354,174783},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57405] = {id=57405,name="Chasing Madness",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="An adversary with no ferry cannot be merry unless it is wary!",rewardGold=128700,rewardXP=710,starts={{npcID=157588}},ends={{npcID=157639}},coords={x=0.37,y=0.632,source="quest_giver",mapID=1525},questType="standard"},
[57425] = {id=57425,name="Land of Opportunity",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This is it! The final event of the tournament! These two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left... Is for one to slay the other!",objectivesText="Defeat High Champion Meskal .",rewardGold=514800,rewardXP=1770,rewardItems={175466,175467,175468,175469},rewardChoices={175468,175466,175469,175467},starts={{npcID=164244}},ends={{npcID=162069}},coords={x=0.504,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[57426] = {id=57426,name="My Terrible Morning",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You simply won't believe what happened to me! I was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me! Amongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol. A tragedy of the highest order! Without it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land. The Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?",rewardGold=257400,rewardXP=1415,rewardItems={175423,175424,175425,175426},rewardChoices={175425,175423,175426,175424},starts={{npcID=157639}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57427] = {id=57427,name="Unbearable Light",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners. That is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body. With the right skills, it is possible to reverse the Light's desecration if it is treated quickly. But the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.",rewardGold=257400,rewardXP=1415,starts={{npcID=157639}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57428] = {id=57428,name="Theotar's Mission",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh the Accuser sent you? How keen! I do, in fact, know the fate of Prince Renathal... at least part of it. When our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall. I'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think. My parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.",rewardGold=257400,rewardXP=1415,rewardItems={171468,171469},starts={{npcID=157639}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57442] = {id=57442,name="Lost in the Desiccation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Theotar incapable of forming coherent sentences. Instead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.> Lost... Syb... Tubbins ... Late for tea... Theotar 's hideout a different way.>",rewardGold=257400,rewardXP=1415,ends={{npcID=157801}},questType="standard"},
[57443] = {id=57443,name="Dirty Job: Demolition Detail",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=157649,text="Rubble Wreckage demolished"},{orderIndex=0,type=3,amount=1,objectID=157632,text="Grab a dredger"}},worldTaskTitle="Dirty Job: Demolition Detail",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57444] = {id=57444,name="An Inspired Moral Inventory",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="! You are well! I am glad of it. Many of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable. This is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways. If they remain unrepentant, then there is no hope for them. They must die.",objectivesText="Slay 3 Forsworn ascended . Progress: They betrayed us.",rewardGold=289575,rewardXP=1060,starts={{npcID=160647}},ends={{npcID=160647}},coords={x=0.58,y=0.758,source="quest_giver",zoneID=10534},questType="standard"},
[57446] = {id=57446,name="The Enemy You Know",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="My heart is filled with dread. If it truly is Lysonia who leads them now... No. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs. They will no doubt try to stop you. I will hold their leader's attention as long as I can. If I do not survive... my disciple will see you safely from this place. Go in service.",objectivesText="Confront Lysonia and cleanse the great Vespers.",rewardGold=63800,rewardXP=1415,starts={{npcID=159762}},ends={{npcID=157673}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[57447] = {id=57447,name="Purity's Prerogative",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Do you feel it, ? That cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will. I do not know how Lysonia came to possess this power, but we must act quickly. I will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly. Speak to me when you are prepared to leave the temple.",objectivesText="Fly with Vesiphone to Purity's Reflection.",rewardGold=25740,rewardXP=175,starts={{npcID=157687}},ends={{npcID=156238}},coords={x=0.646,y=0.71,source="quest_giver",zoneID=10534},questType="standard"},
[57448] = {id=57448,name="New Allies Among Us",level=40,requiredLevel=40,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Even in times of peace, the Horde is not without its problems. Although they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. We don't turn people away when times get tough; we band together and endure. For a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. My only hope is that they still see as much value in the Horde as I see in them.",objectivesText="Witness Baine welcome the vulpera into the Horde.",rewardGold=1024800,rewardXP=8200,rewardItems={174066},starts={{npcID=145424}},ends={{npcID=157693}},coords={x=0.484,y=0.714,source="quest_giver",zoneID=1637},questType="standard"},
[57454] = {id=57454,name="Silence in the Stalks",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Hmm. Well that's not... great. But no cause for alarm, yet! It has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return! Unfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius , since the crisis began. Please, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!",objectivesText="Speak to Cortinarius outside the Stalks.",rewardGold=25740,rewardXP=1020,starts={{npcID=174609}},ends={{npcID=157710}},questType="standard"},
[57455] = {id=57455,name="Mushroom For Improvement",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The mushrooms are under attack! I need your help, or we risk losing it all! Some fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me! I'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do. Sprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald .",objectivesText="Use the Pouch of Spores to plant mushrooms on 15 masked fae in the Stalks. Progress: They'd be feeding the mushrooms anyway, so you might as well accelerate the process.",rewardGold=257400,rewardXP=8165,rewardItems={171989},starts={{npcID=157710}},ends={{npcID=157710}},coords={x=0.332,y=0.364,source="quest_giver",zoneID=11510},questType="standard"},
[57457] = {id=57457,name="Shaking 'Shrooms",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,description="The mushrooms in there need your help, ! Some of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there. If you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.",objectivesText="Shake 8 Swollen Mushroom Stalks.",rewardGold=257400,rewardXP=8165,questType="standard"},
[57458] = {id=57458,name="Ring Repairs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The damage wrought here is severe, but it can be reversed. My master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again. Take this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.",objectivesText="Use the Fungal Beacon to repair 6 Damaged Mushrooms .",rewardGold=257400,rewardXP=8165,rewardItems={172084},starts={{npcID=157710}},ends={{npcID=157710}},coords={x=0.332,y=0.364,source="quest_giver",zoneID=11510},questType="standard"},
[57459] = {id=57459,name="Fighting For Fungus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Behold, Marasmius ! This is his home, his heart. Every mushroom in Ardenweald , maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this. Our foes may look mindless, but they are clever. They will have tracked my position by now. I shall make my final stand here, and hope that Marasmius is strong enough to lend his aid. Will you stand with me, ?",objectivesText="Help Cortinarius defend Marasmius .",rewardGold=514800,rewardXP=10205,starts={{npcID=157710}},ends={{npcID=334880}},coords={x=0.332,y=0.364,source="quest_giver",zoneID=11510},questType="standard"},
[57460] = {id=57460,name="Tubbins's Tea",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Theotar teach Tubbins special tea that make Light go away! Tubbins good tea maker! Watch Tubbins make Theotar feel good! Then Tubbins feel good!",rewardGold=193050,rewardXP=1060,starts={{npcID=157801}},ends={{npcID=157801}},coords={x=0.31,y=0.576,source="quest_giver",mapID=1525},questType="standard"},
[57461] = {id=57461,name="An Uneventful Stroll",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening. Anyway, that tea picked me right up! When I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward. Myself and a few others have been working to gain access to that tower from below, but there are... obstacles. When you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.",rewardGold=514800,rewardXP=1770,rewardItems={179988,179989,179990,179991},rewardChoices={179988,179991,179990,179989},starts={{npcID=158542}},ends={{npcID=158694}},coords={x=0.312,y=0.574,source="quest_giver",mapID=1525},questType="standard"},
[57462] = {id=57462,name="Dream Catcher",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further. Hunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.",objectivesText="Acquire 200 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: Fortune favors the bold, <name>. And few acts are as bold as wielding the power of an Old God.",rewardGold=936000,rewardXP=13630,starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57463] = {id=57463,name="My Way or the Hyphae",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Hmph. More are coming. I would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done. How about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!",objectivesText="Ride the fae rings with Marasmius and defeat 30 invaders.",rewardGold=257400,rewardXP=8165,starts={{npcID=334880}},ends={{npcID=334880}},coords={x=0.295,y=0.347,source="quest_giver",zoneID=11510},questType="standard"},
[57464] = {id=57464,name="Maintaining Focus",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=84,description="At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, , and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.",objectivesText="Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking on a dangerous gambit, <name>. Caution is of the utmost importance.",rewardGold=936000,rewardXP=13630,starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57465] = {id=57465,name="Dirty Job: Wood Work",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=172929,text="Grab a dredger"},{orderIndex=1,type=0,amount=3,objectID=157831,text="Infested Horror Sap destroyed"}},worldTaskTitle="Dirty Job: Wood Work",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57470] = {id=57470,name="An Abominable Discovery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="$p. Come with me. I could explain, but it's easier to understand if you see it for yourself.",objectivesText="Follow Draka to Gharmal's Tower.",rewardGold=25740,rewardXP=1020,starts={{npcID=173308}},ends={{npcID=173194}},coords={x=0.31,y=0.294,source="quest_giver",zoneID=11462},questType="standard"},
[57471] = {id=57471,name="It's a Dirty Job",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This muck pool is all out of order. The anima shortage has taken its toll here for sure. You see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back! Now the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?",objectivesText="Throw Filthy Rubble into the muck pool.",rewardGold=12300,rewardXP=1415,starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[57473] = {id=57473,name="Prized Possession",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This chest is different. It's larger than the others... but more importantly, it's locked. Now, let's see what's inside.",objectivesText="Open the ornate chest. Progress: How did they acquire that?",rewardGold=25740,rewardXP=1020,rewardItems={182658},starts={{npcID=173194}},ends={{npcID=173194}},coords={x=0.274,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57474] = {id=57474,name="Dredger Duty",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble. We're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool. I'll show you how to dredge up some disposable dredgers to work with for now. Get 'em digging in the rubble to find us a Gem of Binding , and then we'll reshape 'em all into a biggun to kick them devourers outta here!",objectivesText="Dredge a dredger and bring it to the pile of rubble . Wait for it to dig through the pile and collect the Gem of Binding . Progress: You got the gem?",rewardGold=22600,rewardXP=1415,rewardItems={171966},starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[57475] = {id=57475,name="The Mantle Returned",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="The Mantle of the Primus... I can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it. This could prove vital toward our efforts to restore Maldraxxus . We must return it to Baroness Draka at the Seat of the Primus immediately.",objectivesText="Return to Draka at the Seat of the Primus.",rewardGold=25740,rewardXP=1020,starts={{npcID=173194}},ends={{npcID=161907}},coords={x=0.274,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57477] = {id=57477,name="We're Gonna Need a Bigger Dredger",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thanks for getting the stone, . While you were out I went ahead and dredged up a few more folks. Now we just need to re-shape these dredgers into a biggun.",objectivesText="Witness the ritual. Progress: What do you want?",rewardGold=64350,rewardXP=355,starts={{npcID=157846}},ends={{npcID=158001}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[57481] = {id=57481,name="Running a Muck",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Bootus ready to smash devourer skulls. Hop on.",objectivesText="Board Bootus and quell the devourer incursion. Progress: Enders smashed?",rewardGold=514800,rewardXP=1770,rewardItems={177653,177654,177655,177656},rewardChoices={177656,177655,177654,177653},starts={{npcID=158001}},ends={{npcID=157846}},coords={x=0.728,y=0.738,source="quest_giver",zoneID=10413},questType="standard"},
[57486] = {id=57486,name="Waning Energy",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1161,description="Mekkatorque's pod is powering down. We are no longer able to hear him speak. His pulse has slowed, in spite of the best efforts of Kul Tiran healers. I have an idea, but I am going to need your help. Meet me at Proudmoore Keep. We must go soon.",objectivesText="Meet Kelsey Steelspark at Proudmoore Keep.",rewardGold=30900,rewardXP=685,starts={{npcID=160101}},ends={{npcID=157997}},coords={x=0.73,y=0.168,source="quest_giver",zoneID=8568},questType="standard"},
[57487] = {id=57487,name="Someone Who Can Help",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1161,description="I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... The mechagnomes have advanced techniques in biomechanical repair and improvements. If there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters . Will you please help me get Mekkatorque's Pod to Mechagon?",objectivesText="Help Kelsey move Mekkatorque's Escape Pod to Mechagon. Progress: How can I help?",rewardGold=170800,rewardXP=2735,starts={{npcID=157997}},ends={{npcID=149816}},coords={x=0.37,y=0.626,source="quest_giver",zoneID=8568},questType="standard"},
[57488] = {id=57488,name="The Current Schematic",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions. There are some items I will need you to procure. From the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project. The Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.",objectivesText="Collect 4 Heat Tolerant Ooze and 6 Acquisitioned Machine Parts . Progress: Were all assets found?",rewardGold=341600,rewardXP=5465,rewardItems={172521,172522},starts={{npcID=150555}},ends={{npcID=150555}},coords={x=0.73,y=0.334,source="quest_giver",zoneID=10290},questType="standard"},
[57490] = {id=57490,name="Voyage to Safety",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. Since we started bringing goods in from Tiragarde, they have been a real thorn in our side. Piston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard. Please hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open. Ahem, we would not be upset if you did a little beach clean-up while you were there...",objectivesText="Defeat the scavenging troggs and retrieve Mekkatorque's Escape Pod . Progress: Did everyone make it back in one piece?",rewardGold=683200,rewardXP=6830,starts={{npcID=158145}},ends={{npcID=150555}},coords={x=0.74,y=0.368,source="quest_giver",zoneID=10290},questType="standard"},
[57491] = {id=57491,name="Better... Stronger... Less Dead",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. There are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning. The logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic. They currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.",objectivesText="Collect the Neural Accelerator , Omni Electromagnetic Amplifier , and Flux Energized Servos from the erratic units. Progress: Did you acquire the parts we need?",rewardGold=683200,rewardXP=6830,rewardItems={172511,173026,173028},starts={{npcID=160232}},ends={{npcID=160232}},coords={x=0.734,y=0.32,source="quest_giver",zoneID=10290},questType="standard"},
[57492] = {id=57492,name="Him?",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader. From what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. I seek a solution that will be most amenable to all. Will you gather the information I need?",objectivesText="Gather data from gnomes and mechagnomes in Mechagon. Progress: Have your communications been productive?",rewardGold=170800,rewardXP=2735,starts={{npcID=158145}},ends={{npcID=158145}},coords={x=0.74,y=0.368,source="quest_giver",zoneID=10290},questType="standard"},
[57493] = {id=57493,name="Mental Attunement",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. Your assistance is needed to get him stabilized and synchronized before removing him from his pod. Please position yourself by the Synchroscope . I will make adjustments, you will need to fire the machine when I call.",objectivesText="Activate the Synchroscope when Christy tells you to fire. Progress: Did you successfully push the button?",rewardGold=170800,rewardXP=2735,starts={{npcID=160232}},ends={{npcID=160232}},coords={x=0.734,y=0.32,source="quest_giver",zoneID=10290},questType="standard"},
[57494] = {id=57494,name="A Strong Heart",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="We saw a flare near Junkwatt Depot. The retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose. This is great news! However, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor . Please move with haste, we are so close to completion.",objectivesText="Retrieve the Spark Reactor and complete Mekkatorque's procedure. Progress: Are you ready?",rewardGold=683200,rewardXP=6830,rewardItems={173302},starts={{npcID=160232}},ends={{npcID=158145}},coords={x=0.734,y=0.32,source="quest_giver",zoneID=10290},questType="standard"},
[57495] = {id=57495,name="The Future of Mechagon",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike. It is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come! When you are ready, please join us at the High Tinkertory for a special address.",objectivesText="Travel to the High Tinkertory in Mechagon City. Progress: When you are ready, please join us at the High Tinkertory for a special address.",rewardGold=34100,rewardXP=685,starts={{npcID=162806}},ends={{npcID=159587}},questType="standard"},
[57496] = {id=57496,name="Ascension",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description="After everything the mechagnomes have done for us today, it is our duty to return the favor. Let us clear out the rogue creations that remain in Mechagon. With their home returned, Prince Erazmin and his people will have a brilliant path forward. With this team, we will make short work of the remaining King Mechagon loyalists. Let me know when you are ready to roll out!",objectivesText="Clear the remaining Mechagon defenders.",rewardGold=683200,rewardXP=6830,starts={{npcID=159587}},ends={{npcID=159587}},coords={x=0.73,y=0.336,source="quest_giver",zoneID=10290},questType="standard"},
[57497] = {id=57497,name="Propagate the News",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=1519,mapID=1161,description="We wanted to save a life and we have accomplished so much more! We really couldn't have done it without you, . I am so excited about the future of all gnomekind. Head back to Stormwind and share the good news!",objectivesText="Update Aysa Cloudsinger in Stormwind.",rewardGold=1024800,rewardXP=8200,rewardItems={174067},starts={{npcID=157997}},ends={{npcID=126332}},coords={x=0.37,y=0.626,source="quest_giver",zoneID=8568},questType="standard"},
[57506] = {id=57506,name="Light Lost",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss. Sadly, they are mistaken. To enter the Maw is to invite eternal damnation. But not for you. Please investigate their fate. If you can find them, their souls might once again be free.",objectivesText="Find Kyrian Aspirants within the Maw and return with their souls to Elysian Hold.",questType="standard"},
[57510] = {id=57510,name="Darklord Taraxis",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Darklord Taraxis"},
[57511] = {id=57511,name="Arms for the Poor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands. Each time, Maldraxxus claimed victory. Now scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals. If we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.",objectivesText="Arm 8 Displaced Scavengers with weaponry scattered around the Iron Trench. Progress: There should be plenty of weapons found on this old battlefield.",rewardGold=241020,rewardXP=1415,rewardItems={172020},starts={{npcID=162069}},ends={{npcID=162069}},coords={x=0.484,y=0.57,source="quest_giver",zoneID=11462},questType="standard"},
[57512] = {id=57512,name="Walk Among Death",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers. In simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that. Eliminate this potential threat, before our enemies turn them against us.",objectivesText="Kill 8 Unbound Deathwalkers .",starts={{npcID=162069}},ends={{npcID=162069}},questType="standard"},
[57513] = {id=57513,name="Enemy of My Enemy",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="I have no doubt you have questions. Know that we share enemies in this land. For now, we must move. I will get you to a safer location and then we can speak.",objectivesText="Escape from the Theater of Pain.",rewardGold=257400,rewardXP=1415,questType="standard"},
[57514] = {id=57514,name="The First Act of War",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Look around you, $p. This army is all that remains to defy the treachery of the other two houses. I must regroup with the margrave and discuss strategy. War will soon be upon us. I would ask that you prepare for the coming battle alongside the rest of our forces. We cannot afford for a single soldier to falter. Seek out Baron Vyraz . He has earned countless victories for Maldraxxus . I fear his blades must soon be turned upon our former allies.",objectivesText="Report to Baron Vyraz . Progress: What are you waiting for?",rewardGold=24335,rewardXP=175,starts={{npcID=159065}},ends={{npcID=157895}},coords={x=0.388,y=0.652,source="quest_giver",zoneID=11462},questType="standard"},
[57515] = {id=57515,name="The House of the Chosen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Look there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness. Let us ride to our fortress. There we can gather our strength and make ready for the battle to come.",objectivesText="Head to the House of the Chosen with Draka. Progress: Yes?",rewardGold=24100,rewardXP=175,starts={{npcID=167535}},ends={{npcID=159065}},questType="standard"},
[57516] = {id=57516,name="Through the Fire and Flames",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you. Potential that must be tested. A stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude. This trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once. Go on, then. Prove your worth.",objectivesText="Reach the Standing Stone. Progress: What happened?",rewardGold=243360,rewardXP=1415,rewardItems={175470,175471,175472,175473,178662},rewardChoices={175471,175473,175472,175470},starts={{npcID=159065}},ends={{npcID=159065}},coords={x=0.388,y=0.652,source="quest_giver",zoneID=11462},questType="standard"},
[57524] = {id=57524,name="Accessing the Archives",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="The information you've gathered has allowed us to better understand these manifestations. I believe MOTHER is waiting to share some of her findings with you.",objectivesText="Speak with MOTHER to activate the Titanic Research Archive, then examine the archives. Progress: Do you require assistance?",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1755,amount=10000}},starts={{npcID=155496}},ends={{npcID=152194}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[57529] = {id=57529,name="Garden in Turmoil",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Please excuse me for not standing. I would rather not disturb these creatures. If you have a desire to help the creatures of Bastion , Zosime needs aid to regain control of our garden. You will find her just down this path. Go in service.",objectivesText="Speak with Zosime downhill in the Garden of Respite.",rewardGold=25740,rewardXP=175,starts={{npcID=158005}},ends={{npcID=158004}},coords={x=0.522,y=0.614,source="quest_giver",zoneID=10534},questType="standard"},
[57530] = {id=57530,name="Gharmal's Tower",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Gharmal collected anything they believed to be an item of power. We'll need to search the tower. There is almost certainly something here of value to us.",objectivesText="Search Gharmal's Tower.",rewardGold=257400,rewardXP=8165,starts={{npcID=173194}},ends={{npcID=173194}},coords={x=0.274,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57531] = {id=57531,name="An Unfortunate Situation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Laurent , mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation. I was attempting to travel on royal business when my mirror sent me to this wasteland instead. Not a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain. Assist me and I will endeavor to create a mirror which will allow us to escape this wretched place.",objectivesText="Defeat Costel and recover Laurent's belongings . Progress: Have you recovered my belongings?",rewardGold=382590,rewardXP=1415,rewardItems={172074,175503,175504,175505,175506},rewardChoices={175504,175506,175505,175503},starts={{npcID=158038}},ends={{npcID=158038}},coords={x=0.264,y=0.49,source="quest_giver",zoneID=10413},questType="standard"},
[57532] = {id=57532,name="Foraging for Fragments",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing. I shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them. Nonetheless, I will not let this deter me. The Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.",objectivesText="Follow Laurent and collect Mirror Fragments . Progress: Simone shouldn't be here!",rewardGold=386100,rewardXP=1415,rewardItems={172085,172086,172087},starts={{npcID=158038}},ends={{npcID=158205}},coords={x=0.264,y=0.49,source="quest_giver",zoneID=10413},questType="standard"},
[57533] = {id=57533,name="Light Punishment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash. The Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain. I do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish. Free the others as you have freed me.",objectivesText="Free 5 Blistering Outcasts . Progress: Penance, not punishment. It seems the Master has forgotten the difference.",rewardGold=64800,rewardXP=1415,starts={{npcID=158088}},ends={{npcID=158088}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57534] = {id=57534,name="When Only Ash Remains",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Is this really what becomes of the exiled? Are they left here to burn to ash? How could the Master allow such a thing? It is cruel. Heartless, even. No venthyr would want to continue on like this. You must end their suffering.",objectivesText="Kill 10 Ashen Ravagers .",rewardGold=64800,rewardXP=1415,rewardItems={175507,175508,175509,175510,175716},rewardChoices={175507,175510,175509,175508,175716},starts={{npcID=158205}},ends={{npcID=158205}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57535] = {id=57535,name="Escaping the Master",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here. Simone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. But first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.",objectivesText="Collect 10 Mirror Fragments . Progress: Have you collected the fragments?",rewardGold=386100,rewardXP=1415,starts={{npcID=158205}},ends={{npcID=158205}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57536] = {id=57536,name="Mirror Making, Not Breaking",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. I need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. Are you ready?",objectivesText="Defend Laurent and Simone from Stone Legion attackers.",rewardGold=772200,rewardXP=1770,rewardItems={175733,177657},rewardChoices={175733,177657},starts={{npcID=158205}},ends={{npcID=158505}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57537] = {id=57537,name="Covering our Tracks",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there. We'll fly the rest of the way. Approach my flayedwing when you are prepared.",objectivesText="Ride with Draka to the House of the Chosen.",rewardGold=25740,rewardXP=175,questType="standard"},
[57538] = {id=57538,name="Disturbing the Peace",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too! Many creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving. If someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!",objectivesText="Kill 10 Anima-Starved creatures. Progress: We must deal with the anima-starved creatures so this place can return to a state of tranquility.",rewardGold=358020,rewardXP=1415,starts={{npcID=158004}},ends={{npcID=158004}},coords={x=0.512,y=0.596,source="quest_giver",zoneID=10534},questType="standard"},
[57545] = {id=57545,name="Distractions for Kala",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden. Since you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well. Hopefully the return of her toys will help keep her distracted.",objectivesText="Collect Kala's playthings. Progress: Do you have her playthings? She's becoming quite the handful!",rewardGold=358020,rewardXP=1415,rewardItems={172036,172037,172039},starts={{npcID=158004}},ends={{npcID=158004}},coords={x=0.512,y=0.596,source="quest_giver",zoneID=10534},questType="standard"},
[57549] = {id=57549,name="In Agthia's Memory",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Greetings, mortal! Are you here to learn about the legacy of Agthia, Paragon of Courage? I welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.",objectivesText="Read the Scrolls of Remembrance around Agthia's Repose. Progress: Agthia did not only live a life of courage, but one of service to all of the Shadowlands.",rewardGold=358020,rewardXP=1415,starts={{npcID=158078}},ends={{npcID=158078}},coords={x=0.47,y=0.634,source="quest_giver",zoneID=10534},questType="standard"},
[57551] = {id=57551,name="Agthia's Path",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself. Ring the bell, take a deep breath, and walk in Agthia 's steps.",objectivesText="Ring the Vesper of History.",rewardGold=96525,rewardXP=355,starts={{npcID=158078}},ends={{npcID=158181}},coords={x=0.47,y=0.634,source="quest_giver",zoneID=10534},questType="standard"},
[57552] = {id=57552,name="Warriors of the Void",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="These Void invaders are wiping our forces from existence! My disciples fall, returning their anima to the lands. If we fail to drive them from our lands, more than kyrian will be lost. First Bastion , then the Shadowlands as a whole.",objectivesText="Kill 15 Void forces.",rewardGold=41625,rewardXP=1415,starts={{npcID=158181}},ends={{npcID=158181}},coords={x=0.466,y=0.634,source="quest_giver",zoneID=10534},questType="standard"},
[57553] = {id=57553,name="On Wounded Wings",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I see my peers fall in pain, their wounds from the Void overtaking them. We cannot allow ourselves, or each other, to give up hope. Share your anima with our wounded brothers and sisters. Help them stand tall for another fight!",objectivesText="Heal 5 Wounded Defenders .",rewardGold=41625,rewardXP=1415,starts={{npcID=158178}},ends={{npcID=158181}},coords={x=0.464,y=0.636,source="quest_giver",zoneID=10534},questType="standard"},
[57554] = {id=57554,name="Wicked Gateways",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The forces of the Void are infinite. They travel through the Great Beyond by creating portals, twisting gateways between our planes. Quickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.",objectivesText="Destroy 3 Void Portals . Progress: New portals shall open, but we can prevent the swell for a time.",rewardGold=41625,rewardXP=1415,starts={{npcID=158181}},ends={{npcID=158181}},coords={x=0.466,y=0.634,source="quest_giver",zoneID=10534},questType="standard"},
[57555] = {id=57555,name="Shadow's Fall",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one... The Void cannot destroy us! They are led by Tezulat the Annihilator , scourge of a thousand realms. This day, his reign of terror will end!",objectivesText="Kill Tezulat the Annihilator . Progress: We shall sing the songs of Agthia , hero of Bastion , for eternities to come.",rewardGold=772200,rewardXP=1770,rewardItems={175719},rewardChoices={175719},starts={{npcID=158181}},ends={{npcID=158078}},coords={x=0.466,y=0.634,source="quest_giver",zoneID=10534},questType="standard"},
[57568] = {id=57568,name="Tough Love",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Heavens! Kala has flown off with Korinna's Allaying Crook ! I saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient. Here, take her slobber ball. It's her favorite and may help to distract her.",objectivesText="Retrieve Korinna's Allaying Crook from Kala inside her den. Progress: Do you have the crook?",rewardGold=772200,rewardXP=1770,rewardItems={172141,175616,175617,175618,175619},rewardChoices={175618,175616,175619,175617},starts={{npcID=158004}},ends={{npcID=158004}},coords={x=0.512,y=0.596,source="quest_giver",zoneID=10534},questType="standard"},
[57571] = {id=57571,name="Moving Mirrors",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="What sort of horrific trap is this? The Light is being reflected directly on her! Simone 's a dear friend of mine! Free her from that thing, please!",objectivesText="Redirect the mirror fragments to free Simone .",rewardGold=57075,rewardXP=1415,starts={{npcID=158205}},ends={{npcID=158088}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[57581] = {id=57581,name="Plucking Plumes",level=15,requiredLevel=15,faction="both",expansion=8,zoneID=3703,mapID=111,objectivesText="Progress: Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead. Continue to bring me more feathers as proof of your victory over them.",rewardItems={31800},starts={{npcID=22429}},ends={{npcID=22429}},questType="standard"},
[57583] = {id=57583,name="Through the Veil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving. Here, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you? Come back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.",objectivesText="Find somewhere to plant Marasmius in the Heart of the Forest.",rewardGold=128700,rewardXP=4085,rewardItems={178033},starts={{npcID=334880}},ends={{npcID=166982}},coords={x=0.295,y=0.347,source="quest_giver",zoneID=11510},questType="standard"},
[57584] = {id=57584,name="A Fate Most Noble",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Welcome, Worthy One! I am Greeter Mnemis . It is my duty and pleasure to assist you on this, your first day among the kyrian. Allow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home. I am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence. We will begin when you are ready.",objectivesText="Learn more about the kyrian. Progress: Please alert me to your needs and concerns, Worthy One.",rewardGold=257400,rewardXP=1415,starts={{npcID=158281}},ends={{npcID=165107}},coords={x=0.422,y=0.782,source="quest_giver",zoneID=10534},questType="standard"},
[57634] = {id=57634,name="Bring Your Own",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Scunner , a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. He emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own. Constructs are built to fight creatures like Scunner . So gather a force of them and eliminate the threat.",objectivesText="Defeat Scunner .",rewardXP=8165,rewardItems={183744,181806,184843},starts={{npcID=159199}},ends={{npcID=167150}},coords={x=0.554,y=0.684,source="quest_giver",zoneID=11462},questType="standard"},
[57636] = {id=57636,name="Pride of Place",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The Mantle of the Primus. It belongs on his statue. You were the one to recover it, so you will have the honor of returning it to its proper place.",objectivesText="Place the Mantle of the Primus. Progress: Each answer leads to another question. Each enemy defeated reveals another secret.",rewardGold=772200,rewardXP=12250,rewardItems={182258,182267,182276,182285},rewardChoices={182276,182267,182285,182258},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[57637] = {id=57637,name="Disturbance Detected: Firelands",level=35,requiredLevel=35,faction="both",expansion=8,zoneID=5723,mapID=84,description="You're early , I hadn't even sent for you yet. Another temporal disturbance has flared up, this time in the Firelands . If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out. Some intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.",objectivesText="Relive the siege of the Firelands . Progress: Bring me the temporal anomaly as soon as you can, so we can get back to yesterday's problems tomorrow.",rewardGold=341600,rewardXP=4790,rewardItems={69224,71665,77067,77069,78919,133543,171627,171628,171629,171630,171631,171632,171633,171634,171635,171636,171637,171638,171639,171842,171843,171844,171845,171846,171847,171848,171849,171850,171851,171852,171853,171854,171855,171856,171857,171858,171859,171860,171861,171862,171863,171864,171865,171866,171867,171868,171869,171870,171871,171872,171873,171874,171875,171876,171877,171878,171879,171880,171881,171882,171883,171884,171885,171886,171887,171888,171889,171890,171891,171892,172506,208095},rewardCurrencies={{id=1166,amount=300},{id=1166,amount=500}},starts={{npcID=158276}},ends={{npcID=158276}},coords={x=0.748,y=0.182,source="quest_giver",zoneID=1519},questType="standard"},
[57638] = {id=57638,name="Korrak the Bloodrager",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=65,description="The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew. We must show them our might! We have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager , tends to remain hidden until given a reason to make his presence known. Death to Korrak would mean death to Winterax Clan! Slay him and return.",objectivesText="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Dun Baldar. Progress: Be warned, soldier: The Frostwolf also hunt for Korrak.",rewardXP=2125,rewardItems={18150,172121,172122,172123,172125,172139},rewardChoices={172121,172122,172123,172125,172139},rewardCurrencies={{id=1166,amount=10}},starts={{npcID=158515}},ends={{npcID=158515}},questType="raid"},
[57639] = {id=57639,name="The Legend of Korrak",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=65,description="The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power. They are lead by Korrak the Bloodrager - a cruel and cunning beast. A strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!",objectivesText="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Warmaster Laggrond . Progress: Be warned, soldier, the Stormpike also hunt for Korrak.",rewardXP=2125,rewardItems={18149,172121,172122,172123,172125,172139},rewardChoices={172121,172122,172123,172125,172139},rewardCurrencies={{id=1166,amount=10}},starts={{npcID=158501}},ends={{npcID=158501}},questType="raid"},
[57640] = {id=57640,name="Master Ryson's All Seeing Eye",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.",objectivesText="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13151}},ends={{npcID=13151}},questType="pvp"},
[57641] = {id=57641,name="Master Ryson's All Seeing Eye",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,mapID=25,description="Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.",objectivesText="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13151}},ends={{npcID=13151}},questType="pvp"},
[57642] = {id=57642,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={172222,172223},starts={{npcID=187236}},ends={{npcID=187236}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[57643] = {id=57643,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={128768,172219},starts={{npcID=180746}},ends={{npcID=180746}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[57644] = {id=57644,name="No Friend Left Behind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him. I can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict... Though it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin . If not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.",objectivesText="Rescue Twigin . Progress: Please spare him this pain.",rewardGold=257400,rewardXP=8165,rewardItems={181237,183118},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158604}},ends={{npcID=158604}},coords={x=0.52,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[57646] = {id=57646,name="The Tithelord",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. He draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells. Speak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.",objectivesText="Slay The Tithelord and collect the Medallion of Envy . Progress: An Archlich? This complicates things.",rewardGold=772200,rewardXP=12250,rewardItems={173976,180920,180921,180922,180923},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167689}},ends={{npcID=158653}},coords={x=0.718,y=0.688,source="quest_giver",zoneID=10413},questType="standard"},
[57648] = {id=57648,name="The Impossible Plan",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. Draka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.",objectivesText="Report back to Draka at the Seat of the Primus.",rewardGold=772200,rewardXP=12250,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160518}},ends={{npcID=161907}},coords={x=0.506,y=0.156,source="quest_giver",zoneID=11462},questType="standard"},
[57649] = {id=57649,name="Whisper of Hope",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive. I know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them. But it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain. We will seize our victory.",objectivesText="Use Vashj's Sigil to rally survivors of the House of Eyes.",rewardGold=257400,rewardXP=8165,rewardItems={172371},starts={{npcID=164619}},ends={{npcID=160518}},coords={x=0.508,y=0.244,source="quest_giver",zoneID=11462},questType="standard"},
[57650] = {id=57650,name="Better Off Dead",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.",rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=161376,text="Enemy Troops slain"},{orderIndex=1,type=0,amount=5,objectID=165828,text="Siege Artillery destroyed"}},worldTaskTitle="Better Off Dead",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57651] = {id=57651,name="Trouble in the Banks",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ah, be welcome in my glade, Maw Walker. You are safe here. While it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald . Perhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir .",objectivesText="Find Foreman Thorodir near the Banks of Life.",rewardGold=1230,rewardXP=175,starts={{npcID=158345}},ends={{npcID=158422}},coords={x=0.51,y=0.338,source="quest_giver",zoneID=11510},questType="standard"},
[57652] = {id=57652,name="Supplies Needed: Amber Grease",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Foreman, Our supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it. I've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right? If you happen to harvest some more, we can certainly put it to good use.",objectivesText="Collect 6 Giant Gorm Gris . Progress: Do you have something for me?",rewardGold=72525,rewardXP=1415,rewardItems={172221},starts={{npcID=348747}},ends={{npcID=165382}},coords={x=0.469,y=0.277,source="quest_giver",zoneID=11510},questType="standard"},
[57653] = {id=57653,name="Unsafe Workplace",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You've returned just in time! Fae are in danger! It seems our actions have enraged the gorm. They are even more aggressive than they were before! While some fae were able to evacuate, there are still many who are trapped down there. Take this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.",objectivesText="Heal 10 wounded sylvar in the Banks of Life.",rewardGold=386100,rewardXP=1415,rewardItems={172950},starts={{npcID=158422}},ends={{npcID=158422}},coords={x=0.466,y=0.294,source="quest_giver",zoneID=11510},questType="standard"},
[57655] = {id=57655,name="Supplies Needed: More Husks!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor. They've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection.",objectivesText="Collect 6 Treated Gorm Husks . Progress: What's that you have there?",rewardGold=386100,rewardXP=1415,rewardItems={172218},starts={{npcID=336415}},ends={{npcID=165382}},coords={x=0.475,y=0.264,source="quest_giver",zoneID=11510},questType="standard"},
[57656] = {id=57656,name="Gifts of the Forest",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="These gorm have gone out of control! We need to stop them. I have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual. Take these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.",objectivesText="Collect 3 Culexwood Branches. Progress: We need that lure for my clever plan. It's very clever, you're going to love it.",rewardGold=386100,rewardXP=1415,rewardItems={172512,172517},starts={{npcID=158489}},ends={{npcID=158489}},coords={x=0.48,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[57657] = {id=57657,name="Tied Totem Toter",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Hope you've caught your breath. The totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it! We need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds. Let Thorodir know when you're done. I will let him know the plan.",objectivesText="Lure 30 gormlings to the wrangler in the Banks of Life.",rewardGold=386100,rewardXP=1415,starts={{npcID=158489}},ends={{npcID=158422}},coords={x=0.48,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[57658] = {id=57658,name="The Final Leg",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11510,mapID=1565,description="Please, I must get to Glitterfall Basin. I thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest. I am too close to fall here. The Lady herself invited me to come join her. She said I would be safe. Can you take me to her?",objectivesText="Deliver Windchaser to Glitterfall Basin.",rewardGold=128700,rewardXP=710,questType="standard"},
[57660] = {id=57660,name="The Grove of Creation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand. You have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought. The Lady of the Falls is droman there. She will know where you can best help!",objectivesText="Speak with the Lady of the Falls in Glitterfall Basin.",rewardGold=25740,rewardXP=175,starts={{npcID=160121}},ends={{npcID=158345}},coords={x=0.628,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[57661] = {id=57661,name="Silk Shortage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up! We are in desperate need for fresh silk. Our main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle , and see what the holdup is!",objectivesText="Find Lillythistle in the Gossamer Cliffs.",rewardGold=25740,rewardXP=1020,starts={{npcID=158556}},ends={{npcID=159270}},coords={x=0.484,y=0.504,source="quest_giver",zoneID=11510},questType="standard"},
[57670] = {id=57670,name="Unbeelievable Quality",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9042,mapID=942,description="<Now that your harvester has matured, the Honeyback hive is creating additional honey. Someone in Brennadam could certainly find a use for this honey.>",objectivesText="Take the Collected Tidebloom Honey to \"Nasty\" Buck in Brennadam. Provided item:",rewardGold=234000,rewardItems={159847},ends={{npcID=138221}},coords={mapID=942,source="quest_giver",x=0.586,y=0.704},questType="standard"},
[57676] = {id=57676,name="The Things That Haunt Us",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="As you will soon learn, a ritual cleansing can be a... painful process. In most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances. However... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion. I fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.",objectivesText="Slay 12 memories. Progress: Is it done?",rewardGold=236340,rewardXP=1415,starts={{npcID=165107}},ends={{npcID=165107}},coords={x=0.482,y=0.726,source="quest_giver",zoneID=10534},questType="standard"},
[57677] = {id=57677,name="A Soulbind In Need",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other. That he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit. I am bound by this law... but you are not. Please bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.",rewardGold=257400,rewardXP=1415,rewardItems={175623,175624,175625,175626},rewardChoices={175624,175626,175625,175623},starts={{npcID=165107}},ends={{npcID=165112}},coords={x=0.482,y=0.726,source="quest_giver",mapID=1533},questType="standard"},
[57686] = {id=57686,name="The Eternal Traveler",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=14838,mapID=47,description="Hail, mortal. For untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon. The power of Death is on the rise. The veil weakens between your world and the Shadowlands. When a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes. Bring these to me, that I might study them... to both our benefits.",objectivesText="Gather Echoes of Mortality from living creatures. Progress: One can glean so much knowledge from the mortal realm.",rewardGold=702000,rewardXP=10225,rewardItems={172075,172076,172077,172078,172079,172080,172081,172082,172083,172954},starts={{npcID=158635}},ends={{npcID=158635}},coords={x=0.736,y=0.47,source="quest_giver",zoneID=10},questType="standard"},
[57689] = {id=57689,name="Prince Renathal",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1960,description="You! They say you are a Maw Walker. Well, time to put that to the test. My master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him. The rebellion failed, and Renathal was flung into the Maw . I propose you and I venture into the Maw . There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.",objectivesText="Enter the Maw to find Prince Renathal. Progress: Your fighting style lacks... finesse.",rewardGold=128700,rewardXP=710,starts={{npcID=158615}},ends={{npcID=158615}},coords={x=0.324,y=0.396,source="quest_giver",zoneID=10986},questType="standard"},
[57690] = {id=57690,name="Cages For All Occasions",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least. Come, let's find him and get out of here.",objectivesText="Find Prince Renathal .",rewardGold=127530,rewardXP=710,starts={{npcID=158649}},ends={{npcID=158645}},questType="standard"},
[57691] = {id=57691,name="A Royal Key",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="I am not about to question whatever twist of fate led you to me. Your timing could not be better. This cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there. Vanquish him and take the key. Be swift, the Jailer's eyes are always on this area.",objectivesText="Recover Renathal's Cage Key . Progress: There was an age when I knew how to pick a lock even this elaborate. Sadly that was so long ago I seem to have fallen out of practice.",rewardGold=510120,rewardXP=1770,rewardItems={172446},starts={{npcID=158645}},ends={{npcID=158645}},coords={x=0.346,y=0.186,source="quest_giver",zoneID=11400},questType="standard"},
[57693] = {id=57693,name="Torghast, Tower of the Damned",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13400,mapID=1543,description="My allies were taken into the Tower of the Damned, and so we must follow. I do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that. Come, let us find our way to one of the most dangerous towers in all of existence.",objectivesText="Recover Renathal's Allies from Torghast, Tower of the Damned.",rewardGold=514800,rewardXP=1770,rewardItems={175731},rewardChoices={175731},starts={{npcID=158645}},ends={{npcID=162688}},coords={x=0.346,y=0.186,source="quest_giver",zoneID=11400},questType="standard"},
[57694] = {id=57694,name="Refuge of Revendreth",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1699,description="Sinfall is more than a ruin. It was once a place of dark magic and experimentation. When the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict. But first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.",objectivesText="Gather your allies.",rewardGold=128700,rewardXP=710,starts={{npcID=162688}},ends={{npcID=162688}},coords={x=0.258,y=0.566,source="quest_giver",zoneID=10986},questType="standard"},
[57709] = {id=57709,name="The Aspirant's Crucible",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have given Kalisthene's words some thought. If you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible. It is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis. Word of your arrival has likely spread. We will not keep them waiting. Take my steed, and go in service.",objectivesText="Ride Theonara to Aspirant's Crucible.",rewardGold=23635,rewardXP=175,starts={{npcID=165107}},ends={{npcID=158807}},coords={x=0.482,y=0.726,source="quest_giver",zoneID=10534},questType="standard"},
[57710] = {id=57710,name="A Life of Service",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Curious. You are unlike any aspirant that has come before, that much is certain. You will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us. Simply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.",objectivesText="Witness memories of your past life. Progress: Such a display is certain to raise our spirits.",rewardGold=236340,rewardXP=1415,rewardItems={173344,173797},rewardChoices={173344},starts={{npcID=158807}},ends={{npcID=158807}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57711] = {id=57711,name="A Forge Gone Cold",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have seen firsthand that you are a most capable soul. Kleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same. There is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again. My helper, whom you have met before, can elaborate on our needs. You will find Sika near the forge. I will follow shortly.",objectivesText="Speak to Sika .",rewardGold=25740,rewardXP=175,starts={{npcID=158807}},ends={{npcID=166577}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57712] = {id=57712,name="Suggested Reading",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Greetings. You must be the new aspirant everyone is talking about. I thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library. Aspirant Leda was the last to hold \" Worlds Beyond Counting .\" Aspirant Ikaran has yet to return \" The Infinite Treatises .\" It seems \" Bear Witness: The Watcher's Code \" went missing some time ago. I would search the village. Once returned, you can read them at your leisure.",objectivesText="Retrieve \" The Infinite Treatises \", \" Worlds Beyond Counting \", and \" Bear Witness: The Watcher's Code .\" Progress: Did you find the scrolls I suggested?",rewardGold=2250,rewardXP=1060,rewardItems={173023,173024,173025},starts={{npcID=157138}},ends={{npcID=157138}},coords={x=0.554,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57713] = {id=57713,name="The Work of One's Hands",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Too long have my hands been idle! Forgelite Sophone smiles warmly at you.> You cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor. It will not be an extravagant affair, but through good works we grow to know ourselves better. I will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed. What do you say?",objectivesText="Assist Forgelite Sophone in crafting a piece of armor. Progress: There is no greater pleasure than creating something from nothing.",rewardGold=257400,rewardXP=1415,rewardItems={173317,173318,173319,173320},rewardChoices={173317,173318,173319,173320},starts={{npcID=158807}},ends={{npcID=158807}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57714] = {id=57714,name="Assessing Your Spirit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="It is clear to all that you are indeed a skilled combatant. There is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos . Consider this a test of your spirit. If you can withstand this trial, then I will deem you ready for what lies ahead.",objectivesText="Challenge Athanos . Progress: < Kleia watches you impassively.>",rewardGold=236340,rewardXP=1415,rewardItems={173325,173326,173327,173328},rewardChoices={173327,173325,173328,173326},starts={{npcID=158862}},ends={{npcID=158862}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[57715] = {id=57715,name="The Archon's Answer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.",objectivesText="Speak to Kalisthene .",rewardGold=514800,rewardXP=1770,starts={{npcID=158862}},ends={{npcID=156217}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[57716] = {id=57716,name="A Wayward Disciple?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you. I sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty. Disciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north. Please, seek him out and ensure that he is not injured or in peril.",objectivesText="Locate Disciple Nikolon . Progress: Have you located Disciple Nikolon ?",rewardGold=236340,rewardXP=1415,rewardItems={173340,173341,173342,173343},rewardChoices={173341,173343,173342,173340},starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[57717] = {id=57717,name="Step Back From That Ledge, My Friend",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="This disciple... such emotion... Eridia stares at Nikolon for a long moment.> Rarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene. There is no time to lose. Come. I will instruct you. ... I only hope we are not too late.",objectivesText="Assist Eridia in cleansing Disciple Nikolon.",rewardGold=117300,rewardXP=1770,starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[57719] = {id=57719,name="Dangerous Discourse",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Eridia will be interested in these.>",objectivesText="Collect 6 Dark Sermons . Progress: We must defend the temple, <name>.",rewardGold=236340,rewardXP=1415,rewardItems={171215},starts={{npcID=344726}},ends={{npcID=159762}},coords={x=0.6,y=0.737,source="quest_giver",zoneID=10534},questType="standard"},
[57722] = {id=57722,name="Empty Stables",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,description="Just look at the stables, ! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct. You must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable. When we have enough rams, the ram rider commander will be notified. With your help, the cavalry will be reborn!",objectivesText="Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture. Progress: Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!",rewardCurrencies={{id=1166,amount=2},{id=1166,amount=5}},starts={{npcID=158863}},ends={{npcID=158863}},questType="standard"},
[57723] = {id=57723,name="Empty Stables",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="The war in the valley has taken its toll on our soldiers. We must revitalize our forces! If we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle. Take this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable. When we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.",objectivesText="Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master . Speak with the Frostwolf Stable Master to earn credit for the capture. Progress: Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!",rewardCurrencies={{id=1166,amount=2},{id=1166,amount=5}},starts={{npcID=158864}},ends={{npcID=158864}},questType="standard"},
[57724] = {id=57724,name="Securing Sinfall",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="They're all still active... The stoneborn, the gargon, the stone fiends... All of 'em! Don't got much time. They're always watching. Breakfist points up.> Vulca told me to follow that big beam of Light in the sky. Goes to a tower guarded by a big old brute, though. Couldn't get in.",rewardGold=514800,rewardXP=1770,rewardItems={177635,177636,177637,177638,177639,177641,177642,177643,177644,184320,184326},rewardChoices={177642,177641,177643,177639,177644,177638,177637,177635,177636,184326,184320},starts={{npcID=169105}},ends={{npcID=158716}},coords={x=0.304,y=0.456,source="quest_giver",mapID=1525},questType="standard"},
[57727] = {id=57727,name="Stonevigil Unrest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Greetings, . I'm sure you've met my associate, Baroness Draka. I have recruited her to help us with the growing threat of the Tithelord. His involvement with the Maldraxxi renegades is troubling. One conspiracy begets another. So I recruited Draka to help us end it. We must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.",objectivesText="Meet Prince Renathal and Baroness Draka at Stonevigil Overlook.",rewardGold=25740,rewardXP=1020,starts={{npcID=158653}},ends={{npcID=167380}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[57729] = {id=57729,name="To the Estate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="A window of opportunity has presented itself to us, . With his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts. His base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced. We will meet you there.",objectivesText="Meet Prince Renathal at The Caretaker's Manor.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167620}},ends={{npcID=167689}},coords={x=0.616,y=0.696,source="quest_giver",zoneID=10413},questType="standard"},
[57730] = {id=57730,name="Zinfizzlex's Portable Shredder Unit",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10458,description="I'm as anxious as you are to try out my portable shredder unit, , but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.",objectivesText="Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...",rewardItems={17410},rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13377}},ends={{npcID=13377}},questType="pvp"},
[57731] = {id=57731,name="Zinfizzlex's Portable Shredder Unit",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=10458,description="I'm as anxious as you are to try out my portable shredder unit, , but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.",objectivesText="Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...",rewardItems={17384},rewardCurrencies={{id=1166,amount=10}},starts={{npcID=13377}},ends={{npcID=13377}},questType="pvp"},
[57766] = {id=57766,name="War with the Horde",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1637,mapID=85,description="Good to see you've received proper training as a . We'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers. King Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job. Before you meet him, let me get get you caught up on what has been happening so far.",objectivesText="Speak with Captain Garrick to find out what is happening between the Horde and Alliance.",rewardGold=25740,rewardXP=175,questType="standard"},
[57771] = {id=57771,name="An Unwelcome Incursion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed. There is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well. The incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone. Take this. I stole it from one of the guards earlier.",objectivesText="Drain anima from 12 Stonevigil stoneborn. Then, refuel the anima well in the town center.",rewardGold=257400,rewardXP=8165,rewardItems={180947},starts={{npcID=167381}},ends={{npcID=167381}},coords={x=0.562,y=0.666,source="quest_giver",zoneID=10413},questType="standard"},
[57772] = {id=57772,name="Fangs and Minds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The denizens of Stonevigil have been wrung dry by the Tithelord's greed. While some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down. Prince Renathal hands you a heavy scroll dripping with anima.> Go, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.",objectivesText="Use Renathal's Decree to inspire 8 Stonevigil Citizens .",rewardGold=257400,rewardXP=8165,rewardItems={178213},starts={{npcID=167380}},ends={{npcID=167380}},coords={x=0.562,y=0.666,source="quest_giver",zoneID=10413},questType="standard"},
[57778] = {id=57778,name="The Maldraxxian Job",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion. Meet with her and the other Eyes at Nurakkir. Do what must be done.",objectivesText="Meet with Whisperer Vyn at Nurakkir.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=160518}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[57787] = {id=57787,name="Keep to the Path",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you. Just stay on the path and you won't be eaten. Probably. See you soon!",objectivesText="Continue down the road toward Tirna Vaal. Progress: Hey! You survived!",rewardGold=245700,rewardXP=1415,starts={{npcID=170533}},ends={{npcID=169031}},coords={x=0.656,y=0.278,source="quest_giver",zoneID=11510},questType="standard"},
[57816] = {id=57816,name="Dreamweaver",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be. Dreamweaver 's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care. Calm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.",objectivesText="Speak with Dreamweaver in the Tranquil Pools.",rewardGold=24805,rewardXP=175,starts={{npcID=158487}},ends={{npcID=169116}},coords={x=0.634,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[57818] = {id=57818,name="Nothing Goes to Waste",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The gormlings are industrious creatures. Naturally, they are our source of gorm gris. Gormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly... . I digress. Gormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. Take that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!",objectivesText="Collect the Depleted Wildseed , place it in the gormling pen, and coax gormlings to eat it. Progress: Have you fed the gormlings?",rewardGold=96525,rewardXP=355,rewardItems={172953},starts={{npcID=158969}},ends={{npcID=158969}},coords={x=0.648,y=0.388,source="quest_giver",zoneID=11510},questType="standard"},
[57824] = {id=57824,name="Collection Day",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Now, we can collect the gorm gris for Guardian Kota! Once the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris! My Gormherd Branch should encourage them to do this safely. Go on, give it a try on good ol' Gloober first. What has me worried is how the other gormlings might behave. They have been acting so strangely lately!",objectivesText="Use the Gormherd Branch on Gloober , then collect gorm gris from the Gorged Gormlings . Progress: I wonder what would happen if I overcharged the Gormherd Branch ... would that be more efficient? Or would it make things explode? ... probably explode.",rewardGold=96525,rewardXP=355,rewardItems={172955,173268},starts={{npcID=158969}},ends={{npcID=158969}},coords={x=0.648,y=0.388,source="quest_giver",zoneID=11510},questType="standard"},
[57825] = {id=57825,name="Delivery for Guardian Kota",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This is most disturbing, indeed. The gorm are just too... wild, now! I wonder if the drought is making everything delicious to them, and that is why. This isn't enough gorm gris, either. And I do not want to disappoint Kota.. But, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her. Would you take this gorm gris to her for me, please?",objectivesText="Deliver the gorm gris to Guardian Kota in Tirna Vaal. Provided item:",rewardGold=25740,rewardXP=175,rewardItems={173268,175741},rewardChoices={175741},starts={{npcID=158969}},ends={{npcID=158921}},coords={x=0.648,y=0.388,source="quest_giver",zoneID=11510},questType="standard"},
[57850] = {id=57850,name="Storied Partnerships",level=1,requiredLevel=1,faction="none",expansion=8,rewardCurrencies={{id=1166,amount=200}},questType="standard"},
[57852] = {id=57852,name="Dungeon Adventure",level=1,requiredLevel=1,faction="none",expansion=8,rewardCurrencies={{id=1166,amount=300}},questType="standard"},
[57853] = {id=57853,name="Battleforged Team",level=1,requiredLevel=1,faction="none",expansion=8,rewardItems={137642},questType="standard"},
[57860] = {id=57860,name="How to Become Forsworn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power. Their numbers are far too great and we are no match. Perhaps there is another way? A small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.",objectivesText="Collect 3 Forsworn Uniform Pieces and a Quartermaster's Insignia from within Kalliope's Rest. Progress: Do you have everything we need to make a disguise?",rewardGold=386100,rewardXP=8165,rewardItems={173029,175277},starts={{npcID=159248}},ends={{npcID=159248}},coords={x=0.366,y=0.376,source="quest_giver",zoneID=10534},questType="standard"},
[57861] = {id=57861,name="Just Act Natural",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however. The most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it. I am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.",objectivesText="Find Artificer Ligiea farther into Kalliope's Rest.",rewardGold=96525,rewardXP=2040,starts={{npcID=159248}},ends={{npcID=159272}},coords={x=0.366,y=0.376,source="quest_giver",zoneID=10534},questType="standard"},
[57865] = {id=57865,name="Ages-Echoing Wisdom",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack! Most of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe. Each elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald .",objectivesText="Locate Elder Gwenna, Elder Finnan, and Groonoomcrooek.",rewardGold=386100,rewardXP=1415,starts={{npcID=158345}},ends={{npcID=158345}},coords={x=0.51,y=0.338,source="quest_giver",zoneID=11510},questType="standard"},
[57866] = {id=57866,name="Idle Hands",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="If you want my help then you are going to need to help me first. There is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands. Go there and teach them a lesson. If they will not flee, then slay them on the spot!",objectivesText="Slay 12 Brittlebark invaders in the Growthworks.",rewardGold=386100,rewardXP=1415,starts={{npcID=158345}},ends={{npcID=158345}},coords={x=0.51,y=0.338,source="quest_giver",zoneID=11510},questType="standard"},
[57867] = {id=57867,name="The Sweat of Our Brow",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ah, an outsider! You are perfect for this task. The spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers! Like our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd. Good luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!",objectivesText="Disarm 6 trapped tools.",rewardGold=386100,rewardXP=1415,rewardItems={177161,177162,177163},starts={{npcID=160045}},ends={{npcID=158345}},coords={x=0.538,y=0.276,source="quest_giver",zoneID=11510},questType="standard"},
[57868] = {id=57868,name="Craftsman Needs No Tools",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oh, I am quite all right! There's just one little thing.... One of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me. Please, I cannot even think about building anything without it. Do keep an eye out for it, will you?",objectivesText="Find Finnan's Lucky Mallet . Progress: It is small, and quite lucky. I am sure you will know it when you see it.",rewardGold=386100,rewardXP=1415,rewardItems={173150},starts={{npcID=159427}},ends={{npcID=159427}},coords={x=0.558,y=0.234,source="quest_giver",zoneID=11510},questType="standard"},
[57869] = {id=57869,name="Spirit-Gathering Labor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You are not like the others. The waters here carry deep power. Power most have forgotten. But the tirnenn forget very little. Power flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels. Search for the vessels beneath the falls. Collect the power.",objectivesText="Collect 6 River Sediment . Progress: Drip, drip, go the falls. Drop, drop, goes the power. Power of the earth.",rewardGold=386100,rewardXP=1415,rewardItems={173187},starts={{npcID=159428}},ends={{npcID=159428}},coords={x=0.564,y=0.292,source="quest_giver",zoneID=11510},questType="standard"},
[57870] = {id=57870,name="The Games We Play",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Do not worry about me. We have a bigger problem. I heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves. I have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.",objectivesText="Win the game of wits by using emotes to correctly answer the Playful Trickster's riddles.",rewardGold=386100,rewardXP=1415,starts={{npcID=159465}},ends={{npcID=159465}},coords={x=0.59,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[57871] = {id=57871,name="Outplayed",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Now we can strike down their leader, friend. It just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction. While you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.",objectivesText="Defeat Wicked Wort .",rewardGold=772200,rewardXP=1770,rewardItems={173355,183849,183850},rewardChoices={183850,183849},starts={{npcID=159465}},ends={{npcID=158345}},coords={x=0.59,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[57872] = {id=57872,name="Bring More Friends!",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11510,mapID=1565,description="This is only the beginning, friend. I must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here. I have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place. She was last seen near Tirna Fein to the west. Please let her know the way is clear.",objectivesText="Locate Roriel.",rewardGold=128700,rewardXP=710,questType="standard"},
[57873] = {id=57873,name="Word from Orsis",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="As you can see, , we have our hands full here dealing with these disgusting bugs. Our caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently. I've sent a patrol toward Orsis to investigate; they are past due for a report back. Can I ask you to check in on them for me?",objectivesText="Investigate the situation in Orsis.",rewardGold=117000,rewardXP=3410,starts={{npcID=159544}},ends={{npcID=154958}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="standard"},
[57875] = {id=57875,name="Mark of Humility",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Quartermaster, you've arrived. Those fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope. Our research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages. Go figure out the problem and get inside that cave. We need its mark to open the final vault.",objectivesText="Obtain the Mark of Humility from within the First Chamber of Kalliope. Progress: Have you acquired the mark?",rewardGold=96525,rewardXP=2040,rewardItems={175754},starts={{npcID=159272}},ends={{npcID=159272}},coords={x=0.432,y=0.384,source="quest_giver",zoneID=10534},questType="standard"},
[57876] = {id=57876,name="The End of the Beginning",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1525,description="I knew Denathrius had hoarded anima, but this... this is beyond imagining. The Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall. We must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone. Return to Oribos with Draven and speak to the Honored Voice, Tal-Inara . Tell her what you have seen this day and implore her to action.",objectivesText="Speak with the Voice of the Arbiter, Tal-Inara , in Oribos .",rewardGold=128700,rewardXP=4085,starts={{npcID=165557}},ends={{npcID=165557}},coords={x=0.502,y=0.284,source="quest_giver",zoneID=10413},questType="standard"},
[57877] = {id=57877,name="The Looming Dark",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="It is good you have returned safely from Revendreth, . We sensed a betrayal that has shifted the infinite threads of fate. The Maw surges with power. We must know the cause.",objectivesText="Reveal the Jailer's plan. Progress: As the bearer of this news, you must bear this burden as well.",rewardGold=128700,rewardXP=4085,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[57878] = {id=57878,name="Choosing Your Purpose",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose. All the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice. The time has come for you to take a side. Speak to your allies. Then make your choice at the map of the Shadowlands before me.",objectivesText="Speak to the Covenants. Decide how your path is entwined with the Purpose. Progress: Have you made your decision yet?",rewardGold=128700,rewardXP=4085,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[57880] = {id=57880,name="An Estate Within the Old Gate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I believe I know how we can obtain the Countess's medallion and avoid making any new enemies. Before being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. If the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. Take this note to my trusted butler, Bogdan . He will provide whatever assistance you need.",objectivesText="Deliver Theotar's Note to Bogdan within the Old Gate. Progress: What is this? A note from the Duke?",rewardGold=25740,rewardXP=1020,rewardItems={173158},starts={{npcID=161979}},ends={{npcID=159513}},coords={x=0.5,y=0.19,source="quest_giver",zoneID=10986},questType="standard"},
[57881] = {id=57881,name="The Key to Rebuilding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If we plan to revive the estate, we'll first need the keys! When Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. The new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. Recover the key and we'll be on our way to rebuilding the manor.",objectivesText="Recover an Ornate Key from Redelav house staff within the Old Gate. Progress: Have you recovered the key?",rewardGold=257400,rewardXP=8165,rewardItems={173180},starts={{npcID=159513}},ends={{npcID=159513}},coords={x=0.604,y=0.4,source="quest_giver",zoneID=10413},questType="standard"},
[57882] = {id=57882,name="Reestablishing the Household",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! Others were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household. Seek them out and present this offer of employment .",objectivesText="Deliver offers of employment to Dumitra , Elena , and Florin .",rewardGold=257400,rewardXP=8165,rewardItems={174839},starts={{npcID=159513}},ends={{npcID=159513}},coords={x=0.604,y=0.4,source="quest_giver",zoneID=10413},questType="standard"},
[57884] = {id=57884,name="Reclaiming Thornhill Manor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. A vile thing, he is. It'll take us weeks to rid the estate of his stench! Hopefully, you can rid us of him in a much timelier fashion. I'll gather the rest of the staff and together we can reclaim Thornhill Manor.",objectivesText="Kill Viscount Nicolae and reclaim Thornhill Manor. Progress: I cannot stand the thought of someone else occupying Thornhill Manor.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=159513}},ends={{npcID=159513}},coords={x=0.604,y=0.4,source="quest_giver",zoneID=10413},questType="standard"},
[57885] = {id=57885,name="A Discreet Entrance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. At least the mirror is still intact, that's what's important. You can use it to enter the Countess 's private chambers discreetly and recover the medallion. Go, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.",objectivesText="Enter the Countess 's chambers by using the ornate mirror.",rewardGold=25740,rewardXP=1020,starts={{npcID=159513}},ends={{npcID=159694}},coords={x=0.604,y=0.4,source="quest_giver",zoneID=10413},questType="standard"},
[57886] = {id=57886,name="A Meal and A Deal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. As such, let us share a meal and speak of the matters at hand. I believe there's a way in which we can both get what we want.",objectivesText="Enjoy The Countess 's hospitality while listening to her proposal. Progress: Please, enjoy my hospitality.",rewardGold=128700,rewardXP=4085,starts={{npcID=159694}},ends={{npcID=159694}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57887] = {id=57887,name="Killing the Messenger",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I make it my business to know what is going on within my district. Traditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. A venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good. Find this courier and recover whatever missives they might be carrying.",objectivesText="Recover a Treasonous Missive from a Redelav Courier. Progress: Has it been done?",rewardGold=514800,rewardXP=10205,rewardItems={173285},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=159694}},ends={{npcID=159694}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57888] = {id=57888,name="An Invitation to Treachery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. All we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? Head into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.",objectivesText="Deliver invitations to each of the noble houses within the Redelav District.",rewardGold=257400,rewardXP=8165,rewardItems={173358},starts={{npcID=159694}},ends={{npcID=159694}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57889] = {id=57889,name="\"Accidental\" Arson",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. We need to get rid of him, and it needs to look like an accident. Once Andrei's been dealt with, set fire to his rug and let the whole estate burn down. Andrei isn't someone you want coming into power. He's as ruthless as he is cruel.",objectivesText="Kill Lord Andrei and set fire to his estate.",rewardGold=514800,rewardXP=10205,rewardItems={180916,180917,180918,180919},starts={{npcID=159694}},ends={{npcID=159694}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57890] = {id=57890,name="Beautiful, But Deadly",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens. Well worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly. Would you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.",objectivesText="Collect 50 Duskmire Mushrooms from gardens within the Redelav District. Progress: Do you have the mushrooms?",rewardGold=257400,rewardXP=8165,rewardItems={173286},starts={{npcID=159694}},ends={{npcID=159694}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57891] = {id=57891,name="Mix, Mingle, and Meddle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. This is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. Be warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.",objectivesText="Attend the Countess 's soiree and speak with guests to uncover the traitorous house. Progress: One among my guests is the traitor. I need you to find out who.",rewardGold=257400,rewardXP=8165,rewardItems={174923},starts={{npcID=159694}},ends={{npcID=159946}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="standard"},
[57892] = {id=57892,name="Enacting Immediate Justice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="There are likely many in attendance who wish me harm. I trust you have done your job in determining which house has been working with Andrei? Once they are named, I trust you will enact immediate justice.",objectivesText="Name the traitorous house and enact justice. Progress: The traitorous house will be uncovered and swiftly dealt with.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=159946}},ends={{npcID=159946}},coords={x=0.568,y=0.286,source="quest_giver",zoneID=10413},questType="standard"},
[57893] = {id=57893,name="Neither Enemy nor Ally",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="I hope you now see the importance of the role I play. My parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. Sometimes, battles are best fought before they begin. Giving you my medallion is an example of that. We may not be allies, but we are not enemies, either.",objectivesText="Deliver the medallion to Prince Renathal in Sinfall. Progress: Have you secured the medallion?",rewardGold=772200,rewardXP=12250,rewardItems={173287},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=159946}},ends={{npcID=158653}},coords={x=0.568,y=0.286,source="quest_giver",zoneID=10413},questType="standard"},
[57895] = {id=57895,name="Elysian Hold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="One more step yet remains before your initiation is complete. You must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training. Once there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.",objectivesText="Travel with Polemarch Adrestes to Elysian Hold.",rewardGold=25740,rewardXP=1020,starts={{npcID=168906}},ends={{npcID=160037}},coords={x=0.584,y=0.288,source="quest_giver",zoneID=10534},questType="standard"},
[57897] = {id=57897,name="Dangerous to Go Alone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="There is one last thing you must do before we can act to clean up Denathrius's chaos. You must have a soulbind. All kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself. Soulguide Daelia will guide you in this process. Seek her out in the chamber below.",objectivesText="Speak with Soulguide Daelia in the Sanctum of Binding.",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=160212}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[57898] = {id=57898,name="Soul Meets Body",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.",objectivesText="Complete the soulbinding ritual. Progress: Take your time. This is a significant step in your journey to ascension.",rewardGold=128700,rewardXP=4085,starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[57899] = {id=57899,name="More Work?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your world has a saying that \"you cannot be in two places at once.\" Without a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct. Christen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.",objectivesText="Activate the Command Table.",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=160389}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[57900] = {id=57900,name="Across the Shadowlands",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity. However, our eternal charge does not end in Oribos. There are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in. Consider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.",objectivesText="Use the Command Table to start an adventure. Progress: Good things are worth waiting for.",rewardGold=128700,rewardXP=4085,starts={{npcID=160389}},ends={{npcID=160389}},coords={x=0.648,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[57901] = {id=57901,name="All That Remains",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above. Capheus , one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most. Given the great drought of anima that plagues us if anyone could use assistance, it would be her.",objectivesText="Activate the Anima Conductor. Progress: Yes, yes, you! You can help!",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=158773}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[57903] = {id=57903,name="Power in the Sky",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="This device you see here can be used to send anima to our temples and aid our people. As each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.",objectivesText="Use the Anima Conductor to channel anima to a location in Bastion. Progress: Does the anima flow?",rewardGold=128700,rewardXP=4085,starts={{npcID=158773}},ends={{npcID=158773}},coords={x=0.382,y=0.676,source="quest_giver",zoneID=11012},questType="standard"},
[57904] = {id=57904,name="Our Eternal Charge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together. For now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. Go in service, .",objectivesText="Return to Polemarch Adrestes .",rewardGold=25740,rewardXP=1020,rewardItems={174292,177053,178156,179942},rewardCurrencies={{id=1822,amount=2}},starts={{npcID=160212}},ends={{npcID=160037}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[57905] = {id=57905,name="A Unique Opportunity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly. Soulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more. You should pay her a visit within the Sanctum of Binding to see if you might be of aid.",objectivesText="Speak to Soulguide Daelia in the Sanctum of Binding.",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=160212}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[57908] = {id=57908,name="The True Crucible Awaits",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I confess, . I had little hope when you first arrived. Kleia is convinced that your presence here is a sign of things finally improving in Bastion . I was... skeptical. What you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most. You are not most. Kleia and Pelagos will tell you more. They await you near the sparring grounds.",objectivesText="Speak to Kleia and Pelagos in Aspirant's Crucible.",rewardGold=23635,rewardXP=175,starts={{npcID=158807}},ends={{npcID=158862}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[57909] = {id=57909,name="Assessing Your Stamina",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure. Look around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not. Your task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation. Help them find focus, and they shall help you do the same. Return to me when you feel ready to continue.",objectivesText="Participate in 8 combat meditations. Progress: Trust in the process, <name>.",rewardGold=236340,rewardXP=1415,starts={{npcID=158861}},ends={{npcID=158861}},coords={x=0.516,y=0.81,source="quest_giver",zoneID=10534},questType="standard"},
[57912] = {id=57912,name="Baron of the Chosen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire. The House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy. Margrave Krexus trusts your might. No doubt you will have need of it.",objectivesText="Meet with Baron Vyraz at the Spearhead.",rewardGold=25740,rewardXP=175,starts={{npcID=168381}},ends={{npcID=159894}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=11462},questType="standard"},
[57914] = {id=57914,name="Mark of Knowledge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads. I need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword. Get me that mark, quartermaster!",objectivesText="Obtain the Mark of Knowledge . Progress: Did you bring the mark? If not, then why are we speaking?",rewardGold=96525,rewardXP=2040,rewardItems={175755},starts={{npcID=159272}},ends={{npcID=159272}},coords={x=0.432,y=0.384,source="quest_giver",zoneID=10534},questType="standard"},
[57915] = {id=57915,name="Search for Survivors",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The bugs came from everywhere... There wasn't any time to react. Many of my friends died where they stood, while others tried to fight with our meager tools. I'm a coward. I fled in the commotion instead of trying to help. Now, here I am, out of food and water and too scared to look for survivors. Please, I beg you to help anyone you find left alive in Orsis...",objectivesText="Check 8 Wastewanders in Orsis.",rewardGold=234000,rewardXP=6815,starts={{npcID=154958}},ends={{npcID=159560}},coords={x=0.408,y=0.384,source="quest_giver",zoneID=10833},questType="standard"},
[57918] = {id=57918,name="The Absolution of Souls",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Do you not yet understand the purpose of Revendreth , Maw Walker? The souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny. That is true under the best of circumstances. Currently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances. We must return to the Halls of Atonement and enforce order.",objectivesText="Meet the Accuser at Absolution Crypt.",rewardGold=25740,rewardXP=175,starts={{npcID=165291}},ends={{npcID=160116}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="standard"},
[57919] = {id=57919,name="An Abuse of Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The souls have suffered tremendously under the Lord Chamberlain. We venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not. The Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence! Use these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.",objectivesText="Subjugate the Abused Soul. Progress: Every lost soul is a tragedy.",rewardGold=514800,rewardXP=1770,starts={{npcID=160116}},ends={{npcID=160116}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="standard"},
[57920] = {id=57920,name="The Proper Souls",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We must save as many souls as we can from the fate we have just witnessed. Search the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement. Together, we will make certain that each soul is appropriately processed and cared for.",objectivesText="Subjugate 4 Fugitive Souls and deliver them to the Accuser . Progress: If even one soul can be saved, it is worth it.",rewardGold=514800,rewardXP=1770,starts={{npcID=160116}},ends={{npcID=160139}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="standard"},
[57921] = {id=57921,name="The Proper Tools",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly. I can mask your garish appearance, but you must acquire the necessary ritual tools on your own. Requisition them from the depraved venthyr serving the Lord Chamberlain nearby.",objectivesText="Collect Venthyr Ritual Robes , Dagger, and Tome. Progress: We will do this the proper way.",rewardGold=514800,rewardXP=1770,rewardItems={173695,173696,173697},starts={{npcID=160116}},ends={{npcID=160139}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="standard"},
[57922] = {id=57922,name="The Proper Punishment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants. These avowed ritualists have been working covertly to preserve the integrity of the halls. They report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls. Give him the reward he deserves.",objectivesText="Kill Fata the Soulflayer .",rewardGold=786300,rewardXP=2125,starts={{npcID=160116}},ends={{npcID=160139}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="standard"},
[57923] = {id=57923,name="Ritual of Absolution",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives. The soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual. The Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima. We will perform the ritual ourselves, and hurry these souls along their journey.",objectivesText="Help the Accuser complete the ritual of absolution. Progress: Absolution is where mercy meets justice.",rewardGold=257400,rewardXP=1415,starts={{npcID=160139}},ends={{npcID=160163}},coords={x=0.706,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[57924] = {id=57924,name="Ritual of Judgment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="After all rituals of absolution are complete, each soul must face its final judgment in Revendreth . There are three potential verdicts: If proven unworthy, it is condemned to the Maw for eternity. If fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination. Our most sacred ritual, the judgment, determines this fate. One such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.",objectivesText="Participate in the ritual of judgment.",rewardGold=193050,rewardXP=1060,starts={{npcID=160163}},ends={{npcID=160294}},coords={x=0.72,y=0.462,source="quest_giver",zoneID=10413},questType="standard"},
[57925] = {id=57925,name="Archivist Fane",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual. Despite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling. Archivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls. I must tend to Gresit. He has much to learn.",objectivesText="Introduce yourself to Archivist Fane .",rewardGold=25740,rewardXP=175,starts={{npcID=160294}},ends={{npcID=160248}},coords={x=0.742,y=0.496,source="quest_giver",zoneID=10413},questType="standard"},
[57926] = {id=57926,name="The Sinstone Archive",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You said Inquisitor Traian oversaw the ritual? Archivist Fane searches the massive archives in this chamber.> We archivists maintain strict records of every soul that passes through these halls. Or at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\" Archivist Fane rolls his eyes.> I don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail. Help me complete my archives, and I'll get you any sinstone you need.",objectivesText="Collect 100 Sinstone Records . Progress: Sinstones are the most powerful weapon in Revendreth .",rewardGold=514800,rewardXP=1770,rewardItems={173733},starts={{npcID=160248}},ends={{npcID=160248}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[57927] = {id=57927,name="Rebuilding Temel",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Revendreth demands penance from all, and it would appear that even you are not exempt. Cryptkeeper Kassir grins.> Do not fear, I have no intention of exacting revenge for the violence you inflicted upon me. But I cannot offer you Temel either. The Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control. His thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.",objectivesText="Collect Temel's Head , Body, and Wings. Progress: No matter how broken Temel is, I can rebuild him.",rewardGold=514800,rewardXP=1770,rewardItems={173737,173738,173739},starts={{npcID=163073}},ends={{npcID=163073}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="standard"},
[57928] = {id=57928,name="Atonement Crypt Key",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>",objectivesText="Open an Atonement Crypt.",rewardGold=193050,rewardXP=1060,ends={{npcID=163073}},coords={mapID=1525,source="quest_giver",x=0.702,y=0.562},questType="standard"},
[57929] = {id=57929,name="Hunting an Inquisitor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion. But now that we have access to Inquisitor Traian 's sinstone from the archives, we have the power needed to break through those defenses. Locate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time. Be ready to strike.",objectivesText="Kill Inquisitor Traian . Progress: Truth, wielded properly, is a potent weapon.",rewardGold=772200,rewardXP=2125,starts={{npcID=160248}},ends={{npcID=160248}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[57931] = {id=57931,name="Phalynx Malfunction",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on. Unfortunately, last time they returned they were one fewer in number. Please search the Golden Pasture and search for the missing unit, then return it here.",objectivesText="Find Gatamatos in the Golden Pasture and return him to his pedestal in Forgefire Outpost. Progress: My phalynx units require occasional repairs to keep them operational. If one is overlooked, it may malfunction.",rewardGold=386100,rewardXP=1415,starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57932] = {id=57932,name="Resource Drain",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Usually repairs easy. Anima everywhere! Except drought means we can't just pull it from air. Other sources needed! Take this. Drain anima from cloudstriders. Not ideal, but desperate times.",objectivesText="Drain anima from Gilded Cloudstriders 5 times. Progress: Drought has big effects. Feel bad for cloudstriders.",rewardGold=386100,rewardXP=1415,rewardItems={173691},starts={{npcID=159609}},ends={{npcID=159609}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57933] = {id=57933,name="We Can Rebuild Him",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Gatamatos needs numerous repairs to meet functional standards. Upkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.",objectivesText="Aid Pelodis in repairing Gatamatos . Progress: As long as you keep your phalynx in working condition, they will obey without hesitation.",rewardGold=358020,rewardXP=1415,rewardItems={173307},starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57934] = {id=57934,name="Combat Drills",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry. I need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.",objectivesText="Kill 8 Agitated Etherwyrms in the Hall of Beasts with Gatamatos.",rewardGold=386100,rewardXP=1415,starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57935] = {id=57935,name="Laser Location",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Phalynx have precise detection mechanisms that allow for excellent scouting. In the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.",objectivesText="Bring Gatamatos to the Hall of Beasts, then direct him to locate 6 Training Gems . Progress: The technical process behind phalynx tracking and locating their targets is quite fascinating. However... you do not seem the type who is interested in the details.",rewardGold=358020,rewardXP=1415,rewardItems={173269},starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57936] = {id=57936,name="Superior Programming",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Phalynx listen to their orders. Never disobey! Larions are wild beasts. Can attack. Could eat a steward, probably! Untamed larion lives close. Has chased many stewards, very scary! Please take care of it.",objectivesText="Kill Leonid in the Hall of Beasts. Progress: Wild beasts. Terrifying! No thank you! I work with very safe phalynx.",rewardGold=358020,rewardXP=1415,rewardItems={175612,175613,175614,175615,175635,175636,175637,175638},rewardChoices={175613,175615,175614,175612,175635,175638,175637,175636},starts={{npcID=159609}},ends={{npcID=159609}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57937] = {id=57937,name="Tactical Formation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next. Formational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.",objectivesText="Aid Gatamatos in taking the correct position in three formations. Progress: A good soldier marches in order.",rewardGold=358020,rewardXP=1415,starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[57947] = {id=57947,name="Spirits of the Glen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves. But danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril. Rescue them.",objectivesText="Find Choofa in the Spirit Glen.",rewardGold=24570,rewardXP=175,starts={{npcID=158487}},ends={{npcID=159638}},coords={x=0.634,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[57948] = {id=57948,name="Nothing Left to Give",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oh no, oh no! My friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us! But we give our anima, we give! To help the groves. And we give so much... sometimes too much. I still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!",objectivesText="Restore soul shapes to Slanknen , Rury , and Awool in the Spirit Glen. Progress: Oh dear, oh dear. My friends are in trouble!",rewardGold=245700,rewardXP=1415,starts={{npcID=159638}},ends={{npcID=159639}},coords={x=0.67,y=0.322,source="quest_giver",zoneID=11510},questType="standard"},
[57949] = {id=57949,name="They Need to Calm Down",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Spriggans! Nasty spriggans. They came to the grove. They messed it all up! They took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay! Beat them up! Then use this soulweb to take back the anima. We need it! They don't!",objectivesText="Defeat Spriggans and use the Soulweb to drain them of stolen anima in Spirit Glen. Progress: Did you destroy them? Did you make them pay?",rewardGold=245700,rewardXP=1415,rewardItems={176445},starts={{npcID=159638},{npcID=159639}},ends={{npcID=159639}},coords={x=0.67,y=0.322,source="quest_giver",zoneID=11510},questType="standard"},
[57950] = {id=57950,name="Mizik the Haughty",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all. Mizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm! Get him. Get him!",objectivesText="Defeat Mizik the Haughty .",rewardGold=245700,rewardXP=1415,starts={{npcID=159639}},ends={{npcID=159638}},coords={x=0.686,y=0.352,source="quest_giver",zoneID=11510},questType="standard"},
[57951] = {id=57951,name="Souls Come Home",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="To the tree, to the tree! It is time for us to return to the grove. We have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy! I will see you there!",objectivesText="Report your success to Droman Tashmur in Tirna Vaal.",rewardGold=24570,rewardXP=175,rewardItems={173292,175656,175657,175658,175659},rewardChoices={175659,175657,175658,175656},starts={{npcID=159638}},ends={{npcID=158487}},coords={x=0.67,y=0.322,source="quest_giver",zoneID=11510},questType="standard"},
[57952] = {id=57952,name="In Need of Gorm Gris",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris. It may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect. I would like to help them out, with the resources that we are able to spare. Please, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population. Ask him for more gorm gris.",objectivesText="Seek out Master Sha'lor by the Tranquil Pools.",rewardGold=25740,rewardXP=175,starts={{npcID=158921}},ends={{npcID=158969}},coords={x=0.626,y=0.36,source="quest_giver",zoneID=11510},questType="standard"},
[57954] = {id=57954,name="Burn the Bodies",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="The bugs seem to be indiscriminately laying eggs all over the nearby corpses. They are using them as food to spawn more of those horrible things. Disgusting! We can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so. Burn the bodies and destroy those eggs!",objectivesText="Burn 10 Egg-bearing corpses.",rewardGold=234000,rewardXP=6815,rewardItems={174323},starts={{npcID=159682}},ends={{npcID=159682}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="standard"},
[57955] = {id=57955,name="To Ankhaten Harbor",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="I fear that I don't yet have the strength to ride out into the sands and face those monsters again. Ride to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing. Tell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate. We must get the word out across Uldum before our forces are further divided!",objectivesText="Find Tracker Samara in Ankhaten Harbor.",rewardGold=117000,rewardXP=3410,starts={{npcID=159560}},ends={{npcID=159682}},coords={x=0.4,y=0.452,source="quest_giver",zoneID=10833},questType="standard"},
[57956] = {id=57956,name="Wastewander Hosts",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying! Some of them are rising from the ground as putrid, bloated, hideous monstrosities. We have to stop them before they continue to bolster their ranks with our fallen. It's not a pleasant task... but I have to ask you to help me destroy them. Completely. Grab some bombs behind me, if you'd like.",objectivesText="Kill 6 Wastewander Hosts .",rewardGold=234000,rewardXP=6815,rewardItems={174325},starts={{npcID=159682}},ends={{npcID=159682}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="standard"},
[57959] = {id=57959,name="Heroic Warfront: The Battle for Darkshore",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8670,mapID=1165,description="Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor. Prepare yourselves. Battle awaits!",objectivesText="Defeat the Alliance at the Battle for Darkshore.",rewardGold=468000,rewardXP=8520,rewardItems={163528,165465,165466,165467,165468,165469,165470,165471,165472,165473,165474,165475,165476,165477,165478,165479,165480,165481,165482,165483,165484,165485,165486,165487,165488,165489,165490,165491,165492,165493,165494,165495,165496,165608,165610,165611,165613,165614,165619,165620,165621,165622,166369,166482,166551,166552,166553,166554,166561,166562,166563,166564,166573,166574,166575,166576,166762,166763,166764,166765,166802,166897},rewardCurrencies={{id=1716,amount=50},{id=1553,amount=750},{id=1803,amount=75},{id=1803,amount=375}},starts={{npcID=138949}},ends={{npcID=138949}},coords={x=0.528,y=0.944,source="quest_giver",zoneID=8670},questType="standard",packageItems={163523,163543,163524,163525,163527,163529,163530,163532,163531}},
[57960] = {id=57960,name="Heroic Warfront: The Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="We will not tolerate further Horde aggression in our territories. The night elves will not stand alone this day. Darkshore will be theirs once more. For the Alliance!",objectivesText="Defeat the Horde at the Battle for Darkshore.",rewardGold=468000,rewardXP=8520,rewardItems={164966,165433,165434,165435,165436,165437,165438,165439,165440,165441,165442,165443,165444,165445,165446,165447,165448,165449,165450,165451,165452,165453,165454,165455,165456,165457,165458,165459,165460,165461,165462,165463,165464,165623,165624,165625,165627,165628,165629,165632,165636,165637,166370,166483,166555,166556,166557,166558,166565,166566,166571,166572,166577,166578,166579,166580,166758,166759,166760,166761,166898},rewardCurrencies={{id=1717,amount=50},{id=1553,amount=750},{id=1803,amount=375},{id=1803,amount=75}},starts={{npcID=142721}},ends={{npcID=142721}},coords={x=0.66,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[57961] = {id=57961,name="Heroic: Battle for Darkshore",level=1,requiredLevel=1,faction="horde",expansion=8,questType="standard"},
[57962] = {id=57962,name="Heroic: Battle for Darkshore",level=1,requiredLevel=1,faction="alliance",expansion=8,questType="standard"},
[57964] = {id=57964,name="Revenge Is Easy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="There's still a lot of us here, trying to survive in these ruins. These constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs. The solution here requires an extensive use of violence, by you!",objectivesText="Kill 15 bonefused forces. Progress: I still see a lot of abominations walking around.",rewardGold=257400,rewardXP=8165,rewardItems={181501,181625,181626,181638,181645,181646,181647,181648,181649,181652,181653,181660,181661,181662,181663,181671,181672,181673,181674,181679,181680,181681,181682,184195,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=160523}},ends={{npcID=160523}},coords={x=0.514,y=0.162,source="quest_giver",zoneID=11462},questType="standard"},
[57966] = {id=57966,name="You Go First",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You've proven useful. So, I am going to require you to disarm the defenses of this hall. Please take care not to die too quickly. I'd like to have the spear before the end of this eon.",rewardGold=386100,rewardXP=8165,starts={{npcID=159272}},ends={{npcID=159272}},coords={x=0.432,y=0.384,source="quest_giver",mapID=1533},questType="standard"},
[57967] = {id=57967,name="Rightful Resting Place",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="You have truly proven yourself a hero in the eyes of those who are its absolute judge. I thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place. Let us meet at Elysian Hold where you can do the honors.",objectivesText="Enshrine the Spear of Kalliope in its rightful place at Elysian Hold. Progress: <The resting place of the spear lies before you.>",rewardGold=96525,rewardXP=2040,rewardItems={180452},starts={{npcID=159248}},ends={{npcID=353946}},coords={x=0.366,y=0.376,source="quest_giver",zoneID=10534},questType="standard"},
[57969] = {id=57969,name="Tend the Wounded",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="My friend, as you can see here, we are besieged by these terrible creatures. Many of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now. If you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.",objectivesText="Heal 8 Wastewander Laborers .",rewardGold=234000,rewardXP=6815,rewardItems={174326},starts={{npcID=159820}},ends={{npcID=159820}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="standard"},
[57970] = {id=57970,name="Ruinator Xok'nixx",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins. She can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down. Although the creature is occupied for now, if our warriors fall, the ruins will be lost to us. Please, make haste, with your help they can surely fell this titanic foe.",objectivesText="Kill Ruinator Xok'nixx .",rewardGold=234000,rewardXP=6815,starts={{npcID=159820}},ends={{npcID=159820}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="standard"},
[57971] = {id=57971,name="Ruins of Ammon",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10833,mapID=1527,description="These things seem to be everywhere and all at once! Either this was an organized attack, or there are far more of them than we can even comprehend. Regardless, this is bad for us... really, really bad. $p, I need you to travel to the Ruins of Ammon and find out what the situation is like over there. If they need help, please try to lend a hand!",objectivesText="Travel to the Ruins of Ammon.",rewardGold=234000,rewardXP=6815,starts={{npcID=159682}},ends={{npcID=159820}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="standard"},
[57973] = {id=57973,name="Heroic: Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",expansion=8,questType="standard"},
[57974] = {id=57974,name="Heroic: Battle for Darkshore",level=50,requiredLevel=50,faction="horde",expansion=8,questType="standard"},
[57976] = {id=57976,name="Lead By Example",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory! Meet these traitorous constructs head on. Leave none standing!",objectivesText="Kill 12 Steelskin Vanguard or Steelskin Brutalizers . Progress: What?",rewardGold=257400,rewardXP=1415,starts={{npcID=159894}},ends={{npcID=169226},{npcID=169359}},coords={x=0.392,y=0.558,source="quest_giver",zoneID=11462},questType="standard"},
[57977] = {id=57977,name="A Temple in Need",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Eridia peers down at you.> Your face is new to me. Eridia frowns.> I regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care. Do not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within. You may find me within the temple when you have given your aid.",objectivesText="Aid the disciples within the Temple of Purity. Progress: Have you lent my disciples your aid?",rewardGold=257400,rewardXP=1415,starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[57979] = {id=57979,name="Offensive Behavior",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Fine work, $p. We've advanced with minimal casualties. From this new forward position, we can strike directly at the enemy commander. The troops you rallied will join the attack. Together, we will bring this battle to a decisive end. Locate General Alver and sound the horn.",objectivesText="Kill General Alver .",rewardGold=250380,rewardXP=1415,rewardItems={175763,179923},rewardChoices={175763},starts={{npcID=169226}},ends={{npcID=169226}},coords={x=0.394,y=0.466,source="quest_giver",zoneID=11462},questType="standard"},
[57982] = {id=57982,name="Breaking Down Barriers",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it. They've secured the chamber with a soul barrier and several bile spewers. We must find a way through! Thales said he may have a suggestion.",objectivesText="Find a way past the Soul Barrier. Progress: Is the barrier down?",rewardGold=128700,rewardXP=710,starts={{npcID=165397}},ends={{npcID=165397}},coords={x=0.302,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57983] = {id=57983,name="Archon Save Us",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. The lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming... I think there are other survivors being held nearby. Can you aid me in freeing them?",objectivesText="Save the souls in the Holding Pens. Progress: Yes?",rewardGold=257400,rewardXP=1415,rewardItems={176456},starts={{npcID=160211}},ends={{npcID=160211}},coords={x=0.32,y=0.274,source="quest_giver",zoneID=11462},questType="standard"},
[57984] = {id=57984,name="The Ones in Charge",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="They have been collecting kyrian... and our corpses... for some dark purpose. Whatever they are planning, we must put a stop to it. I have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.",objectivesText="Slay Doctor Hivvil , Tabulator Hymeris , and Leacher Cvan .",rewardGold=243360,rewardXP=1415,rewardItems={175474,175475,175476,175477},rewardChoices={175477,175475,175476,175474},starts={{npcID=161060}},ends={{npcID=165397}},questType="standard"},
[57985] = {id=57985,name="Give Them a Hand",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs. We can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so. Do not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.",objectivesText="Destroy 10 Vestigial Animates . Progress: The weak make way for the strong, such is the way of Maldraxxus .",rewardGold=243360,rewardXP=1415,rewardItems={180120},starts={{npcID=165397}},ends={{npcID=165397}},coords={x=0.302,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57986] = {id=57986,name="A Burden Worth Bearing",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate. Most of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it. Take the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.",objectivesText="Help Kou and Koa retrieve 6 Lost Kyrian. Progress: Were there any left?",rewardGold=243360,rewardXP=1415,starts={{npcID=160211}},ends={{npcID=169949}},coords={x=0.32,y=0.274,source="quest_giver",zoneID=11462},questType="standard"},
[57987] = {id=57987,name="A Deadly Distraction",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside. Slaughter as many as you can. I will hunt down the masterminds behind these new production efforts.",objectivesText="15 Warstitched forces slain.",rewardGold=255060,rewardXP=1415,starts={{npcID=165397}},ends={{npcID=165397}},coords={x=0.302,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57989] = {id=57989,name="The Spear of Kalliope",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Spear of Kalliope is finally in my grasp! With it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!",objectivesText="Defeat Artificer Ligiea and earn the Spear of Kalliope . Progress: Did you find the spear?",rewardGold=386100,rewardXP=8165,rewardItems={173354},starts={{npcID=159272}},ends={{npcID=159248}},coords={x=0.432,y=0.384,source="quest_giver",zoneID=10534},questType="standard"},
[57990] = {id=57990,name="Obelisk of the Sun",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here. Our comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there. So far, our attempts to get word back to Arik have failed. However, if you can help her get one of those planes working, we might just have a chance. Hopefully they can send aid before we are overrun...",objectivesText="Locate Exterminator Zahra at the Obelisk of the Sun.",rewardGold=117000,rewardXP=3410,starts={{npcID=159820}},ends={{npcID=159920}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="standard"},
[57993] = {id=57993,name="Two of Them, Two of Us",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A construct made entirely of kyrian flesh... This betrays everything Maldraxxus stands for! We are meant to defend the Shadowlands and all within it, not slaughter and exploit them! Come, $p! We end this now!",objectivesText="Defeat Sharrex the Fleshcrafter and First Apprentice Malkrex .",rewardGold=255060,rewardXP=1415,rewardItems={175447,175448,175449,175450},rewardChoices={175449,175448,175450,175447},starts={{npcID=165397}},ends={{npcID=165575}},coords={x=0.302,y=0.238,source="quest_giver",zoneID=11462},questType="standard"},
[57994] = {id=57994,name="In The Flesh",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct! Please, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. Perhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.",objectivesText="Take control of the Soulfused Construct and escape the House of Constructs. Progress: My fallen kin...",rewardGold=257400,rewardXP=1415,starts={{npcID=165575}},ends={{npcID=160211}},coords={x=0.288,y=0.22,source="quest_giver",zoneID=11462},questType="standard"},
[58007] = {id=58007,name="Eyes on the Problem",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay. Vashj has a plan to permanently bolster our defenses. With your help, it might actually succeed. Do what you can to assist her. She seems more... agreeable toward you than she is with me.",objectivesText="Speak with Vashj and put her plan into action.",rewardGold=128700,rewardXP=4085,starts={{npcID=161907}},ends={{npcID=164619}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[58008] = {id=58008,name="All Gassed Up",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks! Saw a few canisters scattered around nearby, surely some a' them have some gas left. Was gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place. Too many here now to deal with on my own, think you'd be able to lend a hand?",objectivesText="Collect 6 Fuel Canisters . Progress: Yo, you got them fuel cans yet?",rewardGold=234000,rewardXP=6815,rewardItems={173366},starts={{npcID=159920}},ends={{npcID=159920}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="standard"},
[58009] = {id=58009,name="To the Moon",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Alright! It's time to high tail it outta here. We gotta get back to camp and tell Arik what's been going on out here as soon as possible. Head for the bomber and let's fuel 'er up. I'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!",objectivesText="Remove the Aqir threat from Obelisk of the Moon.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=159920}},ends={{npcID=159544}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="standard"},
[58011] = {id=58011,name="Bug Bites",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Margrave Stradama eagerly awaits the completion of our latest potion! However, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately... Would you please do me a favor and fetch some more? We cannot continue our work without them!",objectivesText="Collect 6 Bloated Venom Sacs . Progress: Now where did I put my venom sacs...",rewardGold=257400,rewardXP=1415,rewardItems={173368},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[58016] = {id=58016,name="Spores Galore",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="My brightest apprentice, you return to me at last! You worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared! Wherever you went is no matter. You're back now, and we have much to do! Come, my apprentice--we must fetch our ingredients first. Can you smell the spores germinating around us? We should pull some up to use in our endeavors!",objectivesText="Harvest 8 Stringy Spores.",rewardGold=243360,rewardXP=1415,starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[58022] = {id=58022,name="Finish What He Started",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Finding Sha'lor is our main priority. But there is another opportunity. Take the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm. Use it on the gorm in the burrows, and see if you can collect any of their gorm gris. Don't bother with the little ones; get the really potent stuff from the bigger gorm. Perhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.",objectivesText="Use the Gormherd Branch to collect Wild Gorm Gris from gorm in the Dusty Burrows. Progress: Have you had any luck?",rewardGold=372060,rewardXP=1415,rewardItems={173534,180543},starts={{npcID=171099}},ends={{npcID=158921},{npcID=160155}},coords={x=0.628,y=0.322,source="quest_giver",zoneID=11510},questType="standard"},
[58023] = {id=58023,name="One Big Problem",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We must go after Master Sha'lor. Tirna Vaal needs him! And I... I... I will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it. For now, see what you can find. I refuse to believe that he is gone. That monster will know the fury of a vorkai.",objectivesText="Hunt down the Gorm Matriarch . Progress: What's gotten into these gorm?",rewardGold=372060,rewardXP=1415,starts={{npcID=171099}},ends={{npcID=160155}},coords={x=0.628,y=0.322,source="quest_giver",zoneID=11510},questType="standard"},
[58024] = {id=58024,name="Burrows Away",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="<The ground has been freshly dug, and there are signs of more tunnels all over the place. Collapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>",objectivesText="Collapse Gorm Burrows in the Dusty Burrows.",rewardGold=386100,rewardXP=1415,rewardItems={173534},starts={{npcID=171195}},ends={{npcID=158921},{npcID=160155}},coords={x=0.622,y=0.3,source="quest_giver",zoneID=11510},questType="standard"},
[58025] = {id=58025,name="Queen of the Underground",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You tracked the massive gorm here to her den, and we've found Master Sha'lor. Perhaps not entirely unscathed, but he lives. That is enough. One last task remains. Let us end this.",objectivesText="Slay the Gorm Matriarch . Progress: Tirna Vaal will not be safe with that monstrosity about.",rewardGold=772200,rewardXP=1770,rewardItems={172955,173534},starts={{npcID=160155}},ends={{npcID=160155}},coords={x=0.598,y=0.344,source="quest_giver",zoneID=11510},questType="standard"},
[58026] = {id=58026,name="When a Gorm Eats a God",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal. When you get there, report to the droman what we found here. If the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.",objectivesText="Report back to Droman Tashmur in Tirna Vaal.",rewardGold=25740,rewardXP=175,rewardItems={173534,175663,175664,175665,175666},rewardChoices={175665,175663,175664,175666},starts={{npcID=160155}},ends={{npcID=158487}},coords={x=0.598,y=0.344,source="quest_giver",zoneID=11510},questType="standard"},
[58027] = {id=58027,name="Slime, Anyone?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience. Patience and slimes, of course! With the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right... Oh, listen to me--acting as if you've never concocted your own sentient being! Go on, my apprentice! The slimes are calling!",objectivesText="Craft a Plagueborn Slime in Marileth's cauldron. Progress: Go on, now! You can do it!",rewardGold=24335,rewardXP=175,rewardItems={173891},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[58031] = {id=58031,name="Applied Science",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="<What appears to be an old journal sits on Marileth's table, now mangled and missing pages. The entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house. Perhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>",objectivesText="Collect the lost pages of Marileth's journal from Plague-doused Remnants.",rewardGold=243360,rewardXP=1415,rewardItems={180235,180236,180237,180238},starts={{npcID=353645}},ends={{npcID=159930}},coords={x=0.565,y=0.572,source="quest_giver",zoneID=11462},questType="standard"},
[58036] = {id=58036,name="Hazardous Waste Collection",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion. But it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety! Your slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime! Slimes... what would we do without them?",objectivesText="Collect 6 pieces of Laboratory Equipment . Progress: Has your slime been useful? I'm sure it has!",rewardGold=238680,rewardXP=1415,rewardItems={173536},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[58037] = {id=58037,name="Part of the Pride",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail. But where is the nuance? Where is the reward for your effort? Larions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.",objectivesText="Introduce yourself to 5 Tamed Larions . Progress: Larions are free-thinking beings. They will decide whether you are accepted within the pride.",rewardGold=3000,rewardXP=1415,starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58038] = {id=58038,name="All Natural Chews",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="A huge part of larion care is providing for them and keeping them happy. Larions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive. One of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.",objectivesText="Collect 5 Cloudstrider Antlers from Gilded Cloudstriders in the Golden Pasture. Progress: Antlers are great for keeping my pack's teeth sharp and clean.",rewardGold=386100,rewardXP=1415,rewardItems={173690},starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58039] = {id=58039,name="Larion at Large",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Some larions are more particular about the people they bond with than others. Lentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul. One of my pride, Andira , has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have. Would you mind finding her and bringing her home?",objectivesText="Find Andira in the Golden Pasture and return her to Nemea 's Retreat. Progress: Andira and I do not see eye to eye. I know she will be a loyal companion... but perhaps to somebody else.",rewardGold=386100,rewardXP=1415,starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58040] = {id=58040,name="With Lance and Larion",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Say what you want about phalynx, but Larion will always have one major advantage. Wings! A bonded larion will hunt alongside you whether you are on the ground or in the air. Take my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!",objectivesText="Kill 5 Cloudfeather Greatwing in Greatwing Roost.",rewardGold=358020,rewardXP=1415,rewardItems={173692},starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58041] = {id=58041,name="Providing for the Pack",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough. The pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.",objectivesText="Collect 10 Cloudfeather Essence . Progress: Larions bond through hunting. Working together with Andira to collect food is vital to your relationship.",rewardGold=358020,rewardXP=1415,rewardItems={173702},starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58042] = {id=58042,name="On Larion Wings",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="As a flightless being, you will unfortunately never feel the joy of flying alongside your companion. However... you could still fly with Andira . It seems you have earned Andira 's trust more than I've seen her with anybody else. Would you like to try a flight course? Take wing with Andira , then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!",objectivesText="Mount Andira , then complete the flight course. Progress: I set up the flight course to train the larions to listen to aerial commands. They know where to go!",rewardGold=386100,rewardXP=1415,rewardItems={173332,173333,173334,173335},rewardChoices={173333,173335,173334,173332},starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58045] = {id=58045,name="Plague is Thicker Than Water",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Come closer, my apprentice... I have a mission of dire import! A necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations. But I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments... He was trying to steal our slimes! I know it! You should admonish him quite harshly. Show that no harm will come to our friends!",objectivesText="Kill Korrim the Cunning . Progress: Have you chided the defiler?",rewardGold=243360,rewardXP=1415,rewardItems={175455,175456,175457,175458},rewardChoices={175457,175455,175458,175456},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[58060] = {id=58060,name="The Night Market",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I need some assistance, I promise you will be paid handsomely. At the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. But you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. Just don't say I sent you.",objectivesText="Bring the Hastily Wrapped Package to Ta'ruca at The Night Market in Revendreth . Provided item:",rewardGold=25740,rewardXP=1020,rewardItems={173689},starts={{npcID=160100}},ends={{npcID=160091}},coords={x=0.61,y=0.396,source="quest_giver",zoneID=10413},questType="standard"},
[58062] = {id=58062,name="A Very Special Guest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Listen. It is obvious you are doing this deal on Dracho's behalf. I believe Ta'xera , the boss around here, would be very interested in striking a deal with someone of your talents. She resides in the manor at the top of the hill. I recommend you don't keep her waiting.",objectivesText="Speak to Ta'xera at The Night Market.",rewardGold=64350,rewardXP=2040,starts={{npcID=160091}},ends={{npcID=160081}},coords={x=0.51,y=0.786,source="quest_giver",zoneID=10413},questType="standard"},
[58068] = {id=58068,name="...Even The Most Ridiculous Request!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A fan of the competition, are you? Perhaps you would like to be more than a mere spectator? I will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here. As you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.",objectivesText="See to the needs of the Promenade Champions. Progress: What now?",rewardGold=386100,rewardXP=1415,starts={{npcID=159689}},ends={{npcID=159689}},coords={x=0.54,y=0.508,source="quest_giver",zoneID=11462},questType="standard"},
[58069] = {id=58069,name="Favor: The Venthyr Diaries",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera . You will be fairly compensated.",objectivesText="Bring The Venthyr Diaries to Ta'xera at The Night Market in Revendreth . Provided item:",rewardGold=772200,rewardXP=2125,rewardItems={184373,184374},ends={{npcID=160081}},coords={mapID=1525,source="quest_giver",x=0.524,y=0.838},questType="standard"},
