[58084] = {id=58084,name="Soul Snares",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=160168,text="Souls liberated"},{orderIndex=0,type=0,amount=12,objectID=172568,text="Dredhollow threats slain"}},worldTaskTitle="Soul Snares",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58086] = {id=58086,name="The Master of Lies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low. Be sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. When you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.",objectivesText="Defeat Sire Denathrius .",rewardGold=772200,rewardXP=12250,rewardItems={175479,175480,175481,175482,175483,175492,175493,175494},rewardChoices={175480,175492,175483,175494,175482,175493,175481,175479},starts={{npcID=172673}},ends={{npcID=165557}},coords={x=0.32,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58087] = {id=58087,name="Destroying the Source",level=40,requiredLevel=40,faction="horde",expansion=8,zoneID=8499,mapID=862,description="Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. If we can destroy the source, we can destroy Nezara.",objectivesText="Destroy 3 Nazeshi Powercells within Dreadpearl Shallows.",rewardGold=341600,rewardXP=5465,starts={{npcID=145980}},ends={{npcID=145980}},coords={x=0.748,y=0.63,source="quest_giver",zoneID=8499},questType="standard"},
[58088] = {id=58088,name="Juicing Up",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I've conceived a task befitting of your \"talents\". Have you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame. Herein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing. The brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?",objectivesText="Find someone at the Challenger's Promenade who has enhancement potions.",rewardGold=25740,rewardXP=175,starts={{npcID=159827}},ends={{npcID=159833}},coords={x=0.538,y=0.506,source="quest_giver",zoneID=11462},questType="standard"},
[58090] = {id=58090,name="Side Effects",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits! For a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well. I cannot wait to see Minoire's next match in the arena!",objectivesText="Deliver the potion to Scrapper Minoire. Progress: This is an unexpected turn of events.",rewardGold=25740,rewardXP=175,rewardItems={177957},starts={{npcID=159833}},ends={{npcID=159689}},coords={x=0.536,y=0.478,source="quest_giver",zoneID=11462},questType="standard"},
[58092] = {id=58092,name="Halls of Atonement: Your Absolution",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12831,mapID=1525,description="The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain 's guidance inside the Halls of Atonement. If you truly wish to curb this corruption, you must dethrone the imposter that you installed here. Atone for your own mistake. Kill the Lord Chamberlain , so that we may begin to restore permanent order to this place.",objectivesText="Kill the Lord Chamberlain inside the Halls of Atonement.",rewardGold=1010880,rewardXP=2830,rewardItems={184717},starts={{npcID=160248}},ends={{npcID=167332}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="dungeon"},
[58093] = {id=58093,name="Our Forgotten Purpose",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I have no quarrel with you, Maw Walker. The Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power. The Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here. She will bring these depraved dogs to heel.",objectivesText="Meet the Accuser at Absolution Crypt.",rewardGold=25740,rewardXP=175,starts={{npcID=160248}},ends={{npcID=160116}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[58095] = {id=58095,name="Theater of Pain: Help Wanted",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12841,mapID=1536,description="Oh, bother--the Lich champion has withdrawn from the contest. Well, then... It appears we have an opening! Would anyone like to enter in her stead? Perhaps to increase the odds for their house? Anyone? Oh, ! So kind of you to volunteer. No better way to get experience than to just jump right in unprepared! Remember, we can't all be winners.",objectivesText="Enter the Theater of Pain dungeon, and defeat the champions within.",rewardGold=1158300,rewardXP=12250,rewardItems={181646},starts={{npcID=159689}},ends={{npcID=159689}},coords={x=0.54,y=0.508,source="quest_giver",zoneID=11462},questType="dungeon"},
[58096] = {id=58096,name="Supplies from the Rajani",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1530,description="The Rajani appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",objectivesText="Speak with Zhang Ku in Vale of Eternal Blossoms for your reward.",rewardItems={168576,168816,174479,174483},rewardCurrencies={{id=1553,amount=2500}},ends={{npcID=160711}},coords={mapID=1530,source="quest_giver",x=0.444,y=0.752},questType="standard"},
[58097] = {id=58097,name="Supplies from the Uldum Accord",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The Uldum Accord appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",objectivesText="Speak with Provisioner Qorra in Uldum for your reward.",rewardItems={173283,174481,174484},rewardCurrencies={{id=1553,amount=2500}},ends={{npcID=160714}},coords={mapID=1527,source="quest_giver",x=0.55,y=0.328},questType="standard"},
[58103] = {id=58103,name="Pride or Unit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I hope that working with my phalynx has swayed you, . Let us meet with Nemea . There you can decide whose way of life is superior, and which you would prefer to pursue.",objectivesText="Meet with Pelodis and Nemea , then pick a side. Progress: Surely you must agree that the ease of phalynx companionship suits you.",rewardGold=23870,rewardXP=175,starts={{npcID=158765}},ends={{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[58104] = {id=58104,name="Show, Don't Tell",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair. Normally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise. Commune with me so I can pick up the highlights! I'll make sure it's a show to remember!",objectivesText="Commune with Lady Moonberry .",rewardGold=25740,rewardXP=1020,starts={{npcID=161509}},ends={{npcID=160484}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[58122] = {id=58122,name="For the Horde",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=85,description="What an adventure, ! There is so much to explore... so much to discover. These are such exciting times! We'll show our allies in the Horde the value of having some clever Vulpera around. Please meet with the ambassador at the Orgrimmar embassy. I'll meet you there, !",objectivesText="Meet Ambassador Blackguard at the Orgrimmar Embassy.",rewardGold=200,rewardXP=175,rewardItems={167169,174069},starts={{npcID=160452}},ends={{npcID=133407}},coords={x=0.646,y=0.466,source="quest_giver",zoneID=1637},questType="standard"},
[58124] = {id=58124,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1519,mapID=85,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Talk to Chromie . Progress: This city is huge!",rewardGold=200,rewardXP=175,starts={{npcID=133407}},ends={{npcID=160452}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="standard"},
[58127] = {id=58127,name="Inquisitor Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: With my archives, it shouldn't be too challenging to identify and recreate the sinstone of an inquisitor.",rewardItems={173793},starts={{npcID=160248}},ends={{npcID=160248}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[58128] = {id=58128,name="High Inquisitor Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: Even with my archives, it could be difficult to identify and recreate the sinstone of a high inquisitor.",rewardItems={173794},starts={{npcID=160248}},ends={{npcID=160248}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[58129] = {id=58129,name="Grand Inquisitor Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: The Grand Inquisitors are incredibly protective of their secrets. We will need to expend exceptional resources to identify and recreate one of their sinstones.",rewardItems={173795},starts={{npcID=160248}},ends={{npcID=160248}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[58144] = {id=58144,name="Battered and Bruised",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=160400,text="Neglected Soul retrieved"},{orderIndex=2,type=0,amount=12,objectID=160375,text="Ash Ghouls slain"},{orderIndex=0,type=0,amount=1,objectID=160473,text="Chains collected"}},worldTaskTitle="Battered and Bruised",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58157] = {id=58157,name="Break a Leg",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The show is about to begin! You... that's what you're going to wear? Well, I suppose it works. For your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right? The Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! Don't worry about the script. This is your story, after all! Just try not to get too much blood on stage. It's hard to clean.",objectivesText="Reenact the Third Invasion of the Legion on Azeroth. Progress: Well, that wasn't... terrible.",rewardGold=514800,rewardXP=10205,starts={{npcID=160484}},ends={{npcID=160484}},coords={x=0.406,y=0.428,source="quest_giver",zoneID=11510},questType="standard"},
[58158] = {id=58158,name="The Fourth Wall, er, War",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth! Azeroth. Right. All these worlds are hard to tell apart. Help set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again. Get a move on! We have a lot to cover!",objectivesText="Set the Stage then help the reenactment of events after the Legion's fall. Progress: Come on, come on! We have a crowd to please!",rewardGold=257400,rewardXP=8165,starts={{npcID=160484}},ends={{npcID=160484}},coords={x=0.406,y=0.428,source="quest_giver",zoneID=11510},questType="standard"},
[58159] = {id=58159,name="What's My Motivation?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Now for our finale! A thrilling performance of the most recent trials on Azathoth! Featherlight checks his notes.> Azeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror? You're back to playing yourself, so just... do whatever heroes are supposed to do!",objectivesText="Perform the final acts! Progress: Well! That was exciting.",rewardGold=257400,rewardXP=8165,rewardItems={180263},starts={{npcID=160484}},ends={{npcID=160467}},coords={x=0.406,y=0.428,source="quest_giver",zoneID=11510},questType="standard"},
[58160] = {id=58160,name="For Queen and Grove!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="A stunning performance... in more ways than one. So much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage. I dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real. Ysera shakes her head.> The Winter Queen awaits you in the Heart of the Forest. We had best be on our way.",rewardGold=257400,rewardXP=8165,starts={{npcID=160500}},ends={{npcID=156634}},coords={x=0.424,y=0.452,source="quest_giver",mapID=1565},questType="standard"},
[58161] = {id=58161,name="Forest Disappearances",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="A moment of your time, friend? A short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us. However, it has been some time since he left and I have not seen or heard anyone from that region since. Can you go investigate? He came from the northeast.",objectivesText="Find Partik .",rewardGold=1230,rewardXP=175,starts={{npcID=160440},{npcID=169153}},ends={{npcID=160439}},coords={x=0.644,y=0.352,source="quest_giver",zoneID=11510},questType="standard"},
[58162] = {id=58162,name="Mysterious Masks",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The village, my friends, gone. They are no more. I came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart. They are all wearing these masks now, and they are not themselves anymore. Please, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.",objectivesText="Collect 15 Featureless Masks . Progress: For so many to fall, I did not think I was gone that long....",rewardGold=386100,rewardXP=1415,rewardItems={173800},starts={{npcID=160439}},ends={{npcID=160439}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[58163] = {id=58163,name="A Desperate Solution",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Thumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book. Perhaps if the rest of the pages were located then Partik could help decipher what happened here.>",objectivesText="Find the missing journal pages. Progress: What's that you've got there?",rewardGold=386100,rewardXP=1415,rewardItems={155876,173798,173872,173873,183851},rewardChoices={183851},starts={{npcID=349515}},ends={{npcID=160439}},coords={x=0.722,y=0.339,source="quest_giver",zoneID=11510},questType="standard"},
[58164] = {id=58164,name="Cult of Personality",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Some of my people are still alive! We must rescue them! The prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them. Please, set them free. We cannot let what happened to Lavrash happen to them!",objectivesText="Rescue 8 trapped night fae.",rewardGold=386100,rewardXP=1415,starts={{npcID=160439}},ends={{npcID=160439}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[58165] = {id=58165,name="Cut the Roots",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It's just as I feared, friend. The entire village is turned, just like Lavrash. Lewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly .... It pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!",objectivesText="Slay Bitterfly , Fiona Bleakthorn , and Wildtwister Lewor. Progress: If they fell, then what hope do we have?",rewardGold=386100,rewardXP=1415,rewardItems={173732},starts={{npcID=160439}},ends={{npcID=160439}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[58166] = {id=58166,name="Unknown Assailants",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This must be the stone he found. I do not recognize the mark. You should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.",objectivesText="Bring the Strange Runestone to Droman Tashmur in Tirna Vaal. Provided item:",rewardGold=25740,rewardXP=175,rewardItems={173732,175675,175676,175677,175678},rewardChoices={175677,175676,175675,175678},starts={{npcID=160439}},ends={{npcID=158487}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[58174] = {id=58174,name="All An Aspirant Can Do",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I think we can agree that such a reply feels... somewhat hollow. I choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite. We will meet you there, though there is no need to hurry.",objectivesText="Return to Aspirant's Rest.",rewardGold=23635,rewardXP=175,starts={{npcID=158862}},ends={{npcID=158471}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[58175] = {id=58175,name="The Eternal Forge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="The Forgelite Prime has taken up the mantle of building our new Crest of Ascension. No ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge. The Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.",objectivesText="Meet Mikanikos at the Eternal Forge.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=160280}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58176] = {id=58176,name="Stewards of a Feather",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You! Maw Walker! The forge was bustling. Many forgehands, on task! Then Forsworn came. Some followed their demands, turned to their side. But not all! Yes, rescue forgehands so they can aid us. Work to be done!",objectivesText="Free 5 Captured Forgehands . Progress: I tried to save, but am no hero. Can only try to organize chaos.",rewardGold=257400,rewardXP=8165,starts={{npcID=160648}},ends={{npcID=160648}},coords={x=0.502,y=0.206,source="quest_giver",zoneID=10534},questType="standard"},
[58177] = {id=58177,name="Refining Ego",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I will locate Phaestus. In the meantime, task for you! The Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use! Destroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me. I need much metal for my plan.",objectivesText="Collect 8 Purified Metal by collecting Tainted Centurion Components from centurion units and smelting them down at the Eternal Forge. Progress: I keep my resources here. The Forsworn stole from me! I cannot let this stand.",rewardGold=257400,rewardXP=8165,rewardItems={173879,173880},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58178] = {id=58178,name="A Partner for Eternity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Before returning to the Hold, one more thing to do. Defeat the Forsworn and their centurion army! This goliath here can help with just that. My finest creation yet! I need an extra pair of hands. Yours will do.",objectivesText="Help Mikanikos finish his finest creation. Progress: Trust he is no ordinary goliath. An extension of my hand itself!",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58179] = {id=58179,name="Instruments of Perfection",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all! Also very particular! He cannot work without his tools. The Forsworn scattered them around the forge! You need to rebuild Crest? Retrieve his tools!",objectivesText="Collect Mikanikos 's Soulsteel Clamps , Sparkling Driftglobe Core , and Gracepetal Incense Burner . Progress: I cannot work in these conditions.",rewardGold=257400,rewardXP=8165,rewardItems={173882,173909,173910},starts={{npcID=160648}},ends={{npcID=160280}},coords={x=0.502,y=0.206,source="quest_giver",zoneID=10534},questType="standard"},
[58180] = {id=58180,name="Phaestus, Genesis of Aeons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Sika reports the Forsworn are widespread. They not only took over production, but the rise as well! They organize their armies from the cliffs, send word back to their leaders. They've ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!",objectivesText="Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot work on the Crest.",rewardGold=514800,rewardXP=10205,rewardItems={174061,174296,177057,178160,179947},rewardChoices={178160,177057,179947,174296},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58181] = {id=58181,name="Building the Base",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Crest is almost complete. I give you the honor of the final touch. You have done much. Please, take Phaestus and give the final blow!",objectivesText="Complete the Crest of Ascension. Progress: Please care. Phaestus is older than you could dream!",rewardGold=128700,rewardXP=4085,rewardItems={180763},rewardChoices={180763},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58182] = {id=58182,name="Dismantling the Opposition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Forsworn mobilize! We cannot allow them to march. Attune to Bron, share your power with him. Between the three of us, we shall destroy this new centurion army!",objectivesText="Ride Bron, then defeat 30 Forsworn forces and dismantle 2 Colossus in the Eternal Forge. Progress: Bron was not meant as a tool of destruction, but will excel at it with you!",rewardGold=257400,rewardXP=8165,starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58183] = {id=58183,name="Friend to the Forgelite",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With Phaestus in hand, we can start building Crest. Let us return to Elysian Hold. Triumphant!",objectivesText="Return to Polemarch Adrestes in Elysian Hold.",rewardGold=25740,rewardXP=1020,starts={{npcID=160280}},ends={{npcID=160037}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58184] = {id=58184,name="Antiquated Methodology",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You possess the correct mindset for retraining a phalynx. I believe you could find great success here. Before you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea . She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx. Experience her lifestyle so that you may know how much greater my work is.",objectivesText="Talk to Nemea at Nemea 's Retreat.",rewardGold=386100,rewardXP=1415,starts={{npcID=158765}},ends={{npcID=157696}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[58185] = {id=58185,name="Success Without Soul",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The larions seem to truly enjoy your company, Andira most of all. I hope you've come to understand and appreciate the nuance of working with a beast with free will. Now you must spend time with Pelodis , down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction. I am sure working with the phalynx will only strengthen your appreciation of larions.",objectivesText="Talk to Pelodis at Forgefire Outpost.",rewardGold=358020,rewardXP=1415,starts={{npcID=157696}},ends={{npcID=158765}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[58207] = {id=58207,name="Buggin' Out",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=2,type=0,amount=12,objectID=159714,text="Bony Spindel Insects slain"},{orderIndex=1,type=0,amount=6,objectID=159739,text="Injured Scout saved"},{orderIndex=0,type=0,amount=1,objectID=165578,text="Gain Twigin's aid"}},worldTaskTitle="Buggin' Out",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58208] = {id=58208,name="Brace for Impact",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1156,description="That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much. Hold on... what's that sound? I think something big is headed our way!",objectivesText="Find Lady Jaina Proudmoore inside the ship.",rewardGold=30,rewardXP=25,starts={{npcID=160664}},ends={{npcID=156280}},questType="standard"},
[58209] = {id=58209,name="Stand Your Ground",level=1,requiredLevel=1,faction="alliance",expansion=8,mapID=1156,description="I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission. You'll be sparring with me today. We have to make sure you can handle yourself once we make landfall. Let's see what you've got!",objectivesText="Spar with Private Cole . Progress: Having trouble? Happens to the best of us. Just stay calm, select your target, and use one of your abilities on it. Make sure your target is in front of you. We don't want another incident like when Bjorn tried to throw an axe over his shoulder.",starts={{npcID=160664}},questType="standard"},
[58211] = {id=58211,name="Pumped Up",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up! Take this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there! Just be careful with whatever you pull up! You could face some resistance.",objectivesText="Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge. Progress: Have you recovered anything useful?",rewardGold=257400,rewardItems={173881,173892},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=168675}},ends={{npcID=168675}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[58214] = {id=58214,name="Urgent Care",level=40,requiredLevel=40,faction="alliance",expansion=8,zoneID=8568,mapID=84,description="Excellent timing, . Kelsey Steelspark has been sending communications to the capital cities looking for aid. Mekkatorque's condition is quite dire and time is of the essence. Hurry to Boralus Harbor, she will be watching for you.",objectivesText="Find Kelsey Steelspark in Boralus Harbor.",rewardGold=30900,rewardXP=685,starts={{npcID=126332},{npcID=149816}},ends={{npcID=160101}},coords={x=0.522,y=0.136,source="quest_giver",zoneID=1519},questType="standard"},
[58221] = {id=58221,name="Gettin' Even",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={184576},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=158971,text="Bonefused constructs slain"}},worldTaskTitle="Gettin' Even",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58260] = {id=58260,name="Queens And Future Kings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage. With Twigin's help, eliminate the queens and recover larvae from the eggs. I have a plan for the larvae that may allow us to use the marrowbore to our advantage.",objectivesText="Slay 1 marrowbore queens , and collect 5 marrowbore larvae. Progress: It's dirty work, but we need those larvae.",rewardGold=257400,rewardXP=8165,rewardItems={173942},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603}},ends={{npcID=167603}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[58264] = {id=58264,name="Wake Up, Get Up, Get Out There",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="They need your help! Not all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces.... You've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!",objectivesText="Aid 8 subdued faeries.",rewardGold=386100,rewardXP=1415,starts={{npcID=160749}},ends={{npcID=160749}},coords={x=0.534,y=0.588,source="quest_giver",zoneID=11510},questType="standard"},
[58265] = {id=58265,name="Blooming Villains",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Something stinks, traveler. The air to the west is rotten with malice. Shimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent. Scouts bring reports of the strange masked night fae. I know little other than that they are a threat. For the sake of Ardenweald , they must be eliminated. Slay any you encounter.",objectivesText="Slay 15 masked night fae in Shimmerbough.",rewardGold=386100,rewardXP=1415,starts={{npcID=160929}},ends={{npcID=160929}},coords={x=0.606,y=0.514,source="quest_giver",zoneID=11510},questType="standard"},
[58266] = {id=58266,name="Break It Down",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I've seen the ritual. It's... terrifying. But the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits! Primrose is silent for a moment, then takes a deep breath.> If you could get the powder and guard me, we could blow up those altars. I stashed as much as I could in our dwellings. They don't seem to care any more. You don't have wings, but a pinch of faerie dust should work for a short time. Let's do this before I change my mind!",objectivesText="Use Primrose's Pyrotechnic Powder to destroy 5 Ritual Altars.",rewardGold=410772,rewardXP=1415,rewardItems={174078},starts={{npcID=160749}},ends={{npcID=160749}},coords={x=0.534,y=0.588,source="quest_giver",zoneID=11510},questType="standard"},
[58267] = {id=58267,name="Beneath the Mask",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It's time to end this. When I first hid, I saw a dark shape on the northeast platform. I think that's their leader. Now that they can't perform any more rituals, we should be able to scare them off. I... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!",objectivesText="Confront the leader of the possessed fae in Shimmerbough.",rewardGold=386100,rewardXP=1415,rewardItems={175712},rewardChoices={175712},starts={{npcID=160757}},ends={{npcID=160929}},questType="standard"},
[58268] = {id=58268,name="Take the High Ground",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath. His forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed. We will take the ridge from him before that can happen.",rewardGold=243360,rewardXP=1415,starts={{npcID=169359,x=0.394,y=0.556,zoneID=11462}},ends={{npcID=169226,x=0.394,y=0.466,zoneID=11462}},coords={x=0.394,y=0.556,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Take the High Ground"},
[58272] = {id=58272,name="Words Have Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.",objectivesText="Collect 9 Rebellion Pamphlets. Progress: Uncouth and vile documents, but written in a rather elegant hand. The Prince always had better penmanship than sense.",rewardGold=386100,rewardXP=1415,rewardItems={173945,177665},starts={{npcID=352490}},ends={{npcID=155533},{npcID=156291}},coords={x=0.677,y=0.677,source="quest_giver",zoneID=10413},questType="standard"},
[58273] = {id=58273,name="Servant of N'Zoth",level=0,requiredLevel=0,faction="horde",expansion=8,description="<class>... I have watched you... I have felt your bloodlust. But you serve false prophets... the Horde is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Horde!",objectivesText="Use the N'lyeth, Sliver of N'zoth to change your faction from Horde to become devoted to N'Zoth. Then slay 10 Horde players without dying.",rewardItems={173951,174020},questType="standard"},
[58274] = {id=58274,name="Servant of N'Zoth",level=0,requiredLevel=0,faction="alliance",expansion=8,description="<class>... I have watched you... I have felt your bloodlust. But you serve false prophets... the Alliance is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Alliance!",objectivesText="Use the N'lyeth, Sliver of N'zoth to change your faction from Alliance to become devoted to N'Zoth. Then slay 10 Alliance players without dying.",rewardItems={173951,174020},questType="standard"},
[58279] = {id=58279,name="Quartermaster's Bounty",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=8499,mapID=1161,objectivesText="Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.",rewardItems={172519},starts={{npcID=143560}},ends={{npcID=143560},{npcID=143555}},coords={x=0.564,y=0.258,source="quest_giver",zoneID=8568},questType="standard"},
[58297] = {id=58297,name="Faceless Mask of the Daredevil",level=50,requiredLevel=50,faction="both",expansion=8,description="The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.",objectivesText="Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Daredevil on the altar.",rewardItems={173955},questType="standard"},
[58314] = {id=58314,name="Faceless Mask of the Burned Bridge",level=50,requiredLevel=50,faction="both",expansion=8,description="The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.",objectivesText="Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Burned Bridge on the altar.",rewardItems={174342},questType="standard"},
[58316] = {id=58316,name="Faceless Mask of the Dark Imagination",level=50,requiredLevel=50,faction="both",expansion=8,description="These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.",objectivesText="Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Dark Imagination on the altar.",rewardItems={173953},questType="standard"},
[58317] = {id=58317,name="Faceless Mask of the Pained",level=50,requiredLevel=50,faction="both",expansion=8,description="Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.",objectivesText="Return the Faceless Mask of the Pained to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Pained on the altar.",rewardItems={173524},questType="standard"},
[58318] = {id=58318,name="Faceless Mask of the Long Night",level=50,requiredLevel=50,faction="both",expansion=8,description="The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.",objectivesText="Return the Faceless Mask of the Long Night to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Long Night on the altar.",rewardItems={172952},questType="standard"},
[58325] = {id=58325,name="Watcher Emil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him. I had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is. There is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess. You must find Emil at once. We may not have much time.",objectivesText="Search for Watcher Emil in the Catacombs of Regret. Progress: A friend of the Curator ?",rewardGold=257400,rewardXP=8165,starts={{npcID=160941}},ends={{npcID=160956}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58326] = {id=58326,name="Combing the Catacombs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="When the anima drought began, our defenses began to fail. Our guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild. You may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.",objectivesText="Kill 12 Manifestations and 3 Sinstone Rampagers in the Catacombs of Regret.",rewardGold=257400,rewardXP=8165,starts={{npcID=161056}},ends={{npcID=161056}},coords={x=0.658,y=0.324,source="quest_giver",zoneID=10413},questType="standard"},
[58327] = {id=58327,name="Snacks for Stonehead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Stonehead has amassed a wide variety of half-eaten oddities. He'd certainly appreciate you bringing some new, creative snacks for him to try.>",objectivesText="Collect a sampling of snacks from across the Ember Ward for Stonehead . Progress: Tummy rumbly...",rewardGold=772200,rewardXP=12250,rewardItems={175826,175828,175829,175840},starts={{npcID=346046}},ends={{npcID=157199}},coords={x=0.392,y=0.653,source="quest_giver",zoneID=10413},questType="standard"},
[58328] = {id=58328,name="TBD",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Bribe Boulderfoot",objectivesText="TBD",rewardGold=25740,rewardXP=175,questType="standard"},
[58337] = {id=58337,name="Break Out",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process. Take these iron chains. They can be used to rein them under your control. Once you have a soul bound, you can return them to any intact cage you can find.",objectivesText="Use the Chains of Regret on Escaped Captives and bring them to any intact Catacombs Cage.",rewardGold=514800,rewardXP=10205,rewardItems={174040},starts={{npcID=161056}},ends={{npcID=161056}},coords={x=0.658,y=0.324,source="quest_giver",zoneID=10413},questType="standard"},
[58351] = {id=58351,name="The Hills Have Eyes",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence. Any tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak. Take one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.",objectivesText="Uncover hidden spies with the Chosen Corpsehound. Progress: Get moving!",rewardGold=243360,rewardXP=1415,starts={{npcID=157895}},ends={{npcID=157895}},coords={x=0.362,y=0.602,source="quest_giver",zoneID=11462},questType="standard"},
[58372] = {id=58372,name="Lead the Way",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We must move now. That won't be the last assassin we face. I can provide some cover of darkness, but mind that the spell is not infallible. Enough talking. The Curator needs us and my mirror shard to get to her as soon as possible.",objectivesText="Escort Watcher Emil out of the Catacombs of Regret.",rewardGold=257400,rewardXP=8165,rewardItems={180924,180925,180926,180927},starts={{npcID=160956}},ends={{npcID=160941}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58373] = {id=58373,name="Ny'alotha: MOTHER's Guidance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10522,description="Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.",objectivesText="Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Normal Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.",rewardGold=468000,rewardXP=8520,starts={{npcID=160177}},questType="raid"},
[58374] = {id=58374,name="Ny'alotha: MOTHER's Guidance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10522,description="Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.",objectivesText="Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Heroic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.",rewardGold=468000,rewardXP=8520,starts={{npcID=160177}},questType="raid"},
[58375] = {id=58375,name="Ny'alotha: MOTHER's Guidance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10522,description="Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.",objectivesText="Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Mythic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.",rewardGold=468000,rewardXP=8520,starts={{npcID=160177}},questType="raid"},
[58376] = {id=58376,name="Construct Part: Necromantic Oil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Rathan will know how we can use it.>",objectivesText="Deliver this part to Rathan in Butchers Block. Provided item:",rewardXP=1020,rewardItems={183519},ends={{npcID=167150}},coords={mapID=1536,source="quest_giver",x=0.55,y=0.686},questType="standard"},
[58379] = {id=58379,name="Construct Part: Indomitable Hide",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Rathan will know how we can use it.>",objectivesText="Deliver this part to Rathan in Butchers Block. Provided item:",rewardXP=1020,rewardItems={183475},ends={{npcID=167150}},coords={mapID=1536,source="quest_giver",x=0.55,y=0.686},questType="standard"},
[58382] = {id=58382,name="Someone Worth Saving",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Are you familiar with Kael'thas Sunstrider? He was a powerful leader on your world for a time. The immense anima of that lingering power attracted the Master's attention, to the eternal detriment of Kael'thas's soul. The Accuser 's lip curls in disgust.> Every soul deserves a chance at redemption, $p. If you do not believe that, believe me when I say that this soul is immensely powerful and still at risk of self-destruction. Release him so that we may walk his path of redemption together.",objectivesText="Release Kael'thas Sunstrider in Sinfall.",rewardGold=128700,rewardXP=4085,starts={{npcID=165291}},ends={{npcID=165291}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="standard"},
[58383] = {id=58383,name="The Many Sins of Kael'thas Sunstrider",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria. Denathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others. It made his soul strong, but unstable--confused and pushed to the edge of its own existence. Trust me when I tell you that Kael'thas Sunstrider has enough sins of his own. Assist me in identifying which of the many sins heaped on his soul are truly his burden to bear.",objectivesText="Help the Accuser identify the sins of Kael'thas Sunstrider. Progress: The ritual of absolution allows me to peer directly into a soul to see every sin weighing it down.",rewardGold=128700,rewardXP=4085,starts={{npcID=161158}},ends={{npcID=161158}},questType="standard"},
[58384] = {id=58384,name="Dredgers Left Behind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind. The powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead. You will be a welcome sight to them--a sign that the Prince has not forgotten them. If they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.",objectivesText="Help 10 dredgers escape Darkwall Tower.",rewardGold=257400,rewardXP=8165,starts={{npcID=161208}},ends={{npcID=161278}},coords={x=0.422,y=0.476,source="quest_giver",zoneID=10413},questType="standard"},
[58385] = {id=58385,name="Learning to Sacrifice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Kael'thas remains unstable in his current state, bursting at the seams with anima. He is also an arrogant, selfish moron. Thankfully, I have a lesson that can address both concerns. True leaders sacrifice of themselves to empower those under their care. Many stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces. Order Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.",objectivesText="Help Kael'thas reanimate the Prince's pet, Vrednic, and other dormant stoneborn in Darkwall Tower.",rewardGold=257400,rewardXP=8165,starts={{npcID=161208}},ends={{npcID=161278}},coords={x=0.422,y=0.476,source="quest_giver",zoneID=10413},questType="standard"},
[58386] = {id=58386,name="Use My Strengths",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="the Accuser is out of earshot.> the Accuser is so obsessed with my negative traits that she has failed to see my strengths! Even in death, I am incredibly powerful. the Accuser herself said that Denathrius infused me with anima to make me strong. Let us use that strength for good while I have it! This tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance! Vengeance is a virtue I have always appreciated.",objectivesText="Help Kael'thas confront Usurper Simona. Progress: Yes?",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161261}},ends={{npcID=161278}},questType="standard"},
[58387] = {id=58387,name="We Each Must Carry Our Own Sins",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened. He bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not. Let us hope your time with Kael'thas has prepared his soul for my ritual. I must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.",objectivesText="Complete the ritual of extraction on Kael'thas Sunstrider. Progress: This must work.",rewardGold=128700,rewardXP=4085,rewardItems={180941},starts={{npcID=161278}},ends={{npcID=161278}},coords={x=0.438,y=0.514,source="quest_giver",zoneID=10413},questType="standard"},
[58388] = {id=58388,name="Blackbale Betrayers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District. None came. Most simply avoided the conflict, out of self-preservation. A shameful, but understandable choice. However, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead. Prince Renathal has not forgotten that betrayal. Kael'thas seeks vengeance? Let him have some. Start with the stoneborn.",objectivesText="Kill 4 Blackbale Overseers . Progress: The Blackbale seem to have grown more influential since the Prince's fall.",rewardGold=257400,rewardXP=8165,starts={{npcID=161421}},ends={{npcID=161421}},coords={x=0.464,y=0.514,source="quest_giver",zoneID=10413},questType="standard"},
[58389] = {id=58389,name="Maldraxxian Weapons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8721,mapID=1525,description="the Accuser .>",objectivesText="Collect 8 Maldraxxian Weapons . Progress: What are you carrying? Those do not belong here...",rewardGold=257400,rewardXP=8165,rewardItems={174211,174212},ends={{npcID=161421}},coords={mapID=1525,source="quest_giver",x=0.458,y=0.5145},questType="standard"},
[58391] = {id=58391,name="Reconnaissance... for my, uh, Recovery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It appears I am at your mercy once more, $p. Far be it from me to tell you the best way to absolve my sins as the Accuser insists we do. However... In that note, the Tithelord arranged a meeting with his contact in Darkhaven. Do you know where that is? If you do, we could investigate, gather more information, and present that information to the Accuser and Prince Renathal. I imagine that would be quite useful to them. And a very selfless act of assistance on my part, do you not agree?",objectivesText="Spy on the Tithelord's meeting with his Maldraxxian contact.",rewardGold=128700,rewardXP=4085,starts={{npcID=161431}},ends={{npcID=161572}},questType="standard"},
[58392] = {id=58392,name="Death's End Destruction",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It appears we have discovered a common enemy to pursue, $p. Wherever that necromancer ran off to is no doubt filled with traitors, undead armies from another realm, and at least one lich... It cannot be a sin to kill such as these. To demolish the camp of these invaders and betrayers must be a virtue. A virtue I crave. Let us pursue it with haste.",objectivesText="Destroy the Maldraxxian camp in Death's End. Progress: I hope they put up a fight.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161572}},ends={{npcID=161572}},coords={x=0.698,y=0.6,source="quest_giver",zoneID=10413},questType="standard"},
[58393] = {id=58393,name="Strategic Executions",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement. But I am very aware of the dangers posed by a lich with access to power. I am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me. We should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.",objectivesText="Kill the dredger giants in Death's End. Progress: They really do grow their monsters big here, do they not?",rewardGold=514800,rewardXP=10205,starts={{npcID=161572}},ends={{npcID=161572}},coords={x=0.698,y=0.6,source="quest_giver",zoneID=10413},questType="standard"},
[58394] = {id=58394,name="Lady Ouix'Ara",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Can you feel it? The chill in your bones... the energy... power... She's here. The lich. Take me to her. I must speak with her, in my own way.",objectivesText="Kill Lady Ouix'Ara . Progress: No good has ever come from a lich, <name>.",starts={{npcID=161436}},questType="standard"},
[58395] = {id=58395,name="Enough Vengeance For One Day",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I... I... am ready to return to Sinfall. I must recover my strength for what lies ahead. As the Accuser is so fond of reminding me, I have... much to ponder. Let us inform our allies of the enemy we have revealed.",objectivesText="Deliver Kael'thas to Sinfall and report to Prince Renathal .",rewardGold=25740,rewardXP=1020,rewardItems={180901,180902,180903,180904},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161436}},ends={{npcID=158653}},questType="standard"},
[58406] = {id=58406,name="Mirror to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I've received word that Laurent 's made substantial progress with his repairs. Once the mirror has been restored, we can realize our efforts to recover the final medallion. Head to the ramparts and see if his work is near completion.",objectivesText="Find Laurent on the Sinfall ramparts.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158653}},ends={{npcID=170532}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[58407] = {id=58407,name="The Medallion of Dominion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Laurent speaks the truth. We must not delay. This mirror is our entryway into the heart of Maldraxxus. Together with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.",objectivesText="Use Laurent's mirror to enter Maldraxxus and recover the Medallion of Dominion from Kel'Thuzad.",rewardGold=772200,rewardXP=12250,rewardItems={180948,183888,183889,183890,183891,183892,183893},rewardChoices={183888,183889,183890,183891,183892,183893},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=170543}},ends={{npcID=158653}},coords={x=0.274,y=0.404,source="quest_giver",zoneID=10413},questType="standard"},
[58421] = {id=58421,name="Special Access",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam. It is guarded by Nourman , a loyal dredger. Nourman is ever committed to his duties, regardless of the situation. Mateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.",objectivesText="Collect the fangs of Examiner Daciana, Examiner Boian, and Examiner Ionata. Progress: Oi, you want to access the manor? Let me see your fangs.",rewardGold=514800,rewardXP=10205,rewardItems={174093,174094,174095},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160941}},ends={{npcID=161298}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58424] = {id=58424,name="An Eye for an Amulet",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Archivam has been overrun by Denathrius's lackeys. We must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion. Go, . Stop them before it is too late.",objectivesText="Kill 12 Archivam Intruders and 5 Excavation Enforcers in Archivam. Progress: Are they dead?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160956}},ends={{npcID=160956}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58426] = {id=58426,name="In the Shadow of our Failures",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct. I would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path. If you're willing, meet us at Darkwall Tower. Prince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.",objectivesText="Meet the Accuser and Kael'thas at Darkwall Tower.",rewardGold=25740,rewardXP=1020,starts={{npcID=161158}},ends={{npcID=161208}},questType="standard"},
[58428] = {id=58428,name="Crypt Crashers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="There's one more thing I forgot to mention. Apologies, . The mirror, once complete, is inherently cursed by design. You need to locate my Death Lotus Powder . It was in one of the crypts in Archivam... I cannot recall which one. I'm afraid you may have to brute force this one, .",objectivesText="Collect Stonebreaker Mallets to destroy crypt doors in search of Death Lotus Powder . Progress: Do you have the powder?",rewardGold=257400,rewardXP=8165,rewardItems={174098,174100},starts={{npcID=160941}},ends={{npcID=160941}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58431] = {id=58431,name="Pool of Potions",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I shall teach you about the Pool of Potions . The potions we create here have a variety of beneficial effects. Kill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. Deliver this oil to the Pool of Potions and toss it in.",objectivesText="Deliver three Oozing Ingredient: Viscous Oil to the Pool of Potions . Progress: Have you brought enough oil?",rewardGold=386100,rewardXP=1415,rewardItems={171267,171268},rewardChoices={171267,171268},starts={{npcID=157945}},ends={{npcID=157945}},coords={x=0.59,y=0.738,source="quest_giver",zoneID=11462},questType="standard"},
[58432] = {id=58432,name="Something Old, Something Used",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Want new luckydos? Chordy is best at finding luckydos! Want to go look around with Chordy ? Chordy looks at you pleadingly with his large eye.>",rewardXP=8165,rewardItems={174101,178554},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Something Old, Something Used"},
[58433] = {id=58433,name="Anima Attrition",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying. That anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima. Recover the tithe if you can and I will see to your notoriety.",objectivesText="Recover the Anima Canister . Progress: What have you found?",rewardGold=252720,rewardXP=1415,rewardItems={174102},starts={{npcID=155533}},ends={{npcID=155533}},coords={x=0.674,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[58435] = {id=58435,name="Heritage of the Vulpera",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8501,mapID=864,description="The Horde has come to truly value the Vulpera, thanks to your efforts. You are the most... vulperan vulpera that I know! Visit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.",objectivesText="Meet Hagashi at the Vulpera Hideaway in Vol'dun.",rewardItems={173966,173967,173968,173969,173970,173971,174354,174355,174376},starts={{npcID=124108}},ends={{npcID=124108}},questType="standard"},
[58436] = {id=58436,name="Heritage of the Mechagnome",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10290,mapID=1462,description=", we could not be more pleased with your progress. You represent us well with the Alliance. Return to Mechagon City at your earliest convenience. Waren has created a gift for you.",objectivesText="Meet Prince Erazmin in Mechagon City.",rewardGold=341600,rewardXP=6815,rewardItems={173958,173961,173962,173963,173964,173972},starts={{npcID=158145}},ends={{npcID=158145}},questType="standard"},
[58437] = {id=58437,name="Parts to a Whole",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Damien has some great dreams, but without more abominations, this training facility will not succeed! I have a plan though! If we can't recruit more abominations, then we shall make them ourselves! I need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.",rewardXP=8165,rewardItems={174110},questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=161288,text="Corpses marked for harvest"}},worldTaskTitle="Parts to a Whole",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58440] = {id=58440,name="Mirror, Mirror...",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We have what we need to get you through, . My medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. Please be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior. I should be able to tell you everything about this place, but I am afraid that just is not the case anymore.",objectivesText="Enter the Curator 's mirror. Then, collect the Medallion of Avarice . Progress: My medallion? Do you have it?",rewardGold=128700,rewardXP=4085,rewardItems={174111,174179,180945},starts={{npcID=160941}},ends={{npcID=160941}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58443] = {id=58443,name="Continued Care of Kael'thas",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet. He carries more than enough burdens from his own sins to condemn him to the Maw. We must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever. You are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.",objectivesText="Meet the Accuser and Kael'thas in the Chalice District.",rewardGold=25740,rewardXP=1020,starts={{npcID=161278}},ends={{npcID=161421}},coords={x=0.438,y=0.514,source="quest_giver",zoneID=10413},questType="standard"},
[58444] = {id=58444,name="Return to Sinfall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description=", we must get the medallion back to Sinfall as soon as possible. We saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around. I will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties. My first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...",objectivesText="Bring the medallion to Prince Renathal at Sinfall. Progress: Did you retrieve the Medallion of Avarice ?",rewardGold=772200,rewardXP=12250,rewardItems={174111},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160941}},ends={{npcID=158653}},coords={x=0.726,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[58445] = {id=58445,name="Containing the Night",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="It is fortunate you are here, . Thiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior. Let us hear what he has to say.",objectivesText="Listen to Thiernax's plan. Progress: It cannot be easy for Thiernax to share his memories of becoming the Night Warrior... or the pain that followed.",rewardGold=128700,rewardXP=4085,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[58446] = {id=58446,name="Tracker Tracking",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We will require the aid of an expert tracker if we are to find the other Night Warriors. The Wild Hunt possesses legendary skills in such matters. No quarry can elude them. Speak with Lord Herne. With one of his hunters at your side, your search will surely be successful.",objectivesText="Speak with Lord Herne and locate the Wild Hunt tracker.",rewardGold=128700,rewardXP=4085,starts={{npcID=160262}},ends={{npcID=164627}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[58447] = {id=58447,name="Monster Hunting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Make ready, . We hunt a worldeater. They are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. With Ardenweald suffering from the drought, a worldeater's presence could prove disastrous. Still, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor. Knowing our quarry will be what allows us to slay it.",objectivesText="Search for clues and tracks to learn more about the worldeater.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161353}},ends={{npcID=165841}},coords={x=0.3,y=0.448,source="quest_giver",zoneID=11510},questType="standard"},
[58449] = {id=58449,name="Acid Reflux",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We will need to be properly prepared before we can face Voras. The digestive juices of Ardenweald 's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort. For a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east. Long ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.",objectivesText="Use the Gormherd Branch on gorm in Gormhive to retrieve 50 Bulging Digestive Sacs . Progress: We will need those digestive sacs if we are to disrupt the worldeater enough to slay it, <name>.",rewardGold=257400,rewardXP=8165,rewardItems={174467,174645},starts={{npcID=165841}},ends={{npcID=164627}},coords={x=0.352,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[58450] = {id=58450,name="Anima Instincts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight. Did you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them. There should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.",objectivesText="Collect 8 Life-Hardened Anima . Progress: It may take several wildseeds, but with enough concentrated anima, we should be able to lure out Voras.",rewardGold=257400,rewardXP=8165,rewardItems={175753},starts={{npcID=165841}},ends={{npcID=164627}},coords={x=0.352,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[58451] = {id=58451,name="Voras, The Realm Eater",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We have everything we need, . Now only the kill remains. We set the lure, weaken the beast, and land the final blow. Hunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald . Let the hunt begin.",objectivesText="Slay Voras . Progress: Voras cannot continue to leech anima from Ardenweald . We must stop it now.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161353}},ends={{npcID=161354}},coords={x=0.3,y=0.448,source="quest_giver",zoneID=11510},questType="standard"},
[58452] = {id=58452,name="Tracking the Shadows",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course. I will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.",objectivesText="Speak with Ysera in the Heart of the Forest.",rewardGold=25740,rewardXP=1020,rewardItems={175592,179769,179891,181913},rewardChoices={175592,179769,181913,179891},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161353}},ends={{npcID=160262}},coords={x=0.3,y=0.448,source="quest_giver",zoneID=11510},questType="standard"},
[58454] = {id=58454,name="Spoiling For A Fight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima. Would you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her. I can add her to the schedule, she will appear soon if you defeat the other challengers.",objectivesText="Defeat Sabriel the Bonecleaver in the Theater of Pain.",rewardGold=25740,rewardXP=1020,starts={{npcID=159830}},ends={{npcID=159830}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="group"},
[58455] = {id=58455,name="Shadowy Showdown",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=51,mapID=1161,description="This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.",objectivesText="Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.",rewardGold=23400,rewardXP=850,starts={{npcID=147645}},ends={{npcID=147645}},coords={x=0.5,y=0.468,source="quest_giver",zoneID=8568},questType="standard"},
[58456] = {id=58456,name="Shadowy Showdown",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=51,description="This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.",objectivesText="Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.",rewardGold=23400,rewardXP=850,starts={{npcID=147641}},ends={{npcID=147641}},questType="standard"},
[58457] = {id=58457,name="Shadows of Blackrock",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=51,description="We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning. Let me know when you are ready.",objectivesText="Stop the Shadowy Figures. Progress: I can teleport you in, but after that, you're on your own.",rewardGold=936000,rewardXP=13630,rewardItems={122457},starts={{npcID=161782}},ends={{npcID=161782}},questType="standard"},
[58458] = {id=58458,name="Pet Battle Challenge: Blackrock Depths",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=51,description="Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.",objectivesText="Stop the Shadowy Figures. Progress: I can teleport you back in there, but you're on your own once you're inside. Good luck.",rewardGold=234000,rewardXP=6815,rewardItems={174360},starts={{npcID=161782}},ends={{npcID=161782}},questType="standard"},
[58472] = {id=58472,name="A Farewell to Arms",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth. Destroy their encampment. Purge it from our soil, and ensure such an affront never occurs again. The means are not important. All that matters is that these heretics remember the consequences of trifling with true power.",objectivesText="Destroy the Maldraxxi encampment at Death's End. Progress: Well?",rewardGold=257400,rewardXP=8165,starts={{npcID=161694}},ends={{npcID=161694}},coords={x=0.74,y=0.578,source="quest_giver",zoneID=10413},questType="standard"},
[58473] = {id=58473,name="Echoes of Tirna Noch",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some. Many of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them. The Wild Hunt has tracked them to Tirna Noch... my former grove. Long has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive. I remember it well...",objectivesText="Meet Ara'lon in Tirna Noch.",rewardGold=25040,rewardXP=175,starts={{npcID=160963}},ends={{npcID=161378}},coords={x=0.6,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[58480] = {id=58480,name="Read the Roots",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="When my grove withered, I answered the Queen's call and joined the Wild Hunt. Nothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest. We need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it. They likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.",objectivesText="Investigate the Depleted Soulwebs in Tirna Noch, to find the greatest concentration of anima in the grove. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.",rewardGold=250380,rewardXP=1415,starts={{npcID=161378}},ends={{npcID=161378}},coords={x=0.684,y=0.574,source="quest_giver",zoneID=11510},questType="standard"},
[58483] = {id=58483,name="Mementos",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes. It brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well. I can't believe that everything that was once here is truly gone. Perhaps there are still some mementos that can be recovered. Something to remember the fallen.",objectivesText="Collect Stolen Mementos from slain enemies in Tirna Noch. Progress: Is this what lies in store for Heartwood Grove? For my old home?",rewardGold=250380,rewardXP=1415,rewardItems={174219},starts={{npcID=161379}},ends={{npcID=161379}},coords={x=0.684,y=0.574,source="quest_giver",zoneID=11510},questType="standard"},
[58484] = {id=58484,name="Take What You Can",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We know that these invaders have taken over the remains of the grove. But why? Why are they gathering anima and bringing it all to one place? And how did they enter Ardenweald ? We should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.",objectivesText="Take Plundered Anima from stores in Tirna Noch. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.",rewardGold=257400,rewardXP=1415,rewardItems={180287},starts={{npcID=161378}},ends={{npcID=161378}},coords={x=0.684,y=0.574,source="quest_giver",zoneID=11510},questType="standard"},
[58486] = {id=58486,name="He's Drust in the Way",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. When my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again. Anima that was stolen from other groves. We must secure the heart not just for our own sake, but for the entire forest. I suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.",objectivesText="Slay Vroth , Bulwark of Thros, and make your way to the Heart of the Fallen Tree.",rewardGold=257400,rewardXP=1415,starts={{npcID=161446}},ends={{npcID=161492}},questType="standard"},
[58488] = {id=58488,name="Go for the Heart",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I was right! A great deal of anima has been stored inside the heart of the grove. The Drust must have collected it from all over Ardenweald . And now, we will take it back. Quickly, destroy that barrier and grab the heart. Niya and I will protect you.",objectivesText="Destroy the barrier and collect the Heart of Tirna Noch . Progress: We will reclaim this anima. The Drust will not use it for their own ends.",rewardGold=125190,rewardXP=710,rewardItems={174269},starts={{npcID=161492}},ends={{npcID=161492}},coords={x=0.714,y=0.546,source="quest_giver",zoneID=11510},questType="standard"},
[58490] = {id=58490,name="Deadly Reminder",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.",rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Lich Forces Eliminated"}},worldTaskTitle="Deadly Reminder",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58496] = {id=58496,name="An Unwelcome Advisor",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Anduin Wrynn .> , Even with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn. The Light only knows what ill he has in store for Azeroth. Meet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late! Light grant you haste, King Anduin Wrynn",objectivesText="Speak with King Anduin Wrynn in Stormwind Keep. Progress: What is it?",rewardGold=23400,rewardXP=850,starts={{npcID=369893}},ends={{npcID=107574}},coords={x=0.681,y=0.224,source="quest_giver",zoneID=8568},questType="standard"},
[58498] = {id=58498,name="Return of the Warrior King",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10833,mapID=84,description="Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike. This battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side! But first, we'll need tae fetch it.",objectivesText="Walk with Magni and retrieve Fearbreaker in Stormwind Keep. Progress: Need something, champion?",rewardGold=23400,rewardXP=850,rewardItems={175151},starts={{npcID=154532}},ends={{npcID=154532}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[58502] = {id=58502,name="Where the Heart Is",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=9667,mapID=84,description="It's time we put Wrathion's plans in tae motion. He'll be headin' back tae the Chamber of Heart, so we should meet him there.",objectivesText="Return to the Chamber of Heart.",rewardGold=23400,rewardXP=850,starts={{npcID=154532}},ends={{npcID=152206}},coords={x=0.874,y=0.352,source="quest_giver",zoneID=1519},questType="standard"},
[58504] = {id=58504,name="Accusatory Missive",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm. An emissary from Sinfall wishes to discuss the anima reserves we discovered. Join me. We depart immediately.",objectivesText="Meet with the Accuser in the Halls of Atonement in Revendreth.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161461}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[58505] = {id=58505,name="Planned Demise",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.",rewardXP=8165,rewardItems={174231,174232,174233},questType="world",worldTaskTitle="Planned Demise",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58506] = {id=58506,name="Network Diagnostics",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike. Back when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first. Fortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.",objectivesText="Activate the Titan Consoles in the Chamber of Heart to check the status of the titan forges throughout Azeroth. Progress: The consoles should tell ye how the forges are holdin' up.",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=152206}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[58515] = {id=58515,name="Scrounging for Scrolls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks. Why is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus? Perhaps research can divine the answer.",objectivesText="Collect information on the kyrian from the Temple of Humility. Progress: Let's see, where did that paper go?",rewardXP=8165,rewardItems={175275},starts={{npcID=159198}},ends={{npcID=167150}},coords={x=0.552,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[58518] = {id=58518,name="There's Always a Paper Trail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I noticed that you were surprised to find those strange weapons here. I sense the essence of their power as well. It is strangely familiar... We must discover where the weapons came from and who imbued them with such power. If you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!",objectivesText="Discover proof of who's supplying the venthyr with Maldraxxian weapons. Progress: You found something?",rewardGold=514800,rewardXP=10205,rewardItems={174278},starts={{npcID=161427}},ends={{npcID=161421}},questType="standard"},
[58523] = {id=58523,name="You're Dead To Me",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Your cooperation is expected, but I await results. Our reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima. I have called for a carriage to take us there. Let us make haste.",objectivesText="Follow the Accuser to the Maldraxxi encampment.",rewardGold=128700,rewardXP=4085,starts={{npcID=161461}},ends={{npcID=161694}},coords={x=0.72,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[58524] = {id=58524,name="Sparkles Rain from Above",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You found the heart of the grove! And it's full of anima! The Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest! We need to get you and the others out of here safely. I can help. How do you feel about dishing out a little sparkly mayhem?",objectivesText="Speak with Lady Moonberry and escape Tirna Noch.",rewardGold=250380,rewardXP=1415,rewardItems={175767},rewardChoices={175767},starts={{npcID=161494}},ends={{npcID=160894}},coords={x=0.714,y=0.546,source="quest_giver",zoneID=11510},questType="standard"},
[58525] = {id=58525,name="The Two Sides of History",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1536,description="You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue. Everyone has their own version of events. I would like to know them all. There was an author of history books who made her abode in Revendreth's Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. If we could find copies of her works...",objectivesText="Find copies of \" On Bone and Stone \" and \" The Malice of Maldraxxus .\"",rewardXP=8165,rewardItems={183744,182486,182495,182504,182513,184843},starts={{npcID=159198}},ends={{npcID=167150}},coords={x=0.552,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[58530] = {id=58530,name="Hidden Mirror",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion. As denizens of Revendreth, Bastion will not allow us to enter through Oribos. We will need you to activate a mirror hidden away there long ago. Take this. We concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.",objectivesText="Use Laurent's Compact Looking Glass to reveal the Hidden Mirror in Bastion.",rewardGold=128700,rewardXP=4085,rewardItems={180356},starts={{npcID=161514}},ends={{npcID=162213}},coords={x=0.442,y=0.454,source="quest_giver",zoneID=10986},questType="standard"},
[58555] = {id=58555,name="A Tense Reunion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We are looking for the forgelite prime, Mikanikos. Only he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn. When last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge. We will meet you there. Traveling as a group may draw too much attention.",objectivesText="Meet General Draven and Theotar at the Eternal Forge.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=162213}},ends={{npcID=161526}},coords={x=0.496,y=0.302,source="quest_giver",zoneID=10534},questType="standard"},
[58557] = {id=58557,name="Assistance from Sinfall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1533,description="In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward. I have an artifact in mind. Long ago, many souls from Revendreth arrived in Bastion . Purer souls than we have ever received from Revendreth. They bore the mark of the Seal of Contrition, a focus that expedited their cleansing. Go to Revendreth and find this seal so that we may harness its power.",objectivesText="Meet with The Curator in Darkhaven in Revendreth.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=161544}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58558] = {id=58558,name="Overhead Intelligence",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt. However, she has a dark secret. Despite what she may say... she was once mortal. We will need to find where she keeps her sinstone. No easy feat, of course. We will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.",objectivesText="Collect the Rumors of Favor from Chalice Couriers in the Chalice District.",rewardGold=257400,rewardXP=8165,rewardItems={174333,176082,176083,176084},starts={{npcID=161544}},ends={{npcID=161544}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58559] = {id=58559,name="Eyes of the Master",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I worry about entering the city. I'm sure you have noticed how well we... stand out here. Denathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn. Their eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.",objectivesText="Kill Evaala the All-Seeing , Guardian Mastrus , and Keraal the Ripper in the Chalice District. Progress: The stoneborn forces can never be truly defeated, but they can be quelled for a time.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161540}},ends={{npcID=161540}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58560] = {id=58560,name="Gothic Fashion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Making my way into the city unseen was not as simple as I thought. I trekked through some mud, where I came across these... small men. Perhaps Kleia is right. I draw far too much attention here to be of much use. Perhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.",objectivesText="Collect 5 articles of venthyr clothing from Chalice Residents and Garment Trunks in the Chalice District.",rewardGold=257400,rewardXP=8165,rewardItems={174336,176052,176053,176054,176055},starts={{npcID=165011}},ends={{npcID=161543}},questType="standard"},
[58561] = {id=58561,name="Shards of the Countess",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion , but rather shards of a mirror that will lead to the sinstone's location. Based on the intel you found, we know which three houses hold these shards. Primrose, Darkvein, and Sinfang. Go to their manors and retrieve the shards. We will find the frame to piece them into.",objectivesText="Collect the 3 Shards of the Countess .",rewardGold=257400,rewardXP=8165,rewardItems={174359,174374,174375},starts={{npcID=161540}},ends={{npcID=161544}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58562] = {id=58562,name="Collecting Dust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If I know the Countess, which I do, her sinstone will have stronger protection than mere keys. She is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens. Collect the petals of these flowers so that I may protect us from the dangers to come.",objectivesText="Collect 30 Death Lotus Petals from Death Lotuses in the Redelav District. Progress: I will need many petals to protect the four of us.",rewardGold=257400,rewardXP=8165,starts={{npcID=161544}},ends={{npcID=161544}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58563] = {id=58563,name="Through Glass",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there. With these shards, I can piece it together. We will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.",objectivesText="Go through the mirror, then collect the Countess's Sinstone . Progress: Venthyr carry their pasts as a burden, a weight upon them. The kyrian stand free of ours.",rewardGold=514800,rewardXP=10205,rewardItems={174382,174454,181286},rewardChoices={181286},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161544}},ends={{npcID=161540}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58564] = {id=58564,name="Sins of the Past",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Countess built her reputation on being a native venthyr, never a soul. Revealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek. She will tell us where Alwin is. Where the seal is. This mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here. Don't let her threaten you. You hold the power.",objectivesText="Go through the mirror and face the Countess . Progress: You are lucky that the Curator is by your side, Maw Walker. If you dared this stunt on your own, you would never see your precious Bastion again.",rewardGold=128700,rewardXP=4085,rewardItems={174454},starts={{npcID=161544}},ends={{npcID=161996}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58565] = {id=58565,name="Land of Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong. It is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows. If Alwin is there, it may be too late. Let us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.",objectivesText="Meet Theotar at the Sanctuary of the Mad in the Ember Ward.",rewardGold=25740,rewardXP=1020,starts={{npcID=161544}},ends={{npcID=161515}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58566] = {id=58566,name="Actions Speak Louder than Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="<The ash ghoul inspects you, checking your weapons and armor closely. He shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him. Alwin motions for you to follow him.>",objectivesText="Follow Mindscorched Alwin through the Ashen Traverse.",rewardGold=257400,rewardXP=8165,starts={{npcID=161553}},ends={{npcID=161553}},coords={x=0.4,y=0.59,source="quest_giver",zoneID=10413},questType="standard"},
[58567] = {id=58567,name="Skulking in the Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I had only heard tales of the Ember Ward before now. It's breathtaking... yet terrible. The Light burns the venthyr here, scorching their flesh and driving them mad. The only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary. There is no redemption for them. Only justice.",objectivesText="Kill 8 outcast venthyr in the Ashen Traverse.",rewardGold=257400,rewardXP=8165,starts={{npcID=161540}},ends={{npcID=161540}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58568] = {id=58568,name="Light Respite",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns. And after meeting Alwin and the others here, my heart aches for them. They have lost much of who they once were, and suffer daily for it. Please, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds. It is the least I can do.",objectivesText="Collect 25 Brushberries from the Ashen Traverse. Progress: The denizens of the Ember Ward have suffered enough for their mistakes. The Light goes too far in its punishment.",rewardGold=257400,rewardXP=8165,rewardItems={174497},starts={{npcID=161540}},ends={{npcID=161540}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58569] = {id=58569,name="The Folly of Envy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="<Alwin points at a venthyr on the ledge above. He lets out a slight, low rumble.>",objectivesText="Kill Duke Vielle and retrieve the Seal of Contrition . Progress: Alwin has brought us far. We must retrieve the Seal!",rewardGold=514800,rewardXP=10205,rewardItems={174498},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161553}},ends={{npcID=161540}},coords={x=0.4,y=0.59,source="quest_giver",zoneID=10413},questType="standard"},
[58570] = {id=58570,name="Parting Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1525,description="With the seal in hand, we must return to Bastion . Alwin has received his justice. He has bequeathed the seal to our care. Let us say our goodbyes at the Sanctuary of the Mad, then head home. I look forward to returning to the blue skies and open fields of Bastion .",objectivesText="Speak to the Curator at Sanctuary of the Mad, then return to Elysian Hold. Progress: You return! With good news, I hope?",rewardGold=25740,rewardXP=1020,starts={{npcID=161540}},ends={{npcID=162149}},coords={x=0.564,y=0.414,source="quest_giver",zoneID=10413},questType="standard"},
[58571] = {id=58571,name="The Seal of Contrition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Preparations for the Seal are complete. Go, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.",objectivesText="Place the Seal of Contrition in the Crest of Ascension. Progress: <The orb hangs in front of you. The Seal in your hand pulses quickly.>",rewardGold=25740,rewardXP=1020,rewardItems={174289,174498,177050,178153,179943},rewardChoices={178153,177050,179943,174289},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=162149}},ends={{npcID=357941}},coords={x=0.454,y=0.57,source="quest_giver",zoneID=11012},questType="standard"},
[58575] = {id=58575,name="Stuff We All Get",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new! It can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments. Gather them up for me, would you? Can't let a good weapon go to waste!",objectivesText="Collect 12 Weapons of the Fallen . Progress: The weapons you collect could be wielded by a future champion!",rewardGold=386100,rewardXP=1415,rewardItems={174324},starts={{npcID=161559}},ends={{npcID=161559}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[58582] = {id=58582,name="Return of the Black Prince",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9598,mapID=84,description="Valeera Sanguinar .> , I have just returned from a meeting with King Wrynn in Stormwind. We have much to discuss. Meet me at the Great Seal with haste. Al diel shala, Valeera",objectivesText="Speak with Valeera Sanguinar at the Great Seal in Dazar'alor. Progress: Yes?",rewardGold=23400,rewardXP=850,starts={{npcID=369894}},ends={{npcID=161458}},coords={x=0.585,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[58583] = {id=58583,name="Where the Heart Is",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9667,mapID=84,description="The Speaker has requested that I send you to aid him and Wrathion in their efforts. You have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles. Let us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.",objectivesText="Meet Magni Bronzebeard in the Chamber of Heart.",rewardGold=34100,rewardXP=850,starts={{npcID=161458}},ends={{npcID=152206}},coords={x=0.848,y=0.34,source="quest_giver",zoneID=1519},questType="standard"},
[58584] = {id=58584,name="Right our Wrongs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="General Kaal was sent here on a mission for Denathrius long ago. On that mission, they concealed anima siphons , making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness. These previous actions are in opposition to our goal. Take Theotar and destroy those siphons.",objectivesText="Speak to Theotar at the Eternal Forge. Then, reveal and destroy 5 Concealed Anima Siphons .",rewardGold=257400,rewardXP=8165,rewardItems={180934,180936,180937,180938},starts={{npcID=161526}},ends={{npcID=161526}},coords={x=0.5,y=0.206,source="quest_giver",zoneID=10534},questType="standard"},
[58585] = {id=58585,name="No Friend of Mine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Tools. I cannot work without my tools! Famos, my former apprentice, stole them all when she went to the Forsworn. It breaks my heart. She had so much promise. She must be stopped.",objectivesText="Kill Famos in the Eternal Forge and collect Mikanikos 's Toolchest. Progress: I need my tools. My work cannot be done without them.",rewardGold=514800,rewardXP=10205,rewardItems={174466},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58586] = {id=58586,name="The Right Stuff",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Building something that can help in your mission will require some metal. The constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work. Collect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.",objectivesText="Kill Forsworn constructs and collect and smelt 5 Tainted Centurion Components . Progress: Do you have the metal?",rewardGold=257400,rewardXP=8165,rewardItems={173880,174465},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58589] = {id=58589,name="The Restless Dreamer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. Then we can bring the wildseed's nightmares into the light and dispel them. Take the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual. But be careful. Minions of the Drust seem to be amassing near the grove.",objectivesText="Attune the filled heart of the tree at the shrines in the Dreamshrine Basin. Progress: The spirit dreams.",rewardGold=252720,rewardXP=1415,starts={{npcID=160962}},ends={{npcID=160962}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58590] = {id=58590,name="Visions of the Dreamer: Origins",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world. Go to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.",objectivesText="Grapple with the spirit's vision of their origin. If you leave the Vision, interact with a Dreamer's Vision portal in Dreamshrine Basin to enter again.",rewardGold=252720,rewardXP=1415,starts={{npcID=160962}},ends={{npcID=160962}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58591] = {id=58591,name="Despoilers",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Your efforts at Tirna Noch have enraged the Drust. Those creatures of decay and destruction swell at our borders, and already they pierce our defenses. Now we see their real faces, and know the true nature of our foe. Strike at them. It will buy us time for you to conduct Dreamweaver's ritual.",objectivesText="Slay Witherscorn Drust and Blighted, and vanquish Skell the Despoiler .",rewardGold=505440,rewardXP=1770,starts={{npcID=160894}},ends={{npcID=160894}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[58592] = {id=58592,name="Caring for the Caretakers",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Drust attacked so quickly, they captured some of the spirit tenders of this grove! It's not an easy job to do, between the drought and monsters and everything. I should know. Please, see if you can get them out of whatever terrible magic those invaders have cast on them.",objectivesText="Free Spirit Tenders in the Dreamshrine Basin.",rewardGold=257400,rewardXP=1415,starts={{npcID=160962}},ends={{npcID=160962}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58593] = {id=58593,name="End of the Dream",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The time has come. The ritual will be complete when you have fully entered into the spirit's dreams. It will be as if you are her, in every aspect. She relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved. Speak to me when you are ready to immerse yourself in her nightmare of the end.",objectivesText="Witness the end of the spirit's life. Progress: Have you entered into the spirit's final dream and witnessed her fate?",rewardGold=514800,rewardXP=1770,rewardItems={175647,175660,175661,175662},rewardChoices={175661,175647,175660,175662},starts={{npcID=160962}},ends={{npcID=160962}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58596] = {id=58596,name="Specter Of War: Visectus",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,questType="standard"},
[58599] = {id=58599,name="Drive A Dredge Between Them",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="First, we ruin their operation. Questions can come later. I scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts. Kill those dredgers and everything will grind to a halt.",objectivesText="Kill the 3 large dredgers. Progress: Are you ready?",starts={{npcID=161474}},questType="standard"},
[58600] = {id=58600,name="A Perfect Circle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters. I need one more tool to put it together, a mold. Circular objects difficult to get right. Go up to my old storage. A perfect mold exists there. I'm sure of it. Perhaps in one of my old trunks. Go rummage around for it, will you?",objectivesText="Search for the Perfected Circlet Mold . Progress: Crown must be perfect!",rewardGold=514800,rewardXP=10205,rewardItems={174330,180448,180449,180450},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58601] = {id=58601,name="Web of Information",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=161779,text="Necrotic Sentries destroyed"}},worldTaskTitle="Web of Information",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58603] = {id=58603,name="Phaestus, Genesis of Aeons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Missing something sacred. Forsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!",objectivesText="Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot forge your crown!",rewardGold=514800,rewardXP=10205,rewardItems={174061},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160280}},ends={{npcID=160280}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58605] = {id=58605,name="Amateur Night",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=2,objectID=163226,text="Arena opponent slain"}},worldTaskTitle="Amateur Night",db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[58606] = {id=58606,name="A Bit of Investigation",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="$p, this may be the discovery of a lifetime! I cannot yet say with absolute certainty, but I have a suspicion that these insects are known as the aqir. The League has few intact records, but the last mention of these creatures describes a great war waged between the C'Thraxxi, aqir, and early troll civilizations. We had assumed they were driven to extinction, but they may have simply been... rebuilding. Could you please collect some samples for me to examine?",objectivesText="Collect 16 Aqir Bits . Progress: Have you managed to acquire the samples?",rewardGold=234000,rewardXP=6815,rewardItems={174356},starts={{npcID=164196}},ends={{npcID=164196}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="standard"},
[58608] = {id=58608,name="It's Treason, Then",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We've halted their efforts, but we still have more to do. Sin'dane must have sent someone to oversee the encampment. Find and slay whoever is in charge. Only then can we be sure their work has ended.",objectivesText="Kill Lady Ouix'ara . Progress: Still more schemes...",rewardGold=514800,rewardXP=10205,rewardItems={182386},starts={{npcID=161474}},ends={{npcID=161865}},questType="standard"},
[58609] = {id=58609,name="Taking The Seat",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="A wise choice, . Under your command, we will restore honor and glory to Maldraxxus. Your strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential. For now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.",rewardGold=25740,rewardXP=1020,ends={{npcID=158453,x=0.496,y=0.224,zoneID=12876}},questType="world",worldTaskTitle="Taking The Seat"},
[58610] = {id=58610,name="The Speaker of Elune",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Fortune smiles upon us, . We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. His name is Thiernax . I am told he assists in tending to the spirits resting in the Garden of Night. Seek him out and petition him for aid. I pray he will have wisdom to share.",objectivesText="Find Thiernax near the Queen's Garden. Progress: Oh, dear.",rewardGold=25740,rewardXP=1020,starts={{npcID=160262}},ends={{npcID=161786}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[58615] = {id=58615,name="Whispers in the Dark",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="Did ye hear that as well? That cannae be good. If N'Zoth gains access tae this chamber, we'll all be done for! We need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!",objectivesText="Find the source of N'Zoth's whispers in the Chamber of Heart.",rewardGold=468000,rewardXP=8520,starts={{npcID=161805}},ends={{npcID=152206}},coords={x=0.498,y=0.586,source="quest_giver",zoneID=12905},questType="standard"},
[58616] = {id=58616,name="Forging a Champion",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Of all the souls who have reached that stone, only you discovered its true purpose. I am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further. Find Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus , and the last remaining apprentice of the Primus himself. She will know what course to take.",objectivesText="Speak with Bonesmith Heirmir about your runeblade. Progress: Something else?",rewardGold=257400,rewardXP=1415,starts={{npcID=159065}},ends={{npcID=157676}},coords={x=0.388,y=0.652,source="quest_giver",zoneID=11462},questType="standard"},
[58617] = {id=58617,name="Maintaining Order",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard. Deliver my orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix . And do it quickly. Every moment we waste is one our enemy will have to their advantage!",objectivesText="Deliver orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix .",rewardGold=243360,rewardXP=1415,starts={{npcID=157895}},ends={{npcID=157895}},coords={x=0.362,y=0.602,source="quest_giver",zoneID=11462},questType="standard"},
[58618] = {id=58618,name="Ossein Enchantment",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A potent blade requires potent components. I know of something that would suit our needs. Recently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind. Hmph. The will of the Primus trumps the desires of an ambitious baron! The bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.",objectivesText="Slay Marrowjaw and collect an Empowered Bone from its corpse. Progress: Brave enough to manage this?",rewardGold=243360,rewardXP=1415,rewardItems={174499},starts={{npcID=157676}},ends={{npcID=157676}},coords={x=0.362,y=0.708,source="quest_giver",zoneID=11462},questType="standard"},
[58619] = {id=58619,name="Read Between the Lines",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ah, mortal, how fortunate that I, humble Ta'eran , happen to be standing here just as you, the outsider everyone is talking about, happens to wander by! In the spirit of cooperation and mutual interests, there is a matter I wish to discuss. A nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost. If you would do me the honor of escorting me to the Sepulcher, I can share what else I know.",objectivesText="Follow Ta'eran to the Sepulcher of Knowledge and hear his proposal.",rewardGold=365040,rewardXP=1415,starts={{npcID=166657}},ends={{npcID=166664}},coords={x=0.406,y=0.33,source="quest_giver",zoneID=11462},questType="standard"},
[58620] = {id=58620,name="Slaylines",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Gaining entrance to the Sepulcher is no easy feat, ! Not only were guardians put in place, but an elaborate magical lock was created to seal the door. To open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose. Locate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!",objectivesText="Connect the anima flow to the Unlocking Obelisks. Progress: Have you activated the two obelisks?",rewardGold=386100,rewardXP=1415,starts={{npcID=166664}},ends={{npcID=166664}},coords={x=0.43,y=0.252,source="quest_giver",zoneID=11462},questType="standard"},
[58621] = {id=58621,name="Repeat After Me",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses. To gain entrance, you must prove yourself worthy by besting these protectors. Seek out the rune stones that represent the houses of Maldraxxus . Pay attention to the words inscribed on each stone, then pay deference each house's values. If you honor the stone, its protector will come forth. Defeat each of them.",objectivesText="Read the rune stones of the five houses, then honor them by performing the correct /emote at each stone. Progress: The Primus was clever indeed.",rewardGold=386100,rewardXP=1415,rewardItems={175707},rewardChoices={175707},starts={{npcID=166664}},ends={{npcID=166664}},coords={x=0.43,y=0.252,source="quest_giver",zoneID=11462},questType="standard"},
[58622] = {id=58622,name="Secrets Among the Shelves",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Now that the door to the Sepulcher is unlocked, we can venture inside. And by \"we\", I mean \"you\". Until it's safe, at least. The volumes within contain the collected wisdom of the greatest military minds of Maldraxxus . For the good of the Necrolords, do whatever is needed to gather these precious volumes. It is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge. Once you clear a path, I'll join you.",objectivesText="Recover volumes of the tomes kept within the Sepulcher. Progress: Were you successful?",rewardGold=368550,rewardXP=1415,starts={{npcID=166664}},ends={{npcID=170667}},coords={x=0.43,y=0.252,source="quest_giver",zoneID=11462},questType="standard"},
[58623] = {id=58623,name="A Complete Set",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This is only volume one? We can't just take the first volume. A rare item like this is only useful if it's in a complete set! Grab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.",objectivesText="Collect Volumes of Victory. Progress: Did we get all the volumes?",rewardGold=375570,rewardXP=1415,rewardItems={174377,178019},starts={{npcID=166806}},ends={{npcID=166806}},coords={x=0.452,y=0.32,source="quest_giver",zoneID=11462},questType="standard"},
[58624] = {id=58624,name="Pauldrons of Imperium",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1525,description="Now we know who is responsible for the unrest in Maldraxxus. If Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. We must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat. For now, return the pauldrons to the Seat of the Primus. I will meet you there.",objectivesText="Return to the Seat of the Primus with the Pauldrons of Imperium .",rewardGold=772200,rewardXP=12250,rewardItems={182255,182264,182273,182282},rewardChoices={182273,182264,182282,182255},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161865}},ends={{npcID=161907}},coords={x=0.78,y=0.622,source="quest_giver",zoneID=10413},questType="standard"},
[58625] = {id=58625,name="Connecting the Dots",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting. He went off to meet with some member of the House of Rituals. There were a few of his guards with him. While it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.",objectivesText="Search the Forgotten Wounds for the previous baron.",rewardGold=257400,rewardXP=1415,questType="standard"},
[58630] = {id=58630,name="Crown of the Harvesters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. Without the blessing of the flames, I fear it will overwhelm the wearer. Bring venthyr friend. His magic will prove useful. Need you to absorb impurities. Mikanikos hands you an elegant container.> Use this to capture imperfections that burn off during the process.",objectivesText="Meet Mikanikos at the Eternal Forge. Then, assist him with forging the Crown of the Harvesters. Progress: It is done then?",rewardGold=128700,rewardXP=4085,starts={{npcID=160280}},ends={{npcID=174587}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[58631] = {id=58631,name="Into Dreams",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him! There must be a way tae find out where he went. Let's see if MOTHER can track him down!",objectivesText="Speak with MOTHER in the Chamber of Heart to track Ra-den's location. Progress: We're runnin' outta time!",rewardGold=23400,rewardXP=850,rewardItems={173363},starts={{npcID=152206}},ends={{npcID=152206}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[58632] = {id=58632,name="Ny'alotha, the Waking City: The Corruptor's End",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it. That is, until now. Take these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire. Ye'll only get one shot. Make it count!",objectivesText="Defeat N'Zoth in Ny'alotha, the Waking City. Progress: It's time tae blast N'Zoth back tae the void he came from!",rewardGold=936000,rewardXP=13630,rewardCurrencies={{id=1553,amount=3000}},starts={{npcID=152206}},ends={{npcID=152206}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="raid"},
[58634] = {id=58634,name="Opening the Gateway",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="The fabric of reality is torn. But there's no need for me to tell you that, . You've seen it firsthand. It's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness. With the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts. After all, the key to understanding an enemy's weakness is to understand their intentions.",objectivesText="Speak with MOTHER to establish the Tenebrous Gateway in the Chamber of Heart. Progress: Uncertainty comes before discovery.",rewardGold=40125,rewardXP=5110,rewardCurrencies={{id=1755,amount=10000}},starts={{npcID=155496}},ends={{npcID=155496}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[58636] = {id=58636,name="Eyes on the Amathet",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen. In the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection. I was hopin' ye could help out with that. Think ye could spare some time tae see what they're all about? We can start with an aerial look.",objectivesText="Scout the Amathet territories with High Explorer Dellorah in Uldum . Progress: To the skies!",rewardGold=117000,rewardXP=3410,starts={{npcID=155102}},ends={{npcID=155102}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="standard"},
[58638] = {id=58638,name="A Deeper Dive",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination? I think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.",objectivesText="Defend High Explorer Dellorah as she deciphers the Amathet Monument at Sunstone Terrace. Progress: I'm ready when ye are, <class>.",rewardGold=234000,rewardXP=6815,starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58639] = {id=58639,name="Buried History",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands . It looks like it's time for a good old-fashioned dig! The dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!",objectivesText="Uncover and collect 6 Amathet Artifacts in Uldum . Progress: What have ye turned up?",rewardGold=234000,rewardXP=6815,rewardItems={174450},starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58640] = {id=58640,name="A Crack in the Armor",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. This confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect. We should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.",objectivesText="Defend High Explorer Dellorah as she deciphers the Amathet Monument outside the Halls of Origination. Progress: I cannae wait tae solve this mystery!",rewardGold=234000,rewardXP=6815,starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58641] = {id=58641,name="Seekers of Corruption",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out. Of course, I doubt they'll be willing to turn over any information voluntarily. Luckily for me, you're a bit of a specialist at brute force investigation, aren't you?",objectivesText="Collect the Sun King's Decree from Suntouched Amathet in Uldum . Progress: Found anything from the Suntouched?",rewardGold=234000,rewardXP=6815,rewardItems={174451},starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58642] = {id=58642,name="Shared Goals",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="The decree you found made mention of a plan to defeat the Old Gods. I know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it. The decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!",objectivesText="Defend High Explorer Dellorah as she deciphers the Amathet Tablets within the Chamber of the Stars. Progress: Let's see what we can find in the Chamber of the Stars.",rewardGold=234000,rewardXP=6815,starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58643] = {id=58643,name="Mutually Assured Destruction",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! They could strike at any moment. We have tae warn the defenders of the Forge!",objectivesText="Warn the defenders of the Halls of Origination about the Amathet's plan.",rewardGold=23400,rewardXP=850,starts={{npcID=155102}},ends={{npcID=161031}},questType="standard"},
[58645] = {id=58645,name="A World Worth Saving",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="We could not stand against them. Their warriors... wreathed in the sun's flames... They want the forge... to end all... Go... I will... endure...",objectivesText="Stop the Amathet from taking the Halls of Origination.",rewardGold=23400,rewardXP=850,rewardCurrencies={{id=1553,amount=1500}},starts={{npcID=161031}},ends={{npcID=155102}},coords={x=0.72,y=0.522,source="quest_giver",zoneID=10833},questType="standard"},
[58646] = {id=58646,name="Chew On This!",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="These mangy hyena will gnaw on anything they dig up, including priceless artifacts! We cannae allow the history of Uldum tae go tae the dogs, so tae speak. I'm afraid we're gonna have tae thin out their numbers.",objectivesText="Kill 8 Scavenging Dunerunners in Uldum . Progress: Did ye take care of the hyenas?",rewardGold=234000,rewardXP=6815,starts={{npcID=155102}},ends={{npcID=155102}},questType="standard"},
[58647] = {id=58647,name="Broken Webs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least. Spriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.",objectivesText="Help repair soul webs. Progress: Just one more.",rewardGold=257400,rewardXP=8165,starts={{npcID=161786}},ends={{npcID=161786}},coords={x=0.402,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[58654] = {id=58654,name="A Plea to the Harvesters",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. What souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet. If you have the ear of Lord Chamberlain , then you might be able to pass a message to the Master himself. Here, take this letter. Please see that it makes it to the hands of the Chamberlain.",objectivesText="Deliver Mihaela's Note to the Lord Chamberlain . Provided item:",rewardGold=25270,rewardXP=175,rewardItems={174482},starts={{npcID=156822}},ends={{npcID=156374}},coords={x=0.614,y=0.638,source="quest_giver",zoneID=10413},questType="standard"},
[58656] = {id=58656,name="Heavy is the Head...",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve. Socketed one of your medallions. Witness its power focused into a weapon of destruction. Perfect opportunity. Forsworn finished colossi construction. Destroy them. Bring the Forsworn the end they crave. Careful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.",objectivesText="Test the Crown of the Harvesters and defeat the Operational Colossi. Progress: Bring the Forsworn the destruction they crave.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174587}},ends={{npcID=161526}},coords={x=0.514,y=0.184,source="quest_giver",zoneID=10534},questType="standard"},
[58664] = {id=58664,name="Ultimate Makeover",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls. Emeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard. You will assist me in rebuilding Emeni's construct.",objectivesText="Help Rathan rebuild Emeni's Construct.",rewardGold=257400,rewardXP=8165,questType="standard"},
[58665] = {id=58665,name="Rebellious Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Please hear us out, Maw Walker. When Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. Fearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not. Help us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.",objectivesText="Meet Rathan and Emeni at Sixfold Recluse.",rewardGold=25740,rewardXP=1020,starts={{npcID=162222}},ends={{npcID=162108}},coords={x=0.482,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[58668] = {id=58668,name="Find The Way",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct. If we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. Lead us to there and we'll see if we can get it operational.",objectivesText="Lead Rathan and Emeni to the Body Banks.",rewardGold=128700,rewardXP=4085,starts={{npcID=162108}},ends={{npcID=162227}},coords={x=0.26,y=0.426,source="quest_giver",zoneID=11462},questType="standard"},
[58669] = {id=58669,name="A Little Pruning",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them. Usually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood. Qadarin shakes his head.> You would be doing me a favor if you helped me clear the Queen's garden of these vermin.",objectivesText="Slay 15 Sicklethorn spriggan. Progress: At least here we only have to worry about spriggans. Other parts of the forest are not so fortunate.",rewardGold=257400,rewardXP=8165,starts={{npcID=161786}},ends={{npcID=161786}},coords={x=0.402,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[58670] = {id=58670,name="The Slaughter Daughter",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list! Help me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak , who is number one on the list!",objectivesText="Help Emeni slaughter everyone on her list.",rewardGold=257400,rewardXP=8165,starts={{npcID=162174}},ends={{npcID=162174}},coords={x=0.234,y=0.356,source="quest_giver",zoneID=11462},questType="standard"},
[58671] = {id=58671,name="Bottled Up Inside",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima. My friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!",objectivesText="Rescue 10 Imprisoned Souls in the Etheric Vault.",rewardGold=257400,rewardXP=8165,starts={{npcID=162174}},ends={{npcID=162174}},coords={x=0.234,y=0.356,source="quest_giver",zoneID=11462},questType="standard"},
[58672] = {id=58672,name="A Gathering of Champions",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=84,description="The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde. As a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar. I will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others. Make haste, champion. The future of the Horde is about to be decided...",objectivesText="Speak with Valeera Sanguinar in Orgrimmar.",starts={{npcID=161458}},ends={{npcID=162190}},coords={x=0.848,y=0.34,source="quest_giver",zoneID=1519},questType="standard"},
[58673] = {id=58673,name="Warchief of the Horde",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=84,description="The meeting to decide the next Warchief of the Horde is about to begin. The other leaders of the Horde have already arrived. They are waiting for you inside the embassy. Speak with me when you are ready, and we will greet the others together.",objectivesText="Witness the gathering of champions.",starts={{npcID=162190}},ends={{npcID=162190}},coords={x=0.538,y=0.148,source="quest_giver",zoneID=1519},questType="standard"},
[58674] = {id=58674,name="A Gathering of Champions",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=1161,description="King Wrynn has called for an audience with the Alliance leaders in Stormwind. Your presence at the meeting has been specifically requested. The gathering will be held at the embassy. Come speak with me when you arrive in Stormwind, I'll be waiting with the others. Do hurry, . It would be ill-advised to keep the king waiting...",objectivesText="Speak with Master Mathias Shaw in Stormwind.",starts={{npcID=135614}},ends={{npcID=162178}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[58675] = {id=58675,name="The Price of Peace",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="The king will be addressing us shortly with news from his diplomatic mission to the Horde. The other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say. Speak with me when you are ready, and we will greet the king together.",objectivesText="Witness King Wrynn's address.",starts={{npcID=162178}},ends={{npcID=162178}},coords={x=0.532,y=0.15,source="quest_giver",zoneID=1519},questType="standard"},
[58677] = {id=58677,name="Skin in the Game",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This task is probably above your capabilities, but listen anyway. As a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect. When I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir. Kill Faldo Iscar, and get my skin back!",objectivesText="Emini's Magnificent Skin obtained Progress: When I was alive, you might have been my friend... or maybe my dinner.",rewardGold=514800,rewardXP=10205,rewardItems={174520,181456},starts={{npcID=161285}},ends={{npcID=161285}},coords={x=0.242,y=0.386,source="quest_giver",zoneID=11462},questType="standard"},
[58680] = {id=58680,name="Loose Threads",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct! Search the surrounding area. See if you can find us what we need. Search tables for the Skewering Needles , you can find haulers that carry Razorthread Spools , and look for Clotting Patches on constructs you kill.",objectivesText="Locate Skewering Needles , Razorthread Spools and Clotting Patches . Progress: You are good at this.",rewardGold=257400,rewardXP=8165,rewardItems={174524,174526,174534},starts={{npcID=162227}},ends={{npcID=162227}},coords={x=0.242,y=0.386,source="quest_giver",zoneID=11462},questType="standard"},
[58686] = {id=58686,name="Weapon of Mass Construction",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We are in luck! Surgeon Stitchflesh and his assistant have not returned from Bastion. The entire Stitchyard is lightly guarded. We must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.",objectivesText="Get the assembly lab operational. Progress: We will control the means of production!",rewardGold=128700,rewardXP=4085,starts={{npcID=162227}},ends={{npcID=162227}},coords={x=0.242,y=0.386,source="quest_giver",zoneID=11462},questType="standard"},
[58704] = {id=58704,name="The Garden of Night",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband. Hopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.",objectivesText="Slay spriggans in the central garden. Progress: This is my fault... just like before...",rewardGold=514800,rewardXP=10205,rewardItems={175581,179766,179889,181910},rewardChoices={175581,179766,181910,179889},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161934}},ends={{npcID=161785}},questType="standard"},
[58706] = {id=58706,name="Dressing the Kill",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I believe I understand, . But I cannot help you right now. Allow me to explain. In the meantime, will you carve up this carcass with me? Your prey always has something to teach you.",objectivesText="Help Huln Highmountain carve up the devourer. Progress: The more quickly you carve, the more quickly I can help you.",rewardGold=128700,rewardXP=4085,starts={{npcID=161353}},ends={{npcID=161353}},coords={x=0.3,y=0.448,source="quest_giver",zoneID=11510},questType="standard"},
[58707] = {id=58707,name="Sorting Through Visions",level=50,requiredLevel=50,faction="none",expansion=8,rewardItems={173363},questType="standard"},
[58708] = {id=58708,name="Fame Waits for Gnome One",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=8568,mapID=84,description="Tinkmaster Overspark requests your assistance on an important research expedition. Working with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!",objectivesText="Meet with Tinkmaster Overspark in Boralus.",rewardGold=2000,rewardXP=1415,starts={{npcID=162393}},ends={{npcID=150208}},coords={x=0.526,y=0.142,source="quest_giver",zoneID=1519},questType="standard"},
[58714] = {id=58714,name="The Forest Has Eyes",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice? Sorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! They must be hunted down and slain before they can report back on the grove's defenses. Here, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!",objectivesText="Slay hidden Possessed Spies throughout Hibernal Hollow. Progress: Have you uncovered all those pesky spies yet?",rewardGold=252720,rewardXP=1415,starts={{npcID=161847}},ends={{npcID=160894}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58717] = {id=58717,name="Bell of Remembrance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="<The bell is scratched and damaged. You remember the Curator being very interested in this item. Maybe someone at the Crypt of the Forgotten will know more.>",objectivesText="Find someone who knows more about the bell at the Crypt of the Forgotten.",rewardGold=128700,rewardXP=4085,ends={{npcID=161418}},coords={mapID=1525,source="quest_giver",x=0.732,y=0.34},questType="standard"},
[58719] = {id=58719,name="The Droman's Call",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Our enemies close in swiftly, . We must sound the call to defend the grove! Use this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.",objectivesText="Use the Droman's Horn to summon the Wild Hunt at the entrances to the grove. Progress: The Hunt will hear our call and ride to defend the grove!",rewardGold=126360,rewardXP=710,rewardItems={174864},starts={{npcID=160894}},ends={{npcID=160894}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[58720] = {id=58720,name="Missing!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces. She had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble. Find her and provide whatever aid she requires. We need her hunters and her leadership if our defenses are to hold.",objectivesText="Find Hunt-Captain Korayn on the Path of Rebirth.",rewardGold=25270,rewardXP=175,starts={{npcID=160894}},ends={{npcID=162541}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[58721] = {id=58721,name="Awaken the Dreamer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds. Perhaps it is fitting you carry a wounded spirit with you. Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.> This one fights with all of her being. Even now she clings to existence. Come, stranger, let us see what fate the Queen will decree for this one.",objectivesText="Travel to the Grove of Awakening.",rewardGold=126360,rewardXP=710,starts={{npcID=169869}},ends={{npcID=162968}},coords={x=0.48,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[58723] = {id=58723,name="The Court of Winter",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12858,mapID=1565,description="My Court informs me that you bear an important message. You may now deliver it.",objectivesText="Give the Primus's message to the Winter Queen . Progress: The ancient enemy has not been idle...",rewardGold=128700,rewardXP=710,rewardItems={175710},rewardChoices={175710},starts={{npcID=162968}},ends={{npcID=162968}},coords={x=0.452,y=0.63,source="quest_giver",zoneID=11510},questType="standard"},
[58724] = {id=58724,name="The Queen's Request",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1565,description="Dire portents indeed. I have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker. Keeping the Banished One bound within the Maw will require more anima than Ardenweald can spare. Sire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid. Your allies in Oribos can open the way.",objectivesText="Return to Tal-Inara in Oribos.",rewardGold=505440,rewardXP=1770,starts={{npcID=162968}},ends={{npcID=162968}},coords={x=0.452,y=0.63,source="quest_giver",zoneID=11510},questType="standard"},
[58725] = {id=58725,name="Sinkeeper",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This is a Bell of Remembrance . Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. If they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt. Let's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.",objectivesText="Use the Bell of Remembrance to beckon a soul from the Crypt of the Forgotten. Then, deem the soul's fate.",rewardGold=309800,rewardXP=8165,rewardItems={174741},starts={{npcID=161418}},ends={{npcID=161418}},coords={x=0.732,y=0.34,source="quest_giver",zoneID=10413},questType="standard"},
[58726] = {id=58726,name="Thick Skin",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The Primus forged a fine blade, but it will do you no good in its current state. Fortunately for you, I possess the skill to finish his work! That being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor. That's where you come in. You want a new blade? You'll have to earn it.",objectivesText="Collect 40 Pulsating Hide Scraps from Overgrown Masses. Progress: Can't be that difficult, can it?",rewardGold=243360,rewardXP=1415,rewardItems={175462,175463,175464,175465,178676},rewardChoices={175463,175464,175465,175462},starts={{npcID=157676}},ends={{npcID=157676}},coords={x=0.362,y=0.708,source="quest_giver",zoneID=11462},questType="standard"},
[58727] = {id=58727,name="A Place To Call Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You didn't end up on my list... so, I guess we're friends... for the moment. Rathan took the soul you freed to Butchers Block near the Seat of the Primus. Let us meet him there and plan our next step together.",objectivesText="Meet up with Rathan and Emeni at Butchers Block.",rewardGold=25740,rewardXP=1020,starts={{npcID=162174}},ends={{npcID=167150}},coords={x=0.234,y=0.356,source="quest_giver",zoneID=11462},questType="standard"},
[58737] = {id=58737,name="Magni's Findings",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=1473,description="As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults! Ye might want tae be sittin' down for this one, champion.",objectivesText="Learn Magni's findings. Progress: Pay attention, champion!",rewardGold=23400,rewardXP=850,starts={{npcID=152206}},ends={{npcID=152206}},coords={x=0.502,y=0.584,source="quest_giver",zoneID=9667},questType="standard"},
[58750] = {id=58750,name="Take the Bull by the Horns",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus! You do some work for me, and people will know who you are as well. Take this bone splinter and poke a few juicy nibblers . Use them to lure a tauralus to you, then ride it back to me.",objectivesText="Ride 5 Bloodskin Tauraluses back to Dundae . Progress: You want to be famous? Get the tauraluses I wanted?",rewardGold=368550,rewardXP=1415,rewardItems={174749,174751},starts={{npcID=162474}},ends={{npcID=162474}},coords={x=0.468,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[58751] = {id=58751,name="A Common Peril",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals. I have not heard from her since. Either she has found something... or has become another casualty of their treachery. Her orders took her to the Decay in the east. If you can find the baroness, give her this summons. We were not friends, she and I, but she is a formidable combatant. We could use her might.",objectivesText="Locate the lost baroness in the Renounced Bastille. Progress: Someone new...but someone familiar.",rewardGold=24335,rewardXP=175,rewardItems={174755},starts={{npcID=168381}},ends={{npcID=162487}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=11462},questType="standard"},
[58769] = {id=58769,name="REUSE ME",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,description="Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband. But I will get them back. If you are our new champion then you will help me for the good of Ardenweald . Death did not part us. I will not be torn from him now.",objectivesText="Ride with Thiernax after the Drust.",rewardGold=257400,rewardXP=8165,questType="standard"},
[58771] = {id=58771,name="Directions Not Included",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over. We need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago. Luckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help. Look around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.",objectivesText="Find the Locus Manual among discarded scrolls in the Mnemonic Locus. Progress: You find correct scroll?",rewardGold=238680,rewardXP=1415,rewardItems={178046,178092},starts={{npcID=167034}},ends={{npcID=167034}},coords={x=0.572,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[58773] = {id=58773,name="The Thornspeaker Captive",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Good to know the old bear hasn't forgotten me. Unfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up. Do not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander. They should be somewhere nearby. Find them.",objectivesText="Rescue Kivarr from Eventide Grove in Ardenweald . Progress: I would love to help you, but as you can see... I am not exactly free to leave.",rewardGold=257400,rewardXP=8165,rewardItems={180777,182639,182641},starts={{npcID=171413}},ends={{npcID=173612}},coords={x=0.462,y=0.564,source="quest_giver",zoneID=11510},questType="standard"},
[58775] = {id=58775,name="Meet the Queen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1533,description=", we need only one more piece to complete the Crest of Ascension. Eons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest. Seek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.",objectivesText="Gain an audience with the Winter Queen at the Heart of the Forest in Ardenweald.",rewardGold=128700,rewardXP=4085,starts={{npcID=160037}},ends={{npcID=162392}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58785] = {id=58785,name="Smack and Grab",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Bonetooths are the backbone of Maldraxxus 's armed forces. Those that have been trained well are in demand amongst all of the houses. I always need new bonetooths to train, but they can be rather difficult to collect. Bring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.",objectivesText="Capture 10 Neonate Bonetooths. Progress: Bring me back some bonetooths!",rewardGold=386100,rewardXP=1415,starts={{npcID=162615}},ends={{npcID=162615}},coords={x=0.47,y=0.49,source="quest_giver",zoneID=11462},questType="standard"},
[58787] = {id=58787,name="Trial of Ascension",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended. Our generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces. Kleia is amongst the chosen, and thus must complete her final trial. As Pelagos is not yet prepared to ascend, I request you be Kleia 's partner for this process. It is arduous and should not be embarked on alone. She must bear her first soul.",objectivesText="Meet Kleia at the Court of Elation.",rewardGold=30900,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=162542}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58788] = {id=58788,name="Censers of Guidance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=49,description="The Forsworn are going to great lengths to prevent us from ascension. They mobilize to stand in our way, to dismantle our chances to partake in our rituals. They have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.",objectivesText="Collect 10 Incense of Guidance from Forsworn forces. Progress: Each censer will require considerable incense. We must make sure we gather enough.",rewardGold=257400,rewardXP=8165,rewardItems={174821},starts={{npcID=162542}},ends={{npcID=162542}},coords={x=0.326,y=0.398,source="quest_giver",zoneID=44},questType="standard"},
[58789] = {id=58789,name="Misguiding Mentors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="These aspirants... we trained together. Learned together. The Forsworn have swayed them from the path, now leading them to their demise. They betray the path. Take out the Ascended that lead these forces against us.",objectivesText="Kill Strategist Palladia and Instructor Herus . Progress: For an Ascended to use the trust their aspirants have in them... They do not deserve their wings.",rewardGold=514800,rewardXP=10205,rewardItems={174297,177058,178161,179948},rewardChoices={174297,178161,177058,179948},starts={{npcID=162544}},ends={{npcID=162544}},coords={x=0.32,y=0.21,source="quest_giver",zoneID=10534},questType="standard"},
[58790] = {id=58790,name="To Cross the Veil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=49,description="Pallessa found a scroll detailing the ritual. We will need to take our positions and speak a chant, surrendering some of our anima with every word. Your presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.",objectivesText="Aid Kleia in the Rite of Guidance.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=162542}},ends={{npcID=162558}},coords={x=0.326,y=0.398,source="quest_giver",zoneID=44},questType="standard"},
[58791] = {id=58791,name="A Day in the Life",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=44,mapID=49,description="A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands. This soul is ready to move on. During this trial, you will experience his final moments before his death. When you are prepared, you shall see how this soul passed.",objectivesText="Witness Ben Howell 's final moments.",rewardGold=25740,rewardXP=1020,starts={{npcID=162558}},ends={{npcID=162953}},coords={x=0.326,y=0.398,source="quest_giver",zoneID=44},questType="standard"},
[58792] = {id=58792,name="Where a Soul Belongs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=49,description="This soul is no longer tethered to his world of Azeroth. Kleia must perform her duty and bear him to Oribos to be judged by the Arbiter. Take this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos. Go in service.",objectivesText="Use the Vesper of Veilflight to travel to Oribos, then witness Ben Howell's judgment. Progress: It is the duty of all kyrian to ferry souls to Oribos.",rewardGold=128700,rewardXP=4085,rewardItems={175011},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=162558}},ends={{npcID=162542}},coords={x=0.326,y=0.398,source="quest_giver",zoneID=44},questType="standard"},
[58793] = {id=58793,name="Faith Through the Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=49,description="This drought is... so much larger than I imagined. Why did nobody tell us? The burden of this knowledge weighs heavy... do we bear souls to their eternal torture? We must return home.",objectivesText="Return to Adrestes in Elysian Hold.",rewardGold=25740,rewardXP=1020,starts={{npcID=162542}},ends={{npcID=160037}},coords={x=0.326,y=0.398,source="quest_giver",zoneID=44},questType="standard"},
[58794] = {id=58794,name="Stabbing Wasteward",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much! I spotted the one that's responsible for the slaughter just west of here. Get rid of it! And don't mention this to Caleesy!",objectivesText="Slay the Satiated Sawtooth . Progress: I hope you put an end to that creature.",rewardGold=386100,rewardXP=1415,rewardItems={174749,174751},starts={{npcID=162474}},ends={{npcID=162474}},coords={x=0.468,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[58795] = {id=58795,name="Ascended",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="With success over their trials, our aspirants shall now start the next chapter of their afterlives. They have proven themselves through eons of training and cleansing, and will now earn ascendance. As each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.",objectivesText="Assist Pelagos with the ascension ceremony.",rewardGold=128700,rewardXP=4085,rewardItems={174293,177054,178157,179944},rewardChoices={178157,177054,179944,174293},starts={{npcID=160037}},ends={{npcID=163650}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58796] = {id=58796,name="The Forsworn Onslaught",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Loyalty's betrayal shall not go unnoticed. But while the Paragons defend the city proper, it is up to us to defend Elysian Hold. I am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!",objectivesText="Repel the Forsworn invasion. Progress: Devos... she goes too far.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=163650}},ends={{npcID=163650}},coords={x=0.516,y=0.478,source="quest_giver",zoneID=11012},questType="standard"},
[58797] = {id=58797,name="Forged by Trial",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description=", my friend. I have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion ... I knew you would be a boon unto our ranks. Our bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did. I wish to cement our bond. I would be honored to soulbind with you.",objectivesText="Complete the soulbinding ritual with Kleia . Progress: You are an important part in my journey. I respect you greatly, and hope you feel the same.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=163650}},ends={{npcID=163650}},coords={x=0.516,y=0.478,source="quest_giver",zoneID=11012},questType="standard"},
[58798] = {id=58798,name="The Spires of Ascension",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Our task is not complete yet. We may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces. The Archon and the Paragons fight to retake the Spires themselves. We cannot hesitate to aid them in this time of need!",objectivesText="Kill Devos, Paragon of Doubt in the Spires of Ascension.",rewardGold=514800,rewardXP=1770,rewardItems={181743},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160390},{npcID=163650}},ends={{npcID=160037}},coords={x=0.642,y=0.166,source="quest_giver",zoneID=10534},questType="dungeon"},
[58799] = {id=58799,name="The Prime's Directive",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="All centurion are made to serve the kyrian. That they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion . Look at them! Praetors! Goliaths! All... PURPLE! I hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus. I can build more. Do not pity.",objectivesText="Collect 12 Centurion Cores . Progress: You have the cores?",rewardGold=257400,rewardXP=1415,rewardItems={178094},starts={{npcID=167034}},ends={{npcID=167034}},coords={x=0.572,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[58800] = {id=58800,name="The Mnemonic Locus",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Mikanikos examines the scroll you retrieved for him.> Right, right. Soul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient. All I need to do is enable conduits. Simple! Well? Go on. You know how to use these, yes?",objectivesText="Use the Anima Conduits to restore the Mnemonic Locus. Progress: I wait to hear the hum of anima, yes.",rewardGold=119340,rewardXP=710,rewardItems={175704},rewardChoices={175704},starts={{npcID=167034}},ends={{npcID=167034}},coords={x=0.572,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[58801] = {id=58801,name="Enter the Void",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="My faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...",objectivesText="Without dying or leaving Void Wraith form, sacrifice 10 players to N'Zoth.",rewardGold=468000,rewardXP=8520,starts={{npcID=341831}},coords={x=0.603,y=0.51,source="quest_giver",mapID=1527},questType="standard"},
[58802] = {id=58802,name="The Incredible Egg",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="<The aqir seem to have been in the process of empowering this egg with void magic. It looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. Someone in the Explorers' League might be interested in taking a look.>",objectivesText="Bring the Voidtouched Egg to H'partho Adoros in Ramkahen.",rewardGold=23400,rewardXP=850,starts={{npcID=343611}},ends={{npcID=161738}},coords={x=0.208,y=0.62,source="quest_giver",zoneID=10833},questType="standard"},
[58803] = {id=58803,name="Match the Hatch",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they? Of course, we have no idea how to take care of such an egg. I will need you to do some investigating. Head back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.",objectivesText="Investigate 7 Voidtouched Eggs in Uldum . Progress: What have you learned among the aqir?",rewardGold=234000,rewardXP=6815,starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58804] = {id=58804,name="Void Incubation",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. It is fortunate for us that an Old God is attacking Azeroth at this very moment, yes? No? Oh... In any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.",objectivesText="Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Have you found a reliable source of void energy?",rewardGold=234000,rewardXP=6815,rewardItems={174993},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58805] = {id=58805,name="Continued Incubation",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The egg is doing well, but we're going to need more of those void crystals to keep it healthy. Could you go out and gather some?",objectivesText="Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Did you bring more void crystals?",rewardGold=234000,rewardXP=6815,rewardItems={174993},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58806] = {id=58806,name="Warmth of the Sun",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures. These Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy. Keep your eyes open for something we can use.",objectivesText="Collect an Amathet Solar Collector in Uldum . Progress: Did you find anything among the Amathet?",rewardGold=234000,rewardXP=6815,rewardItems={174996},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58807] = {id=58807,name="Wrapping Up",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. I believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some. While you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.",objectivesText="Collect 30 pieces of Aqir Webbing from aqir casters in Uldum . Progress: Did you find some suitable webbing?",rewardGold=234000,rewardXP=6815,rewardItems={175001},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58808] = {id=58808,name="Encased in Amber",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="You know who would probably know a lot about how to properly incubate this egg? The mantid! Of course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge! Perhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure! If you could find and mark one for me, I could airlift it out of there.",objectivesText="Mark an Amber Incubator for H'partho to airlift in the Vale of Eternal Blossoms.",rewardGold=234000,rewardXP=6815,rewardItems={175002},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58809] = {id=58809,name="A Shocking Technique",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend? There's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. If they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.",objectivesText="Collect 8 Lightning Rod Components from the Vale of Eternal Blossoms. Progress: Were you able to collect the proper components?",rewardGold=234000,rewardXP=6815,rewardItems={175003},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58810] = {id=58810,name="Coming Out of His Shell",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="It looks like our egg is ready to hatch! Isn't this exciting! Come, let us welcome our new little friend to this world.",objectivesText="Watch the Aqir Egg hatch in Ramkahen. Progress: Oh, the anticipation!",rewardGold=468000,rewardXP=8520,rewardItems={175063},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58811] = {id=58811,name="A Balanced Diet",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. It would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us. Of course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?",objectivesText="Collect 12 Chunks of Meat from beasts in Uldum and the Vale of Eternal Blossoms. Progress: He looks hungry, I hope you brought a snack.",rewardGold=234000,rewardXP=6815,rewardItems={175014},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58812] = {id=58812,name="Meat Alternatives",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well. Could you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.",objectivesText="Collect 12 pieces of Insectoid Meat from Aqir, Mantid, or other insects in Uldum or the Vale of Eternal Blossoms. Progress: I do hope this works.",rewardGold=234000,rewardXP=6815,rewardItems={175015},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58813] = {id=58813,name="Fetid Filets",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source. I speak, of course, of the Minions of N'Zoth. It's a long shot, but it's worth a try.",objectivesText="Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: Who knew aqir would be such picky eaters?",rewardGold=234000,rewardXP=6815,rewardItems={175016},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58816] = {id=58816,name="Getting Backstage",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1565,description="The next thing we need to prepare the vessel is a set of Night's Veil Flowers. We use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater. I bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her. < Willowblossom flashes a wicked grin.>",objectivesText="Retrieve a Wreath of Night's Veil Flowers from backstage at the Star Lake Amphitheater. Progress: Do you have the flowers?",rewardItems={174845},starts={{npcID=162679}},questType="standard"},
[58817] = {id=58817,name="Action Figures",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained. After all, a happy larva is a healthy larva! I think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!",objectivesText="Collect 6 Amathet Figurines from Amathet creatures in Uldum . Progress: Did you find any suitable toys?",rewardGold=234000,rewardXP=6815,rewardItems={175020},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58818] = {id=58818,name="Bug Buddies",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind. You know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company. What do you think?",objectivesText="Catch 5 Docile Sandstone Hatchlings in Uldum .",starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58820] = {id=58820,name="Bindings of Fleshcrafting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="These are the Bindings of Fleshcrafting ! They empowered the Primus to shape the very flesh and bone of Maldraxxus. We must return them to their rightful place, so their power can bolster us all.",objectivesText="Place the Bindings of Fleshcrafting upon the Statue of the Primus.",rewardGold=772200,rewardXP=12250,rewardItems={182257,182266,182275,182284},rewardChoices={182275,182266,182284,182257},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[58821] = {id=58821,name="Glorious Pursuits",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Perhaps Draka has forgotten her loyalties, but I will fulfill my mission. My enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh. We have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers. Collect him for me. Once you capture him, slay his kin. Weaken his resolve. I will prime my base for his interrogation.",objectivesText="Kidnap Mephiles the Loyal, then kill 6 Morbid Disciples to intimidate him. Progress: Any luck?",rewardGold=243360,rewardXP=1415,rewardItems={178940},starts={{npcID=162487}},ends={{npcID=162487}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="standard"},
[58825] = {id=58825,name="Super Jelly",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. If this jelly works on mantid, logic would suggest it would work on aqir as well! See if you can find a sufficient sample of this jelly to help with our larva's growth.",objectivesText="Collect 8 Concentrated Royal Jelly in the Vale of Eternal Blossoms. Progress: This gets me thinking. After we've raised this one, I wonder if we could hatch a mantid as well?",rewardGold=234000,rewardXP=6815,rewardItems={175022},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58826] = {id=58826,name="A Bloody Treat",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9105,mapID=1527,description="I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\" If this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva. Go see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!",objectivesText="Collect 8 Vials of Purified Anima from Dokani mogu in the Vale of Eternal Blossoms. Progress: Have you returned with the anima?",rewardGold=234000,rewardXP=6815,rewardItems={175023},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58829] = {id=58829,name="They Grow So Fast",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Look! Our little larva friend has entered the pupa stage! Wait... it looks like he's ready to emerge. Go on, give him a hand!",objectivesText="Help the Aqir Larva emerge from its cocoon in Ramkahen. Progress: Take care, our friend is likely still very fragile.",rewardGold=468000,rewardXP=8520,rewardItems={175049},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58830] = {id=58830,name="Aqir Instincts",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures. We should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. He may not be able to fight for long, so don't call him until you're ready for training. With luck, he will come to see us as part of his hive.",objectivesText="Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: Take care of your hatchling. He will return here if he becomes too injured.",rewardGold=23400,rewardXP=850,rewardItems={175055},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58831] = {id=58831,name="Honing Instincts",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="It looks like our little friend is anxious and ready to practice more combat. Would you care to show him the ropes?",objectivesText="Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: How goes the training?",rewardGold=23400,rewardXP=850,rewardItems={175055},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58832] = {id=58832,name="Trinkle Trinkle Little Twerp",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="<On the note are the scribblings for a plan to steal silkstrider larvae and cook them. It is signed by someone named Trinkle.>",objectivesText="Kill Trinkle the Silk Eater . Progress: Have you taken care of that nasty Trinkle?",rewardGold=514800,rewardXP=10205,rewardItems={175982},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},coords={mapID=1565,x=0.404,y=0.547},questType="standard"},
[58833] = {id=58833,name="Calling in All Favors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="$p, the time has come. We cannot allow Kel'Thuzad to wield the Ritualists' sorcery as a weapon. He must be destroyed. Rally our forces. We march on the House of Rituals!",objectivesText="Meet Draka and allies at the House of Rituals.",rewardGold=257400,rewardXP=8165,starts={{npcID=161907}},ends={{npcID=174179}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[58842] = {id=58842,name="The Curator",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I tasked the Curator with reacquiring the Medallion of Avarice. However, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you? I ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.",objectivesText="Meet the Curator at the Crypt of the Forgotten. Progress: I require your assistance, Maw Walker.",rewardGold=128700,rewardXP=4085,starts={{npcID=158653}},ends={{npcID=160941}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[58843] = {id=58843,name="The Vault of the Archon",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion. To make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure. Do consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.",objectivesText="Gain entrance into the Vault of the Archon. Progress: Please place the offerings, and you may enter.",rewardGold=257400,rewardXP=1415,starts={{npcID=167035}},ends={{npcID=167504}},coords={x=0.588,y=0.652,source="quest_giver",zoneID=10534},questType="standard"},
[58844] = {id=58844,name="Before the Dawn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="We shall need all we can muster if this day is to be ours. Gather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them. Our Paragons will clear a staging ground at the Court of Elation for the final assault.",objectivesText="Gather the Watchers, Bearers, Centurions, and Collectors.",rewardGold=257400,rewardXP=8165,starts={{npcID=160037}},ends={{npcID=164473}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58846] = {id=58846,name="The Greater Good",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through. We will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time. Follow the path, .",objectivesText="Defeat Lysonia.",rewardGold=772200,rewardXP=12250,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164473}},ends={{npcID=166693}},coords={x=0.314,y=0.234,source="quest_giver",zoneID=10534},questType="standard"},
[58847] = {id=58847,name="Kyrestia's Grace",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw. She then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were. He may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.",objectivesText="Escort Uther.",rewardGold=128700,rewardXP=4085,rewardItems={183888,183889,183890,183891,183892,183893},rewardChoices={183888,183889,183890,183891,183892},starts={{npcID=166693}},ends={{npcID=160037}},coords={x=0.674,y=0.152,source="quest_giver",zoneID=10534},questType="standard"},
[58854] = {id=58854,name="Convene the Paragons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains. The Temple of Loyalty. Lysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her. We shall need the Paragons to finish this. Summon them.",objectivesText="Summon the Paragons to call them to action. Progress: Without the Paragons we cannot prevail against Lysonia.",rewardGold=128700,rewardXP=4085,starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[58856] = {id=58856,name="Who Are You Fooling?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1565,description="We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend. Unfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back! The spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby .",objectivesText="Loot Sicklethorn Trickster Powder from Sicklethorn spriggans to dispel illusions on Conspicuous Objects and find Grubby . Progress: We need to find Grubby !",rewardGold=257400,rewardXP=8165,rewardItems={174843},starts={{npcID=162392}},ends={{npcID=162392}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=11510},questType="standard"},
[58857] = {id=58857,name="Seeds Away!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good! Grab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!",objectivesText="Stop the gorm from overrunning the Gormhive Defense Wall and then pouring into the rest of Ardenweald! Progress: I can't believe this. Blue seeds, red seeds, flying faeries!",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=162392}},ends={{npcID=163328}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=11510},questType="standard"},
[58858] = {id=58858,name="More Fetid Filets",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Our little guy is getting hungry again. Could you pick him up a quick bite to eat?",objectivesText="Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: My, this thing has an appetite.",rewardItems={175016},starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58859] = {id=58859,name="Someone His Own Size",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size. I know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.",objectivesText="Defeat Retinus the Seeker in a pet battle with your Shadowbarb Hatchling in your party.",rewardGold=234000,rewardXP=6815,starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58860] = {id=58860,name="Big Bad Beetle",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of. I have found an opponent who could provide a challenging fight.",objectivesText="Defeat the Aqir Sandcrawler in a pet battle with your Shadowbarb Hatchling in your party.",rewardGold=234000,rewardXP=6815,starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58861] = {id=58861,name="The Mantids' Mettle",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect. I have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.",objectivesText="Defeat the Vil'thik Hatchling in a pet battle with your Shadowbarb Hatchling in your party. Progress: How did our hatchling fare against the mantid?",rewardGold=234000,rewardXP=6815,starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58862] = {id=58862,name="The Littlest Defender",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses. Fortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling. Find this miniature defender in the Vale of Eternal Blossoms.",objectivesText="Defeat the Baruk Stone Defender in a pet battle with your Shadowbarb Hatchling in your party.",rewardGold=234000,rewardXP=6815,starts={{npcID=161738}},ends={{npcID=161738}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58863] = {id=58863,name="A Custom Order",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=5034,mapID=1527,description="I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle. Wait, that's a marvelous idea! You should speak with Blacksmith Abasi about getting a saddle made.",objectivesText="Speak with Blacksmith Abasi in Ramkahen. Progress: What do you need?",rewardGold=23400,rewardXP=850,starts={{npcID=161738}},ends={{npcID=164250}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="standard"},
[58865] = {id=58865,name="Otherworldly Armaments",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available. I have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. If you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.",objectivesText="Collect 12 Black Empire Armaments from Black Empire cultists in Uldum and the Vale of Eternal Blossoms. Progress: Have you found my materials?",rewardGold=234000,rewardXP=6815,rewardItems={175058},starts={{npcID=164250}},ends={{npcID=164250}},coords={x=0.54,y=0.334,source="quest_giver",zoneID=10833},questType="standard"},
[58866] = {id=58866,name="My Own Drone",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted. I know it looks... aggressive, but I assure you that your aqir will find it quite comfortable. I hope it serves you well.",objectivesText="Bring the Otherworldly Saddle to H'Partho Adoros in Ramkahen. Progress: Was the blacksmith able to help?",rewardGold=468000,rewardXP=8520,rewardItems={174771,175059},starts={{npcID=164250}},ends={{npcID=161738}},coords={x=0.54,y=0.334,source="quest_giver",zoneID=10833},questType="standard"},
[58869] = {id=58869,name="Battle for Hibernal Hollow",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This is where we make our stand. The Drust and their minions have us nearly overrun. But we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds. Fight with us. Let us drive them out.",objectivesText="Win the Battle for Hibernal Hollow.",rewardGold=772200,rewardXP=2125,starts={{npcID=169541}},ends={{npcID=160894}},coords={x=0.598,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[58871] = {id=58871,name="Broken Harts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="The curse on Qadarin is a powerful one. But I will break it. Thiernax snorts.> Death did not part us. I will not be torn from him now. Thiernax studies both you and Shandris with a serious look in his eyes.> Lend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know. Return to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.",objectivesText="Report to Lord Herne at the Heart of the Forest, then speak with Moonberry. Progress: This is even worse than I had thought.",rewardGold=128700,rewardXP=4085,starts={{npcID=161785}},ends={{npcID=161509}},coords={x=0.402,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[58876] = {id=58876,name="Lost Flight",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused. You surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before. There would be no turning back from such madness. But maybe it's not too late for this one...>",objectivesText="Bring the Spawn of Vexiona to Wrathion in the Chamber of Heart. Provided item:",rewardItems={174862},ends={{npcID=155496}},coords={mapID=84,source="quest_giver",x=0.846,y=0.3295},questType="standard"},
[58877] = {id=58877,name="Death's Power Grows",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12952,mapID=1602,description="Listen closely, . A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth. It is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade. Now swear your fealty.",objectivesText="Swear fealty to the Lich King . Progress: Swear your fealty, <name>.",rewardGold=1000,rewardXP=710,rewardItems={174485,174486,174487,174488,174659,174660,174661,174662},rewardChoices={174488,174487,174486,174485,174660,174661,174659,174662},starts={{npcID=163016}},ends={{npcID=163016}},coords={x=0.494,y=0.9,source="quest_giver",zoneID=12952},questType="standard"},
[58879] = {id=58879,name="Alpaca It Up",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,objectivesText="Progress: <Sniffs curiously in the general direction of your backpack, eyeing it intently.>",rewardXP=1705,starts={{npcID=162765}},ends={{npcID=162765}},coords={x=0.552,y=0.698,source="quest_giver",zoneID=10833},questType="standard"},
[58887] = {id=58887,name="Alpaca It In",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,rewardXP=3410,rewardItems={174859},starts={{npcID=162765}},ends={{npcID=162765}},coords={x=0.552,y=0.698,source="quest_giver",mapID=1527},questType="standard"},
[58900] = {id=58900,name="A Sure Bet",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You've made a name for yourself and earned the respect of everyone here, including Au'narim. You are ready, $p! Anzio is expecting us at the entrance to the Theater of Pain. You're going to be a champion!",rewardGold=25740,rewardXP=175,starts={{npcID=161559,x=0.544,y=0.486,zoneID=11462}},ends={{npcID=161733,x=0.504,y=0.516,zoneID=11462}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="A Sure Bet"},
[58902] = {id=58902,name="Defender of Azeroth",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1637,mapID=1602,description="An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.",objectivesText="Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Stormwind. Once there, visit Chromie .",rewardGold=19025,rewardXP=710,starts={{npcID=163016}},ends={{npcID=163016}},coords={x=0.494,y=0.9,source="quest_giver",zoneID=12952},questType="standard"},
[58903] = {id=58903,name="Defender of Azeroth",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=1602,description="An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.",objectivesText="Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Orgrimmar. Once there, talk to Chromie .",rewardGold=170800,rewardXP=710,starts={{npcID=163016}},ends={{npcID=163016}},coords={x=0.494,y=0.9,source="quest_giver",zoneID=12952},questType="standard"},
[58904] = {id=58904,name="Shards of Corruption",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>",objectivesText="Collect 20 Shards of Corruption . Progress: <The Idol tugs at your very being. Demanding you to touch it.>",rewardGold=234000,rewardXP=6815,ends={{npcID=341831}},questType="standard"},
[58905] = {id=58905,name="Picking Up Pelagos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge. We'll see you there!",objectivesText="Meet up with Pelagos , Willowblossom , and Grubby at Claw's Edge.",rewardGold=25740,rewardXP=1020,starts={{npcID=162679}},ends={{npcID=163328}},questType="standard"},
[58908] = {id=58908,name="Finding Your Way",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around. She said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there. Have no worries, ! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master in Old Town!",objectivesText="Speak with Curly at the stables in Old Town. Progress: Welcome to the stables, <class>. I've been expecting you.",rewardXP=505,rewardChoices={2411,25470},starts={{npcID=163095}},ends={{npcID=163007}},coords={x=0.702,y=0.852,source="quest_giver",zoneID=1519},questType="standard"},
[58910] = {id=58910,name="What's Your Specialty?",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Mithlos Falconbriar to learn more about specializations!",objectivesText="Speak with Mithlos Falconbriar to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?",rewardXP=505,starts={{npcID=163097}},ends={{npcID=164962}},questType="standard"},
[58911] = {id=58911,name="Home Is Where the Hearth Is",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="I don't know about you, but all this running around has got me thirsty! Why don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice? While we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a gryphon, but you'll save a few copper in the process!",objectivesText="Speak with Meagan Tillman to make the Pig and Whistle Tavern your home. Progress: How can I help you today, <class>? Are you looking for a place to stay?",rewardXP=505,starts={{npcID=163097}},ends={{npcID=44237}},questType="standard"},
[58912] = {id=58912,name="An Urgent Meeting",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="I've been looking for you all over Stormwind, . The captain has delivered her report to the king. It appears that Stormwind requires your service yet again. The leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay. It has been an honor serving with you, . May the Light bless you on your journey.",objectivesText="Speak with Captain Garrick at Stormwind Keep.",rewardXP=125,starts={{npcID=163211}},ends={{npcID=163219}},coords={x=0.754,y=0.542,source="quest_giver",zoneID=1519},questType="standard"},
[58914] = {id=58914,name="A Warrior's End",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Hey, ! You're a , right? Maybe you can deal with this... situation. I was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors. I know you're still new at this, but why don't you try going over there? We could use every advantage against these ogres.",objectivesText="Speak with the strange ghost at the Darkmaul Bridge.",rewardGold=1600,rewardXP=250,starts={{npcID=156801}},ends={{npcID=162943}},coords={x=0.52,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[58915] = {id=58915,name="Hjalmar's Final Execution",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.",objectivesText="Slay Hjalmar the Undying . You must use Execute in order to truly kill him.",rewardGold=1600,rewardXP=250,starts={{npcID=162943}},ends={{npcID=156801}},coords={x=0.516,y=0.478,source="quest_giver",zoneID=10424},questType="standard"},
[58916] = {id=58916,name="Dread Priming",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror. I have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey . His time has come to be hunted. The Fearstalker hands you a set of Hopebreaker Soul Chains .> Demoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth .",objectivesText="Prepare Houndmaster Loksey for the Penitent Hunt in the Grove of Terror.",rewardGold=127530,rewardXP=710,rewardItems={179388},starts={{npcID=169087}},ends={{npcID=163221}},coords={x=0.506,y=0.738,source="quest_giver",zoneID=10413},questType="standard"},
[58917] = {id=58917,name="A Rogue's End",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="A rogue from the lost expedition, Coulston Nereus , tried scouting the island for any threats after they made landfall. The last time Henry saw him, he was headed for a cave not far from here. Can you make contact with Coulston? He may be able to help with our rescue mission. Oh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.",objectivesText="Use Stealth to sneak around and find the first expedition's rogue. Progress: Did you get the roots? Make sure that bear is far away when you pick them.",rewardGold=2030,rewardXP=250,rewardItems={174916},starts={{npcID=156801}},ends={{npcID=163024}},coords={x=0.52,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[58918] = {id=58918,name="Huwerath",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,objectivesText="Free the Half-Digested Soul",rewardXP=8165,questType="standard",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=163156,text="Free the Half-Digested Soul"}},worldTaskTitle="Huwerath"},
[58923] = {id=58923,name="A Paladin's Service",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="I found something strange while using Lindie's Scout-o-Matic that you should probably know about. The ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you. I don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.",objectivesText="Speak with the paladin's ghost. Progress: Greetings, <name>. It is good to finally see you.",rewardGold=2030,rewardXP=250,starts={{npcID=156801}},ends={{npcID=162998}},coords={x=0.52,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[58931] = {id=58931,name="Inquisitor Stelia's Sinstone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=8721,mapID=1525,description="You never truly escape your past, Maw Walker. Every venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives. Like all souls, they carved their true names and most shameful transgressions into sinstones. Knowledge that intimate can be a potent weapon, if wielded properly. Locate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia. After they're dead, bring me the Accuser's sinstone. I will deal with her myself.",objectivesText="Collect Avowed Crypt Keys and open crypts until you locate Inquisitor Stelia's Sinstone . Progress: Inquisitors hide their sinstones to protect themselves.",rewardGold=252720,rewardXP=1415,rewardItems={174930,174998},starts={{npcID=156823}},ends={{npcID=163576}},coords={x=0.646,y=0.498,source="quest_giver",zoneID=10413},questType="standard"},
[58932] = {id=58932,name="Temel, the Sin Herald",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Echelon shouted an additional command.> Expropriate Temel as well. He will know how to exploit the sinstone properly.",objectivesText="Defeat Cryptkeeper Kassir to earn Temel's obedience. Progress: Temel will not come willingly.",rewardGold=257400,rewardXP=1415,ends={{npcID=163576}},coords={mapID=1525,source="quest_giver",x=0.674,y=0.535},questType="standard"},
[58933] = {id=58933,name="The Deadliest of Poisons",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough. He usually patrols around their citadel. Probably looking for your expedition as we speak! Poison your blades, then take that monster down.",objectivesText="Kill Gutgruk the Tough.",rewardGold=2030,rewardXP=250,starts={{npcID=163024}},ends={{npcID=156801}},coords={x=0.456,y=0.56,source="quest_giver",zoneID=10424},questType="standard"},
[58936] = {id=58936,name="Beast Control",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought. This is a formal request to cull their numbers. We must re-establish dominance over our creations. - Flockmaster Sergio",objectivesText="Kill 6 Dredbats in the Grove of Terror.",rewardGold=157500,rewardXP=1415,rewardItems={179719},starts={{npcID=355296}},ends={{npcID=163221}},coords={x=0.496,y=0.759,source="quest_giver",zoneID=10413},questType="standard"},
[58937] = {id=58937,name="Evil Grubbies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oh no! This place is littered with mites! They are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later. They can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.",objectivesText="Burn 20 Evolving Mites with Pelagos' Flamelash Seeds. Progress: How many more are there?",rewardGold=257400,rewardXP=8165,rewardItems={174291,174938,177052,178155,179941},rewardChoices={178155,177052,179941,174291},starts={{npcID=162392}},ends={{npcID=162392}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=11510},questType="standard"},
[58938] = {id=58938,name="Gorm Ruin Everything",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help. Let's clear out some of these gorm and search for the real seed.",objectivesText="Kill 10 mature gorm. Progress: We need to clear a path.",rewardGold=257400,rewardXP=8165,starts={{npcID=162392}},ends={{npcID=162392}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=11510},questType="standard"},
[58939] = {id=58939,name="The Blue Seed",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in? I wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!",objectivesText="Find the cave entrance , get through the blockage of brambles, and obtain the Ripened Anima Seed . Progress: This has been quite the fun adventure. Wouldn't you say?",rewardGold=128700,rewardXP=4085,rewardItems={176446},starts={{npcID=165110}},ends={{npcID=162392}},questType="standard"},
[58941] = {id=58941,name="Alpha Bat",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts. With the anima drought, our dominion over them has waned. One, Duskterror , has wreaked the most havoc. This presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.",objectivesText="Hitch Houndmaster Loksey to the stake in the Grove of Terror. Then, weaken Duskterror to capture her. Progress: Is Duskterror captured?",rewardGold=255060,rewardXP=1415,rewardItems={175765},rewardChoices={175765},starts={{npcID=163221}},ends={{npcID=163221}},coords={x=0.512,y=0.742,source="quest_giver",zoneID=10413},questType="standard"},
[58946] = {id=58946,name="The Divine's Shield",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="This island has been cursed by necrotic magic. The Light can only just reach this place. Call upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar. Show the darkness on this island that you are protected by the Light's embrace.",objectivesText="Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Yorah if you need to reduce Divine Shield's cooldown. Progress: Do you require aid? Use Divine Shield to safely pass through the necrotic barrier.",rewardGold=2940,rewardXP=250,starts={{npcID=162998}},ends={{npcID=162998}},coords={x=0.576,y=0.52,source="quest_giver",zoneID=10424},questType="standard"},
[58948] = {id=58948,name="Food on the Table",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=44,mapID=49,description="I'm making a stew for dinner tonight, but it seems we're missing rabbit meat . Would you be able to go out back and collect some for me? Oh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.",objectivesText="Collect 4 Rabbit Meat . Progress: Shh shh, Gwendolyn. It's okay, baby girl.",rewardGold=257400,rewardXP=8165,rewardItems={174935},starts={{npcID=162953}},ends={{npcID=162953}},coords={x=0.218,y=0.422,source="quest_giver",zoneID=44},questType="standard"},
[58949] = {id=58949,name="Millie's Garden",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=44,mapID=49,description="Alma came by earlier and gave Millie some flower seeds to plant out in the garden. I love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again! Would you help her with the digging so that she doesn't get too dirty?",objectivesText="Use your shovel to till 3 Untilled Soil. Progress: <Millie giggles.> Hi daddy!",rewardGold=257400,rewardXP=8165,starts={{npcID=162953}},ends={{npcID=162962}},coords={x=0.218,y=0.422,source="quest_giver",zoneID=44},questType="standard"},
[58950] = {id=58950,name="Lumber for Lakeshire",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=44,mapID=49,description="Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it. If you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.",objectivesText="Bring the Bundle of Lumber to Magistrate Solomon at the Lakeshire Town Hall. Progress: The folks are on edge, Ben. It's my job to keep them at ease.",rewardGold=25740,rewardXP=1020,rewardItems={174997},starts={{npcID=162953}},ends={{npcID=163111}},coords={x=0.218,y=0.422,source="quest_giver",zoneID=44},questType="standard"},
[58951] = {id=58951,name="Lakeshire's Last Stand",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="There's no time to evacuate... not if the Scourge are here! Board the windows! Get everybody inside! Our only hope is to hide.",rewardGold=514800,rewardXP=10205,starts={{npcID=163111}},ends={{npcID=162542}},coords={x=0.288,y=0.41,source="quest_giver",mapID=1533},questType="standard"},
[58953] = {id=58953,name="A Priest's End",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="You're a trained priest, right ? This might be up your alley. We've spotted the bodies of other recruits from our expedition. I'm guessing they washed up on a different part of the island. They didn't make it very far. When you have a moment, could you say a few prayers over them? Just to help put their spirits at ease. We'll give them a proper burial once we deal with the ogres.",objectivesText="Find the corpses of the first expedition recruits.",rewardGold=1600,rewardXP=250,starts={{npcID=156801}},ends={{npcID=163108}},coords={x=0.52,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[58960] = {id=58960,name="Resurrecting the Recruits",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island. Use Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger. I've been stranded on this island for years, watchin' these ogres get away with all of this. It's time tae make a stand.",objectivesText="Resurrect the Expedition recruits. Progress: Get goin' and save those recruits with resurrect!",rewardGold=4000,rewardXP=250,starts={{npcID=163108}},ends={{npcID=163108}},coords={x=0.562,y=0.536,source="quest_giver",zoneID=10424},questType="standard"},
[58962] = {id=58962,name="A Warlock's Bargain",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device. I saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck. Think you can go investigate the area and try to close that portal? We have enough problems on this island as it is.",objectivesText="Investigate the first expedition warlock's corpse. Progress: I see you have the grimoire that enacted the binding ritual.",rewardGold=1600,rewardXP=250,rewardItems={174947},starts={{npcID=156801}},ends={{npcID=163246}},coords={x=0.52,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[58975] = {id=58975,name="Pest Removal",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=163212,text="Burrowing Mite extracted"},{orderIndex=1,type=0,amount=12,objectID=170182,text="Mature Gorm slain"}},worldTaskTitle="Pest Removal",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58976] = {id=58976,name="Chasing a Memory",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The attack on the Temple of Purity is unprecedented in Bastion . At least, to my knowledge. We need to know more. The fragment that the Paragon captured may contain the answers we seek. There is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan. I will meet you there. Go in service.",objectivesText="Travel to the Mnemonic Locus.",rewardGold=23870,rewardXP=175,starts={{npcID=156238}},ends={{npcID=167034}},coords={x=0.538,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[58977] = {id=58977,name="What's In a Memory?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak! We will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think. Do not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn. Speak when ready.",objectivesText="Collect memories of the Forsworn from the Fragment of Lysonia . Progress: Do you think we will get the information we need, <name>?",rewardGold=257400,rewardXP=1415,rewardItems={183802},starts={{npcID=167034}},ends={{npcID=167038}},coords={x=0.572,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[58978] = {id=58978,name="Lysonia's Truth",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible. You carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn. If this works, we may know what they are planning within minutes!",objectivesText="Stand before a Soul Mirror and witness memories from Lysonia's past.",rewardGold=257400,rewardXP=1415,starts={{npcID=167038}},ends={{npcID=167034}},coords={x=0.544,y=0.642,source="quest_giver",zoneID=10534},questType="standard"},
[58979] = {id=58979,name="I MADE You!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have had it with this insolence! I have an idea to reset this Mnemis's personality, but you will need to keep it busy. It will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined. Hop to it!",rewardGold=257400,rewardXP=1415,rewardItems={173315,173329,173330,173331},rewardChoices={173329,173331,173330,173315},starts={{npcID=167034}},ends={{npcID=167035}},coords={x=0.572,y=0.552,source="quest_giver",mapID=1533},questType="standard"},
[58980] = {id=58980,name="Mnemis, At Your Service",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you. I recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon. In order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter. The Forgelite Prime is the only one among you who can grant authorization. How convenient!",objectivesText="Locate two offerings within the Walk of Recollection, then proceed to the Vault of the Archon. Progress: Did you find the offerings of which I spoke?",rewardGold=257400,rewardXP=1415,rewardItems={178145,178146},starts={{npcID=167035}},ends={{npcID=167035}},coords={x=0.588,y=0.652,source="quest_giver",zoneID=10534},questType="standard"},
[58983] = {id=58983,name="Battle for Azeroth: Tides of War",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="King Wrynn has called us together for an urgent war council. It seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach. Now that you've arrived, the meeting will begin without delay.",objectivesText="Attend the War Council in Stormwind Keep. Progress: Thank you for coming.",rewardGold=200,rewardXP=125,rewardItems={178941,178942},rewardChoices={178941,178942},starts={{npcID=163219}},ends={{npcID=165395}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[58989] = {id=58989,name="Runeforging 101",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=7543,mapID=23,description="As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons. Above us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.",objectivesText="Use the Runeforging ability in your spellbook to engrave a rune upon your weapon. You may freely replace the engraving at any time, so long as you are near a Runeforge. Progress: Have you emblazoned a rune upon your weapon, <name>?",rewardGold=1000,rewardXP=710,starts={{npcID=29246}},ends={{npcID=29246}},coords={x=0.82,y=0.464,source="quest_giver",zoneID=139},questType="standard"},
[58992] = {id=58992,name="Pie Not?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I want to cook something warm, savory, and gooey! That's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! Now, just any old marrow won't do. I need the very best and rarest marrow. And that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. Oh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.",objectivesText="Collect 4 Maldraxxi Bone Marrow . Progress: Is there any kind of pie that's not just the best? Blood pie, bone marrow pie, bone marrow jelly...",rewardXP=8165,rewardItems={177879},starts={{npcID=161678}},ends={{npcID=161678}},coords={x=0.552,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[58993] = {id=58993,name="Swarm Defense",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=170125,text="Veilwing Sentry mounted"}},worldTaskTitle="Swarm Defense",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58995] = {id=58995,name="I Dreamed A Dream",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion . We owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.",objectivesText="Witness the ceremony. Progress: Do you have the vessel?",rewardGold=128700,rewardXP=4085,rewardItems={175153},starts={{npcID=163328}},ends={{npcID=163328}},coords={x=0.452,y=0.654,source="quest_giver",zoneID=11510},questType="standard"},
[58996] = {id=58996,name="Abel's Fate",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Maw Walker, I have another task for you. Some time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers. They have yet to return. Go find them, will you?",objectivesText="Investigate Soulwatcher Abel's fate. Progress: What became of Abel?",rewardGold=386100,rewardXP=1415,rewardItems={174957},starts={{npcID=156384}},ends={{npcID=156384}},coords={x=0.484,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[58997] = {id=58997,name="A Bittersweet Prize",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1565,description="I... I don't know what to say. All that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion . This sacrifice must not be in vain.",objectivesText="Deliver the Vessel of Ardenweald to Polemarch Adrestes at Elysian Hold in Bastion .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=163328}},ends={{npcID=160037}},coords={x=0.452,y=0.654,source="quest_giver",zoneID=11510},questType="standard"},
[59000] = {id=59000,name="Elements of Corruption",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand. Though I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.",objectivesText="Speak with MOTHER to learn about corrupted items. Progress: What have you discovered?",rewardGold=23400,rewardXP=850,starts={{npcID=155496}},ends={{npcID=152194},{npcID=155923}},coords={x=0.852,y=0.322,source="quest_giver",zoneID=1519},questType="standard"},
[59002] = {id=59002,name="A Shaman's Duty",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=10424,mapID=1409,description="Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman. The shadow energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.",rewardGold=4000,rewardXP=250,rewardItems={174968},starts={{npcID=163329}},ends={{npcID=163329}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59004] = {id=59004,name="Splash Damage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! I developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well! Splash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.",objectivesText="50 Anima Charged Runes collected off Rune-hardened Troops. Progress: Have you cleaned things up?",rewardGold=257400,rewardXP=8165,rewardItems={185485,185729},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=163295}},ends={{npcID=177072},{npcID=177685}},coords={x=0.328,y=0.568,source="quest_giver",zoneID=11400},questType="standard"},
[59007] = {id=59007,name="Soul Well",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,objectivesText="Catch the Stygia erupting from the Soul Well",rewardXP=8165,questType="standard",db2Objectives={{orderIndex=0,type=0,amount=30,objectID=163367,text="Catch the Stygia erupting from the Soul Well"}},worldTaskTitle="Soul Well"},
[59008] = {id=59008,name="Spriggan Snares",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I'm so glad you and Qadarin were passing by! These spriggans are crazy! Get me out of here! I was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!",objectivesText="Free Cirrik and rescue 8 Captives. Progress: This behavior is unexpectedly bold for the spriggans.",rewardGold=257400,rewardXP=8165,starts={{npcID=163385}},ends={{npcID=163385}},coords={x=0.39,y=0.524,source="quest_giver",zoneID=11510},questType="standard"},
[59009] = {id=59009,name="Her Rightful Place",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mor'Bitan has met his end... and a painful one at that. Your fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. There is much left to do, should you truly desire ownership of this realm. Let us regroup at the Seat.",objectivesText="Return to the Seat of the Primus with your runeblade. Progress: Were you successful?",rewardGold=128700,rewardXP=710,rewardItems={175451,175452,175453,175454},rewardChoices={175452,175454,175453,175451},starts={{npcID=164326}},ends={{npcID=168381}},coords={x=0.736,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[59011] = {id=59011,name="In Death We Are Truly Tested",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs. No doubt he intended to trap you within that hellish place as well. It is time he be brought to justice for his treason. Stand with me, and we will face him as one.",objectivesText="Confront Vyraz about the death of Margrave Krexus.",rewardGold=491400,rewardXP=1770,rewardItems={180663,180664,180665,180666,180667,180668,180669,180670,180671,180672,180673,180790,180791,180792},rewardChoices={180791,180663,180666,180664,180792,180673,180668,180672,180667,180665,180790,180669,180671,180670},starts={{npcID=162801}},ends={{npcID=170309}},coords={x=0.412,y=0.606,source="quest_giver",zoneID=11462},questType="standard"},
[59014] = {id=59014,name="King of the Hill",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Loksey is ready. It is finally time to begin the hunt. Take him to Wanecrypt. The Fearstalker and the other hunters will be there already. Hurry now. She does not like to be kept waiting.",objectivesText="Bring Houndmaster Loksey to the Fearstalker in Wanecrypt Hill. Progress: Where's the soul?",rewardGold=64350,rewardXP=355,starts={{npcID=163221}},ends={{npcID=168664}},coords={x=0.512,y=0.742,source="quest_giver",zoneID=10413},questType="standard"},
[59015] = {id=59015,name="Hostile Recollection",expansion=8,mapID=1533,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Repel the Forsworn threat"}},worldTaskTitle="Hostile Recollection"},
[59016] = {id=59016,name="Call to Arms: Uldum",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=862,description="Our objectives in Uldum are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.",objectivesText="Slay Alliance within Uldum .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=100}},starts={{npcID=143536}},ends={{npcID=143536},{npcID=154641}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[59017] = {id=59017,name="Call to Arms: Vale of Eternal Blossoms",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10052,mapID=862,description="Our objectives in Vale of Eternal Blossoms are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.",objectivesText="Slay Alliance within Vale of Eternal Blossoms .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=100}},starts={{npcID=143536}},ends={{npcID=143536},{npcID=154641}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[59018] = {id=59018,name="Call to Arms: Vale of Eternal Blossoms",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="Our mission in Vale of Eternal Blossoms is being compromised by the Horde incursion. Get into Vale and take out as many as you can.",objectivesText="Slay Horde within Vale of Eternal Blossoms .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=100}},starts={{npcID=143559}},ends={{npcID=143559}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[59019] = {id=59019,name="Call to Arms: Uldum",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10052,mapID=1161,description="Our mission in Uldum is being compromised by the Horde incursion. Get into Uldum and take out as many as you can.",objectivesText="Slay Horde within Uldum .",rewardItems={167744,169614},rewardCurrencies={{id=1602,amount=100}},starts={{npcID=143559}},ends={{npcID=143559},{npcID=154640}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[59020] = {id=59020,name="The Third Fall of Kel'Thuzad",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="The time has come to purge Maldraxxus of treachery. Our armies are rallied. Our allies stand ready. The machine of war is in motion. We must win this battle, or all of the Shadowlands will be lost.",objectivesText="Remove Kel'Thuzad from Maldraxxus .",rewardGold=772200,rewardXP=12250,rewardItems={181822},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174179}},ends={{npcID=161907}},coords={x=0.62,y=0.41,source="quest_giver",zoneID=11462},questType="standard"},
[59021] = {id=59021,name="Herald Their Demise",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Since the dawn of Revendreth , Temel has been charged with proclaiming the sins of souls for all to hear. Every soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion. He will know how to wield Inquisitor Stelia 's sinstone to break through her defenses. Simply command him to do so after you locate the inquisitor, and eliminate her.",objectivesText="Order Temel to read from Inquisitor Stelia 's sinstone, then kill her. Progress: Is the inquisitor dead?",rewardGold=257400,rewardXP=1415,rewardItems={175430,175431,175432,175433},rewardChoices={175431,175433,175432,175430},starts={{npcID=163576}},ends={{npcID=163576}},coords={x=0.674,y=0.536,source="quest_giver",zoneID=10413},questType="standard"},
[59023] = {id=59023,name="Ending the Inquisitor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr. We must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle. Temel will once again help you penetrate the inquisitor's defenses. Do not tarry.",objectivesText="Order Temel to read from Inquisitor Vilhelm 's sinstone, then kill him. Progress: Once the inquisitor is dead, the warding spell will be broken.",rewardGold=257400,rewardXP=1415,rewardItems={175442,175443,175444,175445},rewardChoices={175442,175445,175444,175443},starts={{npcID=164166}},ends={{npcID=164166}},coords={x=0.66,y=0.472,source="quest_giver",zoneID=10413},questType="standard"},
[59025] = {id=59025,name="Straight to the Heart",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The success of Mor'Bitan 's treachery has made him complacent. Let him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave. Stand with me now, . Together, we will make an example of this traitor.",objectivesText="Kill Mor'Bitan . Progress: He will regret crossing me.",rewardGold=257400,rewardXP=1415,starts={{npcID=164326}},ends={{npcID=164326}},coords={x=0.736,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[59042] = {id=59042,name="A Good Heart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Despite the beliefs of most people, Emeni has a kind heart. Err...at least she will have one, once you give it to her! I can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds! Please select and place a heart in Emeni's construct.",objectivesText="Place a heart in Emenis' construct. Progress: I hope you chose well!",rewardGold=257400,rewardXP=8165,starts={{npcID=162227}},ends={{npcID=162227}},coords={x=0.242,y=0.386,source="quest_giver",zoneID=11462},questType="standard"},
[59043] = {id=59043,name="Baker's Dozen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies! The brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead. You familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! Mama will even send Starchy to help you out.",objectivesText="Travel to Ardenweald and collect 13 Hatchready Gorm Eggs .",rewardXP=8165,rewardItems={183744,181809,184843},starts={{npcID=161678}},ends={{npcID=161678}},coords={x=0.552,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[59063] = {id=59063,name="Curses!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Oh, dear me, this is terrible! Just terrible! I know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! Now the falls are overrun with all manner of dangerous magic! The spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.",objectivesText="Retrieve 5 pieces of Shredded Scroll from Rotbriar spriggans and a Tattered Binding from a Major Hex to create a Sealed Scroll of Soul Rot . Progress: Hmm... Yes, this looks like it could be the one.",rewardGold=514800,rewardXP=10205,rewardItems={175137,175138,177280},starts={{npcID=165867}},ends={{npcID=161509}},coords={x=0.636,y=0.226,source="quest_giver",zoneID=11510},questType="standard"},
[59067] = {id=59067,name="Orb of Extrication",expansion=8,mapID=1543,questType="world",worldTaskTitle="Orb of Extrication"},
[59068] = {id=59068,name="A Secret Never Spoken",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1701,description="The first reagent listed in the scroll is a secret never spoken . Well, that's easy. I know who has tons of secrets! Watcher Vesperbloom , our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest. I know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain. I'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.",objectivesText="Obtain a Secret Never Spoken from Watcher Vesperbloom 's records. Progress: Whew! This page... It's seen sights no one should ever see.",rewardGold=514800,rewardXP=10205,rewardItems={175152,175154},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161509}},ends={{npcID=161509}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[59069] = {id=59069,name="A Token of Lost Love",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=4922,mapID=1565,description="My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing. She has loved many in her long life, but none as deeply as he. I know in my heart she loves him still. Find Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.",objectivesText="Speak with Alexstrasza at the Vermillion Redoubt in Twilight Highlands. Progress: My sister loves with all of her heart...",rewardGold=128700,rewardXP=4085,rewardItems={175149},starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[59070] = {id=59070,name="A Sacrifice of Anima",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The last thing we need for this counter-curse is some attuned anima. Of course, we don't have much to spare. That means this is more of a sacrifice than it normally would be. But you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need. Thiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.",objectivesText="Slay Spriggans in Tirna Scithe to collect Mischief-touched Anima . Progress: Have you handled those spriggans yet?",rewardGold=257400,rewardXP=8165,rewardItems={175139},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161509}},ends={{npcID=161509}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[59071] = {id=59071,name="Mending a Broken Hart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1701,description="We have all the reagents for the counter-curse! Hurry up and cast it before Qadarin 's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad! But no pressure.",objectivesText="Perform the counter curse. Progress: I... I cannot thank you enough.",rewardGold=514800,rewardXP=10205,rewardItems={181301,182172},rewardChoices={181301},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161509}},ends={{npcID=161336}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[59076] = {id=59076,name="The Minions of Mayhem",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10565,mapID=1670,description="To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves! Come to our secret meeting at the Ledge of Destiny. To all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. Don't tell the fuzz.",objectivesText="Attend the publicly posted \"Secret Meeting.\"",rewardGold=25740,rewardXP=1020,questType="standard"},
[59087] = {id=59087,name="That Darn Fox!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1565,description="You! You there! I, Clarion Song , need your assistance. Yes, yes, give yourself a moment to bask in my glory. Clarion Song gives you a moment.> Done? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him! Make yourself useful and catch that kit!",objectivesText="Find and Catch Renny the Vulpin kit. Progress: Well? Did you catch it?",rewardGold=257400,rewardXP=8165,starts={{npcID=163774}},ends={{npcID=163774}},coords={x=0.508,y=0.338,source="quest_giver",zoneID=11510},questType="standard"},
[59120] = {id=59120,name="Renny the Vulpin",level=60,requiredLevel=60,faction="both",expansion=8,description="<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief. You, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you. What could possibly go wrong?>",rewardItems={175114},starts={{npcID=163903}},ends={{npcID=163903}},questType="standard"},
[59126] = {id=59126,name="Supply Chain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="My friend! I could sure use your expertise right now. One of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! It's important--no--vital, that we recover as much of that equipment as possible. So, you ready to go? Let's head out and salvage what we can!",rewardXP=8165,rewardItems={175133,178681,178682},starts={{npcID=159238}},ends={{npcID=167150}},coords={x=0.552,y=0.682,source="quest_giver",mapID=2151},questType="standard"},
[59130] = {id=59130,name="The House of Plagues",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner... But perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis. If any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.",objectivesText="Search for survivors near the House of Plagues.",rewardGold=24335,rewardXP=175,starts={{npcID=168381}},ends={{npcID=159930}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=11462},questType="standard"},
[59147] = {id=59147,name="The Hand of Purification",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Nikolon was not alone. Eridia stares grimly out over the temple grounds.> Long have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow. But this... wanton destruction! It will not stand. You will be my hand, . Go forth. End them. All of them. My duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.",objectivesText="\"Cleanse\" the Temple of Purity by slaying enemies.",rewardGold=58650,rewardXP=1415,starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[59171] = {id=59171,name="Prey Upon Them",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="My mission cannot progress without a supply of anima. Fortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals. You will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.",objectivesText="Collect 3 Anima-charged Maldracite . Progress: Do not fail me.",rewardGold=257400,rewardXP=1415,rewardItems={174934},starts={{npcID=162487}},ends={{npcID=162487}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="standard"},
[59172] = {id=59172,name="War is Deception",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You have proven a useful ally, . Mephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk. Not that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words. Place the charged crystals around me. They will facilitate the interrogation.",objectivesText="Prepare to interrogate Mephiles the Loyal. Progress: Let us reveal the truth.",rewardGold=24570,rewardXP=175,rewardItems={175706},rewardChoices={175706},starts={{npcID=162487}},ends={{npcID=162487}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="standard"},
[59175] = {id=59175,name="The Eternal Revenge",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="<On the shelves there are hundreds of other phylacteries of varying shapes and sizes. Many bear names - this one specifically has a etching with the name Mor'Bitan. Lady Vashj would be interested in this phylactery.>",objectivesText="Take the phylactery of Mor'Bitan back to Lady Vashj.",rewardGold=257400,rewardXP=8165,questType="standard"},
[59179] = {id=59179,name="Daughter of the Night Warrior",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=10565,mapID=1670,description="In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance. And... Ardenweald 's destruction. These visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm. Shandris Feathermoon , Tyrande's daughter, is touched by dreams as well. Even now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.",objectivesText="Find Shandris Feathermoon within Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[59181] = {id=59181,name="Into the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior. Such power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do. Highlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well. We must find Tyrande and convince her to let go of the Night Warrior's rage.",objectivesText="Take Shandris Feathermoon into the Maw.",rewardGold=25740,rewardXP=1020,starts={{npcID=164277}},ends={{npcID=174833}},questType="standard"},
[59183] = {id=59183,name="Drifting Sorrow",level=60,requiredLevel=60,faction="none",categories={"vignette"},flags={"tracking"},expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="vignette",worldTaskTitle="Drifting Sorrow",db2VignetteID=3848,db2VignetteName="Drifting Sorrow"},
[59184] = {id=59184,name="Borr-Geth",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Borr-Geth"},
[59185] = {id=59185,name="Entangling Web",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It would seem we have a means of luring Mor'Bitan to us. But what good is a web if the prey can run free? For these rituals to work, the liches require a magical conduit. They draw runes with finely ground maldracite to channel anima. I have no doubt Mor'Bitan's necromancers have ground maldracite in the area. If we gather enough, we can draw a rune of binding to trap our target. Work with haste, $p.",objectivesText="Collect 8 jars of Maldracite Dust . Progress: I'm waiting.",rewardGold=257400,rewardXP=1415,rewardItems={178684},starts={{npcID=162487}},ends={{npcID=164326}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="standard"},
[59188] = {id=59188,name="Vaunted Vengeance",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="So you are from my baroness's home world? It must be a special one to breed such powerful individuals. The necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. Three necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes. Collect the plans... and feel free to savor your victims' torment.",objectivesText="Collect Ritual Drafts from the three Architects. Progress: We are hopeful for your success.",rewardGold=257400,rewardXP=1415,rewardItems={175446,175459,175460,175461,178655,178656,178657},rewardChoices={175459,175461,175460,175446},starts={{npcID=164297}},ends={{npcID=164297}},coords={x=0.676,y=0.456,source="quest_giver",zoneID=11462},questType="standard"},
[59189] = {id=59189,name="The Recovery of Tyrande Whisperwind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her. And yet, my mother speaks true. We cannot leave the souls of my people to suffer. We shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei. And in the process, pray that we can save my minn'do as well.",objectivesText="Enter Torghast to recover Tyrande Whisperwind.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174834}},ends={{npcID=174834}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[59190] = {id=59190,name="Seek Your Mark",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I see why Draka sent you in her stead--you accomplish what she could not. We have all the pieces. Now, we must simply put them together. The steps to the ritual are simple: place our fractured crystals in formation around the obelisk. Then comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base. When you are through, return to me.",objectivesText="Prepare the ritual. Progress: Work swiftly.",rewardGold=128700,rewardXP=710,starts={{npcID=164326}},ends={{npcID=164326}},coords={x=0.736,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[59196] = {id=59196,name="Go in Service",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We cannot waste any more time. We must get an audience with the Archon, before this next attack happens! We need to find a way to get you to Elysian Hold... and quickly! Hero's Rest is a place of respite for the aspirants of Bastion . You can see it floating above from across the fields. Meet me there when you can. I have a plan.",objectivesText="Meet Kleia at Hero's Rest. Progress: We must get moving.",rewardGold=23870,rewardXP=175,starts={{npcID=167038}},ends={{npcID=165042}},coords={x=0.544,y=0.642,source="quest_giver",zoneID=10534},questType="standard"},
[59197] = {id=59197,name="Steward at Work",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Stewards are useful for many reasons. They keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support. Your new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.",objectivesText="Use Summon Steward to fix the Beacon of Invocation, then use it to summon Polemarch Adrestes .",rewardGold=119340,rewardXP=710,starts={{npcID=165045}},ends={{npcID=165048}},coords={x=0.528,y=0.478,source="quest_giver",zoneID=10534},questType="standard"},
[59198] = {id=59198,name="On Swift Wings",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Our revered Archon has decided to grace you with an audience. It is your duty to present your discoveries to her, then follow her wise judgment. She holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended. We shall carry you there, for it is a place for those who can fly.",objectivesText="Fly with Adrestes to Elysian Hold.",rewardGold=23870,rewardXP=175,rewardItems={173316,175703},rewardChoices={173316},starts={{npcID=165048}},ends={{npcID=160037}},coords={x=0.528,y=0.456,source="quest_giver",zoneID=10534},questType="standard"},
[59199] = {id=59199,name="Kyrestia, the Firstborne",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="I will escort you to hold audience with the Archon. I beseech you to present your information succinctly and directly. Our wise Archon will hear you and make a decision on the best course of action.",objectivesText="Speak with Adrestes to address the Archon. Progress: None shall doubt the Archon, in her infinite wisdom.",rewardGold=119340,rewardXP=710,starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[59200] = {id=59200,name="The Wards of Bastion",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault. It is concerning that the Forsworn were able to attack Purity in such force... Your orders are to examine the wards. As long as they hold, Bastion stands strong.",objectivesText="Investigate the temple wards in Elysian Hold. Progress: The wards each protect one of the temples of Bastion . If a ward is not active, that temple stands vulnerable.",rewardGold=128700,rewardXP=710,starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[59202] = {id=59202,name="Among the Chosen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Only one rune remains... We should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.",objectivesText="Return to the House of the Chosen.",rewardGold=245700,rewardXP=1415,starts={{npcID=168381}},ends={{npcID=164843}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=11462},questType="standard"},
[59203] = {id=59203,name="Leave Me a Loan",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. However, a few of those customers are late with their payments. And a customer who does not pay is a customer without value. Please ask them to surrender what they owe. I trust you know what to do if they refuse.",objectivesText="Collect 6 Anima Vials from the arena spectators. Progress: Do not try to cheat me out of anything I am owed. I will know.",rewardGold=386100,rewardXP=1415,rewardItems={175413},starts={{npcID=159830}},ends={{npcID=159830}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[59206] = {id=59206,name="Words of the Primus",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it. You came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right. Tell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones. It would be an honor to fight by your side again, .",objectivesText="Return to Oribos.",rewardGold=25740,rewardXP=175,starts={{npcID=164545}},ends={{npcID=164545}},coords={x=0.496,y=0.494,source="quest_giver",zoneID=12876},questType="standard"},
[59207] = {id=59207,name="Unshackled Knowledge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars. I fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine. Most escaped with me, but Lano, Eratus, and Tyrana have not returned yet.",objectivesText="Free Curator Lano , Librarian Eratus , and Historian Tyrana .",rewardGold=289575,rewardXP=6125,starts={{npcID=159248}},ends={{npcID=159248}},coords={x=0.366,y=0.376,source="quest_giver",zoneID=10534},questType="standard"},
[59209] = {id=59209,name="Rebel Reinforcements",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="General Draven looks around.> We require additional reinforcements. I know of two here that are fiercely loyal to the true purpose of Revendreth . The Fearstalker left them here to be consumed by the anima drought due to their allegiance. They are both fully capable of assisting us in our mission. Take this anima stake and infuse them. Direct them to me, I will explain the situation.",objectivesText="Recruit Watchmaster Boromod and Tactician Sakaa . Progress: Are our allies infused?",rewardGold=257400,rewardXP=1415,rewardItems={175414,175427,175428,175429},rewardChoices={175427,175429,175428,175414},starts={{npcID=164394}},ends={{npcID=168471}},coords={x=0.432,y=0.74,source="quest_giver",zoneID=10413},questType="standard"},
[59210] = {id=59210,name="Tainted Cores",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall. We will use our knowledge of his secret ritual to lure him out of the House of Rituals. Take these crystals, . Charge them with anima reclaimed from Mor'Bitan's slain minions. But fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun. That is when we will strike.",objectivesText="Fracture the three Depleted Anima Crystals, then charge the Fractured Anima Crystals with deceased Morbid Ritualists. Progress: Is it done?",rewardGold=257400,rewardXP=1415,rewardItems={175409},starts={{npcID=162487}},ends={{npcID=164326}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="standard"},
[59211] = {id=59211,name="Forgotten Village",expansion=8,mapID=1525,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Dredhollow threats eliminated"}},worldTaskTitle="Forgotten Village"},
[59223] = {id=59223,name="By Any Other Name",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Excellent work, my apprentice! Our laboratory is back in working order! Now, there is one final ingredient we require to complete our potion for Margrave Stradama. You will need to run along to the greenhouse. I've cultivated a sprig of dreadshade that should be ready to harvest. I will prepare the other reagents while you're away. Be safe, apprentice!",objectivesText="Collect Dreadshade Extract for Marileth's potion. Progress: Have you found it?",rewardGold=257400,rewardXP=1415,rewardItems={175410},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[59229] = {id=59229,name="Gargantuan Seeker",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="world",worldTaskTitle="Gargantuan Seeker"},
[59230] = {id=59230,name="Dartanos, Flayer of Souls",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Dartanos, Flayer of Souls"},
[59231] = {id=59231,name="Fathomless Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Forgive me, apprentice... I felt a bit woozy for a moment! But you've done it! You've crafted the potion! I'm so proud of you. What joy your work brought to our margrave! What manner of teacher would I be were I to ask for your help and not offer my own in return? If you have research you must conduct, you have my full support! Let us venture to your laboratory, then. I wait with bated breath to behold your future achievements!",objectivesText="Meet Marileth at the Seat of the Primus.",rewardGold=128700,rewardXP=710,starts={{npcID=159930}},ends={{npcID=168381}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[59232] = {id=59232,name="A Lesson in Humility",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thank you for your service in deposing the Accuser and elevating Lord Chamberlain in her place. The Accuser's unprompted betrayal has rendered her both undeserving and unfit to serve on the Court of Harvesters. Now, please, observe what happens to traitors in Revendreth .",objectivesText="Witness the Accuser's judgment. Progress: Please observe silently, Maw Walker.",rewardGold=126360,rewardXP=710,rewardItems={175434,175435,175436,175437},rewardChoices={175436,175434,175437,175435},starts={{npcID=156381}},ends={{npcID=156381}},coords={x=0.534,y=0.64,source="quest_giver",zoneID=10413},questType="standard"},
[59233] = {id=59233,name="The Prince's New Crown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1533,description="The crown is ready. I will entrust you to deliver it to Renathal. Make haste, . This power will surely attract assailants if word gets out. You may use the mirror to return. Know that I will be dispatching others to destroy it after your arrival. Safe travels, Maw Walker.",objectivesText="Deliver the Crown of the Harvesters to Prince Renathal in Sinfall.",rewardGold=772200,rewardXP=12250,rewardItems={180604,180905,180906,180907,180908},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=171175}},ends={{npcID=158653}},coords={x=0.21,y=0.228,source="quest_giver",zoneID=10534},questType="standard"},
[59234] = {id=59234,name="Mixing A Mess",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=3,objectID=176075,text="Oozing Ingredients collected from slimes"},{orderIndex=1,type=0,amount=3,objectID=164541,text="Oozing Ingredients thrown into Pool of Mixed Monstrosities"}},worldTaskTitle="Mixing A Mess",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59242] = {id=59242,name="Their New Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1543,description="It pains me to leave my mother behind... but the souls of my people must be brought to safety. I heard the attendants in Oribos speaking of a place called Ardenweald . A realm of ancient forests where the spirits of nature slumber. This is a land you know well, is it not? I would see its wonders with my own eyes. Perhaps the spirits there will know how to save my minn'do from the Night Warrior's power.",objectivesText="Take Shandris Feathermoon and the rescued night elf souls to Ysera at the Heart of the Forest in Ardenweald . Progress: You've returned. But what of the others?",rewardGold=772200,rewardXP=12250,rewardItems={175576,179657,179765,179774,179888,181909,181979},rewardChoices={179657,179765,181909,179888,175576,179774,181979},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174834}},ends={{npcID=160262}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[59246] = {id=59246,name="Daughter of the Night Warrior",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=10565,mapID=1670,description="In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance. And... Ardenweald 's destruction. These visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm. Shandris Feathermoon , Tyrande's daughter, is touched by dreams as well. Even now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.",objectivesText="Find Shandris Feathermoon within Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[59254] = {id=59254,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Alaria says that the quilboar kidnapped other members of her expedition. Chances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier. I need to make sure I'm not sending you to your death. We're going to have one last sparring session.",objectivesText="Spar with Captain Garrick .",rewardGold=360,rewardXP=200,starts={{npcID=156651}},ends={{npcID=156651}},coords={x=0.582,y=0.746,source="quest_giver",zoneID=10424},questType="standard"},
[59256] = {id=59256,name="The Fearstalker",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The trap has been set and the Fearstalker has walked right in. Just as I expected, her pride has blinded her to the obvious. Have that vial I gave you earlier ready. It may prove useful in the fight ahead. When you are ready, we can spring the trap.",objectivesText="Speak to the Accuser to trigger the trap, then kill the Fearstalker and collect the Medallion of Dread . Progress: The Fearstalker must be defeated.",rewardGold=510120,rewardXP=1770,rewardItems={175484,175485,175486,175487,175770},rewardChoices={175485,175487,175486,175484},starts={{npcID=168468}},ends={{npcID=168217}},coords={x=0.396,y=0.812,source="quest_giver",zoneID=10413},questType="standard"},
[59258] = {id=59258,name="Home of the Tirnenn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Horned Hunter is no longer here. But I do know where he went. He tracked his prey to the west of here, in the Elder Stand. These woods in particular have grown dangerous as of late, and we are currently beset by invading devourers. They have overrun the roads between here and the Stand. I shall accompany you across the bridge, and see that you are delivered to the Horned Hunter.",objectivesText="Fight your way into Tirna Scithe and find the Horned Hunter.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164627}},ends={{npcID=161353}},coords={x=0.352,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[59259] = {id=59259,name="The Eternal Tormentor",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="world",worldTaskTitle="The Eternal Tormentor"},
[59262] = {id=59262,name="Broken Wings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You help me? Really? Wow! Look at me. What am I? I have beak. Feathers. Scaly toes. I am bird, yes? But birds have wings. And I have arms. Why I not have wings? I broken. I can not fly. Larion nearby, flies so gracefully. I must study her wings up close! You help me?",objectivesText="Bring Kowalskos Ariella's Wing . Progress: If I can study a larion wing, surely I can learn!",rewardGold=289575,rewardXP=6125,rewardItems={175791},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59263] = {id=59263,name="Feathers of Flight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Now, let us see this next to my arm... Look! There many long feathers along the edges of the Larion's wing! And none on mine. This is why I can not fly! Hmm. It will take lots of flight feathers to give me wings. You help?",objectivesText="Bring Kowalskos 100 Larion Flight Feathers . Progress: Feathers... So many feathers...",rewardGold=289575,rewardXP=6125,rewardItems={175792},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59265] = {id=59265,name="Prying Eyes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The Constructs would repurpose the carcass of our necropolis. But we will need its parts for our own ends. Let us deliver a warning to these scavengers. Slay the Constructs amid our wreckage. Pluck the eyes from their skulls. Such is our signature. They will know to fear the darkness once more.",objectivesText="Collect 20 Betrayer's Eyes from constructs in Akarek's Tears. Progress: You offer gifts?",rewardGold=257400,rewardXP=8165,rewardItems={175795},rewardCurrencies={{id=1822,amount=2}},starts={{npcID=164619}},ends={{npcID=158529},{npcID=160518}},coords={x=0.508,y=0.244,source="quest_giver",zoneID=11462},questType="standard"},
[59293] = {id=59293,name="Special Formula",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You may think I'm naturally gassy, but it actually takes a lot of work to build it all up. This is all the result of a nice coating of Pox Nodules . Help me refresh my coating. Just get me near the absorbing pox and I'll pull the nodules right off his slimy skin.",objectivesText="Help Gas Bag collect Pox nodules . Progress: Did you get what he needed?",rewardXP=8165,rewardItems={175843},starts={{npcID=159240}},ends={{npcID=167150}},coords={x=0.542,y=0.68,source="quest_giver",zoneID=11462},questType="standard"},
[59311] = {id=59311,name="How to Catch a Glimmerfly",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Yes! Proper tools collected. Now to catch glimmerflies! Anima drought more severe in northern pools. Many Starving Glimmerflies, most eager to drink from our animyllis blooms . Place blooms, then while glimmerflies are drinking attach to filaments! Then return to me.",objectivesText="Capture 5 Starving Glimmerflies in the Shimmering Pools, then return to Kowalskos . Progress: Glimmerflies will surely help me fly!",rewardGold=386100,rewardXP=8165,rewardItems={176812,180839},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59314] = {id=59314,name="Sinfall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I knew you could be counted on. Revendreth's revival relies on forging pacts with those outside of our realm. The Prince never had any doubt that you would agree to join our cause. He summoned the Court of Harvesters in anticipation of your arrival. Renathal awaits you within Sinfall, where you will be presented to the court.",objectivesText="Report to Prince Renathal in Sinfall.",rewardGold=25740,rewardXP=1020,starts={{npcID=171589}},ends={{npcID=164742}},questType="standard"},
[59315] = {id=59315,name="The Court of Harvesters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Partnerships such as ours will be key to Revendreth's revival. As Harvesters, we have the ability to extend our powers to mortals, though the decision must be unanimous. To that extent, the court has gathered and is awaiting your arrival. Let's not keep them waiting.",objectivesText="Stand before the Court of Harvesters and pledge your loyalty. Progress: You will be welcomed by the court, I have no doubt, but first, you must swear an oath before the Harvesters.",rewardGold=128700,rewardXP=4085,starts={{npcID=164742}},ends={{npcID=164796}},coords={x=0.252,y=0.558,source="quest_giver",zoneID=10986},questType="standard"},
[59316] = {id=59316,name="Binding Power",level=60,requiredLevel=60,faction="none",expansion=8,description="To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.",objectivesText="Complete the soulbinding ritual.",rewardGold=257400,rewardXP=8165,questType="standard"},
[59317] = {id=59317,name="Strengthening the Bond",level=60,requiredLevel=60,faction="none",expansion=8,description="Do you feel it, too? Our connection is stronger than I imagined could be possible. I have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. Sinfall needs our strength. Perhaps it is best we engage in this method now.",objectivesText="Strengthen your bond with Nadjia.",rewardGold=257400,rewardXP=8165,questType="standard"},
[59319] = {id=59319,name="Advancing Our Efforts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="A venthyr's primary responsibility is ensuring that souls are unburdened of their pride, but they must see to other matters as well. We must act beyond the bounds of Revendreth to ensure that the souls of the Shadowlands keep to their fate. Allow me to demonstrate with a simple task for your companion here. This will be the first of many strikes.",objectivesText="Inspect the Command Table and start an adventure. Progress: These calculated strikes will further our cause.",rewardGold=25740,rewardXP=1020,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="standard"},
[59321] = {id=59321,name="Sacred Covenant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Our covenant is more than just pacts and promises. We have immense power, too. And that power we shall bestow upon you in a sacred ritual. Once complete, you will be able to call upon our gifts with ease.",objectivesText="Meet Prince Renathal in the ritual hall on the lower level of the sanctum.",rewardGold=25740,rewardXP=1020,starts={{npcID=164796}},ends={{npcID=171934}},coords={x=0.252,y=0.558,source="quest_giver",zoneID=10986},questType="standard"},
[59322] = {id=59322,name="Shared Souls",level=60,requiredLevel=60,faction="none",expansion=8,description="The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.",objectivesText="Meet The Accuser at the Forge of Bonds.",rewardGold=25740,rewardXP=1020,questType="standard"},
[59323] = {id=59323,name="Anima Awakening",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="This ritual will bestow upon you our gift. We will stir the anima within your soul, awakening a power that has only been known to Harvesters. It has never been performed on a mortal before, but I have been assured that it won't hurt a bit.",objectivesText="Participate in the Harvesters's ritual. Progress: Take your place when you are ready to begin.",rewardGold=25740,rewardXP=1020,starts={{npcID=171934}},ends={{npcID=171934}},questType="standard"},
[59325] = {id=59325,name="A Stalwart Ally",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="We have our work cut out for us, Maw Walker. The Harvesters will not relinquish their power without a fight. You will need stalwart allies at your side. Ones that know how battles are fought within the Shadowlands. Let me be your guide. Together, we will see Revendreth return to its true purpose.",objectivesText="Complete the soulbind process with General Draven .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=161977}},ends={{npcID=172004}},coords={x=0.464,y=0.16,source="quest_giver",zoneID=10986},questType="standard"},
[59327] = {id=59327,name="In the Ruin of Rebellion",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Well, here we are -- Sinfall. Last I saw, the Master was dragging Prince Renathal and his most loyal followers here in a prison convoy. However, this is a forbidden place, wrapped in rumors and mystery. I heard it was once the workshop of Denathrius, where he performed dark experiments. Intriguing to be sure, but we are here to find Renathal. Search below, but proceed with caution. I will send word for the Accuser to make her way here with what allies she can muster.",rewardGold=25505,rewardXP=175,starts={{npcID=158716}},ends={{npcID=158615}},coords={x=0.298,y=0.422,source="quest_giver",mapID=1525},questType="standard"},
[59339] = {id=59339,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Alaria says that the quilboar kidnapped the rest of the expedition... including my son. Chances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier. I need to make sure I'm not sending you to your death. We're going to have one last sparring session.",objectivesText="Spar with Captain Garrick .",rewardGold=200,rewardXP=200,starts={{npcID=156651}},ends={{npcID=156651}},coords={x=0.582,y=0.746,source="quest_giver",zoneID=10424},questType="standard"},
[59342] = {id=59342,name="Taming the Wilds",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="As a hunter, you need a trustworthy beast at your side... or else these quilboar will slaughter you. When you're ready, I'll teach you how to tame such a beast. Then you must find one to be your loyal companion.",objectivesText="Learn Tame Beast from Austin Huxworth , then use Tame Beast on any nearby wildlife. Progress: I'll teach you how to tame beasts. Then you'll need to choose any animals nearby to tame.",rewardGold=565,rewardXP=200,starts={{npcID=154327}},ends={{npcID=154327}},coords={x=0.626,y=0.698,source="quest_giver",zoneID=10424},questType="standard"},
[59343] = {id=59343,name="Kindred Spirits",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have come to the realization that you and I are meant to be the most kindred of spirits. Your enduring nature has enraptured me, and I'm afraid I cannot bear to imagine an afterlife without your beguiling presence. Let us bind our souls, and forever carry each other in both heart and mind.",objectivesText="Complete the soulbinding ritual.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=161979}},ends={{npcID=172046}},coords={x=0.5,y=0.19,source="quest_giver",zoneID=10986},questType="standard"},
[59347] = {id=59347,name="A Monk's Focus",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="You fought well against the harpies, but we all need to become stronger to face what lies ahead. The first step is to find a nice place to meditate and focus yourself. A monk is only as strong as they are focused. Come. I know of such a place.",objectivesText="Follow Kee-La and meditate with her. Progress: Let us meditate. I find meditation always helps clear my mind.",rewardGold=2940,rewardXP=250,starts={{npcID=156885}},ends={{npcID=164835}},coords={x=0.522,y=0.556,source="quest_giver",zoneID=10424},questType="standard"},
[59348] = {id=59348,name="More Wings!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Idea! Maybe I am too heavy. Maybe need more wings! Glimmerflies have lovely wings. With correct bait and strong rope, perhaps we can catch. Please bring Animyllis Blooms . Their nectar is delicious for glimmerflies, and makes them drowsy!",objectivesText="Collect 10 Animyllis Blooms . Progress: Animyllis Bloom nectar is a glimmerfly's favorite sleepytime treat!",rewardGold=289575,rewardXP=6125,rewardItems={175968},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59349] = {id=59349,name="One Last Spar",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Let us have a quick sparring session before we return to camp, . I want to see how this island has pushed you to grow.",objectivesText="Spar with Kee-La .",rewardGold=2940,rewardXP=250,starts={{npcID=164835}},ends={{npcID=156807}},coords={x=0.526,y=0.494,source="quest_giver",zoneID=10424},questType="standard"},
[59350] = {id=59350,name="A Druid's Form",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Thank you for rescuing me, . Allow me to aid you in your druidic studies. To escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same. Come with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.",objectivesText="Commune with the nearby druid stone. Progress: Come. The spirits of nature await us.",rewardGold=2940,rewardXP=250,starts={{npcID=156932}},ends={{npcID=164907}},coords={x=0.454,y=0.492,source="quest_giver",zoneID=10424},questType="standard"},
[59351] = {id=59351,name="Strings and Things",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Glimmerflies are creatures of anima. Though they look delicate, they are quite strong! Filaments from etherwym tails are sturdy. They should help hold onto glimmerflies. Collect for me!",objectivesText="Collect 10 Etherwyrm Filaments . Progress: Etherwyrm Filaments are almost pure anima. Very hard to break!",rewardGold=289575,rewardXP=6125,rewardItems={175967},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59352] = {id=59352,name="A Mage's Knowledge",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Ye got some good spells fer a novice mage. Ye might even be as good as I am one day! But ye don't know Polymorph ! How could ye not know that? Polymorph 's one of a mage's most useful spells. I can teach it tae ye, if ye can find me spellbook. Last I saw, the ogres threw me book in the lake. The LAKE! Go get me book, and I'll show ye how tae cast Polymorph .",objectivesText="Recover Meredy Huntswell 's book at the bottom of the nearby lake. Progress: I hope me book isn't too damaged after sittin' at the bottom o' the lake.",rewardGold=3440,rewardXP=250,rewardItems={175975},starts={{npcID=156886}},ends={{npcID=156886}},coords={x=0.522,y=0.554,source="quest_giver",zoneID=10424},questType="standard"},
[59354] = {id=59354,name="The Best Way to Use Sheep",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="I'm not gonna send ye off without showin' ye how tae properly use this spell. Ye wanna cast Polymorph if ye get yerself into a situation when two foes are fightin' ye at once. Cole and I will spar with ye a bit tae make sure ye know what tae do.",objectivesText="Practice using Polymorph against Meredy and Private Cole . Progress: And don't ye worry, recruit. Ye won't be turnin' anyone into a sheep permanently!",rewardGold=2940,rewardXP=250,starts={{npcID=156886}},ends={{npcID=156886}},coords={x=0.522,y=0.554,source="quest_giver",zoneID=10424},questType="standard"},
[59355] = {id=59355,name="A Hunter's Trap",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="By now, most hunters would have been trained in the art of trapping. Allow me to get you up to speed. We'll start with a freezing trap . In order to make one, you'll have to forage materials from your surroundings. Meredy can provide you with a mote of ice. Scavenge the area for the rest of what is required. And don't delay. You will need that freezing trap to deal with a problem that has cropped up within the camp.",objectivesText="Scavenge parts in the area to create a Freezing Trap . Progress: Did you get the supplies needed? Meredy should have the ice mote , while the other two should be nearby.",rewardGold=1015,rewardXP=200,rewardItems={175979,175980,175981},starts={{npcID=161666}},ends={{npcID=161666}},coords={x=0.524,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[59356] = {id=59356,name="Hunting the Stalker",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="Now that you have your trap, there's a problem we need to deal with. A wild beast has been stalking our camp. It's already stolen some of our food. We have little enough as it is. You and I will work together. Set your freezing trap and lure out whatever this creature is. Once it is caught, I will determine if the beast can be tamed... or if it needs to be put down.",objectivesText="Use your Freezing Trap within the Ogre Ruins to lure out the beast stalking the camp. Progress: Use the Freezing Trap anywhere within the Ogre Ruins. Just don't do it right within the camp.",rewardGold=1015,rewardXP=200,starts={{npcID=161666}},ends={{npcID=161666}},coords={x=0.524,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[59426] = {id=59426,name="Your Personal Assistant",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Here in Hero's Rest, we have a beacon that is the fastest way to draw the Polemarch's attention. It has been quite some time since we have used it, and I am afraid that it has fallen into disrepair. I authorize you to receive a steward companion during your stay here in Bastion . I will call for some to convene here. You may select one to aid you.",objectivesText="Select a steward to aid you, then return to Kalisthene . Progress: Stewards are the force that keep Bastion running.",rewardGold=128700,rewardXP=710,starts={{npcID=165045}},ends={{npcID=165045}},coords={x=0.528,y=0.478,source="quest_giver",zoneID=10534},questType="standard"},
[59427] = {id=59427,name="We Need More Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Laurent's plan is a bit ambitious. Mirrors are most reliable when used to traverse short distances. Traveling to the sanctuary will require a great deal of power, more than he or I have. The shrouded have stores of anima in their compound. With enough of it, the mirror should be stable enough to get us where we need to go.",objectivesText="Collect anima from around The Shrouded Asylum. Progress: Long distance travel requires a great deal of power.",rewardGold=382590,rewardXP=1415,starts={{npcID=158088}},ends={{npcID=158088}},coords={x=0.242,y=0.494,source="quest_giver",zoneID=10413},questType="standard"},
[59430] = {id=59430,name="A Plague on Your House",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though the physical House of Plagues is lost, the knowledge contained within was not. There are survivors here that continue to research and develop new horrifying weapons. In time we will restore the house and rise to even greater power, unleashing creations and plagues never before seen upon our enemies! Perhaps you can help? Speak with survivors and see if any of them can use your aid.",objectivesText="Speak with House of Plagues survivors. Progress: Have you spoken to anyone?",rewardGold=386100,rewardXP=1415,starts={{npcID=165049}},ends={{npcID=157945}},coords={x=0.58,y=0.72,source="quest_giver",zoneID=11462},questType="standard"},
[59441] = {id=59441,name="Soulsmith Yol-Mattar",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Soulsmith Yol-Mattar"},
[59520] = {id=59520,name="Plaguefall: Knee Deep In It",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13228,mapID=1536,description="There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes! These dangers still remain and spread out from the ruins, infecting new victims daily. I need you to travel into the ruins and recover samples from the victims there.",objectivesText="Enter Plaguefall and recover 12 Poxedskin Samples and Margrave Stradama's Plasm . Progress: Have you brought me the Poxedskin Samples ?",rewardGold=1158300,rewardXP=2125,rewardItems={175531,175532,175533,175534},rewardChoices={175532,175534,175531,175533},starts={{npcID=165052}},ends={{npcID=165052}},coords={x=0.594,y=0.73,source="quest_giver",zoneID=11462},questType="dungeon"},
[59554] = {id=59554,name="A Fine Journey",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Aspirants new and ancient, take note! The heralded Agthia's Repose calls. Make the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm! Find the Repose just a short ride southwest of Hero's Rest.",objectivesText="Speak to Keeper Mnemis in Agthia's Repose.",rewardGold=23870,rewardXP=175,starts={{npcID=348558}},ends={{npcID=158078}},coords={x=0.519,y=0.477,source="quest_giver",zoneID=10534},questType="standard"},
[59555] = {id=59555,name="Enemy at the Door",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1698,description="The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever. Our reserves have met the enemy in battle. I need you to break the siege. Report to Heirmir and Marileth. They will give you the means to rain destruction on our foes.",objectivesText="Ride Ragewing and destroy the enemy forces.",rewardGold=257400,rewardXP=8165,rewardItems={182077},starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[59556] = {id=59556,name="Welcome To Our House",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Your ties to the other covenants had me doubting you would return. I see now that was foolish of me. Outsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride. One day, he might return as well. But we cannot afford to wait. In the Primus's absence, I will name you a Necrolord of Maldraxxus.",objectivesText="Speak with Baroness Draka to be inducted as a Necrolord in the Maldraxxus covenant hall. Progress: There is no greater honor than to defend the Shadowlands as a Necrolord of Maldraxxus.",rewardGold=257400,rewardXP=8165,starts={{npcID=158453}},ends={{npcID=165182}},coords={x=0.496,y=0.224,source="quest_giver",zoneID=12876},questType="standard"},
[59578] = {id=59578,name="Let's Get Ready to Humble",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=159504,text="Spar with Aspirants"},{orderIndex=2,type=0,amount=1,objectID=158867,text="Archilon challenged"},{orderIndex=3,type=0,amount=1,objectID=158869,text="Epilon challenged"},{orderIndex=4,type=0,amount=1,objectID=158870,text="Straticus challenged"},{orderIndex=5,type=0,amount=1,objectID=158891,text="Athanos challenged"},{orderIndex=1,type=0,amount=4,objectID=173947,text="Aspirants Defeated"}},worldTaskTitle="Let's Get Ready to Humble",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59581] = {id=59581,name="The Strength of Sinfall",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Chalice District disrupted"}},worldTaskTitle="The Strength of Sinfall",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59583] = {id=59583,name="Welcome to Stormwind",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Now that we are back in Stormwind, I need to deliver my mission report to King Wrynn. In the meantime, I've asked Lindie to accompany you around the city. There's a lot to see and do in Stormwind, so feel free to explore at your leisure. I'll send for you once I've delivered my report to the king.",objectivesText="Meet with Lindie Springstock at the city gate.",rewardGold=1000,rewardXP=505,rewardItems={248336},starts={{npcID=154169}},ends={{npcID=163095}},coords={x=0.738,y=0.914,source="quest_giver",zoneID=1519},questType="standard"},
[59585] = {id=59585,name="We'll Make an Aspirant Out of You",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=165241,text="Equip yourself"},{orderIndex=1,type=15,amount=1,objectID=0,text="Complete the training session"},{orderIndex=2,type=0,amount=34,objectID=165239,text="Successful movement"}},worldTaskTitle="We'll Make an Aspirant Out of You",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59586] = {id=59586,name="What's Your Specialty?",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Dalgrun Steelpine to learn more about specializations!",objectivesText="Speak with Dalgrun Steelpine to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?",rewardXP=505,starts={{npcID=163097}},ends={{npcID=164960}},questType="standard"},
[59587] = {id=59587,name="What's Your Specialty?",level=7,requiredLevel=7,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Frazzle Frostfingers to learn more about specializations!",objectivesText="Speak with Frazzle Frostfingers to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?",rewardXP=505,starts={{npcID=163097}},ends={{npcID=164955}},questType="standard"},
