[59596] = {id=59596,name="Collective Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Souls in Maldraxxus are bound together in war. We draw strength and wisdom from those around us. Should you fall in battle, part of you would remain with your fellow soldiers. Just as they would remain with you. Plague Deviser Marileth has volunteered to teach you the process of soulbinding. From what I have seen, yours will be a powerful bond.",objectivesText="Speak with Plague Deviser Marileth about the soulbinding process.",rewardGold=25740,rewardXP=1020,starts={{npcID=161909}},ends={{npcID=161904}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[59597] = {id=59597,name="Come On, We're Simpatico!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Soulbinding is a wondrous process! I invite you to bind with me to learn how it works, but in time you might bind with others. I have known many soulbinds, but the foremost of them all was Margrave Stradama! Her knowledge, talent and kindness became part of who I am. Now and forever, it is a bond we share. I only hope to be so useful to you, my apprentice! Bound together, I shall grant you all I can and aid you even when we are apart.",objectivesText="Complete the soulbinding ritual with Plague Deviser Marileth .",rewardGold=128700,rewardXP=4085,starts={{npcID=161904}},ends={{npcID=161904}},coords={x=0.39,y=0.328,source="quest_giver",zoneID=12876},questType="standard"},
[59598] = {id=59598,name="Good for the Soul",expansion=8,mapID=1536,questType="world",worldTaskTitle="Good for the Soul"},
