[59600] = {id=59600,name="Rotbriar Trouble",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Grove of Memory defended"}},worldTaskTitle="Rotbriar Trouble",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59601] = {id=59601,name="Assault on the Vestibule",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={172451,176805,176806},questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=165467,text="Herculon empowered"},{orderIndex=3,type=15,amount=1,objectID=0,text="Herculon assisted"}},worldTaskTitle="Assault on the Vestibule",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59603] = {id=59603,name="In Shadowlands Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. When enemies emerge, we are the ones who face them! The threats to the Shadowlands are far more than any one of us can handle. That's where I come in. I will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.",rewardGold=128700,rewardXP=4085,starts={{npcID=165321,x=0.39,y=0.48,zoneID=12876}},ends={{npcID=165321,x=0.39,y=0.48,zoneID=12876}},coords={x=0.39,y=0.48,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="In Shadowlands Service"},
[59604] = {id=59604,name="Takin' Down the Beast",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardGold=128700,rewardXP=710,questType="standard"},
[59605] = {id=59605,name="Takin' Down the Beast",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardGold=128700,rewardXP=710,questType="standard"},
[59607] = {id=59607,name="Takin' Down the Beast",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: Bad bat gon' get smashed! Need ammo! Ammo in Dredhollow!",starts={{npcID=165327}},ends={{npcID=165327}},coords={x=0.462,y=0.778,source="quest_giver",zoneID=10413},questType="standard"},
[59609] = {id=59609,name="No Rest For the Dead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Excellent work, my apprentice! You have completed your training and are now a true Necrolord. That also means you've taken on additional responsibilities. Such is the burden of genius! I believe Baroness Draka wanted to have a word with you.",rewardGold=25740,rewardXP=1020,rewardItems={182254,182263,182272,182281},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161904,x=0.39,y=0.328,zoneID=12876}},ends={{npcID=161907,x=0.496,y=0.502,zoneID=12876}},coords={x=0.39,y=0.328,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="No Rest For the Dead"},
[59615] = {id=59615,name="Every Dog Has Its Day",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Maw Walker, when I heard you were building constructs and a home for souls still loyal to Maldraxxus, I began my search for you! I am loyal and have always wanted a construct form, but the Margrave was unwilling to build one that suited my natural inclinations. I lived my whole life with the curse, it's all I know, and it's all I still want. Would you build a construct for me?",objectivesText="Take specifications for Neena 's construct. Progress: Are you willing to do this?",rewardGold=257400,rewardXP=8165,starts={{npcID=162151}},ends={{npcID=167150}},coords={x=0.698,y=0.41,source="quest_giver",zoneID=11462},questType="standard"},
[59616] = {id=59616,name="Army of One",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mevix will lead the attack, but you will finish it. There are no reinforcements, no cavalry. Only you and your runeblade. Show me the might you wield, outsider. Lay siege to the House of Constructs and bring them to ruin!",objectivesText="Meet Secutor Mevix near the House of Constructs.",rewardGold=121680,rewardXP=710,starts={{npcID=169462}},ends={{npcID=160211}},coords={x=0.396,y=0.466,source="quest_giver",zoneID=11462},questType="standard"},
[59617] = {id=59617,name="Stone Fiend Saboteurs",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={176582},questType="world",db2Objectives={{orderIndex=0,type=0,amount=7,objectID=165372,text="Stolen Missives delivered"},{orderIndex=1,type=0,amount=1,objectID=165377,text="House Redelav"},{orderIndex=2,type=0,amount=1,objectID=165386,text="House Sourwine"},{orderIndex=3,type=0,amount=1,objectID=165387,text="House Darkvein"},{orderIndex=4,type=0,amount=1,objectID=165389,text="House Duskmire"},{orderIndex=5,type=0,amount=1,objectID=165390,text="House Primrose"},{orderIndex=6,type=0,amount=1,objectID=165391,text="House Sinfang"},{orderIndex=7,type=0,amount=1,objectID=165392,text="House Iremoore"}},worldTaskTitle="Stone Fiend Saboteurs",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59621] = {id=59621,name="Breaking a Few Eggs",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="As you can see, we have a gorm problem. I'm not sure what has them so riled up. They've been getting bigger, more hostile. It must be due to the anima drought. If nothing stops them, they'll eat everything! Their egg production is out of control. We can't let their population grow any larger. Please, go in to their nests and destroy as many of their eggs as you can find.",objectivesText="Destroy 10 Gorm Eggs in the Banks of Life.",rewardGold=386100,rewardXP=1415,starts={{npcID=158422}},ends={{npcID=158422}},coords={x=0.466,y=0.294,source="quest_giver",zoneID=11510},questType="standard"},
[59622] = {id=59622,name="Tending to the Tenders",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The eggs are a problem, but so are the gorm that take care of them. The egg-tenders are the leaders of the hive when no matriarch is present. If left unchecked, they will simply produce more eggs and we will be right back where we started. Or worse, one of them could turn into a queen. They are simply too large and hostile for us to properly contain. I see no other recourse than to put them down.",objectivesText="Slay Egg-Tenders Tiom, Bloome and Erys.",rewardGold=372060,rewardXP=1415,starts={{npcID=158422}},ends={{npcID=158422}},coords={x=0.466,y=0.294,source="quest_giver",zoneID=11510},questType="standard"},
[59623] = {id=59623,name="What a Buzzkill",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="What do you say? Fancy one more hunt? One of those little flying pests has grown into a very large flying pest. Large, pristine gorm parts are hard to find in the best of times, and a smith always appreciates a challenge. Besides, I'm worried about the safety of my family and the rest of us in the grove. Bring me the stinger from that big fella and I'll make it worth your while. Do we have a deal?",objectivesText="Deliver Buzzkill's Stinger to Gormsmith Cavina . Progress: I must say, I am looking forward to the opportunity to working with such a fine specimen.",rewardGold=372060,rewardXP=1415,rewardItems={176760,178021,178022,178023,178024,178025,178027,178030,180473,180474},rewardChoices={178024,178021,178022,178023,178025,178027,178030,180474,180473},starts={{npcID=165382}},ends={{npcID=165382}},coords={x=0.516,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[59625] = {id=59625,name="The Only Cure",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Maldraxxus is on the path to reclaiming its rightful role as defender of the Shadowlands. But the treasonous attack on Bastion remains a stain on our honor. We had thought Gharmal's forces routed, but we've received word from the Paragon of Courage that reinforcements have begun arriving at her temple. This threat must be eliminated. I have volunteered to spearhead this operation. Your support would be an asset, $p.",objectivesText="Meet with the Paragon of Courage in Bastion.",rewardGold=25740,rewardXP=1020,starts={{npcID=161988}},ends={{npcID=165412}},coords={x=0.492,y=0.512,source="quest_giver",zoneID=12876},questType="standard"},
[59641] = {id=59641,name="The Nation of Kul Tiras",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=8568,mapID=84,description="Kul Tiras is the greatest naval power on Azeroth, and a former member of the Alliance. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was killed at Theramore. Many have said that Jaina believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father on that day. Perhaps she feels it is time to put the past to rest. Loathe as I am to put Jaina at risk... Kul Tiras must rejoin the Alliance. Light be with you.",objectivesText="Speak with Lady Jaina Proudmoore in Stormwind Harbor.",rewardGold=128700,rewardXP=1415,starts={{npcID=165395}},ends={{npcID=120922}},coords={x=0.858,y=0.316,source="quest_giver",zoneID=1519},questType="standard"},
[59642] = {id=59642,name="Pulling Hairs",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="The abominations are well organized and well supplied. We've not been able to gain any ground. A little disorganization in their supplies and reinforcements might give us an edge. I need you to work you way behind their lines and eliminate three abominations handling their supplies.",rewardXP=8165,rewardItems={176846,176847},questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=175434,text="Stringy Growth plucked"},{orderIndex=1,type=1,amount=8,objectID=176846,text="Corpselouse Bristles collected"},{orderIndex=2,type=1,amount=1,objectID=176847,text="Sour Suckle's Antenna collected"}},worldTaskTitle="Pulling Hairs",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59643] = {id=59643,name="It's Race Day in the Ramparts!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=165475,text="Win the Wheelbarrow Race"},{orderIndex=0,type=3,amount=1,objectID=165419,text="Speak to Grand Marshal Mudrag"}},worldTaskTitle="It's Race Day in the Ramparts!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59644] = {id=59644,name="Blinded By The Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="$p, Sire Denathrius must be stopped. The anima he is stealing from the Shadowlands is weakening the bonds that seal the Jailer within the Maw. That must not happen. Time is short so we must strike quickly. I would like for you to head up to the surface, into that accursed Light, and align as many mirrors as you can find to the focusing mirror atop the portcullis. We will shine a light on Castle Nathria so bright no venthyr will wish to step forth from that fortress to challenge us.",objectivesText="Use the mirrors atop Sinfall to seal the gates of Castle Nathria. Progress: Hopefully you did not get too scorched out there.",rewardGold=257400,rewardXP=8165,starts={{npcID=162688}},ends={{npcID=172673}},coords={x=0.258,y=0.566,source="quest_giver",zoneID=10986},questType="standard"},
[59645] = {id=59645,name="Death Rains",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="With its repeated invasions here, the House of Constructs continues to sully the honor of Maldraxxus . We cannot salvage that honor until justice is done. May we mete it so thoroughly that none will ever attempt this desecration again. Eliminate these traitors with me, $p. Leave none standing.",objectivesText="Slay 30 enemy forces. Progress: See justice done.",starts={{npcID=165591}},ends={{npcID=165591}},questType="standard"},
[59648] = {id=59648,name="Peace by Piece",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="These Maldraxxi fiends have reoccupied my temple. They have entrenched this resurgence with shields powered by necromancy. My disciples--the ones who were not captured and executed by your treacherous compatriots--report the core of a necrotic bulwark to the south. We cannot counter their forces until the shield is brought down. See it done. I will not tolerate your presence otherwise.",objectivesText="Disable the Necrotic Bulwark in the South. Progress: Do not keep me waiting.",rewardGold=257400,rewardXP=8165,starts={{npcID=165412}},ends={{npcID=165412}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59650] = {id=59650,name="No Hesitation, No Surrender",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I cannot fathom where the constructs acquired these reinforcements, but we are once again outnumbered. I seethe at the thought of my fallen disciples. You will make this right. The renegades have established a foothold in the northern region of the temple. Their necrotic magic has granted them a shield, defending them from ranged assault. Disable it. Let nothing impede you. This is the way of Courage.",objectivesText="Disable the Northern Bulwark.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165412}},ends={{npcID=165412}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59653] = {id=59653,name="Don't Cross Courage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We have rendered the enemy holdouts defenseless. My disciples will begin preparations to purge the corruption that your errant kind have left on our home. But more still remain in the inner sanctum of the temple. Their defenses prevent us from flying in en masse, but I can secure a foothold myself. We will cross the breach and annihilate them.",objectivesText="Cross the breach with Xandria . Progress: We shall not waste time.",rewardGold=128700,rewardXP=4085,starts={{npcID=165412}},ends={{npcID=165412}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59656] = {id=59656,name="Well, Tell the Lady",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="That's that, I'd say. The Banks are largely safe now, thanks to you. We can handle the rest of the cleanup on our own now. The Lady of the Falls will want to hear of your success here. Why not go tell her the good news?",objectivesText="Report to the Lady of the Falls in Glitterfall Basin.",rewardGold=25740,rewardXP=175,starts={{npcID=158422}},ends={{npcID=158345}},coords={x=0.466,y=0.294,source="quest_giver",zoneID=11510},questType="standard"},
[59658] = {id=59658,name="Express Dominance",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Conquer Beasts or Slay Enemies"}},worldTaskTitle="Express Dominance",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[59659] = {id=59659,name="Aerial Absolution",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="My kyrian would have attempted to retaliate by now, but these vile interlopers are a devious sort. Their necromancers pollute the air, tainting it with foul power that corrodes our very wings. I cannot advance an assault until they are eradicated. Deal with these befoulers, and I will deliver retribution to the rest.",objectivesText="Slay the three befoulers.",rewardGold=514800,rewardXP=10205,starts={{npcID=165412}},ends={{npcID=165412}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59660] = {id=59660,name="A New Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="My dear $p, I have heard a delightful rumor that you are considering hosting a new court in Sinfall. If that is true, you simply must permit me to recommend staff to help you host a perfect court. Theotar pulls long parchments out of his pockets.> I have been developing ranked lists for every court staff position since the moment I stepped foot in Sinfall. I do not wish to be a braggart, but courts are kind of my specialty.",objectivesText="Recruit the personnel needed to open the Ember Court.",rewardGold=128700,rewardXP=4085,starts={{npcID=161979}},ends={{npcID=164966}},coords={x=0.5,y=0.19,source="quest_giver",zoneID=10986},questType="standard"},
[59661] = {id=59661,name="Ember Court Rehearsal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Look, $p. Venthyr have been throwing fancy courts for themselves ever since they were created. It won't always be easy to impress them with our own court. Don't worry, I've got a plan. I've scheduled a rehearsal court for us to learn the ropes during a practice run. You, me, Renathal, and a few socialites from the covenant who are eager to help us succeed. Relax. It'll be fun!",objectivesText="Help Temel host the rehearsal for the Ember Court.",rewardGold=514800,rewardXP=10205,starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[59674] = {id=59674,name="A Friendly Rivalry",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ah, a fresh soul! Your perspective may prove useful to us. Nemea and I have opposing viewpoints. She lauds her larion, creatures native to Bastion whom she raises and trains as her companions. However, I find that phalynx are the superior beings. They are efficient, obedient, and easy to work with. Please, come learn both of our ways. Perhaps you can decide which of our ways of life is superior.",objectivesText="Meet with Pelodis at Forgefire Outpost or Nemea at Nemea 's Retreat.",rewardGold=25740,rewardXP=175,starts={{npcID=158765}},ends={{npcID=157696},{npcID=158765}},coords={x=0.548,y=0.412,source="quest_giver",zoneID=10534},questType="standard"},
[59676] = {id=59676,name="Harvester of Desire",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="So, here's the sketch: we muck you up to look like one of the servants. This stuff is protected by anti-theft so if 'em clothes think they are being stolen they teleport back here, you an' all. You \"should\" be able to reach the Countess with your message. Just smile, nod, do as you're told, don't talk to anyone, and don't make eye contact with anything that's got wings. They'll know you shouldn't be there.",objectivesText="Infiltrate the Eternal Terrace and deliver Prince Renathal 's message to the Countess . Progress: Still got your head at least. They often try to take that first if they are mad at ya.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=165658}},ends={{npcID=165661}},coords={x=0.524,y=0.352,source="quest_giver",zoneID=10413},questType="standard"},
[59678] = {id=59678,name="Sustain, In Vain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="These turncoats have kept busy. They've opened more portals around the area, allowing themselves to replenish their numbers with little trouble. Even with her might, the Paragon cannot eliminate an endless army. Let us destroy these portals. Without reinforcements to sustain this contingent, it will surely fall.",objectivesText="Disable 6 Necrotic Portals . Progress: The time for mercy is behind us.",rewardGold=257400,rewardXP=8165,starts={{npcID=165591}},ends={{npcID=165591}},coords={x=0.324,y=0.551,source="quest_giver",zoneID=10534},questType="standard"},
[59680] = {id=59680,name="Vesiphone's Vicious Vesper",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Empower the Purity Chime"},{orderIndex=5,type=0,amount=1,objectID=165720,text="Coalesced Fury in Purity's Pinnacle slain"}},worldTaskTitle="Vesiphone's Vicious Vesper",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59698] = {id=59698,name="Wipe the Slate Clean",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="At last, the skies belong to us once more... and in those skies, the storm of our vengeance brews. Come, you who claim to be true Maldraxxi. You wish to right the wrongs of those you once called allies? Rain your justice upon them! Show no quarter!",objectivesText="Fly with Xandria and slay Maldraxxi.",rewardGold=257400,rewardXP=8165,starts={{npcID=165412}},ends={{npcID=165412}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59700] = {id=59700,name="The Last Labor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The evil that threatens Bastion crumbles beneath us. But if we allow this cruel baroness to evade justice, we have not won this day. She cowers in the necropolis above, casting her shadow on this once sacred temple. We will pull the dagger from our backs. This wound will heal.",objectivesText="Slay Baroness Antolyte . Progress: This is all that remains.",rewardGold=514800,rewardXP=10205,rewardItems={182253,182262,182271,182280},rewardChoices={182271,182262,182280,182253},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165412}},ends={{npcID=165752}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59701] = {id=59701,name="Common Ground",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Now that we have a stronghold from which to operate, we need to begin the next stage of my plan to wrest control of Revendreth from the Master. We must convince the Court of Harvesters to convene. We must not have them come here, though. It would be suicide. Go to my old fortress, Darkwall Tower, and place these banners at the four most distant points of the tower. This will ensure the power of the Harvesters and the Master will not be able to interfere with a neutral meeting.",objectivesText="Place four of Renathal's Banners at Darkwall Tower.",rewardGold=257400,rewardXP=8165,starts={{npcID=158653}},ends={{npcID=165661}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[59703] = {id=59703,name="Abombing Run",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=160952,text="Speak with Kynthia"},{orderIndex=1,type=0,amount=50,objectID=160927,text="House of Construct forces slain"},{orderIndex=2,type=0,amount=1,objectID=165684,text="Anima Conduit destroyed"}},worldTaskTitle="Abombing Run",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59705] = {id=59705,name="Things Remembered",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={177186},questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=176461,text="Forgotten Memoranda"}},worldTaskTitle="Things Remembered",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59706] = {id=59706,name="Invitation for the Countess",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Countess, Harvester of Desire. Her wits are sharper than most swords. While I have never seen her carry a weapon, you must assume she is never unprotected. Her mansion mirrors my own, on the Northeastern side of Castle Nathria. Her dominion was that of the Castle Ward, and it is her authority that keeps the nobles in line. She will appreciate a secret message. I will send a dredger ahead with a plan to infiltrate her party. Meet him on the Bridge of Temptation. Good luck.",objectivesText="Find Cudgelface on the Bridge of Temptation leading to the Eternal Terrace.",rewardGold=25740,rewardXP=1020,starts={{npcID=165661}},ends={{npcID=165658}},coords={x=0.41,y=0.548,source="quest_giver",zoneID=10413},questType="standard"},
[59707] = {id=59707,name="Invitation for the Tithelord",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Tithelord is a bully and a coward, just like every Harvester of Envy before him. He is still a force beyond our current reckoning. I have sent Nadjia and Temel to Pridefall Hamlet in the south to ascertain the best, most non-lethal way to reach the Tithelord. Meet them there and use caution. The Tithelord would kill you in less than the blink of an eye if he thought it would gain him more power or authority.",objectivesText="Speak with Nadjia the Mistblade at Pridefall Hamlet.",rewardGold=25740,rewardXP=1020,starts={{npcID=165661}},ends={{npcID=165818}},coords={x=0.41,y=0.548,source="quest_giver",zoneID=10413},questType="standard"},
[59708] = {id=59708,name="Invitation for the Stonewright",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Medallion of Wrath is in the hands of the Stonewright. She is ancient, powerful, and responsible for creating the Stone Legion. She is not someone to be subtle with. It is a very dangerous thing to ask, but would you meet with General Draven at the Dominance Gate? If we are to see the Stonewright attend, she must know the severity of our request, which means both you and Draven walking right in the front door.",objectivesText="Speak with General Draven at the Dominance Gate.",rewardGold=25740,rewardXP=1020,starts={{npcID=165661}},ends={{npcID=165865}},coords={x=0.41,y=0.548,source="quest_giver",zoneID=10413},questType="standard"},
[59709] = {id=59709,name="Afterlife Goes On",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="A new dawn shines on Bastion. I had my reservations, but you have proven that honor yet remains in Maldraxxus . Take my hand once more. I will return you to the temple's entrance. Let all Maldraxxi know of our victory. And for the sake of peace, ensure that this never happens again.",objectivesText="Fly with Xandria to the entrance of the Temple of Courage.",rewardGold=25740,rewardXP=1020,starts={{npcID=165412},{npcID=165752}},ends={{npcID=165794}},coords={x=0.296,y=0.53,source="quest_giver",zoneID=10534},questType="standard"},
[59710] = {id=59710,name="A Curious Invitation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Psst. You there. Yeah, you. You that Maw Walker them fangs been going on about? Huh. I figured you'd be bigger. Anyway, the Taskmaster wants to ahhh ... \"extend his compliments and an invitation to visit his workings.\" That's a fancy word for a bunch of rocks me and my mates are diggin' up. If you're keen an' all that, pop down to Feeder's Thicket and meet with the fang's courier, Araak. He'll get you sorted right out.",objectivesText="Meet with Courier Araak . Progress: The Taskmaster don't like waiting.",rewardGold=1230,rewardXP=175,starts={{npcID=165859}},ends={{npcID=169238}},coords={x=0.608,y=0.624,source="quest_giver",zoneID=10413},questType="standard"},
[59711] = {id=59711,name="Harvester of Envy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thank you for meeting us at a minimum safe distance from the Caretaker's Manor. There are enough people around here that may still find the idea of me in a cage to be worth the trouble. It is too dangerous for you or I to speak to the Tithelord . He is too impulsive and eager to please Denathrius. I recommend we send Temel . The stone fiend is a common messenger for Revendreth and few aside from a handful of observers will bat an eye at his arrival. Just shove him when you are ready.",objectivesText="Guide Temel through the Caretaker's Manor and deliver Prince Renathal 's message to the Tithelord .",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=165818}},ends={{npcID=165661}},coords={x=0.722,y=0.748,source="quest_giver",zoneID=10413},questType="standard"},
[59712] = {id=59712,name="The Lay of the Land",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="So, yeah, not sure why he wants you. Based on a long time working for him, I'm gonna say he wants to use you to do something unsavory to further his interests. But, I'm biased. I could tell you so many stories. Let's go check on my friend, Nadjia.",objectivesText="Check on Nadjia and investigate Taskmaster Matyas's camp. Progress: Have you found Taskmaster Matyas's journal yet?",rewardGold=193050,rewardXP=710,rewardItems={180177},starts={{npcID=169238}},ends={{npcID=165921}},coords={x=0.594,y=0.666,source="quest_giver",zoneID=10413},questType="standard"},
[59713] = {id=59713,name="Active Ingredients",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Matyas will be difficult to handle until we can take my sinstone from him. We need something to knock him out. Will you fetch a few ingredients for me, mortal? I have a cunning plan.",objectivesText="Gather ingredients for Nadjia's mixture. Progress: Do you have the ingredients?",rewardGold=386100,rewardXP=1415,rewardItems={177713,177714},starts={{npcID=165864}},ends={{npcID=165864}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59714] = {id=59714,name="A Fine Vintage",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We will need something special to use as the base of our mixture. To get him to drink it down he will have to believe you've brought him a gift. He fancies himself quite the connoisseur. Some ancient and stuffy vintage will tempt him. Check the old cellar near the ruins. It once held supplies. Perhaps a bottle still lingers in the depths. Araak and I will work out the other details.",objectivesText="Bring Nadjia a fancy beverage. Progress: Have you found a suitable beverage?",rewardGold=386100,rewardXP=1415,rewardItems={177765},starts={{npcID=165864}},ends={{npcID=165864}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59715] = {id=59715,name="Message for Matyas",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Alright. Everything is prepared. When you are ready, ask Courier Araak to summon Taskmaster Matyas as though you have just arrived. I am sure a gift of a favorite drink will tempt him and the poison we've concocted will incapacitate him long enough to take my sinstone from him. Our plan will work flawlessly!",objectivesText="Summon Taskmaster Matyas back to camp.",rewardGold=28538,rewardXP=710,starts={{npcID=165864}},ends={{npcID=166081}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59716] = {id=59716,name="Comfortably Numb",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="A mortal in Revendreth . It's rumored that you can traverse the Maw? Astonishing. I have so many questions. But, I must restrain my curiosity. I have a ... shall we say ... proposition for you that I feel would be advantageous for us both. If it is true that you are able to freely travel these lands then you have access to certain information I cannot reach. You see how you could be useful to me? Come, let us discuss the matter further.",objectivesText="Poison the Taskmaster to get Nadjia's sinstone . Progress: My sinstone, please.",rewardGold=28538,rewardXP=710,rewardItems={175415,175416,175417,175418,175495,175496,175497,175498,177881},rewardChoices={175496,175498,175497,175495,175415,175418,175417,175416},starts={{npcID=166081}},ends={{npcID=165864}},coords={x=0.602,y=0.694,source="quest_giver",zoneID=10413},questType="standard"},
[59717] = {id=59717,name="Things Remembered",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=176461,text="Forgotten Memoranda"}},worldTaskTitle="Things Remembered",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59718] = {id=59718,name="Parasol Peril",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={182695},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=165852,text="Land safely with parasol"}},worldTaskTitle="Parasol Peril",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59719] = {id=59719,name="The Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Well, we have quorum. You have done all you can do for us at this stage, Maw Walker. It falls to me, now, to convince these ancient fools to forsake the greatest patron in all of their reality and throw their lot in with me, a failed rebel with a \"new\" plan. Let us see if I can still sway a crowd, as it were. Wish me luck.",objectivesText="Witness the Court of Harvesters gathering.",rewardGold=128700,rewardXP=4085,rewardItems={180928,180929,180930,180931},starts={{npcID=165661}},ends={{npcID=165661}},coords={x=0.41,y=0.548,source="quest_giver",zoneID=10413},questType="standard"},
[59720] = {id=59720,name="Harvester of Wrath",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We walk in the winged shadows of my brothers and sisters in arms, Stoneborn I have trained since they were first carved from stone. This is an ancient rite. If we cross this bridge on foot, defeating any who would dare stop us, we may have an audience with the mother of the stoneborn. However, know that our safe return is not guaranteed, so try not to offend her. I do not look forward to this.",objectivesText="Cross the Bridge of Defiance on foot.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=165865}},ends={{npcID=165661}},coords={x=0.402,y=0.306,source="quest_giver",zoneID=10413},questType="standard"},
[59721] = {id=59721,name="Becoming the Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Reldorn grins at you.> He knew you'd be back! The Horned Hunter went on ahead to prepare the hunting ground. He said you should join him as soon as you can. Now that you have the materials for the trap, you just need to reach him... It's dangerous territory to traverse, but I've been devising a glamour that should help you avoid the attention of the roaming beasts. Maybe if it's useful, you could put in a good word for... Ahem. Anyway, we should focus on your quarry. Good hunting, friend.",objectivesText="Find Huln Highmountain within the Elder Stand.",rewardGold=128700,rewardXP=4085,starts={{npcID=164627}},ends={{npcID=161353}},coords={x=0.352,y=0.512,source="quest_giver",zoneID=11510},questType="standard"},
[59722] = {id=59722,name="Grand Theft Necropolis",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="The necropolis is safe and secure, but we can only maintain a portal to the Seat of the Primus for a short time. Khaliiq will return with you and work on establishing a permanent portal connection.",objectivesText="Use the portal to meet Khaliiq in the Seat of the Primus.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164679}},ends={{npcID=173306}},coords={x=0.586,y=0.32,source="quest_giver",zoneID=11462},questType="standard"},
[59724] = {id=59724,name="The Field of Honor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thanks to you, , I am free of Matyas's control for the first time in ... well, a very long time. Now, together, we will seek my vengeance. I've laid a solemn duty upon you by naming you as my second for this duel. I know not the code in your homelands but in mine, it is your task to secure the field. Matyas and his followers are garrisoned at Witherfall Ruin nearby. Unless I miss my guess, that's where he will have run. I will prepare for the battle and join you soon.",objectivesText="Clear Taskmaster Matyas's followers from Witherfall Ruins.",rewardGold=386100,rewardXP=1415,starts={{npcID=165864}},ends={{npcID=166616}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59725] = {id=59725,name="Archivist on the Edge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="If the curse isn't removed, Qadarin will waste away until nothing is left! We used to bind and seal curses just like this all the time, but we haven't had to deal with one in ages. Go to Archivist Dreyden at the Grove of Memory. He will know which curse this is and can give you its scroll. Bring it back so we can figure out what we need in order to cast a counter-curse. Hurry, !",objectivesText="Speak with Archivist Dreyden at the Grove of Memory.",rewardGold=25740,rewardXP=1020,starts={{npcID=161509}},ends={{npcID=165867}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[59726] = {id=59726,name="It's a Trap",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="At last, I will have my vengeance! I am certain Matyas will flee again if he sees me first so you will need to confront him on my behalf, friend. Then, while he's distracted, I will engage him. At that point, your obligation as my second is a formality. You must assure Matyas does not dishonor the duel and cheat. When he inevitably does, I expect you'll help me defeat him. He's just through the portcullis there.",objectivesText="Approach Matyas to start the duel. Assist Nadjia when Matyas cheats. Progress: Matyas will apologize, or he will die.",rewardGold=758160,rewardXP=1770,rewardItems={177640,178053,178054,178055,178056,178057,178058,178059,178060},rewardChoices={178057,178058,178056,178055,178054,178059,178053,178060,177640},starts={{npcID=166616}},ends={{npcID=166616}},coords={x=0.602,y=0.786,source="quest_giver",zoneID=10413},questType="standard"},
[59731] = {id=59731,name="An Expected Guest",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="While we await word from Huln, another matter of importance has arisen. Bwonsamdi has returned to Ardenweald. Lord Herne believes he is here to request an audience with the Winter Queen. The loa of death, however, pursues a different purpose. One that I have glimpsed in my dreams. Meet with Bwonsamdi . Discover what fate has in store for the both of you.",objectivesText="Meet Bwonsamdi in the Heart of the Forest within Ardenweald.",rewardGold=25740,rewardXP=850,starts={{npcID=160262}},ends={{npcID=165951}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[59732] = {id=59732,name="Something Extra for the Winter Queen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8500,mapID=1565,description="Ya did good wit' how ya handled Mueh'zala. Me be wantin' ta return da favor. We be friends, after all... riiiight? Dat nasty loa be at me mercy now. Him been mutterin' about some tings he stole from ya Winter Queen. Come along ta me Necropolis. Ya can see what Ol' Bwonsamdi be talkin' about for yaself. Ya gonna come back with someting nice for her majesty... reeeeeal nice.",objectivesText="Travel with Bwonsamdi to the Necropolis in Nazmir.",rewardGold=25740,rewardXP=1020,starts={{npcID=165951}},ends={{npcID=122688}},coords={x=0.482,y=0.524,source="quest_giver",zoneID=11510},questType="standard"},
[59739] = {id=59739,name="The Problem with Containing a Death Loa",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8500,mapID=863,description="Me know Mueh'zala still be hidin' someting. Ol' Bwonsamdi gonna find out what dat be. But dis old loa's presence be drawin' all da undead in Nazmir ta me doorstep! Me be needin' some time ta get Mueh'zala talkin'. Dere be a troll, Zel'han, leadin' da undead. Kill him and show Mueh'zala him broken armor. Dat should end any hope he be havin' of escapin'.",objectivesText="Kill Zel'han the Betrayer and recover his armor. Progress: Zel'han be marchin' in here wit ya head. Me gonna enjoy seein' ya soul tortured in da Maw.",rewardGold=514800,rewardXP=10205,rewardItems={180787},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=122688}},ends={{npcID=166018}},coords={x=0.396,y=0.246,source="quest_giver",zoneID=8500},questType="standard"},
[59740] = {id=59740,name="Repair and Restore",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,description="You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead. It's quite easy once you've found the fragments, but there are a few things of note to keep in mind. Repaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. Here's a few shards to get you started. Restore the mirror to working order and see where it leads.",objectivesText="Repair the Broken Mirror and reap the rewards. Progress: I have complete faith in your abilities.",rewardGold=25740,rewardXP=175,rewardItems={182112},starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[59741] = {id=59741,name="Dark Mojo for a Dark Loa",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8500,mapID=863,description="How many times must de Necropolis come under attack? I suppose no one ever said worshipping Bwonsamdi would be easy... Bwonsamdi seeks to force Mueh'zala into revealing his secrets, and I must do my part to help. De undead swarming de Necropolis are animated by Mueh'zala's dark mojo . Bwonsamdi needs some of dat mojo to finish his ritual. Strike down de undead and claim it.",objectivesText="Recover 100 Dark Mojo from undead attacking the Necropolis. Progress: You got me dat mojo? I be usin' it ta control Mueh'zala durin' me ritual.",rewardGold=257400,rewardXP=8165,rewardItems={177818},starts={{npcID=165968}},ends={{npcID=122688}},coords={x=0.394,y=0.246,source="quest_giver",zoneID=8500},questType="standard"},
[59742] = {id=59742,name="Delaying the Other Side",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8500,mapID=863,description="Many of Bwonsamdi 's worshippers did not make it inside when de undead began swarming de Necropolis. We need a few more of dem to complete Bwonsamdi 's ritual to uncover Mueh'zala's plans. Take dis powder and throw it on de worshippers who are stuck outside. It should dispel de dark magic dat afflicts dem. As for de ones who are already dead... dey will serve Bwonsamdi beyond de grave. Dat is all we could ever ask for.",objectivesText="Use Strange Powder on 6 Injured Bwonsamdi Worshippers .",rewardGold=257400,rewardXP=8165,starts={{npcID=165968}},ends={{npcID=122688}},coords={x=0.394,y=0.246,source="quest_giver",zoneID=8500},questType="standard"},
[59743] = {id=59743,name="The Spider on the Wall",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={177693,177710,177712},questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=165966,text="Speak with Khaliiq"}},worldTaskTitle="The Spider on the Wall",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59747] = {id=59747,name="A Lost Soul",level=60,requiredLevel=60,faction="both",expansion=8,description="Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia. She was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her. Please end her misery.",objectivesText="Bacilia the Lost slain. Progress: Have you completed this task?",starts={{npcID=166096}},ends={{npcID=166096}},questType="standard"},
[59748] = {id=59748,name="No Peace In Death",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description=". I have a favor to ask, if I may. This realm... The sense of honor and purpose that guides its denizens calls to me. My life was defined by such values. Maldraxxus , for a time, shared them with me... But I returned from the Maw to a land rife with treachery. I'd like to speak with the Paragon about Bastion.",objectivesText="Talk to the Paragon of Courage with Alexandros.",rewardGold=128700,rewardXP=4085,starts={{npcID=165795}},ends={{npcID=165794}},coords={x=0.416,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[59749] = {id=59749,name="One Little Whisper",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8500,mapID=863,description="Here be da deal, . To get Mueh'zala talkin', we gotta feed him a teeny bit a da life essence of everybody in dis room. Why ya be lookin' at me like dat? When has ol' Bwonsamdi ever let ya down? Me gonna use da mojo ya got to pull da truth outta him while he be feedin'. Oh, uh, just two more tings. First, I need ya to be ringin' an invitation to a special... friend. Den I be giving ya more of me mojo powder. Use it during da ritual if any o' me followers be gettin' too weak.",objectivesText="Ring the gong to summon the special guest, then use mojo powder in the ritual to fuel Mueh'zala. Progress: I be eager to hear what ol' Mueh'zala be have ta say...",rewardGold=257400,rewardXP=8165,rewardItems={177817,179620,179623,179773,181877},rewardChoices={179623,179773,181877,179620},starts={{npcID=122688}},ends={{npcID=122688}},coords={x=0.396,y=0.246,source="quest_giver",zoneID=8500},questType="standard"},
[59750] = {id=59750,name="How to Get a Head",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="An eager rookie who wants to be champion of the arena? People love a story like yours, but the first step is to get you noticed. Here's the plan. Marcel Mullby needs bloodtusk skulls , but it takes a real fighter to get those! You go kill some bloodtusks, use my knife to collect their heads, and deliver them to Mullby. That should get you recognition.",objectivesText="Collect 12 Bloodtusk Skulls and deliver them to Marcel Mullby . Progress: You deliver those skulls?",rewardGold=386100,rewardXP=1415,rewardItems={177835,177837},starts={{npcID=161559}},ends={{npcID=161559}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[59751] = {id=59751,name="Through the Shattered Sky",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="When Sylvanas shattered the Helm of Domination, she was touched by the power it released. I can sense the echoes of that power, and I know where she has gone. If you wish to rescue your leaders, the shattered helm can open a path. It cannot bring you back, however. That you must do on your own. The risk is great, , but there is no other way. We will begin the ritual at once.",objectivesText="Complete the ritual at the Frozen Throne to open the rift into the Maw.",rewardGold=117000,rewardXP=3410,starts={{npcID=169076}},questType="standard"},
[59752] = {id=59752,name="A Fractured Blade",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="The chaotic energies of this place have scattered the Ebon Blade. I don't think Azeroth's blessings will reach you here, <class>. We will need allies if we are to survive this place. We should find them quickly, before they are overcome.",objectivesText="Rally 10 Knights of the Ebon Blade in the Crucible of the Damned. Progress: We have no time for chatter. Let's find those knights!",starts={{npcID=165918}},ends={{npcID=165918}},questType="standard"},
[59753] = {id=59753,name="Ruiner's End",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="One of the... larger fiends... has several of our knights engaged... Hurry to their aid... lest we lose more of our dwindling forces. Go... it is too late for me...",objectivesText="Defeat Ruiner Maroth in the Crucible of the Damned. Progress: Our allies fall as you stand idle.",rewardGold=234000,rewardXP=6815,starts={{npcID=170624}},ends={{npcID=170624}},questType="standard"},
[59754] = {id=59754,name="On Blackened Wings",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="It's a relief to see friendly faces again. But we have little time for pleasantries. Thrall is wounded, and we are being hunted by the denizens of this realm. We must seek shelter at once. Come, I believe I know of a place.",objectivesText="Assist Jaina in escaping the Mawsworn in Calcis. Progress: What are you doing? This is no time for talk!",starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59755] = {id=59755,name="A Flight from Darkness",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="There's a cave not far from here. If we hurry, we can seek refuge. Those fiends will give chase if they spot us. Be prepared for a fight!",objectivesText="Escort the assembled forces from Calcis to Forlorn Respite. Progress: This way!",starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59756] = {id=59756,name="A Moment's Respite",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="Anduin insisted that our allies would come for us. I confess I had begun to doubt him. I'm sure you have many questions. I'll do what I can to provide answers, but I'm afraid even after... What has it been... weeks? Longer? Time loses all meaning in a place of such darkness. Forgive me. Let me tell you what little I can.",objectivesText="Speak with Jaina in Forlorn Respite to learn what she knows about the Maw. Progress: I will tell you what I can.",starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59757] = {id=59757,name="Field Seance",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="If these souls have information we need, we will take it from them. Even after being shattered by the Banshee, the helm fragment given to you by Bolvar holds the power of Domination. With it, we should be able to take control of the spirits long enough to find out what they know. They will need to be sufficiently weakened before we can break them. I'm confident you're more than capable of that task.",objectivesText="Use the Shattered Helm of Domination to command 5 Malice Shadows in the Planes of Torment. Progress: Do you wish to speak to me, or to the dead?",rewardGold=234000,rewardXP=6815,rewardItems={178495},starts={{npcID=165918}},ends={{npcID=165918}},questType="standard"},
[59758] = {id=59758,name="Speaking to the Dead",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="Look over to the ridge. There lies our quarry! No telling how many souls are writhing together within that amalgam. With any luck, one of them might be coherent enough to give us answers.",objectivesText="Use the Shattered Helm of Domination to command the Tormented Amalgamation in the Planes of Torment. Progress: What are you waiting for?",rewardGold=234000,rewardXP=6815,rewardItems={184313},starts={{npcID=166723}},ends={{npcID=166723}},questType="standard"},
[59759] = {id=59759,name="The Lion's Cage",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="Anduin is being kept in a place the shades call the Tremaculum. It's not far, but the way is perilous. I have tried more than once to free him from his captors, but the forces holding him are too great for me to handle alone. I'm counting on your presence to tip the scales.",objectivesText="Find King Anduin Wrynn in the Tremaculum.",rewardGold=117000,rewardXP=3410,starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59760] = {id=59760,name="The Afflictor's Key",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="Sylvanas thinks us broken. She believes she has already won. We will show her how mistaken she is. First, I will need your help. The bonds that hold me are impossibly strong. We will need the key to free me of them. My... imprisonment here has been overseen by a creature they call the Afflictor. The key is likely in its possession.",objectivesText="Collect the Afflictor's Key from Phael the Afflictor in the Tremaculum and unlock the Mawforged Shackles. Progress: Did you find the key?",rewardGold=234000,rewardXP=6815,rewardItems={178558},starts={{npcID=167833}},ends={{npcID=167833}},questType="standard"},
[59761] = {id=59761,name="An Undeserved Fate",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="I have seen many souls brought here during my detention. The Jailer seems to want to break them, to twist them into his service... or worse. No soul deserves such a fate, . The Mawsworn here hold the keys to their chains. Free as many as you can and we'll get them away from here.",objectivesText="Collect Mawsworn Keys from Mawsworn forces in the Tremaculum and use them to free 15 Shackled Souls . Progress: Free those souls, <name>. They should not be bound here.",rewardGold=234000,rewardXP=6815,rewardItems={178553},starts={{npcID=167833}},ends={{npcID=167833}},questType="standard"},
[59762] = {id=59762,name="By and Down the River",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="Our next step is clear. We must travel to Zovaal's Cauldron--a frightful place I've heard spoken of in fanatical whispers. It's a forge of sorts that lies across the River of Souls. I have only been there a handful of times, but I have seen Baine held captive by the soldiers there. If fortune favors us, he'll still be nearby. Once he's safe, we can see about finding this waystone the shade spoke of.",objectivesText="Cross the bridge over Gorgoa, the River of Souls. Progress: We must hurry!",starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59765] = {id=59765,name="Wounds Beyond Flesh",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="Even as Baine's flesh mends, his spirit draws closer to death. I have seen dark magic like this before... among the Shadowmoon clan. The Jailer's minions must have inflicted a similar malady upon Baine. The only cure for the Shadowmoon's curse was to find the object they used to poison the spirit and shatter it. The sorcerers of this realm wield ornamental daggers. That might be what we're looking for. We must find the one that they used on Baine--quickly!",objectivesText="Collect a Wither Blade from a Mawsworn Soulrender in Detrithos. Progress: We can only hope Baine's curse was inflicted by one of the sorcerers here.",rewardGold=234000,rewardXP=6815,rewardItems={180050},starts={{npcID=166981}},ends={{npcID=166981}},questType="standard"},
[59766] = {id=59766,name="A Good Axe",level=50,requiredLevel=50,faction="both",expansion=8,mapID=1648,description="I was a damned fool for throwing my axe at that sea hag. We can't afford to lose focus. The battle ahead won't be easy. I'll need another weapon to help us fight to the waystone. Looks like these soldiers have plenty of armaments. Let's keep an eye out for one I can use.",objectivesText="Find a suitable weapon for Thrall amongst the Mawsworn Armaments in Detrithos. Progress: There should be something I can use around here...",starts={{npcID=166981}},ends={{npcID=166981}},questType="standard"},
[59767] = {id=59767,name="The Path to Salvation",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="We must move quickly if we wish to find the waystone. The soul mentioned it overlooks the Cauldron, which would put it somewhere upon the ridge on the other side. Unfortunately, this area is swarming with enemy forces. We'd best avoid engaging them, lest we draw the Jailer's attention. I can shield us from sight, but we all have to stay together.",objectivesText="Lead your allies past Zovaal's Cauldron. Progress: Stay close. We cannot risk being seen by the Jailer's forces.",starts={{npcID=166980}},ends={{npcID=166980}},questType="standard"},
[59770] = {id=59770,name="Stand as One",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="I've never seen markings like these before. I've studied titan artifacts, but this appears to be made by a different hand. Hmm. It doesn't respond to me. I think Jaina's right. The waystone is reacting to your presence. Perhaps you'll have better luck activating it. Stay on your guard. The Jailer's forces paid this no mind when it was dormant, but there's no telling what they'll do if that changes.",objectivesText="Activate the Eroded Waystone in Cocyrus.",rewardGold=4000,rewardXP=8520,starts={{npcID=167833}},ends={{npcID=167833}},questType="standard"},
[59771] = {id=59771,name="History of Corruption",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={177836},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=158159,text="Vesper of History rung"}},worldTaskTitle="History of Corruption",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59773] = {id=59773,name="Seek the Ascended",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="When you arrive in Bastion , seek out one of the kyrian. Explain that you require an audience with the Archon. Like the Arbiter, she is one of the Eternal Ones who rule over the Shadowlands. If anyone can guide you to the truth, it is the Archon. Perhaps she will even know a way to end this anima drought. Once you find the answers you seek, you are welcome to return to Oribos. Purpose guide your path, mortal.",objectivesText="Journey to Bastion to inquire about the Maw kyrian.",rewardGold=118170,rewardXP=710,starts={{npcID=175133}},ends={{npcID=166227}},questType="standard"},
[59774] = {id=59774,name="Welcome to Eternity",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Forgive my reaction. You see, the way from Oribos has been closed for quite some time. We did not know if it would ever open again. I welcome you, noble soul, to Bastion . Your deeds in life have earned you a most glorious fate! You are to become a kyrian, a winged bearer of the dead. My name is Kleia . It would be an honor to introduce you to our beautiful realm. There is much you must learn before your journey can begin. Gather yourself. When you are ready, we will venture on.",objectivesText="Speak with Kleia .",rewardGold=118170,rewardXP=710,starts={{npcID=166227}},ends={{npcID=165107}},coords={x=0.374,y=0.764,source="quest_giver",zoneID=10534},questType="standard"},
[59776] = {id=59776,name="From the Mouths of Madness",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="I cannot express my gratitude enough for your help, champion. We mustn't linger, however. The Jailer's forces will soon be alerted to the disturbance here. Let us leave this place at once!",objectivesText="Return to Lord Darion Mograine in Forlorn Respite and see what he has learned. Progress: The fiend is ready to talk. Let's get on with it.",rewardGold=117000,rewardXP=3410,starts={{npcID=167833}},ends={{npcID=167833}},questType="standard"},
[59781] = {id=59781,name="The Last Guy",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You're not the first newcomer wanting to become famous. There've been a lot like you around! The last few wanted to prove themselves by killing a giant bloodtusk... none of them ever returned! You want to get recognition? Go find all those missing newcomers and kill the bloodtusk yourself.",objectivesText="Find 5 Newcomer Corpses and slay Deadeye . Progress: Did you prove yourself?",rewardGold=145050,rewardXP=1770,rewardItems={175725},rewardChoices={175725},starts={{npcID=161559}},ends={{npcID=161559}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[59789] = {id=59789,name="Tithe and Taxes",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={177839},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166228,text="Anima Collector obtained"},{orderIndex=4,type=0,amount=1,objectID=166228,text="HIDDEN: ANIMA CONTAINERS"}},worldTaskTitle="Tithe and Taxes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59800] = {id=59800,name="Team Spirit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on. Enter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!",objectivesText="Douse 15 Arena Challengers with the Flask of Team Spirit .",rewardGold=365040,rewardXP=1415,rewardItems={177877},starts={{npcID=161559}},ends={{npcID=161559}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[59801] = {id=59801,name="Take the Power",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Wait! Before you enter, I would ask something of you. While we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm. Whatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves. Keep an eye out for any anima within the village. We will put it to better use elsewhere.",objectivesText="Collect 8 Animacones . Progress: Were you able to find any anima?",rewardGold=386100,rewardXP=1415,rewardItems={177878},starts={{npcID=160439}},ends={{npcID=160439}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[59802] = {id=59802,name="The Crumbling Village",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this? There is only one way to be sure. Come with me to the village. Or what remains of it.",objectivesText="Follow Partik .",rewardGold=25740,rewardXP=175,starts={{npcID=160439}},ends={{npcID=160439}},coords={x=0.742,y=0.324,source="quest_giver",zoneID=11510},questType="standard"},
[59803] = {id=59803,name="For Honor",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Win Duels against Players or Honorable Duelists"},{orderIndex=1,type=0,amount=7,objectID=166257,text="Duel Won Against Player"},{orderIndex=3,type=0,amount=9,objectID=166256,text="Win Duel Against Honorable Duelist"}},worldTaskTitle="For Honor",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[59804] = {id=59804,name="Gateways of Horror",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=158159,text="Vesper of History rung"},{orderIndex=1,type=0,amount=3,objectID=166237,text="Void Gateways closed"}},worldTaskTitle="Gateways of Horror",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59805] = {id=59805,name="Maw Manifested",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=863,description="Ya heard it from Mueh'zala himself... tanks to ol' Bwonsamdi . Dere be an ancient spirit trapped in da Maw. Me bettin' da Winter Queen gonna want it back. Good ting ya been goin' down dere yaself, hm? Should be nice an' easy for ya. Me gonna clean up da rest of da undead here. Meet ol' Bwonsamdi in Ardenweald when ya get back.",objectivesText="Travel to the Maw to find the lost wild god of Ardenweald .",rewardGold=25740,rewardXP=1020,rewardItems={177817},starts={{npcID=122688}},ends={{npcID=171655}},coords={x=0.396,y=0.246,source="quest_giver",zoneID=8500},questType="standard"},
[59808] = {id=59808,name="Muck It Up",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=166254,text="Recovered Primordial Muck thrown"},{orderIndex=2,type=1,amount=999,objectID=177880,text="999"}},worldTaskTitle="Muck It Up",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59809] = {id=59809,name="On De Other Side",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13309,description="Ay dere, ... It be your ol' friend, Bwonsamdi ! I hear ya be workin' for da Winter Queen. Seems ya be makin' quite a name for yaself! Ardenweald be in grave danger, but da Queen... well, she be too proud to deal with ol' Bwonsamdi . Ya wanna save da forest, mon? Come visit me on da Other Side. I gonna be waitin' for ya...",objectivesText="Use the deathstone to travel to the Other Side.",rewardGold=128700,rewardXP=4085,rewardItems={177904},starts={{npcID=166265}},ends={{npcID=166281}},questType="standard"},
[59811] = {id=59811,name="Taking Inventory",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13309,mapID=1565,description="Dark forces be at work, . Ardenweald be where loa go ta be reborn after dey die on Azeroth. But some of da loa who be sleepin' in Ardenweald have gone missin'! Gotta be someone powerful behind it, takin' dem from right under da Winter Queen... Ol' Bwonsamdi can't be havin' loa vanishin' from Ardenweald. Dat could be me someday! No, no... we gonna put a stop to dis! Go back ta Ardenweald and search for da missin' loa.",objectivesText="Search the Tranquil Pools for missing loa pods. Progress: Dark forces be at work in Ardenweald...",rewardGold=257400,rewardXP=8165,starts={{npcID=166281}},ends={{npcID=166281}},questType="standard"},
[59812] = {id=59812,name="Following the Trail",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1565,description="I got a bad feelin' about dis, mon. Wildseeds don't just go missing... especially da kind wit' powerful loa in dem! Even da bad eggs like Hakkar and Dambala be protected by da Winter Queen. Someone... or someting... must be stealin' dem! But why? Dey weren't even ready ta be reborn... Search da area and see if ya can pick up da trail. Missing loa be bad for business... and Bwonsamdi be in enough trouble wit' da boss already!",objectivesText="Search for clues leading to the missing loa. Progress: Hakkar and Dambala both gone missin' at da same time? Oh, I got a bad feelin' about dis...",rewardGold=257400,rewardXP=8165,rewardItems={180167},starts={{npcID=166265}},questType="standard"},
[59813] = {id=59813,name="Minions of Mueh'zala",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Dese all be followers of Mueh'zala! Me shoulda known he be da one behind it all. Mueh'zala be da loa of death from long ago. It be him who raised up Ol' Bwonsamdi, him who made me a loa. Dat be before his worshippers started turnin' away from him. He always been a greedy one... but dis... Mueh'zala be goin' too far dis time! We gotta stop him, or he gonna take all da loa in Ardenweald!",objectivesText="Defeat High Priest Rakazodu and 8 Mueh'zala forces. Progress: Mueh'zala be goin' too far dis time!",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=166265}},questType="standard"},
[59815] = {id=59815,name="Stolen Loa",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1565,description="Hakkar and Dambala be somewhere in da grove. We need ta hurry and find out what Mueh'zala be up to. Dem two loa been mighty powerful on Azeroth... powerful and evil. Who knows what Mueh'zala be plannin' for dem! Search da Spirit Glen. Find da missing loa and see what Mueh'zala be meanin' ta do!",objectivesText="Locate Hakkar the Soulflayer and Dambala. Progress: We gotta know what be happenin' ta da missin' loa!",starts={{npcID=166265}},questType="standard"},
[59817] = {id=59817,name="Winter Be Comin'",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Da boss be puttin' together an army of terrible loa. Hakkar and Dambala may only be da beginnin'. How da boss get so strong? I not be seein' him use power like dis before... Da Winter Queen not be fond of ol' Bwonsamdi, but we gonna need her help to stop Mueh'zala. Ya be friendly wit' da Queen, no? If she be willin' to rally her forces, we might be able to stop Mueh'zala before it be too late. Head to da Heart of da Forest and speak wit' da Queen. She be our only hope now.",objectivesText="Gain an audience with the Winter Queen . Progress: We gotta convince da Winter Queen to join forces against Mueh'zala...",rewardGold=257400,rewardXP=8165,rewardItems={175586,179767,179890,181911},rewardChoices={175586,179767,181911,179890},starts={{npcID=166265}},ends={{npcID=156634}},questType="standard"},
[59818] = {id=59818,name="Gathering The Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Loath as I am to aid Bwonsamdi, Mueh'zala must be made to answer for his crimes. We will eradicate his worshippers and drive them from the forest before they cause more harm. Rally the groves and muster the Wild Hunt. Ardenweald has need of its protectors. Make haste, .",objectivesText="Gather the Wild Hunt to Tirna Noch in Ardenweald.",rewardGold=257400,rewardXP=8165,starts={{npcID=156634}},ends={{npcID=167823}},coords={x=0.454,y=0.656,source="quest_giver",zoneID=11510},questType="standard"},
[59819] = {id=59819,name="Cleansing the Forest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Winter Queen has commanded us to drive Mueh'zala's forces out of Ardenweald. This won't be an easy battle. The death loa's army is strong, and several of our hunters have been gravely injured. Can we count on you to turn the tide in our favor, ? Aid our fallen allies and vanquish Mueh'zala's minions!",objectivesText="Aid the Wild Hunt in their fight against the forces of Mueh'zala. Progress: The fight is far from over.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167823}},ends={{npcID=167823}},coords={x=0.666,y=0.556,source="quest_giver",zoneID=11510},questType="standard"},
[59821] = {id=59821,name="Report to the Queen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Mueh'zala's forces are routed, and it's only a matter of time before the Wild Hunt completely purges them from Ardenweald. But something tells me that the struggle between Bwonsamdi and Mueh'zala is far from over. That creepy little mask has gone silent... You should hurry back to the Heart of the Forest and report to the Winter Queen . She will decide what we do next.",objectivesText="Speak with the Winter Queen .",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167823}},ends={{npcID=156634}},coords={x=0.666,y=0.556,source="quest_giver",zoneID=11510},questType="standard"},
[59822] = {id=59822,name="Tracking a Wild God",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Dis be a dark place, . We gotta track down da spirit who be trapped here. Me tink me can pick up its trail... but dat be all dis ol' shadow hunter can do. If me be tryin' ta fight wit' ya, da threads dat be tyin' me ta Azeroth might break. Den I gonna be stuck here, too. C'mon. We best be moving.",objectivesText="Track down the missing spirits of Ardenweald .",rewardGold=514800,rewardXP=10205,rewardItems={177817},starts={{npcID=171655}},ends={{npcID=171806}},coords={x=0.448,y=0.41,source="quest_giver",zoneID=11400},questType="standard"},
[59824] = {id=59824,name="Loa Rescue",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="We be here for Ashamane, but me sensin' loa bein' tortured up ahead. Three of dem, if me be right. Me don't know who dey be, but dey don't belong in da Maw. We need ta be bringin' dem back ta Ardenweald , too!",objectivesText="Find and rescue the three loa trapped within the Maw.",rewardGold=514800,rewardXP=10205,rewardItems={177817},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=171806}},ends={{npcID=166461}},coords={x=0.408,y=0.642,source="quest_giver",zoneID=11400},questType="standard"},
[59825] = {id=59825,name="Seed Hunting",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Return Animacones to Alascene and Kill Players"},{orderIndex=1,type=0,amount=5,objectID=166329,text="Animacones Returned"}},worldTaskTitle="Seed Hunting",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[59826] = {id=59826,name="Bet On Yourself",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. The entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it. I've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right. We will be betting, so don't disappoint.",rewardGold=386100,rewardXP=8165,rewardItems={181645,181647,181649,184305,184772,184773,184774,184775,184776},starts={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Bet On Yourself",db2QuestInfoID=1,db2QuestInfoName="Group"},
[59827] = {id=59827,name="Bet On Yourself",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. The entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it. I've brought in a special challenger just to prove the point. Face Devmorta in the Theater of Pain and prove us wrong... or prove us right. We will be betting, so don't disappoint.",rewardGold=386100,rewardXP=8165,rewardItems={181645,181647,181649,184305,184772,184773,184774,184775,184776},starts={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Bet On Yourself",db2QuestInfoID=1,db2QuestInfoName="Group"},
[59828] = {id=59828,name="Bet On Yourself",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. The entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it. I've brought in a special challenger just to prove the point. Face Ti'or in the Theater of Pain and prove us wrong... or prove us right. We will be betting, so don't disappoint.",rewardGold=386100,rewardXP=8165,rewardItems={181645,181647,181649,184305,184772,184773,184774,184775,184776},starts={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Bet On Yourself",db2QuestInfoID=1,db2QuestInfoName="Group"},
[59836] = {id=59836,name="Battles Won Long Ago",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=166379,text="Plant Banner at the Iron Trench"},{orderIndex=0,type=0,amount=15,objectID=166494,text="Iron Trench enemies killed"}},worldTaskTitle="Battles Won Long Ago",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59837] = {id=59837,name="Working for the Living",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13366,mapID=1536,description="I see you are wondering where we acquire all of the challengers we supply to this arena. We scour countless realms in search of opponents to provide the Maldraxxi with firsthand combat experience. Currently, I am in the process of procuring a new combatant--and with it, a lucrative betting opportunity. Would you make use of our portal and assist Zo'umlo in capturing Khogov the Expunger ? You will be appropriately compensated, of course.",objectivesText="Shattered Grove secured and Khogov the Expunger captured. Progress: Have you successfully captured Khogov the Expunger ?",rewardGold=365040,rewardXP=1415,starts={{npcID=159830}},ends={{npcID=159830}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[59840] = {id=59840,name="Divine Gratitude",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,description="Many thanks for restoring my power and vigor. My path will now lead me back to my people, but it is only right that you are rewarded for your efforts.",objectivesText="Accept the boon offered by the deity.",questType="standard"},
[59846] = {id=59846,name="Finders-Keepers, Sinners-Weepers",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh hello, mortal. You have a real knack for arriving at the most opportune times. I wonder what Taskmaster Matyas wants with you. Curious. As for me, again Matyas has used my sinstone against me. I was already enraged that he caged me and I assure you that this latest attack will not go unanswered. Yet, while he has my sinstone I am unable to act against him directly. So we must remedy that. You question the laborers and I will read this journal while I regain my strength.",objectivesText="Discover the secrets of Taskmaster Matyas's efforts in Feeder's Thicket. Progress: Have you discovered anything useful?",rewardGold=49350,rewardXP=1415,rewardItems={178065,178066,178067,178068,178069,178070,178071,178072,179979,179980,179981},rewardChoices={178067,178071,178065,178069,178068,178072,178066,178070},starts={{npcID=165864}},ends={{npcID=165864}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59848] = {id=59848,name="Tea Tales: Theotar",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166478,text="Ask Theotar to Tell His Story"},{orderIndex=4,type=0,amount=1,objectID=166479,text="Get to the Tea Party"},{orderIndex=1,type=0,amount=1,objectID=166504,text="Stolen Parasol Recovered"},{orderIndex=2,type=0,amount=5,objectID=166505,text="Parasol-Stealing Venthyr Slain"},{orderIndex=3,type=0,amount=5,objectID=160744,text="Very Rude Ash Ghouls Slain"}},worldTaskTitle="Tea Tales: Theotar",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59850] = {id=59850,name="Tea Tales: Vulca",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166478,text="Ask Vulca to tell her story"},{orderIndex=3,type=0,amount=1,objectID=166479,text="Get to the tea party"},{orderIndex=1,type=0,amount=1,objectID=166504,text="Glazier's toolkit recovered"},{orderIndex=2,type=0,amount=10,objectID=160744,text="Ash ghouls slain"}},worldTaskTitle="Tea Tales: Vulca",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59852] = {id=59852,name="Tea Tales: Gubbins and Tubbins",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166478,text="Ask Gubbins and Tubbins to tell their story"},{orderIndex=2,type=0,amount=1,objectID=166479,text="Get to the tea party on time!"},{orderIndex=1,type=0,amount=1,objectID=166504,text="Lost teapot found"}},worldTaskTitle="Tea Tales: Gubbins and Tubbins",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59853] = {id=59853,name="Tea Tales: Lost Sybille",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166478,text="Ask Lost Sybille to tell her story"},{orderIndex=7,type=0,amount=1,objectID=166479,text="Get to the tea party"},{orderIndex=1,type=0,amount=1,objectID=166816,text="Theotar's Parasol recovered"},{orderIndex=3,type=0,amount=1,objectID=166817,text="Vulca's Toolkit recovered"},{orderIndex=5,type=0,amount=1,objectID=166818,text="Tubbins's Teapot recovered"},{orderIndex=2,type=0,amount=1,objectID=166511,text="Theotar's Parasol placed"},{orderIndex=4,type=0,amount=1,objectID=166512,text="Vulca's Toolkit placed"},{orderIndex=6,type=0,amount=1,objectID=166513,text="Tubbins's Teapot placed"}},worldTaskTitle="Tea Tales: Lost Sybille",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59855] = {id=59855,name="Major Mirror Disruptions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166454,text="Reach the end of the maze"}},worldTaskTitle="Major Mirror Disruptions",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59856] = {id=59856,name="Rezan, Loa of Kings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Rezan be a powerful loa, one of great importance ta da Zandalari. We need ta rescue him... but dis creature be projectin' a barrier of death. Notin' be gettin' in. Unless... I be usin' me own anima ta shield ya from its magic. Ya gotta act fast and kill da monster dat be drainin' Rezan. Me anima not gonna last forever. Say da word when ya ready ta go.",objectivesText="Accept some of Vol'jin's anima to protect yourself, then slay Exhaurbius to save Rezan. Progress: We need ta save Rezan!",rewardGold=514800,rewardXP=10205,rewardItems={177817},starts={{npcID=166461}},ends={{npcID=166461}},coords={x=0.458,y=0.85,source="quest_giver",zoneID=11400},questType="standard"},
[59862] = {id=59862,name="A Savior for Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="The forest sighs in greeting, Maw Walker. Your arrival was written in the stars, and awaited by the boughs. Now our work begins. Let us proceed. Follow this path into the grove. These are but the first steps on our journey together.",objectivesText="Walk with the Warden to the grove. Progress: Our paths converge. Together we walk.",rewardGold=128700,rewardXP=4085,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[59865] = {id=59865,name="Glimmerflight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="This so exciting! Come, another test is in order. I can hardly wait!",objectivesText="Observe Kowalskos ' test flight.",rewardGold=386100,rewardXP=8165,rewardItems={177951},starts={{npcID=164640}},ends={{npcID=164640}},coords={x=0.428,y=0.428,source="quest_giver",zoneID=10534},questType="standard"},
[59866] = {id=59866,name="Parting Ways",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1543,description="Me don't know what fate be comin' for ol' Vol'jin... but it be waitin' for me in Ardenweald . Ashamane, Hir'eek, Shadra... dey belong dere, too. We best be gettin' outta here. Me had enough of da Maw for an eternity.",objectivesText="Return the lost loa and Vol'jin to the Winter Queen in Ardenweald .",rewardGold=772200,rewardXP=12250,rewardItems={175588,177817,179768,179887,181912},rewardChoices={175588,179768,181912,179887},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=166461}},ends={{npcID=160262}},coords={x=0.458,y=0.85,source="quest_giver",zoneID=11400},questType="standard"},
[59867] = {id=59867,name="WANTED: Appraiser Vix",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix. Special warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders. Elimination of this felon is of the highest priority.",rewardGold=514800,rewardXP=10205,rewardItems={181645,181647,181649,184305,184772,184773,184774,184775,184776},starts={{npcID=349612,x=0.542,y=0.475,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.542,y=0.475,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="WANTED: Appraiser Vix",db2QuestInfoID=1,db2QuestInfoName="Group"},
[59868] = {id=59868,name="Offer of Freedom",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Just as I was, some of the Briarbane venthyr you encounter will have been compelled to serve Matyas. They likely will not want to fight you, but will have no choice. Once they are injured, they may be willing to pause to see if one of the sinstones you recovered earlier is theirs. Free those you can. The use of a sinstone to compel others isn't fair.",objectivesText="Weaken Briarbane venthyr and then offer them a sinstone. Progress: Have you released the compelled venthyr?",rewardGold=386100,rewardXP=1415,rewardItems={178077,179359},rewardChoices={178077},starts={{npcID=165864}},ends={{npcID=166616}},coords={x=0.6,y=0.69,source="quest_giver",zoneID=10413},questType="standard"},
[59870] = {id=59870,name="[OLD NOT USED]",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13367,mapID=1662,rewardGold=119340,rewardXP=4085,questType="standard"},
[59871] = {id=59871,name="Catalyze This",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="The grove grows in power, and so shall the spirits it shelters. You have nurtured a spirit to rebirth on your own. Now you must learn to make use of catalysts. When planted near a wildseed, catalysts grant the slumbering spirit strength beyond what it knew in life. Strength that it retains when reborn. Catalysts are special and rare, though I have one here for you to use. Others can be found across the Shadowlands. For now, plant the catalyst and witness the potential it holds.",objectivesText="Use the catalyst on the catalyst plot.",rewardGold=128700,rewardXP=4085,rewardItems={184779},starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[59872] = {id=59872,name="How to Save a God",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="Many mortal souls suffer within the Maw. But so too do many spirits of Nature. Anima alone cannot heal wounds inflicted by the Jailer. Spirits plucked from his grasp must be planted anew and tended with care. These wildseeds are unlike any other. This grove, unlike any other. Within them lies dormant hope, a chance for even the weakest spirit to be reborn. One such as this. Lay this spirit to rest within a wildseed. Let its rebirth begin.",objectivesText="Place the Soul Seed into the wildseed. Progress: Let fate and compassion guide your hand.",rewardGold=128700,rewardXP=4085,rewardItems={177953},starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[59873] = {id=59873,name="Greeting a God",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="Soon, the moment of the spirit's rebirth will be nigh. A fate all but extinguished by the Maw, rekindled by grove and caretaker. Time will be the spirit's salve. Once enough of it has passed, lay your hands upon the wildseed and awaken them.",objectivesText="Wait for the spirit to finish incubating, then open the wildseed. Progress: Patience is the way of the forest.",rewardGold=128700,rewardXP=4085,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[59874] = {id=59874,name="The Maw",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1536,description="$p, your arrival has set Maldraxxus ablaze. If you have any honor, you will do as I ask. I believe I know where our answers may lie. The baron preceding Draka was lost to the Maw. It is said you have entered that dark abyss... and returned. If the baron survived, he may know our next course of action. You came here from Oribos. Return there, and see if you can find a way back to the Maw.",objectivesText="Speak with Bolvar in Oribos.",rewardGold=25740,rewardXP=175,starts={{npcID=164843}},ends={{npcID=164843}},coords={x=0.382,y=0.666,source="quest_giver",zoneID=11462},questType="standard"},
[59876] = {id=59876,name="Field Reports",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10,mapID=84,description="The Scourge can strike anytime, anywhere. To counter their unpredictability, the Argent Crusade has secured key locations along the southern road heading east. However, I have yet to receive any reports from our scouts in the field. With the erratic nature of these attacks, I fear the worst. Travel the road and take stock of our outposts. I'll be expecting a full report when you return. Light be with you, .",objectivesText="Gather reports from officers in Elwynn Forest, Redridge Mountains and Duskwood. Progress: Gregor sent you?",rewardGold=128700,rewardXP=3410,rewardItems={177958,177959,177960},starts={{npcID=166383}},ends={{npcID=166184}},coords={x=0.656,y=0.768,source="quest_giver",zoneID=1519},questType="standard"},
[59877] = {id=59877,name="A Message from Icecrown",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=210,mapID=84,description="We received word from our forces in Northrend. Justicar Trueheart requests our immediate assistance. As you are an experienced , I ask that you answer the call. The urgency of this summons cannot be ignored, even if it means braving the terrors of Icecrown itself. I know you fear for the safety of everyone here. I will continue to coordinate our efforts and call in additional reinforcements. Light be with you, .",objectivesText="Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.",rewardGold=117000,rewardXP=3410,starts={{npcID=166383}},ends={{npcID=167045}},coords={x=0.656,y=0.768,source="quest_giver",zoneID=1519},questType="standard"},
[59879] = {id=59879,name="This Thing of Ours",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Au'narim is the top broker here. She keeps this place supplied with exotic creatures for us to fight in the arena. She's noticed your efforts and wants to meet you! This is important. A broker's backing could lead to an invitation to compete!",objectivesText="Meet with Au'narim .",rewardGold=25740,rewardXP=175,starts={{npcID=161559}},ends={{npcID=159830}},coords={x=0.544,y=0.486,source="quest_giver",zoneID=11462},questType="standard"},
[59882] = {id=59882,name="Sure Bet",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="You appear to have great profit potential. There are many interested parties willing to bet upon your performance in the Theater of Pain. Go now, Louison will arrange your appearance.",objectivesText="Meet with Louison",rewardGold=25740,rewardXP=175,questType="standard"},
[59894] = {id=59894,name="The Golden Dawn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The machinations of war commence. Gharmal's crimes are now evident to all of the Shadowlands. Bastion demands vengeance, and we shall share it with them. Only our combined forces will defeat the Constructs once and for all. Meet Draka at the overlook. Your presence there will help solidify an agreement.",objectivesText="Teleport to the Overlook to meet with Draka.",rewardGold=772200,rewardXP=12250,rewardItems={181803},rewardChoices={181803},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161988}},ends={{npcID=166535}},coords={x=0.492,y=0.512,source="quest_giver",zoneID=12876},questType="standard"},
[59897] = {id=59897,name="Seeking the Baron",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Take this amulet. One like it is carried by each of the Four Horsemen. The amulets are imbued with a power that links them to one another. That connection should help you locate Darion Mograine. No doubt Darion has witnessed countless horrors in the Maw. Perhaps he has caught sight of the missing baron. Let us hope he can lead you to our Azerothian allies as well.",objectivesText="Enter the Maw.",rewardGold=257400,rewardXP=1415,starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[59902] = {id=59902,name="A Curious Cache",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=166695,text="Banewood wildlife slain"}},worldTaskTitle="A Curious Cache",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59904] = {id=59904,name="A Curious Cache",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=166695,text="Banewood wildlife slain"}},worldTaskTitle="A Curious Cache",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59905] = {id=59905,name="A Curious Cache",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=166695,text="Banewood wildlife slain"}},worldTaskTitle="A Curious Cache",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[59907] = {id=59907,name="Mawsworn Menace",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13570,mapID=1648,description="Our knights are strong, but they don't stand much chance scattered against such an opponent. We need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.",objectivesText="Defeat 8 Mawsworn enemies in the Crucible of the Damned. Progress: Let your blade do the talking!",rewardGold=234000,rewardXP=6815,starts={{npcID=166723}},ends={{npcID=166723}},questType="standard"},
[59910] = {id=59910,name="Fight and Flight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mograine and Emeni will lead the assault on the western gate. You and Xandria will advance from the east. Secure the area and slay all who oppose you. Once we have them surrounded, we can strike the final blow against Gharmal.",objectivesText="Fly with Xandria to the House of Constructs.",rewardGold=25740,rewardXP=1020,starts={{npcID=171483}},ends={{npcID=166333}},coords={x=0.362,y=0.366,source="quest_giver",zoneID=11462},questType="standard"},
[59912] = {id=59912,name="[OLD NOT USED]",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13367,mapID=1662,description="Now that you have seen the basics it is time for us to expand your understanding. I hope your little mind will be able to hold this information. You seem capable so far, but you are so small. I'll be intrigued to see if you are bigger on the inside. First. You need to learn more about the catalysts. There should be a small number growing in this very grove. Fetch me some and I can explain what they are.",rewardGold=128700,rewardXP=4085,questType="standard"},
[59914] = {id=59914,name="Fear to Tread",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies. We will draw less attention alone. The Ebon Blade will hold back, awaiting my signal. Come, let us see what awaits us in this hellscape.",objectivesText="Scout Calcis for any signs of your allies. Progress: Champion? Tell me this is not an illusion.",rewardGold=234000,rewardXP=6815,starts={{npcID=165918}},ends={{npcID=165918}},questType="standard"},
[59915] = {id=59915,name="Soul in Hand",level=50,requiredLevel=50,faction="alliance",expansion=8,mapID=1648,description="My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent. It will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care. Let's bring our prize to the Lord Admiral.",objectivesText="Return to Lady Jaina Proudmoore in Forlorn Respite.",rewardGold=23400,rewardXP=850,starts={{npcID=166723}},ends={{npcID=166723}},questType="standard"},
[59916] = {id=59916,name="The Butchers of Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?! No! The butchers of Bastion made clear their hearts that day! They deserve only the eternal darkness that awaits them. Ensure that they meet it!",objectivesText="Kill 10 House of Constructs forces in the Separation Chamber.",rewardGold=257400,rewardXP=8165,starts={{npcID=168743}},ends={{npcID=168743}},coords={x=0.352,y=0.26,source="quest_giver",zoneID=11462},questType="standard"},
[59917] = {id=59917,name="Kill Them, Of Course",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources. Their presence here is inconvenient, to put it mildly. They tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher. Exactly the sort of work you're accustomed to, yes?",objectivesText="Slay 8 Enraged Gluttons . Progress: How did the hunting go?",rewardGold=386100,rewardXP=1415,starts={{npcID=166664}},ends={{npcID=166664}},coords={x=0.43,y=0.252,source="quest_giver",zoneID=11462},questType="standard"},
[59919] = {id=59919,name="An Earned Bond",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="There is one more thing you should do, Maw Walker. In rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you. Given his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.",objectivesText="Soulbind with Mikanikos. Progress: This is a moment to remember.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[59920] = {id=59920,name="Light the Forge, Forgelite",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I think we have the materials I will need to light the forge, at long last. I am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands. I would very much appreciate your help to get the place in order while I coax the forge to life once more.",objectivesText="Help Forgelite Sophone .",rewardGold=38050,rewardXP=1415,starts={{npcID=158807}},ends={{npcID=158807}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[59921] = {id=59921,name="All I Ever Will Be",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary. Many of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage. Accompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies. He will learn that this afterlife is not the one suited for him.",objectivesText="Reflect on the Scrolls of Remembrance with Alexandros Mograine. Progress: What have you learned?",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165794}},ends={{npcID=165794}},coords={x=0.416,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[59922] = {id=59922,name="Do Not Forget",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1533,description="The Arbiter's judgment was, as always, infallible. Though Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus , not Bastion. Nonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted. Go now. Return to your leader with news of our victory today. And tomorrow, we shall purge our foes once and for all.",objectivesText="Return to Draka in the Seat of the Primus.",rewardGold=25740,rewardXP=1020,starts={{npcID=165794}},ends={{npcID=161907}},coords={x=0.416,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[59925] = {id=59925,name="[OLD NOT USED]",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,rewardGold=128700,rewardXP=3410,questType="standard"},
[59929] = {id=59929,name="Murloc Mania",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The shore is littered with shipwrecks. This must be where the lost expedition crashed. We'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up. Slay those murlocs to get back what belongs to the Horde.",rewardGold=565,rewardXP=200,rewardItems={170549},starts={{npcID=166782}},ends={{npcID=166782}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59930] = {id=59930,name="Emergency First Aid",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="We must treat our wounded before we can begin for the missing expedition. Take this first aid kit and tend to the survivors. I'll handle the others nearby.",rewardGold=565,rewardXP=200,rewardItems={168410,174780},starts={{npcID=166782}},ends={{npcID=166782}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59931] = {id=59931,name="Finding the Lost Expedition",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Breka Grimaxe went north to look for survivors. Join her to see what she's found. I'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.",rewardGold=285,rewardXP=100,starts={{npcID=166782}},ends={{npcID=166854},{npcID=166906}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59932] = {id=59932,name="Cooking Meat",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This is Won'sa , a shaman who was with the expedition. She is dying of starvation. A death unfit for the Horde! Slay some of the nearby wildlife for their meat and cook it over the fire. Won'sa can tell us what happened to the missing expedition after she eats.",rewardGold=565,rewardXP=200,rewardItems={117,174072,174074},starts={{npcID=166906}},ends={{npcID=166854}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59933] = {id=59933,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Won'sa said the quilboar have kidnapped the missing expedition. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!",rewardGold=565,rewardXP=200,starts={{npcID=166906}},ends={{npcID=166906}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59934] = {id=59934,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Won'sa said the quilboar have kidnapped the missing expedition... including my daughter. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!",rewardGold=565,rewardXP=200,starts={{npcID=166906}},ends={{npcID=166906}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59935] = {id=59935,name="Northbound",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Da quilboar kidnapped da rest of da expedition and took dem north. Dey said dey gonna use da expedition for some sorta sacrifice! Ya gotta head north as fast as ya can ta stop dem!",rewardGold=285,rewardXP=100,rewardItems={167206},starts={{npcID=175030}},ends={{npcID=166996}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59937] = {id=59937,name="Taming the Wilds",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="A hunter like yourself needs a good pet by your side. Did you not bring one with you? Hmm. I suppose I shall have to compensate for your lack of training. Listen closely and learn quickly. I will teach you how to tame a beast and make it your pet. You will need one if you are to fight the quilboar.",rewardGold=565,rewardXP=200,starts={{npcID=166996}},ends={{npcID=166996}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59938] = {id=59938,name="Down with the Quilboar",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition. The ritual is being performed by the tribe's leader, Geolord Grek'og . Slay Grek'og and save the survivor. Show this brute that the Horde is not to be trifled with.",rewardGold=565,rewardXP=200,starts={{npcID=166996}},ends={{npcID=167019}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59939] = {id=59939,name="Forbidden Quilboar Shadow Magic",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Quilboar are savage and violent. I did not think they knew how to use shadow magic. Obviously, we cannot allow them to continue their rituals. And certainly not on members of the Horde. Slay the quilboar in the den. They must learn the fatal error of their ways.",rewardGold=565,rewardXP=200,rewardItems={174786,174787,174788,174789,175180,175181,175182,175183,175212,175213,175214,175215},rewardChoices={175181,175213,175183,175215,175182,175214,175180,175212},starts={{npcID=166996}},ends={{npcID=167020}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59940] = {id=59940,name="The Choppy Booster Mk. 5",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You're in luck, 'cause I'm the ONE goblin who can help you find the rest of the expedition! Feast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own! I call it the Choppy Booster Mk. 5 . Use it to find Shuja and the others.",rewardGold=285,rewardXP=100,starts={{npcID=167019}},ends={{npcID=167019}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59941] = {id=59941,name="Re-sizing the Situation",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I call this gadget \"the Re-Sizer.\" It's what I used to unshrink the Choppy Booster Mk. 5. Look, I'm gonna be honest. I got, at best, a passing understandin' of how this thing works. That means I'm gonna be pushing a lot of buttons to see what happens. I'm sure we'll figure out how to upsize one of these boars. Then we'll use it to trample those undead goons! You hold the Re-Sizer while I fiddle with it. Then just press the button and, uh... hope for the best?",rewardGold=425,rewardXP=150,rewardItems={178051},starts={{npcID=167019}},ends={{npcID=167021}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59942] = {id=59942,name="The Re-Deather",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I got the perfect plan. You're gonna ride the Choppy Booster Mk. 5 and BLAST those walkin' cadavers from the sky! I hereby dub the Re-Sizer the \"Re-Deather.\" We're gonna show them where the undead belong! Er, except for OUR undead. They're totally fine. Anyway, hop on the Choppy Booster Mk. 5 and I'll pilot it. Once we save Wrathion , we'll blast our way to all the other survivors!",rewardGold=1130,rewardXP=250,rewardItems={175161,175162,175163,175164,175165,175166,175167,175168,175169,175170,175171,175172,175173,175174},rewardChoices={175161,175172,175171,175170,175173,175174,175162,175169,175165,175168,175163,175167,175164,175166},starts={{npcID=167019}},ends={{npcID=167128}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59943] = {id=59943,name="The Harpy Problem",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The ogres are planning to sacrifice the rest of the expedition to fuel this ritual to control Kalecgos, leader of the blue dragonflight. It seems one of the survivors was taken to the hills north of here. Bo scouted ahead to investigate. Come, we'll see what he has found.",rewardGold=860,rewardXP=440,starts={{npcID=167219}},ends={{npcID=167291}},coords={x=0.538,y=0.522,source="quest_giver",mapID=1409},questType="standard"},
[59944] = {id=59944,name="The Rescue of Herbert Gloomburst",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies plan to sacrifice the expedition's mage, a Forsaken by the name of Herbert Gloomburst . Herbert's ethics are... questionable, but he always strives to serve the Horde. We'll need his magic to stop the ogres. Let's move.",rewardGold=1720,rewardXP=875,starts={{npcID=167290}},ends={{npcID=167182}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59945] = {id=59945,name="Harpy Culling",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies seem to be in league with the ogres. Many of them are gathering to attack our camp. We must thin their numbers and thwart their attempts to eliminate us. Perhaps they will learn it is best to leave the Horde be.",rewardGold=1720,rewardXP=875,starts={{npcID=167291}},ends={{npcID=167291}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59946] = {id=59946,name="Purge the Totems",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies have placed vile totems throughout the area to attain more power. We must destroy those totems in order to debilitate our foes. Take this torch and burn any totems you see. It is wise to weaken one's enemy before the fight even begins.",rewardGold=1720,rewardXP=875,rewardItems={168445,175199,175200,175201,175202,175231,175232,175233,175238},rewardChoices={175200,175238,175202,175233,175201,175232,175199,175231},starts={{npcID=167291}},ends={{npcID=167291}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59947] = {id=59947,name="Message to Base",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Let us return to camp with Herbert in tow. We're one step closer towards thwarting the ogres and their plans.",rewardGold=860,rewardXP=440,rewardItems={175191,175192,175193,175194,175223,175224,175225,175226},rewardChoices={175192,175224,175194,175226,175193,175225,175191,175223},starts={{npcID=167290}},ends={{npcID=167212}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59948] = {id=59948,name="Westward Bound",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Thrall wants us to search west of here for the site of the next ritual. We could use your help. I've already died once. It's not an experience I'd care to repeat.",rewardGold=860,rewardXP=440,starts={{npcID=167221}},ends={{npcID=167225}},coords={x=0.528,y=0.564,source="quest_giver",mapID=1409},questType="standard"},
[59949] = {id=59949,name="Who Lurks in the Pit",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="There's a whole lot of shadow energy coming from this pit. I'm guessing a ritual is being performed down there. And that means a sacrifice. Do you hear that? I've got the best hearing around, ever since I got this new ear sewn onto me. It sounds like there are some more of our soldiers trapped down there. Probably all webbed up. Won'sa and I will... stay up here and help anyone who gets out. You should jump in and rescue anyone who is left down there!",rewardGold=2940,rewardXP=1095,rewardItems={175203,175204,175205,175206,175234,175235,175236,175237},rewardChoices={175203,175234,175206,175237,175205,175236,175204,175235},starts={{npcID=167225}},ends={{npcID=167212}},coords={x=0.528,y=0.564,source="quest_giver",mapID=1409},questType="standard"},
[59950] = {id=59950,name="Stocking Up on Supplies",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Provisioner Jin'hake managed to recover some other supplies from the shipwreck. Take a look at what he has before heading out.",rewardGold=1500,rewardXP=150,rewardItems={175239},starts={{npcID=167212}},ends={{npcID=167212}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59951] = {id=59951,name="A Druid's Form",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Thank you for rescuing me, . Allow me to aid you in your druidic studies. To escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same. Come with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.",rewardGold=4000,rewardXP=250,starts={{npcID=166575}},ends={{npcID=167473}},coords={x=0.454,y=0.492,source="quest_giver",mapID=1409},questType="standard"},
[59952] = {id=59952,name="A Hunter's Trap",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="If you want to be called a true hunter, you'll need to learn the art of trapping. Fortunately, I happen to be an expert in it. First, you will need to gather supplies from the surrounding area so you can fashion a proper freezing trap . Herbert can supply you with a mote of ice. Scavenge the area for other materials. You will need the trap to handle another issue that has recently arisen.",rewardGold=1470,rewardXP=200,rewardItems={175979,175980,175981},starts={{npcID=167215}},ends={{npcID=167215}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59953] = {id=59953,name="Hunting the Stalker",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Now that you have your trap, we can move onto the true problem at hand. A strange creature not native to this island has been stalking our camp. I think we should capture it and see how it can help us. Set the freezing trap within these ruins to lure it out. We'll see just what we are dealing with.",rewardGold=2000,rewardXP=200,starts={{npcID=167215}},ends={{npcID=167215}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59954] = {id=59954,name="A Mage's Knowledge",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You've got some good spells for a novice mage. There are a few things holding you back, though. For instance, it's absolutely clear to me you don't know Polymorph . If you did, you would've been using it on the harpies that were attacking us! Let's fix that. My spellbook has details on how to cast it... but my captors threw it into the nearby lake. Grab it for me, would you? Oh, and don't look through the book beforehand. You will almost certainly regret it if you do.",rewardGold=4000,rewardXP=250,rewardItems={178229},starts={{npcID=167309}},ends={{npcID=167309}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59955] = {id=59955,name="The Best Way to Use Sheep",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I can't send you off without making sure you can cast Polymorph correctly. Why, if you messed it up you may transform someone into something completely different! I want to make sure I'm around to take notes if that happens. Let's see... ah, Throg will do nicely! I can spot a prime test subject from a mile away. Shall we begin?",rewardGold=4000,rewardXP=250,starts={{npcID=167309}},ends={{npcID=167309}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59956] = {id=59956,name="A Monk's Focus",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You fought well against the harpies, but you'll need even more skill to best the challenges ahead. We must meditate and focus if we are to gain more strength. Come. I know of a place we can go.",rewardGold=4000,rewardXP=250,starts={{npcID=167308}},ends={{npcID=167537}},coords={x=0.52,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59957] = {id=59957,name="One Last Spar",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Let's have a quick sparring session before returning to camp. I can sense new power rising from within you. I want to see it in action!",rewardGold=4000,rewardXP=250,starts={{npcID=167537}},ends={{npcID=167212}},coords={x=0.52,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59958] = {id=59958,name="A Paladin's Service",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="While you were destroying that army of the undead, the ghost of a paladin approached me... and asked for you! They floated over to the ruins nearby. You should see what this ghost wants. I do not know much about the Light... but I know not to ignore a ghost.",rewardGold=4000,rewardXP=250,starts={{npcID=167216}},ends={{npcID=167179}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59959] = {id=59959,name="The Brand Holds the Key",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="cage is locked, and doesn't appear easily broken. Perhaps the holder of the key is this \"Brand\" he mentioned.>",objectivesText="Find the key to free Darion. Progress: Are you willing to listen to my proposition?",rewardGold=176280,rewardXP=1415,rewardItems={178018},starts={{npcID=355798}},ends={{npcID=171770}},coords={x=0.384,y=0.485,source="quest_giver",zoneID=11400},questType="standard"},
[59960] = {id=59960,name="A Cooling Trail",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="<The amulet burns hot in your hand. The magic that runs through it tugs slightly at your grip. Perhaps the enchantment spoken of by Bolvar can now be used to find Mograine.>",objectivesText="Use the Amulet of the Horsemen to find Darion Mograine.",rewardGold=257400,rewardXP=1415,rewardItems={181174},ends={{npcID=355798}},questType="standard"},
[59961] = {id=59961,name="A Priest's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You're a trained priest, right ? I have a grim request for you. I passed by some injured members of the first expedition. I did what I could... but they were too far gone. Can you perform a ritual to lay them to rest? Their spirits deserve to rest with honor.",rewardGold=4000,rewardXP=250,starts={{npcID=167216}},ends={{npcID=167188}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59962] = {id=59962,name="Hope Never Dies",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="So, mortal, you are here looking for someone. Well it just so happens that, clever as I am, it's quite possible I know where they are. Allow me to propose a trade. That amulet you carry... it holds an interesting power. You give me the amulet, and I will help you find this Maldraxxi baron. And then you will leave. I don't mean to be rude, but I really prefer to keep a low profile. Allow me to speed things along.",objectivesText="Follow Ve'nari .",rewardGold=24570,rewardXP=175,starts={{npcID=171770}},ends={{npcID=171770}},coords={x=0.362,y=0.556,source="quest_giver",zoneID=11400},questType="standard"},
[59965] = {id=59965,name="Resurrecting the Recruits",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Ya gotta cast Resurrection on dese recruits ta be savin' dem. Da necrotic magic of dis place be tuggin' at deir souls. Quickly, now!",rewardGold=4000,rewardXP=250,starts={{npcID=167188}},ends={{npcID=167188}},coords={x=0.562,y=0.536,source="quest_giver",mapID=1409},questType="standard"},
[59966] = {id=59966,name="Delving Deeper",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="It's quite a thrill to have a mortal for a business partner! The amulet really is intriguing. What's that? Oh yes, that baron you're searching for... Well it so happens that I learned of a Maldraxxi warlord being held in the lower courtyard of Perdition Hold. As you might guess by the name, it's not the most charming of places. I would prefer to avoid the attention of the Jailer's forces. Fortunately, I have just the thing. Give the word, and I will conceal us from the Mawsworn.",objectivesText="Follow Ve'nari to Perdition Hold.",rewardGold=245700,rewardXP=1415,starts={{npcID=171770}},ends={{npcID=172414}},coords={x=0.362,y=0.556,source="quest_giver",zoneID=11400},questType="standard"},
[59967] = {id=59967,name="A Rogue's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Shuja mentioned a rogue from the first expedition. Goes by Drizza Sidestabber . Drizza was last seen heading northwest... towards a large bear's den. None of us can sneak around like you. See if you can find Drizza and bring her back here.",rewardGold=4000,rewardXP=250,rewardItems={174916},starts={{npcID=167216}},ends={{npcID=167586}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59968] = {id=59968,name="The Deadliest of Poisons",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You've got the poison. Now you gotta to take out that ogre. Goon's name is Gutgruk the Tough. He usually patrols around the citadel. I betcha it's lookin' for your expedition right now! Poison your blades, then take that monster down. Show him he ain't so tough!",rewardGold=4000,rewardXP=250,starts={{npcID=167586}},ends={{npcID=167216}},coords={x=0.456,y=0.56,source="quest_giver",mapID=1409},questType="standard"},
[59969] = {id=59969,name="A Shaman's Duty",level=1,requiredLevel=1,faction="none",expansion=8,zoneID=10424,mapID=1409,description="Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman. The necrotic energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.",objectivesText="Gather 4 ghost blossoms to burn on the campfire in order to rescue the ghost wolf 's companions.",rewardGold=4000,rewardXP=250,questType="standard"},
[59970] = {id=59970,name="A Warlock's Bargain",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="While scouting the area, I saw an open portal near the bridge up the hill. That does not bode well for any of us. It seemed like another warlock tried to seal the portal, but failed. I know you dabble in such... affairs. Perhaps you could put your knowledge to good use and close that portal.",rewardGold=4000,rewardXP=250,rewardItems={174947},starts={{npcID=167216}},ends={{npcID=167481}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59971] = {id=59971,name="A Warrior's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Hail, ! You've grown stronger since we sparred on the boat. You may one day become a warrior of great renown! Speaking of which... I encountered a ghost on the bridge to the north that demands to meet a true warrior. Perhaps you can see what it wants. It did not seem hostile. It might even be willing to help us.",rewardGold=4000,rewardXP=250,starts={{npcID=167216}},ends={{npcID=162943}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59972] = {id=59972,name="Hjalmar's Final Execution",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.",rewardGold=4000,rewardXP=250,starts={{npcID=162943}},ends={{npcID=167216}},coords={x=0.516,y=0.478,source="quest_giver",mapID=1409},questType="standard"},
[59973] = {id=59973,name="A Bond Beyond Death",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="Since crossing into the Shadowlands, I've been so focused on our mission that I never even considered the souls of my family being here somewhere. Whatever this realm called Maldraxxus is, I hope it is worthy of my father's service! We must free him, . There is... much I need to say to him.",objectivesText="Protect Darion while he frees Alexandros. Progress: Every moment spent here tears at one's soul.",rewardGold=245700,rewardXP=1415,starts={{npcID=172414}},ends={{npcID=172414}},coords={x=0.33,y=0.664,source="quest_giver",zoneID=11400},questType="standard"},
[59974] = {id=59974,name="A Soul Saved",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Vyraz... all this time... This cannot stand, . We must avenge Krexus and cut him down! He must have sent you to the Maw expecting that you would never return. He underestimated you. A fatal mistake. Go with Mograine and claim Vyraz's head. I will warn our forces at the Seat of the Primus.",objectivesText="Meet Alexandros Mograine at the House of the Chosen in Maldraxxus .",rewardGold=24570,rewardXP=175,starts={{npcID=167903}},ends={{npcID=162801}},questType="standard"},
[59975] = {id=59975,name="To Darkmaul Citadel",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The last remaining survivor is being held within the ogre's citadel. Crenna and Herbert have a plan to get us inside. A small group of us will gather up north. You're coming with us. If we fail here, the ogres will gain control of Kalecgos and his powerful blue dragon magic.",rewardGold=1000,rewardXP=505,starts={{npcID=167212}},ends={{npcID=167596}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59978] = {id=59978,name="Right Beneath Their Eyes",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="We need to get into Darkmaul Citadel, rescue the last survivor, and stop Gor'groth. Herbert and Crenna are going to cast a spell to make you look an ogre... and then you're going to take us in as your \"prisoners.\" Speak with Herbert when you're ready.",rewardGold=2000,rewardXP=1010,starts={{npcID=167596}},ends={{npcID=167633}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59979] = {id=59979,name="Like Ogres to the Slaughter",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This is worse than I thought. The ogres were counting on us to stage a rescue attempt. It seems that they plan to attack our camp while they near completion of the ritual. We can't let that happen. Crush the ogres! Show them the strength of the Horde!",rewardGold=2000,rewardXP=1010,rewardItems={175184,175185,175186,175187,175216,175217,175218,175219},rewardChoices={175186,175218,175184,175216,175187,175219,175185,175217},starts={{npcID=167632}},ends={{npcID=167632}},coords={x=0.402,y=0.324,source="quest_giver",mapID=1409},questType="standard"},
[59980] = {id=59980,name="Catapult Destruction",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="As we snuck in here I noticed the ogres erecting catapults to destroy our camp. Cork must have anticipated this and gave me several explosives to use, \"just in case\". Take these explosives and blow up those catapults ! Also don't shake them too hard.",rewardGold=2000,rewardXP=1010,starts={{npcID=167630},{npcID=167631}},ends={{npcID=167630},{npcID=167631}},coords={x=0.402,y=0.326,source="quest_giver",mapID=1409},questType="standard"},
[59981] = {id=59981,name="Controlling their Stones",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Warlord Thunderwalker won't last much longer. Soon, his life essence will be completely drained. Gor'groth mentioned that they are keeping him captive through the use of ward stones . I want you to recover these ward stones and bring them here so we can release Thunderwalker.",rewardGold=2000,rewardXP=1010,rewardItems={168599,168600,168601},starts={{npcID=167633}},ends={{npcID=167183}},coords={x=0.402,y=0.324,source="quest_giver",mapID=1409},questType="standard"},
[59984] = {id=59984,name="Dungeon: Darkmaul Citadel",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Gor'groth seeks to use shadow magic to gain control of Kalecgos, the aspect of the Blue Dragonflight. He's collected enough life essence to attempt to finish the ritual. I do not know what will happen, but we cannot let him complete it! Gor'groth will not stop until he is slain! You must storm the citadel and slay Gor'groth before he can complete his ritual! I would charge in beside you, were I not still recovering from his dark magic.",rewardGold=8000,rewardXP=2020,rewardItems={175175,175188,175189,175190,175207,175220,175221,175222},rewardChoices={175188,175220,175190,175222,175189,175221,175175,175207},starts={{npcID=167183}},ends={{npcID=167675}},coords={x=0.4,y=0.322,source="quest_giver",mapID=1409},questType="standard"},
[59985] = {id=59985,name="An End to Beginnings",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=13644,mapID=2022,description="You've done well here, . Kalecgos and Wrathion are planning to continue on to the Dragon Isles. I must return to Orgrimmar. This shadow magic is concerning... and requires that I look into it more. Talk with Kalecgos . He'll get you to the Dragon Isles and inform you about what's going on there.",rewardGold=2000,rewardXP=2020,rewardItems={175208,175209,175210,175211},rewardChoices={175179,175211,175178,175210,175177,175209,175176,175208},starts={{npcID=167675}},ends={{npcID=168431},{npcID=244496}},coords={x=0.396,y=0.32,source="quest_giver",mapID=2022},questType="standard",packageItems={175179,175178,175177,175176}},
[59986] = {id=59986,name="Wide Worlds of Catalysts",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,description="Catalysts come in different forms, for now we shall introduce you to two of them. Speed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover. Quality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. Return to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.",objectivesText="Identify the different types of Catalysts",rewardGold=257400,rewardXP=6815,questType="standard"},
[59994] = {id=59994,name="Trust Fall",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Let us ponder the meaning of the Archivist's last words: \"Victory only belongs to those brave enough to fall.\" Hmm. It could be reference to the Volume of Victory. That is the most well-known of all the writings said to be kept in this tower. That book is priceless, . I mean that almost literally. We must do whatever is necessary to find it! But, uh... What do you suppose \"brave enough to fall\" refers to?",objectivesText="Jump from the tower. Progress: You have it?",rewardGold=375570,rewardXP=1415,rewardItems={175516,175517,175518,175519,178020},rewardChoices={175517,175519,175518,175516},starts={{npcID=162476}},ends={{npcID=166806}},questType="standard"},
[59999] = {id=59999,name="Rebirth of the Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="Though not yet withered, the conservatory wilts amidst the drought. This grove is not what it once was. As warden, I bear the twin burdens of guilt and shame. Fate saw to this grove's decay and my failure to prevent it. But fate has also seen to hope in its renewal. Hope in you. I beseech you, mortal, to seek out Zayhad in the Heart of the Forest and restore what has been lost. For as the wounded spirits must be reborn, so too must this grove.",rewardGold=257400,rewardXP=8165,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",mapID=1662},questType="standard"},
[60003] = {id=60003,name="A Valiant Effort",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=210,mapID=118,description="It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.",objectivesText="Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?",rewardGold=257400,rewardXP=6815,rewardItems={183797},rewardCurrencies={{id=1754,amount=1}},starts={{npcID=168123}},ends={{npcID=168123}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[60004] = {id=60004,name="A Valiant Effort",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=210,mapID=118,description="It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.",objectivesText="Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?",rewardGold=257400,rewardXP=6815,rewardItems={183689},rewardCurrencies={{id=1754,amount=1}},starts={{npcID=168123}},ends={{npcID=168123}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[60005] = {id=60005,name="Imminent Danger",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="The Temple of Courage must not fall! All kyrian learn to fight in its hallowed halls. Not only to protect Bastion , but to ensure their own safety when retrieving souls from across the veil. Travel there at once. Seek out Thanikos , the Paragon of Courage's loyal hand.",objectivesText="Seek out Thanikos at Xandria's Vigil.",rewardGold=25740,rewardXP=175,starts={{npcID=160037}},ends={{npcID=167873}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[60006] = {id=60006,name="Now or Never",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="In a fair fight our warriors could stand against countless swarms of these Maldraxxi. This was no fair fight, outsider. They came without warning. Without cause. We were caught unprepared. They must not be allowed to encroach any further. This stops here.",objectivesText="Reclaim Xandria's Vigil. Progress: We will not go down without a fight.",rewardGold=257400,rewardXP=1415,starts={{npcID=167873}},ends={{npcID=167873}},coords={x=0.418,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[60007] = {id=60007,name="Stay Scrappy",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I can rebuild this colossus's core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise. Replacements are in order! I require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom! I'll take care of the rest. Quickly, now!",objectivesText="Recover the Anima Conflux , Eternity Plating , and Archonic Resonator . Progress: Do you have the parts?",rewardGold=241020,rewardXP=1415,rewardItems={178041,178042,178043},starts={{npcID=167135}},ends={{npcID=167135}},coords={x=0.408,y=0.554,source="quest_giver",zoneID=10534},questType="standard"},
[60008] = {id=60008,name="Rip and Tear",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We will show these Maldraxxi insurgents the price for their betrayal. The northern grounds have been taken by the House of Constructs, home to Maldraxxus' most resilient warriors. They have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.",objectivesText="Slay House of Constructs forces. Progress: This is what must be done.",rewardGold=241020,rewardXP=1415,starts={{npcID=167134}},ends={{npcID=167134}},coords={x=0.406,y=0.552,source="quest_giver",zoneID=10534},questType="standard"},
[60009] = {id=60009,name="Fight Another Day",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Some of our brethren are still alive in there! While many were lost in the initial assault, they seem keen on taking any survivors prisoner. I know not what they intend, but given their mastery of corpses we must assume the worst. Some have already been taken to their necropolis above, but others remain in cages on the ground. Free all you can.",objectivesText="Save 6 captured kyrian. Progress: The kyrian leave none behind on the field of battle.",rewardGold=241020,rewardXP=1415,rewardItems={175718},rewardChoices={175718},starts={{npcID=167269}},ends={{npcID=167269}},coords={x=0.412,y=0.544,source="quest_giver",zoneID=10534},questType="standard"},
[60010] = {id=60010,name="Tremaculum: Liberated Souls",expansion=8,mapID=1543,questType="world",worldTaskTitle="Tremaculum: Liberated Souls",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60011] = {id=60011,name="Calcis: Decryption",expansion=8,mapID=1543,questType="world",worldTaskTitle="Calcis: Decryption",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60012] = {id=60012,name="Zovaal's Cauldron: Stygia Overflow",expansion=8,mapID=1543,questType="world",worldTaskTitle="Zovaal's Cauldron: Stygia Overflow",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60013] = {id=60013,name="Leave it to Mnemis",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have deduced by the urgency in your collective voices that you wish to leave. I will expedite your exit. There is a transport pad in the antechamber. I will ensure that the chamber is sealed once again on your exit. Please accompany me.",objectivesText="Use the Transport Pad in the Vault of the Archon.",rewardGold=128700,rewardXP=710,starts={{npcID=167504}},ends={{npcID=167038}},coords={x=0.562,y=0.676,source="quest_giver",zoneID=10534},questType="standard"},
[60020] = {id=60020,name="An Opportunistic Strike",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I'm impressed you made it this far. But don't get too full of yourself. Most of the fodder you plowed your way through were amateurs at best. Only one combatant will leave this arena a champion. Each of the five... uh, three houses has fighters in the field. Most merely seek to test their own limits or earn a bit of favor. Only a few have a real chance at claiming victory. Seek out those challengers if you wish to claim true glory this day.",objectivesText="Slay 10 elite contenders. Progress: Are they finished?",rewardGold=241020,rewardXP=1415,starts={{npcID=164244}},ends={{npcID=164244}},coords={x=0.504,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[60021] = {id=60021,name="Champion the Cause",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Now you're starting to show potential! I'm guessing your name was well known on whatever mortal world you hail from. But don't rest on your laurels. The harder you fight, the harder others will strive to strike you down. That's the Maldraxxi way! Nothing wins the favor of the crowd like taking down a former champion. Two are in attendance today, attempting to recapture their past glories. Slaughter them!",objectivesText="Slay Champion Rin'mar and Champion Gutrend . Progress: Is it done?",rewardGold=241020,rewardXP=1415,starts={{npcID=164244}},ends={{npcID=164244}},coords={x=0.504,y=0.444,source="quest_giver",zoneID=11462},questType="standard"},
[60023] = {id=60023,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=8,rewardXP=12250,questType="standard"},
[60024] = {id=60024,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=8,rewardXP=12250,questType="standard"},
