[60103] = {id=60103,name="The Miscreation Wing",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13400,mapID=1700,description="<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>",objectivesText="Enter the Miscreation Wing and defeat its warden.",questType="standard"},
[60104] = {id=60104,name="Darkness' Domain",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13400,mapID=1700,description="<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>",objectivesText="Enter Darkness' Domain and defeat its warden.",questType="standard"},
[60105] = {id=60105,name="Sineater Belfry",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13400,mapID=1700,description="<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>",objectivesText="Enter Sineater Belfry and defeat its warden.",questType="standard"},
[60106] = {id=60106,name="The Upper Reaches",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13400,mapID=1700,description="<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>",objectivesText="Enter the Upper Reaches and defeat its warden.",questType="standard"},
[60107] = {id=60107,name="The Winding Halls",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13400,mapID=1700,description="<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>",objectivesText="Enter the Winding Halls.",questType="standard"},
[60108] = {id=60108,name="Drust and Ashes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="The Drust encroach upon the Grove of Awakening, ! We must fly in defense of Ardenweald !",objectivesText="Defend the Grove of Awakening from the Drust and slay Gorak Zhar.",rewardGold=772200,rewardXP=12250,rewardItems={180721,182165,183888,183889,183890,183891,183892,183893},rewardChoices={183889,183892},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=172091}},ends={{npcID=156634}},coords={x=0.39,y=0.634,source="quest_giver",zoneID=11510},questType="standard"},
[60110] = {id=60110,name="Never Had a Friend Like Me",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="I feel like you could use a little help, Maw Walker. There is knowledge I have which could make you more useful to the Necrolords. So just this once... I will teach you something and you won't even have to lose a limb. Soulbind with me and we'll see if you can learn anything.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=161906,x=0.386,y=0.362,zoneID=12876}},ends={{npcID=161906,x=0.386,y=0.362,zoneID=12876}},coords={x=0.386,y=0.362,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Never Had a Friend Like Me"},
[60111] = {id=60111,name="Forging A Friendship",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="When you first arrived I was uncertain of your potential. The Primus demands such perfection in his work... and you are far from perfect. I see now that you bring new knowledge and ideas to our house. Your actions make us stronger. The Primus would be proud of you and wish for us all to learn from you. I am ready now to know your ways. Let me soulbind with you now, so we can grow stronger together.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=161905,x=0.424,y=0.324,zoneID=12876}},ends={{npcID=161905,x=0.424,y=0.324,zoneID=12876}},coords={x=0.424,y=0.324,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Forging A Friendship"},
[60112] = {id=60112,name="Cut to the Bone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I fear if our presence is known, so too is the presence of our comrades. We must develop a contingency. With the foundry on such high alert, we cannot sneak about undetected. Unless, of course, you were to provide a distraction. Perhaps thinning their numbers would suffice.",objectivesText="Eliminate 5 Ossein Workers and 10 Violent Animates .",rewardGold=257400,rewardXP=8165,starts={{npcID=172574}},ends={{npcID=172574}},coords={x=0.318,y=0.402,source="quest_giver",zoneID=11462},questType="standard"},
[60113] = {id=60113,name="An Urgent Request",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Champion, A matter of great urgency has arisen--one that requires your immediate attention. Due to the sensitive nature of recent events, I must withhold further details until we meet. We have much to discuss. King Greymane and I await your arrival at Lion's Rest.",objectivesText="Report to Genn Greymane at Lion's Rest in Stormwind City.",rewardGold=25740,rewardXP=850,ends={{npcID=167329}},coords={mapID=84,source="quest_giver",x=0.395,y=0.642},questType="standard"},
[60114] = {id=60114,name="Aerial Advantage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Gharmal's rocs dominate the skies above, striking at our forces as we advance. We cannot move the necropolis into position until they are cleared out! I would slaughter them myself, but the cowards remain out of reach, and I am not constructed for flight. You, however, seem slight enough of build. Take my riding hook and latch onto a roc. Once you are atop of one, beat it to a pulp. Worry about the landing later.",objectivesText="Grapple 6 Battlesewn Rocs out of the sky. Progress: Annihilate them!",rewardGold=257400,rewardXP=8165,rewardItems={180899},starts={{npcID=167810}},ends={{npcID=167810}},coords={x=0.282,y=0.374,source="quest_giver",zoneID=11462},questType="standard"},
[60115] = {id=60115,name="An Urgent Request",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Champion, A matter of great urgency has arisen--one that requires your immediate attention. Due to the sensitive nature of recent events, I must withhold further details until we can speak in person. There is much to discuss. Regent Lord Lor'themar Theron awaits your arrival in Orgrimmar.",objectivesText="Report to Lor'themar Theron atop Grommash Hold in Orgrimmar.",rewardGold=25740,rewardXP=850,ends={{npcID=169928}},coords={mapID=85,source="quest_giver",x=0.488667,y=0.736},questType="standard"},
[60116] = {id=60116,name="Cause for Distraction",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="The very heart of the Alliance is under attack. The undead Scourge is swarming in numbers not seen since the return of Arthas Menethil. Amidst the chaos, something... terrible has happened. What I am about to share with you has not yet been revealed to our allies. They will be told in due time, but I needed to speak to you directly before word gets out. Allow me to explain.",objectivesText="Speak with Genn Greymane at Lion's Rest in Stormwind City. Progress: There is much to discuss.",rewardGold=25740,rewardXP=850,starts={{npcID=167329}},ends={{npcID=167329}},coords={x=0.396,y=0.642,source="quest_giver",zoneID=1519},questType="standard"},
[60117] = {id=60117,name="Return of the Crusade",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="The Scourge's unbound hunger has been unleashed. It's only a matter of time before those monsters swarm our streets. We need expertise in dealing with this menace. The death knights of the Ebon Blade have stepped forward to aid us, but even they can't do this alone. The Argent Crusade has answered the call. I need you to work with them to keep our people safe, . I have sent word of your arrival to their commander. He awaits you at their camp just inside the city gates.",objectivesText="Speak with Commander Gregor in the Trade District of Stormwind City.",rewardGold=25740,rewardXP=850,starts={{npcID=167329}},ends={{npcID=166383}},coords={x=0.396,y=0.642,source="quest_giver",zoneID=1519},questType="standard"},
[60120] = {id=60120,name="Burning Crusade: To Outland!",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=84,description="The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.",objectivesText="Go through the Dark Portal in Blasted Lands. The Honor Hold Mage in the Mage District can help you get there.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60123] = {id=60123,name="Burning Crusade: To Outland!",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=85,description="The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.",objectivesText="Go through the Dark Portal in Blasted Lands. The Thrallmar Mage in the Orgrimmar Portal Room can help you get there.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60125] = {id=60125,name="Mists of Pandaria: To Pandaria!",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn. We have received word of a conflict in the seas to the south, and we need the help of an experienced to assist in the investigation.",objectivesText="Report to Rell Nightwind in Stormwind.",starts={{npcID=167032}},ends={{npcID=55789}},questType="standard"},
[60126] = {id=60126,name="Mists of Pandaria: To Pandaria!",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=85,description="You are hereby ordered to present yourself at Grommash Hold immediately. We have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.",objectivesText="Report to Grommash Hold in Orgrimmar.",starts={{npcID=167032}},ends={{npcID=54870}},questType="standard"},
[60127] = {id=60127,name="Missing Stone Fiend",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You or I could wield these sinstones directly, but I much prefer to use stone fiends for such tasks. Exceptional results, no personal risk. Unfortunately, my stone fiend did not return from its last errand. Speak with Cryptkeeper Kassir in the archives above. He is loyal to the Accuser and will loan us his stone fiend.",objectivesText="Speak with Cryptkeeper Kassir .",rewardGold=25740,rewardXP=175,starts={{npcID=160248}},ends={{npcID=163073}},coords={x=0.73,y=0.52,source="quest_giver",zoneID=10413},questType="standard"},
[60128] = {id=60128,name="Ready to Serve",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Do not mind Temel. His zeal for heralding sins is powerful, but he is still a stone fiend. He will obey. Give Archivist Fane my regards.",objectivesText="Return to Archivist Fane .",rewardGold=25740,rewardXP=175,starts={{npcID=163073}},ends={{npcID=160248}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="standard"},
[60129] = {id=60129,name="Stranger in an Even Stranger Land",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw. Wherever you are, it is clearly very, very far from home. It appears your arrival has been noticed.>",objectivesText="Find your way inside Oribos to learn what is happening. Progress: Try to communicate with the guards and enter the city.",rewardGold=128700,rewardXP=3410,coords={mapID=1670,x=0.204,y=0.503},questType="standard"},
[60132] = {id=60132,name="Constellan Writs and Stygia",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="There is much to discover within the Maw , and much of it can be turned to future profit. Information is an investment. There are many objects that I find interesting in this place, and I am happy to barter with you should you find any. Find one and we shall open negotiations.",questType="standard"},
[60136] = {id=60136,name="Into Torghast",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The bond to your covenant is growing stronger, . Good. The power lies within you to venture into Torghast and rescue our allies. You saw Baine Bloodhoof while assisting the broker in the Maw . Perhaps this Ve'nari knows a way to breach the Jailer's tower and find the chieftain. When I peered into Torghast once before, you stood at my side. I believe that connection will allow me to see through your eyes as you navigate its torments. Seek out Ve'nari and request her aid, Maw Walker.",objectivesText="Find a way into Torghast, Tower of the Damned. Progress: Do whatever you can, Maw Walker. We are depending on you.",rewardXP=4085,starts={{npcID=164079}},ends={{npcID=162804}},questType="standard"},
[60139] = {id=60139,name="Torment Chamber: Jaina",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13404,mapID=1670,description="I sense Lady Proudmoore's magic upon this debris. And these notes describe methods to contain her power. By the Light! They are tormenting her with white-hot fires. Though her will is strong, there is only so much any mortal can endure. I will modify Ve'nari's Attuned Shard using the items you returned. You must find her, $p. Before it is too late.",objectivesText="Rescue Jaina Proudmoore from Torghast. Progress: You must find Jaina Proudmoore in Torghast.",rewardGold=1029600,rewardXP=16330,rewardItems={184550},rewardCurrencies={{id=1828,amount=200}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[60145] = {id=60145,name="Third Talon Vartox",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This \"win the spirit of the people\" operation is noble and good. However, we must set our sights on cutting down our foe's tools. Third Talon Vartox , the leader of this incursion, also serves as the top stoneborn at the Tithelord's estate. If we strike her down here, the Tithelord will be left exposed for our attack.",objectivesText="Kill Third Talon Vartox . Progress: Is Vartox dealt with?",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167381}},ends={{npcID=167381}},coords={x=0.562,y=0.666,source="quest_giver",zoneID=10413},questType="standard"},
[60146] = {id=60146,name="Torment Chamber: Thrall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13413,mapID=1670,description="Using the totem you recovered, I will alter the Attuned Shard to guide you to Thrall 's location. Take care. You know the torments Baine and Lady Proudmoore endured in that accursed place. Thrall 's confinement will be no less harrowing. Beware. The deeper you journey into the Tower of the Damned, the closer you get to the Jailer himself. Free Thrall , ... before all hope is lost.",objectivesText="Rescue Thrall from Torghast, Tower of the Damned. Progress: All our allies must be saved, <name>.",rewardGold=1029600,rewardXP=16330,rewardItems={184551},rewardCurrencies={{id=1828,amount=200}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[60147] = {id=60147,name="Mirror Attunement: The Eternal Terrace",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Work has been completed on a mirror that will allow travel between Sinfall and The Eternal Terrace. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.",objectivesText="Enter the mirror in The Eternal Terrace.",rewardGold=25740,rewardXP=175,starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[60148] = {id=60148,name="No Place for the Living",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="A living mortal ... incredible! Forgive my astonishment. I am Kah-Delen, an overseer of the Arbiter's attendants here in the Eternal City of Oribos . You stand within the heart of the Shadowlands. While we are accustomed to receiving souls from all manner of worlds within the mortal realm, never before has one arrived that is quite so ... corporeal. Answer honestly, mortal. Did you truly escape the Maw?",objectivesText="The Overseers want to know more about how you escaped the Maw. Progress: So where did you come from stranger?",rewardGold=128700,rewardXP=3410,starts={{npcID=167425}},ends={{npcID=167425}},questType="standard"},
[60149] = {id=60149,name="Audience with the Arbiter",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="I am Tal-Inara , Honored Voice of the Arbiter. I speak for she who is ever silent. The Arbiter watches over Oribos . She blesses us with her wisdom. Every mortal soul that enters the Shadowlands passes before her for judgment. In the merest fraction of a moment, she sees every glory, every folly, every joy, every regret. With this knowledge, she chooses an ideal afterlife for that soul. At least, she did. Not long ago, catastrophe struck, and ... Come. Some things are better seen than explained.",objectivesText="The Voice of the Arbiter wishes you to join them in the Arbiter's chamber. Progress: The Purpose guides us always.",rewardGold=128700,rewardXP=3410,starts={{npcID=167486}},ends={{npcID=167486}},questType="standard"},
[60150] = {id=60150,name="Tether to Home",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="It is disappointing that you were unable to stir the Arbiter, but we must not give up hope. Your continued presence in the Shadowlands may help our cause. Perhaps your efforts would benefit from creating a tether to the mortal plane. The map table in this chamber was put in place long ago by the First Ones, the wise architects of all you see. If you have a memento from your homeworld, place it there. The table's magic can establish a connection.",objectivesText="Affix the Helm of Domination fragment to the console.",rewardGold=128700,rewardXP=3410,starts={{npcID=167425}},ends={{npcID=167425}},questType="standard"},
[60151] = {id=60151,name="A Doorway Through the Veil",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="The Helm fragment connected us while you were in the Maw. As if through a darkened pane of glass, I saw glimpses of what you endured. The terrors you faced. At least the heroes of Azeroth yet live. They must be saved. By affixing the Helm here, you gave us a tether to Azeroth that served to bring a few of us across the veil. But you, and other heroes who join us, require a stronger connection. Our acolytes can open portals back. No doubt these attendants will be particular about their placement.",objectivesText="Establish portals back to Azeroth. Progress: Have you helped the acolytes open the portals yet?",rewardGold=128700,rewardXP=3410,starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[60152] = {id=60152,name="The Eternal City",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You should become familiar with the Eternal City and how best to navigate it. We, the attendants, serve Oribos as its caretakers. Everything you see here is done in service to the Purpose. In this time of chaos and drought, we must adapt our perspective. It seems we are to serve the Purpose in a new way. You mortals are not the only visitors here. Others have come as well. Like you, the brokers are not of Oribos . They are congenial and willing to aid you. Usually for a price.",objectivesText="Tour the Eternal City of Oribos . Progress: Have you concluded your tour yet?",rewardGold=128700,rewardXP=3410,starts={{npcID=167424}},ends={{npcID=167424}},questType="standard"},
[60153] = {id=60153,name="Into the Unknown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?",objectivesText="Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[60154] = {id=60154,name="Understanding the Shadowlands",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1671,description="As I sat upon the Frozen Throne all those years, , I could peer into the Shadowlands. Brief glimpses, clouded and uncertain. Sights both wondrous and terrible. We must work together to make sense of what has happened. To prevent the Maw from consuming all of reality. Whatever Sylvanas and the Jailer want, we must stop them. But we cannot do so alone. Perhaps Tal-Inara can put us on the path to find answers.",objectivesText="Speak to Tal-Inara . Progress: Let us align your path to the Purpose.",rewardGold=128700,rewardXP=3410,starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[60155] = {id=60155,name="To Open the Way",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10565,mapID=1670,rewardGold=128700,rewardXP=4085,questType="standard"},
[60156] = {id=60156,name="The Path to Bastion",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1671,description="Within the Arbiter's Chamber are gateways to the infinite realms of the Shadowlands. As each soul was judged, a gateway would be opened to the appropriate afterlife. But since the... incident, all gateways have remained closed. Dormant. We dare not use the Arbiter's sacred chamber for so mundane a purpose as travel. But here in the upper ring of the city, gateways can be configured for your needs. Before us stands the means to activate a gateway. Together we can channel the anima to power it.",objectivesText="Open the gateway to Bastion. Progress: Your destiny and the Purpose are being drawn together.",rewardGold=128700,rewardXP=3410,starts={{npcID=175829}},ends={{npcID=175829}},questType="standard"},
[60158] = {id=60158,name="Rule 7: Betrayal is Inevitable",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Our arrangement has been quite lucrative. Reliable associates like yourself can be so hard to find. I believe I can entrust you with a task I would usually perform on my own. While working with the tracking runes you retrieved for me earlier, I detected a device of broker origin nearby. It must have been brought into the Maw by the captured expedition. Please examine it and prepare it for transport back to the refuge. I will join you shortly. This could be a valuable discovery.",objectivesText="Recover the broker device outside of Perdition Hold. Progress: Have you found the device?",rewardGold=772200,rewardXP=12250,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60159] = {id=60159,name="Mirror Attunement: Halls of Atonement",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Work has been completed on a mirror that will allow travel between Sinfall and the Halls of Atonement. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.",objectivesText="Enter the mirror in the Halls of Atonement.",rewardGold=25740,rewardXP=175,starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[60160] = {id=60160,name="Mirror Attunement: The Banewood",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Work has been completed on a mirror that will allow travel between Sinfall and The Banewood. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.",objectivesText="Enter the mirror in The Banewood.",rewardGold=25740,rewardXP=175,starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[60162] = {id=60162,name="The Art of Taming",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Quite the surprise to find this beast so hale and hearty. It seems to have taken a liking to you. If you're ever going to be as great as one of the Dawntrackers, you must learn how to handle multiple pets. Allow me to show you how.",rewardGold=2000,rewardXP=200,starts={{npcID=167215}},ends={{npcID=167215}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[60164] = {id=60164,name="Mirror Attunement: Dominance Keep",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Work has been completed on a mirror that will allow travel between Sinfall and Dominance Keep. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.",objectivesText="Enter the mirror in Dominance Keep.",rewardGold=25740,rewardXP=175,starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[60165] = {id=60165,name="Mirror Attunement: Feeders' Thicket",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Work has been completed on a mirror that will allow travel between Sinfall and Feeders' Thicket. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.",objectivesText="Enter the mirror in Feeders' Thicket.",rewardGold=25740,rewardXP=175,starts={{npcID=167160}},ends={{npcID=167160}},coords={x=0.47,y=0.572,source="quest_giver",zoneID=10986},questType="standard"},
[60168] = {id=60168,name="The Art of Taming",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=10424,mapID=1409,description="I'm quite surprised to find this beast still alive and kicking. It appears to like you. Before we finish, you had better learn how to wrangle multiple pets. I'll give you one last lesson.",objectivesText="Learn how to dismiss, tame, and stable pets from Austin Huxworth . Progress: Make sure to dismiss your pet before we get started. Oh, and if it's injured, use Revive Pet to bring it back.",rewardGold=1015,rewardXP=200,starts={{npcID=161666}},ends={{npcID=161666}},coords={x=0.524,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[60169] = {id=60169,name="Securing the Area",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="The Scourge's attack was as sudden as it was unexpected. Truth be told, they caught us unawares. Through swift action, we were able to rally our defenses... though not before the tournament grounds were overrun. We must secure the area before we can mount a counteroffensive. Vanquish these monsters in the name of the Light!",objectivesText="Remove 12 Scourge from the Argent Tournament Grounds.",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=1}},starts={{npcID=167045}},ends={{npcID=167045}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[60172] = {id=60172,name="This Quest is Temporary",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Dropping out of the sky is a key part of this playtest, so enjoy the ride.",objectivesText="Speak with Draedan to enter the Maw.",rewardGold=257400,rewardXP=8165,questType="standard"},
[60174] = {id=60174,name="The Divine's Shield",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This island has foul necromancy here in addition to the shadow magic. The Light can only just reach this place. Call upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar. Show the darkness on this island that you are protected by the Light's embrace.",rewardGold=4000,rewardXP=250,starts={{npcID=167179}},ends={{npcID=167179}},coords={x=0.576,y=0.52,source="quest_giver",mapID=1409},questType="standard"},
[60175] = {id=60175,name="A Taste of Tirna Noch",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="I'm a simple mushroom with simple pleasures, . And what's simpler than a nice, hearty meal? Don't look so surprised. I need to eat just like anyone else! How else do you think I grew so big? Nice, tasty compost, that's how! Back in my day, I had the pick of Ardenweald for where to feed. Now, not so much. I've had a hankering for some of the loam that used to be around Tirna Noch. I haven't had shoots out there in a long time. Could you bring me some?",objectivesText="Collect 6 Leafy Loam in Tirna Noch. Progress: Tirna Noch is a beautiful tree located east of Hibernal Hollow. You can't miss it.",rewardGold=257400,rewardXP=8165,rewardItems={178215},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[60176] = {id=60176,name="Bring Out Your Tithe",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Unfortunately the Lord Chamberlain's gift isn't sufficient to cover the entire tithe we're expected to provide the Tithelord, but it will make a good start. The loss of the tithe convoy is a terrible blow to our village. Our little community is already suffering greatly from the drought and the need to meet the Tithelord's demands. Still we must all do our part. We have little time to accomplish this task. Can you help? Get the tithe from villagers and scour the area for every forgotten drop.",objectivesText="Collect anima from the village for the tithe.",rewardGold=257400,rewardXP=1415,starts={{npcID=156822}},ends={{npcID=156822}},coords={x=0.614,y=0.638,source="quest_giver",zoneID=10413},questType="standard"},
[60177] = {id=60177,name="Reason for the Treason",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If you ask me, the attack on our convoy is suspicious. I told Mistress Mihaela that there must be a traitor in the village, but she isn't concerned. It's understandable. She's got to worry about gathering a new tithe. I've taken it upon myself to figure this out and I could use your help. I'm making discreet inquiries but I can't be seen speaking with the help. That's where you come in. You can be my assistant sleuth.",objectivesText="Speak with the \"help\" in the village to find clues leading to the identity of the traitor. Progress: Have you identified the traitor yet?",rewardGold=257400,rewardXP=1415,rewardItems={178565},starts={{npcID=167489}},ends={{npcID=167489}},coords={x=0.622,y=0.612,source="quest_giver",zoneID=10413},questType="standard"},
[60178] = {id=60178,name="And Then There Were None",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Ilka and Samu argued, you say? And you found a coded message indicating that the tithe was going to be sent out soon. Those are helpful clues that will allow me to put the puzzle together. It's clear to me now who betrayed the village and what we need to do about it! You deliver invitations to a meeting to our suspects and I'll prepare to reveal the traitor.",objectivesText="Gather the suspects and meet Lajos in the large crypt. Progress: The Master knows what's best for us. We must do our part.",rewardXP=710,rewardItems={175737,175766},rewardChoices={175766,175737},starts={{npcID=167489}},ends={{npcID=168448}},coords={x=0.622,y=0.612,source="quest_giver",zoneID=10413},questType="standard"},
[60179] = {id=60179,name="Memory of Honor",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Maldraxxus honors the history of those who claimed great victories here. Similar memorials seem to be spread throughout the trench. Perhaps they can offer more insight into the denizens of this realm.>",objectivesText="Read 3 Faded Epitaphs . Progress: Yes?",rewardGold=241020,rewardXP=1415,starts={{npcID=351467}},coords={x=0.483,y=0.577,source="quest_giver",zoneID=11462},questType="standard"},
[60180] = {id=60180,name="A Paragon's Reflection",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You appear to carry a signature unique to one of the Paragons. If you know which Paragon, simply peer into their Soul Mirror to examine the memory of your choice. If you require anything else, you need only speak.",objectivesText="Reveal the final memory. Progress: Did you find the memory you seek?",rewardGold=514800,rewardXP=1770,starts={{npcID=167504}},ends={{npcID=167504}},coords={x=0.562,y=0.676,source="quest_giver",zoneID=10534},questType="standard"},
[60181] = {id=60181,name="Trench Warfare",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="These would-be recruits seek a way to prove themselves. Let us give them the chance. The specter known as Malifis has grown in strength by consuming our anima reserves. In this time of drought, we cannot afford to lose any of our most precious resource. This threat needs to be dealt with immediately. Use this horn to signal the scavengers we've recruited. Let us see how well they fight under our banner!",objectivesText="Use the Baron's Warhorn to defeat Malifis . Progress: Take care, our quarry is formidable.",rewardItems={175739,178496,180827},starts={{npcID=164244}},ends={{npcID=164244}},questType="standard"},
[60183] = {id=60183,name="After Them!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We must move quickly! That anima will be key in fueling these citizens for the fight ahead. Deathfang is ready to ride.",objectivesText="Board Deathfang and ride with Baroness Draka to stop the carriage.",rewardGold=514800,rewardXP=10205,starts={{npcID=167381}},ends={{npcID=167620}},coords={x=0.562,y=0.666,source="quest_giver",zoneID=10413},questType="standard"},
[60184] = {id=60184,name="Dude, Where's My Necropolis?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="Maintaining the portal between our sanctum and the Zerekriss is a difficult task. With enough resources, we could make it permanent and become the unstoppable force my baroness wishes us to be. She has asked much of you, as have I. But this work will make your name a legend among the Maldraxxi, as my baroness's has become. Help to empower us, and you will be empowered in turn.",objectivesText="Upgrade your Sanctum's portal system to Rank 2.",rewardGold=128700,rewardXP=4085,starts={{npcID=173306}},ends={{npcID=173306}},coords={x=0.608,y=0.332,source="quest_giver",zoneID=12876},questType="standard"},
[60185] = {id=60185,name="LFGDungeons - BFA - Ny'alotha Raid Finder - 1st",level=50,requiredLevel=50,faction="none",expansion=8,rewardGold=2340000,questType="standard"},
[60188] = {id=60188,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",rewardItems={178464,178465},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[60189] = {id=60189,name="We Strike Now",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The time has come. The Wild Hunt has driven the Drust back to their stronghold at the edge of Ardenweald . Their scouts report that Gorak Zhar herself is among them. This may be our only opportunity to fully purge the minions of Thros from this realm. Lord Herne awaits your arrival at the battlefront. Go with haste, .",objectivesText="Meet Lord Herne outside of Darkreach.",rewardGold=25740,rewardXP=850,starts={{npcID=160262}},ends={{npcID=167686}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[60190] = {id=60190,name="Assault on Darkreach",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Drust have inflicted enormous loss on this forest and its denizens, . It is time we put an end to their atrocities. We will drive the Drust from their enclave and close their gateway into Ardenweald . With you as our vanguard, victory is assured. I will make my way into the heart of their camp. Find me once you have routed their forces.",objectivesText="Assault the Drust forces within Darkreach.",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167686}},ends={{npcID=171838}},coords={x=0.39,y=0.636,source="quest_giver",zoneID=11510},questType="standard"},
[60191] = {id=60191,name="Ingra Drif",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ingra Drif , the Drust captain, has been spotted inside Darkreach. This is our chance to destroy him for good. I know him and his cruelty all too well, . Whatever you do to him, it's better than what he deserves.",objectivesText="Slay Ingra Drif .",rewardGold=514800,rewardXP=8520,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=172010}},ends={{npcID=172010}},coords={x=0.35,y=0.724,source="quest_giver",zoneID=11510},questType="standard"},
[60192] = {id=60192,name="Their Last Line of Defense",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Those sneaky Drust are protecting Gorak Zhar with their evil magic! I can sense several foul runes that are scattered across Darkreach. If you destroy them, we can easily shatter the barrier around that nasty Gorak Zhar. Hurry! I will meet you inside the enemy camp.",objectivesText="Destroy Gorak Zhar's shielding runes .",rewardGold=257400,rewardXP=6815,starts={{npcID=167688}},ends={{npcID=167688}},coords={x=0.39,y=0.636,source="quest_giver",zoneID=11510},questType="standard"},
[60193] = {id=60193,name="Unmasked",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Thanks to your efforts, the shield that protects our prey has been made brittle as a dried leaf. Our hunt is all but complete. Come, let us put an end to the vile Gorak Zhar .",objectivesText="Slay Gorak Zhar .",rewardGold=514800,rewardXP=8520,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=171838}},ends={{npcID=171992}},coords={x=0.352,y=0.724,source="quest_giver",zoneID=11510},questType="standard"},
[60194] = {id=60194,name="The Call of the Hunt",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I fear Lord Herne will have further need of our aid before this night is over. Come, I'll put some wings on you. We'll have to fly if we want to keep up with him.",objectivesText="Speak to Lord Herne in Ardenweald .",rewardGold=25740,rewardXP=850,starts={{npcID=171992}},ends={{npcID=172091}},coords={x=0.362,y=0.696,source="quest_giver",zoneID=11510},questType="standard"},
[60195] = {id=60195,name="Build One More",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="All these souls deserve a new construct, and when rebuilt any of them will make a valuable addition to our forces. We must start somewhere. You should be able to find Malleable Flesh through out the Shadowlands. A few of the other parts may be harder to locate. Collect parts and use the Abominable Stitching Table to build another construct.",objectivesText="Build one new construct. Progress: Remember, you can find parts from almost anything in Maldraxxus.",rewardGold=128700,rewardXP=4085,rewardItems={183830},starts={{npcID=167150}},ends={{npcID=167150}},coords={x=0.55,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[60211] = {id=60211,name="Spore Losers",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world"},
[60215] = {id=60215,name="Timely Gate Crashers",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=440,mapID=71,description="Did you see that giant mechanical monstrosity just walking around in the dunes outside? How about the icky shadowy Sha of Anger ? Or that big frost giant in the north? Yeah, they aren't native to this area. They tell me the timeways are screwy around this time of year. They have asked me to organize a clean-up crew. Would you be up to the challenge? If you like this challenge, I have another for you as well.",objectivesText="Defeat Doomwalker , Sha of Anger , and Archavon the Stone Watcher in Tanaris. Progress: How's it going?",rewardGold=1366400,rewardXP=8230,rewardItems={232877,233014},rewardCurrencies={{id=1166,amount=100},{id=3100,amount=3}},starts={{npcID=223882}},ends={{npcID=223882}},questType="standard"},
[60217] = {id=60217,name="The Archon's Answer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.",objectivesText="Speak to Kalisthene .",rewardGold=514800,rewardXP=1770,starts={{npcID=158862}},ends={{npcID=156217}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[60218] = {id=60218,name="The Archon's Answer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.",objectivesText="Speak to Kalisthene .",rewardGold=472680,rewardXP=1770,starts={{npcID=158862}},ends={{npcID=156217}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
