[60228] = {id=60228,name="Sinstone Delivery TBD",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="TBD",objectivesText="TBD",rewardGold=257400,rewardXP=1415,questType="standard"},
[60229] = {id=60229,name="The Archon's Answer",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.",objectivesText="Speak to Kalisthene .",rewardGold=514800,rewardXP=1770,starts={{npcID=158862}},ends={{npcID=156217}},coords={x=0.556,y=0.864,source="quest_giver",zoneID=10534},questType="standard"},
[60230] = {id=60230,name="More the Merrier",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!",objectivesText="Take the construct requests from the souls present.",rewardGold=128700,rewardXP=4085,starts={{npcID=167150}},ends={{npcID=167150}},coords={x=0.55,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[60231] = {id=60231,name="State of Decay",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Kill Slimed enemies or Players"}},worldTaskTitle="State of Decay",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[60236] = {id=60236,name="RSVP: Cryptkeeper Kassir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8721,mapID=1525,description="I would be most honored to attend Prince Renathal's Ember Court. I prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties. However, the Lord Chamberlain's goons have stolen it once more. They hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring. It may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.",rewardGold=257400,rewardXP=8165,rewardItems={178526},starts={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},ends={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="RSVP: Cryptkeeper Kassir"},
[60237] = {id=60237,name="Old Stomping Grounds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1536,description="Once, long ago, I journeyed to Ardenweald to assist in putting down a threat now long forgotten. I remember that while there, I saw small creatures taking tiny clusters of anima--animacones, the fae called them--and buried them under the soil. If those clusters are still there, we must gather them for ourselves! I should be able to unearth any of the animacones we encounter. Let's go hunt for them!",objectivesText="Collect 15 Lost Animacones . Use Toothpick 's World Shaker to unearth them.",rewardXP=8165,rewardItems={183744,182488,182497,182506,182515,184843},starts={{npcID=159212}},ends={{npcID=167150}},coords={x=0.548,y=0.678,source="quest_giver",zoneID=11462},questType="standard"},
[60238] = {id=60238,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={128768,178530},starts={{npcID=180746}},ends={{npcID=180746}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[60239] = {id=60239,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={178533},starts={{npcID=187236}},ends={{npcID=187236}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[60242] = {id=60242,name="Trading Favors: Necrotic Wake",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others. So let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable. I hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?",objectivesText="Obtain Nalthor's Phylactery Instructions from Nalthor the Rimebinder in the Necrotic Wake. Progress: Have you found any objects of interest?",rewardItems={178577},rewardChoices={184374},starts={{npcID=167880},{npcID=205783}},ends={{npcID=167880},{npcID=205783}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60243] = {id=60243,name="Trading Favors: Sanguine Depths",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us. It would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.",objectivesText="Obtain a Medallion of Orientation from General Kaal in the Sanguine Depths. Progress: What have you brought before me?",rewardItems={178584},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880},{npcID=205783}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60244] = {id=60244,name="Trading Favors: Halls of Atonement",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12831,description="The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth. How they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel. They keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.",objectivesText="Obtain the Tome of Dredger Alchemy from Lord Chamberlain in the Halls of Atonement. Progress: Have you found something of interest?",rewardItems={178583},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60245] = {id=60245,name="Trading Favors: De Other Side",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. A pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities. We would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.",objectivesText="Obtain a Golden Death Mask from Mueh'zala in De Other Side. Progress: You have the stench of death about you.",rewardItems={178582},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60246] = {id=60246,name="Trading Favors: Tirna Scithe",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest. Or perhaps, mhm, you do? For some, that is entertainment. It is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?",objectivesText="Obtain an Engorged Gorm Larva from Tred'ova in the Mists of Tirna Scithe. Progress: Have you completed the task?",rewardItems={178581},rewardChoices={184374},starts={{npcID=167880}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60247] = {id=60247,name="Trading Favors: Theater of Pain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. Those of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed. I trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.",objectivesText="Obtain a Champion's Coin from Mordretha in the Theater of Pain. Progress: Six, seven, eight... oh, yes? Do you have an offer of trade? I have much more inventory to catalogue.",rewardItems={178580},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880},{npcID=205783}},ends={{npcID=167880},{npcID=205783}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60248] = {id=60248,name="Trading Favors: Plaguefall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13228,description="Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools. You would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well. I am sure she has little use for these possessions in her current state.",objectivesText="Obtain one of Stradama's Lost Ledgers from Margrave Stradama in Plaguefall. Progress: Oh, it is you again.",rewardItems={178579},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60249] = {id=60249,name="Trading Favors: Spires of Ascension",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12837,description="The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation. We would like to know more about their travels to the realms beyond. Surely one of them has brought something back from another land? They are, after all, so very interested in memories.",objectivesText="Obtain a Strange Doll from Devos, Paragon of Doubt in the Spires of Ascension. Progress: How may I assist you?",rewardItems={178578},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167880}},ends={{npcID=167880}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=10565},questType="dungeon"},
[60250] = {id=60250,name="A Valuable Find: Theater of Pain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. With the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record. As such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles. I would very much like to see such an item.",objectivesText="Obtain the Ring of Otherworldly Metal from Mordretha in the Theater of Pain. Progress: Were you victorious, or have you come to tend to your wounds?",rewardItems={178572},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881}},ends={{npcID=167881},{npcID=205782}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60251] = {id=60251,name="A Valuable Find: Plaguefall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor. It is possible, even probable, that this was the cause of the fate that befell the House of Plagues. I do not need to tell you how valuable such a rarity would be to us, do I?",objectivesText="Obtain A Slimy Correspondence from Margrave Stradama in Plaguefall. Progress: Yes? I am quite busy here.",rewardItems={178571},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881},{npcID=205782}},ends={{npcID=167881}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60252] = {id=60252,name="A Valuable Find: Spires of Ascension",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12837,description="You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom. This temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away. We have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.",objectivesText="Obtain the Fading Memory Glass from Devos, Paragon of Doubt in the Spires of Ascension. Progress: You have the look of one who has something to say.",rewardItems={178570},rewardChoices={184374},starts={{npcID=167881}},ends={{npcID=167881}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60253] = {id=60253,name="A Valuable Find: Necrotic Wake",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. It may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us. There are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.",objectivesText="Obtain \" The Origin of Death \" from Nalthor the Rimebinder in the Necrotic Wake. Progress: What have you found?",rewardItems={178569},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881},{npcID=205782}},ends={{npcID=167881},{npcID=205782}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60254] = {id=60254,name="A Valuable Find: Tirna Scithe",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us. One of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.",objectivesText="Obtain the Unusual Automaton Parts from Tred'ova in the Mists of Tirna Scithe. Progress: You look as if you have been sifting through gorm carcass, or perhaps that is simply what you always look like?",rewardItems={178573},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881},{npcID=205782}},ends={{npcID=167881}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60255] = {id=60255,name="A Valuable Find: De Other Side",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. But we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity. Slay the foolish creature, bring me his secrets, I will reward you handsomely!",objectivesText="Obtain a Strange Ritual Mask from Mueh'zala in De Other Side. Progress: Have you brought something of interest?",rewardItems={178574},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881}},ends={{npcID=167881},{npcID=205782}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60256] = {id=60256,name="A Valuable Find: Halls of Atonement",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind. Often they will travel with a piece or two affixed to their garb as a show of status. Now, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. Of course. Yet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.",objectivesText="Obtain the Golden Orb of Energy from Lord Chamberlain in the Halls of Atonement. Progress: How does the battle fare?",rewardItems={178575,178590,178591,178592,178593},rewardChoices={178593,178592,178590,178591,1804,1805,1806,1807},starts={{npcID=167881},{npcID=205782}},ends={{npcID=167881},{npcID=205782}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60257] = {id=60257,name="A Valuable Find: Sanguine Depths",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12842,description="General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls -- it is a bag of eclectic contents. Contained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr. Such a strange mystery must be solved. I will, of course, provide great compensation.",objectivesText="Obtain an Ancient Broker Headpiece from General Kaal in the Sanguine Depths. Progress: What information do you bring?",rewardItems={178576},rewardChoices={1804,1805,1806,1807,184374},starts={{npcID=167881}},ends={{npcID=167881}},coords={x=0.51,y=0.438,source="quest_giver",zoneID=10565},questType="dungeon"},
[60264] = {id=60264,name="Soul Survivor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I knew when you helped me in the Etheric Vault, that you were a just and worthy leader. I have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance. Please, build a construct for me, and allow me to help you as you have helped me.",objectivesText="Take specifications for Miru's construct. Progress: Are you willing to do this?",rewardGold=25740,rewardXP=1020,starts={{npcID=167877}},ends={{npcID=167150}},coords={x=0.55,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[60265] = {id=60265,name="Disrupting the Chain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="From the desk of the Tithelord: All supply carriages must re-route to Stonevigil for collection assistance. Once complete, you may resume your regularly scheduled routes.",objectivesText="Destroy the Darkhaven and Manor carriages in Stonevigil Overlook.",rewardGold=257400,rewardXP=8165,rewardItems={178557},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},ends={{npcID=167380}},coords={mapID=1525,source="quest_giver",x=0.562,y=0.666},questType="standard"},
[60267] = {id=60267,name="Prison of the Forgotten",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari may know more of its purpose.>",objectivesText="Take the object back to Ve'nari . Progress: <The lock appears to be sturdy, yet old and untouched. Dust has collected considerably upon it.>",rewardXP=4085,questType="standard"},
[60268] = {id=60268,name="Deep Within",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1912,description="Who... who are you? Have you come to extract more of my memories? I'm afraid there aren't any useful ones left, save for the memories of my imprisonment. Or perhaps you're here for something else?",objectivesText="Speak with the prisoner and learn of his situation. Progress: What do you want of me?",starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[60269] = {id=60269,name="Reawakening",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1912,description="If you can retrieve my memories, I can help you. At least I believe I can. Then, perhaps, we can help each other.",objectivesText="Find a stolen memory of the Runecarver . Progress: Have you found what was taken from me?",rewardXP=10205,rewardItems={178561},starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[60270] = {id=60270,name="A Damned Pact",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Yes... I begin to remember. Power. Power with a purpose. That is what I can offer. Runes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands. Well, one hand would suffice. Both would be better. Find a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.",objectivesText="Discover a way to break the Runecarver free from his chains.",starts={{npcID=164937}},ends={{npcID=162804}},questType="standard"},
[60271] = {id=60271,name="A Grave Chance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="First you'll need a vessel to house anima and a way to expel it. I happen to possess such a device, which I'll be pleased to give to you. For a price, of course. You recall Zovaal's Cauldron, I trust? The denizens there were forged in unholy fire. Assuming their anima is of a similar nature, it should be able to melt even the metals of the tower. With my device and their anima, I believe you can achieve your goal, Maw Walker.",objectivesText="Purchase an Anima Supricifer from Ve'nari and recover 5 Molten Anima . Progress: Were you able to acquire the anima?",rewardGold=257400,rewardXP=8165,rewardItems={178562,181324},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60272] = {id=60272,name="The Weak Link",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="This ought to be enough to break the bonds that hold your newfound ally. Ve'nari pauses for a moment.> Before you do so, I offer a word of warning. No creature imprisoned in that place should be trusted. Tread carefully, mortal. After all, it would be a shame to lose so valuable a business partner.",objectivesText="Break the Runecarver free. Progress: It's good to remember something new again.",rewardXP=8165,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60274] = {id=60274,name="Trading Favors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="Welcome, friend. I can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes. There are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. Let your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.",objectivesText="Report to Finder Ta'sul in Oribos .",rewardGold=3805,rewardXP=1020,starts={{npcID=156688}},ends={{npcID=156688}},questType="standard"},
[60275] = {id=60275,name="WANTED: Enforcer Kristof",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="WARNING! Shrouded patrols have increased throughout the Ember Ward. By order of Enforcer Kristof , all who are found near the asylum will be forced to endure the Light. Use extreme caution when venturing beyond our sanctuary. Even the shadows are not safe so long as Kristof remains in power. A reward awaits whoever is able to rid the ward of this tyrant. - Dispatcher Raluca",objectivesText="Find and slay Enforcer Kristof .",rewardXP=12250,rewardItems={181714},starts={{npcID=351874}},ends={{npcID=168120}},coords={x=0.307,y=0.489,source="quest_giver",zoneID=10413},questType="standard"},
[60276] = {id=60276,name="WANTED: Summoner Marcelis",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Be advised: Summoner Marcelis and his cohorts are dabbling in dangerous magics. They are calling forth ashen elementals to ravage these Light-scorched lands. We cannot let such acts continue. Any who can are urged to put an end to this madness. - Dispatcher Raluca",objectivesText="Find and slay Summoner Marcelis . Progress: You'll get your reward when you slay Marcelis, and not a moment sooner.",rewardXP=2125,rewardItems={180459},starts={{npcID=351888}},ends={{npcID=168120}},coords={x=0.308,y=0.49,source="quest_giver",zoneID=10413},questType="standard"},
[60277] = {id=60277,name="WANTED: Aggregate of Doom",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Attention all workers: We got ourselves a problem down in the thicket. A golem is trekking through the worksite, causing all sorts of trouble. Grab a rock and get to throwin'. The dredger that takes it out gets the rest of the day off. - Foreman Scug",objectivesText="Find and slay the Aggregate of Doom .",rewardXP=2125,rewardItems={180288},starts={{npcID=351885}},ends={{npcID=168122}},coords={x=0.591,y=0.692,source="quest_giver",zoneID=10413},questType="group"},
[60278] = {id=60278,name="WANTED: Duke Anton",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Loyal Citizens of Revendreth : Duke Anton and his decrepit house are relics of noble venthyr society. His attempts to tarnish my name are laughable at best. It is time someone rid us of Duke Anton 's presence for good. I shall offer double whatever pathetic sum he can muster. Sincerely, Lord Darion of House Redelav",objectivesText="Find and slay Duke Anton of House Briarbane.",rewardItems={179380},starts={{npcID=351886}},ends={{npcID=168121}},coords={x=0.607,y=0.401,source="quest_giver",zoneID=10413},questType="standard"},
[60279] = {id=60279,name="WANTED: The Pale Doom",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Notice to all: A lingering menace lurks in the Endmire, dangerously close to Darkhaven's border. If alone in your travels, take care to avoid this monstrosity, lest it make you meet your true death. Those with a sense of adventure and a well-armed brigade might manage to slay this beast. If so, a reward will await you upon your return. Sincerely, Taskmaster Gavril",objectivesText="Find and slay The Pale Doom within the Endmire. Progress: There's no shame in turning down the bounty. Not everyone has what it takes to slay a devourer.",rewardXP=10205,rewardItems={180458},starts={{npcID=351889}},ends={{npcID=168057}},coords={x=0.622,y=0.635,source="quest_giver",zoneID=10413},questType="group"},
[60280] = {id=60280,name="WANTED: Lord Darion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="To Whom it May Concern: Lord Darion of House Redelav thinks that he can buy his place in society. He flaunts his wealth, using it to win favor of other lords and ladies. Is there no price on decency? This is not the way the noble houses of Revendreth should conduct themselves. I implore you to find Lord Darion and help him meet his true death. The honor of House Briarbane rests in your capable hands. Warmest Regards, Duke Anton of House Briarbane",objectivesText="Find and slay Lord Darion of House Redelav.",rewardXP=12250,rewardItems={180289},starts={{npcID=351887}},ends={{npcID=168121}},coords={x=0.608,y=0.4,source="quest_giver",zoneID=10413},questType="standard"},
[60281] = {id=60281,name="Rule 4: Make A List",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I've discovered that one of the Jailer's inquisitors is attempting to devise a method to track my movements. Clearly, that is a problem for me... and by extension, it is a problem for you. The inquisitor has risen to the top of my list of potential threats. In the past, I would have had to deal with him myself. But now... I have a business partner. Put an end to him, yes? And if you can, determine exactly how he intended to track me.",objectivesText="Kill Inquisitor Devaki and find out how he is trying to track Ve'nari . Progress: Have you learned anything of Inquisitor Devaki 's tracking methods?",rewardGold=514800,rewardXP=10205,rewardItems={184492},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60283] = {id=60283,name="Specter Of War: Visectus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,objectivesText="Progress: We have conjured Visectus to lead our attack, but we need your help to prepare it properly. We require more Anima-bound Wraps to strengthen the summons.",starts={{npcID=161668}},ends={{npcID=161668}},coords={x=0.534,y=0.692,source="quest_giver",zoneID=11462},questType="standard"},
[60284] = {id=60284,name="Rule 5: Be Audacious",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="You have proven yourself a useful associate, . In thanks, I have crafted a cypher that will allow you to venture further into the Maw . But... it is experimental in nature. You will have to test it in the field. And I have just the test in mind. Cartel Ve has foolishly sent more agents into the Maw . They were captured and taken to Perdition Hold. I must know why. Breach the fortress and learn what has become of the captive brokers. Nothing is more valuable than knowledge of your enemy's plans.",objectivesText="Investigate the increased activity within Perdition Hold. Progress: What have you discovered, Maw Walker?",rewardGold=514800,rewardXP=10205,rewardItems={182688},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60285] = {id=60285,name="Rule 6: Concealment is Everything",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have made a startling discovery, . Do you recall how the captured agents of my cartel were taken to the Beastwarrens? The Mawsworn seem to think they possess a means of tracking me. And now, strange new runes empower the Jailer's hounds. Clearly, we cannot have that. This new cypher will grant you solace from the screeching in the Beastwarrens. Brave its caverns and secure those runes for inspection. If we are to counter their effects, I must know how they work.",objectivesText="Retrieve 15 Broker Hunting Runes from The Beastwarrens. Progress: The runes... you have them?",rewardGold=514800,rewardXP=10205,rewardItems={182955,182956},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60287] = {id=60287,name="Rule 1: Have an Escape Plan",level=55,requiredLevel=55,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Many doomed souls suffer within the Maw . You must be careful if you do not wish to join them. Your Soulkeeper can hold a small number of souls until you return to your covenant. But that will be of little benefit if you do not survive this place yourself. There is a substance, stygia, that is found on some creatures within the Maw . The stronger the soul, the more stygia they have. Collect some of it for me and I can fashion it into many things you will find quite useful.",objectivesText="Rescue 5 souls and retrieve 60 Stygia. Stronger enemies will have a higher chance to drop large amounts of Stygia. Use the Stygia to purchase a Cypher of Relocation from Ve'nari . Progress: I will gladly assist you in the acquisition of survival tools... provided you bring me the stygia.",rewardGold=257400,rewardXP=7490,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60288] = {id=60288,name="Supplies from the Necrolords",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="<name>, thanks to your efforts, our forces have been able to secure additional resources in our battles. The more you continue to dominate the battlefield the more resources our forces can spare.",objectivesText="Speak with Oyne Soulborn at the Bleak Redoubt in Maldraxxus for your reward.",questType="standard"},
[60289] = {id=60289,name="Rule 3: Trust is Earned",level=55,requiredLevel=55,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Before you leave this cursed realm, there is one final task you must complete for me. The Mawsworn regularly transfer souls to various blocks of Torghast from many different areas in the Maw . I happen to know of one such area. Place this beacon there so I may be informed when the next transfer happens. And if you are seen by the enemy... well, you are known for your prowess in combat, yes?",objectivesText="Place a Signaling Beacon in Cocyrus. Progress: I will have opportunities for trade in the future, Maw Walker. I am certain our paths will cross again.",rewardGold=514800,rewardXP=9365,rewardItems={184284},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[60291] = {id=60291,name="Corpse Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?",rewardXP=8165,rewardItems={183744,182483,182492,182501,182510,184843},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=158300,x=0.542,y=0.68,zoneID=11462},{npcID=158300,x=0.332,y=0.546,zoneID=11400}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Corpse Run"},
[60292] = {id=60292,name="Dangerous Discourse",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I found this scroll while you were cleansing the temple. These are dire words, and I suspect it only gets worse. Collect more of these scrolls so I can determine just what these so-called Forsworn want.",objectivesText="Collect 6 Dark Sermons . Progress: We must defend the temple, <name>.",rewardGold=257400,rewardXP=1415,rewardItems={171215},starts={{npcID=159762}},ends={{npcID=159762}},coords={x=0.54,y=0.736,source="quest_giver",zoneID=10534},questType="standard"},
[60296] = {id=60296,name="Pride or Unit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You have made great strides with our pride. I hope you found value and fulfillment in working with the larion. The time to meet with Pelodis has come. You must decide whose way of life is more rewarding, and which you would prefer to pursue.",objectivesText="Meet with Pelodis and Nemea , then pick a side. Progress: The pack has welcomed you, <name>. I hope that you feel it.",rewardGold=23870,rewardXP=175,starts={{npcID=157696}},ends={{npcID=157696}},coords={x=0.572,y=0.392,source="quest_giver",zoneID=10534},questType="standard"},
[60313] = {id=60313,name="Dredhollow",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="That was a narrow escape. But I believe this presents an opportunity to finally turn the tide of this strife and defeat the Fearstalker. Meet me at Dredhollow: the abandoned hunting lodge of the Fearstalker. We must take separate paths. The Fearstalker will soon be after us again.",objectivesText="Meet the Accuser at Dredhollow.",rewardGold=25740,rewardXP=175,starts={{npcID=156554}},ends={{npcID=168217}},coords={x=0.516,y=0.592,source="quest_giver",zoneID=10413},questType="standard"},
[60315] = {id=60315,name="WANTED: Gorgebeak",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Thief! Pilferer! Menace! The insidious menace known as Gorgebeak threatens our harvest of ambrosi for tribute to our great Archon. She must be stopped! If any are willing to take on this foul fowl, I have tracked her nest to the western edges of Firstborne's Bounty. Proof of her demise shall be amply rewarded. -- Gerdus",objectivesText="Collect Gorgebeak's Bill for Gerdus in Firstborne's Bounty. Progress: What business have you with this simple tender?",rewardGold=716040,rewardXP=1770,rewardItems={173345,173346,173347,173348,178683},rewardChoices={173345,173346,173347,173348},starts={{npcID=352027}},ends={{npcID=161499}},coords={x=0.532,y=0.464,source="quest_giver",zoneID=10534},questType="group"},
[60316] = {id=60316,name="WANTED: Altered Sentinel",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Praetor broken! At Aspirant's Crucible. Attacking everybody! Something wrong. Maybe changed? Simo not know how to fix. Tried everything! Must destroy!",objectivesText="Destroy the Altered Sentinel for Forgehand Simo in Aspirant's Rest.",rewardGold=772200,rewardXP=1770,rewardItems={173349},starts={{npcID=352028}},ends={{npcID=160596}},coords={x=0.491,y=0.728,source="quest_giver",zoneID=10534},questType="group"},
[60337] = {id=60337,name="Pupa Trooper",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={178717},questType="world",db2Objectives={{orderIndex=0,type=2,amount=1,objectID=365342,text="Borrow a pair of enchanted wings"}},worldTaskTitle="Pupa Trooper",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60338] = {id=60338,name="Journey to Ardenweald",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The warning you received from the Primus needs to reach the Winter Queen of Ardenweald , . The Eternal Ones must stand together against the coming darkness. The Winter Queen oversees the cycle between Death and Life. In her forest slumber ancient spirits of nature that must be reborn. I fear the anima drought will have taken an especially grim toll upon her realm. The night fae can lead you to the Queen. Bring her this message, and she will know what needs to be done.",objectivesText="Travel to Ardenweald and find someone to take you to the Winter Queen.",rewardGold=25740,rewardXP=175,starts={{npcID=159478}},ends={{npcID=168341}},questType="standard"},
[60339] = {id=60339,name="The Ember Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!",objectivesText="Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests. Progress: I can't wait to see who attends today's court!",rewardGold=772200,rewardXP=12250,rewardItems={179958},starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[60340] = {id=60340,name="Hands on Approach",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape. Now, with my blade hands... it's time for my revenge! I've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!",objectivesText="Slay Wurtzog Soultap and recover 12 anima traces . Progress: Did you kill them all?",rewardXP=8165,rewardItems={178788},starts={{npcID=159214}},ends={{npcID=167150}},coords={x=0.544,y=0.678,source="quest_giver",zoneID=11462},questType="standard"},
[60341] = {id=60341,name="First on the Agenda",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Let's make a deal, . I'll seek out the Winter Queen on your behalf if you complete a few of my duties in my stead. The Queen isn't the only one who's been kept busy by the drought! First, you're going to help my fellow fae here with their spriggan problem. Boot their leader off that poor moth! Featherlight will tell you where to go after that. We'll reunite in Tirna Vaal if you survive. Oh, and I would stay on the path if I were you. Ardenweald can be dangerous for the unwary!",objectivesText="Slay Mothbane the Mighty . Progress: Not bad! Not bad at all!",rewardGold=378480,rewardXP=1770,starts={{npcID=157788}},ends={{npcID=170175}},coords={x=0.65,y=0.196,source="quest_giver",zoneID=11510},questType="standard"},
[60342] = {id=60342,name="Cut 'Em Down to Size",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1536,description="Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything! I hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!",objectivesText="Slay Charthox in the Dredgewood of Revendreth.",rewardXP=8165,rewardItems={183744,182484,182493,182502,182511,184843},starts={{npcID=159214}},ends={{npcID=167150}},coords={x=0.544,y=0.678,source="quest_giver",zoneID=11462},questType="standard"},
[60343] = {id=60343,name="Welcome to Orgrimmar",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once. For now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit. I'll send for you once I've given my report to the warchief.",rewardGold=1000,rewardXP=505,starts={{npcID=168431}},ends={{npcID=168441}},coords={x=0.524,y=0.882,source="quest_giver",mapID=85},questType="standard"},
[60344] = {id=60344,name="Finding Your Way",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Orgrimmar 's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around. She said to speak with Rohaka at the stables... but I can't seem to remember the way there. Don't worry, ! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master. Then we can be on our way!",rewardXP=505,rewardChoices={25474},starts={{npcID=168441}},ends={{npcID=168540}},coords={x=0.52,y=0.854,source="quest_giver",mapID=85},questType="standard"},
[60346] = {id=60346,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Telotha Pinegrove to learn more about specializations!",rewardXP=505,ends={{npcID=168553}},questType="standard"},
[60347] = {id=60347,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Tamanji to learn more about specializations!",rewardXP=505,ends={{npcID=168551}},questType="standard"},
[60348] = {id=60348,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Feenix Arcshine to learn more about specializations!",rewardXP=505,ends={{npcID=168626}},questType="standard"},
[60349] = {id=60349,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Huinli Wingpaw to learn more about specializations!",rewardXP=505,ends={{npcID=168619}},questType="standard"},
