[60352] = {id=60352,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Thega Graveblade to learn more about specializations!",rewardXP=505,ends={{npcID=168598}},questType="standard"},
[60353] = {id=60353,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Hretar Riverspeaker to learn more about specializations!",rewardXP=505,ends={{npcID=168628}},questType="standard"},
[60355] = {id=60355,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Kazak Darkscream to learn more about specializations!",rewardXP=505,ends={{npcID=168623}},questType="standard"},
[60357] = {id=60357,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Gormok Ogrefist to learn more about specializations!",rewardXP=505,ends={{npcID=168596}},questType="standard"},
[60358] = {id=60358,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Took our gildenite ! Stole it! Stole it and took it away! Need it, need it to make armor! Weapons! Can't make armor without gildenite ! You understand? Yes? Why you still here?",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60359] = {id=60359,name="Home Is Where the Hearth Is",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="I don't know about you, but I'm in the mood for some good ol' fashioned recreation! Why don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola? While we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a wyvern, but you'll save yourself some dough in the process!",rewardXP=505,ends={{npcID=46642}},questType="standard"},
[60360] = {id=60360,name="An Urgent Meeting",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="I've been looking for you all over Orgrimmar , . Warlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again. I was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, . Lok-tar ogar!",objectivesText="Speak with Warlord Breka Grimaxe at Grommash Hold.",rewardXP=125,starts={{npcID=168771}},ends={{npcID=168431}},coords={x=0.71,y=0.496,source="quest_giver",zoneID=1637},questType="standard"},
[60361] = {id=60361,name="Battle for Azeroth: Mission Statement",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=8499,mapID=862,description="The warchief has requested to meet with you in person. Lady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. Now that you've arrived, I will make the introduction.",rewardGold=200,rewardXP=125,rewardItems={178941,178942},rewardChoices={178941,178942},starts={{npcID=168431}},ends={{npcID=121210}},coords={x=0.524,y=0.882,source="quest_giver",mapID=862},questType="standard"},
[60362] = {id=60362,name="Blank",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1519,mapID=84,description="Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.",objectivesText="Speak with Lady Jaina Proudmoore in Stormwind Harbor.",rewardGold=119340,rewardXP=1415,questType="standard"},
[60363] = {id=60363,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Hshh... the golden ore, we need it. Golden ore of Bastion. Make their armor with it. We need, many uses. Armors, weapons, trinkets and rings. Many uses. Travel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands. They do not use it. We will. Go now.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60364] = {id=60364,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="Our allies in Bastion are in possession of a special ore known as gildenite . A golden metal used for many things in their lands, it is also useful to us. Once upon a time, we would have traded for it. Now, we have little to trade, and they have little to give. Yet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it. Should you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60365] = {id=60365,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well. Our stores are nearly depleted, and we have little to trade, but our needs are great. Let us reflect. In Bastion, there are those that have turned their backs on their own people. We may relieve these deceivers of their gildenite without remorse.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60366] = {id=60366,name="WANTED: Darkwing",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Cloudfeather matriarch, Darkwing, has fallen to a great and terrible sickness. She has grown aggressive, dominating her children and driving them to violence. Darkwing must be slain if her flock is to ever return to the Archon's grace. Please use the attached whistle to call her to her nest. I shall consider one of her crown feathers sufficient proof of the deed. -- Eumelia , Stable Master",objectivesText="Collect an Umbral Plume from Darkwing in Greatwing Roost for Eumelia . Progress: Until Darkwing rests at last I fear her brood will know no peace.",rewardGold=716040,rewardXP=1770,rewardItems={175762,178790,178791},rewardChoices={175762},starts={{npcID=352027}},ends={{npcID=160178}},coords={x=0.532,y=0.464,source="quest_giver",zoneID=10534},questType="group"},
[60369] = {id=60369,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="The shapers of our lands cultivate a very special form of wood we call wealdwood . It contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn. It is the basis of our arms and armor, and in these dark days, it is a target of our enemies. They steal and hoard it, out there in the wilds. Find them, and return our treasures to us.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60370] = {id=60370,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood , an enchanted substance used for many sorcerous purposes, is a key component in our rituals. Without it, our magics pale in comparison to those of our enemies. Yet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places. Travel to those places, and return to us once you have brought atonement to these vile creatures.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60371] = {id=60371,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes. They do not use it, not as we would. We must use it. It is ours to take. Kshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it. Need it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60372] = {id=60372,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood . wealdwood magical, help us make many thing. You find some? Bring to Sika? Yes? Hoo? Yes. See?",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60373] = {id=60373,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="There is a dark, evil vine that grows in Revendreth, known as sorrowvine . They say it feeds off of the anguish of the souls as they are broken. Regardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin. Revendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60374] = {id=60374,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones. They form their armors out of a cultivated form of bone we call bonemetal . Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength. We have many uses for it, both as a means of attachment, and when ground up, as a reagent. We cannot ask them for resources now, but if you find any, I would use it.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60375] = {id=60375,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Maldraxxus no longer answers our calls, and the houses are in disarray. Yet we have need of them. Once, they supplied us with bonemetal , a strong yet malleable material useful for many armors. There are those in Maldraxxus that hoard the material, seeking to profit from the chaos. They must atone for these sins.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60376] = {id=60376,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Ksh-ksh-ksh... you are needed. So many betrayers in our lands, many deaths, much armor destroyed. Need to rebuild. The eyes have shown me stores of bonemetal , hoarded by our foes. Bring them to me.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60377] = {id=60377,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="No bonemetal ! Again, out of bonemetal ! Hoo! Where you come from? Oh, OH. bonemetal ! You get? Get from Maldraxxus. Help us out! That way!",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60378] = {id=60378,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins. We use it for many things, from potions to venoms. It is a versatile reagent. Our stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us. As you travel our lands, should you come upon any, we would make good use of it.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60379] = {id=60379,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms. Revendreth does not answer our calls. The eyes show me conflict and strife in their lands. This matters little to us. Shh... travel there, find their vines, return to me.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60380] = {id=60380,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Need sorrowvine ! Please help! Revendreth not sending us supplies, not answering Sika! Can't make potions now. What we do? You go! Go go!",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60381] = {id=60381,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides. Travel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall. Remind them that our great purpose will be fulfilled, and we will not let the groves wither. You, Maw Walker, will unite us today.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60382] = {id=60382,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="We do not turn out backs on our allies, even when we face darkness here in Ardenweald. In Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader. We cannot allow those that make Sinfall their home to lose hope. Travel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60383] = {id=60383,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did. Now they are plagued by infighting and an imbalance in power. We have few allies there, but those that remain, we must maintain. Go there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more. Without them, we are but one invasion from complete annihilation.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60384] = {id=60384,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die. We cannot allow them to fall, for without Bastion, we are lost. Travel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60385] = {id=60385,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training. Come here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt. For tomorrow, we hunt.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60386] = {id=60386,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves. There is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields. Take this one with you on your travels today, so that they may see what real combat looks like.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60387] = {id=60387,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Our hunters do not have the time for proper training, and so we must train them in the field. Our allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor. Do you hear that, trainee? Today, you accompany the Maw Walker! Maw Walker, do not go easy on this one.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60388] = {id=60388,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Get up, trainee, you must get up! Look at this one! Needs much more training before we stand a fighting chance against our enemies. We have precious little time to build combat prowess these days, with so many foes at our backs. Take this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60389] = {id=60389,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Ay there, ya got a moment? Lotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one. We're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? Do I gotta spell it out for you? Get on over there, ya big goof.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60390] = {id=60390,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We are attacked by enemies on all sides, Maw Walker. And Ardenweald faces a similar threat. It is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need. Together, we are strong. This is the doctrine of the phalanx, and it will be ours as well.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60391] = {id=60391,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall! Make haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone! Bastion stands with them, and with us, they will never falter!",rewardItems={181475},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60392] = {id=60392,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In our own golden hills, evil abounds. We will not allow it to take root and fester! Raise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them! With haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon! For Bastion!",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60393] = {id=60393,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them. Travel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies. War is not always fought on the battlefield, but often in the means of replenishment.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60394] = {id=60394,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better. We got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff. Rendle wipes his nose loudly.>",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60395] = {id=60395,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all. We must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord. A spear of gold and bone we will form! And thrust it into the heart of evil! Go now, Maw Walker, as the tip of the spear, to glorious battle!",rewardItems={181732},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60396] = {id=60396,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand. Walk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you. Fear is the seed that breeds doubt, and doubt is the root that crumbles empires.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60397] = {id=60397,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left. All's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out. Get over there and help them good ones keep the peace, maybe they help us out some day, too.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60398] = {id=60398,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. Once, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses. Today, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part. It is your Primus-given duty to aid Sinfall against those that seek to break the cycle.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60399] = {id=60399,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Oi there, got somethin' for you to do today. Lots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems. We're not gonna make much headway against Denathrius with his lot at our heels all the time, ay? Get out there an' get some muck on your boots.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60400] = {id=60400,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius. We cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all. We of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!",rewardItems={181556},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60401] = {id=60401,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. Plenty of things to maim over there, maybe they learn a thing or two about wood.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60402] = {id=60402,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads. Take this trainee out and get them some real combat experience. Ardenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60403] = {id=60403,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="It is our great duty to take our aspiring warriors and train them in combat. Today, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands. Teach them the ways of battle and honor.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60404] = {id=60404,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="What better place to stretch our wings than right here on our own fields? Take one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here. Part of their training will be courage when facing off against those they thought their brethren. It has been known to break hearts and ranks before.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60405] = {id=60405,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Useless minions, the lot of them. All of this fodder needs to get trained. Here, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me. Plenty of things to test them against, there. If you get them killed, I don't want to hear it.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60406] = {id=60406,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have yet another minion, er, recruit that needs training. Take them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. Maybe you pick up some new tricks while you're out there, too.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60407] = {id=60407,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath. Take this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators. There, they will face true challenges, and return with great knowledge.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60408] = {id=60408,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat. Take a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60409] = {id=60409,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Another trainee needs some looking after, if you don't mind. Maldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that. Just throw them in the arena or something. 'Sink or swim' is an effective training strategy.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60410] = {id=60410,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have yet more troops for you to train, and there are plenty of things to do right here in our domain. Take them out and give them a good, solid, and probably bloody taste of what we're up against. Now, if you get them killed? That's none of my business.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60411] = {id=60411,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking. Do me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic. Won't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60412] = {id=60412,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="A trainee is in need of your guiding hand. Take them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes. Return victorious, as their shield and mentor, so that our armies will be bolstered this day.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60414] = {id=60414,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1701,description="The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. We have relied upon them to bring us useful materials for many years, but these days, we have little to trade. They value a currency of their own making, coins of brokerage, as a general means of trade. If you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.",rewardItems={179327,181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168513,x=0.436,y=0.524,zoneID=11510}},ends={{npcID=168513,x=0.436,y=0.524,zoneID=11510}},coords={x=0.436,y=0.524,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60415] = {id=60415,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Hello! Yes! Hello. Brokers, you know them? Sika does her best attempt at looking like a broker. It is not convincing.> Trade many things with us. Things we no get. Things we want. Need coins. Clink clink! Sika makes a circle with her finger feathers.> Find them everywhere, bring them to Sika !",rewardItems={179327,181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168519,x=0.634,y=0.168,zoneID=10534},{npcID=168519,x=0.334,y=0.448,zoneID=11012}},ends={{npcID=168519,x=0.634,y=0.168,zoneID=10534},{npcID=168519,x=0.334,y=0.448,zoneID=11012}},coords={x=0.634,y=0.168,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60416] = {id=60416,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them. Find many secrets, they do. Bring us supplies, strange and rare. Need things to trade. Need broker coins. They trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. You may eat their corpses, I will not judge. Just need coins.",rewardItems={179327,181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167201,x=0.47,y=0.384,zoneID=12876}},ends={{npcID=167201,x=0.47,y=0.384,zoneID=12876}},coords={x=0.47,y=0.384,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60417] = {id=60417,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13400,mapID=1700,description="The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure. They are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere. They hold in high regard a currency of their own creation, you may find such coins in your travels. I will gladly take them off of your hands to bolster our supplies.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158713,x=0.248,y=0.562,zoneID=10986},{npcID=158713,x=0.608,y=0.664,zoneID=10986}},ends={{npcID=158713,x=0.248,y=0.562,zoneID=10986},{npcID=158713,x=0.608,y=0.664,zoneID=10986}},coords={x=0.248,y=0.562,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60418] = {id=60418,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1701,description="Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. If they fall to darkness, it's only a matter of time before we, too, dwindle and fade. They are beset by all manner of problems. We have to get over there and help them!",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60419] = {id=60419,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1701,description="They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! All throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect. If the cycle stops here, so many great souls will be lost... forever. There's no time to waste, we need your help! Defend Ardenweald!",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60420] = {id=60420,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1701,description="I'm glad you're here! We've got some problems in Maldraxxus. The forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. But now, some of the houses have overthrown the balance, and seek to conquer the rest of us! Our allies there need our help! Aid them however you can.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60421] = {id=60421,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1701,description="Oh, I'm glad you're here, we've got a problem! Our friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! If Denathrius's control of Revendreth isn't broken, he'll come for us next... Let's do whatever we can to help them out!",rewardItems={181556},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60422] = {id=60422,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1699,description="We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger. The great soul-trees of Ardenweald are under assault from many foes that seek to harness their power. We must aid our allies in the Night Fae, and punish their enemies for these transgressions. We are stronger together.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60423] = {id=60423,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1698,description="Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. Maldraxxus alone is responsible for challenging those that would disrupt the cycle. Take our banners, steady your weapons, and bring war to Ardenweald. For the Shadowlands.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60424] = {id=60424,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1707,description="Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls. Should the weald fall, the devastation that would be unleashed could destroy us all. We must aid the Winter Queen. It is the will of the Archon. Go now, and provide support to the Night Fae.",rewardItems={181475},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60425] = {id=60425,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1707,description="Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes. Today, we root them out. Head into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you. In the name of the Archon.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60426] = {id=60426,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1698,description="We, the defenders of the Shadowlands, will never let a great foe go unchallenged. The Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services. Now, they too are under attack from within. We must defend them in their time of need. Go now, and bring glory in the name of the Primus.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60427] = {id=60427,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1699,description="The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger. They have their own troubles in these times, as well. Today, we must look without, and aid our allies. Travel to the golden fields, and rid them of their foes. Only with allies do we stand a chance against Denathrius.",rewardItems={181372},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60428] = {id=60428,name="The Blade of the Primus",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="That's everything I need. Time to get to work. I'd stay close, if I were you. Forging a weapon is never a simple task when the Primus's handiwork is involved. If he taught me anything, it was to expect the unexpected.",objectivesText="Help Bonesmith Heirmir forge your runeblade. Progress: Stay close, now.",rewardGold=514800,rewardXP=1770,starts={{npcID=157676}},ends={{npcID=157676}},coords={x=0.362,y=0.708,source="quest_giver",zoneID=11462},questType="standard"},
[60429] = {id=60429,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1698,description="Look! Look around you! All around us, foes await the crushing hand of victory. There is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened. The only cure is more combat! Challenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60430] = {id=60430,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1707,description="The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands. Now, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others. Their problems are many, our solutions are just. Travel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60431] = {id=60431,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1699,description="The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now. The houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten. Go now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60432] = {id=60432,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1699,description="There are many tasks that need your attention outside of the walls of Sinfall. Our closest allies are under assault from all sides, and the forces of Denathrius are unrelenting. Take your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies. We will take back what is ours.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60433] = {id=60433,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1698,description="We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls. There is one such betrayer - Sire Denathrius. Bring the vengeance of Maldraxxus down upon his foul crown. Slay his allies, serve his foes, end his reign in carnage.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60434] = {id=60434,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1707,description="We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just. Yet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands. We have friends there, amongst the Venthyr. Aid them, and put their enemies to rest. The Word of the Archon is with you.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60435] = {id=60435,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors. Over many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will. What better way to secure our allies and test our strength, than to eliminate his most fervent champions. Go now, and hunt.",rewardItems={181476},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60436] = {id=60436,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands. There, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds. Crash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60437] = {id=60437,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls. They are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos. Doubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.",rewardItems={181741},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60438] = {id=60438,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life. In our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue. Take on this trial, and put an end to the invaders of Tirna Scithe.",rewardItems={181476},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60439] = {id=60439,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades. Ready your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness. It is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils. Light shines only in darkness.",rewardItems={181476},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60440] = {id=60440,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no? So ready your weapon and get out there! What better place to prove your might? Smash them to pieces, in the name of Maldraxxus!",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60441] = {id=60441,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Ardenweald was once a place of peace and regrowth, but no longer. Foes assault the weald from all sides, dark creatures that serve no masters. They will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them. They will see what we do to those that must be broken. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",rewardItems={181476},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60442] = {id=60442,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Sometimes we need look no further than our own golden hills to find a suitable challenge. Doubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight. We must stand against them, now. It will not be easy, but things that are worth fighting for rarely are.",rewardItems={181741},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60443] = {id=60443,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle! We must aid them against their foes, or else the arena will sit barren, and we can't have that! Find their greatest enemies and turn their bones into golden dust.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60444] = {id=60444,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services. Yet, within their ranks, doubt has grown and festered. If this continues, we will all pay. Their loss of focus shall not be allowed to continue. We will punish their wandering hearts. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",rewardItems={181741},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60445] = {id=60445,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds. Here, you will find some of your greatest challenges. Seek out the champions of the strongest houses, stand against them, and let them see your might.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60446] = {id=60446,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds. For many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless. They must pay for these transgressions. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60447] = {id=60447,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors. What better place to test yourself? Head into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60448] = {id=60448,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all. Some are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. They are the mightiest of Denathrius's allies, and they must be brought to justice. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",rewardItems={181557},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60449] = {id=60449,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out. Their leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right. I want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60450] = {id=60450,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? In this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield. None more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands. And here is where you must challenge yourself today.",rewardItems={181557},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60451] = {id=60451,name="Never Enough",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Well done, recruit. These were merely the first of many assignments in your future. Matters here demand my attention. Report to Baroness Draka and see what need she has of you. I will watch closely as this war unfolds.",objectivesText="Return to Baroness Draka .",rewardGold=24335,rewardXP=175,starts={{npcID=157895}},ends={{npcID=159065}},coords={x=0.362,y=0.602,source="quest_giver",zoneID=11462},questType="standard"},
[60452] = {id=60452,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it! You need to go back there! You're the Maw Walker! See what you can learn of his power, and slow him down however you can. I believe in you! Be careful, ok?",rewardItems={181476},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},ends={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60453] = {id=60453,name="The Path to Glory",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It's been some time since I had a chance to craft a weapon that powerful! Good to know that the skills I learned from the Primus haven't dulled. You'd best get back to the baroness with that runeblade. I'm sure the margrave will want to know you wield it, as well. The Primus was notorious for thinking ten paces ahead of everyone else. I suspect he knew that someone like you would take up that blade.",objectivesText="Return to Baroness Draka with your runeblade.",rewardGold=25740,rewardXP=175,starts={{npcID=157676}},ends={{npcID=159065}},coords={x=0.362,y=0.708,source="quest_giver",zoneID=11462},questType="standard"},
[60454] = {id=60454,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this. We know little about the Jailer's lands, save that he is powerful beyond imagining. I ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces. We must buy more time.",rewardItems={181741},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},ends={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60455] = {id=60455,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall. Return to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day. His forces must be slowed, make what progress you can.",rewardItems={181733},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},ends={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},coords={x=0.432,y=0.472,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60456] = {id=60456,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return. What I am about to ask of you I would not dare ask of another. We cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands. Make what progress you can, we must slow down his forces however possible.",rewardItems={181557},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},ends={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60457] = {id=60457,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it. Maw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower. Bring us that which we lack.",rewardItems={181476,184561},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},ends={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60458] = {id=60458,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands. Souls that have been devoured, consumed, their anima lost to us. Return to us what you can.",rewardItems={181372,184561},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},ends={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60459] = {id=60459,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus. The Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops. Travel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.",rewardItems={181732,184561},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},ends={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},coords={x=0.432,y=0.472,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60460] = {id=60460,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society. This is a necessary part of the cycle. Yet now, the cycle is broken, and are unable to serve our great purpose. In order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.",rewardItems={181556},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},ends={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60461] = {id=60461,name="Meet the Margrave",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Word of the runeblade has reached Margrave Krexus . He wishes to see it for himself. With such a weapon by your side, you pose a threat that the other houses cannot ignore. Perhaps we can use that to our advantage. But enough talk. Follow me.",objectivesText="Present your runeblade to Margrave Krexus .",rewardGold=24335,rewardXP=175,starts={{npcID=159065}},ends={{npcID=158007}},coords={x=0.388,y=0.652,source="quest_giver",zoneID=11462},questType="standard"},
[60462] = {id=60462,name="Anima Appeal",expansion=8,mapID=1702,rewardItems={181475},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60463] = {id=60463,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Maw Walker! Our anima stores have run low, and soon we will have nothing to sate our thirst... Seek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum. These are dire circumstances. Our fate is in your hands.",rewardItems={181556},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60464] = {id=60464,name="Anima Appeal",expansion=8,mapID=1698,rewardItems={181732},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60465] = {id=60465,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Maw Walker! Our supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late! Search the realms for all the anima you can gather and deliver it to the sanctum. Time is short. Move swiftly, .",rewardItems={181372},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60466] = {id=60466,name="The Old Ways",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You there! Might I ask your help? I must confess, with the lack of new souls arriving, our supplies have dwindled. We lack the means to clothe arrivals in proper kyrian attire. Before the forging of the centurions, aspirants trained against the native wildlife. Perhaps there is another way these beasts can prove useful. If you collect materials from the cloudstriders and larions nearby, we can use them to ensure our new arrivals look the part. Oh, and some thread from Mirene, if you would!",objectivesText="Collect an Elysian Thread , 4 Cloudstrider Pelts , and 12 Larion Plumes . Progress: How goes the hunt?",rewardGold=772200,rewardXP=1770,rewardItems={173797,178885,178890,178891},rewardChoices={173797},starts={{npcID=160598}},ends={{npcID=160598}},coords={x=0.478,y=0.734,source="quest_giver",zoneID=10534},questType="standard"},
[60467] = {id=60467,name="A Rousing Aroma",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Sabina is unresponsive. Her exposed flesh cracked and blistered. Perhaps something with a pungent aroma will rouse her.>",objectivesText="Collect 4 Pungent Swarmer Toxin from Ravenous Swarms. Progress: Sabina remains unresponsive.",rewardGold=157500,rewardXP=1415,rewardItems={178898},starts={{npcID=168455}},ends={{npcID=168455}},coords={x=0.35,y=0.538,source="quest_giver",zoneID=10413},questType="standard"},
[60468] = {id=60468,name="Rubble Rummaging",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I do not know how long it's been since my captors left me here, but the Light has... taken its toll. You must help me escape. The key to my shackles should be hidden nearby. Perhaps among the rubble? That's likely where I'd hide something small.",objectivesText="Find a Shackle Key among the rubble within Ashen Traverse. Progress: Have you found the key?",rewardGold=386100,rewardXP=1415,rewardItems={178904},starts={{npcID=168455}},ends={{npcID=168455}},coords={x=0.35,y=0.538,source="quest_giver",zoneID=10413},questType="standard"},
[60469] = {id=60469,name="Safe in the Shadows",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I cannot recollect what happened. Perhaps the Light has burdened my memory? Who knows how long I've been out here... The last thing I remember before things went dark... my companions and I had finally found refuge in the shadows. I worry for their well-being. So long as my assailants remain at large, my companions could be in danger. Will you find them and ensure they're still safe in the shadows?",objectivesText="Find out what happened to Sabina 's companions.",rewardGold=386100,rewardXP=1415,starts={{npcID=168455}},ends={{npcID=168455}},coords={x=0.35,y=0.538,source="quest_giver",zoneID=10413},questType="standard"},
[60470] = {id=60470,name="Setting Sabina Free",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Release me. Please, you must do so. I cannot linger in the Light any longer. This unease, it's so... familiar, but it will pass. I will feel myself once again, once I have returned to the shade. I'll stay as still as silence while you work the lock.",objectivesText="Release Sabina from her shackles.",rewardGold=80250,rewardXP=1415,rewardItems={175736},starts={{npcID=168455}},ends={{npcID=168455}},coords={x=0.35,y=0.538,source="quest_giver",zoneID=10413},questType="standard"},
[60474] = {id=60474,name="Spawn Tracking Unit-Specified World Effect in a WMO Bug",level=1,requiredLevel=1,faction="none",expansion=8,zoneID=4019,description="There seems to be a bug when you setup a world effect containing a gold dot on the minimap through Spawn Tracking that is set to Unit, rather than Objective. It seems to only happen with spawns inside WMOs. Might also be happening with setting it to Object as well. If the Spawn Tracking on the World Effect is set to Objective, everything's fine. However, if it is set to Unit, the golden dot will not show up on the minimap.",objectivesText="Attempt to figure out why the WMO spawned objective's minimap golden dot will not appear when its spawn tracking is set to Unit instead of Objective.",questType="standard"},
[60475] = {id=60475,name="We'll Workshop It",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={178876},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=168568,text="Deliver the supplies"}},worldTaskTitle="We'll Workshop It",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60476] = {id=60476,name="Spriggan Size Me!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={178903,178907,178908,178909},questType="world",worldTaskTitle="Spriggan Size Me!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60480] = {id=60480,name="The Endmire",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oi! You. Not sure what landed you in the Endmire but I need your help. See these torches? It's my gig to keep 'em lit. But it ain't like they runnin' on flint n' tinder. My stash of infused rubies got hauled off by some devourers when my back was turned. Can ya find 'em before we both get ate by one of these horrors?",objectivesText="Find 5 Infused Rubies . Progress: Just going to be clear on this: I... HATE... THIS... GIG.",rewardGold=386100,rewardXP=1415,rewardItems={175751},starts={{npcID=168618}},ends={{npcID=168618}},coords={x=0.652,y=0.636,source="quest_giver",zoneID=10413},questType="standard"},
[60482] = {id=60482,name="See With My Eyes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. There are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now. Journey to the hold, use my sightless vision to see the weapons and recover what you can.",objectivesText="Collect 10 hidden weapons Progress: Have you recovered the weapons.",rewardGold=257400,rewardXP=8165,rewardItems={178992,178993},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=168675}},ends={{npcID=168675}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[60487] = {id=60487,name="It Used to Be Quiet Here",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Well... You don't look like the rest of 'em, do you? Chiselgrump shrugs.> Doesn't bother me. Keep my head down and do my job, making sure these sinstones stay in good shape. Keep breaking my tools, though. Bring me some more chisels and I'll teach you an old dredger construction trick.",objectivesText="Collect 8 Dredger Chisels . Progress: Got those chisels yet?",rewardGold=53500,rewardXP=1415,rewardItems={179002},starts={{npcID=168698}},ends={{npcID=168698}},coords={x=0.694,y=0.534,source="quest_giver",zoneID=10413},questType="standard"},
[60489] = {id=60489,name="The Path of Ascension",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With the anima you collected, we can once again start up the Path of Ascension. The eternal training ground of the kyrian, the Path is an ancient tradition and favored amongst many of the kyrian, aspirant and ascended alike. The Hands of Courage, Apolon and Artemede, have stepped up to lead this tradition. Once you herald the Path's rebirth, speak to them to learn more.",objectivesText="Activate the Path of Ascension.",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=168485}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[60491] = {id=60491,name="Among the Kyrian",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You will be well at home among the kyrian, . We welcome your aid. The Archon was so confident in this outcome that she has arranged a grand reception for you in honor of your efforts against the Maldraxxus incursion into our realm. For now, all you must do is journey to the Seat of Eternal Hymns. I shall meet you there.",objectivesText="Meet Polemarch Adrestes at the Seat of Eternal Hymns in Bastion.",rewardGold=25740,rewardXP=1020,starts={{npcID=171787}},ends={{npcID=168742}},questType="standard"},
[60492] = {id=60492,name="A Proper Reception",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Though the path you follow is not that of a traditional ascended, it is a kyrian path all the same. To follow it is to bask in the footsteps of the innumerable lives before us, forever in service to a good far greater than we can achieve alone. To join us amidst such strife is an accomplishment worthy of recognition. Our Archon has called all among us to join her in welcoming you to our ranks.",objectivesText="Join the Kyrian Covenant. Progress: This is the final step of joining our ranks. Should you have second thoughts, have them now.",rewardGold=128700,rewardXP=4085,starts={{npcID=168742}},ends={{npcID=168906}},coords={x=0.566,y=0.314,source="quest_giver",zoneID=10534},questType="standard"},
[60493] = {id=60493,name="Humble Gatherer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Before your soulbinds step foot in the coliseum, you must challenge your first opponent. There is a tradition to this, as with all things. You will need to gather specific items, then bring them back here to fashion armaments to help execute your challenge. In the case of your first challenge, you will find the materials throughout Bastion. Return to me once you have collected everything, then we will continue.",objectivesText="Collect 2 Depleted Goliath Cores from Forsworn goliaths, 6 Tampered Anima Chargers from Forsworn centurions, and 5 Soul Mirror Shards from Forsworn kyrian. Progress: Though the Path of Ascension leads to glory, participants must remember to stay humble and grounded in the tradition.",rewardXP=8165,starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60494] = {id=60494,name="Your Friend, Dactylis",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With the materials you gathered, you are now ready to craft your lure. Report to Dactylis. She will be able to help you craft not only this, but many more items of all kinds later. Once you craft your lure, return to me and I will give you your next instruction.",objectivesText="Speak to Dactylis to craft 2 Overcharged Goliath Cores and 1 Soul Mirror . Progress: Inspired by the Collectors, we must take the time to craft by hand. Through crafting we practice patience, diligence, and humility.",rewardGold=128700,rewardXP=4085,starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60495] = {id=60495,name="A Suitable Opponent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="The opponents you train against in the coliseum are not physical beings, but rather manifestations of such. Your first opponent is one you and your soulbinds have met numerous times before -- the Ascended Kalisthene. Asking another kyrian to be your opponent in the Path is a great honor, as it tells them that you have much to learn from them. Go to Aspirant's Awakening and use the cores to summon Kalisthene by calling back to your first introduction. It is as ceremony states.",objectivesText="Use the Overcharged Goliath Cores on the Depleted Goliaths in Aspirant's Awakening, then use the Soul Mirror to capture a memory of Kalisthene.",rewardGold=257400,rewardXP=8165,rewardItems={181782},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60496] = {id=60496,name="Into the Coliseum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="The time of your challenge has come! As you are not a being of Bastion, you shall act as a tactician for your soulbinds. You have developed mighty bonds between each other... let us see how they handle the coliseum. Let me know when you are ready to begin. Show us the merit of your bonds!",objectivesText="Speak to Artemede to challenge the Path of Ascension. Progress: This is just the first of many challenges ahead of you, <name>. Remember to stay humble.",rewardGold=257400,rewardXP=8165,rewardItems={180481},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60497] = {id=60497,name="Herald's Footpads",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Sometimes, sheer force of will is not enough. A piece of equipment can save your life. This blueprint you found can teach you to craft your first piece of equipment. Bring it over to Dactylis . She will be able to aid you in this as well.",objectivesText="Bring the Blueprint: Herald's Footpads to Dactylis . Progress: Welcome back. How may I aid you?",rewardGold=25740,rewardXP=1020,rewardItems={180464},starts={{npcID=168427}},ends={{npcID=168430}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60498] = {id=60498,name="Overcoming the Trial",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="These new footpads can give Pelagos the edge he may need to defeat Kalisthene . Return to the Path, . Equip Pelagos with these footpads and overcome your opponent. It may take a few tries, but all trials do. Go in service, and in glory!",objectivesText="Defeat Kalisthene in the Path of Ascension.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1819,amount=5}},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[60500] = {id=60500,name="Halls of Atonement: Medallion of Pride",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12831,description="Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. I do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. Lord Chamberlain falls into this latter category. His medallion must be taken by force.",objectivesText="Recover the Medallion of Pride from Lord Chamberlain within the Halls of Atonement. Progress: Have you recovered the medallion?",rewardGold=1029600,rewardXP=16330,rewardItems={179024},rewardCurrencies={{id=1807,amount=750}},starts={{npcID=352520}},ends={{npcID=158653}},coords={x=0.566,y=0.303,source="quest_giver",zoneID=10986},questType="dungeon"},
[60501] = {id=60501,name="Redemption for the Redeemer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="<Energies of death and innervation struggle to free themselves from the blade and consume you to your very core.> <The bonds of warding placed on this blade by Prince Renathal will not hold for long. It should be taken to Sinfall where more permanent arrangements have been made for this prisoner.>",objectivesText="Deliver Remornia to General Draven on the edge of Sinfall. Provided item:",rewardGold=1029600,rewardXP=16330,rewardItems={181552},ends={{npcID=168893}},coords={mapID=1525,source="quest_giver",x=0.26,y=0.436},questType="raid"},
[60502] = {id=60502,name="Sanguine Depths: An Ally Within",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="There are whispers of a prisoner within these depths that may be of use to our cause. Whether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. We cannot afford to ignore an opportunity such as this. Venture into the Sanguine Depths and recover this valuable prisoner.",objectivesText="Recover the valuable prisoner from within the Sanguine Depths.",rewardGold=1029600,rewardXP=16330,rewardItems={181549},starts={{npcID=166689}},ends={{npcID=168893}},questType="dungeon"},
[60504] = {id=60504,name="Strengthen the Bond",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="To bond souls is but the first step. You must now explore its potential. Just as Pelagos will gain strength from you, so too shall you grow from him. As your bond grows over time you will touch deeper into one another's souls, and so your strength shall increase. All you must do is place your hand upon the Forge of Bonds to augment your bond. There is no price to pay--the only limitation is your connection to our sacred covenant.",objectivesText="Activate a Soulbind Power using the Forge of Bonds. Progress: This device is merely a pathway to the strength that lies within you both.",rewardGold=128700,rewardXP=4085,rewardItems={180847,181373,181467,181469,181512,181600,181707,181759,181840,181962,181974,182106,182108,182113,182133,182295,182317,182321,182324,182336,182345,182440,182448,182460,182466,182469,182584,182646,182778,182960,183466,183467,183471,183492,183496,183500},starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[60505] = {id=60505,name="Spider's Lair",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. He has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse. I need you eliminate Manipulator Zalisar and his spider forces.",objectivesText="Slay 8 Razorweb Weavers and Manipulator Zalisar .",rewardGold=257400,rewardItems={181501,181502,181638,181645,181646,181647,181648,181649,181650,181656,181658,181671,181672,181673,181674,181679,181681,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=168675}},ends={{npcID=168675}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[60506] = {id=60506,name="The Accuser",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It is time to hunt our final prey, the Accuser . Anima drought or not, her sycophantic adherence to sacred \"rituals\" flies in the face of the Master's will. I can't wait to see the fear in her eyes.",objectivesText="Hunt the Accuser .",rewardGold=128700,rewardXP=710,starts={{npcID=156499}},ends={{npcID=156554}},questType="standard"},
[60508] = {id=60508,name="On the Trail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="In my visions, I witnessed Tyrande cutting through an endless storm of malevolent, nightmarish beings. Up ahead... is that...? Yes. I believe it is the very place I saw. Come. It may hold a clue as to where my mother has gone.",objectivesText="Look for signs of Tyrande Whisperwind.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174833}},ends={{npcID=168929}},coords={x=0.444,y=0.412,source="quest_giver",zoneID=11400},questType="standard"},
[60509] = {id=60509,name="Not My Job",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Right. So, 'em devourers are going to start creepin' out of the Endmire soon. And with the anima drought puttin' the squeeze to the fangs... well... we ain't gettin' help from them until it's too late. Us dredgers could use someone in your line of work. Professional destroyer as it were. If you can spare the time, meet me out at the Dredgewood. We'll scoop up a couple of lads and see if we can't make a stand.",objectivesText="Meet Rendle in the Dredgewood.",rewardGold=25270,rewardXP=175,starts={{npcID=158057}},ends={{npcID=157846}},coords={x=0.674,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[60510] = {id=60510,name="Descended",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple in Bastion. As I flew above their ranks I could hear their surgeons chanting its name above the din of combat-- Woeblade . It is an affront to all the kyrian stand for, an atrocity beyond any other. Mark it with the flames of courage when you engage, and we will help you destroy it.",objectivesText="Slay Woeblade the Atrocity.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=166333}},ends={{npcID=166333}},coords={x=0.356,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[60514] = {id=60514,name="Hunting Trophies",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="To be a hopebreaker is to conquer all prey, not just souls. The Banewood is home to many dangerous creatures: deathwalkers, fearspinners, and the horrifying doomfangs. If you wish to really master the art of the hunt, you should be able to defeat these foes. Bring me trophies as proof of your conquests. Then, you may just earn my respect.",objectivesText="Collect 3 Doomfang Skulls , 3 Pristine Deathwalker Paws , and 3 Prized Fearspinner Fangs . Progress: Have you conquered the creatures of the Banewood?",rewardGold=386100,rewardXP=1415,rewardItems={178996,178997,179316},starts={{npcID=156384}},ends={{npcID=156384}},coords={x=0.484,y=0.684,source="quest_giver",zoneID=10413},questType="standard"},
[60517] = {id=60517,name="The Toll of the Road",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This vessel appears to be brimming with anima. It is certainly tolls collected from denizens traveling by this crossroads. I am sure with all that is going on, Mistress Mihaela in Darkhaven would appreciate these tolls brought to her to cover the Village Ward's obligations.",objectivesText="Return the tolls to Darkhaven. Provided item:",rewardGold=14300,rewardXP=1770,ends={{npcID=156822}},coords={mapID=1525,source="quest_giver",x=0.614,y=0.638},questType="standard"},
[60519] = {id=60519,name="Audience with the Winter Queen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Zephyrs herald the Queen's arrival. Hushed silence descends upon the grove. Wait, watch, and speak when the time has come.",objectivesText="Speak to Moonberry and await the Winter Queen's arrival. Progress: The Queen shoulders so much because of this drought. But she is powerful, and I know we will make it through.",rewardGold=514800,rewardXP=1770,starts={{npcID=158487}},ends={{npcID=169031}},coords={x=0.634,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[60520] = {id=60520,name="Nightmares Manifest",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oh, this isn't good. As soon as you left, the spirit's nightmares spilled out all over Tirna Vaal. I've done everything to try to soothe her. I've tried singing to her, I've tried telling her stories, but nothing I do seems to calm her. Please, would you confront and dispel her nightmares? That might be the only thing that will work.",objectivesText="Confront the wildseed's nightmares in Tirna Vaal. Progress: Her dreams are usually beautiful.",rewardGold=248040,rewardXP=1415,starts={{npcID=169142}},ends={{npcID=169142}},questType="standard"},
[60521] = {id=60521,name="Call of the Hunt",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You've done so much, but the Queen's focus is still divided across the forest. If you want to deliver your message, then we need to help lessen her burden. Let's start with the Wild Hunt. They are the protectors of Ardenweald , and dealing with the threat of the masked fae has stretched them thin. Seek out Hunt-Captain Korayn at Glitterfall Basin. Last I heard, her hunting party could use reinforcements. And don't let her ferocity put you off. She's quite nice as long as you're not her prey!",objectivesText="Seek out Hunt-Captain Korayn in Glitterfall Basin.",rewardGold=24805,rewardXP=175,starts={{npcID=169031}},ends={{npcID=169584}},coords={x=0.636,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[60522] = {id=60522,name="Return to Tirna Vaal",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We of the Wild Hunt are always prepared to return to the cycle in defense of Ardenweald . I must move on, and so should you. I advise you to return to Droman Tashmur in Tirna Vaal. Others will need your help. Here, take this. It is a gift and a thank you. Helping each other is the only way to survive this drought.",objectivesText="Return to Tirna Vaal.",rewardGold=124020,rewardXP=710,rewardItems={180207},starts={{npcID=169935}},ends={{npcID=169935}},coords={x=0.512,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[60530] = {id=60530,name="The Sea of Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Some force here seeks to keep us from finding Tyrande. The trail of bodies seems to go into this... stream of souls. I suggest we split up. I will follow along the bank of the river. You enter its current and follow the trail. Should you need me, I will be close at hand. We will find Tyrande, no matter where this course leads.",objectivesText="Follow the trail of corpses to Tyrande Whisperwind.",rewardGold=257400,rewardXP=8165,starts={{npcID=168929}},ends={{npcID=174834}},coords={x=0.3,y=0.364,source="quest_giver",zoneID=11400},questType="standard"},
[60531] = {id=60531,name="Chosen Champions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={174110},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="House of the Chosen disrupted"},{orderIndex=1,type=0,amount=13,objectID=172401,text="T4 Credit"},{orderIndex=2,type=0,amount=25,objectID=170969,text="T3 Credit"},{orderIndex=3,type=0,amount=50,objectID=164886,text="T2 Credit"},{orderIndex=4,type=0,amount=100,objectID=172398,text="T1 Credit"},{orderIndex=5,type=2,amount=50,objectID=355937,text="Barrel"},{orderIndex=6,type=2,amount=50,objectID=355938,text="Potion"},{orderIndex=7,type=2,amount=50,objectID=355939,text="Armor"},{orderIndex=8,type=2,amount=50,objectID=355940,text="Book 1"},{orderIndex=9,type=2,amount=50,objectID=355941,text="Book 2"},{orderIndex=10,type=2,amount=50,objectID=355942,text="Book 3"}},worldTaskTitle="Chosen Champions",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60532] = {id=60532,name="Destroy the Dominant",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={174110},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Dominance Keep disrupted"},{orderIndex=1,type=0,amount=13,objectID=159441,text="T4"},{orderIndex=2,type=0,amount=25,objectID=158978,text="T3"},{orderIndex=3,type=0,amount=50,objectID=159114,text="T2"},{orderIndex=4,type=0,amount=100,objectID=159495,text="T1"},{orderIndex=5,type=2,amount=50,objectID=356560,text="Barrel"},{orderIndex=6,type=2,amount=50,objectID=356561,text="Lantern 1"},{orderIndex=7,type=2,amount=50,objectID=356562,text="Lantern 2"},{orderIndex=8,type=2,amount=50,objectID=356563,text="Rose"}},worldTaskTitle="Destroy the Dominant",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60533] = {id=60533,name="Terrors in Tirna Scithe",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Tirna Scithe cleansed"},{orderIndex=1,type=0,amount=10,objectID=172082,text="T4 Credit"},{orderIndex=2,type=0,amount=17,objectID=163991,text="T3 Credit"},{orderIndex=3,type=0,amount=34,objectID=166499,text="T2 Credit"},{orderIndex=4,type=0,amount=100,objectID=163987,text="T1 Credit"},{orderIndex=5,type=2,amount=50,objectID=355796,text="Gorm Sac"},{orderIndex=6,type=2,amount=50,objectID=355795,text="Mushroom - Int"},{orderIndex=7,type=2,amount=50,objectID=355803,text="Mushroom - Agi"},{orderIndex=8,type=2,amount=50,objectID=355804,text="Mushroom - Str"},{orderIndex=9,type=2,amount=50,objectID=355805,text="Mushroom - Cleanse"},{orderIndex=10,type=2,amount=50,objectID=355797,text="Barrel"}},worldTaskTitle="Terrors in Tirna Scithe",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60534] = {id=60534,name="Disloyal Denizens",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Citadel of Loyalty disrupted"},{orderIndex=1,type=0,amount=13,objectID=156815,text="T4 Credit"},{orderIndex=2,type=0,amount=25,objectID=156561,text="T3 Credit"},{orderIndex=3,type=0,amount=50,objectID=157754,text="T2 Credit"},{orderIndex=4,type=0,amount=50,objectID=156571,text="Glimmerfly"},{orderIndex=5,type=2,amount=50,objectID=334206,text="Weapon Rack"},{orderIndex=6,type=2,amount=50,objectID=355379,text="Proclamation - Zeal"},{orderIndex=7,type=2,amount=50,objectID=355380,text="Proclamation - Pride"},{orderIndex=8,type=2,amount=50,objectID=355382,text="Proclamation - Fury"},{orderIndex=9,type=2,amount=50,objectID=355381,text="Proclamation - Ambition"},{orderIndex=10,type=2,amount=50,objectID=355375,text="Barrel"}},worldTaskTitle="Disloyal Denizens",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[60545] = {id=60545,name="Shadowlands: A Chilling Summons",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1637,mapID=84,description="The time has come, . Highlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Stormwind, and I will take you to him. I would not keep him waiting.",objectivesText="Meet Darion Mograine outside Stormwind Keep.",rewardGold=23400,rewardXP=850,starts={{npcID=176554}},ends={{npcID=176554}},coords={x=0.764,y=0.428,source="quest_giver",zoneID=1519},questType="standard"},
[60557] = {id=60557,name="First Time? You Have to Fight!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="When it comes to warfare, strength of will is as critical as strength of arms. A demoralized soldier is a defeated soldier! We have the numbers to overwhelm the constructs with a full scale assault, but only if our forces are fully committed to the charge. Some may fall, but their sacrifice will secure our victory! Take this battle horn and rally our troops. Remind them of their duty to the Chosen!",objectivesText="Rally 8 demoralized soldiers . Progress: Have you rallied the troops?",rewardGold=257400,rewardXP=1415,rewardItems={179923},starts={{npcID=159894}},ends={{npcID=169226},{npcID=169359}},coords={x=0.392,y=0.558,source="quest_giver",zoneID=11462},questType="standard"},
[60563] = {id=60563,name="Tending to Wildseeds",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We infuse wildseeds with anima from the animacones we collect in the surrounding area. But the caretakers are missing, and we have wildseeds in need of an anima infusion. This is an absolute mess that must be corrected before the Winter Queen arrives! I've already gathered a basket of animacones . Can you use them to infuse a few of the wildseeds ? I'll show you how it's done, but then I have to look for the missing caretakers.",objectivesText="Collect basket of animacones , then use them on 4 wildseeds .",rewardGold=257400,rewardXP=1415,rewardItems={179389},starts={{npcID=169116}},ends={{npcID=169202}},coords={x=0.642,y=0.412,source="quest_giver",zoneID=11510},questType="standard"},
[60564] = {id=60564,name="Three Gorm Enter, No One Leaves",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",worldTaskTitle="Three Gorm Enter, No One Leaves",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60565] = {id=60565,name="A Steward for Every Occasion",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=169077,text="First chore completed"},{orderIndex=0,type=0,amount=5,objectID=169085,text="Chores done"},{orderIndex=2,type=0,amount=1,objectID=169082,text="Second chore completed"},{orderIndex=3,type=0,amount=1,objectID=169081,text="Third chore completed"},{orderIndex=4,type=0,amount=1,objectID=169080,text="Fourth chore completed"},{orderIndex=5,type=0,amount=1,objectID=169079,text="Fifth chore completed"},{orderIndex=6,type=0,amount=1,objectID=169078,text="Sixth chore completed"}},worldTaskTitle="A Steward for Every Occasion",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60566] = {id=60566,name="Into the Light",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I am afraid that you must endure the next stretch of the stroll without me, $p. While my compatriots and I have secured access to the elevator that shall carry us up to Sinfall, we are unable to utilize it. The Master has redirected a massive beam of Light directly onto the elevator's landing. Venthyr that get close are obliterated. Dredgers sent up never return. We need someone who can walk in the Light to discover what is happening up there. Lady Sybille will show you the way.",rewardGold=25740,rewardXP=175,starts={{npcID=158694}},ends={{npcID=169105}},coords={x=0.32,y=0.476,source="quest_giver",mapID=1525},questType="standard"},
[60567] = {id=60567,name="Shooing Wildlife",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Things are chaotic here in the Tranquil Pools. I'd be devastated if the Winter Queen saw this. This is meant to be a peaceful place where we give anima to wildseeds. But with the current drought, starving beasts have encroached on the pools and are trying to feed on the anima themselves. Sadly, we need to put them down... or else they may endanger the spirits within the wildseeds.",objectivesText="Slay 8 Anima-Starved wildlife. Progress: I hate having to do this, but if it's a choice between sparing the beasts and saving the wildseeds, I have to choose the wildseeds.",rewardGold=257400,rewardXP=1415,starts={{npcID=169116}},ends={{npcID=169202}},coords={x=0.642,y=0.412,source="quest_giver",zoneID=11510},questType="standard"},
[60568] = {id=60568,name="TEMP MAW RUN",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,questType="standard"},
[60572] = {id=60572,name="For the Sake of Spirit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="With all of the anima you recovered from Tirna Noch, it is only a matter of time before my grove becomes the target of every anima-seeking enemy of Ardenweald . I hope Dreamweaver knows what he is doing with this ritual. Proceed quickly. Speak with Dreamweaver , and see what needs to be done to aid the spirit within the wildseed.",objectivesText="Speak with Dreamweaver to prepare the ritual.",rewardGold=25270,rewardXP=175,starts={{npcID=160894}},ends={{npcID=160962}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[60573] = {id=60573,name="Meatball's Revenge",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[60574] = {id=60574,name="Shaking 'Shrooms",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=157753,text="Swollen Mushroom Stalks shaken"},{orderIndex=1,type=0,amount=16,objectID=157721,text="Invading fae slain"}},worldTaskTitle="Shaking 'Shrooms",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60575] = {id=60575,name="Belly Full of Fae",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The local flora have gone somewhat wild during this anima drought. It seems they swallowed most of the young fae who were tending to the wildseeds here. At least now we know where they've been. Oh, don't worry. This isn't the first time this has happened. We can last quite a while inside those plants. Take my dagger. Use it to cut through the shrubbery and free the other wildseed tenders .",objectivesText="Free 16 Wildseed Tenders from inside Devouring Hydra. Progress: How goes the gardening?",rewardGold=257400,rewardXP=1415,rewardItems={175671,175672,175673,175674,179921},rewardChoices={175673,175671,175672,175674},starts={{npcID=169202}},ends={{npcID=169217}},coords={x=0.614,y=0.41,source="quest_giver",zoneID=11510},questType="standard"},
[60577] = {id=60577,name="Hungry for Animacones",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I have to apologize for the state of the Tranquil Pools. Normally, it's quite peaceful here. The wildseed tenders tell me that the plants you see walking around have eaten all the animacones intended for use in Tirna Vaal. Could you rip the animacones out of those plants? We have wildseeds that are in need of that anima.",objectivesText="Recover 25 Animacones from Gobbling Blossoms. Progress: Have you found the animacones ? They're still useful, even if they're a little slimy. Trust me, the spirits don't mind as long as they get their anima.",rewardGold=248040,rewardXP=1415,rewardItems={179922},starts={{npcID=169202}},ends={{npcID=169217}},coords={x=0.614,y=0.41,source="quest_giver",zoneID=11510},questType="standard"},
[60578] = {id=60578,name="Visions of the Dreamer: The Betrayal",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I sense that in the spirit's vision, she struggles with the memory of a betrayal that is truly profound. Someone as close to her as a brother, turned to an enemy. Go to the second Dreamshrine in the Basin, and help vanquish the pain of this nightmare.",objectivesText="Grapple with the Dreamer's vision of a great betrayal. If you leave the Vision, interact with a Dreamer's vision portal in Dreamshrine Basin to enter again. Progress: Have you seen what dreams have come?",rewardGold=257400,rewardXP=1415,starts={{npcID=160962}},ends={{npcID=160962}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[60585] = {id=60585,name="Spriggan Riot",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=169261,text="Blackthorn spriggans slain"},{orderIndex=1,type=0,amount=6,objectID=169260,text="Silkstrider Caretakers rescued"},{orderIndex=2,type=0,amount=25,objectID=169262,text="Silkstrider Grubbies saved"}},worldTaskTitle="Spriggan Riot",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60594] = {id=60594,name="One Special Spirit",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds. I'd love for you to come with me. It's only fair, since you're the one who recovered the animacones. I'm quite excited for you! Let's go.",objectivesText="Go with Dreamweaver to feed anima to the wildseed in Tirna Vaal. Progress: The howling wind becomes a gentle breeze. All is well once again.",rewardGold=128700,rewardXP=710,rewardItems={179978,179983},starts={{npcID=169217}},ends={{npcID=158487}},coords={x=0.622,y=0.364,source="quest_giver",zoneID=11510},questType="standard"},
[60597] = {id=60597,name="Trouble at the Gormling Corral",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=2,amount=1,objectID=352833,text="Take the Modified Gormling Lure"},{orderIndex=1,type=0,amount=8,objectID=158887,text="Deliver Gormdaughters to the wrangler"}},worldTaskTitle="Trouble at the Gormling Corral",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60600] = {id=60600,name="Preparing for the Winter Queen",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you. You have more than upheld your end of our bargain... and yet I was not able to do the same. That is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement? Please, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!",objectivesText="Receive Ardenweald 's essence from Lady Moonberry . Progress: Joy follows Lady Moonberry , a scent that lingers as a flower blooms.",rewardGold=124020,rewardXP=710,starts={{npcID=169031}},ends={{npcID=158487}},coords={x=0.636,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[60601] = {id=60601,name="Darkwing Drills",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardCurrencies={{id=1885,amount=2}},questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Training progress"},{orderIndex=0,type=0,amount=1,objectID=169422,text="Trainee chosen"}},worldTaskTitle="Darkwing Drills",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60602] = {id=60602,name="Secret Service",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Guest happiness"},{orderIndex=0,type=2,amount=1,objectID=353017,text="Servant's Basic Kit acquired"}},worldTaskTitle="Secret Service",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60605] = {id=60605,name="Glimmerfin Scale",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=3537,mapID=114,description="King Mrgl-Mrgl would know more about this new species?>",objectivesText="Show the scale to King Mrgl-Mrgl in Borean Tundra.",rewardGold=256200,rewardItems={5996},starts={{npcID=352909}},ends={{npcID=25197}},coords={x=0.185,y=0.882,source="quest_giver",zoneID=394},questType="standard"},
[60606] = {id=60606,name="Glimmerfin Welcome",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=114,description="First thing's first, they're probably hungry. Life up here in the cold isn't quite as easy as it is elsewhere, and even the most acclimated murlocs sometimes have trouble finding food. We're going to need to feed them, but also help them find food for themselves. They're already watching you, so search the area around where you found the murlocs for food sources and show them what to hunt. Then bring the meat to their leader--just look for the biggest one.",objectivesText="Collect 10 Meaty Crab Chunks and deliver them to Glimmergut in Venture Bay. Progress: Mrgg?",rewardGold=341600,rewardItems={180010},starts={{npcID=25197}},ends={{npcID=169414}},coords={x=0.434,y=0.138,source="quest_giver",zoneID=3537},questType="standard"},
[60609] = {id=60609,name="Who Devours the Devourers?",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=169444,text="Devourer Rifts closed"},{orderIndex=1,type=0,amount=1,objectID=175539,text="Resonating Anima Core created from motes"}},worldTaskTitle="Who Devours the Devourers?",db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[60614] = {id=60614,name="A Big Horkin' Task",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=116,description="Glimmergut begins to draw in the sand. The murloc traces the outline of what appears to be a large seal. He points at the picture, then upwards, indicating that the creature must be somewhere on the surface of the water. The murloc then digs a small, shallow hole in the sand, and points at it several times.> Mrg! Mrg! Grml.",objectivesText="Collect one Pile of Blubberfat and deliver it to Glimmergut in Venture Bay. Progress: Grmgr?",rewardGold=341600,rewardItems={180025},starts={{npcID=169414}},ends={{npcID=169414}},coords={x=0.178,y=0.932,source="quest_giver",zoneID=394},questType="standard"},
[60615] = {id=60615,name="Seer of the Waves",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=116,description="Glimmergut points across the ship. He wants you to take the blubber to someone.> Mrg m'grrl.",objectivesText="Deliver the Blubberfat to the Glimmerfin Oracle .",rewardGold=34100,starts={{npcID=169414}},ends={{npcID=169415}},coords={x=0.178,y=0.932,source="quest_giver",zoneID=394},questType="standard"},
[60616] = {id=60616,name="Pearl in the Deeps",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=116,description="<The oracle draws a circle in the sand, then points down into the deeps. There is something round down there that she is after, perhaps a pearl or stone? The oracle motions for you to wait a moment before you leave. She waves her hands around frantically, then places them under her mouth, mimicking two large fangs. You take this as a warning that there may be something waiting for you in the icy darkness.>",objectivesText="Collect the Giant Pearl and deliver it to the Glimmerfin Oracle . Progress: <The oracle looks at you.>",rewardGold=232300,rewardItems={180026},starts={{npcID=169415}},ends={{npcID=169415}},coords={x=0.17,y=0.938,source="quest_giver",zoneID=394},questType="standard"},
[60619] = {id=60619,name="Wrap it Up",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=116,description="<The seems quite excited about the presence of the new egg. You get the sense that this is an important occasion for these murlocs--there may be few eggs left. The oracle waves a small piece of seaweed in front of you, showing you the young buds of the immature plant. She warps the seaweed around a small part of the egg, then points at you, then back at the wrapped seaweed. It appears that the egg needs to be wrapped in more immature seaweed stalks.>",objectivesText="Collect a Warm Seaweed Stalk , a Young Seaweed Stalk , and a Bulbous Seaweed Stalk and deliver them to the Glimmerfin Oracle . Progress: <The oracle blinks at you.>",rewardGold=341600,rewardItems={180031,180032,180033},starts={{npcID=169415}},ends={{npcID=169415}},coords={x=0.17,y=0.938,source="quest_giver",zoneID=394},questType="standard"},
[60620] = {id=60620,name="Guardian of the Smallest",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=394,mapID=116,description="<The oracle pats you on the shoulder, and seems quite pleased with all that you've done. She holds up one finger, then spreads her hands wide and emits a terrible roar-like murgle. She points outside, then at you, then your weapon, then nods seriously. There must be one more trial to await you. It would appear to be a test of strength.>",objectivesText="Slay Great Mua'kin and return to the Glimmerfin Oracle . Progress: <The oracle claps excitedly.>",rewardGold=683200,rewardItems={180034},starts={{npcID=169415}},ends={{npcID=169415}},coords={x=0.17,y=0.938,source="quest_giver",zoneID=394},questType="group"},
[60621] = {id=60621,name="Enemies at the Gates",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Lorkron is here. I tracked him all the way from the Glittering Falls. Then I saw the Drust try to flank our forces. I'd say they were rather surprised that we turned the tables against them. Huntsmen and huntresses, with me! We ride to defend the grove! Take no prisoners and leave none standing!",objectivesText="Reach Droman Aliothe in Hibernal Hollow.",rewardGold=25270,rewardXP=175,starts={{npcID=162541}},ends={{npcID=169541}},coords={x=0.56,y=0.576,source="quest_giver",zoneID=11510},questType="standard"},
[60622] = {id=60622,name="Eye of the Scryer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Evading the Mawsworn's scryers requires powerful magical countermeasures. The prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance. The scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye. Restraint is advised in its procurement.",rewardItems={180035},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Eye of the Scryer"},
[60623] = {id=60623,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Repel the Devourer threat"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60624] = {id=60624,name="Ride to Heartwood Grove",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="A storm of strife and fear rains down upon Heartwood Grove. Sylvar flee from the flood. Brave the torrent astride a stag. Becalm the deluge and be the salvation of those who would drown. Make haste. Time wanes.",objectivesText="Ride a stag to Heartwood Grove.",rewardGold=124020,rewardXP=710,starts={{npcID=158487}},ends={{npcID=169686}},coords={x=0.634,y=0.362,source="quest_giver",zoneID=11510},questType="standard"},
[60628] = {id=60628,name="The Missing Hunters",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Strange creatures have been seen lurking just outside the grove. Terrible, ugly things. Whatever they might be, they are not native to Ardenweald . It does not matter how they breached our borders, though. Every one of them must be eliminated. I sent my best huntsmen and huntresses to slay them, but not one has returned. See if you can determine what has delayed them.",objectivesText="Find Jynkla , Serinkai , Rondar , and Ara'lon .",rewardGold=257400,rewardXP=1415,starts={{npcID=169584}},ends={{npcID=169584}},coords={x=0.512,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[60629] = {id=60629,name="Extreme Recycling",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Wild Hunt serves the Winter Queen under the leadership of Lord Herne. We are elite fighters, hunters, and trackers. But we cannot fight without weapons and supplies. The droman here informs me that there are severe obstacles to their delivery. I do not have time to wait. We need equipment, and we need it now. See what you can scavenge from the field. A broken weapon can always be mended and put to use again.",objectivesText="Slay the Blighted and take their weapons. Progress: Did you find anything of use out there?",rewardGold=248040,rewardXP=1415,rewardItems={180061},starts={{npcID=169584}},ends={{npcID=169584}},coords={x=0.512,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[60630] = {id=60630,name="Totem Eclipse",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I can smell our foes' dark magic, twisting the air and muddling my mind. They are up to something. Bringing awful powers into Ardenweald . If you see any of their totems, destroy them immediately. I always feel better after smashing something to pieces, don't you?",objectivesText="Destroy Foul Totems . Progress: What terrible magic has been brought into Ardenweald ?",rewardGold=257400,rewardXP=1415,starts={{npcID=169584}},ends={{npcID=169584}},coords={x=0.512,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[60631] = {id=60631,name="Big Problem, Little Vorkai",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ara'lon's report matches what I have seen. Too many enemies, and too few of the Wild Hunt to dispose of them on our own. Fortunately, I feel strongly inclined to take matters into my own hands. And avenge my fallen hunters. Let us depart. We will show those monsters the fury of nature.",objectivesText="Slay Blighted with Korayn. Progress: Ardenweald will endure.",rewardGold=248040,rewardXP=1415,starts={{npcID=169584}},ends={{npcID=169584}},coords={x=0.512,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[60632] = {id=60632,name="I Know Your Face",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This voice... I have heard it before. Though it is distorted and vengeful now. He hunts us. But I am not prey. And I will not let him gloat over his slain quarry. That is not the way of the Wild Hunt. Though he may draw us to ground of his choosing, we will fight him. And we will win. Are you with me?",objectivesText="Defeat Lorkron the Hunter .",rewardGold=514800,rewardXP=1770,rewardItems={175667,175668,175669,175670},rewardChoices={175670,175668,175669,175667},starts={{npcID=169772}},ends={{npcID=169935}},questType="standard"},
[60637] = {id=60637,name="The End of Former Friends",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Heartwood Grove was to give up its anima so that other groves could survive. But then... I started seeing these masks on many of the other fae. Soon, everyone was wearing them. I don't know what has come over them, but it's clear they mean us harm. Please... you have to... They aren't the friends I once knew. Not anymore.",objectivesText="Slay 8 possessed creatures in Heartwood Grove.",rewardGold=248040,rewardXP=1415,starts={{npcID=169686}},ends={{npcID=169748}},coords={x=0.668,y=0.266,source="quest_giver",zoneID=11510},questType="standard"},
[60638] = {id=60638,name="Recovering Wildseeds",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="One of my tasks in Heartwood Grove was to tend to the wildseeds. Some were chosen to be brought back to Tirna Vaal. But now the masked fae are draining the anima from them! We need to save the ones that remain. I beg of you, recover any surviving wildseeds you can find. The spirits within them were chosen to be reborn. I won't let them wither away!",objectivesText="Recover 6 Drained wildseeds in the Heartwood Grove. Progress: We need to split up and rescue as many wildseeds as we can.",rewardGold=248040,rewardXP=1415,rewardItems={180126},starts={{npcID=169686}},ends={{npcID=169748}},coords={x=0.668,y=0.266,source="quest_giver",zoneID=11510},questType="standard"},
[60639] = {id=60639,name="Heart of the Grove",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We were supposed to take the heart of the grove to Tirna Vaal when we left this place to wither. The masked fae struck before that could happen. They must be after the heart of the grove! The heart contains all of the anima that was meant to save the other groves. We can't afford to lose it. Can you secure it? I need to find Korenth , one of our healers. His skills will help any survivors we find.",objectivesText="Bring the Heart of the Grove to Tirna Vaal. Progress: Do you have the heart of the grove?",rewardGold=128700,rewardXP=710,starts={{npcID=169686}},ends={{npcID=169748}},coords={x=0.668,y=0.266,source="quest_giver",zoneID=11510},questType="standard"},
[60640] = {id=60640,name="Regrowth of the Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="The grove thrives, my mortal friend, but there is yet room for it to grow. With enough anima, it can nourish even more wildseeds at once. Each one is a spirit that might otherwise be lost forever. Speak with Zayhad once again, and see to the regrowth of the conservatory.",objectivesText="Upgrade the Queen's Conservatory to Tier Three.",rewardGold=257400,rewardXP=8165,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[60641] = {id=60641,name="Blossoming of the Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="The conservatory grows hearty and hale. Now, it must blossom anew. Though it requires much in the way of anima, every additional spirit that the conservatory rebirths returns your generosity tenfold. Confer with Zayhad, so that this conservatory may grow ever larger.",objectivesText="Upgrade the Queen's Conservatory to Tier Four",rewardGold=257400,rewardXP=8165,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[60642] = {id=60642,name="The Grove Resplendent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="You have done much to return the conservatory to its former splendor. In ages past, this grove was a place of convalescence for spirits who were wounded upon their demise, and needed special care before being reborn. It was a place rarely used... but now, it is critical to the continuation of the cycle. Tell Zayhad that the time has come. The Queen's Conservatory must thrive for the good of Ardenweald.",objectivesText="Upgrade the Queen's Conservatory to Tier Five",rewardGold=257400,rewardXP=8165,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[60643] = {id=60643,name="[OLD NOT USED]",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,description=".",rewardGold=257400,rewardXP=6815,questType="standard"},
[60644] = {id=60644,name="Draw Out the Darkness",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11400,mapID=1543,description="Now that we have the dagger, it will take the combined will of all of us to sever the weapon's link to the High Chieftain. Jaina, Anduin, and I must do our part to keep Baine's spirit grounded, so it will be up to you to deal with whatever force is unleashed when the blade is broken. Are you up to the task?",objectivesText="Draw out and defeat the Withering Presence in Detrithos.",rewardGold=234000,rewardXP=6815,starts={{npcID=167827}},ends={{npcID=168162}},questType="standard"},
[60645] = {id=60645,name="Gargantuan Seeker",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13332,questType="standard"},
[60646] = {id=60646,name="Misery Business",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls. Why? I do not know yet. But it behooves us to stop them. Destroy the conduits that they deposit the misery into and bring me some samples of their work. Perhaps with some research, I can discern their intentions.",rewardItems={180129,184614},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Misery Business"},
[60647] = {id=60647,name="Recovering the Animacones",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The grove's droman is wearing one of the masks. I fear he's going to drain all of the anima from the grove's heart! That anima is meant for the forest's other groves. If we lose it... then Heartwood Grove would have been lost for nothing... We'll carve a path to the Shrouded Mire to find the droman before it's too late. Many of these masked fae have stolen Heartwood Grove's animacones . We must recover them along the way. In this drought, every bit of anima is precious.",objectivesText="Recover 25 animacones from the Possessed. Progress: We can't let the possessed take anything else from us.",rewardGold=257400,rewardXP=1415,rewardItems={180172},starts={{npcID=169748}},ends={{npcID=169748}},coords={x=0.684,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[60648] = {id=60648,name="Survivors of Heartwood Grove",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Korenth... I can't believe he's... We have to save whomever we can. Droman Krelnor is too strong for us to face alone. I saw a few other survivors scattered around the grove. Hurry, we have no time to waste!",objectivesText="Rescue Casad, Wagonmaster Derawyn , and Te'zan from the possessed. Progress: We must rescue my friends!",rewardGold=248040,rewardXP=1415,starts={{npcID=169748}},ends={{npcID=169748}},coords={x=0.684,y=0.244,source="quest_giver",zoneID=11510},questType="standard"},
[60649] = {id=60649,name="A Thorn In Their Side",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt the Drust's efforts"}},worldTaskTitle="A Thorn In Their Side",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60651] = {id=60651,name="Champion: Meatball",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[60653] = {id=60653,name="Mirror Restoration",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={175384},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=169879,text="Broken Mirror restored"},{orderIndex=3,type=0,amount=1,objectID=169880,text="Shrouded Assailant slain"},{orderIndex=2,type=0,amount=1,objectID=169883,text="Ornate Mirror entered"}},worldTaskTitle="Mirror Restoration",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
