[60655] = {id=60655,name="A Stolen Stone Fiend",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={180249,180270,183859},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=170075,text="Missing Stone Fiend found"},{orderIndex=1,type=0,amount=1,objectID=170076,text="Missing Stone Fiend found"},{orderIndex=2,type=0,amount=1,objectID=170077,text="Missing Stone Fiend found"},{orderIndex=3,type=19,amount=0,objectID=20643,text="Missing Stone Fiend found"},{orderIndex=4,type=0,amount=1,objectID=170079,text="Missing Stone Fiend rescued"}},worldTaskTitle="A Stolen Stone Fiend",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60656] = {id=60656,name="Summon Your Sins",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={180298,180299,180300,180301,180302,180303,180304,180305,180306,180357,180358,180359,180360,180361,180362,180363,180364,180365,180366,180367,180368,180369,180370,180371,180372,180373,180374,180376},questType="world",db2Objectives={{orderIndex=5,type=14,amount=1,objectID=85599,text="Sinstone Fragments collected"},{orderIndex=1,type=1,amount=20,objectID=180281,text="Tier"},{orderIndex=2,type=1,amount=20,objectID=180282,text="Time"},{orderIndex=0,type=1,amount=20,objectID=180283,text="Rare"},{orderIndex=3,type=1,amount=20,objectID=180284,text="Pet"},{orderIndex=6,type=0,amount=1,objectID=170277,text="Catalyst chosen"},{orderIndex=10,type=0,amount=1,objectID=170278,text="Amalgamation created"},{orderIndex=7,type=0,amount=1,objectID=170372,text="Might"},{orderIndex=8,type=0,amount=1,objectID=170373,text="Renewal"},{orderIndex=9,type=0,amount=1,objectID=170374,text="Power"}},worldTaskTitle="Summon Your Sins",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
