[60658] = {id=60658,name="An Endless Appetite",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=172484,text="Speak to Morgan"},{orderIndex=2,type=15,amount=1,objectID=0,text="Enemies devoured"}},worldTaskTitle="An Endless Appetite",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60659] = {id=60659,name="Light Defense",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=171352,text="Mirror secured"},{orderIndex=1,type=15,amount=1,objectID=0,text="Enemies slain"}},worldTaskTitle="Light Defense",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60661] = {id=60661,name="Dying Dreams",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="We have lost so much... and this one is special. Come, . We will carry her on the Path of Rebirth and entreat the Queen to save her. Hurry and make preparations. We have little time.",objectivesText="Take Ysera's wildseed to the Heart of the Forest.",rewardGold=126360,rewardXP=710,starts={{npcID=161847}},ends={{npcID=169869}},coords={x=0.6,y=0.53,source="quest_giver",zoneID=11510},questType="standard"},
[60669] = {id=60669,name="Cause for Distraction",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=85,description="The Horde has come under siege, $p. The undead Scourge rises like a grim tide, in numbers not seen since Arthas Menethil sat upon the frozen throne. And as if that were not concerning enough... something terrible has occurred. What I am about to tell you, I share in the strictest confidence. This information will be known by all soon enough, but I needed to speak with you directly first. Allow me to explain.",objectivesText="Speak with Lor'themar Theron atop Grommash Hold in Orgrimmar. Progress: There is much to discuss.",rewardGold=25740,rewardXP=850,starts={{npcID=169928}},ends={{npcID=169928}},coords={x=0.49,y=0.736,source="quest_giver",zoneID=1637},questType="standard"},
[60670] = {id=60670,name="Return of the Crusade",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=85,description="I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. The fate that befell Silvermoon must never be repeated. Death knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements. The Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, . Their commander awaits your arrival.",objectivesText="Speak with Commander Throgg in the Valley of Strength in Orgrimmar.",rewardGold=25740,rewardXP=850,starts={{npcID=169928}},ends={{npcID=169878}},coords={x=0.49,y=0.736,source="quest_giver",zoneID=1637},questType="standard"},
[60671] = {id=60671,name="The Sacrifices We Must Make",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Hurry! We can use the animacones we gathered to save Derawyn. I know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.",objectivesText="Use the recovered animacones to save Wagonmaster Derawyn .",rewardGold=128700,rewardXP=710,starts={{npcID=169868}},ends={{npcID=169985}},questType="standard"},
[60673] = {id=60673,name="The Traitor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Right, looks like I should let you in now. Can't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that. Wonder what happened to her. Denathrius seemed awfully upset when they last spoke. Anyways, let me just get that door open for ya.",objectivesText="Kill Sinkeeper Mateo and collect his mirror shard. Progress: Do you have Mateo's mirror shard ?",rewardGold=514800,rewardXP=10205,rewardItems={174092,180900,180913,180914,180915},starts={{npcID=161298}},ends={{npcID=160941}},coords={x=0.774,y=0.392,source="quest_giver",zoneID=10413},questType="standard"},
[60709] = {id=60709,name="Recovering the Heart",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove. Anima drains from the heart, nectar taken from ripened fruit. It must be stopped. Foul magic bars the way. Anima in peril, anima the salvation. Beseech Te'zan . An old soul, brimming with anima, the spark to ignite our hope.",objectivesText="Speak with Te'zan to break down the droman's barrier, then confront Droman Krelnor.",rewardGold=248040,rewardXP=1415,starts={{npcID=169956}},ends={{npcID=170012}},coords={x=0.662,y=0.236,source="quest_giver",zoneID=11510},questType="standard"},
[60721] = {id=60721,name="The Anima Must Flow",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="This device you see here can be used to send anima to the thirsting wards, aiding our people. As each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.",objectivesText="Use the Anima Conductor to channel anima to a location in Revendreth.",rewardGold=128700,rewardXP=4085,starts={{npcID=164739}},ends={{npcID=164739}},questType="standard"},
[60722] = {id=60722,name="Tower Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them. Though you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes. Use the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.",objectivesText="Use the Anima Conductor to channel anima to a location in Maldraxxus. Progress: The anima must flow!",rewardGold=128700,rewardXP=4085,starts={{npcID=167205}},ends={{npcID=167205}},coords={x=0.492,y=0.362,source="quest_giver",zoneID=12876},questType="standard"},
[60723] = {id=60723,name="The Roots Thirst",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="This device can soak the roots of our great canopy in anima. The branches thirst for it. As each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade. Now, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.",objectivesText="Use the Anima Conductor to channel anima to a location in Ardenweald. Progress: The leaves shake in anticipation.",rewardGold=162600,rewardXP=4085,starts={{npcID=167196}},ends={{npcID=167196}},questType="standard"},
[60724] = {id=60724,name="Heartless",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="So many of my friends have returned to the cycle... all because of those strange masks. Why did they take my friends? What was the point of destroying the heart of my grove? You have to return to Tirna Vaal and tell Droman Tashmur what happened here. I'll make my way there eventually. I just... need some time to say goodbye.",objectivesText="Return to Droman Tashmur in Tirna Vaal.",rewardGold=24805,rewardXP=175,rewardItems={175648,175649,175650,175651},rewardChoices={175650,175649,175648,175651},starts={{npcID=170012}},ends={{npcID=158487}},coords={x=0.654,y=0.266,source="quest_giver",zoneID=11510},questType="standard"},
[60725] = {id=60725,name="Field Reports",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=17,mapID=85,description="We cannot anticipate where and when the Scourge will strike. In order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them. Seek out my field officers along the southern road. I expect a full report when you return.",objectivesText="Gather reports from officers in Durotar and the Barrens. Progress: Reinforcements? Thank the Light!",rewardGold=128700,rewardXP=3410,rewardItems={180231,180232,180233},starts={{npcID=169878}},ends={{npcID=170084}},coords={x=0.528,y=0.774,source="quest_giver",zoneID=1637},questType="standard"},
[60726] = {id=60726,name="[OLD NOT USED]",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,rewardGold=238680,rewardXP=6815,questType="standard"},
[60727] = {id=60727,name="A Message from Icecrown",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=210,mapID=85,description="Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance. We must respond to this summons at once, no matter what terrors await us in Icecrown. A like you would do much to bolster our chances on the battlefield. You have my word that Orgrimmar will be protected in your absence. Battle calls, . I trust you are ready.",objectivesText="Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.",rewardGold=128700,rewardXP=3410,starts={{npcID=169878}},ends={{npcID=167045}},coords={x=0.528,y=0.774,source="quest_giver",zoneID=1637},questType="standard"},
[60732] = {id=60732,name="Disrupting the Flow",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,rewardItems={177698,177699,178874,178877,178880,178881,178882,178883},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=176164,x=0.394,y=0.458,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.394,y=0.458,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Disrupting the Flow"},
[60733] = {id=60733,name="Front and Center",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The runes on that blade... they are the same as the ones etched on the door to the Seat of the Primus. And one of them just began to glow... Is this what I think it is, $p? Do you have the means to unseal the Seat? If so, then perhaps Vyraz's gambit was not for nothing. This could turn the tide of the entire war!",objectivesText="Empower the Rune of Might at the Seat of the Primus. Progress: Come! Victory awaits!",rewardGold=128700,rewardXP=710,starts={{npcID=170094}},ends={{npcID=168381}},coords={x=0.376,y=0.29,source="quest_giver",zoneID=11462},questType="standard"},
[60735] = {id=60735,name="Trouble in Paradise",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have given your presence here some thought, . It is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented. You must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence. So... I ask you... why are you here, truly?",objectivesText="Answer Kleia 's question. Progress: < Kalisthene peers down at you.> What is it, mortal?",rewardGold=118170,rewardXP=710,starts={{npcID=165107}},ends={{npcID=166306}},coords={x=0.482,y=0.726,source="quest_giver",zoneID=10534},questType="standard"},
[60736] = {id=60736,name="Quest 02",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Open the door to the Seat of the Primus.",rewardGold=25740,rewardXP=175,questType="standard"},
[60737] = {id=60737,name="The Door to the Unknown",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=12876,mapID=1536,description="You empowered the final rune? Then we might yet turn the tide of battle! Open the door, ! We'll hold the enemy back as long as we can!",objectivesText="Open the door to the Seat of the Primus.",rewardGold=378480,rewardXP=1770,starts={{npcID=170309}},ends={{npcID=353420}},coords={x=0.504,y=0.678,source="quest_giver",zoneID=11462},questType="standard"},
[60738] = {id=60738,name="The Way to Hibernal Hollow",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this. Then again, we've also never had a living mortal in our midst. We need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs. I'll place it into the spirit cradle. Can you ask Niya if she would accompany you? The poor sylvar has been directionless since the fall of her grove. This would be good for her.",objectivesText="Recruit Niya to help you bring the wildseed to Hibernal Hollow.",rewardGold=128700,rewardXP=710,starts={{npcID=169142}},ends={{npcID=170171}},questType="standard"},
[60739] = {id=60739,name="Tough Crowd",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",worldTaskTitle="Tough Crowd",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60759] = {id=60759,name="Damned Intruders",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=17,mapID=10,description="It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads. Before you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.",objectivesText="Kill 6 Cultists and 4 Bloodthirsty Ghouls at the Crossroads. Progress: In troubled times, the Light guides our path.",starts={{npcID=170084}},ends={{npcID=170084}},questType="standard"},
[60761] = {id=60761,name="Return of the Scourge",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=10,description="Deliver these reports to Commander Throgg . He must be told of the full extent of the threat we face. If we fail to hold the line against the Scourge... then Light help us all.",objectivesText="Bring Lieutenant Althera 's report to Commander Throgg in the Valley of Strength in Orgrimmar. Provided item:",rewardGold=128700,rewardXP=3410,rewardItems={180269},starts={{npcID=170084}},ends={{npcID=169878}},coords={x=0.494,y=0.592,source="quest_giver",zoneID=17},questType="standard"},
[60762] = {id=60762,name="Death Motes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have a task for you, Maw Walker. Souls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will. It is a tragic end. I wish to better understand this process--what is it about a soul that causes this transformation? Fragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.",rewardItems={177698,178874,178880,178881,178882,178883,185717},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Death Motes"},
[60763] = {id=60763,name="I Moustache You to Lend a Hand",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time. This isn't a prank, is it? The Queen doesn't have time for pranks. But I do! And for this one, I think we need one more lily. Let me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.",objectivesText="Assist Moonberry and Featherlight.",rewardGold=122850,rewardXP=710,rewardItems={178747},starts={{npcID=168341}},ends={{npcID=157788}},coords={x=0.682,y=0.184,source="quest_giver",zoneID=11510},questType="standard"},
[60764] = {id=60764,name="Soothing Song",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive. This wildseed seems to take comfort in your presence, so you'll need to stick close to it. Niya will also need to sing to the wildseed to keep it calm... or else the nightmares may return. Spriggans love to interrupt our songs, so be on the lookout for them. Let me know when you're ready to head off.",objectivesText="Travel with Niya to take the wildseed to Hibernal Hollow. Progress: How strange that such a small wildseed could cause so much trouble...",rewardGold=250380,rewardXP=1415,starts={{npcID=170172}},ends={{npcID=170290}},coords={x=0.646,y=0.39,source="quest_giver",zoneID=11510},questType="standard"},
[60765] = {id=60765,name="Cure For All Ills",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness. Maw Walker, I'd do anything to help them. Even saving a few is better than saving none. Please, help me cure them!",objectivesText="Use Roseboil 's Regenerative Molt to cure 15 Plague-ridden Survivors .",rewardXP=8165,rewardItems={183744,182487,182496,182505,182514,184843},starts={{npcID=158259},{npcID=159241}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[60766] = {id=60766,name="Damned Intruders",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10,mapID=47,description="Before you depart... we are in desperate need of reinforcements. These reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.",objectivesText="Kill 12 Scourge in the area. Progress: In troubled times, the Light guides our path.",starts={{npcID=166184}},ends={{npcID=166184}},questType="standard"},
[60767] = {id=60767,name="Return of the Scourge",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=47,description="Deliver my report to Commander Gregor . He must be informed of what we are up against. The Scourge's numbers are on the rise, and if they do not abate... then the Light help us all.",objectivesText="Bring Lieutenant Vernon 's report to Commander Gregor in the Trade District of Stormwind City. Provided item:",rewardGold=128700,rewardXP=3410,rewardItems={178170},starts={{npcID=166184}},ends={{npcID=166383}},coords={x=0.736,y=0.472,source="quest_giver",zoneID=10},questType="standard"},
[60770] = {id=60770,name="Squish and Burn",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={180274},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=170239,text="Gorm eggs burned"},{orderIndex=1,type=0,amount=50,objectID=170240,text="Larvae squished"}},worldTaskTitle="Squish and Burn",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60775] = {id=60775,name="A Suitable Demise",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy. The soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain. This of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.",rewardItems={180280},rewardCurrencies={{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Suitable Demise"},
[60778] = {id=60778,name="Wildseed Rescue",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Featherlight checks his notes.> Let's see... There was a request for help regarding an imperiled wildseed and... something about an egg? The original note wasn't entirely clear, but the fae who sent it was... Ah! It was Korenth . Again. Well, I suppose we'll find out what his trouble is soon enough! I'll fly ahead and look for him. Stick to the path.",objectivesText="Help Korenth recover the wildseed. Progress: You survived!",rewardGold=378480,rewardXP=1770,starts={{npcID=170175}},ends={{npcID=170324}},coords={x=0.65,y=0.194,source="quest_giver",zoneID=11510},questType="standard"},
[60785] = {id=60785,name="Party Crashers!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13329,mapID=1525,questType="standard"},
[60786] = {id=60786,name="Swarm Defense",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=170125,text="Veilwing Sentry mounted"}},worldTaskTitle="Swarm Defense",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60825] = {id=60825,name="Amateur Spies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: Your court is infested with spies, Maw Walker. Necromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down. I will dispatch any that I come across, but I would prefer to focus my attentions on the court. Bring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.",rewardItems={180296},starts={{npcID=168444}},ends={{npcID=168444}},coords={x=0.476,y=0.412,source="quest_giver",zoneID=10413},questType="standard"},
[60827] = {id=60827,name="Advancing the Effort",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="While the other crusaders regain control of the tournament grounds, you and I must press on. Our forces previously attempted to set up a forward camp farther into Icecrown, but they were overrun. With you by our side, I am confident we can reclaim the area.",objectivesText="Secure a foothold atop the Ironwall Rampart in Icecrown. Progress: There is no stopping what has begun. We must continue our efforts.",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=5}},starts={{npcID=168123}},ends={{npcID=167045}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[60828] = {id=60828,name="A New Foothold",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="Our preparations are complete. It is time we take the fight to the Scourge. Justicar Trueheart has tasked me with leading our efforts at the forward camp. Meet me there and we shall continue our work together.",objectivesText="Meet Crusader Renn at the Argent Camp atop the Ironwall Rampart in Icecrown.",rewardGold=25740,rewardXP=850,starts={{npcID=168123}},ends={{npcID=170467}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[60831] = {id=60831,name="Fit For a Margrave",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We're finally ready, my apprentice. We shall craft our greatest potion! Though what the potion is meant for escapes me, I'm simply so proud of your progress. Margrave Stradama will be thrilled by your achievements! Come, now. Let's present what we've made to her!",objectivesText="Present your potion to Margrave Stradama. Progress: Go on, apprentice!",rewardGold=477360,rewardXP=1770,rewardItems={175722,175723},rewardChoices={175722,175723},starts={{npcID=159930}},ends={{npcID=159930}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="standard"},
[60837] = {id=60837,name="Wrath of Aliothe",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Garden of Night cleansed"},{orderIndex=1,type=0,amount=25,objectID=170440,text="Spriggan slain"}},worldTaskTitle="Wrath of Aliothe",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60839] = {id=60839,name="Remnants of the Wild Hunt",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Wild Hunt is holding the line against these monsters, lest they overrun the road to Hibernal Hollow. Too many of my fellow hunters have been possessed by the dark magic of those twisted masks. But with you here, we might be able to turn the tide. Aid any hunters you can find before our foes turn them against us. I will meet you farther within the meadow. If we rally our numbers, we can bring an end to this battle.",objectivesText="Rescue 5 Wounded Defenders from Soryn's Meadow.",rewardGold=250380,rewardXP=1415,starts={{npcID=170290}},ends={{npcID=170485}},coords={x=0.624,y=0.454,source="quest_giver",zoneID=11510},questType="standard"},
[60840] = {id=60840,name="Wild Hunt Offensive",expansion=8,mapID=1565,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blighted forces disrupted"}},worldTaskTitle="Wild Hunt Offensive"},
[60842] = {id=60842,name="To Serve Spriggan",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={180439},questType="world",db2Objectives={{orderIndex=0,type=0,amount=10,objectID=170540,text="Spriggan fed to The Craw"}},worldTaskTitle="To Serve Spriggan",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60843] = {id=60843,name="Cult Couture",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="Though our scouts have been able to infiltrate the cultist forces at Aldur'thar, sneaking into Mord'rethar has proven all but impossible. Perhaps it is time to explore other methods of ingress. Start by investigating the cult's nearby ritual chambers. You may find something of use.",objectivesText="Collect a Collaborator's Hood and a Collaborator's Robe from the cultists at Aldur'thar. Progress: Find something?",rewardGold=257400,rewardXP=6815,rewardItems={181253,181254},rewardCurrencies={{id=1754,amount=1}},starts={{npcID=170467}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60844] = {id=60844,name="Flight School: Falling With Style",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Fall, with style"}},worldTaskTitle="Flight School: Falling With Style",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60855] = {id=60855,name="Gormageddon",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Dusty Burrows cleared"},{orderIndex=1,type=0,amount=20,objectID=170503,text="Gorm slain"}},worldTaskTitle="Gormageddon",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60856] = {id=60856,name="Toppling the Brute",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="A nearby monstrosity has been thwarting our efforts to clear the meadow. Together, we can bring it down. You and I will face off against the beast. When the time is right, I will call for the hunt to charge. The Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!",objectivesText="Defeat the Blighted Beast .",rewardGold=257400,rewardXP=1415,rewardItems={175983,175984,175985,175986,175987,175988,175989,175990,175992,178029},rewardChoices={175986,175983,175984,175985,175990,175987,175988,175989,175992,178029},starts={{npcID=170485}},ends={{npcID=170485}},coords={x=0.642,y=0.5,source="quest_giver",zoneID=11510},questType="standard"},
[60857] = {id=60857,name="We Can't Save Them All",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I am surprised--but pleased--that you weren't torn to pieces! Well done. But now... I fear we have a far more serious task to complete. The Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved. We are to bring the final list to Droman Krelnor .",objectivesText="Bring the list of saved wildseeds to Droman Krelnor at the Heartwood Grove. Progress: Move along, stranger.",rewardGold=19570,rewardXP=175,rewardItems={180436},starts={{npcID=170324}},ends={{npcID=168528}},coords={x=0.676,y=0.206,source="quest_giver",zoneID=11510},questType="standard"},
[60858] = {id=60858,name="Flight School: Up and Away!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=170565,text="Temple summit reached"},{orderIndex=0,type=0,amount=1,objectID=170566,text="Updraft entered"}},worldTaskTitle="Flight School: Up and Away!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60859] = {id=60859,name="Souls of the Forest",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="If you're standing in for Lady Moonberry, then maybe you can help! Wagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey! Come on! They're just down the road!",objectivesText="Rescue souls in peril. Progress: Well, that was exciting.",rewardGold=257400,rewardXP=1415,rewardItems={175652,175653,175654,175655},rewardChoices={175654,175652,175653,175655},starts={{npcID=170537}},ends={{npcID=170533}},coords={x=0.678,y=0.242,source="quest_giver",zoneID=11510},questType="standard"},
[60861] = {id=60861,name="Secrets in Shadows",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers. Take these robes. Make your way into the inner sanctum and see what you can discover. This may be our only chance to learn their intentions, .",objectivesText="Use the Collaborator's Robes in Mord'rethar to discover what secrets lie within. Progress: Find something?",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=1}},starts={{npcID=170467}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60867] = {id=60867,name="A Message from Above",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="This is troubling news, $p. Whoever this \"Banished One\" may be, it is clear he is behind the Scourge's return. That the undead are amassing in great numbers outside Icecrown Citadel cannot be a coincidence. Lead our hippogryph riders in surveying the area from above. Determine if the dark herald you saw is among them, and then clear a path for reinforcements. Let us hope she possesses the answers we seek.",objectivesText="Discover the location of Herald Dalora. Destroy the Scourge forces surrounding Icecrown Citadel. Progress: The skies over the citadel may be dangerous, but we need to know what we're up against.",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=1}},starts={{npcID=170467}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60869] = {id=60869,name="With Hope in Hand",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=118,description="You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, .",objectivesText="Establish a portal to Orgrimmar at the Argent Tournament Grounds. Deliver the news to Lor'themar Theron atop Grommash Hold in Orgrimmar.",rewardGold=257400,rewardXP=6815,starts={{npcID=170467}},ends={{npcID=169928}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60871] = {id=60871,name="With Hope in Hand",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=118,description="You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, .",objectivesText="Establish a portal to Stormwind at the Argent Tournament Grounds. Deliver the news to Genn Greymane at Lion's Rest in Stormwind City.",rewardGold=257400,rewardXP=6815,starts={{npcID=170467}},ends={{npcID=167329}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60872] = {id=60872,name="A Dangerous Harvest",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={180447},questType="world",db2Objectives={{orderIndex=0,type=1,amount=10,objectID=180447,text="Animacones collected"}},worldTaskTitle="A Dangerous Harvest",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60881] = {id=60881,name="Ride of the Wild Hunt",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Thanks to your efforts, we have turned the tide of battle. We won't soon forget your aid. We should be able to hold Soryn's Meadow, now that this brute is dead. Ride with us, . Let us return to the road and your wildseed.",objectivesText="Ride with the Wild Hunt to Niya and the wildseed.",rewardGold=128700,rewardXP=710,starts={{npcID=170485}},ends={{npcID=170290}},coords={x=0.642,y=0.5,source="quest_giver",zoneID=11510},questType="standard"},
[60886] = {id=60886,name="The Seat of the Primus",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="This cannot be a coincidence. It is clear that your runeblade is somehow connected to the Seat of the Primus. I will not pretend to know the Primus's agenda. But I would not be surprised if he left behind a way for the worthy to open the door to his sanctum. Draka will bring you to the Seat of the Primus. If you hold the key, mortal, then our victory is all but assured.",objectivesText="Go with Draka to the Seat of the Primus. Progress: What is it?",rewardGold=121680,rewardXP=710,rewardItems={180818,180819,180820,180821,180822,180823,180824,180825,180826},rewardChoices={180826,180818,180824,180825,180823,180819,180820,180822,180821},starts={{npcID=158007}},ends={{npcID=168381}},coords={x=0.37,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[60887] = {id=60887,name="Cataclysm: Onward to Adventure in Kalimdor",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=85,description="There are people across Azeroth that could use your help, . They come from different walks of life, but are all working towards finding their place on this beautiful world. Examine the Warchief's Command Board and see where your adventure awaits!",objectivesText="Find the Warchief's Command Board in Orgrimmar. Progress: I cannot wait to hear your stories someday.",starts={{npcID=167032}},ends={{npcID=172387}},questType="standard"},
[60889] = {id=60889,name="Favor: She Had a Stone Heart",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera . You will be fairly compensated.",objectivesText="Bring the She Had a Stone Hearth poem to Ta'xera at The Night Market in Revendreth . Provided item:",rewardGold=772200,rewardXP=2125,rewardItems={184373,184374},ends={{npcID=160081}},coords={mapID=1525,source="quest_giver",x=0.524,y=0.838},questType="standard"},
[60891] = {id=60891,name="Cataclysm: Onward to Adventure in the Eastern Kingdoms",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="There are people across Azeroth that could use your help, . They come from different walks of life, but are all working towards finding their place on this beautiful world. Examine the Hero's Call Board and see where your adventure awaits!",objectivesText="Find the Hero's Call Board in Stormwind. Progress: I cannot wait to hear your stories someday.",starts={{npcID=167032}},ends={{npcID=172334}},questType="standard"},
[60898] = {id=60898,name="The Fate of Ara'lon",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description=", I have an urgent request to make of you. Recently, the Wild Hunt has been encountering the masked fae in greater numbers... particularly in the area surrounding Blackthorn Grove. I sent a hunting party to investigate, but they have yet to return. Ara'lon was leading the hunt. You have offered him aid before, yes? I ask that you do so again. Search the area for signs of the missing hunters and report back to me.",objectivesText="Search near Blackthorn Grove for Ara'lon and the lost hunting party.",rewardGold=25740,rewardXP=1020,starts={{npcID=158544}},ends={{npcID=170705}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="standard"},
[60899] = {id=60899,name="A Night in the Woods",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Assist the patrol"},{orderIndex=1,type=0,amount=5,objectID=172322,text="Patrol credit"}},worldTaskTitle="A Night in the Woods",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60900] = {id=60900,name="Archival Protection",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The rarest volumes are kept at the top of this tower, protected by an entity called the Archivist . This stoic guardian is incorruptible. Intractable. Completely uninterested in striking a fair bargain! Its utter lack of business acumen is really quite upsetting. Ah, well. I fear we have no choice but to dispatch this impediment. Shall we?",objectivesText="Defeat the Archivist .",rewardGold=372060,rewardXP=1415,starts={{npcID=170667}},ends={{npcID=170667}},coords={x=0.418,y=0.236,source="quest_giver",zoneID=11462},questType="standard"},
[60901] = {id=60901,name="Passage to Hibernal Hollow",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You have done the Wild Hunt a great service. I must repay you in some way. The battle for Soryn's Meadow has turned. With the brute defeated, the Blighted forces lose their strength. Allow us to escort you to Hibernal Hollow. Speak to me whenever you wish to depart.",objectivesText="Speak with Ara'lon to receive an escort to Hibernal Hollow.",rewardGold=25040,rewardXP=175,starts={{npcID=170290}},ends={{npcID=160894}},coords={x=0.624,y=0.454,source="quest_giver",zoneID=11510},questType="standard"},
[60903] = {id=60903,name="Krala",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Krala"},
[60904] = {id=60904,name="Medallion of Desire",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="The Medallion of Desire rests upon the neck of the Countess. It is a source of power for her, but not her only source of power. Claiming it by force would merit us only a short victory. For this we must be much more subtle. Lucky for us, Theotar has come to me with a plan but he will need your help. Speak with him and see what the two of you can do. He was closer to the Countess than any of us for a long time and I would consider him our resident expert on her.",objectivesText="Speak with Theotar .",rewardGold=128700,rewardXP=4085,starts={{npcID=353948}},ends={{npcID=161979}},coords={x=0.533,y=0.326,source="quest_giver",zoneID=10986},questType="standard"},
[60905] = {id=60905,name="Infusing the Wildseed",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Dreamweaver tells me of a ritual to quell the wildseed's nightmares... but it will require anima. A soul named Proglo lives beneath this tree, gathering anima for the grove's caretakers to use. His mortal life came to a violent end, and his soul has been skittish ever since. He will not respond well to your current form. I will grant you the ability to assume the soulshape of a fox. Approach Proglo in your new form to gain his trust and ask for his anima.",objectivesText="Use Soulshape to collect anima from Proglo , then infuse the wildseed with the collected anima. Progress: I hope we can aid this wildseed.",rewardGold=125190,rewardXP=710,starts={{npcID=160894}},ends={{npcID=160963}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[60906] = {id=60906,name="Rightful Resting Place",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You have truly proven yourself a hero in the eyes of those who are its absolute judge. I thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place. Let us meet at Hero's Rest where you can do the honors.",objectivesText="Enshrine the Spear of Kalliope in its rightful place at Hero's Rest. Progress: <The resting place of the spear lies before you.>",rewardGold=96525,rewardXP=2040,rewardItems={180452},starts={{npcID=159248}},ends={{npcID=353959}},coords={x=0.366,y=0.376,source="quest_giver",zoneID=10534},questType="standard"},
[60907] = {id=60907,name="Ascension Calling: Kleia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Kleia to join you and Pelagos on the Path of Ascension. It would be wise to deliver this to her at once.>",objectivesText="Inform Kleia she is now able to participate in the Path of Ascension.",rewardGold=25740,rewardXP=1020,ends={{npcID=160390}},coords={mapID=1533,source="quest_giver",x=0.642,y=0.166},questType="standard"},
[60910] = {id=60910,name="Masks of Deception",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="My hunting party was ambushed not far from here. I narrowly escaped capture, but the others were taken deeper into Blackthorn Grove. We must find and rescue them, but we are vastly outnumbered. We'll need to disguise ourselves while we search the grove. See if you can find something we can use to do so. I need just a little longer to recover from my wounds.",objectivesText="Find two Masks of Possession . Progress: What have you found?",rewardGold=257400,rewardXP=8165,rewardItems={180462},starts={{npcID=170705}},ends={{npcID=170705}},coords={x=0.46,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[60911] = {id=60911,name="Flight School: Flapping Frenzy",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=170717,text="Speak to Instructor Malo"},{orderIndex=1,type=0,amount=1,objectID=170718,text="Goal reached"}},worldTaskTitle="Flight School: Flapping Frenzy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60916] = {id=60916,name="RSVP: Stonehead",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Hi, best bud! Me no go party. Stonehead shakes his head vigorously.> Got to stay for job!",rewardGold=257400,rewardXP=8165,rewardItems={171343,171344,180466},starts={{npcID=157199,x=0.39,y=0.66,mapID=1525}},ends={{npcID=157199,x=0.39,y=0.66,mapID=1525}},coords={x=0.39,y=0.66,source="quest_giver",mapID=1525},questType="world",worldTaskTitle="RSVP: Stonehead"},
[60920] = {id=60920,name="Akros",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Akros"},
[60928] = {id=60928,name="Blackthorn Captives",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="These disguises will allow us to explore the grove undetected, but beware of the overseers. Their Drust magic will more than likely be able to pierce through our deception. We need to save the rest of my hunting party while we still can.",objectivesText="Locate the missing hunters in Blackthorn Grove. Progress: The Drust have taken so much from us...",rewardGold=257400,rewardXP=8165,rewardItems={180523},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=170705}},ends={{npcID=170705}},coords={x=0.46,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[60929] = {id=60929,name="Air Supremacy",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={180465},questType="world",db2Objectives={{orderIndex=1,type=0,amount=5,objectID=170803,text="Flayedwing riders slain"}},worldTaskTitle="Air Supremacy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60930] = {id=60930,name="Lower Your Standards",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: < Picky Stefan leans in close and whispers.> Maw Walker, we are running low on refreshments! Thankfully, you chose to serve such a humble ... \"delicacy\" that we can find more just about anywhere. As you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.",rewardItems={180470},starts={{npcID=165500}},ends={{npcID=165500}},coords={x=0.328,y=0.578,source="quest_giver",zoneID=10413},questType="standard"},
[60932] = {id=60932,name="Only Shadows Remain",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="We may not know who this dark herald serves, but it is clear that the message she brings has emboldened the Scourge and the Cult of the Damned alike. This cannot be allowed to continue. We must vanquish her and strike a definitive blow against her master's new minions. Lead the charge, $p. The Argent Crusade stands with you. Light willing, we will put an end to this madness here and now.",objectivesText="Defeat Herald Dalora in the Cathedral of Darkness. Progress: May we continue our fight together.",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=5}},starts={{npcID=170467}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[60934] = {id=60934,name="Report to Lord Herne",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="I will do whatever it takes to save Gweyir from the Drust's curse. Lord Herne must be informed of what befell my hunting party. Deliver my report to him while I escort Gweyir back to the Heart of the Forest. Gweyir was under my leadership during the ambush... she is my responsibility. I will make sure she gets home safely.",objectivesText="Deliver Ara'lon's report to Lord Herne . Progress: Did you find the lost hunting party?",rewardGold=25740,rewardXP=1020,rewardItems={175603,179772,179894,180606,181916},rewardChoices={175603,179772,181916,179894},starts={{npcID=170705}},ends={{npcID=170848}},coords={x=0.46,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[60935] = {id=60935,name="Medallion of Avarice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="The Medallion of Avarice was the tool of the Curator. With its power it granted her authority over the Catacombs Ward. Combined with her knowledge of the vast library of sinstones Revendreth has accumulated over the ages, the Curator was a master of her craft. When Denathrius defeated my first rebellion, he tossed both myself and the Curator into the Maw. The Curator was clever, though, and she hid the medallion before Denathrius could act. Come, let us speak of plans.",objectivesText="Speak with Prince Renathal .",rewardGold=25740,rewardXP=1020,starts={{npcID=353949}},ends={{npcID=158653}},coords={x=0.545,y=0.306,source="quest_giver",zoneID=10986},questType="standard"},
[60945] = {id=60945,name="Deep Echo Trident",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<The trident glistens in the sunlight. This should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>",objectivesText="Bring the Deep Echo Trident to Paolone .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1819,amount=2}},ends={{npcID=171816}},coords={mapID=1533,source="quest_giver",x=0.628,y=0.16},questType="standard"},
[60946] = {id=60946,name="Blueprint: Deep Echo Trident",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this piece of equipment.>",objectivesText="Bring the Blueprint: Deep Echo Trident to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[60947] = {id=60947,name="Blueprint: Charm of Fortitude",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this charm.>",objectivesText="Bring the Blueprint: Charm of Fortitude to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[60948] = {id=60948,name="RSVP: The Countess",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Prince wishes to host court? Well, that should be interesting... I am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. So you shall do something for me. House Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses. Steal it for me, but incriminate one of the other houses in the act.",rewardGold=257400,rewardXP=8165,rewardItems={180497},starts={{npcID=171106,x=0.58,y=0.276,zoneID=10413}},ends={{npcID=171106,x=0.58,y=0.276,zoneID=10413}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="RSVP: The Countess"},
[60950] = {id=60950,name="A Matter of Stealth",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=170791,text="Fallen Sylvar Enraged"},{orderIndex=0,type=0,amount=1,objectID=170928,text="Obtain Disguise from Amberfoot"}},worldTaskTitle="A Matter of Stealth",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60955] = {id=60955,name="Noko's Flute",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: < Noko breathes in slowly.> The stage manager says he cannot find my flute anywhere. The last time this happened, one of the rowdy roadies had run off with it. You can find those troublesome dredgers causing trouble around the party. Retrieve my flute from them and I will play for your guests.",rewardItems={180484},starts={{npcID=170874}},ends={{npcID=170874}},coords={x=0.538,y=0.376,source="quest_giver",zoneID=10413},questType="standard"},
[60957] = {id=60957,name="Ansel's Lucky Violin",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: < Lucky Ansel reluctantly breaks gaze with his sinstone.> My burdens are still far too heavy. I will never be free of the Maw's dangers while even a single sin remains on this stone. Luckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor. Retrieve my violin from the band supplies over near the dancers and I will begin my public penance.",rewardItems={180485},starts={{npcID=170881}},ends={{npcID=170881}},coords={x=0.536,y=0.37,source="quest_giver",zoneID=10413},questType="standard"},
[60958] = {id=60958,name="We Send Only You",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="House of Constructs forces disrupted"}},worldTaskTitle="We Send Only You",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60959] = {id=60959,name="Burning Crusade: Onward to Adventure in Outland",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=111,description="The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself. Find your way back there and continue your adventure!",objectivesText="Travel to the shattered world of Outland.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60960] = {id=60960,name="Chiu's Lute",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: I am nervous, <name>. Music lays bare my soul for all to see. And while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within. Lord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived. I must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.",rewardItems={180486},starts={{npcID=170878}},ends={{npcID=170878}},coords={x=0.532,y=0.362,source="quest_giver",zoneID=10413},questType="standard"},
[60961] = {id=60961,name="Burning Crusade: Onward to Adventure in Outland",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=111,description="The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself. Find your way back there and continue your adventure!",objectivesText="Travel to the shattered world of Outland.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60962] = {id=60962,name="Wrath of the Lich King: Onward to Adventure in Northrend",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=125,description="The Lich King will stop at nothing to subjugate every living being on Azeroth. Find your way back to Northrend and continue your adventure!",objectivesText="Travel to the icy continent of Northrend.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60963] = {id=60963,name="Wrath of the Lich King: Onward to Adventure in Northrend",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=125,description="The Lich King will stop at nothing to subjugate every living being on Azeroth. Find your way back to Northrend and continue your adventure!",objectivesText="Travel to the icy continent of Northrend.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60964] = {id=60964,name="Mists of Pandaria: Onward to Adventure in Pandaria",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=371,description="There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, <name>. Find your way back there and continue your adventure!",objectivesText="Travel to the mysterious land of Pandaria.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60965] = {id=60965,name="Mists of Pandaria: Onward to Adventure in Pandaria",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=371,description="There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, <name>. Find your way back there and continue your adventure!",objectivesText="Travel to the mysterious land of Pandaria.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60968] = {id=60968,name="Warlords of Draenor: Onward to Adventure in Draenor",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=85,description="You mustn't delay, <name>. The people of Draenor still need your help! Find your way back there and continue your adventure!",objectivesText="Travel to the orcish homeworld of Draenor.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60969] = {id=60969,name="Warlords of Draenor: Onward to Adventure in Draenor",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=84,description="You mustn't delay, <name>. The people of Draenor still need your help! Find your way back there and continue your adventure!",objectivesText="Travel to the orcish homeworld of Draenor.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60970] = {id=60970,name="Legion: Onward to Adventure in the Broken Isles",level=10,requiredLevel=10,faction="horde",expansion=8,mapID=630,description="The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it! Find your way back to the Broken Isles and continue your adventure!",objectivesText="Travel to the Broken Isles.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60971] = {id=60971,name="Legion: Onward to Adventure in the Broken Isles",level=10,requiredLevel=10,faction="alliance",expansion=8,mapID=627,description="The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it! Find your way back to the Broken Isles and continue your adventure!",objectivesText="Travel to the Broken Isles.",starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[60972] = {id=60972,name="The Hunt for the Baron",level=10,requiredLevel=10,faction="none",expansion=8,mapID=1960,description="<The amulet Bolvar gave you flickers with a faint red light, then grows dim. To be useful in finding Darion Mograine, you must find a way to restore its potency. You recall an area called Zovaal's Cauldron that was teeming with dark magic. Perhaps the amulet's power could be restored there.>",objectivesText="Charge the Amulet of the Horsemen.",coords={mapID=1543,x=0.449,y=0.409},questType="standard"},
[60973] = {id=60973,name="Blueprint: Phial of Serenity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this piece of equipment.>",objectivesText="Bring the Blueprint: Phial of Serenity to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[60974] = {id=60974,name="Phial of Serenity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<Your steward friend gave you an extra bottle to store this potion in. This should keep your soulbinds fighting in the Path of Ascension, as your phial does.>",objectivesText="Bring the Phial of Serenity to Paolone .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1819,amount=2}},ends={{npcID=171816}},coords={mapID=1533,source="quest_giver",x=0.628,y=0.16},questType="standard"},
[60975] = {id=60975,name="Blueprint: Spiritforged Aegis",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this piece of equipment.>",objectivesText="Bring the Blueprint: Spiritforged Aegis to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[60991] = {id=60991,name="Orrholyn, Lord of Bloodletting",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Orrholyn, Lord of Bloodletting"},
[60992] = {id=60992,name="Razkazzar, Lord of Axes",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Razkazzar, Lord of Axes"},
[60993] = {id=60993,name="Citadel of Loyalty",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. Forge cannot solve this. Citadel of Loyalty can. Taken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.",objectivesText="Meet Mikanikos at the Citadel of Loyalty.",rewardGold=25740,rewardXP=1020,starts={{npcID=160280}},ends={{npcID=171001}},coords={x=0.502,y=0.204,source="quest_giver",zoneID=10534},questType="standard"},
[60994] = {id=60994,name="Lowering Their Defenses",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We can alter the crown to expunge Denathrius's corruption in the medallions. Problem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken. Drain the anima from the barrier's sources that power it. Barrier will disappear.",objectivesText="Drain the anima from the Forsworn Barrier Sources.",rewardGold=257400,rewardXP=8165,starts={{npcID=171001}},ends={{npcID=171001}},coords={x=0.244,y=0.298,source="quest_giver",zoneID=10534},questType="standard"},
[60995] = {id=60995,name="Disloyalty",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="There are many enemies of Bastion here. If we thin their numbers, it will further mend the tension between our realms. Show no remorse. I will take to the skies to support from above. I will be able to provide ground support when needed.",objectivesText="Kill 15 Forsworn in the Citadel of Loyalty.",rewardGold=257400,rewardXP=8165,starts={{npcID=170999}},ends={{npcID=171001}},coords={x=0.244,y=0.298,source="quest_giver",zoneID=10534},questType="standard"},
[60996] = {id=60996,name="Face Your Fears",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown. Prepare yourself. Denathrius's magic has always been potent and destructive. This won't be easy.",objectivesText="Speak to General Draven to go to the Temple of Loyalty. Then, aid Mikanikos in purifying the Crown of the Harvesters .",rewardGold=514800,rewardXP=10205,rewardItems={180605},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=171147}},ends={{npcID=171175}},coords={x=0.242,y=0.296,source="quest_giver",zoneID=10534},questType="standard"},
[61050] = {id=61050,name="How to Wear Seven Medallions",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them. What I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder. Unfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius. No, for this, we must employ the aid of a realm that specializes in service. Draven has the details.",objectivesText="Speak with General Draven .",rewardGold=25740,rewardXP=1020,starts={{npcID=158653}},ends={{npcID=161514}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[61051] = {id=61051,name="The Absent-Minded Artisan",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Of all the foolhardy, misguided, exasperating... Guardian Kota snorts and stomps a hoof.> But standing here does Sha'lor no good. We must find him and bring him back safely. Come, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.",objectivesText="Search for Master Sha'lor on the Autumnal Rise.",rewardGold=25740,rewardXP=175,starts={{npcID=158921}},ends={{npcID=171099}},coords={x=0.626,y=0.36,source="quest_giver",zoneID=11510},questType="standard"},
[61057] = {id=61057,name="By Trials Forged",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. It has been a privilege to fight by your side, . It would be my honor to continue, as your Soulbind.",objectivesText="Complete the soulbinding ritual with Korayn. Progress: Together we are stronger!",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=165659}},ends={{npcID=165659}},questType="standard"},
[61058] = {id=61058,name="Bound in Dreams",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well! Since then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger. I would be honored to help you continue the good work you have been doing, and to become your soulbind.",objectivesText="Complete the soulbinding ritual with Dreamweaver . Progress: I am humbled by the care you have shown for others.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160482}},ends={{npcID=160482}},coords={x=0.356,y=0.472,source="quest_giver",zoneID=12858},questType="standard"},
[61059] = {id=61059,name="RSVP: Rendle and Cudgelface",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e haven't got proper ah-tire. Says 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths. He says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.",rewardGold=257400,rewardXP=8165,rewardItems={176118},questType="world",worldTaskTitle="RSVP: Rendle and Cudgelface"},
[61060] = {id=61060,name="Spore Losers",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=171115,text="Fungret Mushroom eaten"},{orderIndex=1,type=15,amount=1,objectID=0,text="Revenge for Fungrets"},{orderIndex=3,type=0,amount=50,objectID=171140,text="Rally Fungret"}},worldTaskTitle="Spore Losers",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61061] = {id=61061,name="Ulfar's Guidance",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=8721,mapID=1565,description="There is one who may know how to dispel the curse from Gweyir. In the mountains of Drustvar lives Ulfar , an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust. Journey to his den and ask for his wisdom. He may hold the answers you seek. Lord Herne and I will tend to Gweyir once she arrives with Ara'lon.",objectivesText="Speak with Ulfar at Ulfar 's Den in Drustvar.",rewardGold=25740,rewardXP=1020,starts={{npcID=171138}},ends={{npcID=141159}},coords={x=0.46,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[61062] = {id=61062,name="Adjutant Dekaris",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="world",worldTaskTitle="Adjutant Dekaris"},
[61075] = {id=61075,name="A Spark of Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned. The Jailer's unblinking eyes patrol the river and watch for souls who attempt escape. Blind the eyes that find them. Close them for good. Take this and do what must be done.",rewardItems={180607},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Spark of Light"},
[61076] = {id=61076,name="Into the Flame",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=8721,mapID=896,description="I know the curse of which you speak. Dark magic that possesses the mind of the afflicted. Long ago, the Drust were ruled by a sorcerer king named Gorak Tul. It was he who twisted our rituals and set us on the path of death and domination. You will need to claim a portion of his power to break the curse. Take this fetish to Gol Inath and temper it in the Flame of Oblivion. But beware... it is a vile place, and danger lurks among its shadows.",objectivesText="Imbue the Drust Fetish with the power of Gorak Tul. Progress: Gorak Tul's magic empowers the curse, and only his magic can break it.",rewardItems={180625},starts={{npcID=141159}},ends={{npcID=141159}},questType="standard"},
[61077] = {id=61077,name="Confronting Sin",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Thanks to the raid launched against Castle Nathria, we have obtained an opportunity. A soul, powerful and fused with dark purpose at the hands of the Master's experiments. Given this soul is from Azeroth, the Accuser has asked for your assistance in untwining the corruption done to his sinstone. the Accuser awaits you in the lower levels of Sinfall.",objectivesText="Speak with the Accuser in Sinfall.",rewardGold=128700,rewardXP=4085,starts={{npcID=158653}},ends={{npcID=165291}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[61079] = {id=61079,name="The Jailer's Share",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn's torturers have a talent for misery. The suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss. I have fashioned a conduit specifically for capturing the leftover stygia . You can borrow it if you wish. There are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.",rewardItems={177698,177699,178874,178877,178880,178881,178882,178883,185717},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="The Jailer's Share"},
[61088] = {id=61088,name="Dust to Dust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn never cease to invent new forms of suffering. Even the ground on which we tread is formed from souls pounded into dust. With the flood of souls passing through Gorgoa, the Mawsworn are keen to expand their domain. At present, the Mawsworn are burying souls and crafting new terrain from their torment. It is not too late for some of them. Free the buried souls and stop the endless expansion of suffering.",rewardItems={185717},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Dust to Dust"},
[61092] = {id=61092,name="RSVP: Grandmaster Vole",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I'm busy, so I'll get right to the point. The only way I'm going is if you pay me enough coin to make it worth my while or you amuse me. As interesting and enjoyable as the Ember Court may be, I lose money every time I am away from here. That said, I do love a good slaughter. So, coin or deaths. Take your pick.",rewardGold=257400,rewardXP=8165,rewardItems={176122},starts={{npcID=163019,x=0.528,y=0.492,zoneID=11462}},ends={{npcID=163019,x=0.528,y=0.492,zoneID=11462}},coords={x=0.528,y=0.492,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Grandmaster Vole"},
[61095] = {id=61095,name="Supplies from The Undying Army",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Your efforts meet with the approval of The Undying Army. These rewards are in recognition of those efforts. May they help you in the battles to come.",objectivesText="Speak with Nalcorn Talsen at the Theater of Pain.",rewardItems={180646,181269,182081,184495},starts={{npcID=173003}},ends={{npcID=173003}},questType="standard"},
[61096] = {id=61096,name="The Arbiter's Will",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1671,description="We will all suffer if Bastion and Maldraxxus fall into war. For some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion. Though our anima reserves remain low, they will be enough to open the way for you.",objectivesText="Meet Kah-Sher in the Ring of Transference in Oribos.",rewardGold=24100,rewardXP=175,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[61097] = {id=61097,name="Supplies from The Ascended",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Ascended would like to thank you for your efforts in aiding Bastion . Please accept a gift in recognition of your service to our cause and our people.",objectivesText="Speak with Adjutant Nikos in Hero's Rest in Bastion .",rewardItems={180647,184396,184399,184435},rewardCurrencies={{currencyID=1819,quantity=1}},starts={{npcID=160470}},ends={{npcID=160470}},questType="standard"},
[61098] = {id=61098,name="Supplies from The Wild Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="The Wild Hunt thanks you for your efforts in aiding Ardenweald . Take these gifts as recognition for your aid. May they help you in whatever trials may come.",objectivesText="Speak with Aithlyn at the Heart of the Forest in Ardenweald .",rewardItems={180635,180649,183800,185054,187870},starts={{npcID=158556}},ends={{npcID=158556}},questType="standard"},
[61099] = {id=61099,name="The Search for Baine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13400,mapID=1543,description="I dare not step inside that accursed tower myself, of course. While I cannot tell you exactly where your comrade is being held, I offer a gift to assist you. Use it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes? Either that, or you'll end up trapped within the tower's ever-shifting halls for all eternity. But those are the risks one must take, I suppose. Best of luck!",objectivesText="Enter Torghast and search for Baine. Progress: You've found him!",rewardGold=214000,rewardXP=16330,rewardItems={184544,184757},rewardChoices={184757},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[61100] = {id=61100,name="Supplies from the Court of Harvesters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. As a result, we have collection of resources you may find useful, plundered from Sire Denathrius' most devoted followers. They are waiting for you with me in Darkhaven.",objectivesText="Speak with Mistress Mihaela for your reward.",rewardItems={180601,180648},starts={{npcID=156822}},ends={{npcID=156822}},questType="standard"},
[61102] = {id=61102,name="Kivarr the Thornspeaker",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=12858,mapID=896,description="In my youth, I was mentored by a wise and powerful Thornspeaker named Kivarr. She passed from this world long ago, but her soul may yet rest within the Shadowlands. Kivarr's knowledge is ancient and vast, far eclipsing my own. She may be able to offer you the guidance that I cannot. Seek her out. Deliver the fetish to her. She will know what to do. May the wind be your guide.",objectivesText="Speak with Lord Herne at Heart of the Forest in Ardenweald.",rewardGold=25740,rewardXP=1020,starts={{npcID=141159}},ends={{npcID=170848}},coords={x=0.452,y=0.458,source="quest_giver",zoneID=8721},questType="standard"},
[61103] = {id=61103,name="Disrupting the Cycle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The shacklers in the Tremaculum are an awful sort. Souls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. If you wish to slow the rate at which the Jailer raises his armies, start at the source. Disrupt the cycle at the Tremaculum.",rewardItems={185717},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Disrupting the Cycle"},
[61104] = {id=61104,name="Grathalax, the Extractor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13587,mapID=1543,description="There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer. Far beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax . Power is fed to him via conduits throughout the area. His role is to make the process of anima extraction more efficient. His methods are... unkind. I believe we would both benefit from the end of his existence.",rewardItems={177698,177699,178874,178880,178881,178882,178883,185717},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Grathalax, the Extractor"},
[61105] = {id=61105,name="RSVP: Plague Deviser Marileth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Oh! This sounds like a wonderful opportunity to do field research in Revendreth, apprentice. I look forward to collaborating with new colleagues. We must bring a gift to thank them for their invitation. What could be more appropriate than some lovely slimes? Please pick some of the best slimes for me to present to our host. Just bring them to Kevin so they can make friends and travel together.",rewardGold=257400,rewardXP=8165,rewardItems={176124},starts={{npcID=159930,x=0.604,y=0.716,zoneID=11462}},ends={{npcID=159930,x=0.604,y=0.716,zoneID=11462}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Plague Deviser Marileth"},
[61107] = {id=61107,name="A Land of Strife",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10565,mapID=1671,description="It is imperative that you identify the cause of the attack on Bastion . We will require your aid to open the gateway. Once the focus is sufficiently powered, we will call upon the gate to Maldraxxus and direct it into position. From there, the fate of this war must rest upon your shoulders.",objectivesText="Activate the gateway to Maldraxxus. Progress: Time is precious, now more than ever.",rewardGold=120510,rewardXP=710,starts={{npcID=171338}},ends={{npcID=171338}},questType="standard"},
[61109] = {id=61109,name="RSVP: Hunt-Captain Korayn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I am a Captain of the Wild Hunt, a defender of the sacred groves. As much as I would enjoy the diversion, my place is here fighting back the forces of the enemy, not venturing outside of Ardenweald. Eggs are hatching again at Gormhive and we shall soon be overrun by gormling larva. Until that threat is neutralized I cannot leave my post.",rewardGold=257400,rewardXP=8165,rewardItems={176116},starts={{npcID=171319,x=0.508,y=0.704,zoneID=11510}},ends={{npcID=171319,x=0.508,y=0.704,zoneID=11510}},coords={x=0.508,y=0.704,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Hunt-Captain Korayn"},
[61112] = {id=61112,name="A Hunger for Flesh",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="Commander Gregor will want to know of this at once.>",objectivesText="Bring the Partially Digested Cloth to Commander Gregor in the Trade District of Stormwind City. Provided item:",rewardGold=234000,rewardXP=6815,ends={{npcID=166383}},coords={mapID=84,source="quest_giver",x=0.655,y=0.768},questType="standard"},
[61113] = {id=61113,name="Kivarr's Den",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Kivarr... I have not heard that name in many an age. She used to make her home near Eventide Grove to the south. Ara'lon knows the area well. I suggest you take him with you. I fear that the situation with Gweyir weighs heavily upon him. Perhaps joining you on the hunt will do him some good.",objectivesText="Travel to Kivarr's Den at Eventide Grove in Ardenweald. Progress: Kivarr has made her home in Ardenweald for many an age, but she has always kept to herself.",rewardGold=128700,rewardXP=4085,starts={{npcID=170848}},ends={{npcID=170705}},coords={x=0.462,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[61114] = {id=61114,name="A Hunger for Flesh",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Commander Throgg will want to know of this at once.>",objectivesText="Bring the Partially Digested Leather to Commander Throgg in the Valley of Strength in Orgrimmar. Provided item:",rewardGold=257400,rewardXP=6815,ends={{npcID=169878}},coords={mapID=85,source="quest_giver",x=0.528,y=0.775},questType="standard"},
[61123] = {id=61123,name="RSVP: Polemarch Adrestes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I must politely decline your Prince's offer. My skills are needed here, and I am not particularly well-suited to the social demands of attending court. Perhaps the Paragon of Humility would be a better representative for Bastion. You may find him at the Temple of Humility, east of here. Please express my sincere regrets that I am unable to attend.",rewardGold=257400,rewardXP=8165,rewardItems={176117},starts={{npcID=171385,x=0.69,y=0.406,zoneID=10534}},ends={{npcID=171385,x=0.69,y=0.406,zoneID=10534}},coords={x=0.69,y=0.406,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Polemarch Adrestes"},
[61124] = {id=61124,name="Warren Mongrel",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Warren Mongrel"},
[61125] = {id=61125,name="Malevolent Stygia",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Malevolent Stygia"},
[61129] = {id=61129,name="RSVP: Droman Aliothe",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. Once, I might have enjoyed your Prince's party, but I am no longer suited to revelry. My world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home. I have heard those strange traders, the brokers, have unusual objects from other worlds. Perhaps they have something from mine?",rewardGold=257400,rewardXP=8165,rewardItems={176121},rewardCurrencies={{id=1851,amount=90}},starts={{npcID=160894,x=0.6,y=0.538,zoneID=11510}},ends={{npcID=160894,x=0.6,y=0.538,zoneID=11510}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Droman Aliothe"},
[61130] = {id=61130,name="RSVP: Sika",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Hello, ! Sika like to help. So much to do. Would go to Ember Court, but too many things only Sika can do. Very sorry.",rewardGold=257400,rewardXP=8165,rewardItems={180965,180966,180967,180968},starts={{npcID=166577,x=0.526,y=0.826,zoneID=10534}},ends={{npcID=166577,x=0.526,y=0.826,zoneID=10534}},coords={x=0.526,y=0.826,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Sika"},
[61135] = {id=61135,name="Heart of the Crest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With this greatest of gifts from Ardenweald, we have the final piece to rebuild the Crest of Ascension. Let us make certain Willowblossom's sacrifice is not in vain.",objectivesText="Place the Vessel of Ardenweald at the Crest of Ascension. Progress: <The vessel seems drawn to the spot.>",rewardGold=25740,rewardXP=1020,rewardItems={180778},starts={{npcID=160037}},ends={{npcID=355255}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[61136] = {id=61136,name="Agonix",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Agonix"},
[61139] = {id=61139,name="RSVP: Choofa",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oooh a party! I love parties. My friends have to come too or it's just not as much fun. Ask them please! You need to find Awool, Rury, and Slanknen so we can go together.",rewardGold=257400,rewardXP=8165,rewardItems={176119},starts={{npcID=160814,x=0.636,y=0.366,zoneID=11510}},ends={{npcID=160814,x=0.636,y=0.366,zoneID=11510}},coords={x=0.636,y=0.366,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Choofa"},
[61140] = {id=61140,name="Dath Rezara",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Dath Rezara"},
[61141] = {id=61141,name="Deathfang's Favorite Toy",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=12876,mapID=1536,rewardXP=8165,rewardItems={180810},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166274,text="Throwin' Skull found"},{orderIndex=1,type=0,amount=5,objectID=171591,text="Play with Deathfang"}},worldTaskTitle="Deathfang's Favorite Toy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61143] = {id=61143,name="Return to the Den",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="There may be a way to break the curse and free your friend's mind, but it will require some work. Ulfar was wise to send you to me. He knew that a portion of Gorak Tul's power would be necessary, but the other reagents we need do not exist on Azeroth. My den is not far from here. Meet me there and I will help you prepare a ritual to break the curse.",objectivesText="Meet with Kivarr at her den in Ardenweald .",rewardGold=257400,rewardXP=8165,rewardItems={175600,179771,179893,181915},rewardChoices={175600,179771,181915,179893},starts={{npcID=171413}},ends={{npcID=171413}},coords={x=0.462,y=0.564,source="quest_giver",zoneID=11510},questType="standard"},
[61145] = {id=61145,name="Take The Fight To Them",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Our scouts report that Margrave Gharmal gathers their forces at the House of Constructs. Our necropolis and our new kyrian allies have already begun an aerial assault. I need you to lead our forces on the ground. Meet me within Zerekriss. We will begin our attack immediately.",objectivesText="Take the portal to meet Draka aboard the Zerekriss.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=171483}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[61146] = {id=61146,name="Manifesting Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="As you know, shedding our memories of life can result in dangerous creatures known as manifestations. They have increased in number and strength as of late, but I believe we can find use for them yet. Manifestations carry great power within them--power we may purify and use in our own creations at the forge here. In making something positive out of such negativity, we do a noble act of service. Simply eliminate any you come across, and collect their essence. That is all.",objectivesText="Collect 15 Condensed Essence from manifestations. Progress: Be cautious in your travels. Manifestations are no simple foe.",rewardXP=8165,rewardItems={181368,181377,181581,181609,181614,181627,181637,181745,184294,184362,184363,184765,184766,184767,184768},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171677}},ends={{npcID=171677}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61148] = {id=61148,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={180789},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=171514,text="Enter a Rift"},{orderIndex=3,type=0,amount=1,objectID=171829,text="Exit the Rift"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61156] = {id=61156,name="Where There's a Quill...",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="In times long past, Aspirants trained against the fauna of Bastion. The creation of the Centurions rendered such unstructured progression obsolete. The many flying denizens of this realm are known for their quills. They are light and sturdy, perfect for our purposes. Gather all that you can, please. Any flying creature shall suffice.",objectivesText="Collect 30 Shimmerflight Quills from flying beasts. Progress: Have you the quills?",rewardXP=8165,rewardItems={180796},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171676}},ends={{npcID=171676}},coords={x=0.504,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61157] = {id=61157,name="Straight to the Point",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The horned beasts of Bastion were once commonly used in aspirant training, but centurion sparring units have mostly taken their place. Over the past few eons, their numbers have grown and now must be culled. Their horns are critical components to our work. Many specimens are broken from use in battle--they will not suffice. You must be careful in collecting them. Face them, defeat them, and bring back their horns.",objectivesText="Collect 12 Elysian Horns from horned beasts. Progress: We require as many horns as you are able to procure.",rewardXP=8165,rewardItems={181368,181377,181577,181605,181606,181609,181611,181612,181702,181704,181745,184294,184362,184363,184765,184766,184767,184768},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171676}},ends={{npcID=171676}},coords={x=0.504,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61159] = {id=61159,name="Signs of Demise",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="All members of the Forsworn carry an insignia on their person at all times. We suspect they are imbued with the power of the Temple of Loyalty, bolstering their strength against us. Collect these insignias from their deceased forms. Strip them of this power, and we shall put it to better use in our own machinations. Such is the Archon's will, as it is ours.",objectivesText="Collect 20 Forsworn Insignias from Forsworn kyrian. Progress: Each insignia is a shift of power in our favor.",rewardXP=8165,rewardItems={180816},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171676}},ends={{npcID=171676}},coords={x=0.504,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61161] = {id=61161,name="Party Crashers!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13329,mapID=1525,questType="standard"},
[61162] = {id=61162,name="Party Crashers!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13329,mapID=1525,questType="standard"},
[61163] = {id=61163,name="Party Crashers!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13329,mapID=1525,questType="standard"},
[61164] = {id=61164,name="Party Crashers!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13329,mapID=1525,questType="standard"},
[61166] = {id=61166,name="Reduce, Reuse, Recycle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Centurions need lots of parts. But so do we! Kofi needs their metal. Can be from Centurions or the ground. Your choice! Not too damaged, ok? Hard to clean!",objectivesText="Collect 20 Resonant Alloy from Forsworn centurions or Centurion parts. Progress: You have metal?",rewardXP=8165,rewardItems={180830},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171671}},ends={{npcID=171671}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61171] = {id=61171,name="Unbroken Bonds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="The Drust will pay for this foul curse that they've unleashed upon us. We have lost too many allies... too many friends to give up now. Even though we cannot save those who have fallen into possession, we can end their torment. I will instruct the hunt to put down all possessed they encounter. Please deliver this report to the Winter Queen . She must be told what we have learned. Thank you for your service, . You are a true friend and guardian of Ardenweald .",objectivesText="Deliver Lord Herne's report to the Winter Queen . Progress: What news do you bring?",rewardGold=257400,rewardXP=8165,rewardItems={175597,179770,179892,180832,181914},rewardChoices={179892,175597,181914,179770},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=170848}},ends={{npcID=156634}},coords={x=0.462,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[61173] = {id=61173,name="RSVP: Mikanikos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ember Court sounds interesting ... but very busy right now! Forsworn got into my supplies. Now everything jumbled and disorganized. Can't work in these conditions. My workshop isn't right! Help me! Get parts. Most will be damaged and you don't know how to tell about flaws. Bring me many to examine. I will find perfect part.",rewardGold=257400,rewardXP=8165,rewardItems={180895,182114},starts={{npcID=171647,x=0.502,y=0.212,zoneID=10534}},ends={{npcID=171647,x=0.502,y=0.212,zoneID=10534}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Mikanikos"},
[61174] = {id=61174,name="RSVP: Baroness Vashj",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I am no stranger to courts, Maw Walker. Having attended on Queen Azshara herself, and then later serving my Lord Illidan. That does not mean, however, that I accept every invitation I receive. Baroness Vashj smirks.> Impress me with your strength, $p, and I will believe Prince Renathal has power that is worth my time.",rewardGold=257400,rewardXP=8165,rewardItems={180846,180848,180849,180850},starts={{npcID=162487,x=0.676,y=0.46,zoneID=11462}},ends={{npcID=162487,x=0.676,y=0.46,zoneID=11462}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Baroness Vashj"},
[61179] = {id=61179,name="Forge Ahead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Eternal Forge has anima again? Ah! Yes! So exciting! You must go. Find Forgelite Selene . She will help! So much to make!",objectivesText="Speak to Forgelite Selene at the Eternal Forge.",rewardXP=8165,starts={{npcID=158773}},ends={{npcID=171677}},coords={x=0.382,y=0.676,source="quest_giver",zoneID=11012},questType="standard"},
[61180] = {id=61180,name="Burn Before Reading",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's constructs. It is also incomplete. There must be more of these among Stitchflesh's remaining followers. I saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls. We must ensure they are never read again.",objectivesText="Collect 6 Stitchflesh Designs . Progress: This foul work must be destroyed.",rewardGold=257400,rewardXP=8165,rewardItems={180845},starts={{npcID=168744}},ends={{npcID=168744}},coords={x=0.352,y=0.268,source="quest_giver",zoneID=11462},questType="standard"},
[61182] = {id=61182,name="Pollen Your Weight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You know Twirlpetal flowers?! They spin around in the light! We need pollen. Only pollen if in bloom! Get a bunch! Flowers in golden fields. And they spin! Round and round!",objectivesText="Collect 30 Twirlpetal Pollen in Bastion's plains. Progress: Pollen very fragile. Won't last long!",rewardXP=8165,rewardItems={180851},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171671}},ends={{npcID=171671}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61189] = {id=61189,name="Further Gelatinous Research",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={180876},questType="world",db2Objectives={{orderIndex=1,type=0,amount=30,objectID=171746,text="Slime gathered"},{orderIndex=0,type=0,amount=1,objectID=171747,text="Accumulator Acquired"}},worldTaskTitle="Further Gelatinous Research",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61190] = {id=61190,name="Wake of Ashes",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="It feels as if the Maw itself is sentient... and taking notice of our presence. We must leave at once. Bolvar must be informed of what is happening here. I will bring my father with us. Lead the way out of here, . With haste.",objectivesText="Escape from the Maw and report to Bolvar in Oribos.",rewardGold=122850,rewardXP=710,starts={{npcID=172414}},ends={{npcID=162804}},coords={x=0.33,y=0.664,source="quest_giver",zoneID=11400},questType="standard"},
[61193] = {id=61193,name="A Light Touch",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Need Firstborne's Light ! You know? Named after Archon! Always in water. Kofi 's favorite! Shine big light when grown. And go to shore! Easy to see!",objectivesText="Collect 15 Firstborne's Light in water sources. Progress: Only grown flowers! Little ones won't work.",rewardXP=8165,rewardItems={180897},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171671}},ends={{npcID=171671}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61196] = {id=61196,name="The Secret Ingredient",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common. There is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions. Will you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.",objectivesText="Collect 10 Ephemeral Draught . Progress: Were you able to find the draught?",rewardXP=8165,rewardItems={181368,181377,181583,181601,181610,181703,181745,184294,184362,184363,184765,184766,184767,184768,184839,184840,184841,184842},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171677}},ends={{npcID=171677}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61199] = {id=61199,name="Arms Day",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Many battles here. Especially lately! Now weapons all over. Too many. We can use! Go to big battle places and grab them. We will use better!",objectivesText="Collect 20 Blessed Armaments from battlefields. Progress: Careful with the pointy end!",rewardXP=8165,rewardItems={180946},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171671}},ends={{npcID=171671}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61209] = {id=61209,name="A Somber Melody",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters. These memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like. Take my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.",objectivesText="Dissipate 15 Kyrian memories along the roads of Bastion.",rewardXP=8165,rewardItems={180990},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=171677}},ends={{npcID=171677}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="standard"},
[61217] = {id=61217,name="Champion: Thela Soulsipper",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61218] = {id=61218,name="Champion: Dug Gravewell",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61219] = {id=61219,name="Champion: Nerith Darkwing",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61220] = {id=61220,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Repel the Devourer threat"},{orderIndex=0,type=0,amount=1,objectID=171834,text="Assist Aspirant Thetes"},{orderIndex=6,type=0,amount=40,objectID=162685,text="Helpless Aspirant rescued"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61221] = {id=61221,name="Champion: Stonehuck",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61222] = {id=61222,name="Champion: Kaletar the Mender",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61223] = {id=61223,name="Champion: Ayeleth the Deprived",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61226] = {id=61226,name="Extra Limbs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit. Three individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it. There remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her. Meet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.",objectivesText="Locate and assist Navigator Xennir .",rewardGold=25740,rewardXP=1020,starts={{npcID=158529},{npcID=160518}},ends={{npcID=158604}},coords={x=0.498,y=0.178,source="quest_giver",zoneID=11462},questType="standard"},
[61227] = {id=61227,name="The Other Foot",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash. But opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections. Find this individual. An enemy deserter could make for a potential ally.",objectivesText="Locate Mechanic Ansid.",rewardGold=25740,rewardXP=1020,starts={{npcID=164646}},ends={{npcID=159814}},coords={x=0.498,y=0.178,source="quest_giver",zoneID=11462},questType="standard"},
[61228] = {id=61228,name="Dug's Missing Shovel",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61230] = {id=61230,name="Outside Influence",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir. But Baroness Vashj has informed me of a means to acquire a new helmsman. Follow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require. I suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.",objectivesText="Meet with Khaliiq at the House of Eyes' communications pillar.",rewardGold=25740,rewardXP=1020,rewardItems={173312,175796},starts={{npcID=171875}},ends={{npcID=174343}},coords={x=0.5,y=0.18,source="quest_giver",zoneID=11462},questType="standard"},
[61234] = {id=61234,name="Stonehuck's Sinstone",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61243] = {id=61243,name="Thela's Memory Stone",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61246] = {id=61246,name="Power of the Chosen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The necropolis is nearly in position. Now is the time to strike! We must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts. The Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.",objectivesText="Destroy the Bilebloat Juggernauts . Progress: Every moment the juggernauts remain standing, our position is in jeopardy!",rewardGold=128700,rewardXP=4085,starts={{npcID=166211}},ends={{npcID=166211}},coords={x=0.288,y=0.382,source="quest_giver",zoneID=11462},questType="standard"},
[61248] = {id=61248,name="Kaletar's Freedom",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61252] = {id=61252,name="Call In a Favor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her. Activate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.",objectivesText="Summon Helmsman Caliroux and defeat her.",rewardGold=514800,rewardXP=10205,rewardItems={181162},starts={{npcID=174343}},ends={{npcID=171875}},coords={x=0.542,y=0.162,source="quest_giver",zoneID=11462},questType="standard"},
[61255] = {id=61255,name="RSVP: Alexandros Mograine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. But before I leave my post, I must ensure my comrades will be safe while I am away. Fight your way into the Ossein Foundry and retrieve weapons from our rivals there. I will have them distributed among the troops while I make ready to depart.",rewardGold=257400,rewardXP=8165,rewardItems={181160,181161},starts={{npcID=171933,x=0.504,y=0.674,zoneID=11462}},ends={{npcID=171933,x=0.504,y=0.674,zoneID=11462}},coords={x=0.504,y=0.674,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Alexandros Mograine"},
[61256] = {id=61256,name="RSVP: Kleia and Pelagos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Oh, how wonderful! Thank you for the invitation to the Ember Court. We were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?",rewardGold=257400,rewardXP=8165,rewardItems={176123},starts={{npcID=174916,x=0.558,y=0.864,zoneID=10534}},ends={{npcID=171951,x=0.578,y=0.856,zoneID=10534}},coords={x=0.558,y=0.864,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Kleia and Pelagos"},
[61259] = {id=61259,name="Ayeleth's Hunger",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61262] = {id=61262,name="Nerith's Vengeance",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61265] = {id=61265,name="Blueprint: Charm of Alacrity",level=60,requiredLevel=60,faction="none",expansion=8,description="<You have discovered plans for a charm that seems to hasten your soulbinds in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>",objectivesText="Bring the Blueprint: Charm of Alacrity to Dactylis.",questType="standard"},
[61269] = {id=61269,name="Blueprint: Charm of Persistence",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this charm.>",objectivesText="Bring the Blueprint: Charm of Persistence to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
