[61304] = {id=61304,name="Blueprint: Kyrian Smith's Kit",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this kit.>",objectivesText="Bring the Blueprint: Kyrian Smith's Kit to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[61313] = {id=61313,name="Champion: Kythekios",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61314] = {id=61314,name="REUSE ME - SCS",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=11400,mapID=1543,description="You'll need a vessel to hold the anima you need to collect, but one that will also allow you to channel said anima. There was once such a device ages ago, but as of late they've become much more rare. In my travels through the Maw , I have seen one once. It is in the (AREA NAME), held by (CREATURE). You'll need luck on your side in order to retrieve it.",objectivesText="Obtain the Anima Focuser.",questType="standard"},
[61317] = {id=61317,name="Champion: Teliah",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61318] = {id=61318,name="Champion: Telethakas",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61319] = {id=61319,name="Champion: Hala",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61320] = {id=61320,name="Champion: Molako",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61321] = {id=61321,name="Champion: Ispiron",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61322] = {id=61322,name="Kythekios' Memory Stone",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61323] = {id=61323,name="See What You've Done",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We have gathered what forces we can. I hope it is enough. Within the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus. To preserve all that remains to us, we must end her. Lead the attack, and the Eyes will join you. We will reclaim our home.",objectivesText="Slay Gorgantus the Gutter .",rewardGold=514800,rewardXP=10205,rewardItems={181162,182256,182265,182274,182283},rewardChoices={182265,182274,182283,182256},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158529}},ends={{npcID=164619}},coords={x=0.498,y=0.178,source="quest_giver",zoneID=11462},questType="standard"},
[61330] = {id=61330,name="Teliah's Stolen Spear",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61331] = {id=61331,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1565,description="Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible! The Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=514800,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158553}},ends={{npcID=158553}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[61332] = {id=61332,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands. The Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right. Return to the Maw and save all that you can.",objectivesText="Rescue 5 Souls from the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[61333] = {id=61333,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1698,description="Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. We must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords. I shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167748}},ends={{npcID=167748}},coords={x=0.47,y=0.42,source="quest_giver",zoneID=12876},questType="standard"},
[61334] = {id=61334,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1525,description="Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.",objectivesText="Rescue Souls in the Maw.",rewardGold=514800,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164738}},ends={{npcID=164738}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[61335] = {id=61335,name="Rage Against the Cage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You're looking for a mechanic, are you? Look no further! I've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods. But now you need help, right? I'm your construct! You get me out of here, and you've got yourself a new mechanic!",rewardGold=257400,rewardXP=8165,rewardItems={173312},starts={{npcID=159814,x=0.486,y=0.186,zoneID=11462}},ends={{npcID=159814,x=0.486,y=0.186,zoneID=11462}},coords={x=0.486,y=0.186,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Rage Against the Cage"},
[61337] = {id=61337,name="March of the Eternal Protector",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defend Heraclor"},{orderIndex=7,type=0,amount=200,objectID=172025,text="Assist Heraclor"}},worldTaskTitle="March of the Eternal Protector",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61340] = {id=61340,name="Telethakas' Revenge",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61342] = {id=61342,name="Battles Won Long Ago",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=166380,text="Plant Banner at the Burning Thicket"},{orderIndex=0,type=0,amount=15,objectID=166501,text="Burning Thicket enemies killed"}},worldTaskTitle="Battles Won Long Ago",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61343] = {id=61343,name="Battles Won Long Ago",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=166381,text="Plant Banner at the Sepulcher of Knowledge"},{orderIndex=0,type=0,amount=15,objectID=166502,text="Sepulcher of Knowledge enemies killed"}},worldTaskTitle="Battles Won Long Ago",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61346] = {id=61346,name="Cyrixia the Willbreaker",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Cyrixia the Willbreaker"},
[61347] = {id=61347,name="Molako's Freedom",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61348] = {id=61348,name="Hala's Sword",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61351] = {id=61351,name="Ancient Sinstone (+Formal)",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: < Prince Renathal looks at the Ancient Sinstone you're carrying with great interest.> Now where did you find that old sinstone?",starts={{npcID=164965}},ends={{npcID=164965}},coords={x=0.474,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[61352] = {id=61352,name="All Will Be Consumed",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=163434,text="Devourer slain"},{orderIndex=2,type=0,amount=6,objectID=175808,text="Collectors rescued"}},worldTaskTitle="All Will Be Consumed",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61353] = {id=61353,name="All Will Be Consumed",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Devourer Invasion stopped"},{orderIndex=2,type=0,amount=20,objectID=172068,text="Rift closed"}},worldTaskTitle="All Will Be Consumed",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61354] = {id=61354,name="RSVP: Lady Moonberry",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Of course I will attend, , the Ember Court sounds like a lot of fun! But I cannot go without a gift! Hospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests. Lady Moonberry suppresses a smirk.> Now for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones. Easy enough for someone of your prowess.",rewardGold=257400,rewardXP=8165,rewardItems={181250,181251,181252},starts={{npcID=172098,x=0.49,y=0.51,zoneID=11510}},ends={{npcID=172098,x=0.49,y=0.51,zoneID=11510}},coords={x=0.49,y=0.51,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Lady Moonberry"},
[61355] = {id=61355,name="Rule 2: Keep a Low Profile",level=55,requiredLevel=55,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Though you may wish to depart with your precious souls in tow, we now have additional matters to settle first. The Eye of the Jailer is upon you. And that does not bode well for either of us. Take this device. You will reinforce my wards to ensure he does not take notice of me as well. The last thing I need is a loud, inelegant mortal bringing more attention my way. I can't have the Jailer capturing me, after all. I'm far too valuable.",objectivesText="Reinforce 4 Soul Wards . Progress: Our business is not yet complete. Attend to my wards.",rewardXP=3745,rewardItems={184314},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[61356] = {id=61356,name="Echthra, Dame of Hatred",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds. She has requested a special anointment oil used in kyrian ceremonies in return for her memory.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61357] = {id=61357,name="Hatred Abated",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1536,description="As agreed, you may take my memory for the trials you seek. Heed this warning, mortal--even as an echo of my physical form I will attack without hesitation. Expect no mercy, for I will show none. You have done me a great service this day. See to your business.",objectivesText="Capture Echthra 's memory.",rewardGold=257400,rewardItems={181701},starts={{npcID=172515}},ends={{npcID=168430}},coords={x=0.566,y=0.116,source="quest_giver",zoneID=11462},questType="standard"},
[61358] = {id=61358,name="Alderyn and Myn'ir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest. We have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61359] = {id=61359,name="Power of the Primus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="As a Necrolord, your duty is to defend the Shadowlands. To carry out such service, the Primus grants us his strength. Stand upon the altar of the Primus. Let his power become your own.",objectivesText="Kneel before the Primus and receive his power! Progress: It is a great gift to wield the Primus's power.",rewardGold=128700,rewardXP=4085,starts={{npcID=165182}},ends={{npcID=165182}},coords={x=0.496,y=0.432,source="quest_giver",zoneID=12876},questType="standard"},
[61360] = {id=61360,name="The Hunt's Gratitude",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1565,description="The forests of Ardenweald are safer with your help, envoy of the kyrian. As a reward for your aid, we shall allow you to capture our memory. It is an honor to be chosen to help train the mighty warriors of Bastion. Whenever you are ready.",objectivesText="Capture Alderyn and Myn'ir 's memories.",rewardGold=257400,rewardItems={182580},starts={{npcID=173403}},ends={{npcID=168430}},coords={x=0.518,y=0.788,source="quest_giver",zoneID=11510},questType="standard"},
[61361] = {id=61361,name="Nuuminuuru",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed. One tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61362] = {id=61362,name="Caretaker of Faeries",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1565,description="Tirnenn and faeries hold many dissimilarities. While tirnenn stand patient and calm, like the trees that grow tall and protect us, faeries dance and dart and declare their desires directly. Despite these differences, we stand together. Learning, growing, evolving. We will help you and yours achieve the same symbiotic serenity.",objectivesText="Capture Nuuminuuru 's memory.",rewardGold=257400,rewardItems={182969},starts={{npcID=173710}},ends={{npcID=168430}},coords={x=0.514,y=0.336,source="quest_giver",zoneID=11510},questType="standard"},
[61363] = {id=61363,name="Mad Mortimer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst. If we lend him aid, he has agreed to allow you to capture his memory for the Path.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61364] = {id=61364,name="Oozing with Opportunity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1536,description="They called me mad! As a matter of fact, they still do! Ah, but none of them have the mental acuity of Doctor James Mortimus of the very much in-tact House of Plagues, nor his handsome smile! Fools! With the catalyst you have so kindly provided, dear...whatever you are...certainly not a kyrian... I digress! We shall get to whatever it is you wanted in a moment, for now is the time of SCIENCE! Come, come, let me show you the wondrous fruits of my labors!",objectivesText="Aid Mad Mortimer in his experiment, then capture his memory using the Soul Mirror .",rewardXP=8165,rewardItems={181460},starts={{npcID=172141}},ends={{npcID=168430}},coords={x=0.592,y=0.72,source="quest_giver",zoneID=11462},questType="standard"},
[61365] = {id=61365,name="Splinterbark Nightmare",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald. If we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon , we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61366] = {id=61366,name="Tactical Operation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1533,description="Your target lies near the Oaken Assembly in Ardenweald on the Elder Strand. Take caution, for powerful drust forces lurk nearby. Once your target is in sight, activate the beacon and protect the praetors that arrive as they work to subdue the beast. You will only be able to capture its memory once it has been fully incapacitated. Make haste, and good luck. Follow the path.",objectivesText="Activate the Praetor Resonance Beacon at the Splinterbark Nightmare at the Elder Strand in Ardenweald, protect the praetors, then capture the Splinterbark Nightmare's memory.",rewardGold=257400,rewardItems={182467},starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61367] = {id=61367,name="Thran'tiok",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. Training against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61368] = {id=61368,name="Filching Phylacteries",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1536,description="This phylactery holds the soul of Thran'tiok... her very essence. Be quick in whatever you need to do. I must get this piece of her soul away from here before she returns. Her paranoia shall truly be her end.",objectivesText="Capture Thran'tiok's memory through the Phylactery of Pain.",rewardGold=257400,rewardItems={182965},starts={{npcID=173495}},ends={{npcID=168430}},coords={x=0.538,y=0.488,source="quest_giver",zoneID=11462},questType="standard"},
[61369] = {id=61369,name="Craven Corinth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward. His memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61370] = {id=61370,name="No Other Way",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=9042,mapID=1533,description="Corinth will not surrender his memory willingly. You must weaken him sufficiently before he will relent to the soul mirror 's energy. You will find him deep within the Desiccation in Revendreth, locked away among the other light-scarred venthyr. Once you free him, he will surely attack in his confused rage. Subdue him, and capture his memory. He may then roam free among his kind.",objectivesText="Subdue Craven Corinth in the Desiccation in Revendreth, then capture his memory.",rewardGold=257400,rewardItems={182479,182623},starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61371] = {id=61371,name="Athanos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,objectivesText="Progress: For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos. It has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard . The blade was disassembled upon his departure, as is tradition. Should Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.",rewardGold=257400,rewardXP=8165,starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61372] = {id=61372,name="Back to Him",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Even with Humility's Guard in hand, if you are to convince Athanos to join the Path of Ascension once more then you must prove yourself a worthy adversary. Enter the ring and wield the spear against him. Even with its power you cannot hope to defeat him, but it should be able to parry his mighty stomp. Thwart his assault for long enough, and he will surely allow you to capture his memory.",objectivesText="Block Athanos' Power Stomp 6 times, then capture his memory.",rewardGold=257400,rewardItems={181472},starts={{npcID=175295}},ends={{npcID=168430}},coords={x=0.516,y=0.808,source="quest_giver",zoneID=10534},questType="standard"},
[61373] = {id=61373,name="Azaruux, the Realm Ender",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="You must act at once! A devourer of incredible strength has opened a rift in the coliseum and even now threatens to consume it! What few fighters were present at the time struggle to keep the creature at bay. If this horror is not stopped, it will continue into the rest of the spires. You must take what anima you can in the area and subdue it. Once the threat has been negated, take this spare mirror and capture its memory so we may learn more of its kind for future encounters.",objectivesText="Absorb anima to activate the Anima Confluxes to subdue Azaruux, then capture its memory. Progress: You must not delay!",rewardGold=257400,rewardItems={181795},starts={{npcID=168430}},ends={{npcID=168430}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61388] = {id=61388,name="A Journey Made Together",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Binding souls is but the first step. Over time, the power of our bond will grow in strength and manifest itself in the form of amazing new abilities! To tap into this newfound strength, all you must do is place your hand upon the Forge of Bonds. There is no price to pay--the only limitation is your connection to Necrolords.",objectivesText="Activate a Soulbind Power using the Forge of Bonds. Progress: This device is merely a conduit to the strength that lies within us both.",rewardGold=128700,rewardXP=4085,rewardItems={180847,181373,181467,181469,181512,181553,181707,181770,181840,181962,181981,182106,182108,182113,182133,182292,182317,182324,182336,182339,182346,182442,182448,182460,182466,182469,182584,182706,182770,182961,183466,183467,183472,183493,183496,183500},starts={{npcID=161904}},ends={{npcID=161904}},coords={x=0.39,y=0.328,source="quest_giver",zoneID=12876},questType="standard"},
[61391] = {id=61391,name="The Eye of the Jailer",level=55,requiredLevel=55,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Yes... I remember you... Do you think that because you evaded my grasp once, that I would let it happen again? No. The Maw answers to me. All that befalls you here will be because I willed it so. Death comes for you, mortal. Everywhere you go, my eye is upon you.",objectivesText="Speak with Ve'nari about what you just heard.",rewardGold=25740,rewardXP=935,questType="standard"},
[61394] = {id=61394,name="Gormling Toss: Tranquil Pools",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={181284},rewardCurrencies={{id=1885,amount=3}},questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=168254,text="Wayward Gormlings knocked down and bagged"},{orderIndex=0,type=0,amount=1,objectID=172175,text="Gormling in a Bag acquired"}},worldTaskTitle="Gormling Toss: Tranquil Pools",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61395] = {id=61395,name="Spare Parts",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,starts={{npcID=172157}},questType="standard"},
[61396] = {id=61396,name="Dark Developments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential! Now, if subject number one-three-five succeeds in a proper wing transplant at last...",objectivesText="Bring the Abhorrent Design to Artemede . Provided item:",rewardGold=25740,rewardXP=1020,rewardItems={181285},starts={{npcID=355825}},ends={{npcID=168744}},coords={x=0.335,y=0.242,source="quest_giver",zoneID=11462},questType="standard"},
[61397] = {id=61397,name="Opportunity Strikes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="This sanctum cannot function on anima alone. It will take many willing souls working in harmony to unlock the full potential of the Seat of the Primus. Our Soul Warden is always in search of new souls to induct into the sanctum. Your ability to travel back and forth from the Maw will undoubtedly prove useful to him. You should pay him a visit to see what assistance you can offer.",objectivesText="Speak to Osbourne Black .",rewardGold=25740,rewardXP=1020,starts={{npcID=161909}},ends={{npcID=167748}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[61398] = {id=61398,name="Ember Court: Traditional",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,description="Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court. Venthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity. Our resources are stretched thin, . We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom . There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.",rewardGold=257400,rewardXP=8165,rewardItems={181473},starts={{npcID=156822,x=0.614,y=0.638,zoneID=10413}},ends={{npcID=156822,x=0.614,y=0.638,zoneID=10413}},coords={x=0.614,y=0.638,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Traditional"},
[61399] = {id=61399,name="Ember Court: Mortal Reminders",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=2717,mapID=1670,description="For a reasonable renumeration, Ta Cartel can supply the decorations you require. Restocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer. Your world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.",rewardGold=257400,rewardXP=8165,rewardItems={181336,181354,181356,181367},questType="world",worldTaskTitle="Ember Court: Mortal Reminders"},
[61400] = {id=61400,name="Ember Court: Mystery Mirrors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I support Prince Renathal's efforts and will certainly help the Ember Court! Mystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time. You will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.",rewardGold=257400,rewardXP=8165,rewardItems={182097,183912,183919},starts={{npcID=172986,x=0.246,y=0.504,zoneID=10413}},ends={{npcID=172986,x=0.246,y=0.504,zoneID=10413}},coords={x=0.246,y=0.504,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Mystery Mirrors"},
[61401] = {id=61401,name="Ember Court: Venthyr Volunteers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh, hello again! Did you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits. I need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.",rewardGold=257400,rewardXP=8165,rewardItems={181716},starts={{npcID=172614,x=0.61,y=0.394,zoneID=10413}},ends={{npcID=172614,x=0.61,y=0.394,zoneID=10413}},coords={x=0.61,y=0.394,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Venthyr Volunteers"},
[61402] = {id=61402,name="Ember Court: Stoneborn Reserves",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them. We will also need weapons for them. Sort that out and I will make sure the Prince and his guests are well protected.",rewardGold=514800,rewardXP=10205,rewardItems={181500},starts={{npcID=172502,x=0.264,y=0.292,zoneID=10413}},ends={{npcID=172502,x=0.264,y=0.292,zoneID=10413}},coords={x=0.264,y=0.292,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Stoneborn Reserves",db2QuestInfoID=1,db2QuestInfoName="Group"},
[61403] = {id=61403,name="Ember Court: Maldraxxus Army",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8501,mapID=1536,description="So your prince's little parties have attracted unwanted attention? Emeni laughs.> I have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards! But I have finally found a solution. Take this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.",rewardGold=257400,rewardXP=8165,rewardItems={176140},starts={{npcID=172964,x=0.542,y=0.692,zoneID=11462}},ends={{npcID=172964,x=0.542,y=0.692,zoneID=11462}},coords={x=0.542,y=0.692,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Ember Court: Maldraxxus Army"},
[61404] = {id=61404,name="Ember Court: Tubbins's Tea Party",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1525,description="Theotar need tea for party? Tubbins make best! Special tea. Very special. Only I can make. Recipe need very good water from garden place. Good pool on special floaty island! You go get and Tubbins makes tea!",rewardGold=514800,rewardXP=10205,rewardItems={181370,183943},starts={{npcID=167863,x=0.31,y=0.576,zoneID=10413},{npcID=173299,x=0.312,y=0.574,zoneID=10413}},ends={{npcID=167863,x=0.31,y=0.576,zoneID=10413},{npcID=173299,x=0.312,y=0.574,zoneID=10413}},coords={x=0.31,y=0.576,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Tubbins's Tea Party",db2QuestInfoID=1,db2QuestInfoName="Group"},
[61405] = {id=61405,name="Ember Court: Divine Desserts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Recipes very important. Must not be lost! I learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn. I bring desserts to Ember Court. Fair, yes?",rewardGold=257400,rewardXP=8165,rewardItems={176135},starts={{npcID=172448,x=0.34,y=0.666,zoneID=10534}},ends={{npcID=172448,x=0.34,y=0.666,zoneID=10534}},coords={x=0.34,y=0.666,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Ember Court: Divine Desserts"},
[61406] = {id=61406,name="Ember Court: Mushroom Surprise!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court! Hmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me. Let's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps . You'll need to grapple your way up there.",rewardGold=257400,rewardXP=8165,rewardItems={181828,181829,181830,181839},starts={{npcID=168429,x=0.402,y=0.412,zoneID=11462}},ends={{npcID=168429,x=0.402,y=0.412,zoneID=11462}},coords={x=0.402,y=0.412,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Ember Court: Mushroom Surprise!"},
[61407] = {id=61407,name="Ember Court: Atoning Rituals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement. However, I must ask for your assistance preparing the necessary components quickly. Capture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose. Sinstone fragments will also help us identify the sins of these lost souls.",rewardGold=257400,rewardXP=8165,rewardItems={176130},starts={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},ends={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Atoning Rituals"},
[61408] = {id=61408,name="Ember Court: Glimpse of the Wilds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It would be wonderful to show Revendreth the wild creatures of Ardenweald! You can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. Here's a net to use to subdue the Territorial Waders. They should follow you once you've caught them. Highland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly. We will get others to help too. This sounds like fun.",rewardGold=257400,rewardXP=8165,rewardItems={183944},starts={{npcID=172352,x=0.562,y=0.556,zoneID=11510}},ends={{npcID=172352,x=0.562,y=0.556,zoneID=11510}},coords={x=0.562,y=0.556,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Ember Court: Glimpse of the Wilds"},
[61411] = {id=61411,name="Our Heart Will Go On",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={181284},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=172185,text="Speak to Zayhad"},{orderIndex=1,type=0,amount=12,objectID=172193,text="Drust invaders slain"},{orderIndex=2,type=0,amount=3,objectID=172278,text="Good memories collected"},{orderIndex=3,type=0,amount=1,objectID=172266,text="Scene 01 Complete"},{orderIndex=13,type=0,amount=1,objectID=172283,text="Return good memories to Zayhad"},{orderIndex=4,type=0,amount=1,objectID=172267,text="Scene 02 Complete"},{orderIndex=5,type=0,amount=1,objectID=172268,text="Scene 03 Complete"},{orderIndex=6,type=0,amount=1,objectID=172269,text="Scene 04 Complete"},{orderIndex=7,type=0,amount=1,objectID=172270,text="Scene 05 Complete"},{orderIndex=8,type=0,amount=1,objectID=172271,text="Scene 06 Complete"},{orderIndex=9,type=0,amount=1,objectID=172272,text="Scene 07 Complete"},{orderIndex=10,type=0,amount=1,objectID=172273,text="Scene 08 Complete"},{orderIndex=11,type=0,amount=1,objectID=172274,text="Scene 09 Complete"},{orderIndex=12,type=0,amount=1,objectID=172280,text="Zayhad spoken to"}},worldTaskTitle="Our Heart Will Go On",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61412] = {id=61412,name="An Early End",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Within the Hall of Chains lie more constructs that are nearly complete. As we speak, the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages. If they are allowed to finish their work, then the destruction we have wrought thus far will make little difference in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost. That must not come to pass. Destroy any of these abominations you encounter.",objectivesText="Destroy 6 Inert Butchers .",rewardGold=257400,rewardXP=8165,starts={{npcID=168743}},ends={{npcID=168743}},coords={x=0.352,y=0.26,source="quest_giver",zoneID=11462},questType="standard"},
[61414] = {id=61414,name="Faulty Fireworks (+Safe)",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: < Prince Renathal looks at the Flimsy Firework you're carrying with great concern.> This cheap party favor could send all of Sinfall up in flames!",starts={{npcID=164965}},ends={{npcID=164965}},coords={x=0.474,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
