[61433] = {id=61433,name="Giant Lungcap",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: Is that... a lungcap? How did you possibly find one of those here in Revendreth ? No matter. Throw it on a platter! Perhaps they will not notice how terrible it tastes.",starts={{npcID=165500}},ends={{npcID=165500}},coords={x=0.328,y=0.578,source="quest_giver",zoneID=10413},questType="standard"},
