[61436] = {id=61436,name="Field Trip",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1533,description="Now that you have the catalyst, you need only bring it to Mortimer in Maldraxxus. Our last correspondence indicates that his laboratory is still in-tact within the former House of Plagues. Exercise caution in your journey--what remains of the house is fraught with danger, and Mortimer himself has earned a less than pristine reputation among his peers.",objectivesText="Bring the Catalyst of Creation to Mad Mortimer in the House of Plagues in Maldraxxus. Provided item:",rewardGold=25740,rewardXP=1020,rewardItems={181470},starts={{npcID=168430}},ends={{npcID=172141}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
