[61469] = {id=61469,name="Tailoring: Woven Gossamer Tunic",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={181971,182102,182103,182104},questType="world",db2Objectives={{orderIndex=1,type=1,amount=1,objectID=181971,text="Craft a Woven Gossamer Tunic"},{orderIndex=0,type=0,amount=1,objectID=173159,text="Gather materials from the Crafter's Crate"}},worldTaskTitle="Tailoring: Woven Gossamer Tunic",db2QuestInfoID=121,db2QuestInfoName="Tailoring World Quest"},
[61473] = {id=61473,name="Sourcing Your Own Materials",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="I can aid you in crafting many pieces of equipment for your soulbinds. Though they may only equip one at a time, each piece grants a new ability that they may not have without it. This time you must source your own materials from around the Shadowlands. When you have collected them, return to me and we can create the footpads!",objectivesText="Craft the Herald's Footpads with Dactylis . Check the materials in the crafting window to learn where you can gather them. Progress: You find materials okay? Blueprint can help!",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1819,amount=5}},starts={{npcID=168430}},ends={{npcID=171816}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61475] = {id=61475,name="The Heart of the Forest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="I knew we were gonna get along! Welcome to our covenant. Well, almost. There's just a few details left. Little things. You know. Oaths to be made, blood pacts to sort out, firstborns to be promised. I'm just kidding! Well, not about the oaths part. We take those seriously around here. I'll meet you at the camp outside the Heart of the Forest!",objectivesText="Meet Lady Moonberry at the Refugee Camp beside the Heart of the Forest in Ardenweald.",rewardGold=25740,rewardXP=1020,starts={{npcID=172431}},ends={{npcID=172431}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="standard"},
[61477] = {id=61477,name="Calling the Champions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=172318,text="Light the Flame of Challenge"},{orderIndex=2,type=2,amount=1,objectID=355859,text="Plague Brazier"},{orderIndex=3,type=2,amount=1,objectID=355929,text="Lich Brazier"},{orderIndex=4,type=2,amount=1,objectID=355930,text="Eyes Brazier"},{orderIndex=5,type=2,amount=1,objectID=355932,text="Construct Brazier"},{orderIndex=6,type=2,amount=1,objectID=355931,text="Warlords Brazier"},{orderIndex=1,type=2,amount=1,objectID=355924,text="Seat Start"}},worldTaskTitle="Calling the Champions",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61478] = {id=61478,name="Humble Beginnings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With Humility's Guard whole once more, you may be able to coax Athanos back into the arena. Travel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone --she guides all those who seek an encounter with Athanos. Present the spear to her. She will know your intent and instruct you further.",objectivesText="Bring Humility's Guard to Forgelite Sophone in Aspirant's Crucible. Progress: What is that you have there?",rewardGold=25740,rewardXP=1020,rewardItems={181471},starts={{npcID=168430}},ends={{npcID=175295}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61479] = {id=61479,name="The Boon of Shapes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Mortal though you are, you have chosen to become one of our champions. While you uphold our cause, we are obligated to extend hospitality to you within our sacred hall and grant you certain boons. As a member of the Court of Night, I can bestow our powers on chosen mortals. , of Azeroth, I bid you welcome to the first tree, Tirna Achiad, the Heart of the Forest. Please, follow me.",objectivesText="Accompany Lady Moonberry into the Heart of the Forest and take part in the ceremony. Progress: Accept this boon and use it for the benefit of Ardenweald.",rewardGold=128700,rewardXP=4085,starts={{npcID=172431}},ends={{npcID=172431}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="standard"},
[61485] = {id=61485,name="I'll Only Say This Once",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="At last, we are fully prepared to enact the baroness's plan. Now that you have arrived, I will recount our roles one final time. Then we will seize our fate. Listen closely.",objectivesText="Speak with Whisperer Vyn about the plan.",rewardGold=128700,rewardXP=4085,starts={{npcID=160518}},ends={{npcID=172574}},coords={x=0.506,y=0.156,source="quest_giver",zoneID=11462},questType="standard"},
[61486] = {id=61486,name="The Banshee's Champion",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1519,mapID=84,description="I... we... I mean... he's... We found him. We found the Blightcaller. I was on patrol like I'd done a hundred times before only there he was sitting on the front porch of that old house with those terrible dogs and I swear he smirked at me and stared with those fiery red eyes and-- He's at the Marris Stead. Our forces have him surrounded, but, uh... You should probably gather your friends. I don't think he plans to surrender.",objectivesText="Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands. Progress: What news do you bring of the Blightcaller?",rewardGold=772200,rewardXP=10225,rewardCurrencies={{id=1754,amount=5}},starts={{npcID=172510}},ends={{npcID=167329}},coords={x=0.656,y=0.768,source="quest_giver",zoneID=1519},questType="standard"},
[61488] = {id=61488,name="The Banshee's Champion",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Word has reached us of... well, I'm not quite sure how to put it... The Blightcaller has been found. Horde forces have been scouring Azeroth for any sign of him. Determined to make him answer for his crimes. One of our Argent patrols has found him. Not hiding in some distant land. Just... waiting at his old homestead. We have him surrounded, but, uh, I confess I don't like our odds. Perhaps you could gather your allies and bring him to justice.",objectivesText="Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.",rewardGold=772200,rewardXP=10225,rewardCurrencies={{id=1754,amount=5}},starts={{npcID=172514}},ends={{npcID=169928}},coords={x=0.528,y=0.772,source="quest_giver",zoneID=1637},questType="standard"},
[61489] = {id=61489,name="Of Hearsay and Heresy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1533,description="Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus. Bring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger. Good luck, Maw Walker.",objectivesText="Find Echthra in the House of Eyes in Maldraxxus. Progress: Be cautious. There are many in the House of Eyes who would not tolerate your presence.",rewardGold=257400,rewardItems={181706},starts={{npcID=168430}},ends={{npcID=172515}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61490] = {id=61490,name="War of Information",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ah, the anointment oil. I had expected one of Adrestes' recruits. No matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice. With our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end. Information is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions. Then can we resolve payment.",objectivesText="Place Eyes of Hatred in the House of Rituals in Maldraxxus, Eonian Archives in Bastion, Tirna Vaal in Ardenweald, and Castle Nathria in Revendreth. Progress: There will be no negotiation in this matter.",rewardGold=257400,rewardItems={181683,181699},starts={{npcID=172515}},ends={{npcID=172515}},coords={x=0.566,y=0.116,source="quest_giver",zoneID=11462},questType="standard"},
[61492] = {id=61492,name="The Princeguard",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Renathal carries himself well, but hides great pain. His wounds from Denathrius have not healed. He is vulnerable. He intends to send you to secure his old fortress of Darkwall Tower with banners and rely on his own strength to deter enemies. This is a poor tactical choice. Take this small reserve of anima with you and revive Chelra the Bladewall . She was last seen at Darkwall. Revive her and she can aid you in taking the tower.",objectivesText="Revive Chelra the Bladewall and drive enemies out of Darkwall Tower. Progress: I have suffered in stillness for months. I worried I would never wake again.",rewardGold=257400,rewardXP=8165,rewardItems={181516},starts={{npcID=161977}},ends={{npcID=161977}},coords={x=0.464,y=0.16,source="quest_giver",zoneID=10986},questType="standard"},
[61509] = {id=61509,name="Shinies of Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy is bored, boooored! You want to go look for luckydos? Go on adventure with Chordy ? We go to land of wing people, go look for valuable luckydos there. Ready?",rewardXP=8165,rewardItems={174101,178554},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Shinies of Bastion"},
[61510] = {id=61510,name="A Bountiful Haul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy want to go on adventure! You want to go too, yes? I scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days. We go to land of tree people! If we search together, we'll find many luckydos!",rewardXP=8165,rewardItems={174101,178554},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="A Bountiful Haul"},
[61511] = {id=61511,name="Things They Leave Behind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy bored. Chordy want to go on adventure! You want to go too, yes? Pale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves! You ready to go?",rewardXP=8165,rewardItems={174101,178554},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Things They Leave Behind"},
[61518] = {id=61518,name="Follow Me",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Assuming the others are in position, we are prepared to steal the necropolis. You and I must push forward to rendezvous with Ansid. Khaliiq will regroup with Vyn once their tasks are complete. Come along, $p, and stay near. I will shroud the both of us in shadow, so long as you are at my side.",objectivesText="Follow Navigator Xennir to the rendezvous point. Progress: Keep your eyes open.",rewardGold=257400,rewardXP=8165,starts={{npcID=172574}},ends={{npcID=172574}},coords={x=0.318,y=0.402,source="quest_giver",zoneID=11462},questType="standard"},
[61520] = {id=61520,name="Enemy of My Mnemis",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={181710,181711},questType="world",db2Objectives={{orderIndex=10,type=0,amount=1,objectID=172615,text="Forge-Keeper Mnemis activated"},{orderIndex=2,type=15,amount=1,objectID=0,text="Charge the core"},{orderIndex=1,type=0,amount=1,objectID=172617,text="Charge the core"}},worldTaskTitle="Enemy of My Mnemis",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61522] = {id=61522,name="Corpse Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?",rewardXP=8165,rewardItems={183744,182483,182492,182501,182510,184843},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=158300,x=0.542,y=0.68,zoneID=11462},{npcID=158300,x=0.332,y=0.546,zoneID=11400}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Corpse Run"},
[61523] = {id=61523,name="Corpse Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?",rewardXP=8165,rewardItems={183744,182483,182492,182501,182510,184843},starts={{npcID=158300,x=0.332,y=0.546,zoneID=11400},{npcID=158300,x=0.542,y=0.68,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.332,y=0.546,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Corpse Run"},
[61524] = {id=61524,name="The Ember Court",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!",objectivesText="Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.",rewardGold=772200,rewardXP=12250,ends={{npcID=164966}},coords={mapID=1525,source="quest_giver",x=0.28,y=0.43},questType="standard"},
[61525] = {id=61525,name="The Ember Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!",objectivesText="Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests. Progress: I can't wait to see who attends today's court!",rewardGold=772200,rewardXP=12250,rewardItems={179958},starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61526] = {id=61526,name="The Ember Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!",objectivesText="Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests. Progress: I can't wait to see who attends today's court!",rewardGold=772200,rewardXP=12250,rewardItems={179958},starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
