[61540] = {id=61540,name="Just Winging It",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=172658,text="Flayedwing tamed"},{orderIndex=0,type=0,amount=1,objectID=172871,text="Flayedwing ridden"}},worldTaskTitle="Just Winging It",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61541] = {id=61541,name="The Forge of Bonds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description=", are you ready for another gift? The next boon we grant thee is one of bonds. As you have bound yourself to us, we shall bind to you. In the binding of souls, we become something greater. Sounds scary, huh? Don't worry! You and your soulbind will both strengthen each other. When I asked for volunteers, many fae stepped forward. I picked someone I just know you're going to like. And this will be a boon for her, too. Go to Flutterby . She'll help you both.",objectivesText="Meet Flutterby at the Forge of Bonds.",rewardGold=25740,rewardXP=1020,starts={{npcID=172431}},ends={{npcID=158553}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="standard"},
[61542] = {id=61542,name="The Boon of Binding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Flutterby clasps her hands before her and assumes an air of tranquility.> Soulbinding is not an irrevocable act. However, such a bond must be carefully considered before it is made. You and your soulbind will know each other's hearts and minds. Your hopes and fears; your dreams and memories; all will be shared between you. As long as the bond exists, you are intertwined; always together even when apart. Once complete, your connection will transcend physical space and empower you both.",objectivesText="Complete the soulbinding ritual. Progress: When you are ready, we may proceed.",rewardGold=257400,rewardXP=8165,starts={{npcID=158553}},ends={{npcID=172677}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[61543] = {id=61543,name="Herbalism: Lambent Vigil's Torch",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={181757},questType="world",worldTaskTitle="Herbalism: Lambent Vigil's Torch",db2QuestInfoID=119,db2QuestInfoName="Herbalism World Quest"},
[61544] = {id=61544,name="Herbalism: Lush Widowbloom",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={181762},questType="world",worldTaskTitle="Herbalism: Lush Widowbloom",db2QuestInfoID=119,db2QuestInfoName="Herbalism World Quest"},
[61545] = {id=61545,name="Herbalism: Engorged Marrowroot",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={181388},questType="world",worldTaskTitle="Herbalism: Engorged Marrowroot",db2QuestInfoID=119,db2QuestInfoName="Herbalism World Quest"},
[61548] = {id=61548,name="Set Me Free",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ansid has been captured and imprisoned by the foundry's guards. It seems they were expecting us, completely shattering the element of surprise. My baroness would be disappointed in my lack of foresight. This plan cannot succeed without Ansid. One of these soldiers is bound to possess the key to his cage. Should you find it, we may yet carry out my baroness's will.",objectivesText="Find the Ossein Key on one of the Ossein Strongarms and use it to free Ansid. Progress: Take caution.",rewardGold=257400,rewardXP=8165,rewardItems={181785},starts={{npcID=172573}},ends={{npcID=172573}},coords={x=0.296,y=0.44,source="quest_giver",zoneID=11462},questType="standard"},
[61549] = {id=61549,name="Drought Conditions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=172703,text="Etherwyrms slain"},{orderIndex=1,type=0,amount=8,objectID=172714,text="Caretakers evacuated"}},worldTaskTitle="Drought Conditions",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61550] = {id=61550,name="Strengthening the Bond",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="I know how you feel... and what you have endured for the sake of your world. You now know of my own triumphs and tragedies as well. Our bond will grow stronger over time. But for now, let us see what it has granted us. Ardenweald has needs of us. We must do everything in our power to save it.",objectivesText="Activate a Soulbind Power using the Forge of Bonds. Progress: We are stronger together.",rewardGold=257400,rewardXP=8165,rewardItems={180847,181373,181467,181469,181512,181539,181707,181775,181840,181962,182106,182108,182113,182129,182133,182317,182324,182335,182336,182347,182448,182460,182466,182469,182584,182651,182767,182964,183199,183463,183466,183467,183473,183494,183496,183500},starts={{npcID=172677}},ends={{npcID=172677}},coords={x=0.332,y=0.468,source="quest_giver",zoneID=12858},questType="standard"},
[61551] = {id=61551,name="Crush 'Em All",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us. Enforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered. She is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.",objectivesText="Use Ansid's Explosive to kill Enforcer Borgulla .",rewardGold=514800,rewardXP=10205,rewardItems={182250,182259,182268,182277},rewardChoices={182268,182259,182277,182250},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=172573}},ends={{npcID=172573}},coords={x=0.296,y=0.44,source="quest_giver",zoneID=11462},questType="standard"},
[61552] = {id=61552,name="The Hunt Watches",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets. Watcher Vesperbloom directs the eyes and ears of the forest. Seek out our new growth, then turn to her for guidance.",objectivesText="Activate Adventures then seek out Watcher Vesperbloom . Progress: Ah. You're here. Good.",rewardGold=25740,rewardXP=1020,starts={{npcID=165702}},ends={{npcID=164023}},questType="standard"},
[61553] = {id=61553,name="Know Where to Strike",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove. This is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen. Allow me to demonstrate...",objectivesText="Use the Command Table to send your forces on an adventure. Progress: Every victory furthers our cause.",rewardGold=25740,rewardXP=1020,starts={{npcID=164023}},ends={{npcID=164023}},coords={x=0.446,y=0.562,source="quest_giver",zoneID=11510},questType="standard"},
[61554] = {id=61554,name="The Play's The Thing",level=60,requiredLevel=60,faction="none",expansion=8,description="You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt. Before our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold. Lady Moonberry awaits you in the Sanctum Hall with more information. Break a leg.",objectivesText="Seek out Lady Moonberry in the Heart of the Forest central hall.",rewardGold=25740,rewardXP=1020,questType="standard"},
[61556] = {id=61556,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Party Crashers",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[61557] = {id=61557,name="An Echo in the Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="$p, I... I am beset by dark visions. A power emanating from within Torghast. A familiar sensation. One I have not felt since... Come to Oribos . Do not delay.",objectivesText="Meet Bolvar Fordragon in Oribos .",rewardGold=128700,rewardXP=1020,questType="standard"},
[61558] = {id=61558,name="The Highlord's Vision",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=10565,mapID=1670,description="Thrall 's brow is furrowed.> We were speaking with the Highlord when he was struck by a jolt of agony. He said he could see something stirring in the Maw. Inside the Jailer's tower. The pain seems to be getting worse. We need to find out what he's sensing.",objectivesText="Find out what Bolvar senses inside Torghast. Progress: We must know the truth.",starts={{npcID=171362}},ends={{npcID=171362}},questType="standard"},
[61559] = {id=61559,name="A Mourneblade Born",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=10565,mapID=1670,description="While his father was missing, I cared for Anduin like a son. To see him like that, at the mercy of Sylvanas... Something must be done. Take a moment. Let me know when you are ready to discuss what comes next.",objectivesText="Discuss the vision with Bolvar and the others.",starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[61564] = {id=61564,name="Blacksmithing: Polished Kyrian Shield",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={181790,181791,181792,181793},questType="world",db2Objectives={{orderIndex=1,type=1,amount=1,objectID=181791,text="Craft a Polished Kyrian Shield"},{orderIndex=0,type=0,amount=1,objectID=173152,text="Gather materials from the Crafter's Crate"}},worldTaskTitle="Blacksmithing: Polished Kyrian Shield",db2QuestInfoID=116,db2QuestInfoName="Blacksmithing World Quest"},
[61567] = {id=61567,name="Grave Intent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="My spies have identified several astral projectors that Margrave Gharmal uses to rally their troops in the Stitchyard. I do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor. See to it that these projectors are destroyed. We believe them to be along the yard's perimeter.",objectivesText="Destroy the Southwestern, Northwestern, and Notheastern Astral Projectors .",rewardGold=257400,rewardXP=8165,starts={{npcID=167173}},ends={{npcID=167173}},coords={x=0.286,y=0.376,source="quest_giver",zoneID=11462},questType="standard"},
[61569] = {id=61569,name="Keys to the Ruin",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="At last, our target is within reach. The necropolis rests above us, moored to this platform by a necrotic restraining bolt. Twigin can fly you to the apex of the necropolis. It will be ours to command once you insert this keystone. We will prepare for our departure. Rejoin us when you are done. Victory will soon be ours.",objectivesText="Fly with Twigin to the necropolis's apex and plug in the Runic Keystone. Progress: Our mission is nearly complete.",rewardGold=514800,rewardXP=10205,starts={{npcID=172805}},ends={{npcID=172573}},coords={x=0.3,y=0.436,source="quest_giver",zoneID=11462},questType="standard"},
[61586] = {id=61586,name="Machinations of War",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="With Bastion as our ally, we have the strength to crush Gharmal and the House of Constructs. We'll gather the supplies for the attack, but our soldiers need a great champion to follow into battle. Prove to them that you are the champion they seek.",objectivesText="Increase your Renown.",rewardGold=25740,rewardXP=1020,starts={{npcID=166535}},ends={{npcID=161907}},coords={x=0.504,y=0.706,source="quest_giver",zoneID=11462},questType="standard"},
[61593] = {id=61593,name="A Crisis of Memory",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=3,type=0,amount=1,objectID=173917,text="Enter the large cave"}},worldTaskTitle="A Crisis of Memory",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61594] = {id=61594,name="This Way Out",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We are fully prepared to launch the necropolis. We must hurry before Margrave Gharmal tries to interfere. Speak with Vyn when you are prepared, but we mustn't waste time. We will cast our shadow upon all of Maldraxxus .",objectivesText="Tell Whisperer Vyn to launch the necropolis.",rewardGold=25740,rewardXP=1020,starts={{npcID=172573}},ends={{npcID=172805}},coords={x=0.296,y=0.44,source="quest_giver",zoneID=11462},questType="standard"},
