[61616] = {id=61616,name="The Ember Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We've got everything we need to host our first real Ember Court whenever you're ready, Maw Walker. Take a moment to finalize everything, and then we'll open court! Remember, we're trying to impress Cryptkeeper Kassir and convince him that we know what we're doing, so make sure you choose the refreshments and entertainment we hired for him! Once everything's ready, let me know and I'll open the court!",objectivesText="Finalize your guest and amenity selections for the Ember Court, then do your best to impress your guest. Progress: Cryptkeeper Kassir is going to love this!",rewardGold=772200,rewardXP=12250,rewardItems={176850,179958},rewardChoices={181536},starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
