[61626] = {id=61626,name="Leatherworking: Courtly Leather Boots",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={181967,182053,182054,182055},questType="world",db2Objectives={{orderIndex=1,type=1,amount=1,objectID=181967,text="Craft Courtly Leather Boots"},{orderIndex=0,type=0,amount=1,objectID=173158,text="Gather materials from the Crafter's Crate"}},worldTaskTitle="Leatherworking: Courtly Leather Boots",db2QuestInfoID=117,db2QuestInfoName="Leatherworking World Quest"},
