[61628] = {id=61628,name="Tailoring: Looming Tapestry",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={181973,182050,182051,182052},questType="world",db2Objectives={{orderIndex=1,type=1,amount=1,objectID=181973,text="Craft a Looming Tapestry"},{orderIndex=0,type=0,amount=1,objectID=173159,text="Gather materials from the Crafter's Crate"}},worldTaskTitle="Tailoring: Looming Tapestry",db2QuestInfoID=121,db2QuestInfoName="Tailoring World Quest"},
[61629] = {id=61629,name="Enchanting: True Aim",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={181948,182020,182021},questType="world",db2Objectives={{orderIndex=2,type=1,amount=1,objectID=181948,text="Craft an Enchant: True Aim"},{orderIndex=0,type=0,amount=1,objectID=173154,text="Gather materials from the Crafter's Crate"},{orderIndex=1,type=14,amount=1,objectID=90598,text="Disenchant the Antique Kyrian Javelin"}},worldTaskTitle="Enchanting: True Aim",db2QuestInfoID=123,db2QuestInfoName="Enchanting World Quest"},
[61630] = {id=61630,name="Enchanting: Everburning Brand",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,rewardItems={181950,182066,182067},questType="world",db2Objectives={{orderIndex=2,type=1,amount=1,objectID=181950,text="Craft an Everburning Brand"},{orderIndex=0,type=0,amount=1,objectID=173154,text="Gather materials from the Crafter's Crate"},{orderIndex=1,type=14,amount=1,objectID=90600,text="Disenchant the Antique Duelist's Rapier"}},worldTaskTitle="Enchanting: Everburning Brand",db2QuestInfoID=123,db2QuestInfoName="Enchanting World Quest"},
[61631] = {id=61631,name="Drust Between You and Me",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=174729,text="Drust Forces Slain"}},worldTaskTitle="Drust Between You and Me",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61635] = {id=61635,name="Troubled Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!",objectivesText="Take the construct requests from the souls present.",rewardGold=128700,rewardXP=4085,starts={{npcID=167150}},ends={{npcID=167150}},coords={x=0.55,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[61637] = {id=61637,name="Unity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="A unique construct has chosen to join us, but its unethical creation leaves it most unsettled. The fusing of fragmented Kyrian souls within this construct, gives it pain and suffering. We must find a way to harmonize these souls so they can live together in peace. Create the Bindings of Wellbeing and bring ease to the Soulfused Construct.",objectivesText="Bring ease to the Soulfused Construct. Progress: Have you helped this construct?",rewardGold=128700,rewardXP=4085,starts={{npcID=167150}},ends={{npcID=167150}},coords={x=0.55,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[61638] = {id=61638,name="Iron Solution",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!",objectivesText="Take the construct requests from the souls present.",rewardGold=128700,rewardXP=4085,starts={{npcID=167150}},ends={{npcID=167150}},coords={x=0.55,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[61667] = {id=61667,name="Forged in Secret",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166753,text="Speak with the Forgemaster"},{orderIndex=1,type=0,amount=1,objectID=166954,text="Protect the Forgemaster"}},worldTaskTitle="Forged in Secret",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61689] = {id=61689,name="A Crisis of Memory",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=172872,text="Doubtful Acolytes subdued"},{orderIndex=1,type=0,amount=24,objectID=172909,text="Hostile memories slain"}},worldTaskTitle="A Crisis of Memory",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61697] = {id=61697,name="A New Age",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="With the final empowerment in place, our renewed Crest of Ascension stands bolstered by the might of not just Bastion , but all covenants. Soon new Ascended will grace these halls once more as aspirants finish their long-awaited trials. None of this would be possible without your aid, Maw Walker. The honor of activating the Crest at last is yours.",objectivesText="Activate the Crest of Ascension. Progress: This is a glorious moment for all kyrian.",rewardGold=772200,rewardXP=12250,rewardItems={180633,180766,181295},rewardChoices={180766},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=174177}},ends={{npcID=174177}},coords={x=0.436,y=0.662,source="quest_giver",zoneID=11012},questType="standard"},
[61699] = {id=61699,name="Not Much to Goo On",expansion=8,mapID=1536,rewardItems={177844},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="House of Plagues reclaimed"}},worldTaskTitle="Not Much to Goo On",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61701] = {id=61701,name="Searching the Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It is clear that a struggle took place here. I fear that Kivarr may have been taken by the Drust. I scouted the surrounding area before you arrived. Eventide Grove has been overrun. The Drust cannot have taken her far. We may yet be able to find her. I just pray that we are not too late...",objectivesText="Search for Kivarr at Eventide Grove in Ardenweald.",rewardGold=128700,rewardXP=4085,starts={{npcID=170705}},ends={{npcID=171413}},coords={x=0.46,y=0.566,source="quest_giver",zoneID=11510},questType="standard"},
[61702] = {id=61702,name="A Swift Intervention",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Drust just took Kivarr away. They said they were going to sacrifice her in one of their rituals! If we hurry, you may still be able to save her! I've seen where the Drust keep their sacrificial altar... it's scary, but I can take you there! There's no time to waste! Follow me!",objectivesText="Rescue Kivarr from Eventide Grove in Ardenweald.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173612}},ends={{npcID=171413}},coords={x=0.466,y=0.73,source="quest_giver",zoneID=11510},questType="standard"},
[61703] = {id=61703,name="Nox Root",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="In order to perform the ritual, I will need some nox root from Darkreach. It is a unique plant that only grows within soil that has been corrupted by Drust magic. Darkreach lies to the west, not far from my den. What was once a peaceful, verdant grove is now filled with blight and ruin. I will travel to the Heart of the Forest to prepare the ritual. Meet me there when you have gathered the nox root .",objectivesText="Collect 12 Nox Root from Darkreach in Ardenweald . Progress: Have you brought the reagents?",rewardGold=257400,rewardXP=8165,rewardItems={182958},starts={{npcID=171413}},ends={{npcID=171413}},coords={x=0.462,y=0.564,source="quest_giver",zoneID=11510},questType="standard"},
[61704] = {id=61704,name="Ember Court: Guest RSVPs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal will wish to invite certain guests to each Ember Court. In the future, we'll be able to adjust the guest list to make it easier to please everyone in attendance. But, we should follow the Prince's lead on this first one. Work with Lord Garridan and Lady Ilinca to ensure that Cryptkeeper Kassir is able to attend and returns his RSVP. If you haven't met Cryptkeeper Kassir yet in your adventures, you may need to introduce yourself before he'll listen to you.",objectivesText="Speak with Lord Garridan to see your Guest List, then meet Cryptkeeper Kassir to earn his RSVP.",rewardGold=257400,rewardXP=8165,rewardItems={179958},starts={{npcID=164966}},ends={{npcID=163073}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61705] = {id=61705,name="Ember Court: Refreshments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We should always serve refreshments in the Ember Court, tailoring our choice of refreshment type to the preferences of our guests. Luckily, I know our first guest well. Like Theotar, he prefers it to be Formal. Work with Picky Stefan to acquire everything we need to throw a fancy tea party.",objectivesText="Speak with Picky Stefan to see your Refreshment options, then complete Tubbins 's quest to earn the tea party contract.",rewardGold=257400,rewardXP=8165,starts={{npcID=164966}},ends={{npcID=167863},{npcID=173299}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61706] = {id=61706,name="Ember Court: Entertainment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Everyone loves entertainment! Our first guest is from the Halls of Atonement, so he will certainly appreciate a presentation of the powerful rituals the Accuser is capable of. Work with Hips to acquire everything we need to host atoning rituals at the Ember Court.",objectivesText="Speak with Hips to see your Entertainment options, then complete Gresit 's quest to earn the rituals contract.",rewardGold=257400,rewardXP=8165,starts={{npcID=164966}},ends={{npcID=167332}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61707] = {id=61707,name="Crumbled Reality",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="As the drought and devourers eat our buildin's, the structures lose their hold on reality. Thing is, it ain't a clean process. Some of that debris is still infused with anima. When your out, be a stoneback an' bring us whatever infused debris you can find. See, we can recycle it into new structures as you hero types go and get the anima flowin' again. Bring it here an we'll get it sorted.",objectivesText="Recover 100 Infused Rubble . Progress: Impressed 'ow much you can carry with 'em 'itty bitty arms.",rewardItems={182158},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173036}},ends={{npcID=173036}},coords={x=0.712,y=0.746,source="quest_giver",zoneID=10413},questType="standard"},
[61708] = {id=61708,name="Drawing Out the Poison",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardItems={174043},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=162224,text="Phylactery of Arin'gore found"},{orderIndex=0,type=0,amount=1,objectID=160917,text="Ride Grimshadow to the Flayedwing Nesting Grounds"},{orderIndex=2,type=0,amount=1,objectID=161292,text="Phylactery of Arin'gore destroyed"}},worldTaskTitle="Drawing Out the Poison",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61709] = {id=61709,name="Witch's Satchel",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I sent Ara'lon to steal a witch's satchel from the Drust... a dangerous task from which he has yet to return. The Drust's nightscreamers carry many reagents we need to perform the ritual. We cannot proceed without one. You must go to the Oaken Assembly to procure one of their satchels... and find Ara'lon, if you can.",objectivesText="Collect 1 Witch's Satchel from the Oaken Assembly in Ardenweald . Progress: Do you have the satchel? And what of Ara'lon?",rewardGold=257400,rewardXP=8165,rewardItems={182963},starts={{npcID=171413}},ends={{npcID=171413}},coords={x=0.462,y=0.564,source="quest_giver",zoneID=11510},questType="standard"},
[61710] = {id=61710,name="The Broken Spear",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Lord Herne will want to know of your discovery.>",objectivesText="Deliver the remains of Ara'lon's spear to Lord Herne at Heart of the Forest in Ardenweald . Progress: What news do you bring?",rewardGold=257400,rewardXP=8165,rewardItems={182966},starts={{npcID=357726}},ends={{npcID=170848}},coords={x=0.339,y=0.545,source="quest_giver",zoneID=11510},questType="standard"},
[61711] = {id=61711,name="Ritual of Purification",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I have finished making preparations for the ritual. The moment of truth has come. The Drust fetish that Ulfar gave you will channel the ritual's power into Gweyir. It should counteract the curse that imprisons her mind. This will not be pleasant. It may not even work. But this is the only chance we have to free her.",objectivesText="Complete the Ritual of Purification. Progress: The ritual is our only hope of freeing Gweyir. We must try...",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=171413}},ends={{npcID=171413}},coords={x=0.462,y=0.564,source="quest_giver",zoneID=11510},questType="standard"},
[61713] = {id=61713,name="Blueprint: Charm of Quickness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this charm.>",objectivesText="Bring the Blueprint: Charm of Quickness to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[61714] = {id=61714,name="Gilded Abacus",level=60,requiredLevel=60,faction="both",expansion=8,description="steward will appreciate this as not only a useful gift, but an exquisite one.>",objectivesText="Summon your steward companion via Summon steward , then give them the Gilded Abacus . Provided item:",questType="standard"},
[61715] = {id=61715,name="Request of the Highlord",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="The information you uncovered in Maldraxxus should quell the drums of war between the Necrolords and the Kyrian. And this message from the Primus... extraordinary! I would advise you to enlist Highlord Fordragon's counsel, but he appears preoccupied. Visitors from your world have come to seek him out. Quite insistently, I might add. The nuances of mortal interaction elude me. But it seems the nature of their dialogue was rather... intense. Perhaps you can assist the Highlord with this matter.",objectivesText="Speak to Bolvar Fordragon.",rewardGold=25740,rewardXP=850,starts={{npcID=162928}},ends={{npcID=162928}},questType="standard"},
[61716] = {id=61716,name="A Glimpse into Darkness",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="When I put the Lich King's crown upon my head, I wanted the world to believe I was dead. Even my daughter, Taelia. I... thought a lie would be kinder than the truth. But she is no longer the little girl I left in Kul Tiras. I see my choice was a selfish one. She and Lady Menethil have asked me to peer into the Maw to see if our allies yet live. It is a dangerous request, but one I cannot refuse. Help me focus on the broken helm. Together, we may find a glimpse of truth.",objectivesText="Witness Bolvar's vision of the Maw. Progress: There is much to do.",rewardGold=189240,rewardXP=6815,rewardItems={184165},starts={{npcID=173384}},ends={{npcID=173384}},questType="standard"},
[61717] = {id=61717,name="Gormling Piper: Tranquil Pools",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={182189},rewardCurrencies={{id=1885,amount=3}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=158969,text="Fae Flute acquired"},{orderIndex=1,type=0,amount=8,objectID=173074,text="Burrowing Gormlings coaxed and bagged"}},worldTaskTitle="Gormling Piper: Tranquil Pools",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61725] = {id=61725,name="Stolen Mementos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: I anticipate the timely return of our stolen merchandise, Maw Walker. Their pilfering leaves a blemish on what could otherwise be a perfectly satisfying event.",starts={{npcID=171449}},ends={{npcID=171449}},coords={x=0.426,y=0.738,source="quest_giver",zoneID=10413},questType="standard"},
[61728] = {id=61728,name="Valis the Cruel",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Valis the Cruel"},
[61729] = {id=61729,name="Adventurer: Rahel",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
[61730] = {id=61730,name="The Captive King",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="King Anduin has not been found inside Torghast. I fear we could spend eternity searching those endless corridors to no avail. We must know what fate has befallen him. To peer into the tower represents a grave risk, yet we have little choice. Stand with me, . We will use the broken Helm of Domination to see into that hellish place. Perhaps together we can hold back the hungry darkness.",objectivesText="Use the Helm of Domination to peer into Torghast. Progress: We must peer into Torghast before Anduin is lost to us.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1828,amount=250}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[61731] = {id=61731,name="Magical Curios",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: Curious. Most curious trinkets... May I keep to study? Will learn much.",starts={{npcID=171831}},ends={{npcID=171831}},coords={x=0.73,y=0.33,source="quest_giver",zoneID=10413},questType="standard"},
[61732] = {id=61732,name="Old Habits Never Die",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Your redistribution of anima has been commendable so far. But venthyr are still venthyr. They may spend eons educating souls on the folly of greed and hoarding, but they often fail to acknowledge the return of that trait in themselves, given enough time. My scouts have witnessed a number of venthyr siphoning the anima you have redistributed and hoarding it within their estates and dwellings. Search these places and recover this hoarded anima so that we might put it to better use.",objectivesText="Recover 10 Hoarded Anima Cages .",rewardItems={181176,181178,181181,181198,181201,181203,181206,181211,181216,181217,181545,181546,181547,181548,181550,181708,184147,184150,184777,185854},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173042}},ends={{npcID=173042}},coords={x=0.722,y=0.76,source="quest_giver",zoneID=10413},questType="standard"},
[61733] = {id=61733,name="Big Bag of Creepers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Right. You've been a polished bit of gray so far and it's appreciated from the bottom up for sure. Well, now I got a task for 'ou that would help all of us dredgers put that anima you obtained to good use. Creepers. Not just any creepers, but 'em mire creepers . 'Ey got a look about 'em and a taste about 'em that just sings when you put it to good use. As you go trippin' around Revendreth, grab any creepers ya find an' stick 'em in this here sack. I'll pay ya.",objectivesText="Collect 20 Mire Creepers . Progress: Creepers. 'Ey like chewin' on the mortar at holds all these walls up.",rewardItems={182583},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173127}},ends={{npcID=173036}},coords={x=0.714,y=0.744,source="quest_giver",zoneID=10413},questType="standard"},
[61734] = {id=61734,name="Census of Sins",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Curator once knew the contents and locations of every sinstone in Revendreth dating back to the founding of this realm. Sadly, her time in the Maw disrupted those essential parts of her vast intellect and we can no longer rely upon her for such knowledge. At least, not for a while. And so it falls to me to rebuild a 'living' archive. As you venture into Revendreth I would ask that you recover the contents and location of certain sinstones. This will help us orient our archive.",objectivesText="Inspect 7 Lost Sinstones.",rewardItems={181175,181176,181177,181179,181180,181182,181183,181184,181185,181191,181194,181196,181197,181198,181199,181200,181202,181204,181206,181207,181216,181217,181218,181224,181334,181545,181546,181547,181548,181550,182724,184147,184150,184777,185854,185942},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173532}},ends={{npcID=173532}},coords={x=0.722,y=0.758,source="quest_giver",zoneID=10413},questType="standard"},
[61735] = {id=61735,name="Awaken Our Allies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I have need of your services. I have identified a collection of stoneborn throughout Revendreth whom may be swayed to our cause, or were already members of our cause before returning to their stone slumber. You have provided us with the anima we needed, now it is time to put it to use. Seek out our allies and awaken them. I have fashioned an anima container for easier transport to aid in this endeavor. We need an army if we are to face an army.",objectivesText="Awaken 15 Allied Stoneborn.",rewardItems={182291},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173038}},ends={{npcID=173038}},coords={x=0.714,y=0.764,source="quest_giver",zoneID=10413},questType="standard"},
[61736] = {id=61736,name="Stolen Away",level=50,requiredLevel=50,faction="none",expansion=8,description="There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Whitemane. She can tell you the rest.",objectivesText="Speak to Sally Whitemane about the abductions.",rewardGold=23400,rewardXP=850,questType="standard"},
[61737] = {id=61737,name="Stolen Away",level=50,requiredLevel=50,faction="none",expansion=8,description="There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Nazgrim. He can tell you the rest.",objectivesText="Speak to Nazgrim about the abductions.",rewardGold=23400,rewardXP=850,questType="standard"},
[61738] = {id=61738,name="Ember Court: Lost Chalice Band",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw! The band is not quite ready to tour yet, however. The musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities! Noise complaints and all that. Help me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!",rewardGold=257400,rewardXP=8165,rewardItems={182302,182310,182311,182312},starts={{npcID=173173,x=0.55,y=0.438,zoneID=10413}},ends={{npcID=173173,x=0.55,y=0.438,zoneID=10413}},coords={x=0.55,y=0.438,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Lost Chalice Band"},
[61739] = {id=61739,name="The Wayward Baron",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It has come to my attention that you seek to uncover a plot by the baron Kel'Thuzad. That upstart has been a thorn in my side since he arrived at the House of Rituals. Not only did he pilfer my rightfully earned title, he has since shut me out of the house's dealings. I have yet to find evidence that would mar Sin'dane's adoration for her new baron, and thus I offer an arrangement. I grant you access to the House of Rituals, and in return you help me bring down Kel'Thuzad. Do we have an accord?",objectivesText="Open Balmedar's Supplies at the tower near the Scaplian Ridge.",rewardGold=25740,rewardXP=1020,starts={{npcID=173172}},ends={{npcID=173420}},coords={x=0.662,y=0.322,source="quest_giver",zoneID=11462},questType="standard"},
[61740] = {id=61740,name="Playing Favorites",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We will have to construct an illusion to allow you entry into the House of Rituals. However, not just any illusion will do. In order to join Kel'Thuzad's inner circle, we require something... specific. We're going to need a body. Fortunately for us, one of the baron's favorite acolytes is performing a ritual outside of the house itself. You'll need to fight your way to her, but of that I'm sure you're capable.",objectivesText="Defeat Acolyte Nelesis and bring her corpse back to the tower near Scaplian Ridge. Progress: Don't you have a corpse to procure?",starts={{npcID=173422}},ends={{npcID=173422}},questType="standard"},
[61741] = {id=61741,name="Pilfered Power",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1536,description="The illusion ritual will require a substantive amount of anima to complete. Since such a resource isn't simply lying around these days, we will need to take some. The abominations from the House of Constructs recently arrived with a delivery of anima-rich spoils from the raid on Bastion. Use the maldracite crystal I've included in the parcel to extract enough anima for our ritual.",objectivesText="Drain anima from the Kyrian Spoils in the House of Rituals to fill the maldracite crystal.",starts={{npcID=173422}},ends={{npcID=173422}},questType="standard"},
[61742] = {id=61742,name="A Fitting Guise",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The ritual to complete your disguise should be quite simple with the assistance of my oculus. Even a like you should be able to manage it. When you are ready, simply hold the empowered crystal above Nelesis's corpse. My oculus will do the rest.",objectivesText="Meet Balmedar in the Hall of Blades at the House of Rituals.",rewardGold=128700,rewardXP=4085,starts={{npcID=173422}},ends={{npcID=173172}},coords={x=0.593,y=0.329,source="quest_giver",zoneID=11462},questType="standard"},
[61743] = {id=61743,name="The Pupil Returns",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Now that you have your disguise--and I have assurance of your loyalty--it is time you reported to your new master. Find Kel'Thuzad within the Vault of Souls. Do whatever tasks he requires of you, but keep your eyes open for anything untoward. My oculus will continue to accompany you so that I can provide guidance when the time is right. We will uncover this new baron's true intentions.",objectivesText="Meet Kel'Thuzad within the Vault of Souls.",rewardGold=25740,rewardXP=1020,starts={{npcID=173172}},ends={{npcID=172923}},coords={x=0.662,y=0.322,source="quest_giver",zoneID=11462},questType="standard"},
[61744] = {id=61744,name="The Baron's Plan",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You have done well in my service, Nelesis. When the time has come to take my rightful place, you will be well rewarded. Until then, I will require your utmost devotion and secrecy. Our preparations are almost complete. Come, walk with me, and I will show you the splendor of our works.",objectivesText="Walk with Kel'Thuzad . Progress: Walk with me, acolyte.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=172923}},ends={{npcID=172923}},coords={x=0.702,y=0.266,source="quest_giver",zoneID=11462},questType="standard"},
[61745] = {id=61745,name="Mistress of Tomes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The kyrian will no doubt make a worthy sacrifice for our ritual, but I am not entirely versed with the magics of his kind. I have requested that the Baroness Ninadar assemble a list of appropriate literature, so that I can ensure my ritual will have the desired effect. As you know, the baroness enjoys exploiting her title, so expect to be faced with some manner of mundane tasks in exchange for her cooperation. Return when you have procured the tomes, acolyte.",objectivesText="Speak with Baroness Ninadar in the Grimoirium.",rewardGold=25740,rewardXP=1020,starts={{npcID=172923}},ends={{npcID=172924}},coords={x=0.702,y=0.266,source="quest_giver",zoneID=11462},questType="standard"},
[61746] = {id=61746,name="Cantrip Collections",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="One of the... more regrettable duties of the Mistress of Tomes is the collation and maintenance of our scroll library. Unfortunately, many of our acolytes are less than prompt when it comes to returning items they have borrowed, which requires me to seek them out and retrieve them myself. Of course, this is far too menial a task for a baroness, but that is why lackeys like you exist. Go, and retrieve my scrolls. Feel free to use whatever persuasive means you have at your disposal.",objectivesText="Collect 6 Overdue Scrolls from Necrotic Acolytes in the Grimoirium. Progress: Have you found my scrolls?",rewardGold=257400,rewardXP=8165,rewardItems={182609},starts={{npcID=172924}},ends={{npcID=172924}},coords={x=0.662,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61747] = {id=61747,name="Errant Enchantments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The House of Rituals is a place of constant study. Every day, new incantations and formulae are concocted to further the arts of necromancy. It can be difficult to keep track of such innovation. To aid in cataloguing our progress, our sorcerers have applied the use of enchanted quills and parchment. Unfortunately, if not properly stored, these implements tend to run amok. Of course, they were not properly stored. Find the implements and return them to where they belong.",objectivesText="Retrieve 4 Errant Quills and 6 Rampant Grimoires in the Grimoirium. Progress: Enchanted quills will not collect themselves, now will they?",rewardGold=257400,rewardXP=8165,rewardItems={182615,182616},starts={{npcID=172924}},ends={{npcID=172924}},coords={x=0.662,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61748] = {id=61748,name="The Hall of Tomes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Very well, you can have your list. The volumes you seek can be found in the Hall of Tomes. Now, run back to your master like a good little pet.",objectivesText="Collect the required volumes from the Hall of Tomes and return them to Kel'Thuzad in the Vault of Souls. Progress: You have returned? Do you have my tomes?",rewardGold=128700,rewardXP=4085,rewardItems={182642,182643,182644,182645},starts={{npcID=172924}},ends={{npcID=172923}},coords={x=0.662,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61749] = {id=61749,name="Necessary Ingredients",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="As you are well aware, a ritual of this complexity requires several reagents. I have asked that Carver Jor'dan prepare what I'll need. Seek him out in the Reagentry, and provide whatever assistance he requests.",objectivesText="Speak with Jor'dan the Powerful in the Reagentry.",rewardGold=25740,rewardXP=1020,starts={{npcID=172923}},ends={{npcID=173492}},coords={x=0.702,y=0.266,source="quest_giver",zoneID=11462},questType="standard"},
[61750] = {id=61750,name="Heart of the Forest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The baron requests a veilwing's heart , but procuring one is going to be something of a problem. As you can plainly see, one of our sorcerers proved incapable of restraining the beast. I regret to inform you that our only specimen has escaped. It cannot have gone far, though. If you follow its tracks you should be able to catch up with it and retrieve the heart yourself. I assure you the baron will not be able to perform his ritual without it.",objectivesText="Collect a Veilwing's Heart from the Elusive Veilwing in the House of Rituals. Progress: Did you find the veilwing?",rewardGold=514800,rewardXP=10205,rewardItems={182676},starts={{npcID=173492}},ends={{npcID=173492}},coords={x=0.7,y=0.326,source="quest_giver",zoneID=11462},questType="standard"},
[61751] = {id=61751,name="Cage Free Spores",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I will need your assistance with the collection of one other reagent for your master. These spore clusters he requests--while normally a trivial matter--will require a bit of work. You see, as the veilwing rampaged throughout the Reagentry, it toppled and broke several nearby cages hosting the blightrays from which we harvest the clusters. You will have to collect them through more... conventional means. The clusters are fragile, however, so try not to damage them while subduing the creatures.",objectivesText="Collect 6 Intact Spore Clusters from Escaped Blightrays in the Reagentry. Progress: Do you have the spore clusters?",rewardGold=257400,rewardXP=8165,rewardItems={182678},starts={{npcID=173492}},ends={{npcID=173492}},coords={x=0.7,y=0.326,source="quest_giver",zoneID=11462},questType="standard"},
[61752] = {id=61752,name="The Final Reagent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I have gathered most of the remaining reagents on your master's list. All that remains is the special shipment he requested from Oribos. The brokers have yet to deliver the shipment. When it arrives, your master will have all he needs to complete his ritual.",objectivesText="Bring the Bundle of Reagents to Balmedar in the House of Rituals. Progress: Let us see what we have here.",rewardGold=25740,rewardXP=1020,rewardItems={182252,182261,182270,182279,182679},rewardChoices={182270,182261,182279,182252},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173492}},ends={{npcID=173172}},coords={x=0.7,y=0.326,source="quest_giver",zoneID=11462},questType="standard"},
[61753] = {id=61753,name="Explosive Schemes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The brokers deal in objects most exotic and profound. If Kel'Thuzad requires reagents from them, his ritual must be outside the normal scope of the House of Rituals. This mysterious reagent could be the key to unlocking Kel'Thuzad's plan. We must get a hold of this delivery from Oribos. I have taken the liberty of concocting an alchemical bomb. Use it to ambush the caravan and retrieve whatever they are transporting.",objectivesText="Use the Alchemical Explosive to ambush the Broker caravan at the Scaplian Ridge. Progress: The caravan will arrive any moment now. Make haste!",rewardGold=257400,rewardXP=8165,starts={{npcID=173172}},ends={{npcID=173422}},coords={x=0.662,y=0.322,source="quest_giver",zoneID=11462},questType="standard"},
[61754] = {id=61754,name="No Crate Unturned",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="That explosion will likely bring onlookers from the House of Rituals. We must act quickly. Search through the debris for anything that looks out of the ordinary. It is likely that Kel'Thuzad's mystery reagent won't be hard to spot.",objectivesText="Search the Broker's Crates for Kel'Thuzad's special reagent.",rewardGold=257400,rewardXP=8165,rewardItems={182734,182735},starts={{npcID=173422}},ends={{npcID=173172}},coords={x=0.593,y=0.329,source="quest_giver",zoneID=11462},questType="standard"},
[61755] = {id=61755,name="Blinding the Brokers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We cannot allow Kel'Thuzad to discover who stopped his shipment. None must be left to tell the tale of what transpired here.",objectivesText="Kill 8 broker witnesses in the Scaplian Ridge.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173422}},ends={{npcID=173172}},coords={x=0.593,y=0.329,source="quest_giver",zoneID=11462},questType="standard"},
[61756] = {id=61756,name="Designed to Fail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The pieces are all coming together. The kyrian, the Paths of the First Ones, and runes of domination? Kel'Thuzad is looking to breach the Maw! We cannot allow this to happen! The Maw has been locked away from the Shadowlands for good reason. Opening that floodgate could be catastrophic! The baron is too powerful to confront headlong, so we will stop his ritual instead. Return to him with his reagents. I have made some \"modifications\" that should provide a calamitous end to his scheme.",objectivesText="Bring the Bundle of \"Modified\" Reagents to Kel'Thuzad in the Vault of Souls. Progress: My acolyte returns. What have you brought me?",rewardGold=25740,rewardXP=1020,rewardItems={182779},starts={{npcID=173172}},ends={{npcID=172923}},coords={x=0.662,y=0.322,source="quest_giver",zoneID=11462},questType="standard"},
[61757] = {id=61757,name="Caught in the Act",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Well then, since it was you who managed to procure the missing reagent, I find it only fair that you assist me with the final ritual! I can guarantee that this incantation will see you promoted to a full sorcerer of the house! The preparations are already made. We can begin as soon as you are ready.",objectivesText="Assist Kel'Thuzad in completing the ritual.",rewardGold=128700,rewardXP=4085,starts={{npcID=172923}},ends={{npcID=172923}},coords={x=0.702,y=0.266,source="quest_giver",zoneID=11462},questType="standard"},
[61758] = {id=61758,name="Improvised Implements",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1652,description="There must be some way we can get ourselves out of these cells. I don't see anything I can use over here. Search your cell for anything that can facilitate our escape.",objectivesText="Search your cell for something that can be used to escape.",coords={mapID=1652,x=0.542,y=0.679},questType="standard"},
[61759] = {id=61759,name="A Helpful Hand",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It takes but a simple act of necromancy to animate a hand. Unfortunately, since you will be in closest proximity, you must be the one to command it. When you are ready, I will reanimate the hand. Once you have control, use it to pull the lever at the end of the hall. Couldn't be simpler, right?",objectivesText="Navigate the Reanimated Hand to the end of the hall and activate the Corroded Lever .",rewardGold=257400,rewardXP=8165,ends={{npcID=173172}},coords={mapID=1536,source="quest_giver",x=0.662,y=0.322},questType="standard"},
[61760] = {id=61760,name="The Traitor Unmasked",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We must waste no time in warning the margrave of Kel'Thuzad 's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond! Let us put an end to this!",rewardGold=514800,rewardXP=10205,rewardItems={182251,182260,182269,182278},rewardChoices={182269,182260,182278,182251},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173172}},coords={x=0.662,y=0.322,source="quest_giver",mapID=1536},questType="standard"},
[61761] = {id=61761,name="The Better Part of Valor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="We now have no choice but to make a strategic retreat. Kel'Thuzad is far too fortified within the necropolis, and if Ninadar is his ally, then the House of Rituals is firmly in his grasp. It will take nothing short of an army to save the margrave now.",objectivesText="Return to the Seat of the Primus.",rewardGold=772200,rewardXP=12250,rewardItems={183847},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173831}},ends={{npcID=161907}},questType="standard"},
[61762] = {id=61762,name="Making a Smarter Dredger",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If he be hostin' fancy courts with you and Temel, this dredger's gotta be special... Smarter. Stronger. Quicker to apologize when they accidentally knock over the refreshments table and spill anima all over some poor duchess... I got an idea! Broker bloke at the Night Market was tryin' to sell me some important drinks. Kaja'Extreme or somethin'. Says it bigguns the brain, yeah? That's just what we need! Take these Scorchshrooms, that broker loves them, but note he rotates his costs each week.",objectivesText="Purchase a bottle of Kaja'Extreme from Ta'tru at the Night Market. Progress: You got the Kaja'Extreme ?",rewardGold=341600,rewardXP=8165,rewardItems={184448},starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[61763] = {id=61763,name="Dredging up an Assistant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Here we go, onto the dredging part. Just like we made that biggun here earlier! I mean we don't need the stone of binding or three other dredgers, but you'll still be throwing stuff into the muck! So it's the same. You head to the shore with this here Kaja-Infused Dredger Mix I whipped up for you. Toss it into that muck pool and let's meet that new dredger butler of yours!",objectivesText="Throw the Kaja-Infused Dredger Mix into the muck pool to create your dredger butler.",rewardGold=257400,rewardXP=8165,rewardItems={182301,182683},starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[61764] = {id=61764,name="Dredging up a Name",level=60,requiredLevel=60,faction="both",expansion=8,description="Oi, why aren't you addressing me by my proper name? Wait, I don't remember my name, proper or other. Does this mean I have amnesias? Oh no, I don't have a name, please, help!",objectivesText="Talk with your assistant and decide on a name for them.",starts={{npcID=172854}},questType="standard"},
[61765] = {id=61765,name="Words of Warding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes. The Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware. The runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require. Good luck.",rewardItems={182303},rewardCurrencies={{id=1767,amount=600},{id=1880,amount=475}},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group",worldTaskTitle="Words of Warding",db2QuestInfoID=1,db2QuestInfoName="Group"},
[61766] = {id=61766,name="Homegrown Help",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Every good party herald needs an assistant. Which is why I have you! But every good party herald's assistant... also needs an assistant. Which is why I procured permission from the prince for you to create your own dredger butler. We can start him on security while we cozy up to the guests and procure the necessary reading materials to train him on the social protocols of the different realms. He'll be entertaining the whole court in no time. No, don't thank me. You've earned this!",objectivesText="Meet Rendle in Dredgewood to make a dredger butler.",rewardGold=257400,rewardXP=8165,starts={{npcID=164966}},ends={{npcID=157846}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61767] = {id=61767,name="A Perilous Journey",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mograine has rallied the House of the Chosen to strike at Margrave Gharmal and his House of Constructs. They grow in strength with each passing day--this may be our only chance. We will join them on the field of battle. We will have justice for the fallen at my temple, as well as Mograine's own fallen kin. Rendezvous at Spider's Watch within Maldraxxus' northern reaches. We will move from there.",objectivesText="Meet Xandria at Spider's Watch in Maldraxxus.",rewardGold=25740,rewardXP=1020,rewardItems={181476,181557,181733},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=154627}},ends={{npcID=173222}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="standard"},
[61768] = {id=61768,name="Stronger Together",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We are to meet Baroness Draka aboard the Zerekriss above this position. Trust our allies' judgment in the battle ahead--true courage is knowing when to rely on the wisdom of others. The plan is simple. Clear out our flanks to ensure Gharmal's forces do not interfere with our true goal, then assault the Margrave himself. If we fail, we fail in the name of justice.",objectivesText="Fly with Xandria into the necropolis Zerekriss.",rewardGold=25740,rewardXP=1020,starts={{npcID=173222}},ends={{npcID=171483}},coords={x=0.376,y=0.294,source="quest_giver",zoneID=11462},questType="standard"},
[61769] = {id=61769,name="Fight and Flight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Alexandros and Emeni will lead the Chosen assault on the western gate. You and Xandria will direct your forces at the eastern gate. Secure the area and eliminate any resistance. Once both flanks are secured we can attack Gharmal directly.",objectivesText="Fly with Xandria to the House of Constructs.",rewardGold=25740,rewardXP=1020,starts={{npcID=171483}},ends={{npcID=166333}},coords={x=0.362,y=0.366,source="quest_giver",zoneID=11462},questType="standard"},
[61770] = {id=61770,name="The Butchers of Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these things?! No! The butchers of Bastion made clear their hearts that day! They deserve only the eternal darkness that awaits them. Ensure they see it!",objectivesText="Kill 10 House of Constructs forces in the Separation Chamber. Progress: Go bravely, <name>.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=168743}},ends={{npcID=168743}},coords={x=0.352,y=0.26,source="quest_giver",zoneID=11462},questType="standard"},
[61771] = {id=61771,name="Justice from Above",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts. The Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once. I shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.",objectivesText="Destroy 5 Maldracite Cores .",rewardGold=257400,rewardXP=8165,starts={{npcID=166333}},ends={{npcID=166333}},coords={x=0.356,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61772] = {id=61772,name="Dark Developments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential! Now, if subject number one-three-five succeeds in a proper wing transplant at last... Artemede .>",objectivesText="Bring the Abhorrent Design to Artemede outside the Hall of Chains. Provided item:",rewardGold=25740,rewardXP=1020,rewardItems={181285},starts={{npcID=357246}},ends={{npcID=168744}},coords={x=0.335,y=0.242,source="quest_giver",zoneID=11462},questType="standard"},
[61773] = {id=61773,name="Descended",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple. As I flew above their ranks I could hear their surgeons chanting its name above the din of combat-- Woeblade . It is an affront to all the kyrian stand for, an atrocity beyond any other. Mark it with the flames of courage when you engage, and we will help you destroy it.",objectivesText="Slay Woeblade the Atrocity.",rewardGold=514800,rewardXP=10205,rewardItems={174295,177056,178159,179946},rewardChoices={178159,177056,179946,174295},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=166333}},ends={{npcID=166333}},coords={x=0.356,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61774] = {id=61774,name="Burn Before Reading",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's abomination constructs. It is also incomplete. There must be more of these among Stitchflesh's remaining followers. I saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls. We must ensure they are never read again.",objectivesText="Collect 6 Stitchflesh Designs . Progress: This foul work must be destroyed.",rewardGold=257400,rewardXP=8165,rewardItems={180845},starts={{npcID=168744}},ends={{npcID=168744}},coords={x=0.352,y=0.268,source="quest_giver",zoneID=11462},questType="standard"},
[61775] = {id=61775,name="An Early End",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Within the Hall of Chains lie more abominations that are nearly complete. As we speak the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages. If they are allowed to finish their work, the constructs we have destroyed so far will mean little in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost. That must not come to pass. Destroy any abominations you come across.",objectivesText="Destroy 6 Inert Butchers . Progress: May your blade strike true.",rewardGold=257400,rewardXP=8165,starts={{npcID=168743}},ends={{npcID=168743}},coords={x=0.352,y=0.26,source="quest_giver",zoneID=11462},questType="standard"},
[61776] = {id=61776,name="Trouble on the Western Front",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Alexandros and our Maldraxxi allies need reinforcement at the western gate on the Margrave's opposite flank. They are barely holding on! Our forces will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks we cannot hope to achieve victory.",objectivesText="Fly with Kynthia to report to Alexandros at the Stitchyard.",rewardGold=25740,rewardXP=1020,starts={{npcID=168860}},ends={{npcID=166211}},coords={x=0.354,y=0.264,source="quest_giver",zoneID=11462},questType="standard"},
[61777] = {id=61777,name="Charging The Blade",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We can't advance with those juggernauts bombarding our position! I led a strike against the nearest, but conventional weapons do nothing against their imbued hides. Thankfully, I have an idea. Your old runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...",objectivesText="Charge your runeblade by killing enemy constructs in the Stitchyard.",rewardGold=257400,rewardXP=8165,starts={{npcID=166211}},ends={{npcID=166211}},coords={x=0.288,y=0.382,source="quest_giver",zoneID=11462},questType="standard"},
[61778] = {id=61778,name="Aerial Advantage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Gharmal's rocs dominate the skies above, striking at our forces as we advance. The Zerekriss can't get into position until they are cleared out! I would take care of them myself, but I'm not much of a flier. Don't have the balance for it! Take my riding hook and latch onto a roc. Once you're riding, just start hitting it 'til the job is done.",objectivesText="Grapple 6 Battlesewn Rocs out of the sky. Progress: Teach 'em a lesson!",rewardGold=257400,rewardXP=8165,rewardItems={180899},starts={{npcID=167810}},ends={{npcID=167810}},coords={x=0.282,y=0.374,source="quest_giver",zoneID=11462},questType="standard"},
[61779] = {id=61779,name="Grave Intent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="My spies have identified several astral projectors that Margrave Gharmal uses to rally his troops in the Stitchyard. I do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor. See to it that these projectors are destroyed. We believe them to be along the yard's perimeter.",objectivesText="Destroy the Southwestern, Northwestern, and Northeastern Astral Projectors . Progress: A blow inflicted to the enemy's morale can be as effective as traditional combat.",rewardGold=257400,starts={{npcID=167173}},ends={{npcID=167173}},coords={x=0.286,y=0.376,source="quest_giver",zoneID=11462},questType="standard"},
[61780] = {id=61780,name="Power of the Chosen",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The Zerekriss is nearly in position. Now is the time to strike! We must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts. The Margrave will be unable to ignore their deaths. Once he leaves his blighted tower, we can finish him once and for all.",objectivesText="Destroy the Bilebloat Juggernauts . Progress: Every moment the juggernauts live our position is in jeopardy!",rewardGold=257400,starts={{npcID=166211}},ends={{npcID=166211}},coords={x=0.288,y=0.382,source="quest_giver",zoneID=11462},questType="standard"},
[61781] = {id=61781,name="The End is Now",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Our forces have control of the House of Constructs, thanks to your intervention. Now, all that remains is the fall of the instigator themselves--Margrave Gharmal. This battle has been long in the making, $p. I am at your side without hesitation. Let us go to this monster. We will join Xandria to see him slain.",objectivesText="Meet with Xandria near the central chamber of the House of Constructs.",rewardGold=25740,rewardXP=1020,starts={{npcID=166211}},ends={{npcID=172002}},coords={x=0.288,y=0.382,source="quest_giver",zoneID=11462},questType="standard"},
[61782] = {id=61782,name="Pursuit of Justice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Draka stands ready to unleash the power of the Zerekriss upon Gharmal. We need only buy her time to focus its weapon. What we do now, we do for all of us. Bastion and Maldraxxus have both lost many to these fiends. He will not be defeated easily, but united our forces will finally bring him to justice!",objectivesText="Defeat Margrave Gharmal .",rewardGold=772200,rewardXP=12250,rewardItems={174294,177055,178158,179945},rewardChoices={178158,177055,179945,174294},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=172002}},ends={{npcID=173193}},coords={x=0.318,y=0.304,source="quest_giver",zoneID=11462},questType="standard"},
[61783] = {id=61783,name="Mega Bite",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2968,text="Defeat Jawbone"}},worldTaskTitle="Mega Bite",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61784] = {id=61784,name="Cliffs of Bastion",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173131,text="Defeat Stratios in a Pet Battle"}},worldTaskTitle="Cliffs of Bastion",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61785] = {id=61785,name="An Expected Visitor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="One Alexandros Mograine of Maldraxxus is meeting with the Paragon of Courage in Archon's Rise. Xandria has requested you join them. The two worked together recently to repel a nascent secondary assault on the Temple of Courage. Xandria seems to trust him well enough, so we have granted him access to the hold...for now. I suspect they will not stay here long. You should make haste.",objectivesText="Speak with Xandria in Archon's Rise.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=154627}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[61786] = {id=61786,name="Adventurer: Stonehead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
[61787] = {id=61787,name="Micro Defense Force",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173130,text="Defeat Zolla in a Pet Battle"}},worldTaskTitle="Micro Defense Force",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61788] = {id=61788,name="Adventurer: Simone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
