[61790] = {id=61790,name="Adventurer: Vulca",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
[61791] = {id=61791,name="Thenia's Loyal Companions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173129,text="Defeat Thenia in a Pet Battle"}},worldTaskTitle="Thenia's Loyal Companions",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61792] = {id=61792,name="Adventurer: Bogdan",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741}},ends={{npcID=164741}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
