[61814] = {id=61814,name="Nurgash Muckformed",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",worldTaskTitle="Nurgash Muckformed",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[61815] = {id=61815,name="Oranomonos the Everbranching",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",worldTaskTitle="Oranomonos the Everbranching",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[61816] = {id=61816,name="Mortanis",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",worldTaskTitle="Mortanis",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[61839] = {id=61839,name="Nipping at the Undergrowth",level=60,requiredLevel=60,faction="both",expansion=8,description="<The small gorger nips at your heels hungry and seeking your protection. Maybe it will like some of the plants here?>",objectivesText="Collect Endmire Vineroot . Progress: Collect Endmire Vineroot for your small gorger.",rewardItems={182314,182590},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[61840] = {id=61840,name="Vineroot on the Menu",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,description="Endmire Vineroot .>",objectivesText="Collect Endmire Vineroot . Progress: Collect Endmire Vineroot for your small gorger.",rewardXP=4085,rewardItems={182314,182591},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[61841] = {id=61841,name="Not Much to Goo On",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,rewardCurrencies={{id=1885,amount=3}},questType="world",worldTaskTitle="Not Much to Goo On",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61842] = {id=61842,name="Vineroot Will Not Do",level=60,requiredLevel=60,faction="both",expansion=8,description="<Clearly bigger, the gorger looks at a vineroot you point to and you can see the hint of menace in its eye at being offered the root again. It looks longingly at the devourer mites nearby.>",objectivesText="Collect Infused Endmire Fruit . Progress: Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.",rewardItems={182315,182592},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[61845] = {id=61845,name="Edict of Doom: Devourers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,description="The infusion of anima within Revendreth has led to a resurgence in devourer infestations. These eaters of the world must be slain. By order of Prince Renathal and the rightful Court of Harvesters, this edict decrees the doom upon these aberrations. Complete this quota of destruction within Revendreth and receive a reward equal to your efforts.",objectivesText="Destroy 20 Devourers in Revendreth.",rewardItems={181183,181184,181196,181199,181200,181201,181202,181211,181212,181215,181217,181218,181545,181546,181547,181548,181550,181708,184147,184150,184777,185854},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173247}},ends={{npcID=173248}},questType="standard"},
[61846] = {id=61846,name="Edict of Doom: Dredbats",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The recent suffusion of anima in the region has led to an increase in dredbats being animated far and above any intended volume. By order of Prince Renathal and the true Court of Harvesters an edict of doom is declared on dredbats within Revendreth. Avoid those used for transport or assigned to specific duties, but slay any in the less tamed regions of the realm and a reward shall be proffered.",objectivesText="Destroy 25 Dredbats in Revendreth. Progress: Maw Walker?",rewardItems={181175,181176,181180,181181,181185,181194,181197,181199,181200,181201,181202,181203,181204,181205,181206,181217,181218,181545,181546,181547,181548,181550,184147,184150,184777,185854,185942},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173251}},ends={{npcID=173248}},questType="standard"},
[61847] = {id=61847,name="Overdue Purging",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,description="There are many duties of a stoneborn that have been forsaken by the plans of Denathrius. One such duty is the elimination of manifestations. The process venthyr use to extract anima from souls is not clean, and often leads to unresolved issues made manifest. These entities are dangerous if left unchecked, and increase in number thanks to your revivication of anima to these droughted lands. While you patrol Revendreth, destroy any manifestations you encounter and I shall provide you recompense.",objectivesText="Destroy 30 Manifestations in Revendreth.",rewardItems={181175,181176,181177,181185,181192,181194,181196,181198,181200,181203,181206,181217,181218,181334,181545,181546,181547,181548,181550,181708,184147,184150,184777,185854,185942},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173087}},ends={{npcID=173087}},coords={x=0.714,y=0.762,source="quest_giver",zoneID=10413},questType="standard"},
[61848] = {id=61848,name="Edict of Doom: Sinstone Golems",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,description="By order of the true Court of Harvesters an edict of doom is issued for any Sinstone Golems that have coalesced into dangerous sizes within the realm. These entities are the manifestation of unresolved sins of those souls who failed their redemption and were condemned to the Maw. With the recent suffusion of anima to the region they have grown dangerously strong. Expunge them from existence and recompense shall be provided.",objectivesText="Destroy 4 Sinstone Golems in Revendreth.",rewardItems={181175,181177,181178,181179,181180,181183,181185,181191,181195,181196,181197,181199,181200,181202,181211,181217,181218,181334,181545,181546,181547,181548,181550,181708,182724,184147,184150,184777,185942},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173629}},ends={{npcID=173248}},questType="standard"},
[61849] = {id=61849,name="Take the Bite Out of 'Em",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Right. So you got a quota of venthyr you need offed and I got a mean need for some payback. See, you may not think it to look at me but 'em venthyr loooove to chew on me specifically. Not sure what dark habit followed them across the veil but I just was a squishy bag of indulgence for far too long. As you go about offin' 'em venthyr for your normal... motivations... I'd ask you to bring me a bunch of fangs off 'em you off, as it were. I'll pay for payback!",objectivesText="Collect 40 Venthyr Fangs . Progress: I'm gettin' quite a collection goin'.",rewardItems={182692},rewardCurrencies={{id=1885,amount=2}},starts={{npcID=173630}},ends={{npcID=173630}},coords={x=0.712,y=0.744,source="quest_giver",zoneID=10413},questType="standard"},
[61851] = {id=61851,name="Shades of Muck",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Yeah, this here muck pool's got everythin' we need to make your dredger butler. We'll make this one special just for you. Made to specifications, as the fangs say. First up, you gotta choose its color. Us dredgers comes in all kind of different shades of muck. Take a peek at some me fellow dredgers and let me know what color we should dredge up for your butler. We can recolor a dredger after-the-fact, but it ain't pleasant. Rendle shudders at the thought.>",objectivesText="Look at nearby dredgers to see color options, and then tell Rendle which color you want. Progress: What color you thinkin' of?",rewardGold=257400,rewardXP=8165,starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
