[61867] = {id=61867,name="Extra Pieces",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173263,text="Defeat Rotgut in a Pet Battle"}},worldTaskTitle="Extra Pieces",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61868] = {id=61868,name="Uncomfortably Undercover",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173267,text="Defeat Dundley Stickyfingers in a Pet Battle"}},worldTaskTitle="Uncomfortably Undercover",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61869] = {id=61869,name="Search the Place",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="Zerekriss is ours... along with everything it contains. The Primus was personally involved in the design of this necropolis. It was truly a sight to witness his hands shape the form of this vessel. It would be wise to search the room. Perhaps he kept some tools here that might be of use to us.",objectivesText="Check the Foreman's Chest for anything valuable. Progress: What did you find?",rewardGold=128700,rewardXP=4085,starts={{npcID=164679}},ends={{npcID=161907}},coords={x=0.586,y=0.32,source="quest_giver",zoneID=11462},questType="standard"},
[61870] = {id=61870,name="Failed Experiment",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2978,text="Defeat Gorgemouth in a Pet Battle"}},worldTaskTitle="Failed Experiment",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61871] = {id=61871,name="To Current Matters",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8499,mapID=862,description="Ye've done good here, champion. MOTHER and I will be figurin' out what te do next. Ye best get back te matters at hand, and do what ye can te empower that necklace o' yours. I've got ways te reach ye once MOTHER and I have fixed things up here.",objectivesText="Return to Nathanos Blightcaller on the Banshee's Wail in Zuldazar.",rewardGold=23400,rewardXP=850,starts={{npcID=136907}},ends={{npcID=135691}},coords={x=0.5,y=0.616,source="quest_giver",zoneID=9667},questType="standard"},
[61872] = {id=61872,name="To Current Matters",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=8568,mapID=1161,description="Ye've done good here, champion. MOTHER and I will be figurin' out what te do next. Ye best get back te matters at hand, and do what ye can te empower that necklace o' yours. I've got ways te reach ye once MOTHER and I have fixed things up here.",objectivesText="Return to Halford Wyrmbane on the Wind's Redemption in Boralus.",rewardGold=23400,rewardXP=850,starts={{npcID=136907}},ends={{npcID=135612}},coords={x=0.5,y=0.616,source="quest_giver",zoneID=9667},questType="standard"},
[61874] = {id=61874,name="Shadowlands: A Chilling Summons",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=1637,mapID=84,description="The time has come, . Highlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Orgrimmar, and I will take you to him. I would not keep him waiting.",objectivesText="Meet Darion Mograine outside Grommash Hold in Orgrimmar.",rewardGold=23400,rewardXP=850,starts={{npcID=176554}},ends={{npcID=176554}},coords={x=0.764,y=0.428,source="quest_giver",zoneID=1519},questType="standard"},
[61875] = {id=61875,name="Doing the Dew",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Thistledrop is magnificent creature. The roots go deep into the earth where they drink of waters most ancient. With these waters they collect the very essence of the land into a drop of dew that enables our artisans to craft powerful armaments. Help us gather the dew and you will be well rewarded. Hurry, before it evaporates!",objectivesText="Collect 30 Thistledrop Dew in Ardenweald's Forests. Progress: The dew evaporates quickly, hurry now!",rewardGold=257400,rewardItems={182333},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173277}},ends={{npcID=173277}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[61876] = {id=61876,name="Take Heart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Mograine and I spoke at length when he visited Bastion. He suggested that should we manage to kill Gharmal, his heart could be used to empower the Crest of Ascension. The Margrave bears the power to shape form in ways few beings can. Though his results are grim, if we could harness that power our Ascended would be stronger than ever before. It is not our way, but our way is changing, I think. Perhaps this is a step on our new path.",objectivesText="Collect the Fleshshaper's Heart . Progress: It must be done.",rewardGold=128700,rewardXP=4085,rewardItems={182334},starts={{npcID=173193}},ends={{npcID=173193}},coords={x=0.31,y=0.29,source="quest_giver",zoneID=11462},questType="standard"},
[61877] = {id=61877,name="Return to the Hold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1536,description="Let us ferry the heart to Elysian Hold swiftly. There are many in the Shadowlands who would strike at us to take its power for their own. Keep your eyes open, Maw Walker. We return to our kin victorious this day.",objectivesText="Meet Xandria at the Crest of Ascension in Elysian Hold in Bastion.",rewardGold=25740,rewardXP=1020,starts={{npcID=173193}},ends={{npcID=173313}},coords={x=0.31,y=0.29,source="quest_giver",zoneID=11462},questType="standard"},
[61878] = {id=61878,name="Crest of Greatness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Once you are ready, all you must do is place the heart within the sphere here on the Crest of Ascension. Mikanikos's handiwork will ensure that its energy is channeled properly to aid in our ascension rituals, and its power should help protect the Crest against any further attack. May the House of Constructs never set foot in our realm again.",objectivesText="Place the Fleshshaper's Heart in the Crest of Ascension. Progress: <This looks to be the orb Xandria directed you to place the heart in.>",rewardGold=25740,rewardXP=1020,rewardItems={182341},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=173313}},ends={{npcID=357261}},coords={x=0.392,y=0.596,source="quest_giver",zoneID=11012},questType="standard"},
[61879] = {id=61879,name="Ashes Will Fall",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2979,text="Defeat Scorch in a Pet Battle"}},worldTaskTitle="Ashes Will Fall",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61880] = {id=61880,name="Honored Attendance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It is my humble honor to be the Ember Court's first guest. Please inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.",rewardGold=128700,rewardXP=4085,starts={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},ends={{npcID=164966,x=0.28,y=0.43,zoneID=10413}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Honored Attendance"},
[61882] = {id=61882,name="Formal Entertainment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Accuser will be pleased that you have chosen such humble and formal entertainment for the first Ember Court. I look forward to the occasion.",rewardGold=128700,rewardXP=4085,starts={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},ends={{npcID=164966,x=0.28,y=0.43,zoneID=10413}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Formal Entertainment"},
[61883] = {id=61883,name="Resilient Survivors",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173315,text="Defeat Sylla in a Pet Battle"}},worldTaskTitle="Resilient Survivors",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61884] = {id=61884,name="Formal Refreshments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Tubbins 's tea ready soon. Go tell Theotar and friends. Tubbins is best!",rewardGold=128700,rewardXP=4085,starts={{npcID=167863,x=0.31,y=0.576,zoneID=10413},{npcID=173299,x=0.312,y=0.574,zoneID=10413}},ends={{npcID=164966,x=0.28,y=0.43,zoneID=10413}},coords={x=0.31,y=0.576,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Formal Refreshments"},
[61885] = {id=61885,name="Eyegor's Special Friends",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173324,text="Defeat Eyegor in a Pet Battle"}},worldTaskTitle="Eyegor's Special Friends",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61886] = {id=61886,name="The Mind Games of Addius",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173331,text="Defeat Addius the Tormentor in a Pet Battle"}},worldTaskTitle="The Mind Games of Addius",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61892] = {id=61892,name="Ember Court Ambassador",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.",objectivesText="Complete World Quests across the Shadowlands.",rewardGold=514800,rewardXP=10205,rewardItems={181521},starts={{npcID=165453}},ends={{npcID=165453}},coords={x=0.284,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[61893] = {id=61893,name="Ember Court Ambassador",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.",objectivesText="Complete World Quests across the Shadowlands.",rewardGold=514800,rewardXP=10205,rewardItems={181524},starts={{npcID=165453}},ends={{npcID=165453}},coords={x=0.284,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[61894] = {id=61894,name="Ember Court Ambassador",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.",objectivesText="Complete World Quests across the Shadowlands.",rewardGold=514800,rewardXP=10205,rewardItems={182342},starts={{npcID=165453}},ends={{npcID=165453}},coords={x=0.284,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[61895] = {id=61895,name="Ember Court Ambassador",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.",objectivesText="Complete World Quests across the Shadowlands.",rewardGold=514800,rewardXP=10205,rewardItems={182343},starts={{npcID=165453}},ends={{npcID=165453}},coords={x=0.284,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[61896] = {id=61896,name="Undercover Security",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Do you know why the venthyr carve stoneborn into different shapes? Because diversity in form allows for diversity in strategy. Our different shapes give us different purpose. We need a new shape to solidify our court defenses. With the right training and tools, venthyr guards could be hidden in plain sight--posed as greeters. Able to be among the guests without raising concerns, they'd be the first to respond to active threats.",objectivesText="Collect The Everyday Assassin training guide from Maldraxxus and 20 Enchanted Trickster Dust from Ardenweald. Progress: Undercover guards? Interesting idea...",rewardGold=514800,rewardXP=10205,rewardItems={182363,182364},starts={{npcID=165496}},ends={{npcID=164966}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[61898] = {id=61898,name="Small Bites",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The reviews are in, $p. Our menu is too Revendreth-centric! All the best courts have exotic appetizers, small plates, and other specialties that guests can look forward to every time they come. And for a court like ours, which boasts frequent guests from other realms, we simply must do better! Do not worry, after tireless research, I have drafted a very particular list of ingredients for you to find me. Bring them to me, and I will serve our guests eternity on a platter!",objectivesText="Collect cheeses from Bastion and Sourbread Yeast Starter from Maldraxxus. Progress: Are you sure Picky Stefan wanted ALL of these things?",rewardGold=514800,rewardXP=10205,rewardItems={182355,182356,182357,182365},starts={{npcID=165490}},ends={{npcID=164966}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[61899] = {id=61899,name="Anima Tastings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You started a trend, $p! Your constant gallivanting around the different realms of the Shadowlands has inspired a new flair for the exotic among Revendreth's elite. If it's from outside Revendreth, the venthyr want to try it. And I know just what the next big thing will be: anima tastings! Think about it: we--and by 'we' I mean 'you'--bring back fresh anima from all the different realms you travel to. Then socialites get to sip it and pretend it tastes like wherever you got it from!",objectivesText="Collect fresh anima from Ardenweald, Bastion, Maldraxxus, and Revendreth. Progress: That's a whole lot of anima you got there. That's all just for drinking?",rewardGold=514800,rewardXP=10205,rewardItems={182358,182359,182360,182361},starts={{npcID=165494}},ends={{npcID=164966}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[61900] = {id=61900,name="Comfy Chairs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1525,description="I want guests to sit. Standing is hard. I know 'cause I stand a lot. Guest should sit and be comfy. I make comfy chairs for all guests to sit. Guests be happy, stay longer!",objectivesText="Collect 30 Soft Vulpin Fur from Bastion and 30 Reclaimed Wood from Ardenweald. Progress: Boot knows his stuff. If he says we should make chairs, we should make chairs.",rewardGold=514800,rewardXP=10205,rewardItems={182354,182362},starts={{npcID=165493}},ends={{npcID=164966}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[61916] = {id=61916,name="Restock: Fire Damage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, those big fires from candles burn all the tablecloths. Bring me pretty cloth and I make new tablecloths. Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[61943] = {id=61943,name="Court Influencer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,rewardItems={181537},starts={{npcID=165399}},ends={{npcID=165399}},coords={x=0.286,y=0.41,source="quest_giver",mapID=1525},questType="standard"},
[61944] = {id=61944,name="Discerning Taste",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,rewardItems={181538},starts={{npcID=165399}},ends={{npcID=165399}},coords={x=0.286,y=0.41,source="quest_giver",mapID=1525},questType="standard"},
[61945] = {id=61945,name="The Professionals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Smart move bringing in the specialists, $p. Once you get into this week's Ember Court, be sure to let the specialists know what you want them to do. Breakfist down in the dredger pools can smash or clean things to make the court more Messy or Clean for you. Crooked Crick in the refreshments area can adjust Decadence. Lady Ilinca in the embassy area can adjust Formality. Cosmin the Illusionist on stage can adjust Excitement. Wing Commander Vulpek at the front gates can adjust Danger.",objectivesText="Enter the Ember Court, then give orders to one of the specialist staff members.",rewardGold=257400,rewardXP=8165,starts={{npcID=164966}},ends={{npcID=164966}},coords={x=0.28,y=0.43,source="quest_giver",zoneID=10413},questType="standard"},
[61946] = {id=61946,name="Natural Defenders",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173372,text="Defeat Glitterdust in a Pet Battle"}},worldTaskTitle="Natural Defenders",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61947] = {id=61947,name="Lurking In The Shadows",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2998,text="Defeat Nightfang in a Pet Battle"}},worldTaskTitle="Lurking In The Shadows",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61948] = {id=61948,name="Airborne Defense Force",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=11,amount=1,objectID=173377,text="Defeat Faryl in a Pet Battle"}},worldTaskTitle="Airborne Defense Force",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61949] = {id=61949,name="Ardenweald's Tricksters",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2999,text="Defeat Rascal in a Pet Battle"}},worldTaskTitle="Ardenweald's Tricksters",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[61950] = {id=61950,name="Hunting the Wilds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The supply of attuned anima is running low again. I'm surprised that we've managed to stretch our resources so far without a resupply. You've proven yourself proficient at tracking down what is needed, perhaps you could assist us once again? The runestags that roam Ardenweald's forests are particularly suffused with the power of the wilds, anima retrieved from them will be optimal for our needs. Good hunting!",objectivesText="Collect 10 Feral Anima from Runestags. Progress: Worry not about the runestags, after some time they will return. This is just one part of the eternal cycle.",rewardGold=257400,rewardItems={182387},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173282}},ends={{npcID=173282}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[61957] = {id=61957,name="Champion: Ashraka",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61958] = {id=61958,name="Champion: Gorgelimb",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61959] = {id=61959,name="Champion: Talethi",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61960] = {id=61960,name="Champion: Xertora",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61961] = {id=61961,name="Champion: Rattlebag",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61962] = {id=61962,name="Champion: Velkein",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[61963] = {id=61963,name="Called to the Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1533,description="The Wild Hunt is made up of fae who have dedicated their lives to the protection of Ardenweald and its denizens. Each member has skill sharp as a blade and sense unlike no other. We have spoken to a duo, an evoker and a huntress, who will permit us to capture their memories for training if we help them on a particular hunt. Meet Alderyn in Claw's Edge. He is one you seek.",objectivesText="Find Alderyn in Claw's Edge in Ardenweald. Progress: You are not of these lands. How may I aid you?",rewardGold=257400,starts={{npcID=168430}},ends={{npcID=173402}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[61965] = {id=61965,name="Piercing the Shell",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Our quarry is one of the gorm, native creatures who were once helpful beasts of the realm, until the drought drove them mad. This particular beast has not only grown to a frightening size, but also has a shell so strong that none of our weapons or arrows have managed to pierce it. This spear you bring, infused with the anima of Bastion, could be the exact weapon we need to pierce the gorm's armor and put him down. My sister went ahead to scout. Let's not linger.",objectivesText="Find Myn'ir in the Gormhive, then kill the Fortified Desiccator .",rewardGold=514800,starts={{npcID=173402}},ends={{npcID=173403}},coords={x=0.506,y=0.698,source="quest_giver",zoneID=11510},questType="standard"},
[61967] = {id=61967,name="Remedial Lessons",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={182457,182458,182477},questType="world",db2Objectives={{orderIndex=0,type=0,amount=3,objectID=173426,text="Ancient Instructors restored"},{orderIndex=1,type=0,amount=15,objectID=156364,text="Manifestations of Pride slain"},{orderIndex=2,type=0,amount=1,objectID=156327,text="Speak to Voitha"}},worldTaskTitle="Remedial Lessons",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61968] = {id=61968,name="Just Wing It",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="For untold ages, the humble Ardenmoth has supplied the scales for the creation of armor for the Wild Hunt. Now, with our attention divided between the threats to the realm and the anima drought, it has become increasingly difficult for our foragers to find the perfect scales that we require. Only the scales of the highest quality are suitable. If you should obtain any in your travels and return with them, I shall ensure you are well rewarded.",objectivesText="Collect 28 Perfect Ardenmoth Wing Scales from Ardenmoths. Progress: Have you the scales?",rewardGold=257400,rewardItems={182450},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173282}},ends={{npcID=173282}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[61981] = {id=61981,name="Replenish the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Right, here's the gig: we need anima. Not just a bit or a pinch, but a lot. See, anythin' worth doin' can't be done without anima. Not in the Shadowlands. Not if we are gonna fix this mess Denathrius got us in. So, we need your increasin'ly resourceful self to beg, borrow, steal, nick, burglarize, pulverize, pirate-ize, earn, swindle, or otherwise become the source of a great charity of any anima you can get. Bring it to me, an' I'll stock our coffers, as it were, so you can put it to use.",objectivesText="Collect anima sources for the Anima Reservoir at Sinfall in Revendreth. Progress: How goes the anima hunt? You pinch us a pint or boost us keg?",rewardGold=1029600,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=172605}},ends={{npcID=172605}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[61982] = {id=61982,name="Replenish the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Hail, Maw Walker. As our influence over Bastion grows, so too does our need for our most precious resource--anima. We must replenish our reserves. Scour the realms for all that you can find and return here with the anima. With our precious reserves replenished, we can direct the anima wherever it is needed most. Go in service, .",objectivesText="Collect anima sources for the Anima Reservoir at Elysian Hold in Bastion. Progress: Every drop of anima is a gift in these times.",rewardGold=1029600,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167745}},ends={{npcID=167745}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[61983] = {id=61983,name="Replenish the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We require your strength, Maw Walker. The houses of our enemies grow stronger by the hour. In order to press the attack we must find new sources of anima to bolster our reserves. Search the realms for this precious resource and bring it back here to the Sanctum. Let none deny you! With your help the rival houses shall fall, one by one, and we will emerge victorious!",objectivesText="Collect anima sources for the Anima Reservoir at Seat of the Primus in Maldraxxus. Progress: The march to victory will require more anima.",rewardGold=1029600,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=161909}},ends={{npcID=161909}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[61984] = {id=61984,name="Replenish the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1702,description="Greetings, Maw Walker. The Tirna Achiad, Heart of Ardenweald, flourishes in our care, yet more anima is needed for our Sanctum. The cycle of rebirth, our purpose, must continue. To help our Queen, we must acquire more. Will you help us replenish the reservoir?",objectivesText="Collect anima sources for the Anima Reservoir at the Heart of the Forest in Ardenweald. Progress: Have you come to dedicate anima to our sacred purpose?",rewardGold=1029600,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=167196}},ends={{npcID=167196}},questType="standard"},
[61985] = {id=61985,name="Wake The Sleepers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The land speaks to me, . Ardenweald is a realm of cycles, but it has never faced an anima drought such as this. We will need the aid of all who reside here if we are to make it through this crisis. Many souls slumber within the forests and hills. If they can provide us some of their anima, we may be able to endure a little longer. Should you encounter any of the souls in your travels, please awaken them and send them to me.",objectivesText="Awaken 8 Slumbering Souls .",rewardGold=257400,rewardItems={175713,175728,175740,179517,179532,179547,179562,181401,181402,181407,181410,181411,181412,181413,181414,181415,181416,181417,181457,181459,181477,181479,181541,184378,184381,184382,184383,184384,184487,184519},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173277}},ends={{npcID=173277}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[61996] = {id=61996,name="Say The Magic Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ever since I cast my first spell, I've not been able to get enough of magic! It's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening! There are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!",rewardXP=8165,rewardItems={183744,182485,182494,182503,182512,184843},starts={{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.548,y=0.688,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Say The Magic Words"},
[61998] = {id=61998,name="Legacy of Stone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: We got room for another big statue on this here spot. You get me some stone and I'll make whatever kind of statue you want, yeah? Maybe one of you, or someone else, yeah?",starts={{npcID=173065}},ends={{npcID=173065}},coords={x=0.664,y=0.298,source="quest_giver",zoneID=10413},questType="standard"},
[62000] = {id=62000,name="Choosing Your Purpose",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Each covenant is vital to the Shadowlands. Though they have been isolated and divided as of late, the Purpose depends on the success of their efforts. All of the covenants must bolster their strength to face the threat of the Banished One. But your contributions cannot be divided. They must be focused upon a single path. Other mortals may make a different choice. Speak to your potential allies. Then make your choice at the map of the Shadowlands before me.",objectivesText="Speak to the Covenants. Decide how your path is entwined with the Purpose. Progress: Have you made your decision?",rewardGold=128700,rewardXP=3410,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62041] = {id=62041,name="In A Bad Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I've heard about the chaos in Revendreth. Reports of exiles driven mad and burned in the Desiccation. The very thought of all that suffering fills me with the urge to do something about it. If you are headed there, please let me accompany you. I simply must help as many as I can!",objectivesText="Use Roseboil 's Regenerative Molt to cure 15 Light-Seared Exiles. Progress: Did we cure them all?",rewardXP=8165,rewardItems={183744,182487,182496,182505,182514,184843},starts={{npcID=158259},{npcID=159241}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[62043] = {id=62043,name="Prove Your Worth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,description="You must prove your worth to us again . We have not forgotten your betrayal. Yet you say you seek penance. This task will start to demonstrate that you are serious about earning back our trust.",objectivesText="Complete the task for the Kyrian.",rewardGold=128700,rewardXP=4085,starts={{npcID=171787}},ends={{npcID=171787}},questType="standard"},
[62044] = {id=62044,name="Standing Toe To Toe",level=60,requiredLevel=60,faction="both",expansion=8,description="<The gorger is clearly bigger, it gestures with its head towards one of the other gorgers as if urging you to attack it.>",objectivesText="Defeat devourer gorgers. Progress: Attack and defeat devourer gorgers in the Endmire.",rewardItems={182594},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[62045] = {id=62045,name="Ready for More",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,description="<Again the gorger is strutting ready for more fighting, staring down the the closest gorger.>",objectivesText="Defeat devourer gorgers. Progress: Attack and defeat devourer gorgers in the Endmire.",rewardXP=4085,rewardItems={182586,182587,182588},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[62046] = {id=62046,name="A New Pack",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,description="<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>",objectivesText="Defeat an Unbidden Worldeater . Progress: <The gorger gestures in the direction of a worldeater, seemingly feeling up to the challenge with you by its side.>",rewardXP=4085,rewardItems={182589},starts={{npcID=174482}},ends={{npcID=174482}},questType="standard"},
[62051] = {id=62051,name="Gormling Toss: Spirit Glen",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={182600,184487},rewardCurrencies={{id=1885,amount=3}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=173520,text="Gormling in a Bag acquired"},{orderIndex=1,type=0,amount=8,objectID=173521,text="Wayward Gormlings knocked down and bagged"}},worldTaskTitle="Gormling Toss: Spirit Glen",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62052] = {id=62052,name="Exiled by Paranoia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1533,description="The liches of the House of Rituals were an instrumental piece in the Maldraxxi attack on Bastion. They are not currenty our allies, and it would be difficult to convince one to let us capture their memory for our training purposes. We have made contact with a necromancer who has a score to settle with one of the liches. Find her and she will aid you in capturing this memory.",objectivesText="Find Karaxi the Defector in the Challenger's Promenade in Maldraxxus. Progress: <Karaxi is sifting through a book very carefully.>",rewardGold=257400,starts={{npcID=168430}},ends={{npcID=173495}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[62053] = {id=62053,name="Necromantic Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="My old master, Thran'tiok, is the epitome of paranoia. She believes everybody will turn on her, and it led to my exilement from not only her service, but the House of Rituals as a whole. I had no intent to cross her... but that has changed. Take the crystal casing you have built and slay my old colleagues to infuse it with necromantic energy. It shall lead you to Thran'tiok's phylactery, which should be exactly what we both seek.",objectivesText="Charge the Soulseeker Crystal by defeating foes in the House of Rituals, then use it to find Thran'tiok's phylactery. Progress: Thran'tiok thinks I am a threat... I will show her what that word truly means.",rewardGold=257400,starts={{npcID=173495}},ends={{npcID=173495}},coords={x=0.538,y=0.488,source="quest_giver",zoneID=11462},questType="standard"},
[62054] = {id=62054,name="Castle Nathria: Getting a Head",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13224,description="We need to show Denathrius that we mean business. His dredger... pet... should do the trick. Bring me his head. Four times should do it. Dredgers are curious creatures.",objectivesText="Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Normal Difficulty. Progress: I need the heads or we cannot make a profound statement.",rewardGold=514800,rewardXP=10205,starts={{npcID=172653}},questType="raid"},
[62055] = {id=62055,name="Castle Nathria: Getting a Head",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13224,description="We need to show Denathrius that we mean business. His dredger... pet... should do the trick. Bring me his head. Four times should do it. Dredgers are curious creatures.",objectivesText="Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Heroic Difficulty. Progress: I need the heads or we cannot make a profound statement.",rewardGold=514800,rewardXP=10205,starts={{npcID=172653}},questType="raid"},
[62056] = {id=62056,name="Castle Nathria: Getting a Head",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13224,description="We need to show Denathrius that we mean business. His dredger... pet... should do the trick. Bring me his head. Four times should do it. Dredgers are curious creatures.",objectivesText="Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Mythic Difficulty. Progress: I need the heads or we cannot make a profound statement.",rewardGold=514800,rewardXP=10205,starts={{npcID=172653}},questType="raid"},
[62057] = {id=62057,name="Those Who Hunger",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I've heard reports that the number of gorm sightings have risen greatly the past few days. Normally they're simple decomposers, playing their part in the great cycle, but in great numbers the gorm can be aggressive. If left unchecked, their ravenous hunger will cause untold destruction. The Wild Hunt has called for a gorm hunt. Meet your quota and you will be well-rewarded.",objectivesText="Destroy 20 Gorm in Ardenweald.",rewardGold=257400,rewardItems={175740,179517,179532,181402,181404,181405,181406,181415,181416,181418,181420,181421,181424,181425,181426,181428,181429,181430,181477,181479,181541,182464,184378,184381,184382,184383,184384,184487,184519},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173282}},ends={{npcID=173282}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62058] = {id=62058,name="Centurions, Assemble!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=173541,text="Select a Centurion"},{orderIndex=1,type=0,amount=1,objectID=173553,text="Pilot your Centurion"},{orderIndex=2,type=15,amount=1,objectID=0,text="Repel the Forsworn Threat"}},worldTaskTitle="Centurions, Assemble!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62059] = {id=62059,name="Prove Your Worth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,description="You must prove your worth to us again . We have not forgotten your betrayal. Yet we know you seek penance. This task should prove your willingness to rejoin our ranks.",objectivesText="Complete the task for the Necrolords.",rewardGold=128700,rewardXP=4085,starts={{npcID=171821}},ends={{npcID=171821}},questType="standard"},
[62060] = {id=62060,name="Prove Your Worth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="You must prove your worth to us again . We have not forgotten your betrayal. Yet we know you seek penance. This task should prove your willingness to rejoin our ranks.",objectivesText="Complete the task for the Night Fae.",rewardGold=128700,rewardXP=4085,starts={{npcID=171795}},ends={{npcID=171795}},questType="standard"},
[62061] = {id=62061,name="Prove Your Worth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,description="You must prove your worth to us again . We have not forgotten your betrayal. Yet we know you seek penance. This task should prove your willingness to rejoin our ranks.",objectivesText="Complete the task for the Venthyr.",rewardGold=128700,rewardXP=4085,starts={{npcID=171589}},ends={{npcID=171589}},questType="standard"},
[62062] = {id=62062,name="Restock: Stolen Rugs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12831,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, those thieves steal more than memories. They steal rugs too! New rugs be so heavy thieves can't carry! Bring me things to make heavy rugs. Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[62064] = {id=62064,name="Restock: Broken Mirrors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, those prisoners break all the mirrors when they escape! Laurent help me fix, but need pieces. Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[62065] = {id=62065,name="Restock: My Favorite Table",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, one of them big bad dredgers sit on my favorite table, break in half! Need wood to fix table. Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[62066] = {id=62066,name="Restock: Dredger Pool",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy! Need way to get rid of all bad stuff... You know thing does that? Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[62067] = {id=62067,name="Restock: Statues",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: Decorations not ready! Last Ember Court, dredgers see big new statue made. All want statues now! Bring me stone and I carve tiny statues to hold. Make all dredgers happy. Then we can pick decorations for next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165493}},ends={{npcID=165493}},coords={x=0.298,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[62068] = {id=62068,name="Gormling Piper: Crumbled Ridge",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,rewardXP=8165,rewardItems={182611},rewardCurrencies={{id=1885,amount=3}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=158969,text="Fae Flute acquired"},{orderIndex=1,type=0,amount=8,objectID=173561,text="Burrowing Gormlings coaxed and bagged"}},worldTaskTitle="Gormling Piper: Crumbled Ridge",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62069] = {id=62069,name="Restock: Sinstones",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: We got a problem, <name>. Last Ember Court, the Accuser's rituals were a little TOO convincing. A bunch of my dredgers want their own sinstones now, so they can list things they think they've done wrong. I'm going to need some resources to soothe their guilty consciences. Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62070] = {id=62070,name="Restock: Fragrant Flowers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1525,objectivesText="Progress: We got a problem, <name>. Last Ember Court, some of the animals had... issues. I can't get the stains out and everything reeks! I'm going to need some very fragrant flowers to cover up this smell. Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62073] = {id=62073,name="Restock: Band Shirts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: We got an opportunity, <name>. The Lost Chalice Band is the hottest entertainment in Revendreth after that killer performance at the last Ember Court. It's all anyone's talking about. We should make some band shirts, give 'em out for free to keep the hype rolling. Bring me the materials and I'll take care of the rest. Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62074] = {id=62074,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=11400,mapID=1543,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
[62075] = {id=62075,name="Restock: Soul Cages",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: We got a problem, <name>. Last Ember Court, we were able to save quite of a few of those abused souls the Master's minions attacked us with. That's great, but we need more chains and cages if we're going to keep that many souls here until the Accuser can take them. Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62076] = {id=62076,name="Restock: Free Press",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: We got a problem, <name>. Last Ember Court, that provocateur's gossip spread further than we thought. I've gotten all sorts of uncomfortable questions from socialites and nobles unsure of what to believe. We've got to write some pamphlets to set the record straight and dispel that scoundrel's lies! Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62078] = {id=62078,name="Restock: Fashion Accessories",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: We got a problem, <name>. Last Ember Court, the Countess's clothier showed everyone the future of fashion and we're all way behind. Medallions are all the rage, thanks to the Prince's growing collection. I can't get a medallion, but I at least need a necklace so I don't get laughed out of courts. Then we can pick our entertainment for the next Ember Court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165494}},ends={{npcID=165494}},coords={x=0.306,y=0.418,source="quest_giver",zoneID=10413},questType="standard"},
[62080] = {id=62080,name="Restock: Herbal Tea",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, our guests drank more tea than Theotar himself! Our entire supply is depleted. I simply must acquire new tea ingredients, and I only accept the highest quality! After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62081] = {id=62081,name="Return Those Animacones!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Reports say that once again the spriggan are proving to be a nuisance, . Word is that a bunch of them broke into the stores at the Heart of the Forest and made off with a huge store of animacones. Needless to say, we need those animacones back. The report says the spriggan group split up as they were making their escape, so any one you see is as likely to be carrying the animacones as the next. Good luck.",objectivesText="Collect 44 Looted Animacones from spriggan within Ardenweald. Progress: Were you able to find the animacones?",rewardGold=257400,rewardItems={182619},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173282}},ends={{npcID=173282}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62082] = {id=62082,name="Restock: Personal Stash",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, while your guests were so flippantly flinging food around court, several stray pies flew directly into my personal food supplies. Everything was ruined! You know I do not like to make a fuss, but I simply must insist that you replace the delicacies ruined by that unwelcome food fight. After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62083] = {id=62083,name="Restock: Medical Supplies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, those wild mushrooms you brought poisoned me and half of the socialites! Thankfully, it does not appear to be a lethal poison, but it has been most uncomfortable for all involved. We are in desperate need of anti-venom. After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62084] = {id=62084,name="Restock: Fine Cutlery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, the venthyr invaders did not just assault our guests--they stole our cutlery! My old friend Forgy can craft replacement cutlery for us, but we will need to provide the supplies. After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62085] = {id=62085,name="...Why Me?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Overseer Kalvaros ' canteen.>",objectivesText="Deliver the Reclaimed Vessel to Overseer Kalvaros at the Challenger's Promenade. Provided item:",rewardGold=491400,rewardXP=1770,ends={{npcID=159689}},coords={mapID=1536,source="quest_giver",x=0.54,y=0.506},questType="standard"},
[62086] = {id=62086,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=11400,mapID=1543,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
[62087] = {id=62087,name="Restock: Imported Dinnerware",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, the stone fiends dropped more than Theotar's tea set. They broke the dinnerware I had imported directly from Ardenweald, in order to help our Night Fae guests feel at home! I believe I can repair them, but I will need resources. After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62088] = {id=62088,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=11400,mapID=1543,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
