[62092] = {id=62092,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13224,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
[62093] = {id=62093,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13404,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
[62094] = {id=62094,name="Restock: Exploratory Meals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I suffer yet another crisis in the kitchen, Maw Walker! You may recall that an excess of gnats swarmed our last Ember Court. Although initially repulsed, I have begun to ponder if there might be some culinary value to these creatures. I would like to attempt a few meals with them. I shall require a few things to steel myself for the culinary adventure. After that, I shall happily discuss refreshment options for our next court.",rewardGold=257400,rewardXP=8165,starts={{npcID=165490}},ends={{npcID=165490}},coords={x=0.29,y=0.442,source="quest_giver",zoneID=10413},questType="standard"},
[62095] = {id=62095,name="Restock: Medic's Tent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. While the volunteer portion of our security showed tremendous bravery at the last Ember Court, it was clear that they were unprepared for the rigors of battle. They suffered tremendous injuries. We need to resupply our medical team to be ready for the next court. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62096] = {id=62096,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=11400,mapID=1543,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
