[62103] = {id=62103,name="Professions - Reuse",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13404,description="You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.",objectivesText="Bring the memory back to the Runecarver .",questType="standard"},
[62104] = {id=62104,name="Restock: Stoneborn Reserves",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. At the last Ember Court, many of our stoneborn suffered fractures and cracked limbs while defending our guests. We will need to repair them. Bring me the stone, and I will coordinate the repairs with our dredgers. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62105] = {id=62105,name="Restock: Unconventional Weapons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. Fighting alongside the Maldraxxi forces at the last Ember Court inspired me to strategize outside of the typical boundaries of venthyr warfare. I am certain you mortals have developed creative weapons. Bring me some, so that I may learn them. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62106] = {id=62106,name="Restock: Enchantments",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. The Stone Legion's surprise attack on our last Ember Court revealed that I have been far too lax in pursuing enchantments for our troops' equipment. We must use every advantage at our disposal. Bring me any enchantment you can spare. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62108] = {id=62108,name="Restock: Strategic Codices",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. At the last Ember Court, the devourer's ambush tactics caught our guards by surprise. Their portals opened all around us and we were too slow to respond. We should stock up on supplies that will allow us to adapt to changing circumstances. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62109] = {id=62109,name="Restock: Surveillance Equipment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,objectivesText="Progress: I have an urgent matter to discuss. As you are aware, a murder occurred at the last Ember Court. That is an unacceptable failing on my part and I apologize. I would like to acquire additional surveillance equipment to ensure we are prepared if it happens again. After that is resolved, we can discuss security options for future Ember Courts.",rewardGold=257400,rewardXP=8165,starts={{npcID=165496}},ends={{npcID=165496}},coords={x=0.32,y=0.416,source="quest_giver",zoneID=10413},questType="standard"},
[62110] = {id=62110,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Party Crashers",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62113] = {id=62113,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Party Crashers",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62115] = {id=62115,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Party Crashers",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62117] = {id=62117,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Party Crashers",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62122] = {id=62122,name="Mystery Mirrors",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Mystery Mirrors",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62123] = {id=62123,name="Prison Break",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Prison Break",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62125] = {id=62125,name="Ritual of Absolution",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Ritual of Absolution",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62155] = {id=62155,name="Runestone Roundup",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Stone is a rare material in Ardenweald. Yet, I've heard tales that those who were masked by the Drust have small stones upon them. I'd like you to retrieve some of these stones for the Wild Hunt, so that we may better understand their link to our enemy. Face the masked and collect the stones from their deceased forms and I'll compensate you for your efforts. It's a gruesome task, but one that must be done.",objectivesText="Collect 18 Runestone Spikes from drust possessed fae within Ardenweald. Progress: How goes your investigation?",rewardGold=257400,rewardItems={182647},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173282}},ends={{npcID=173282}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62157] = {id=62157,name="Scouting from a Safe Distance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="The resurgence of the Scourge is troubling enough, but there are also reports that the Cult of the Damned has risen anew as well. If true, then that bodes ill for us all. We cannot allow the cultists' machinations to continue unchecked. I suggest we engage in some reconnaissance.",objectivesText="Survey the Cult of the Damned's presence at Aldur'thar and Mord'rethar. Progress: Notice anything unusual?",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=1}},starts={{npcID=168123}},ends={{npcID=168123}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="standard"},
[62159] = {id=62159,name="Aiding the Shadowlands",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="There is much to do within the Shadowlands. Many areas are suffering from the anima drought. The choice of who to help first is yours. Where will you go?",objectivesText="Choose where to go in the Shadowlands.",rewardGold=128700,rewardXP=3410,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62160] = {id=62160,name="A Bundle of Lilies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This grove needs something special, something to make it really stand out. I have a plan, but first I need flowers. Not just any flowers, but Night Lillies . They have a sweet scent that evokes starlit nights spent standing on a hilltop overlooking the majesty of the land. As you go exploring Ardenweald, look to the waterways for Night Lillies growing in the waterways and collect them. I will pay you for your efforts, of course.",objectivesText="Collect 10 Night Lillies . Progress: Were you able to find any of the lillies?",rewardGold=257400,rewardItems={182659},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173277}},ends={{npcID=173277}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62161] = {id=62161,name="Blood from a Bone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="I want nothing more than to make for Revendreth immediately... but it seems they have their own challenges to face. All know of the mark we left on Bastion. The venthyr are sure to be wary of allowing us into their realm. Once again, we must turn to you. Your renown across the Shadowlands has earned you the trust of many. Now, we need the trust of Revendreth.",objectivesText="Increase your Renown.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62162] = {id=62162,name="A Message from the Justicar",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=210,mapID=84,description="Justicar Trueheart has sent a personal request for your immediate assistance, . The frozen winds of Icecrown await your return.",objectivesText="Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.",rewardGold=25740,rewardXP=850,starts={{npcID=166383}},ends={{npcID=167045}},coords={x=0.656,y=0.768,source="quest_giver",zoneID=1519},questType="standard"},
[62163] = {id=62163,name="A Message from the Justicar",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=210,mapID=85,description="Justicar Trueheart has sent a personal request for your immediate assistance, . The frozen winds of Icecrown await your return.",objectivesText="Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.",rewardGold=25740,rewardXP=850,starts={{npcID=169878}},ends={{npcID=167045}},coords={x=0.528,y=0.774,source="quest_giver",zoneID=1637},questType="standard"},
[62165] = {id=62165,name="Tal-Inara's Call",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10565,mapID=1670,description="Your presence is needed within the Enclave. It is time for you to choose a covenant to ally yourself with.",objectivesText="Meet Tal-Inara within the Enclave in Oribos .",rewardGold=25740,rewardXP=850,questType="standard"},
[62166] = {id=62166,name="Tal-Inara's Call",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10565,mapID=1670,description="Your presence is needed within the Enclave. It is time for you to choose a covenant to ally yourself with.",objectivesText="Meet Tal-Inara within the Enclave in Oribos .",rewardGold=25740,rewardXP=850,questType="standard"},
[62168] = {id=62168,name="Bonescript Dispatches",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,questType="standard"},
[62169] = {id=62169,name="Eyes to the Sky",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The House of Eyes still reels from Akarek's demise. They search for direction. For purpose. Perhaps you can help them find it. Continue to gain the trust of the Eyes. Their skills will be invaluable to our cause.",objectivesText="Increase your Renown.",rewardGold=128700,rewardXP=4085,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62170] = {id=62170,name="You'll Never Walk Alone",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1533,description="Like wind and rain, discord storms my mind, tossing and blowing. ... I must find the golden skies. ... Remember, walk on, heart full of hope, and you'll never walk alone.",objectivesText="Turn these notes in to Inkiep in Hero's Rest.",rewardGold=477360,rewardXP=1770,ends={{npcID=160173}},coords={mapID=1533,source="quest_giver",x=0.532,y=0.468},questType="standard"},
[62171] = {id=62171,name="Tea Time",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard",worldTaskTitle="Tea Time",db2QuestInfoID=272,db2QuestInfoName="VenthyrPartyQuest"},
[62172] = {id=62172,name="Shortsleeved Doublet",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: Is that a slightly worn doublet for me!",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62173] = {id=62173,name="Long Sleeved Doublet",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,objectivesText="Progress: <Your dredger reaches out enthusiastically for the long sleeved doublet .>",starts={{npcID=172854}},ends={{npcID=172854}},coords={x=0,y=0,source="quest_giver",zoneID=16105},questType="standard"},
[62174] = {id=62174,name="A Proper Cover",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: <Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62175] = {id=62175,name="Looking Fabulous",level=60,requiredLevel=60,faction="both",expansion=8,objectivesText="Progress: Who is this? Oh, look at those flowing locks...",starts={{npcID=172854}},questType="standard"},
[62176] = {id=62176,name="The Spikey Look",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: That creature has a very distinct look...",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62177] = {id=62177,name="A Memorable Look",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: Oh, I have seen this dredger before!",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62178] = {id=62178,name="Black Muck Dye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,objectivesText="Progress: Another muck dye!",starts={{npcID=172854}},ends={{npcID=172854}},coords={x=0,y=0,source="quest_giver",zoneID=16105},questType="standard"},
[62179] = {id=62179,name="Blue Muck Dye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: Isn't muck so versatile!",starts={{npcID=172854}},ends={{npcID=172854},{npcID=173721}},coords={x=0,y=0,source="quest_giver",zoneID=16105},questType="standard"},
[62180] = {id=62180,name="Green Muck Dye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: There are so many muck colors, how do you choose just one?",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62181] = {id=62181,name="Bubbling Red Muck Dye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: Is that one still bubbling?",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62182] = {id=62182,name="A Letter From Nadja",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The letter is addressed to Nadja's contact Dimwiddle in Darkhaven. It is clearly sealed with Nadja's mark. It is certainly of great import, you should make sure the letter is delivered.",objectivesText="Return the letter to Darkhaven. Provided item:",rewardGold=683200,rewardXP=1770,ends={{npcID=165859}},coords={mapID=1525,source="quest_giver",x=0.608,y=0.624},questType="standard"},
[62183] = {id=62183,name="A Leaking Box Marked Perishable",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="A very exact entity wanted this package to reach Ta'tru at the Night Market. It looks like Broker script. The package is clearly leaking, and it is marked perishable. Perhaps delivering it quickly would be best.",objectivesText="Deliver the package to the Night Market. Provided item:",rewardGold=514800,rewardXP=1770,ends={{npcID=171808}},coords={mapID=1525,source="quest_giver",x=0.51,y=0.788},questType="standard"},
[62184] = {id=62184,name="A Crate of Sinvyr Ore",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The crate is fairly big and looks heavy, but it also looks like something someone would be willing to compensate for. Take the crate to Gibbo at the Old Gate. He should be expecting the recurring shipment.",objectivesText="Deliver the crate to the Old Gate. Provided item:",rewardGold=193050,rewardXP=1060,rewardItems={171832},ends={{npcID=163161}},coords={mapID=1525,source="quest_giver",x=0.606,y=0.398},questType="standard"},
[62185] = {id=62185,name="Fighting for Attention",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="Maintaining a watchful eye on the Cult of the Damned has proven challenging... and perilous. Several of our hippogryph riders recently ran afoul of the cult's winged terrors. Though a few were able to escape, the others were captured and brought to Aldur'thar. Do what you can to free them from their captors. We cannot afford to lose any more of our forces.",objectivesText="Free 5 Argent Hippogryph Riders from Aldur'thar.",rewardGold=257400,rewardXP=6815,rewardItems={183698},rewardCurrencies={{id=1754,amount=1}},starts={{npcID=170467}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[62186] = {id=62186,name="Swollen Anima Seed",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The masked sylvar set aside a single seed laden with anima; for what purpose, you can only imagine. Droman Tashmur would appreciate the return of such a precious resource.",objectivesText="Return the Swollen Anima Seed to Droman Tashmur in Tirna Vaal. Provided item:",rewardGold=514800,rewardXP=1770,ends={{npcID=158487}},coords={mapID=1565,source="quest_giver",x=0.635,y=0.362},questType="standard"},
[62187] = {id=62187,name="Satchel of Culexwood",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="This lost satchel is filled with wood given by the nearby Culex trees. Fluttercatch would surely appreciate its return.",objectivesText="Return the Satchel of Culexwood to Fluttercatch in the Banks of Life. Provided item:",rewardGold=514800,rewardXP=1770,ends={{npcID=158489}},coords={mapID=1565,source="quest_giver",x=0.48,y=0.244},questType="standard"},
[62188] = {id=62188,name="Catch A Star",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I require your aid on a... delicate matter, . Starfly Wings form a vital ingredient for some of our creations and our supply is exhausted. They are tiny things, very fragile, and I am ill able to handle them delicately. Could you obtain the Starflies for me? They must be caught alive in order for their wings to not spoil and we desperately need them. I'll ensure that you are compensated for your time, of course.",objectivesText="Collect 13 Glittering Starflies .",rewardGold=257400,rewardItems={175713,175740,179517,179532,179547,179562,179584,181401,181404,181405,181406,181413,181416,181417,181418,181425,181459,181477,181479,181541,182584,184378,184381,184382,184383,184384,184487,184519},rewardCurrencies={{id=1885,amount=3},{id=1806,amount=175}},starts={{npcID=173277}},ends={{npcID=173277}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62189] = {id=62189,name="Parasol Components",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Sheets of fine cloth, wooden parasol ribs, wooden dowels and metal braces, everything you would need to put together new parasols. These are worth a lot of gold in the Ember Ward. Mats would certainly reward you handsomely if you brought him this cache.",objectivesText="Return the components to Sanctuary of the Mad. Provided item:",rewardXP=1770,rewardCurrencies={{id=1820,amount=35}},ends={{npcID=166076}},coords={mapID=1525,source="quest_giver",x=0.326,y=0.492},questType="standard"},
[62190] = {id=62190,name="It's a Dirty Job",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We gotta fix up this muck pool before we go makin' that dredger butler of yours. Looks like the anima shortage caused all sorts of problems for this pool. Them muck pools gotta have plenty of filth and fiber in 'em to grow good dredgers. But between them devourers and nasty elementals formin' from all that wild muck, I can't get close enough to feed it! Help me out and throw some of that filthy rubble into the pool, yeah?",objectivesText="Throw 6 Filthy Rubble into the muck pool.",rewardGold=257400,rewardXP=8165,starts={{npcID=157846}},ends={{npcID=157846}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[62194] = {id=62194,name="Fighting Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="Throughout the Shadowlands, there is so much magic to learn! A threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can! Help me fight back the Forsworn at the Temple of Humility and save the scrolls within.",rewardXP=8165,rewardItems={183744,182485,182494,182503,182512,184843},starts={{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.548,y=0.688,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Fighting Words"},
[62195] = {id=62195,name="The Last Word",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1536,description="Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away. I've heard she will share her knowledge with anyone that releases her from imprisonment. I want to learn all she knows! We must free her!",rewardXP=8165,rewardItems={182957},starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="The Last Word"},
[62200] = {id=62200,name="Functioning Anima Core",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<The incomprehensible core whirs with a pleasant hum. Surely someone would have a use for this? >",objectivesText="Deliver the Functioning Anima Core to Kalisthene .",rewardGold=514800,rewardXP=1770,ends={{npcID=156217},{npcID=163427},{npcID=165045},{npcID=168517}},coords={mapID=1533,source="quest_giver",x=0.535,y=0.87},questType="standard"},
[62203] = {id=62203,name="Major Mirror Disruptions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166454,text="Reach the end of the maze"}},worldTaskTitle="Major Mirror Disruptions",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62204] = {id=62204,name="Major Mirror Disruptions",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166454,text="Reach the end of the maze"}},worldTaskTitle="Major Mirror Disruptions",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62205] = {id=62205,name="Venthyr Ettiquette",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: Is that Theotar's new book?",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62206] = {id=62206,name="Ardenweald Etiquette",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: Ooh, I am beginning to like these books.",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62207] = {id=62207,name="Bastion Etiquette",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: That looks like a 'big' book.",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62208] = {id=62208,name="Maldraxxi Protocols",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: It looks shorter than the others, but... are those bullets?",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62209] = {id=62209,name="Houndmaster Vasanok",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Houndmaster Vasanok"},
[62210] = {id=62210,name="Sanngror the Torturer",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Sanngror the Torturer"},
[62211] = {id=62211,name="Skittering Broodmother",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Skittering Broodmother"},
[62213] = {id=62213,name="A Brokered Deal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="Hey, . I've found a lucrative business proposition that'll help me... us... greatly! See, Au'narim is willing to give us supplies if we can help him recover from a trade deal that went sideways. Apparently, several of his cohorts never returned from a job. He needs us to follow their path and recover the item they failed to deliver. Simple, right? To ensure we don't have any mishaps, I've taken the liberty of acquiring a few items that may be of help to us. So, you in?",rewardXP=8165,rewardItems={178681,183119},starts={{npcID=159238}},ends={{npcID=159830}},coords={x=0.552,y=0.682,source="quest_giver",mapID=2151},questType="standard"},
[62214] = {id=62214,name="Forces of Perdition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Survival requires that we keep our enemies in check, Maw Walker. With Gorgoa overflowing, the Mawsworn continue to gain strength. Perdition Hold has been fortified with fresh troops. We cannot allow the Mawsworn to bolster their ranks any further. Make your way into Perdition Hold and decimate their forces. When the work is done, you may return to me for your reward.",rewardItems={177698,177699,178874,178877,178880,178881,178882,178883,185717},rewardCurrencies={{id=1767,amount=600},{id=1880,amount=475}},starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Forces of Perdition",db2QuestInfoID=1,db2QuestInfoName="Group"},
[62216] = {id=62216,name="Training Program",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Sergeant Krashj is an adequate drill master, but these recruits need proper training with a real warrior. Someone who has been bloodied on the battlefield. Someone like me! And I know just the fight that will whip these troops into shape. Let's go teach them a thing or three.",objectivesText="Slay Decadious .",rewardXP=8165,rewardItems={183744,182482,182491,182500,182509,184843},starts={{npcID=158259},{npcID=158301}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[62217] = {id=62217,name="Field Training",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="Though it was not by our hand, Maldraxxus has dealt a great injustice to the kyrian of Bastion. We must do all that we can to make amends. The Forsworn menace continues to be a thorn in their side. Sounds like the perfect opportunity to both show our support and for our recruits to gain some combat experience.",objectivesText="Eliminate 15 Forsworn forces at The Eternal Forge in Bastion.",rewardXP=8165,rewardItems={183744,182482,182491,182500,182509,184843},starts={{npcID=158259},{npcID=158301}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[62218] = {id=62218,name="A Fountain for Fae",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1533,description="Nuuminuuru spends their days protecting and taking care of many faeries throughout Ardenweald. They have expressed concern about some faeries in their care whom they have not seen in some time. Report to Nuuminuuru and see if you can help them find their scattered sprites.",objectivesText="Report to Nuuminuuru in Glitterfall Basin in Ardenweald. Progress: A greeting to you, ally of the soulbearers.",rewardGold=257400,rewardItems={181275},starts={{npcID=168430}},ends={{npcID=173710}},coords={x=0.63,y=0.16,source="quest_giver",zoneID=10534},questType="standard"},
[62219] = {id=62219,name="Fanciful Distractions",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ever chasing their fleets of fancy, my faerie friends are seldom seen. Their mercurial natures oft lead them astray, tracing them paths to distraction and dismay. Seek my friends, insist they return to my roots, and both you and they may receive recompense.",objectivesText="Find Riverblossom , Lunarwind , and Flitterfly and convince them to return to Nuuminuuru . Progress: My wards know to return to my roost, to spin stories of their pursuits and strengthen their spirits. The longer they flit away, the deeper the creases of my concern grow.",rewardGold=257400,rewardItems={182974},starts={{npcID=173710}},ends={{npcID=173710}},coords={x=0.514,y=0.336,source="quest_giver",zoneID=11510},questType="standard"},
[62221] = {id=62221,name="My Own Death Pony!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,objectivesText="Progress: That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...",starts={{npcID=173721}},ends={{npcID=173721},{npcID=172854}},coords={x=0.362,y=0.468,source="quest_giver",zoneID=10413},questType="standard"},
[62222] = {id=62222,name="On Silver Wings",level=60,requiredLevel=60,faction="both",expansion=8,objectivesText="Progress: What do you intend for me to do with that thing?",starts={{npcID=172854}},questType="standard"},
[62223] = {id=62223,name="Ascension Calling: Mikanikos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Mikanikos to participate in the Path, along with Bron. Perhaps you should bring this to Mikanikos .>",objectivesText="Inform Mikanikos he is now able to participate in the Path of Ascension.",rewardGold=25740,rewardXP=1020,ends={{npcID=160391}},coords={mapID=1533,source="quest_giver",x=0.656286,y=0.166571},questType="standard"},
[62224] = {id=62224,name="A Thread Of Hope",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="The Court of Night is akin to a thirsty flower, it quickly draws up its nutrients. If well supplied it will bloom and if its supply is depleted, it withers. Our roots are beginning to dry, we need more anima! I've sent workers out to place silk lined catchers along the roads and paths that cross Ardenweald. These catchers will collect a tiny bit of anima, not much but enough for what we need. Seek them out and return the Anima Infused Silk to us.",objectivesText="Collect 13 Anima Infused Silk Progress: Were you able to find the silk?",rewardGold=257400,rewardItems={183041},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=173277}},ends={{npcID=173277}},coords={x=0.596,y=0.528,source="quest_giver",zoneID=11510},questType="standard"},
[62225] = {id=62225,name="Bursting the Bubble",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="<The words of the shadowy herald are dark and foreboding. Whatever \"the Banished One\" intends to accomplish, it must not come to pass. Something foul bubbles within the cauldrons nearby. Judging by the care with which the cultists are tending to them, their contents must be crucial to their plans. Several barrels containing what appears to be a new type of plague have been left unattended. Perhaps they can serve as instruments for sabotage.>",objectivesText="Sabotage 3 of the Cult of the Damned's experiments in Mord'rethar. Progress: What have you discovered?",rewardGold=257400,rewardXP=6815,rewardCurrencies={{id=1754,amount=1}},starts={{npcID=170467},{npcID=357758}},ends={{npcID=170467}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="standard"},
[62226] = {id=62226,name="Talethi's Desire",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62227] = {id=62227,name="Xertora's Construct",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62229] = {id=62229,name="Ashraka's Intelligence",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62231] = {id=62231,name="Velkein's Blade",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62232] = {id=62232,name="Arboreal Tactics",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1536,description="The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands. Let's test these troops against a real opponent.",objectivesText="Eliminate 12 Bristlecone Spriggan in Mistveil Tangle in Ardenweald.",rewardXP=8165,rewardItems={183744,182482,182491,182500,182509,184843},starts={{npcID=158259},{npcID=158301}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[62234] = {id=62234,name="Power of the Colossus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have another task for you, Maw Walker. Deep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us. Travel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw , you will find the Soulsteel Colossus. Shatter the colossus and bring me its power source as proof of your victory.",rewardItems={183042},rewardCurrencies={{id=1767,amount=600}},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group",worldTaskTitle="Power of the Colossus",db2QuestInfoID=1,db2QuestInfoName="Group"},
[62235] = {id=62235,name="Allay Their Fears",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={183045},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=175556,text="Korinna's Allaying Crook"},{orderIndex=1,type=0,amount=1,objectID=173763,text="Allaying Crook charged"},{orderIndex=2,type=0,amount=20,objectID=173762,text="Wildlife absorbed"},{orderIndex=4,type=0,amount=1,objectID=173773,text="Allaying Ritual completed"}},worldTaskTitle="Allay Their Fears",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62236] = {id=62236,name="Rattlebag's Lost Armor",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62237] = {id=62237,name="Mysterious Soul Mirror",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Thenios will want to see this.>",objectivesText="Bring the Mysterious Soul Mirror to Thenios at the temple in the Eonian Archives. Progress: How can I be of service?",rewardGold=25740,rewardXP=1020,ends={{npcID=154629},{npcID=173771}},coords={mapID=1533,source="quest_giver",x=0.52,y=0.195},questType="standard"},
[62238] = {id=62238,name="Soul Led Astray",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life. I believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.",objectivesText="Use the Soul Mirror at the Eonian Archives to view Uther's arrival in Bastion . Progress: Sometimes the hard truths are the most important to witness.",rewardGold=25740,rewardXP=1020,starts={{npcID=154629},{npcID=173771}},ends={{npcID=154629},{npcID=173771}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[62239] = {id=62239,name="Rodent Removal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,rewardItems={183105},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=365084,x=0.603,y=0.721,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.603,y=0.721,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Rodent Removal"},
[62241] = {id=62241,name="Training Regimen",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={183121},questType="world",db2Objectives={{orderIndex=0,type=14,amount=1,objectID=87409,text="Gatamatos retrieved"},{orderIndex=5,type=0,amount=1,objectID=159878,text="First formation complete"},{orderIndex=6,type=0,amount=1,objectID=159888,text="Second formation complete"},{orderIndex=7,type=0,amount=1,objectID=159889,text="Third formation complete"},{orderIndex=8,type=0,amount=1,objectID=159686,text="Gatamatos placed"},{orderIndex=4,type=0,amount=1,objectID=158765,text="Speak to Pelodis"}},worldTaskTitle="Training Regimen",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62244] = {id=62244,name="Digging Around",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1536,description="The thin pale ones of Revendreth have been hoarding anima. I've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it. I say that should be us! Let's go get some anima.",objectivesText="Collect 15 Lost Anima Caches .",rewardXP=8165,rewardItems={183744,182488,182497,182506,182515,184843},starts={{npcID=159212}},ends={{npcID=167150}},coords={x=0.548,y=0.678,source="quest_giver",zoneID=11462},questType="standard"},
[62246] = {id=62246,name="A Fallen Friend",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \"Until Winter's end. - Flwngyrr \"",objectivesText="Return this bracelet to Flwngyrr at the Heart of the Forest Provided item:",rewardGold=505440,rewardXP=1770,ends={{npcID=168032}},coords={mapID=1565,source="quest_giver",x=0.484,y=0.505},questType="standard"},
[62250] = {id=62250,name="A New Adventure Awaits",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1637,mapID=84,description="! You're needed in the present. Things have... well, you should just come back to see. I would finish what you're doing then head back. I can't keep you in the past for much longer!",objectivesText="Return to Stormwind to embark on a new adventure. Chromie 's magic will run out soon, returning you to Stormwind.",rewardGold=200,rewardXP=175,rewardItems={183185},ends={{npcID=101759},{npcID=172334},{npcID=189569}},coords={mapID=84,source="quest_giver",x=0.762,y=0.172},questType="standard"},
[62256] = {id=62256,name="Asset Extraction",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="Hey, it's my good pal ! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept. The deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property. The associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! So, you ready to go?",rewardXP=8165,rewardItems={178681,183130,183166},starts={{npcID=158259},{npcID=159238}},ends={{npcID=166640}},coords={x=0.504,y=0.474,source="quest_giver",mapID=2151},questType="standard"},
[62258] = {id=62258,name="Soaring Over Bastion",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,rewardItems={183140},questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=160255,text="Andira mounted"},{orderIndex=3,type=15,amount=1,objectID=0,text="Fly through the rings"},{orderIndex=1,type=0,amount=1,objectID=173946,text="Antlers placed"}},worldTaskTitle="Soaring Over Bastion",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62259] = {id=62259,name="Anima-Laden Dreamcatcher",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You stumble upon an enchanted dreamcatcher, placed so remotely that it has managed to collect a significant amount of anima without being harvested. Droman Dawnblossom in nearby Dreamsong Fenn would surely appreciate its safe return.",objectivesText="Return the Enchanted Dreamcatcher to Droman Dawnblossom in Dreamsong Fenn. Provided item:",rewardGold=514800,rewardXP=1770,ends={{npcID=165341}},coords={mapID=1565,source="quest_giver",x=0.38,y=0.368},questType="standard"},
[62261] = {id=62261,name="Grinder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It's tough keeping these hands of mine razor sharp. With all the hacking and cleaving, they can grow dull so quickly! What's a girl to do? The House of the Chosen makes some very fine quality sharpening stones. I doubt they will just hand them over, but I'm sure my blades can persuade them otherwise. How about we pay them a visit and see how many stones they can spare?",objectivesText="Collect 12 Sharpening Stones and 3 Bonesheared Grinders . Progress: Did you kill them all?",rewardXP=8165,rewardItems={183138},starts={{npcID=158259},{npcID=159214}},ends={{npcID=167150}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="standard"},
[62263] = {id=62263,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62265] = {id=62265,name="A New Adventure Awaits",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=1,description="! You're needed in the present. Things have... well, you should just come back to see. I would finish what you're doing then head back. I can't keep you in the past for much longer!",objectivesText="Return to Orgrimmar to embark on a new adventure. Chromie's magic will run out soon, returning you to Orgrimmar.",rewardGold=30900,rewardXP=175,ends={{npcID=190239}},coords={mapID=1,source="quest_giver",x=0.558,y=0.126},questType="standard"},
[62275] = {id=62275,name="Bastion",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="After being set back by a surprise attack by Maldraxxus forces and an army of their own fallen kin known as the Forsworn, the Ascended stand to lose control of Bastion if they are not given aid.",objectivesText="Speak with Tal-Inara .",rewardGold=23400,rewardXP=850,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62276] = {id=62276,name="Drink to the Dead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="The Forsworn are ravaging the temples of Bastion, and the aspirants are leaving behind their supplies as they flee. All those wonderful bottles of nectar falling into the hands of the Forsworn? I think not! There's no way we can save all of the aspirants, but we can keep the Forsworn from taking those supplies. Besides... we could all use something to drink around here.",objectivesText="24 Purified Nectar and 2 Stewards collected Progress: Did you find us some supplies?",rewardXP=8165,rewardItems={183186},starts={{npcID=158298}},ends={{npcID=167150}},coords={x=0.548,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[62277] = {id=62277,name="Ardenweald",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="Ardenweald still faces threats from the Drust, as well as other nefarious forces. The Winter Queen could use your aid in fending off the forces that seek to destroy Ardenweald.",objectivesText="Speak with Tal-Inara .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62278] = {id=62278,name="Maldraxxus",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="With the houses in shambles, the loyal army of the Primus struggles to hold their ground in Maldraxxus. They need help to tip the scales in their favor.",objectivesText="Speak with Tal-Inara .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62279] = {id=62279,name="Revendreth",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="Chaos rules Revendreth in the wake of Sire Denathrius's betrayal. They are in dire need of your aid!",objectivesText="Speak with Tal-Inara .",rewardGold=23400,rewardXP=850,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[62280] = {id=62280,name="Limbo",expansion=8,mapID=1533,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=174007,text="First soul assessed"},{orderIndex=1,type=0,amount=1,objectID=174008,text="Second soul assessed"},{orderIndex=2,type=0,amount=1,objectID=174029,text="Third soul assessed"}},worldTaskTitle="Limbo",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62292] = {id=62292,name="Pitch Black Scourgestones",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,objectivesText="Progress: The most powerful of the undead carry scourgestones imbued with the darkest magic. We do not know from whence they came, but their power is unlike any we have encountered before. Please relinquish any you find to the Argent Crusade. Who knows what foul evil may be lurking within them?",rewardItems={12844},rewardCurrencies={{id=1754,amount=3}},starts={{npcID=169718}},ends={{npcID=169718}},coords={x=0.71,y=0.216,source="quest_giver",zoneID=210},questType="standard"},
[62293] = {id=62293,name="Darkened Scourgestones",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,objectivesText="Progress: Scourgestones were once common amongst the minions of the Lich King. But these new ones are different... and darker. Bring them to us as you find them. They will serve both a mark of your victories, and as an opportunity for us to study their strange magic.",rewardItems={12844},rewardCurrencies={{id=1754,amount=1}},starts={{npcID=169718}},ends={{npcID=169718}},coords={x=0.71,y=0.216,source="quest_giver",zoneID=210},questType="standard"},
[62294] = {id=62294,name="One Lich's Trash...",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It is said that one person's trash, is another's treasure. When it comes to relics, the adage is particularly true. The House of Rituals is notoriously secretive, which means any knowledge we can glean from them will be all the sweeter. If we sift through their detritus, I'm sure there are all sorts of treasures we will find.",objectivesText="Search through Piles of Debris within the House of Rituals for clues about its past, and recover an Intriguing Ancient Relic . Progress: Did you find anything of interest?",rewardXP=8165,rewardItems={183398},starts={{npcID=159198}},ends={{npcID=167150}},coords={x=0.552,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[62296] = {id=62296,name="Into the Unknown",level=60,requiredLevel=60,faction="both",expansion=8,description="Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?",objectivesText="Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62297] = {id=62297,name="A Fatal Failure",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Acolyte, we could use a hand here! It seems one of your fellow pupils botched their ritual in spectacular fashion. Now destructive necromantic energies are running rampant throughout the house. This threat must be dealt with. Can you assist?",objectivesText="Kill 7 Fatal Coalescences in the House of Rituals. Progress: Have you taken care of the threat, acolyte?",rewardGold=257400,rewardXP=8165,rewardItems={183394},starts={{npcID=174020}},ends={{npcID=174020}},coords={x=0.704,y=0.278,source="quest_giver",zoneID=11462},questType="standard"},
[62298] = {id=62298,name="Classic 20-49",level=20,requiredLevel=20,faction="none",expansion=8,rewardXP=4150,rewardItems={135539},questType="standard"},
