[62308] = {id=62308,name="Mantle of Mastery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle . When you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus . Conquer the spirit, and prove your mettle!",objectivesText="Summon an elder spirit of Maldraxxus through the Prime Arcanum and defeat it. Summoning requires three players.",rewardGold=772200,rewardXP=12250,rewardItems={183399},starts={{npcID=172813}},ends={{npcID=172813}},coords={x=0.678,y=0.306,source="quest_giver",zoneID=11462},questType="group"},
[62309] = {id=62309,name="Adventurer: Secutor Mevix",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,starts={{npcID=165321}},ends={{npcID=165321}},coords={x=0.39,y=0.48,source="quest_giver",mapID=1698},questType="standard"},
[62312] = {id=62312,name="Adventurer: Gunn Gorgebone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,starts={{npcID=165321}},ends={{npcID=165321}},coords={x=0.39,y=0.48,source="quest_giver",mapID=1698},questType="standard"},
[62313] = {id=62313,name="Adventurer: Rencissa the Dynamo",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,starts={{npcID=165321}},ends={{npcID=165321}},coords={x=0.39,y=0.48,source="quest_giver",mapID=1698},questType="standard"},
