[62361] = {id=62361,name="Introductions are in Order",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16981,mapID=1525,description="Now yous is all set with yer new dredger, go ahead call on them and officially introduce yerself.",objectivesText="Talk with your new Dredger Butler .",rewardGold=25740,rewardXP=1020,starts={{npcID=157846}},ends={{npcID=172854}},coords={x=0.726,y=0.732,source="quest_giver",zoneID=10413},questType="standard"},
[62362] = {id=62362,name="Volatile Reactions",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The living slime within Maldraxxus naturally produces a powerful catalyst used in many of the House of Eyes's poisons. There is always a need for the substance. It would be of great help if you could retrieve some for us.",rewardGold=257400,rewardItems={183436},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Volatile Reactions"},
[62363] = {id=62363,name="Heavy Lifting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The stronger members of the House of the Chosen tend to take a fairly specific form. No doubt you've seen the larger warriors in the house? They are the greatest threat in their collective force. Thin them out.",rewardGold=257400,rewardItems={181501,181638,181645,181647,181649,181650,181653,181654,181660,181663,181665,181667,181668,181669,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Heavy Lifting"},
[62364] = {id=62364,name="Dire Learning",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Necromancers and liches often use powerful tomes to assist in their rituals. Now that the House of Rituals has expanded their reach, the tomes can be found anywhere where their members are active. Find these books and destroy them. It won't end their vile experiments but it should at least delay them.",rewardGold=257400,rewardItems={181502,181503,181507,181625,181626,181638,181645,181647,181648,181649,181650,181651,181658,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Dire Learning"},
[62366] = {id=62366,name="Round 3",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62367] = {id=62367,name="Round 1",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62368] = {id=62368,name="Rebuild Our Trust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,description="Well , it seems you are serious about earning your way back into our good graces. It seems you are serious about this penance. This task should prove your willingness to rejoin our ranks.",objectivesText="Complete the task for the Kyrian.",rewardGold=128700,rewardXP=4085,starts={{npcID=171787}},ends={{npcID=171787}},questType="standard"},
[62371] = {id=62371,name="Tirna Scithe: A Warning Silence",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13334,mapID=1565,description="The songs of Tirna Scithe have faded as the grove wanes, yet there is now silence. Droman Oulfarran's voice has not been heard in some time. The trees whisper of penumbral shadows, discordant songs, and dying roots. All is not well. Friend of Ardenweald, travel to Root-home. Delve into the Mists. Remove that which threatens us.",objectivesText="Defeat Tred'ova in The Mists of Tirna Scithe. Progress: What has silenced the grove of Tirna Scithe?",rewardGold=1029600,rewardXP=13630,rewardItems={184515,184516,184517,184518},rewardChoices={184516,184517,184518,184515},starts={{npcID=168032}},ends={{npcID=168032}},coords={x=0.484,y=0.504,source="quest_giver",zoneID=11510},questType="dungeon"},
[62373] = {id=62373,name="Round 2",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62374] = {id=62374,name="Round 3",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62382] = {id=62382,name="Into the Unknown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?",objectivesText="Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62385] = {id=62385,name="Round 1",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62386] = {id=62386,name="Round 2",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62387] = {id=62387,name="Round 3",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,questType="standard"},
[62388] = {id=62388,name="House of Rituals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The Ritualists are the ones behind this war. Every act of treason has been committed under their orders. We cannot defeat their sorcery with strength of arms alone. Victory will hinge on our knowledge of what they are plotting. Continue to bolster our forces. I will look for a way to infiltrate the House of Rituals.",objectivesText="Increase your Renown.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62389] = {id=62389,name="Rebuild Our Trust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,description="So you have taken the first step to reclaiming our trust. Now you must prove that was not another false start in our relationship. This final task should prove your willingness to rejoin our ranks.",objectivesText="Complete the task for the Venthyr.",rewardGold=128700,rewardXP=4085,starts={{npcID=171589}},ends={{npcID=171589}},questType="standard"},
[62390] = {id=62390,name="Body Count",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I am acquainted with a few fleshcrafters who work outside of the House of Constructs. If we can find reagents for them, they can supply our war effort with constructs. The House of Constructs has plenty of excess body parts. Find them and bring them back here.",rewardGold=257400,rewardItems={183600},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Body Count"},
[62391] = {id=62391,name="Mobilize Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="It will be difficult to reach Kel'Thuzad while he is in his necropolis. Go now. It will take time for us to muster an army that can pierce his defenses.",objectivesText="Increase your Renown.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62392] = {id=62392,name="Rebuild Our Trust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,description="You return as requested. Impressive, maybe you have indeed turned a new leaf. I wish to see you complete one more task for us. To prove your dedication to this transition. Not that we doubt you, but you must understand your previous behavior gives us reason to doubt that dedication.",objectivesText="Complete the task for the Night Fae.",rewardGold=128700,rewardXP=4085,starts={{npcID=171795}},ends={{npcID=171795}},questType="standard"},
[62393] = {id=62393,name="Rebuild Our Trust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,description="You still have the same strength you had before it seems. The question is - do you have any loyalty left within you? I have one more task so you can demonstrate that loyalty again.",objectivesText="Complete the task for the Necrolords.",rewardGold=128700,rewardXP=4085,starts={{npcID=171821}},ends={{npcID=171821}},questType="standard"},
[62394] = {id=62394,name="House In Decline",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Our forces are gathering. Soon it will be time to move against the House of Rituals. See what you can do to continue strengthening our position.",objectivesText="Increase your renown.",rewardGold=25740,rewardXP=1020,questType="standard"},
[62400] = {id=62400,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62401] = {id=62401,name="Strange Scourgestones",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=210,mapID=118,description="The Lich King's minions once carried scourgestones given to them by their dark master. New ones have been found on the corpses of the undead. We do not know their purpose... but they have been touched by even more sinister magic. As you slay the Scourge across Icecrown, keep your eyes open for such stones. If you bring them back to me, I shall turn them over to the confessors for study.",objectivesText="Collect Darkened Scourgestones and Pitch Black Scourgestones from undead forces in Icecrown. Progress: How goes your slaying of the undead?",rewardGold=257400,rewardXP=6815,rewardItems={12844},rewardCurrencies={{id=1754,amount=5}},starts={{npcID=169718}},ends={{npcID=169718}},coords={x=0.71,y=0.216,source="quest_giver",zoneID=210},questType="standard"},
[62403] = {id=62403,name="Boared to Death",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1536,description="The boars around Maldraxxus have a peculiar trait. Their tusks absorb liquid. Depending on where it has been, these bones may contain a powerful compound of poisons or other alchemical rarities. It takes a trained eye to tell what the bone is made of, so just bring back a large amount of them. From there I will see if any of them are valuable.",objectivesText="Collect 25 bloody tusks from the boars in Maldraxxus . Progress: Take care not to let any of the bones touch your skin for too long. They may cause irritation.",rewardGold=257400,rewardItems={183620},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=167603}},ends={{npcID=167603}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="standard"},
[62406] = {id=62406,name="Staff of the Primus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The Staff of the Primus . The final piece of our leader's regalia. I can't deny the pride I feel in restoring this hall. You should feel the same sense of accomplishment. The statue awaits you, . Bring glory to this realm.",objectivesText="Place the Staff of the Primus upon the Statue of the Primus.",rewardGold=772200,rewardXP=12250,rewardItems={183888,183889,183890,183891,183892,183893},rewardChoices={183892},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62407] = {id=62407,name="Herbicidal Tendencies",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1536,description="My gas is the most potent in all of Maldraxxus, but I've heard some of the others saying that it's not the strongest in the Shadowlands. They claim there are some plants in Ardenweald with a bloom that is far more pungent than my gas. Nonsense! Let's go and check these plants out. If their stench is as strong as the stories claim, I might even be able to mix them in with my own gas!",objectivesText="Help Gas Bag collect Rotbloom Petals . Progress: Having fun picking flowers?",rewardXP=8165,rewardItems={183719},starts={{npcID=159240}},ends={{npcID=167150}},coords={x=0.542,y=0.68,source="quest_giver",zoneID=11462},questType="standard"},
[62414] = {id=62414,name="Burying Suspicion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It will do us no good to disguise yourself as Nelesis if word reaches Kel'Thuzad that she was slain. You must ensure that no one who sees you enter the cave survives.",objectivesText="Kill 10 Lichsworn forces outside the House of Rituals.",starts={{npcID=173422}},ends={{npcID=173422}},questType="standard"},
[62417] = {id=62417,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",rewardGold=257400,rewardXP=8165,rewardItems={183697},rewardCurrencies={{id=1877,amount=1}},questType="standard"},
[62420] = {id=62420,name="Snapper Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Snapper Soul is determined. The shape of the dragon turtle will be yours to call upon.>",objectivesText="Bring the Snapper Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62421] = {id=62421,name="Gulper Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Gulper Soul is patient and calm. The shape of the Gulper will be yours to call upon.>",objectivesText="Bring the Gulper Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62422] = {id=62422,name="Ardenmoth Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald . Delicate looking creatures, they have hidden strength. Their magic can soothe the most tortured soul... or send the unwary into an eternal sleep. The shape of the moth will be yours to call upon.>",objectivesText="Bring the Ardenmoth Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62423] = {id=62423,name="Ursine Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ursine Soul is stalwart and brave. The shape of the bear will be yours to call upon.>",objectivesText="Bring the Ursine Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62424] = {id=62424,name="Crane Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Crane Soul dances with grace. The shape of the crane will be yours to call upon.>",objectivesText="Bring the Crane Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62425] = {id=62425,name="Veilwing Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald is more respected for its fierce defense of its family or territory than the veilwing. You have defeated a foe who endangered not only Ardenweald , but all of the Shadowlands. For this, Champion of Ardenweald , you have earned a special boon - the ability to call upon the essence of the veilwing and take their shape.>",objectivesText="Bring the Veilwing Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62426] = {id=62426,name="Gryphon Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Gryphon Soul is agile and swift. The shape of the gryphon will be yours to call upon.>",objectivesText="Bring the Gryphon Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62427] = {id=62427,name="Hippogryph Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Hippogryph Soul is intelligent and valiant. The shape of the hippogryph will be yours to call upon.>",objectivesText="Bring the Hippogryph Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62428] = {id=62428,name="Equine Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Equine Soul is free-spirited and loyal. The shape of a horned horse will be yours to call upon.>",objectivesText="Bring the Equine Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62429] = {id=62429,name="Leonine Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="<The Leonine sine Soul is powerful and brave. The shape of the lion will be yours to call upon.>",objectivesText="Bring the Leonine Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62430] = {id=62430,name="Moose Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Moose Soul endures and protects. The shape of the moose will be yours to call upon.>",objectivesText="Bring the Moose Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62431] = {id=62431,name="Shadowstalker Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Shadowstalker Soul is cunning and careful. The shape of the Shadowstalker will be yours to call upon.>",objectivesText="Bring the Shadowstalker Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62432] = {id=62432,name="Owlcat Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Owlcat Soul is a curious trickster, a beast of many parts working together in a playful balance, always seeking the next challenge. The shape of the owlcat will be yours to call upon.>",objectivesText="Bring the Owlcat Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62433] = {id=62433,name="Raptor Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Raptor Soul is loyal and fierce. The shape of the raptor will be yours to call upon.>",objectivesText="Bring the Raptor Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62434] = {id=62434,name="Runestag Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Runestag Soul is calm and enduring. The shape of the Runestag will be yours to call upon.>",objectivesText="Bring the Runestag Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62435] = {id=62435,name="Stag Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Stag Soul is noble and mighty. The shape of the stag will be yours to call upon.>",objectivesText="Bring the Stag Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62436] = {id=62436,name="Shrieker Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Shrieker Soul is swift and fierce. The shape of the veil shrieker will be yours to call upon.>",objectivesText="Bring the Shrieker Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62437] = {id=62437,name="Tiger Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Tiger Soul is proud and strong. The shape of the tiger will be yours to call upon.>",objectivesText="Bring the Tiger Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62438] = {id=62438,name="Lupine Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Lupine Soul is a fierce and free-spirited protector. The shape of the wolf will be yours to call upon.>",objectivesText="Bring the Lupine Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62439] = {id=62439,name="Wolfhawk Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Wolfhawk Soul is cunning hunter. The shape of the wolfhawk will be yours to call upon.>",objectivesText="Bring the Wolfhawk Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62440] = {id=62440,name="Wyvern Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Wyvern Soul is proud and determined. The shape of the wyvern will be yours to call upon.>",objectivesText="Bring the Wyvern Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[62441] = {id=62441,name="Fair Exchange for a Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="While we work away here in the Conservatory, we must not forget to support the rest of the covenant. I am needed here, but you can range far, even though your legs are short. Please, help our covenant recover the anima we need. I can then dedicate my time to preparing another spirit for you to restore.",objectivesText="Collect anima for your Sanctum. Progress: Go, find more anima. I shall tend to the spirits while you do.",rewardGold=257400,rewardXP=8165,rewardItems={177699,178877,178880,178883},rewardChoices={178880,178877,178883,177699},starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[62442] = {id=62442,name="Aid the Covenant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.",objectivesText="Complete a World Quest in Ardenweald.",rewardGold=257400,rewardXP=8165,rewardItems={176921},starts={{npcID=174324}},ends={{npcID=174324}},coords={x=0.324,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[62443] = {id=62443,name="Aid the Covenant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.",objectivesText="Complete a World Quest in Ardenweald.",rewardGold=257400,rewardXP=8165,rewardItems={176832},starts={{npcID=174324}},ends={{npcID=174324}},coords={x=0.324,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[62444] = {id=62444,name="Aid the Covenant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!",objectivesText="Complete a World Quest in Ardenweald. Progress: Head out into the Shadowlands. Return to me with stories of your exploits.",rewardGold=257400,rewardXP=8165,rewardItems={176922},starts={{npcID=174324}},ends={{npcID=174324}},coords={x=0.324,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[62445] = {id=62445,name="A Spirit's Pride",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I seek to understand more about the prideful beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.",objectivesText="Place a Prideful Spirit into a wildseed. Progress: Find a prideful spirit to restore. That is what I wish to see today.",rewardGold=257400,rewardXP=8165,rewardItems={176832,176921,176922},rewardChoices={176922,176921,176832},starts={{npcID=174273}},ends={{npcID=174273}},coords={x=0.246,y=0.538,source="quest_giver",zoneID=13367},questType="standard"},
[62447] = {id=62447,name="A Rare and Unusual Spirit",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I have a mystery for you, ! Who doesn't savor a good mystery? We have found a spirit unlike any other, one who does not respond to being placed in a wildseed. Each of us who touched it experienced a dream in which we saw you battling a great beast. Only when you defeated it did the spirit begin on its path to rebirth. We think we know the beast. Are you up for discovering if these dreams were a portent?",objectivesText="Defeat Tred'ova in Mists of Tirna Scithe.",rewardItems={183704},starts={{npcID=171107}},ends={{npcID=171107}},coords={x=0.416,y=0.522,source="quest_giver",zoneID=13367},questType="standard"},
[62448] = {id=62448,name="Securing the House",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Your journey into the Maw was impressive, but it will take even more phenomenal feats to earn the loyalty of the Maldraxxi. Increase your renown among our ranks, Maw Walker. The Maldraxxi are dedicated soldiers, but they will not follow just anyone into battle. Let your deeds prove your worth to them.",objectivesText="Increase your Renown.",rewardGold=128700,rewardXP=4085,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62449] = {id=62449,name="A Spirit's Duty",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I seek to understand more about the Dutiful beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.",objectivesText="Place a Dutiful Spirit into a wildseed. Progress: Find a Dutiful spirit to restore. That is what I wish to see today.",rewardGold=257400,rewardXP=8165,rewardItems={176832,176921,176922},rewardChoices={176922,176921,176832},starts={{npcID=174273}},ends={{npcID=174273}},coords={x=0.246,y=0.538,source="quest_giver",zoneID=13367},questType="standard"},
[62450] = {id=62450,name="A Spirit's Heart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I seek to understand more about the Untamed beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.",objectivesText="Place an Untamed Spirit into a wildseed. Progress: Find an Untamed spirit to restore. That is what I wish to see today.",rewardGold=257400,rewardXP=8165,rewardItems={176832,176921,176922},rewardChoices={176922,176921,176832},starts={{npcID=174273}},ends={{npcID=174273}},coords={x=0.246,y=0.538,source="quest_giver",zoneID=13367},questType="standard"},
[62451] = {id=62451,name="Assault on the Vestibule",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,rewardXP=8165,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=174303,text="Take the Colossal Core"},{orderIndex=1,type=0,amount=1,objectID=174304,text="Charge the Colossal Core"},{orderIndex=2,type=15,amount=1,objectID=0,text="Charge the Colossal Core"},{orderIndex=9,type=0,amount=1,objectID=174305,text="Insert the Colossal Core"},{orderIndex=10,type=0,amount=1,objectID=174306,text="Push the Button"}},worldTaskTitle="Assault on the Vestibule",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62452] = {id=62452,name="A Spirit's Might",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I seek to understand more about the Martial beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.",objectivesText="Place a Martial Spirit into a wildseed. Progress: Find a Martial spirit to restore. That is what I wish to see today.",rewardGold=257400,rewardXP=8165,rewardItems={176832,176921,176922},rewardChoices={176922,176921,176832},starts={{npcID=174273}},ends={{npcID=174273}},coords={x=0.246,y=0.538,source="quest_giver",zoneID=13367},questType="standard"},
[62453] = {id=62453,name="Into the Unknown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, ? Up for an adventure?",objectivesText="Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!",rewardGold=257400,rewardXP=8165,rewardItems={183961},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62454] = {id=62454,name="A Rare and Unusual Spirit",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I awaken. I exist once more. And yet... There is an emptiness within. A lingering tether to a home that no longer exists. So much wonder... so much splendor... lost. Now I have no purpose. No fate. No path. Will you teach me of this place, awakener? I sense there is much to be understood. Many secrets. Many truths. In so doing, perhaps a new fate will emerge.",objectivesText="Speak to Falir and bring them essences from the realms of the Shadowlands. Progress: Return to me when you have the essences from each realm.",starts={{npcID=174329}},ends={{npcID=174329}},coords={x=0.246,y=0.538,source="quest_giver",zoneID=13367},questType="standard"},
[62456] = {id=62456,name="De Other Side: Dealin' Wit' Da Boss",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13309,description="Ay, mon. Long time no see! I be havin' a bit of trouble wit' me boss, Mueh'zala. Now, now... don't you worry. Your ol' friend Bwonsamdi got dis whole ting under control! I just be needin' some help gatherin' me mojo back from a few ungrateful business partners. You bring me da mojo, and we goin' ta take care of ol' Mueh'zala once and for all!",objectivesText="Defeat Mueh'zala in De Other Side. Progress: First you get da mojo, then I get da powa'... then we be gettin' Mueh'zala!",rewardItems={184519},starts={{npcID=174327}},ends={{npcID=168141},{npcID=174327}},questType="dungeon"},
[62458] = {id=62458,name="De Other Side",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13309,mapID=1565,description="Ay, dere ! Ya be just da I've been lookin' for! It be your ol' pal Bwonsamdi reachin' out ta ya from De Other Side! I be havin' a little problem over here wit' de boss... Ya be lookin' mighty bored just standin' around here in Ardenweald. Why don't ya come to De Other Side and help out an ol' friend? Bwonsamdi promise he gonna make it worth ya while! Ya might want ta bring a few more adventurers wit' ya... just ta be safe.",objectivesText="Speak with the Mask of Bwonsamdi in De Other Side.",rewardGold=18925,starts={{npcID=174341}},ends={{npcID=174327}},coords={x=0.648,y=0.196,source="quest_giver",zoneID=11510},questType="dungeon"},
[62459] = {id=62459,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",rewardGold=257400,rewardXP=8165,rewardItems={183725},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62461] = {id=62461,name="Stalking the Warrens",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="So, they are creating magical beasts deep within the Warrens. Their power is... substantial. Maw Walker, I must trust in you to handle this. While I can provide insight, in combat I must admit your prowess exceeds my own. Hunt the beasts that they train to hunt us. Show the Mawsworn that we too can bare fangs.",rewardGold=257400,rewardXP=8165,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group"},
[62462] = {id=62462,name="WANTED: The Key of Eyes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I seek a mercenary of unparalleled might to venture into the House of Eyes and procure the \" Key of Eyes \". Above average compensation is assured for the one who can both deliver the key and regale me with the story of its previous owner's demise. Be warned that the grounds once belonging to the House of Eyes are extremely dangerous and lone exploration is highly discouraged.",objectivesText="Eliminate Chelicera and obtain the Key of Eyes . Progress: So, you've seen my posting?",rewardGold=514800,rewardXP=10205,rewardItems={183728},starts={{npcID=358382}},ends={{npcID=169964}},coords={x=0.531,y=0.414,source="quest_giver",zoneID=11462},questType="group"},
[62465] = {id=62465,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",rewardItems={183791,183792},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62466] = {id=62466,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",objectivesText="Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62467] = {id=62467,name="Seed of a Thought",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="Within wildseeds, spirits slumber and grow. But so too can catalysts, when seeds take the place of spirits. Seed Merchant Daybreak trades in such seeds. She can supply you with the ones you seek. Choose one to plant within a wildseed. The forest holds its breath and awaits your choice.",objectivesText="Acquire a seed and plant it within a wildseed. Progress: Your talents as a cultivator continue to thrive.",rewardGold=128700,rewardXP=4085,starts={{npcID=166476}},ends={{npcID=166476}},coords={x=0.334,y=0.61,source="quest_giver",zoneID=13367},questType="standard"},
[62477] = {id=62477,name="Blueprint: Skystrider Glider",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this kit.>",objectivesText="Bring the Blueprint: Skystrider Glider to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62483] = {id=62483,name="Steward Mail Pouch",level=60,requiredLevel=60,faction="both",expansion=8,description="steward 's size. You are certain your steward will love it.>",objectivesText="Summon your steward companion via Summon steward , then give them the Steward Mail Pouch . Provided item:",questType="standard"},
[62486] = {id=62486,name="Blueprint: Empyrean Refreshment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with the crafting.>",objectivesText="Bring the Blueprint: Empyrean Refreshment to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62536] = {id=62536,name="The Lost of Teldrassil",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11400,mapID=1565,description="I learned that Sylvanas burned Teldrassil. I felt my heart break for the night elves. And that was only the beginning. We know now that the souls lost that day did not go to their intended rest. But you have the power to begin to correct that, Maw Walker. If you find yourself in the Maw, look for any of those lost. Please, bring them home.",objectivesText="Travel to the Maw and rescue Lost Souls.",rewardGold=257400,rewardXP=6815,starts={{npcID=160262},{npcID=171138}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[62539] = {id=62539,name="Stygian Incinerator",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Stygian Incinerator"},
[62544] = {id=62544,name="From a Dark Place",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11400,description="You rescued some of the night elves from the Maw before. While the danger is still great, I must ask you to do it again. I have to believe that we can save them. As many of them as possible. Please, go and see if you can recover any more lost souls.",objectivesText="Travel to the Maw and rescue Lost Souls.",rewardGold=257400,rewardXP=6815,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[62546] = {id=62546,name="No Wisp Left Behind",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11400,description="More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.",objectivesText="Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.",rewardGold=257400,rewardXP=6815,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[62549] = {id=62549,name="No Wisp Left Behind",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11400,description="More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.",objectivesText="Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.",rewardGold=257400,rewardXP=6815,starts={{npcID=160262}},ends={{npcID=160262}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[62554] = {id=62554,name="Sootible Hat: Red Noggin Candle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,objectivesText="Progress: One of them Noggin Candles would impress 'em all, right?",starts={{npcID=165302}},ends={{npcID=165302}},questType="standard"},
[62555] = {id=62555,name="A Touch of Humility",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="With the Temple of Humility under our control, its power shall flow back into the Crest of Ascension once more. Join me below so that we may witness it together. Mikanikos has ensured it will become even more magnificent as its power grows.",objectivesText="Witness the Crest of Ascension become empowered by the Temple of Humility.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[62556] = {id=62556,name="Sootible Hat: Pink Party Hat",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,objectivesText="Progress: A Pink Party Hat is stylish an' classy, innit?",starts={{npcID=165302}},ends={{npcID=165302}},questType="standard"},
[62557] = {id=62557,name="Our Realm Reclaimed",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Though Forsworn still fight across Bastion , the Temple of Loyalty is ours, and with it our realm. We will have to stay diligent to maintain control of all of the temples, and much remains to be decided with the fate of our fallen brethren, but today is a day of great victory. Join me at the Crest of Ascension, and witness its final empowerment.",objectivesText="Witness the Crest of Ascension become empowered by the Temple of Loyalty.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[62558] = {id=62558,name="Sootible Hat: Fae Revel Masque",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,objectivesText="Progress: I gots to get one o' them Fae Revel Masques . Gonna keep 'em guessin' and be mysterious an' all.",starts={{npcID=165302}},ends={{npcID=165302}},questType="standard"},
[62559] = {id=62559,name="Sootible Hat: Crown of the Righteous",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,objectivesText="Progress: I knows what I needs! Everybody gonna bow down when they sees me in a Crown of the Righteous .",starts={{npcID=165302}},ends={{npcID=165302}},questType="standard"},
[62560] = {id=62560,name="Growing in Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="Wonderful news, ! You have gathered enough Anima. The Queen is now able to empower the Heart of the Forest!",objectivesText="Witness the Winter Queen empower the Heart of the Forest. Progress: I am so excited!",rewardGold=25740,rewardXP=1020,starts={{npcID=161509}},ends={{npcID=161509}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[62561] = {id=62561,name="My Heart is Full",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="! Can you believe it? We have enough Anima that the Winter Queen can fully restore the Heart of the Forest! You've done so much for us!",objectivesText="Witness the Winter Queen empower the Heart of the Forest. Progress: I am so excited!",rewardGold=25740,rewardXP=1020,starts={{npcID=161509}},ends={{npcID=161509}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[62563] = {id=62563,name="Back Again!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Gorgantus just won't give up! We've defeated her several times already, but the scavengers salvage the body, fix her up and send her right back in here! She thinks this time she will defeat us... prove her wrong.",objectivesText="Defeat Gorgantus the Gutter",rewardGold=257400,rewardXP=8165,rewardItems={181501,181502,181503,181507,181625,181638,181645,181646,181647,181648,181649,181651,181652,181653,181654,181655,181660,181661,181662,181663,181664,181665,181666,181667,181668,181669,181670,181672,181675,181676,181677,181679,181680,181689,181695,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1885,amount=3}},starts={{npcID=160523}},ends={{npcID=160523}},coords={x=0.514,y=0.162,source="quest_giver",zoneID=11462},questType="standard"},
[62567] = {id=62567,name="Adventurers Wanted: Chromie's Call",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1637,mapID=84,description="Chromie is seeking veteran adventurers to embark on expeditions through time and space. This is your opportunity to experience the legendary adventures of the past--today! Speak with Chromie near the Stormwind Embassy for more information.",objectivesText="Speak with Chromie in Stormwind.",rewardGold=30900,rewardXP=175,starts={{npcID=167032}},ends={{npcID=167032}},questType="standard"},
[62568] = {id=62568,name="Adventurers Wanted: Chromie's Call",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1637,mapID=84,description="Chromie is seeking veteran adventurers to embark on expeditions through time and space. This is your opportunity to experience the legendary adventures of the past--today! Speak with Chromie near the Orgrimmar Embassy for more information.",objectivesText="Speak with Chromie in Orgrimmar .",rewardGold=30900,rewardXP=175,starts={{npcID=168431}},ends={{npcID=167032}},questType="standard"},
[62569] = {id=62569,name="The Jailer's Grasp",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=10565,mapID=1670,description="By peering into the Maw, Bolvar drew the Jailer's attention. His worst fears have come to pass. You must help me break the link, ! The fragment of the Helm is the key!",objectivesText="Help Jaina Proudmoore sever the Jailer's connection to Bolvar.",rewardItems={184315},starts={{npcID=170153}},ends={{npcID=170153}},questType="standard"},
[62587] = {id=62587,name="In Search of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I have always had dreams. Special dreams you could say. Any place of tranquility or calm can come to me in a dream. Even those that may have danger nearby, as calm can be found anywhere, if you know how. Now I dream of your world, your Azeroth. I cannot travel to your realm. Help me connect to my latest dream through your eyes. I have dreamed of a high place. A very high place. Do you know it?",objectivesText="Travel to Highmountain in search of calm",rewardGold=257400,rewardXP=8165,starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62588] = {id=62588,name="In Search of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="You return. This pleases me. More places of tranquility have come to me in dreams. I see a sandy beach, Sunsets. I cannot travel to your realm. Help me connect to my latest dream through your eyes.",objectivesText="Travel to Zuldazar to meditate.",rewardGold=257400,rewardXP=8165,starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62589] = {id=62589,name="In Search of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I am glad you wish to continue your meditations. It will help you be more centered. I have had another dream. A warm dream of a cold place. It is wrapped in white. Do you know of it? Venture there and experience the vista I saw in my dream.",objectivesText="Meditate in Winterspring",rewardGold=257400,rewardXP=8165,starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62590] = {id=62590,name="In Search of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="Thank you for returning. I have had another dream. Another vision of your realm. In this dream the sky danced above me. On the edge of a cliff, in a northern land. Such a sight to behold. You must experience it for yourself.",objectivesText="Meditate in Howling Fjord",rewardGold=257400,rewardXP=8165,starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62591] = {id=62591,name="In Search of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="We have already experienced so much together. I am grateful to have a companion on this voyage of discovery. You walk where I can only project. You touch that which I can only see. I have had another dream. Another coast. A statue. A large statue of a little one. Go, seek out the view from my dream.",objectivesText="Meditate in Booty Bay",rewardGold=257400,rewardXP=8165,starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62592] = {id=62592,name="Master of Inner Calm",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="You have come a long way. You are almost prepared to access your inner calm anywhere. Just one more journey under my guidance. It is a short one. Peace was here in this garden all along. One more location of calm to experience. Then you shall shed your spiritual shackles. I shall be proud.",objectivesText="Find the new meditation location within the Queen's Conservatory .",rewardGold=128700,rewardXP=4085,rewardItems={183856},starts={{npcID=174508}},ends={{npcID=174508}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62593] = {id=62593,name="Hunt: Death Elementals",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13476,mapID=1543,rewardGold=514800,rewardCurrencies={{id=1767,amount=10}},questType="dungeon"},
[62597] = {id=62597,name="Bonesmith Heirmir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Bonesmith Heirmir in Maldraxxus. What aid might she be able to offer the Ember Court?>",objectivesText="Deliver Alexandros Mograine's letter to Bonesmith Heirmir in Maldraxxus. Provided item:",rewardGold=64350,rewardXP=2040,rewardItems={183844},ends={{npcID=157676}},coords={mapID=1536,source="quest_giver",x=0.418667,y=0.698},questType="standard"},
[62598] = {id=62598,name="Forgelite Sophone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Forgelite Sophone in Bastion. What aid might she be able to offer the Ember Court?>",objectivesText="Deliver Polemarch Adrestes's letter to Forgelite Sophone in Bastion. Provided item:",rewardGold=64350,rewardXP=2040,rewardItems={183845},ends={{npcID=158807},{npcID=174719}},coords={mapID=1533,source="quest_giver",x=0.535,y=0.8325},questType="standard"},
[62599] = {id=62599,name="Gormsmith Cavina",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Gormsmith Cavina in Ardenweald. What aid might he be able to offer the Ember Court?>",objectivesText="Deliver Hunt-Captain Korayn's letter to Gormsmith Cavina in Ardenweald. Provided item:",rewardGold=64350,rewardXP=2040,ends={{npcID=165382}},coords={mapID=1565,source="quest_giver",x=0.515,y=0.34},questType="standard"},
[62600] = {id=62600,name="Finding Inner Peace",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="This is a lovely spot don't you think? I knew the myths of Ardenweald. Even glimpsed it in dream. Yet it swells with tranquility unimagined. Calm is what my kind live for. Even in chaos. You can always find calm. I can show you if you would like? I can sense a nearby convergence of calm. That will provide a suitable demonstration.",objectivesText="Travel out into Ardenweald to commune with the calm of the land.",rewardGold=128700,rewardXP=4085,starts={{npcID=174507}},ends={{npcID=174507}},coords={x=0.258,y=0.48,source="quest_giver",zoneID=13367},questType="standard"},
[62601] = {id=62601,name="Forgy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Forgy in Darkhaven. On the outside of the envelope are very specific orders to tell Forgy that Rendle sent you. What aid might Forgy be able to offer the Ember Court?>",objectivesText="Deliver Rendle's letter to Forgy in Darkhaven. Provided item:",rewardGold=64350,rewardXP=2040,ends={{npcID=161931}},coords={mapID=1525,source="quest_giver",x=0.632,y=0.625},questType="standard"},
[62603] = {id=62603,name="A Rare and Unusual Spirit",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="I'm glad to see you again, friend! We have found another inert spirit gripped by dark dreams. Nasty stuff! In this dream, a noble figure that once embodied loyalty has been consumed by their own doubts, leading them down a dark path. If you were to defeat the fallen paragon, I bet we'll be able to revive this poor spirit. Will you help us once more, ?",objectivesText="Defeat Devos in the Spires of Ascension.",rewardGold=128700,rewardXP=4085,rewardItems={183805},starts={{npcID=171107}},ends={{npcID=171107}},coords={x=0.416,y=0.522,source="quest_giver",zoneID=13367},questType="standard"},
[62605] = {id=62605,name="Broker Business",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="<A web covered box of assorted scholar supplies lays haphazardly on the ground. The make seems Broker in origin. Perhaps the owner is nearby.>",objectivesText="Find the owner of the forgotten supplies .",rewardGold=24570,rewardXP=175,starts={{npcID=358533}},ends={{npcID=166657}},coords={x=0.382,y=0.313,source="quest_giver",zoneID=11462},questType="standard"},
[62606] = {id=62606,name="A Blackthorn Blend",level=60,requiredLevel=60,faction="both",expansion=8,description="Ah, just the mushroomancer I wanted to see! Mind getting me some clay? There's all kinds of different soil, you know. It's not all just dirt! And clay... clay is something special. You ever try growing through clay? Oh, I guess not. It's hard work to break down, but once you do the flavor is incomparable! My roots are looking forward to the challenge. Blackthorn Grove has a particularly bitter and complex clay that is just what I'm craving. I'm sure they won't mind if you ask them for some.",objectivesText="Collect 6 Blackthorn Clay in Blackthorn Grove. Progress: If they give you any trouble, just tell 'em Marasmius sent you. I bet someone there is old enough to remember me.",rewardItems={183840},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62607] = {id=62607,name="Glittering Gritty Goodness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Well, hello there! Fancy helping me out today? You ever been to Shimmerbough? Ever wonder why it's called that? I was there when it was named, you know. Lots of people think it's the trees or the water, and they're right. But the secret to the shimmering is in the silt. The soil soaks and gains excess anima from the water, until the ground itself practically sparkles. I could really go for some shimmersilt right now. Would you let an old mushroom relive his youth?",objectivesText="Collect 6 Shimmersilt in Shimmerbough. Progress: Oooh, I always used to get tingly all over when I had shimmersilt . And that's a lot of tingling!",rewardGold=257400,rewardXP=8165,rewardItems={183836},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62608] = {id=62608,name="A Royal Treat",level=60,requiredLevel=60,faction="both",expansion=8,description="So nice to see you again. I've got a special request for you. The Winter Queen herself used to tend directly to groves, in the early times. Everything she touched burst with life and power. Even the ground she walked on. Over time, the Queen's Garden came to be known as the Garden of Night, for the Queen had not tended to her garden in so long. But the ground is still potent with her power. It's the finest meal I've ever had. I know this is indulgent, but you and I both know I deserve it!",objectivesText="Collect 6 Royal Peat in the Garden of Night. Progress: Sometimes you just need to treat yourself to something nice.",rewardItems={183837},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62609] = {id=62609,name="Necrolord Arsenal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Hmm. Mograine usually has more sense than this... An order's an order. I'll arrange for a shipment of raw materials and forging equipment to be delivered to your court. While you wait, Mograine asks that you clear out some of our enemies to help cover for my absence. It was in the letter. Shame it's all shredded up so you can't read it.",objectivesText="Complete World Quests in Maldraxxus.",rewardGold=257400,rewardXP=8165,rewardItems={177241},starts={{npcID=157676}},ends={{npcID=157676}},coords={x=0.362,y=0.708,source="quest_giver",zoneID=11462},questType="standard"},
[62610] = {id=62610,name="Hyphae Patrol: The Stalks",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="< Marasmius sighs.> They're at it again, up in the Stalks. Seems like we didn't give them enough of a thrashing the first time, eh? What say you and I team up again and teach those younglings a lesson they won't forget? Let me know when you're ready and we'll get 'em, just like before!",objectivesText="Ride the fae rings and slay 30 Masked Invaders in The Stalks. Progress: Let's go, before they do any more damage!",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62611] = {id=62611,name="Hyphae Patrol: Heartwood Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Those masked fiends have taken over Heartwood Grove, and I mean to stop their plans. Heartwood Grove was so beautiful before. And now, it's... No matter. We're going to fix this, you and me. Right now. Come, join me in battle. We'll give those monsters a thrashing that will make their masters think twice before desecrating that sacred place again!",objectivesText="Ride the fae rings and slay 30 Possessed Desecrators in Heartwood Grove. Progress: Hurry up. I won't stand to let them spend one moment more in that grove.",rewardGold=257400,rewardXP=8165,rewardItems={175713,175740,179500,179508,179517,179537,179547,179562,179584,179604,181407,181409,181410,181418,181422,181423,181424,181425,181430,181457,181458,181459,181477,181479,181506,181541,182480,182649,183167,183468,183469,183473,183486,183489,184381,184382,184383,184384,184587},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62612] = {id=62612,name="Venthyr Arsenal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Forgy reads the letter you hand him.> Ah, Rendle sent you. Should've said so. No problem. I'll get you everything you need to be bashing skulls at that court. Gonna need some help convincing my boss for the time off, though. Real stick in the muck, yeah? Say you take care of some of the troubles around here, tell everyone it's for me--that'll do it.",objectivesText="Complete World Quests in Revendreth.",rewardGold=257400,rewardXP=8165,rewardItems={177242},starts={{npcID=161931}},ends={{npcID=161931}},coords={x=0.632,y=0.626,source="quest_giver",zoneID=10413},questType="standard"},
[62613] = {id=62613,name="Kyrian Arsenal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Forgelite Sophone reads the letter you hand her.> I see. Wherever I may serve, I will go. Are you willing to do the same? Will you serve Bastion where it has need?",objectivesText="Complete World Quests in Bastion.",rewardGold=257400,rewardXP=8165,rewardItems={177243},starts={{npcID=158807},{npcID=174719}},ends={{npcID=158807},{npcID=174719}},coords={x=0.528,y=0.834,source="quest_giver",zoneID=10534},questType="standard"},
[62614] = {id=62614,name="Hyphae Patrol: Eventide Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="I hope you're ready to fight. The Drust are bolstering their forces in Eventide Grove. Most of Ardenweald doesn't remember them, but I do. You have to completely root them out to be rid of their presence, or they'll grow right back, tougher than ever. Come with me. We're going to exterminate every last one of them. Let me know when you're ready.",objectivesText="Ride the fae rings and slay 30 Possessed Invaders in Eventide Grove. Progress: Quickly, before they spread any further into Ardenweald . Now's our chance.",starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62615] = {id=62615,name="Hyphae Patrol: Gossamer Cliffs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="Bad news from the Gossamer Cliffs. We need to help. The varmints terrorizing the poor silk striders have become more cruel and aggressive lately. The silk striders are important to Ardenweald ; more important than almost anyone else knows. We can't lose any more. Let me know when you're ready to go and we'll scare those gits away for good!",objectivesText="Ride the fae rings and slay 30 Blackthorn Assailants in the Gossamer Cliffs. Progress: Quickly! The striders are counting on us!",rewardGold=257400,rewardXP=8165,rewardItems={175713,179508,179513,179517,179532,179537,179547,179562,179584,181389,181403,181404,181405,181406,181417,181418,181426,181427,181428,181429,181458,181459,181477,181479,181508,181511,181541,181698,182441,182466,182478,182610,182621,183167,183464,183473,183479,183490,183491,183496,184381,184382,184383,184384},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=167455}},ends={{npcID=167455}},questType="standard"},
[62616] = {id=62616,name="Night Fae Arsenal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Gormsmith Cavina reads the letter you hand him.> I'm not surprised the Hunt-Captain sent you to me. I am the finest gormsmith in all of Ardenweald, afterall. Her orders are clear and I'm happy to help. We'll need you to take on some extra patrols to make up for the lost time and resources. Sound fair?",objectivesText="Complete World Quests in Ardenweald.",rewardGold=257400,rewardXP=8165,rewardItems={177244},starts={{npcID=165382}},ends={{npcID=165382}},coords={x=0.516,y=0.34,source="quest_giver",zoneID=11510},questType="standard"},
[62618] = {id=62618,name="Odalrik",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Odalrik"},
[62619] = {id=62619,name="A Meandering Story",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Archivist Dreyden would probably be pleased to have his book back.>",objectivesText="Bring the Meandering Story to Archivist Dreyden in the Grove of Memory. Provided item:",rewardGold=25740,rewardXP=1020,ends={{npcID=165867}},coords={mapID=1565,source="quest_giver",x=0.636,y=0.226},questType="standard"},
[62620] = {id=62620,name="A Wandering Tale",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Archivist Dreyden would probably be pleased to have his book back.>",objectivesText="Bring the Wandering Tale to Archivist Dreyden in the Grove of Memory. Provided item:",rewardGold=25740,rewardXP=1020,ends={{npcID=165867}},coords={mapID=1565,source="quest_giver",x=0.636,y=0.226},questType="standard"},
[62621] = {id=62621,name="An Escapist Novel",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Archivist Dreyden would probably be pleased to have his book back.>",objectivesText="Bring the Escapist Novel to Archivist Dreyden in the Grove of Memory. Provided item:",rewardGold=25740,rewardXP=1020,ends={{npcID=165867}},coords={mapID=1565,source="quest_giver",x=0.636,y=0.226},questType="standard"},
[62622] = {id=62622,name="A Travel Journal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ardenweald ! And self-written and published no less! Flipping towards the end you see yourself enter the picture as a villain, unjustly attacking the book and opening it. You read \"This book appears to be a travelogue of this book's personal journey around Ardenweald ! And Self-written and-\" You hurriedly close the book, feeling queasy. It should go back to Archivist Dreyden .>",objectivesText="Bring the Travel Journal to Archivist Dreyden in the Grove of Memory. Provided item:",rewardGold=25740,rewardXP=1020,ends={{npcID=165867}},coords={mapID=1565,source="quest_giver",x=0.636,y=0.226},questType="standard"},
[62623] = {id=62623,name="A Naughty Story",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Archivist Dreyden .>",objectivesText="Bring the Naughty Story to Archivist Dreyden in the Grove of Memory. Provided item:",rewardGold=25740,rewardXP=1020,ends={{npcID=165867}},coords={mapID=1565,source="quest_giver",x=0.636,y=0.226},questType="standard"},
[62624] = {id=62624,name="The Queen's Conservatory",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="I have heard that you are aiding us in restoring our sanctum, . There is a very special magical grove that we know as The Queen's Conservatory . Within this magical sanctuary we nurture the spirits of old deities back to life. But its magic has waned with the anima drought. It is in need of your help. It would mean the world to us if you could start the restoration process by acquiring the resources we need.",objectivesText="Speak to Zayhad to unlock the Queen's Conservatory . Progress: You can go and Speak to Zayhad in your Sanctum to unlock the Queen's Conservatory once you have collected sufficient resources.",rewardGold=257400,rewardXP=8165,starts={{npcID=173171}},ends={{npcID=173171}},questType="standard"},
[62625] = {id=62625,name="A Rare and Unusual Spirit",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,description="It's a joy to see the progress you've made in the restoration of the conservatory, ! But there's still more work to be done. We have found another inert spirit. A dark dream is preventing its awakening. In this dream, the spirit is caught in the midst of a feud between ancient beings. Both are a bit on the unsavory side, but one is much, much worse than the other! If you were to defeat the Father of Sleep, it should nudge the spirit from its slumber. Will you help?",objectivesText="Defeat Mueh'zala in De Other Side.",rewardGold=257400,rewardXP=10205,rewardItems={183806},starts={{npcID=171107}},ends={{npcID=171107}},coords={x=0.416,y=0.522,source="quest_giver",zoneID=13367},questType="standard"},
[62626] = {id=62626,name="Mullby's Marker",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The Marker looks like it might be important to this Mulby fellow. Returning it to him in Maldraxxus might net you a finder's fee.",objectivesText="Return the marker to the Challenger's Promenade in Maldraxxus.",rewardGold=823680,ends={{npcID=161710}},coords={mapID=1536,source="quest_giver",x=0.544667,y=0.494667},questType="standard"},
[62627] = {id=62627,name="All Spirits Great and Small",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=6720,description="This is a most curious place. So much energy of rebirth. A fusion of different forms of magic. Not what I expected. I too was committed to rebirth among my kind. This magic is both known to me, and like nothing I have seen before. Yet it all serves to balance. It is not just great spirits of import that help to maintain the cosmic balance. Even the smallest of creatures can play a role. I can show you if you like? Visit the remains of one such creature, and we shall rekindle its spirit.",objectivesText="Travel to Frostfire in search of the remains Progress: Return to me when you have found the remains that birthed the spirit animal.",rewardGold=257400,rewardXP=8165,starts={{npcID=174511}},ends={{npcID=174511}},coords={x=0.264,y=0.636,source="quest_giver",zoneID=13367},questType="standard"},
[62628] = {id=62628,name="Vole's Voucher",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Au'narim at the Challenger's Promenade outside the Theater of Pain in Maldraxxus he should dispense the funds to you from Grandmaster Vole's credit.>",objectivesText="Take the voucher to the Challenger's Promenade in Maldraxxus. Progress: You wish to make a transaction?",rewardGold=3088800,ends={{npcID=159830}},coords={mapID=1536,source="quest_giver",x=0.536,y=0.475},questType="standard"},
[62629] = {id=62629,name="All Spirits Great and Small",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=5841,description="The time has come for us to rekindle another animal spirit. This one was lost to fire and raiding in a distant land. Go. Commune with the creature's remains . Release its spirit so that it may return here.",objectivesText="Travel to Kun-Lai Summit in search of the remains",rewardGold=257400,rewardXP=8165,starts={{npcID=174511}},ends={{npcID=174511}},coords={x=0.264,y=0.636,source="quest_giver",zoneID=13367},questType="standard"},
[62630] = {id=62630,name="All Spirits Great and Small",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8567,description="The time has come for us to rekindle another animal spirit. While appearing normal to you, and to the great winged creature that ate it, this creature was in fact somewhat special among its kind. You should travel to its grisly resting place and commune with its spirit so that it may join us in the conservatory.",objectivesText="Travel to Tiragarde Sound in search of the remains",rewardGold=257400,rewardXP=8165,starts={{npcID=174511}},ends={{npcID=174511}},coords={x=0.264,y=0.636,source="quest_giver",zoneID=13367},questType="standard"},
[62642] = {id=62642,name="LFGDungeons - SL - Heroic Random - 1st",level=60,requiredLevel=60,faction="none",expansion=8,rewardGold=1544400,rewardXP=16330,questType="standard"},
[62644] = {id=62644,name="LFGDungeons - SL - Normal Random - 1st",level=50,requiredLevel=50,faction="none",expansion=8,rewardGold=1029600,rewardXP=13630,questType="standard"},
[62646] = {id=62646,name="LFGDungeons - SL - Raid Finder - 1st",level=60,requiredLevel=60,faction="none",expansion=8,rewardGold=2574000,questType="standard"},
[62653] = {id=62653,name="Stop the Inquisition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Lord Chamberlain's inquisitors still torment the poor souls trapped under their care. You must put a stop to their wicked deeds! Speak with Archivist Fane, whom you worked with before to defeat an inquisitor, to acquire the sinstone of another inquisitor in the halls. With their sinstone, you will be able to shatter that inquisitor's defenses and lead the charge to defeat them. Bring friends, $p. Many of the inquisitors are far too dangerous to approach alone.",objectivesText="Defeat any inquisitor in Halls of Atonement. Archivist Fane can provide Inquisitor Sinstones to help you in your hunt. Progress: Archivist Fane can help you acquire an inquisitor's sinstone.",rewardGold=257400,rewardXP=8165,starts={{npcID=167332}},ends={{npcID=173705}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="group"},
[62654] = {id=62654,name="Maw Walker",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,description="I believe now it is time for you to leave. You are a Maw Walker, one who can activate the waystone between the Maw and the lands beyond. While your friends may not hold the same title, there is a way to send them through the gate. Souls can be connected. In theory, if you let someone attune themselves to your soul while you activate the waystone, you both should be able to leave. Even fleeting connections may produce some result. Go with your other two guests and see if my hypothesis is correct.",objectivesText="Attune with Darion and Alexandros and assist them in leaving the Maw.",rewardGold=257400,rewardXP=1415,rewardItems={175511,175524,175525,175526},rewardChoices={175524,175526,175525,175511},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[62691] = {id=62691,name="A Calling in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot. If we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth. We get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot. It's a call to action, it is. And it's important that we get started right away. Get on out there and get your boots muddy!",rewardItems={181556},rewardCurrencies={{id=1191,amount=35},{id=1822,amount=1},{id=1822,amount=2}},questType="world",worldTaskTitle="A Calling in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62692] = {id=62692,name="A Calling in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion. Travel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more. Today, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.",rewardItems={181372},rewardCurrencies={{id=1191,amount=35}},starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="A Calling in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62693] = {id=62693,name="A Calling in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here. We call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom. Our trust is in you, our newest seedling.",rewardItems={181475},rewardCurrencies={{id=1191,amount=35},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Calling in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62694] = {id=62694,name="A Calling in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Today marks the beginning of our path to victory. Enemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war. Once we have secured our home front, we can direct our efforts outwards. Such is your calling. Failure is unacceptable.",rewardItems={181732},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Calling in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62695] = {id=62695,name="A Call to Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="An opportunity has arisen that will be perfect for you to display your... prowess... to the denizens of Revendreth. Speak with Rendle . That dredger is disturbingly effective when it comes to hatching schemes. He says he has a plan for you.",objectivesText="Speak with Rendle .",rewardGold=25740,rewardXP=1020,starts={{npcID=175772}},ends={{npcID=165302}},coords={x=0.546,y=0.268,source="quest_giver",zoneID=10986},questType="standard"},
[62697] = {id=62697,name="A Call to Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Laurel picks out a sad tune on her harp.> Our groves wilt and wither, and enemies wait at our gates! The forest calls out in sorrow, \"Please help us before it's too late!\" O , now answer our calling! Ardenweald is in need of your might! Envoy Blodwyn will give you a mission, to ride with the Wild Hunt tonight!",objectivesText="Speak with Blodwyn .",rewardGold=128700,rewardXP=4085,starts={{npcID=176096}},ends={{npcID=167195}},coords={x=0.34,y=0.37,source="quest_giver",zoneID=12858},questType="standard"},
[62698] = {id=62698,name="A Call to Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Elysian Hold requires anima to operate fully. We need as much as we can so it may serve our needs. Our temples are fraught with challenges. By heeding their call you will recover anima for use within the sanctum here. Speak with Hermestes first, who will guide you on the path of courage.",objectivesText="Speak with Hermestes .",rewardGold=25740,rewardXP=1020,starts={{npcID=176100}},ends={{npcID=160387}},coords={x=0.648,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[62700] = {id=62700,name="Ashes of the Tower",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10472,description="Your first step towards obtaining the power is to retrieve... something. Yes, I believe it's coming back to me.",objectivesText="Collect 1250 Soul Ash in Torghast. Progress: Have you recovered what is needed?",starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62704] = {id=62704,name="The Threads of Fate",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="It is my duty to observe the strands of fate. The wondrous possibilities that the Purpose lays before us. Fate flows around you, mortal. It shifts. It changes. But I have stilled its movements to offer you... a choice. You may journey through the Shadowlands in the same manner as those who came before you have done. Or you may choose a different path. One that lets you forge a bond with a covenant now, and move freely through the realms of Death to forge your own destiny. What say you, mortal?",objectivesText="Speak with Fatescribe Roh-Tahl and decide how you want to experience Shadowlands. Progress: Fate is not fickle. Should you accept its offer, there will be no turning back.",rewardGold=25740,rewardXP=850,starts={{npcID=174871}},ends={{npcID=174871}},questType="standard"},
[62705] = {id=62705,name="Scour the Temple",expansion=8,mapID=1533,rewardItems={181721},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defend the temple"},{orderIndex=5,type=0,amount=13,objectID=174875,text="Terrified Steward rescued"},{orderIndex=7,type=0,amount=7,objectID=157622,text="Vesper of Purity cleansed"},{orderIndex=8,type=0,amount=7,objectID=157625,text="Vesper of Harmony cleansed"},{orderIndex=10,type=0,amount=20,objectID=174876,text="Forsworn Axiom destroyed"}},worldTaskTitle="Scour the Temple"},
[62707] = {id=62707,name="The Elysian Fields",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in the crossroads called Hero's Rest. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Kalisthene at Hero's Rest in Bastion .",rewardGold=200,rewardXP=850,starts={{npcID=159478}},ends={{npcID=163427}},questType="standard"},
[62712] = {id=62712,name="War of Attrition",expansion=8,mapID=1536,rewardItems={181675,181676,181677,181678},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Wear down the enemy Forces"}},worldTaskTitle="War of Attrition"},
[62714] = {id=62714,name="A Gift for an Acolyte",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The materials you supplied were more than sufficient for my purposes. For that, you have my gratitude. I think I know how to make the best use of the excess. A dear friend of mine recently achieved the role of Acolyte in service to the Temple of Purity. You are new here, so I will spare you the details, but it is an honor to serve a temple before one reaches ascension. I want to celebrate her success with a gift. Will you take this parcel to Acolyte Amalthina ?",objectivesText="Deliver Klystere's Gift to Acolyte Amalthina in the Temple of Purity. Progress: Welcome to the Temple of Purity. How may I be of service?",rewardGold=23635,rewardXP=175,rewardItems={183966},starts={{npcID=160598}},ends={{npcID=174900}},coords={x=0.478,y=0.734,source="quest_giver",zoneID=10534},questType="standard"},
[62715] = {id=62715,name="More Than A Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You have no idea what you just delivered, do you? I will explain, but first... I wish to return the favor. Klystere and I frequent a resting place to the north of here, along the path to the Temple of Courage. We planted a flower for our enjoyment, as we spend so much of our free time there. Bring me this bloom, if you would be so kind. Then I will tell you about the significance of this gift.",objectivesText="Acquire 1 Cultivated Windblossom . Progress: Did you find the place I mentioned? And the flower?",rewardGold=289575,rewardXP=1060,rewardItems={183967},starts={{npcID=174900}},ends={{npcID=174900}},coords={x=0.538,y=0.738,source="quest_giver",zoneID=10534},questType="standard"},
[62716] = {id=62716,name="Re-Introductions",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Though you have chosen your path, the fate of the Shadowlands has yet to be determined. The power of the Banished One grows. It falls to you, and others of your kind, to thwart him. The Arbiter's Honored Voice, Tal-Inara , will aid you in choosing a covenant. Bolstering their strength offers our best chance at victory. Let the Purpose guide you, . Always.",objectivesText="Speak with Tal-Inara within the Enclave in Oribos .",rewardGold=25740,rewardXP=850,starts={{npcID=164173}},ends={{npcID=164173}},questType="standard"},
[62718] = {id=62718,name="Hero's Rest",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="In light of the new arrivals to Bastion , Kalisthene has enabled the anima gateways to Hero's Rest once more! Those wishing to partake of breathtaking views, unparalleled steward service, and all manner of training and repair facilities should venture to this most remarkable of locations at their earliest convenience. Simply follow the path north and bear to the right at the crossroads. Kalisthene will personally greet all new arrivals for this most joyous of occasions!",objectivesText="Speak to Kalisthene in Hero's Rest.",rewardGold=25740,rewardXP=175,starts={{npcID=362489}},ends={{npcID=163427},{npcID=165045}},coords={x=0.488,y=0.733,source="quest_giver",zoneID=10534},questType="standard"},
[62719] = {id=62719,name="The Final Pieces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,description="The final components you'll need to acquire are... vessels... rune vessels! Armor to hold the might that will be imbued. And... powers? No... missives? Yes! Missives will allow your item to enhance your own personal strengths. But they cannot be the same. No, the two must offer different benefits. All of these can be obtained from souls with the correct crafting knowledge. And lastly, more of my memories. Memories of the runes, of the powers... of myself.",objectivesText="Acquire a Runecarver Memory, an Armor Rune Vessel suitable to your class, and two different Missives. These items can be obtained through crafting, or can be found on the Auction House. Progress: Have you acquired the remaining items?",starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62720] = {id=62720,name="The Fallen Tree",expansion=8,mapID=1565,rewardItems={181403,181404,181405,181406,184015},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Tirna Noch reclaimed"}},worldTaskTitle="The Fallen Tree"},
[62721] = {id=62721,name="Deconstructing The Problem",expansion=8,mapID=1536,rewardItems={181679,181680,181681,181682,183987},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Construct House Operations Disrupted"}},worldTaskTitle="Deconstructing The Problem"},
[62723] = {id=62723,name="Bolstering Bastion",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12916,mapID=1533,description="You are no aspirant, but I welcome any aid that Oribos might bring us in these dire times. Please, aid our people in any way you can. With anima in low supply and the insidious Forsworn encroaching from all sides, there is no shortage of trials to overcome. Do this for us, and I will see to it myself that our almighty Archon hears of your deeds in service of the kyrian. Mark well my words, and follow the path.",rewardGold=4118400,rewardXP=13630,rewardItems={181627,181628,181629,181630,181631,181632,181633,181634,181635,181636,181637,181743},rewardChoices={181632},starts={{npcID=163427,x=0.51,y=0.468,zoneID=10534},{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=163427,x=0.51,y=0.468,zoneID=10534},{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.51,y=0.468,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Bolstering Bastion"},
[62729] = {id=62729,name="Return to Oribos",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1533,description="You have proven yourself a worthy ally of Bastion in your time here, . Though I wish you could remain here, there are other realms in the Shadowlands that require aid more. Return to Oribos when you are able and seek out Tal-Inara . She will help you decide where to best next focus your efforts. Archon watch over you.",objectivesText="Speak to Tal-Inara in Oribos.",rewardGold=25740,rewardXP=850,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=3}},starts={{npcID=163427},{npcID=168517}},ends={{npcID=163427}},coords={x=0.51,y=0.468,source="quest_giver",zoneID=10534},questType="standard"},
[62730] = {id=62730,name="Fruit of the Gods",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You like sweet fruit? Stewards grow juiciest Purian. It special fruit! You find it many places in Bastion . It used for many things. Eat for nourishment. Give to bells for blessings. Give to stewards for treasure. You find, I show you how!",objectivesText="Bring Elios 1 Ripe Purian fruit. Progress: You find sweet Purian?",rewardGold=289575,rewardXP=6125,starts={{npcID=170284}},ends={{npcID=170284}},coords={x=0.532,y=0.464,source="quest_giver",zoneID=10534},questType="standard"},
[62732] = {id=62732,name="Locus Focus",expansion=8,mapID=1533,rewardItems={181575,181587,181603,181612},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defend the Mnemonic Locus"},{orderIndex=6,type=0,amount=10,objectID=174935,text="Soul Mirror Repaired"}},worldTaskTitle="Locus Focus"},
[62733] = {id=62733,name="The Sweetest Tribute",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Purian good to eat, yes, but better to give. You find locked Silver Strongbox near steward statue. Give Ripe Purian fruit as tribute. Then get nice surprise! You try?",objectivesText="Place a Ripe Purian fruit in the steward statue Tribute Tray. Progress: You give Purian yet?",rewardGold=289575,rewardXP=6125,starts={{npcID=170284}},ends={{npcID=170284}},coords={x=0.532,y=0.464,source="quest_giver",zoneID=10534},questType="standard"},
[62735] = {id=62735,name="Hostile Recollection",expansion=8,mapID=1533,rewardItems={181703},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Repel the Forsworn threat"}},worldTaskTitle="Hostile Recollection"},
[62736] = {id=62736,name="Maldraxxi Eviction Notice",expansion=8,mapID=1533,rewardItems={181569,181577,181591,181605},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Repel the Maldraxxi threat"}},worldTaskTitle="Maldraxxi Eviction Notice"},
[62737] = {id=62737,name="Aspirant For a Day",expansion=8,mapID=1533,rewardItems={172518,181571,181580,181596,181608,184043},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Aid the aspirants"},{orderIndex=11,type=0,amount=13,objectID=174959,text="Lost Library Scrolls returned"}},worldTaskTitle="Aspirant For a Day"},
[62738] = {id=62738,name="A Fresh Blade",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other. Their armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus. Speak to Secutor Mevix at the Bleak Redoubt in Maldraxxus . His tactical skills will ensure you are sent where you are most needed. Pathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.",objectivesText="Speak to Secutor Mevix at the Bleak Redoubt in Maldraxxus .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=175008}},questType="standard"},
[62739] = {id=62739,name="Restoring Balance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm. Unfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle. Now foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. Lady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Lady Moonberry at the Heart of the Forest in Ardenweald .",rewardGold=1230,rewardXP=850,starts={{npcID=159478}},ends={{npcID=172431}},questType="standard"},
[62740] = {id=62740,name="Dark Aspirations",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth 's vast anima stores into the Maw. You must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Prince Renathal in the crypt beneath Darkhaven in Revendreth .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=175056}},questType="standard"},
[62741] = {id=62741,name="Choice of Action",expansion=8,mapID=1536,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="House of the Chosen attacked"}},worldTaskTitle="Choice of Action"},
[62742] = {id=62742,name="Avoid 'Em Like the Plague",expansion=8,mapID=1536,rewardItems={181638},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Aid House of Plagues survivors"}},worldTaskTitle="Avoid 'Em Like the Plague"},
[62743] = {id=62743,name="Decaying Situation",expansion=8,mapID=1536,rewardItems={181651,181664,181665,181666},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Glutharn's Decay Secured"}},worldTaskTitle="Decaying Situation"},
[62748] = {id=62748,name="Rallying Maldraxxus",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13228,mapID=1536,description="We need all the help we can get! It's taking all we have to hold our ground against the other houses, let alone gain any ground against them. Truth be told, your blade will be welcome anywhere. There are no shortage of battles to be won, foes to be toppled, or weary soldiers to be relieved. Help us regain control of Maldraxxus , and in the name of the Primus I will see you are amply rewarded.",rewardGold=4118400,rewardXP=13630,rewardItems={181648,181684,181685,181686,181687,181688,181689,181690,181691,181692,181693,181694,181695,181696,181697},rewardChoices={181687,181692},starts={{npcID=175008,x=0.528,y=0.682,zoneID=11462}},ends={{npcID=175008,x=0.528,y=0.682,zoneID=11462}},coords={x=0.528,y=0.682,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Rallying Maldraxxus"},
[62761] = {id=62761,name="Return to Oribos",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1536,description="I wouldn't be a tactician if I didn't recognize when the mission is complete. Much remains to be done before Maldraxxus can stand tall once again, but that day will come thanks to your efforts. There are other realms in need of your skills more than us. You should return to Oribos and see to it that they receive it.",objectivesText="Speak to Tal-Inara in Oribos.",rewardGold=25740,rewardXP=850,rewardCurrencies={{id=1822,amount=3}},starts={{npcID=175008}},ends={{npcID=175008}},coords={x=0.528,y=0.682,source="quest_giver",zoneID=11462},questType="standard"},
[62763] = {id=62763,name="Support the Court",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13334,mapID=1565,description="Groves are under attack everywhere! There simply aren't enough of us to protect them all! You just might be our only hope. We must restore order, or more precious souls will be lost to us. Please, help anyone you can, anywhere you can. My heart cannot bear to see any more pain! I'll make sure the Winter Queen hears of your deeds, don't you worry!",rewardGold=4118400,rewardXP=13630,rewardItems={179500,179508,179513,179517,179532,179537,179547,179562,179584,179604,181432,181433,184379},rewardChoices={179584},starts={{npcID=172431,x=0.492,y=0.522,zoneID=11510},{npcID=172431,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858}},ends={{npcID=172431,x=0.492,y=0.522,zoneID=11510},{npcID=161509,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858},{npcID=161509,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Support the Court"},
[62773] = {id=62773,name="Dreamshrine Basin",expansion=8,mapID=1565,rewardItems={175713},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Hibernal Hollow defended"}},worldTaskTitle="Dreamshrine Basin"},
[62774] = {id=62774,name="Tranquil Pools",expansion=8,mapID=1565,rewardItems={172948,179921,181418,181419,181420,181421},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Tranquil Pools aided"}},worldTaskTitle="Tranquil Pools"},
[62775] = {id=62775,name="The Waning Grove",expansion=8,mapID=1565,rewardItems={181414,181415,181416,181417,184101},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Heartwood Grove preserved"}},worldTaskTitle="The Waning Grove"},
[62776] = {id=62776,name="Return to Oribos",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1565,description="I wish you could stay and relax here, maybe enjoy a play at the Star Lake Amphitheater, but there's simply no time! There are other realms out there that need your help, too. You will always be a friend of the Court, but I'm afraid you must return to Oribos. The Shadowlands needs you!",objectivesText="Speak to Tal-Inara in Oribos.",rewardGold=25740,rewardXP=850,rewardCurrencies={{id=1822,amount=3}},starts={{npcID=172431}},ends={{npcID=172431}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="standard"},
[62778] = {id=62778,name="Reinforcing Revendreth",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12831,mapID=1525,description="Denathrius must be stopped at all costs. However, we've no hope of taking him out while his forces still control much of Revendreth . If you are here to aid us, then there is no shortage of work to be done. Disposing of my father's many allies being chief among that work, of course, but any aid you can provide will be of use. There is too much at stake for all the Shadowlands if we fail. I will see to it that you are handsomely rewarded for your efforts.",rewardGold=4118400,rewardXP=13630,rewardItems={181207,181208,181209,181210,181211,181212,181213,181214,181215,181216,181219,181220,181221,181222,181223,181224,181244,181549},rewardChoices={181208,181211,181224},starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986},{npcID=175056,x=0.614,y=0.604,zoneID=10413}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986},{npcID=175056,x=0.614,y=0.604,zoneID=10413}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Reinforcing Revendreth"},
[62779] = {id=62779,name="Return to Oribos",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1525,description="I truly wish you could remain here and aid our cause--it is truly the most pressing manner in all the Shadowlands--but Revendreth alone cannot stand against the growing darkness. You must return to Oribos and ensure the other realms do not falter in their commitments. Tal-Inara will be able to guide you appropriately. Thank you once again for your aid, mortal. May our paths cross again.",objectivesText="Speak to Tal-Inara in Oribos.",rewardGold=25740,rewardXP=850,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=158653},{npcID=175056}},ends={{npcID=175056}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[62780] = {id=62780,name="Parasites of Reality",expansion=8,mapID=1525,rewardItems={181176,181183,181194,181199},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Endmire horrors eliminated"}},worldTaskTitle="Parasites of Reality"},
[62781] = {id=62781,name="Ash You Like It",expansion=8,mapID=1525,rewardItems={181334},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Desiccation decimated"}},worldTaskTitle="Ash You Like It"},
[62782] = {id=62782,name="The Banewood",expansion=8,mapID=1525,rewardItems={181184,181193,181196,181206},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Hunting grounds cleared"}},worldTaskTitle="The Banewood"},
[62783] = {id=62783,name="Stalking Fear",expansion=8,mapID=1525,rewardItems={181180,181187,181195,181203},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Dredhollow threats eliminated"}},worldTaskTitle="Stalking Fear"},
[62784] = {id=62784,name="Charlatans of Ceremony",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardGold=1029600,rewardXP=13630,rewardItems={181179,181185,181189,181200},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Depravity purged"}},worldTaskTitle="Charlatans of Ceremony"},
[62785] = {id=62785,name="I Could Be A Contender",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Hold up there, . If you are serious about fighting in the Arena you're going to need a manager. Lucky for you, , I know a guy. He's just had some openings in his roster of fighters and you look like just the type of he needs to fill his ranks. Name is Louison , you can find him at the gate just east of here. Tell him I sent ya, .",objectivesText="Speak with Louison .",rewardGold=24335,rewardXP=175,starts={{npcID=161733}},ends={{npcID=161559}},coords={x=0.504,y=0.516,source="quest_giver",zoneID=11462},questType="standard"},
[62789] = {id=62789,name="Of Great Renown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="As you aid our sacred covenant across the Shadowlands, your connection to it shall grow ever stronger. Your Renown will afford you many benefits over time. Seek out Iona Skyblade at the front of the hold, near the Crest of Ascension. She will show you the glory of the path.",objectivesText="Speak with Iona Skyblade .",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=176100}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[62790] = {id=62790,name="The Path Provides",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="All who follow the path are granted precious gifts by virtue of their connection with our covenant. The strength of that bond, known as Renown, is reflected in the shining spires of Elysian Hold itself. Though you have yet to gain Renown, you will as you aid us across the Shadowlands. When you are ready, I will show you all that the path can provide.",objectivesText="Examine your Renown with the Kyrian Covenant. Progress: Some say it is the Archon herself who grants our covenant its strength.",rewardGold=128700,rewardXP=4085,starts={{npcID=176100}},ends={{npcID=176100}},coords={x=0.648,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[62791] = {id=62791,name="Our Most Precious Resource",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You have fulfilled your calling, Maw Walker, and brought peace to our realm. Stay vigilant, for others will similarly call upon you in time. The anima you have so dutifully recovered will be of great use in the hold. Bring it to Haephus at once. He will ensure it is kept safe until it is needed. Go in service.",objectivesText="Speak to Haephus .",rewardGold=25740,rewardXP=1020,starts={{npcID=160387}},ends={{npcID=167745}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="standard"},
[62792] = {id=62792,name="Into the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="As the flow of anima withered within Bastion, our mighty Archon entrusted me with guarding our stores until they are needed. You may deposit any anima you recover into the reservoir here. By my life, and by the glory of the Archon, I will ensure they are kept safe.",objectivesText="Deposit Anima into your sanctum's Reservoir. Progress: Anima is best kept here, safe from our enemies who would take it from us.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=167745}},ends={{npcID=167745}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[62793] = {id=62793,name="It's All Coming Together",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Our brothers and sisters are spread thin fighting the Forsworn, maintaining order among aspirants waiting to ascend, and countless other duties. The willing souls you recovered from the Maw will be a great boon to our capabilities in these dire times. Go to Haephus at once--he has long been searching for aid in activating some of our sanctum's most powerful features. It is time we saw Elysian Hold brought to its full potential.",objectivesText="Speak to Haephus .",rewardGold=25740,rewardXP=1020,rewardChoices={174292,177053,178156,179942},starts={{npcID=160037}},ends={{npcID=167745}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[62794] = {id=62794,name="Enhancing the Hold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="As thanks for your efforts in recovering the anima and souls we now have available, you may decide which of Elysian Hold's features we upgrade first. Once active, it shall expand our capabilities to help not only Bastion, but all the Shadowlands. Do not worry--as you continue to recover anima and willing souls we will activate them all in time. For now, a single upgrade must suffice.",objectivesText="Start a Sanctum Upgrade. Progress: Take your time. The first step on the path is always the most difficult.",rewardGold=128700,rewardXP=4085,rewardItems={174292,177053,178156,179942},rewardChoices={178156,177053,179942,174292},starts={{npcID=167745}},ends={{npcID=167745}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[62795] = {id=62795,name="A Conduit for Good",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="While the gifts your bond shall bring you are substantial, you may also empower yourself further through the use of conduits. Conduits act to channel the energy of your soulbind into your form more directly, increasing your potential in a myriad of ways. Use the ones I have given you as a test of this power, but fear not--you will find others as you aid the Shadowlands.",objectivesText="Add the Conduits to the Forge of Bonds, then apply one to a slot on Pelagos. Progress: This is a crucial step in the path.",rewardGold=128700,rewardXP=4085,starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[62796] = {id=62796,name="Return to Adrestes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued to Elysian Hold. The kyrian are vital to the Shadowlands. If Bastion remains in turmoil, then all might soon be lost.",objectivesText="Report to Polemarch Adrestes at Elysian Hold in Bastion.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=2}},starts={{npcID=164079}},ends={{npcID=160037}},questType="standard"},
[62797] = {id=62797,name="The Vessels of Metal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="You have the bearing of one familiar with the art of smithing. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.",objectivesText="Bring the memory back to Smith Au'berk in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62798] = {id=62798,name="The Vessels of Leather and Bone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="You have the bearing of one familiar with the art of leatherworking. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.",objectivesText="Bring the memory back to Tanner Au'qil in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62799] = {id=62799,name="The Vessels of the Thread",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="You have the bearing of one familiar with the art of thread work. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.",objectivesText="Bring the memory back to Stitcher Au'phes in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62800] = {id=62800,name="The Vessels of Jewels",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="You have the bearing of a lapidary. Though familiar with the art of jewelcraft, perhaps there is yet more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.",objectivesText="Bring the memory back to Appraiser Au'vesk in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=164937}},ends={{npcID=164937}},questType="standard"},
[62801] = {id=62801,name="The Call of Fate",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us. Fate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice. Return to Oribos , , that I might help guide your path. The Purpose is our way.",objectivesText="Meet Fatescribe Roh-Tahl in Oribos .",rewardGold=25740,rewardXP=850,questType="standard"},
[62804] = {id=62804,name="Filling the Tanks",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more. Slaying the correct combination of slimes should provide all the fluid necessary.>",objectivesText="Slay the variety of slimes to fill the tanks with fluid.",rewardGold=257400,rewardXP=8165,rewardItems={184156},ends={{npcID=157945}},coords={mapID=1536,source="quest_giver",x=0.59,y=0.738},questType="standard"},
[62807] = {id=62807,name="Forest Refugees",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Some of those displaced by the fallen groves have made a home for themselves at the base of the Heart of the Forest. Hibernal Hollow is fortunate. We have supplies, when they may not. If you would, bring these to Flwngyrr . They care for the refugees there.",objectivesText="Bring Hibernal Hollow supplies to Flwngyrr in the Heart of the Forest. Provided item:",rewardGold=25740,rewardXP=175,rewardItems={184157},starts={{npcID=160894}},ends={{npcID=168032}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="standard"},
[62832] = {id=62832,name="Friends in Dark Places",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Even with all your aid, our sanctum will grow weaker without souls willing to help us. Many souls that may have been destined for Bastion are trapped within the Maw. If you can find a way to free them, they will help us restore Elysian Hold's power. Seek out what aid you can and do what we cannot, Maw Walker. Our very future may depend on it.",objectivesText="Find Ve'nari in the Maw.",rewardGold=25740,rewardXP=1020,starts={{npcID=160212}},ends={{npcID=162804}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[62833] = {id=62833,name="A Hero of Great Renown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="As you gain renown across the Shadowlands, you will draw others to our cause. Some may provide resources; some may offer direct support. Elspeth Larink will be responsible for putting their contributions to use. Speak with her to learn more.",objectivesText="Speak with Elspeth Larink .",rewardGold=25740,rewardXP=1020,starts={{npcID=165182}},ends={{npcID=175998}},coords={x=0.496,y=0.432,source="quest_giver",zoneID=12876},questType="standard"},
[62834] = {id=62834,name="Glorious Ambition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The renown you earn through your deeds can and will greatly benefit our covenant. Our ambition is not confined within the borders of Maldraxxus, after all. Allow me to demonstrate what we achieve as you gain renown.",objectivesText="Examine your Renown with the Necrolord Covenant. Progress: Talent is nothing without ambition.",rewardGold=128700,rewardXP=4085,starts={{npcID=175998}},ends={{npcID=175998}},coords={x=0.468,y=0.402,source="quest_giver",zoneID=12876},questType="standard"},
[62835] = {id=62835,name="A Call to Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We may hold the Seat of the Primus, but it will do us no good without the anima to power it. As you fight beside our troops on the battlefield, seek out opportunities to recover anima to support the war effort. Speak with Sergeant Romark . He can offer you additional guidance.",objectivesText="Speak with Sergeant Romark .",rewardGold=25740,rewardXP=1020,starts={{npcID=175998}},ends={{npcID=158339}},coords={x=0.468,y=0.402,source="quest_giver",zoneID=12876},questType="standard"},
[62836] = {id=62836,name="Signs of the Lion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Thanks to your efforts, Thrall, Jaina Proudmoore, and Baine Bloodhoof are safe. Yet so long as the Jailer holds any hero of Azeroth, I fear he has power over us all. It seems Anduin has been taken deeper into the tower than the others. Before I risk peering inside, you must make one last attempt to find him. You say the Jailer spoke of honing a weapon. I fear we are running out of time. Do not relent, . Search the twisting corridors of Torghast for any sign of the Young Lion.",objectivesText="Enter Torghast and explore the Twisting Corridors for any sign of Anduin Wrynn. Progress: Did you find any sign of Anduin?",rewardGold=1029600,rewardXP=16330,rewardItems={184276,184277,184278},rewardCurrencies={{id=1828,amount=50}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62837] = {id=62837,name="Hopeful News",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1543,description="The terms of our bargain have been met. You may depart with the souls you acquired. Perhaps the fate of this \"Baine\" is of interest to you or your allies. I suggest you return to Oribos and consult them. No need to rush. After all, those held within Torghast are tortured for centuries. Kindly remember not to tell anyone about our arrangement. Discretion is key between business partners, after all.",objectivesText="Speak with Bolvar Fordragon in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[62839] = {id=62839,name="Anima is Strength",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="You are victorious, Maw Walker. And with your success, our forces grow stronger. Stay alert. Your strength will be called upon again soon enough. Bring the anima you recovered to Akradia Moa at once. She will ensure its proper storage.",objectivesText="Speak to Arkadia Moa",rewardGold=25740,rewardXP=1020,starts={{npcID=158339}},ends={{npcID=161909}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="standard"},
[62840] = {id=62840,name="Into the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="With anima in short supply, Baroness Draka has tasked me with carefully managing our reserves as they are needed. You may deposit any anima you recover into the reservoir here. Be assured that the Necrolords will defend it at all costs.",objectivesText="Deposit Anima into your sanctum's Reservoir.",rewardGold=128700,rewardXP=4085,starts={{npcID=161909}},ends={{npcID=161909}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[62843] = {id=62843,name="The Soul Contact",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Your reputation precedes you, Maw Walker... braving the Maw and bringing Baron Mograine back in one piece... That was most impressive! With our dire shortage of souls, we'll need you to do that again. Bring us more willing souls so we can restore this sanctum's power! Seek out the broker who aided you before and ask if she will do so again. You may need her.",objectivesText="Speak to Ve'nari in the Maw.",rewardGold=25740,rewardXP=1020,starts={{npcID=167748}},ends={{npcID=162804}},coords={x=0.47,y=0.42,source="quest_giver",zoneID=12876},questType="standard"},
[62844] = {id=62844,name="Return to Draka",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will do what I can to prepare one. In the meantime, you received a summons from Baroness Draka asking that you return to the Seat of the Primus. The Necrolords are the key to saving the Shadowlands, . I suggest you return to them as soon as you are able.",objectivesText="Report to Baroness Draka at the Seat of the Primus in Maldraxxus.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164079}},ends={{npcID=161907}},questType="standard"},
[62845] = {id=62845,name="Bringing It All Together",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="With all of the houses against us, our forces are hard pressed to hold the line. The souls you rescued from the Maw will help strengthen our position and bolster our defenses. Bring them to Arkadia Moa . She will know how best to put them to use and empower our sanctum.",objectivesText="Speak to Arkadia Moa .",rewardGold=25740,rewardXP=1020,rewardItems={182254,182263,182272,182281},rewardChoices={182272,182263,182281,182254},starts={{npcID=161907}},ends={{npcID=161909}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[62846] = {id=62846,name="Sanctum Improvements",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Your will to succeed is strong, Maw Walker. With the anima and the souls you have recovered, we can now begin to unlock our sanctum's true potential. As we acquire more souls and more anima, we can gain even greater power from the Seat of the Primus. Remain relentless in your pursuit, and victory will be ours.",objectivesText="Start a Sanctum Upgrade. Progress: This is only the beginning.",rewardGold=128700,rewardXP=4085,starts={{npcID=161909}},ends={{npcID=161909}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[62848] = {id=62848,name="Conduits, What Are They For?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="While the benefits of soulbinding are substantial, you may strengthen them further through the use of conduits. Conduits act to channel the anima of our bond in a myriad of ways, vastly increasing both of our potential. Let us test out the ones I have given you. Fear not--many others like it can be found throughout the Shadowlands.",objectivesText="Add the Conduits to the Forge of Bonds, then apply one to a slot on Plague Deviser Marleth. Progress: This is an important lesson, my apprentice.",rewardGold=128700,rewardXP=4085,starts={{npcID=161904}},ends={{npcID=161904}},coords={x=0.39,y=0.328,source="quest_giver",zoneID=12876},questType="standard"},
[62849] = {id=62849,name="Paragon of the Court of Harvesters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Maw Walker. Your efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius. If you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. With treasure, of course.",objectivesText="Speak with Mistress Mihaela in Darkhaven.",starts={{npcID=156822}},ends={{npcID=156822}},questType="standard"},
[62850] = {id=62850,name="Paragon of the Ascended",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Maw Walker. Your efforts have provided the Ascended with a decisive edge in their goals. We have rewards for you, and thanks.",objectivesText="Speak with Adjutant Nikos in Hero's Rest in Bastion .",starts={{npcID=160470}},ends={{npcID=160470}},questType="standard"},
[62851] = {id=62851,name="Paragon of the Undying Army",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. I have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.",objectivesText="Speak with Nalcorn Talsen at the Theater of Pain.",starts={{npcID=173003}},ends={{npcID=173003}},questType="standard"},
[62852] = {id=62852,name="Paragon of the Wild Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Well met, ! You have proven yourself to all of Ardenweald. We would grant you further rewards, for your valor and cunning on our behalf. Meet with me at the Heart of the Forest.",objectivesText="Speak with Aithlyn at the Heart of the Forest.",starts={{npcID=158556}},ends={{npcID=158556}},questType="standard"},
[62855] = {id=62855,name="Edict of the Eternal Ones",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia. Return to the place of your passing, and you shall find what you left behind.",objectivesText="Recover your Dropped Stygia from your corpse.",rewardGold=128700,questType="standard"},
[62856] = {id=62856,name="Building Your Renown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="As you aid the court in your travels across the Shadowlands, your connection to us shall grow ever stronger. In time, you will be able to reap the benefits of your growing Renown. One of my most trusted and loyal followers, Rahel , has been watching you for some time. She can report as to your standing and the Renown you have garnered with my people. Speak to her and she might explain better how this Renown might be best put to work.",objectivesText="Speak with Rahel .",rewardGold=25740,rewardXP=1020,starts={{npcID=171934}},ends={{npcID=171934}},questType="standard"},
[62857] = {id=62857,name="The Court's Bounty",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Venthyr are drawn to new things, so we are going to make you the figurehead of our Sanctum. As your Renown throughout the Shadowlands grows, we will grow with you, accumulating power and influence we otherwise would not have access to. It will fall to me to track your Renown and quantify it as a resource. A true currency of Courts, if you will. Observe.",objectivesText="Examine your Renown with Sinfall. Progress: With enough anima, anything is possible.",rewardGold=25740,rewardXP=1020,starts={{npcID=175772}},ends={{npcID=175772}},coords={x=0.546,y=0.268,source="quest_giver",zoneID=10986},questType="standard"},
[62858] = {id=62858,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1565,description="Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible! The Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=10},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158553}},ends={{npcID=158553}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62859] = {id=62859,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1565,description="Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible! The Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=514800,rewardItems={184379},rewardCurrencies={{id=1810,amount=15},{id=1822,amount=1}},starts={{npcID=158553}},ends={{npcID=158553}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62860] = {id=62860,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1701,description="Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible! The Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw. Progress: Were you able to save anyone?",rewardGold=514800,rewardItems={177698,177699,177700,178874,178877,178878,178879,178880,178881,178882,178883,178884},rewardCurrencies={{id=1810,amount=20}},starts={{npcID=158553}},ends={{npcID=158553}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62861] = {id=62861,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands. The Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right. Return to the Maw and save all that you can.",objectivesText="Rescue 10 Souls from the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=10},{id=1822,amount=1}},starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[62862] = {id=62862,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands. The Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right. Return to the Maw and save all that you can.",objectivesText="Rescue 15 Souls from the Maw.",rewardGold=514800,rewardCurrencies={{id=1810,amount=15},{id=1822,amount=1}},starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[62863] = {id=62863,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1533,description="Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands. The Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right. Return to the Maw and save all that you can.",objectivesText="Rescue 20 Souls from the Maw. Progress: There is no fate worse than the Maw.",rewardGold=514800,rewardItems={181743,184763,184764},rewardCurrencies={{id=1810,amount=20},{id=1822,amount=1}},starts={{npcID=160212}},ends={{npcID=160212}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="standard"},
[62864] = {id=62864,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. We must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords. I shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=10},{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=167748}},ends={{npcID=167748}},coords={x=0.47,y=0.42,source="quest_giver",zoneID=12876},questType="standard"},
[62865] = {id=62865,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="Maw Walker, I'm sure you've seen first hand the souls that continue to pour into the Maw. We must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords. I shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=15},{id=1822,amount=1}},starts={{npcID=167748}},ends={{npcID=167748}},coords={x=0.47,y=0.42,source="quest_giver",zoneID=12876},questType="standard"},
[62866] = {id=62866,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. We must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords. I shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus. Return to the Maw and rescue those that you can.",objectivesText="Rescue Souls in the Maw. Progress: There is no fate worse than the Maw.",rewardGold=514800,rewardItems={181646,181648,181650},rewardCurrencies={{id=1810,amount=20},{id=1822,amount=1}},starts={{npcID=167748}},ends={{npcID=167748}},coords={x=0.47,y=0.42,source="quest_giver",zoneID=12876},questType="standard"},
[62867] = {id=62867,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1525,description="Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.",objectivesText="Rescue Souls in the Maw.",rewardGold=107000,rewardCurrencies={{id=1810,amount=10},{id=1822,amount=1}},starts={{npcID=164738}},ends={{npcID=164738}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[62868] = {id=62868,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1525,description="Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.",objectivesText="Rescue Souls in the Maw.",rewardGold=514800,rewardCurrencies={{id=1810,amount=15},{id=1822,amount=1}},starts={{npcID=164738}},ends={{npcID=164738}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[62869] = {id=62869,name="Return Lost Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1525,description="Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.",objectivesText="Rescue Souls in the Maw.",rewardGold=514800,rewardItems={181549,181552,184149},rewardCurrencies={{id=1810,amount=20},{id=1822,amount=1}},starts={{npcID=164738}},ends={{npcID=164738}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[62870] = {id=62870,name="Souls for Sinfall",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued back to Sinfall. Denathrius's machinations have left the venthyr poorly provisioned, and Prince Renathal will require all the souls he can muster.",objectivesText="Return the souls rescued from the Maw to Tenaval in Sinfall within Revendreth.",rewardGold=25740,rewardXP=1020,rewardItems={180202,180909,180910,180911,180912},rewardCurrencies={{id=1810,amount=5}},starts={{npcID=164079}},ends={{npcID=164738}},questType="standard"},
[62882] = {id=62882,name="Setting the Ground Rules",level=55,requiredLevel=55,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Back to rescue more souls? How intrepid. Though I must say, your earlier escapade has drawn the Jailer's attention... and his ire. After all, none have successfully eluded him before. Except for me. Now his forces are on high alert, hunting down any errant souls that the fabled Maw Walker may try to steal from him. It has made things quite... inconvenient for me. If you and I are going to work together, we need to set a few ground rules. And you must be properly equipped.",objectivesText="Set the ground rules about working together with Ve'nari . Progress: Let us discuss the terms of our arrangement.",rewardXP=3745,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[62883] = {id=62883,name="Keeper of Great Renown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. Seek out Laurel , our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.",objectivesText="Seek out Laurel the Heart of the Forest.",rewardGold=25740,rewardXP=1020,starts={{npcID=156634}},ends={{npcID=176096}},coords={x=0.454,y=0.656,source="quest_giver",zoneID=11510},questType="standard"},
[62884] = {id=62884,name="The Forest Will Sing Your Name",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Laurel picks out an intricate melody on deft fingers, and sings.> The keeper of word and deed, am I, the weaver of song and lore. Boons are granted as you grow in Renown, fulfilling the oaths we swore. Each deed that you do is a seed of strength, which will blossom in fabulous power. Speak with me now and see what awaits, our magic is yours to discover!",objectivesText="Examine your Renown with the Night Fae Covenant. Progress: I cannot wait to compose a song for you!",rewardGold=128700,rewardXP=4085,starts={{npcID=176096}},ends={{npcID=176096}},coords={x=0.34,y=0.37,source="quest_giver",zoneID=12858},questType="standard"},
[62886] = {id=62886,name="A Call to Service",level=60,requiredLevel=60,faction="none",expansion=8,description="The Heart of the Forest requires anima to be renewed and to grow. The Wild Hunt will need your help to recover what we need. Together we strand strong. Speak with Blodwyn. She has been guiding assistance to where it is most needed.",objectivesText="Speak with Blodwyn.",rewardGold=25740,rewardXP=1020,questType="standard"},
[62890] = {id=62890,name="Who Shapes the Forest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1702,description="You have fulfilled your calling, Maw Walker, and brought calm to our forest. Stay vigilant, for others will similarly call upon you in time. The anima you have recovered will be of great use to the Heart of the Forest. Bring it to Zayhad. They will ensure it is safe until it is needed. You will find them deep in the roots of the Heart of the Forest.",objectivesText="Find Zayhad in the Roots of the Heart of the Forest.",rewardGold=25740,rewardXP=1020,starts={{npcID=167195}},ends={{npcID=165702}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="standard"},
[62891] = {id=62891,name="Into the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1702,description="Groves wither, and our Queen weeps on barren soil. Anima, precious as water, now rare as snow. Our Queen gives of her own, shelters all beneath her boughs... but one tree does not a forest make. Your gift will be treasured and protected. Anima nourishes our roots, as hope nourishes our hearts. Ardenweald may yet flourish once more.",objectivesText="Deposit Anima into your sanctum's Reservoir. Progress: None to waste, and none shall be wasted. It will be safe until needed.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=165702}},ends={{npcID=165702}},questType="standard"},
[62892] = {id=62892,name="Recover the Lost",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Anima and souls. Wind and rain. Ardenweald needs both to thrive. Souls meant for our boughs suffer in darkness. None escape the Maw... but you walk its shadows and return. You are their salvation. Flutterby shepherds the flock with care and compassion. Speak with her. Bring our lost souls home.",objectivesText="Speak to Flutterby in the Heart of the Forest.",rewardGold=25740,rewardXP=1020,starts={{npcID=165702}},ends={{npcID=165702}},questType="standard"},
[62893] = {id=62893,name="Do What We Cannot",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Rumor has it that you've been to the Maw and back... and that you even made friends with a broker in there! So many souls destined for Ardenweald are trapped in that dark realm. They need our help... and we need theirs! We can't cultivate the Heart of the Forest's magic without them. I know this is a lot to ask... but you may be our only hope of rescuing them. Please, venture into the Maw and do what we cannot. Ardenweald's future depends on it!",objectivesText="Find Ve'nari in the Maw.",rewardGold=25740,rewardXP=1020,starts={{npcID=158553}},ends={{npcID=162804}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62894] = {id=62894,name="Flutterback",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued back to Ardenweald. They deserve respite after their harrowing ordeal in the Maw, and they will surely prove vital to the Night Fae's efforts.",objectivesText="Report to Flutterby in the Heart of the Forest in Ardenweald.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1810,amount=5},{id=1822,amount=1}},starts={{npcID=164079}},ends={{npcID=158553}},questType="standard"},
[62897] = {id=62897,name="Recovered Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1702,description="Oh, I wonder what sorts of shapes these souls might take! Words can't express how grateful we are that you saved them. Not only have you brought an end to their torment, but they might be willing to aid us as well. Go speak with Zayhad. They haven't been able to tend the forest in a long while, but that might be about to change. This is all so exciting!",objectivesText="Speak to Zayhad.",rewardGold=25740,rewardXP=1020,starts={{npcID=158553}},ends={{npcID=165702}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62898] = {id=62898,name="The First New Growth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Long have we lain dormant. With souls, with anima, we grow once more. A choice now awaits. How shall we grow? You may decide which flower blooms first. In time, with more anima and willing souls, the whole garden will prosper. For now, a single blossom signals hope for the future. Lady Moonberry will want to know of your choice. Seek her out once it is made.",objectivesText="Start a Sanctum Upgrade.",rewardGold=128700,rewardXP=4085,starts={{npcID=165702}},ends={{npcID=172431}},questType="standard"},
[62899] = {id=62899,name="The Endless Forest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Well, that's all I have for you! Whew! You've been on a whirlwind tour of things around here, haven't you? Up and down and slantways and even into the Maw! Your head must be practically spinning. Flutterby giggles.> You should check in with Lady Moonberry and let her know your training is complete! She probably won't quiz you on what you've learned. Probably.",objectivesText="Return to Lady Moonberry .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=158553}},ends={{npcID=161509}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="standard"},
[62900] = {id=62900,name="A Conduit for Growth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="While our bond is powerful in and of itself, you can also enhance it through the use of conduits. Conduits channel the anima between soulbinds in many different ways, increasing both of our potential in the process. They allow us to attune ourselves to each other's unique strengths. Let's use a few now. If they can further empower our bond, then they can aid us in protecting the forest.",objectivesText="Add the Conduits to the Forge of Bonds, then apply one to a slot on Niya . Progress: We're going to do great things together.",rewardGold=128700,rewardXP=4085,starts={{npcID=172677}},ends={{npcID=158553}},coords={x=0.332,y=0.468,source="quest_giver",zoneID=12858},questType="standard"},
[62902] = {id=62902,name="Anima is Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="You did well, boss. Keep it up like that, right, and we just might 'ave a chance of survivin' this mess. Keep your eyes open, though. Word of success like this gets 'round and it's only a matter of time till uvvers come callin' for your 'elp. Now, right, all that anima you've recovered can be put to use 'round 'ere. Bring it down to Foreman Flatfinger . He'll ensure it stored away nice and secure.",objectivesText="Speak to Foreman Flatfinger .",rewardGold=25740,rewardXP=1020,starts={{npcID=165302}},ends={{npcID=165302}},questType="standard"},
[62903] = {id=62903,name="Into the Reservoir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="With anima in short supply these days, I've been entrusted to manage the reserves 'till they be needed. Go 'ead and deposit any anima you collect into the reservoir 'ere. Be assured, It'll be safe an' secure in me care.",objectivesText="Deposit Anima into your sanctum's Reservoir. Progress: I assure you, this here reservoir is the safest place to keep Anima in all of Revendreth.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=172605}},ends={{npcID=172605}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[62904] = {id=62904,name="The Souls Plight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Anima enables us to do many fings, but this sanctum can not function on anima alone. It'll require the combined effort of many souls workin' togeffer to unlock its full potential. The Soul Warden is eager to be of service ever since you rescued 'im from the Maw. Your unique ability 'ta brin' souls from there will prove useful to him. Why don't you go pay 'im a visit?",objectivesText="Speak to Tenaval .",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=164738}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[62905] = {id=62905,name="Back into the Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Souls continue to pour into the Maw, and with them the anima that could help us. You were able to rescue me from that place. Can I count on your strength to repeat the same trick? Please, get us more willing souls so we can bolster this sanctum's power. Seek out what aid you can and do what we can't, Maw Walker. You are our last, best, hope.",objectivesText="Find Ve'nari in the Maw.",rewardGold=25740,rewardXP=1020,starts={{npcID=164738}},ends={{npcID=162804}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[62914] = {id=62914,name="A Coalition of the Willing",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="The good people of Revendreth continue to suffer under the oppression of Denathrius's loyalists. We must bolster our forces before we can move openly against our former Master. The willing souls you recovered from the Maw will prove a boon in these trying times. Go to Foreman Flatfinger . He has been searching for assistance with building enhancements for our sanctum. Together, we will see Sinfall reach its full potential.",objectivesText="Speak to Foreman Flatfinger .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=164738}},ends={{npcID=172605}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="standard"},
[62915] = {id=62915,name="Home Improvement",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I've been finkin' of a bit of ways we could improve the place, but since you brought in all of the anima and souls to do it, I fink you should be the one to decide which improvement we start on first. Don't get overwhelmed. As you bring in more anima and find more willin' souls, we'll be able to bring more capabilities to the place. For now, a single upgrade will fit the bill.",objectivesText="Start a Sanctum Upgrade. Progress: Take your time. The first step's always the hard one.",rewardGold=128700,rewardXP=4085,starts={{npcID=172605}},ends={{npcID=172605}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[62916] = {id=62916,name="Your Next Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You looking for a new friend? Hoo-hoo! Lots of stewards who are happy to be friend. Plus, current friend can take break! Maybe go to Cliffs of Respite, rest feet, eat cake... Sika gets lost in a daydream.> Hoo! Right! I call stewards. You make new friend!",objectivesText="Select a new steward companion, then return to Sika . Progress: New friends, new friends! Stewards love making new friends!",starts={{npcID=175426}},ends={{npcID=175426}},coords={x=0.53,y=0.474,source="quest_giver",zoneID=10534},questType="standard"},
[62917] = {id=62917,name="Shared Souls",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1699,description="The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.",objectivesText="Meet The Accuser at the Forge of Bonds.",rewardGold=25740,rewardXP=1020,questType="standard"},
[62918] = {id=62918,name="Binding Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.",objectivesText="Complete the soulbinding ritual.",rewardGold=128700,rewardXP=4085,starts={{npcID=171950}},ends={{npcID=171979}},coords={x=0.446,y=0.202,source="quest_giver",zoneID=10986},questType="standard"},
[62919] = {id=62919,name="Strengthening the Bond",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Do you feel it, too? Our connection is stronger than I imagined could be possible. I have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. Sinfall needs our strength. Perhaps it is best we engage in this method now.",objectivesText="Use the Forge of Bonds to strengthen your bond with Nadjia. Do so by selecting a power and activating it. Progress: This will benefit us both.",rewardGold=128700,rewardXP=4085,rewardItems={180847,181373,181467,181469,181512,181639,181707,181774,181840,181962,182106,182108,182113,182130,182133,182288,182317,182324,182331,182336,182348,182448,182460,182463,182466,182469,182584,182685,182777,182962,183466,183467,183474,183495,183496,183500},starts={{npcID=171979}},ends={{npcID=171979}},coords={x=0.432,y=0.184,source="quest_giver",zoneID=10986},questType="standard"},
[62920] = {id=62920,name="A Conduit For Change",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="While the powers from your bond are substantial, you may also strengthen the bond further through the use of conduits. Conduits act to channel the energy of your soulbind into your form more directly, increasing your potential in many ways. Use the ones I have given you as a test of this power, but fear not--you will find others in your travels.",objectivesText="Add the Conduits to the Forge of Bonds, then apply one to a slot on Nadjia the Mistblade. Progress: This step is crucial for your advancement.",rewardGold=128700,rewardXP=4085,starts={{npcID=171950}},ends={{npcID=171950}},coords={x=0.446,y=0.202,source="quest_giver",zoneID=10986},questType="standard"},
[62921] = {id=62921,name="Our True Purpose",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="We are grateful for this partnership, Maw Walker. With your help, Renathal will lead us into a new era, one that will see Revendreth reclaim its true purpose. Return to him now so that the real work can begin.",objectivesText="Return to Prince Renathal .",rewardGold=772200,rewardXP=12250,rewardItems={180909,180910,180911,180912},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=171950}},ends={{npcID=158653}},coords={x=0.446,y=0.202,source="quest_giver",zoneID=10986},questType="standard"},
[62928] = {id=62928,name="Blueprint: Ring of Warding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this piece of equipment.>",objectivesText="Bring the Blueprint: Ring of Warding to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62932] = {id=62932,name="Explore Torghast",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Baine is safe, but our other allies are still prisoners of the Jailer. They remain in grave peril. Torghast is a constantly changing place, shifting according to the will of its master. It may be impossible to track them through normal means. Enter its cell blocks and see what information you can find. Seek any clue that might lead us to our missing friends, and bring it back to me.",objectivesText="Explore Torghast for clues to locate your allies. Progress: What did you find?",rewardGold=1029600,rewardXP=16330,rewardItems={184198,184758},rewardChoices={184758},rewardCurrencies={{id=1828,amount=200}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62935] = {id=62935,name="Remnants of Hope",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13575,mapID=1670,description="I studied the key you brought back from Torghast, . It confirms that Jaina Proudmoore is still being held somewhere in the tower. However we do not know precisely where. Countless souls are captive inside that wretched place. A few may be intact, but many are shattered and broken. Take pity upon the remnants and free those you can. Perhaps they will be able to aid our search.",objectivesText="See if you can gain any new insights from the trapped Soul Remnants in Torghast.",rewardGold=1029600,rewardXP=16330,rewardCurrencies={{id=1828,amount=100}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62938] = {id=62938,name="Information for a Price",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="We must continue our search for Jaina Proudmoore. I have a new strategy to suggest. Since arriving in Oribos, I have been approached by many of the brokers. Some ask questions, others offer help--for a price. You have encountered others of their kind inside Torghast. They may possess information we can use, though I doubt they will part with it freely. Seek them out and appeal to their avarice. Offer to pay for whatever information they possess.",objectivesText="Question the Brokers trapped inside Torghast. Progress: A promising lead.",rewardGold=1029600,rewardXP=16330,rewardItems={184199,184200},rewardCurrencies={{id=1828,amount=50}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62951] = {id=62951,name="Path of Ascension: Kleia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Artemede has been personally training Kleia , running her through combat meditations and drills. She has come far, and she is prepared to take on another trial in the Path of Ascension. Return to the coliseum and guide her as her tactician so that she may reach victory.",objectivesText="Win any Path of Ascension trial as Kleia .",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[62952] = {id=62952,name="Path of Ascension: Pelagos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Though combat is not his strong suit, Pelagos has been reading, meditating, and training to better himself on the Path. We believe he is ready to seek victory. He requests you by his side to help him strategize. He is stronger with the help of his friends.",objectivesText="Win any Path of Ascension trial as Pelagos .",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[62953] = {id=62953,name="Path of Ascension: Mikanikos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Mikanikos has been hard at work at the Eternal Forge, calibrating Bron and tuning his combat procedures. He is confident in his recent changes, and requests permission to attempt another trial. Enter the Path with Mikanikos so that he may assess his goliath's strengths and weaknesses.",objectivesText="Win any Path of Ascension trial as Mikanikos .",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[62954] = {id=62954,name="Path of Ascension: Kalisthene",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Kalisthene , that they may learn from the lessons her memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Kalisthene to prove their growth.",objectivesText="Defeat Kalisthene in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[62966] = {id=62966,name="Finding a Witness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have rescued two of our allies from Torghast, but Anduin and Thrall have yet to be found. That tower's corridors are vast... seemingly endless. You could spend an eternity wandering those unholy halls. In your expeditions, you have encountered many unfortunate prisoners. Perhaps one of them has seen or heard something that could guide our search. Seek out any captives that might have the information we need, .",objectivesText="Look for a prisoner in Torghast who might know where Anduin or Thrall is being held.",rewardGold=1029600,rewardXP=16330,rewardCurrencies={{id=1828,amount=50}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62967] = {id=62967,name="Prison of the Forgotten",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I discovered an interesting item off the Warden you killed in the tower. Best not to ask how I know what you do and where you do it within the tower. Let's just say, I have my ways. But this key could lead to something interesting within Torghast. Or something horrible. Most likely horrible. You ought to explore a bit and see what it unlocks.",objectivesText="Figure out where to use the Key of the Forgotten. Provided item:",rewardXP=4085,starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[62969] = {id=62969,name="Lest the Trail Go Cold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="From what the captive dredger told you, it seems Thrall has been taken deep into Torghast. The torments he is enduring must be unimaginable. We need to learn where he is being held before the trail goes cold. The tower is vast and perilous. Search where you are able. Bring back any clues you find. Go carefully, . The Jailer's eye is upon you.",objectivesText="Enter Torghast and find something to help us locate Thrall. Progress: Have you found anything to help us locate Thrall?",rewardGold=1029600,rewardXP=16330,rewardItems={184242},rewardCurrencies={{id=1828,amount=50}},starts={{npcID=164079}},ends={{npcID=164079}},questType="standard"},
[62970] = {id=62970,name="Blueprint: Steward Mail Pouch",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this.>",objectivesText="Bring the Blueprint: Steward Mail Pouch to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62971] = {id=62971,name="Blueprint: Gilded Abacus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this.>",objectivesText="Bring the Blueprint: Gilded Abacus to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62976] = {id=62976,name="Artisan Tool Belt",level=60,requiredLevel=60,faction="both",expansion=8,description="steward to not only assist you with crafting, but also carry common trade goods.>",objectivesText="Summon your steward companion via Summon steward , then give them the steward Mail Pouch. Provided item:",questType="standard"},
[62981] = {id=62981,name="Blueprint: Artisan Tool Belt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this.>",objectivesText="Bring the Blueprint: Artisan Tool Belt to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62984] = {id=62984,name="Blueprint: Medallion of Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you facilitate this.>",objectivesText="Bring the Blueprint: Medallion of Service to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62985] = {id=62985,name="Dredging up a New Look",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,description="If ye look around the muck pool I am sure you will find an armor dye. It might be nice to have the option to dye me belt a different color.",objectivesText="Search enemies or discarded bottles in the Dredgewood for an armor dye. Progress: Did you find one?",rewardGold=257400,rewardXP=8165,starts={{npcID=172854}},ends={{npcID=172854}},coords={x=0,y=0,source="quest_giver",zoneID=16105},questType="standard"},
[62986] = {id=62986,name="Blueprint: Vesper of Calling",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this chime.>",objectivesText="Bring the Blueprint: Vesper of Calling to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62993] = {id=62993,name="The Riddle of Death",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62995] = {id=62995,name="Spiritforged Aegis",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<As you pick up the shield, your hands seem to lightly bounce off of it with ease. This should help your soulbinds take a few hits in the Path of Ascension.>",objectivesText="Bring the Spiritforged Aegis to Paolone .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1819,amount=2}},ends={{npcID=171816}},coords={mapID=1533,source="quest_giver",x=0.628,y=0.16},questType="standard"},
[62996] = {id=62996,name="Vial of Lichfrost",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<The vial, filled with a frosty liquid, is chill to the touch. This should hinder your soulbinds' opponents in the Path of Ascension.>",objectivesText="Bring the Vial of Lichfrost to Paolone .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1819,amount=2}},ends={{npcID=171816}},coords={mapID=1533,source="quest_giver",x=0.628,y=0.16},questType="standard"},
[62997] = {id=62997,name="Blueprint: Vial of Lichfrost",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this piece of equipment.>",objectivesText="Bring the Blueprint: Vial of Lichfrost to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[62998] = {id=62998,name="Ring of Warding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="<You place down the ring and are knocked back by a protective bubble. This should force your soulbinds' opponents away from an area in the Path of Ascension.",objectivesText="Bring the Ring of Warding to Paolone .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1819,amount=2}},ends={{npcID=171816}},coords={mapID=1533,source="quest_giver",x=0.628,y=0.16},questType="standard"},
[62999] = {id=62999,name="Champion: Croman",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[63000] = {id=63000,name="Blueprint: Charm of Focus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Dactylis should be able to help you with crafting this charm.>",objectivesText="Bring the Blueprint: Charm of Focus to Dactylis . Provided item:",ends={{npcID=168430}},coords={mapID=1533,source="quest_giver",x=0.63,y=0.16},questType="standard"},
[63002] = {id=63002,name="Dangerous to Go Alone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="I trust you know well all that Elysian Hold can provide, but that alone will not be enough to thwart Denathrius. You must have a soulbind to aid you, Maw Walker. Seek out Soulguide Daelia in the chamber below. She has prepared for the ritual.",objectivesText="Speak with Soulguide Daelia in the Sanctum of Binding.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=160212}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[63003] = {id=63003,name="Collective Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="You know conflict as well as any soldier in Maldraxxus, Maw Walker. But we do not fight alone. There is great wisdom in leaning on the strengths of your allies. That is the Maldraxxi way. Speak to Plague Deviser Marileth . He will show you how to soulbind and best reap its benefits.",objectivesText="Speak with Plague Deviser Marileth about the soulbinding process.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161904}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[63006] = {id=63006,name="For Queen and Grove!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="You have already done so much to help us since you first step foot in our realm! I'm so glad you decided to join our covenant. There will be plenty of time for reminiscing later, though. You have an audience with the Winter Queen herself to go to! Let's not keep her waiting!",objectivesText="Join the Night Fae Covenant. Progress: Welcome to the Hunt.",rewardGold=257400,rewardXP=8165,starts={{npcID=161509}},ends={{npcID=156634}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[63008] = {id=63008,name="The Forge of Bonds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="To best serve the court and the forest, you must bond with another fae. It is an ancient ritual, one which will grant you great strength to face the many trials ahead. Flutterby below will guide you further.",objectivesText="Meet Flutterby at the Forge of Bonds.",rewardGold=25740,rewardXP=1020,starts={{npcID=156634},{npcID=172431}},ends={{npcID=158553}},coords={x=0.454,y=0.656,source="quest_giver",zoneID=11510},questType="standard"},
[63022] = {id=63022,name="Rule 6 Addendum: Save Me At Any Cost",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="You! You, there! Wait! You are the infamous Maw Walker, yes? I have heard much about you. Please, help me! My compatriots have been drained of their essence. The Mawsworn are using it to fashion their foul runes. One of them bound me here, and I am sure to be next on his list. You must slay him in order to free me! I can make it worth your while. I have collected a fair amount of stygia during my time in the Maw . It is yours, all of it, if you save me!",objectivesText="Slay Runemaster Mavrok . Progress: There is no time to waste. Hurry, before the Mawsworn return!",rewardGold=514800,rewardXP=10205,rewardItems={182955},rewardCurrencies={{id=1767,amount=223}},starts={{npcID=175703}},ends={{npcID=175703}},coords={x=0.57,y=0.576,source="quest_giver",zoneID=11400},questType="standard"},
[63029] = {id=63029,name="The Highlord Calls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="We have received word from Highlord Fordragon urging you to return to him in Oribos at once. All I know is it pertains to the Maw . You should go to him with haste. Anything involving that dark place must be our top priority.",objectivesText="Report to Highlord Bolvar Fordragon in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=160037}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[63030] = {id=63030,name="The Highlord Calls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Highlord Fordragon needs you in Oribos right away! I'm not sure of the details, but the messenger mentioned the Maw . You should go to him as soon as you can. If the Maw is involved, it must be serious!",objectivesText="Report to Highlord Bolvar Fordragon in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=161509}},ends={{npcID=161509}},coords={x=0.5,y=0.402,source="quest_giver",zoneID=12858},questType="standard"},
[63031] = {id=63031,name="Acquisition: Crystallized Stygia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari would likely be interested in any of these shards you come across.>",rewardItems={184510},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=364899,x=0.212,y=0.341,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.212,y=0.341,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Crystallized Stygia"},
[63032] = {id=63032,name="The Highlord Calls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Highlord Fordragon has requested your presence in Oribos. We know only that it involves the Maw . Go to him, and show him that the Maldraxxi will never falter. Even in the face of that dark place.",objectivesText="Report to Highlord Bolvar Fordragon in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=161907}},ends={{npcID=161907}},coords={x=0.496,y=0.502,source="quest_giver",zoneID=12876},questType="standard"},
[63033] = {id=63033,name="The Highlord Calls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="A messenger from Oribos has informed us that Highlord Fordragon has requested your presence in Oribos. It seems it pertains to the Maw ... and the Master's plans, no doubt. I suggest you heed his summons, Maw Walker. We must leave nothing to chance.",objectivesText="Report to Highlord Bolvar Fordragon in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=158653}},ends={{npcID=158653}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[63034] = {id=63034,name="The Elysian Fields",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11012,description="You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in your new sanctum, Elysian Hold. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Kalisthene at Elysian Hold in Bastion .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=168517}},questType="standard"},
[63035] = {id=63035,name="A Fresh Blade",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other. Their armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus. Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus . His tactical skills will ensure you are sent where you are most needed. Pathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.",objectivesText="Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus .",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=175008}},questType="standard"},
[63036] = {id=63036,name="Restoring Balance",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm. Unfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle. Now foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. Lady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Lady Moonberry at the Heart of the Forest in Ardenweald .",rewardGold=27855,rewardXP=850,starts={{npcID=159478}},ends={{npcID=172431}},questType="standard"},
[63037] = {id=63037,name="Dark Aspirations",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10986,description="Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth 's vast anima stores into the Maw. You must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.",objectivesText="Speak to Prince Renathal in Sinfall in Revendreth .",rewardGold=5350,rewardXP=850,starts={{npcID=159478}},ends={{npcID=158653}},questType="standard"},
[63038] = {id=63038,name="Guaranteed Delivery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari . Clutched in their hand is a list of items and a containment orb . Finishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>",rewardItems={184513},rewardCurrencies={{id=1767,amount=600},{id=1880,amount=475}},starts={{npcID=175797,x=0.306,y=0.584,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.306,y=0.584,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Guaranteed Delivery",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63039] = {id=63039,name="A Monument to Vengeance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,rewardItems={184511},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=175807,x=0.222,y=0.478,zoneID=11400}},ends={{npcID=364911,x=0.234,y=0.499,zoneID=11400}},coords={x=0.222,y=0.478,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Monument to Vengeance"},
[63040] = {id=63040,name="Guaranteed Delivery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari . Clutched in their hand is a list of items and a containment orb . Finishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>",rewardItems={184513},rewardCurrencies={{id=1880,amount=475}},starts={{npcID=175797,x=0.306,y=0.584,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.306,y=0.584,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Guaranteed Delivery",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63041] = {id=63041,name="Short-Supply Reward",level=60,requiredLevel=60,faction="none",expansion=8,rewardItems={184522},questType="standard"},
[63043] = {id=63043,name="Sundered Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The traps... they didn't affect us before. Too many souls... escaping. They... made new traps... tear apart fleeing souls... ...too late for me. Destroy... so others might escape!",starts={{npcID=175813,x=0.282,y=0.146,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400},{npcID=178228,x=0.27,y=0.138,zoneID=11400}},coords={x=0.282,y=0.146,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Sundered Souls"},
[63044] = {id=63044,name="Ratgusher",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,rewardXP=8165,questType="standard",worldTaskTitle="Ratgusher"},
[63045] = {id=63045,name="Feed Your Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="They... drained my anima... to fuel their ritual... Souls of great power are brought here... to this altar... and sacrificed to conjure unspeakable horrors bound to the Jailer. I was powerful once... Imbue me with the anima they stole... and I can be powerful again. Then, together... we will destroy the one who leads their efforts.",rewardCurrencies={{id=1767,amount=600},{id=1880,amount=475}},starts={{npcID=175866,x=0.25,y=0.666,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.25,y=0.666,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Feed Your Soul",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63046] = {id=63046,name="The End and the Beginning",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,description="I am so happy you restored our connection to the Queen's Conservatory! In light of this accomplishment, the Winter Queen has requested you attend her at the Grove of Awakening! You will see first hand the purpose of Ardenweald and gain a greater understanding of our sacred charge before you too, take it upon yourself. Hurry! Don't keep everyone waiting!",objectivesText="Learn about Wildseeds from the Winter Queen .",rewardGold=128700,rewardXP=4085,starts={{npcID=173171}},ends={{npcID=166476}},questType="standard"},
[63047] = {id=63047,name="Acquisition: Runeforged Shackles",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could find some use in studying these runes.>",rewardItems={184552},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=364926,x=0.257,y=0.242,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.257,y=0.242,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Runeforged Shackles"},
[63050] = {id=63050,name="Acquisition: Blazing Ingots",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could aid her attempts at unlocking the Jailer's secrets.>",rewardItems={184556},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=364932,x=0.39,y=0.399,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.39,y=0.399,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Blazing Ingots"},
[63051] = {id=63051,name="Trust Issues",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ah, Maw Walker! Allow me to introduce myself. I am Ve'rayn . I deal with assets and liabilities for Cartel Ve. I have heard that you are able to freely travel between Oribos and the Maw , a place of great interest to my cartel. Would you mind if I ask you a few questions about it? You will, of course, be properly compensated for your time and information. They are the most valuable of commodities, after all.",objectivesText="Answer Ve'rayn 's questions about the Maw .",rewardGold=128700,rewardXP=4085,starts={{npcID=168432}},ends={{npcID=162804}},questType="standard"},
[63052] = {id=63052,name="Step of Faith",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Our ascended fly across Bastion with ease, ensuring safety and prosperity across the realm. Long ago we established a network of anima gateways to help our aspirants, goliaths, and stewards traverse our realm more quickly. Go forth and activate the network once more, so that you too may be wherever you are needed in the mere blink of an eye.",objectivesText="Activate the Transportation Network.",rewardGold=25740,rewardXP=1020,starts={{npcID=167745}},ends={{npcID=175907}},coords={x=0.648,y=0.18,source="quest_giver",zoneID=10534},questType="standard"},
[63053] = {id=63053,name="At a Moment's Notice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="No longer must you take a larion across Bastion, Maw Walker. With our gateways active once more, you shall enjoy instantaneous travel wherever you are needed. Do note that you must still utilize a larion to return to Oribos or travel to the other realms. Give it a try and see for yourself.",objectivesText="Use the Eternal Gateway to travel somewhere in Bastion, then use any Eternal Gateway to return to Elysian Hold. Progress: It really is amazing, is it not?",rewardGold=25740,rewardXP=1020,starts={{npcID=175907}},ends={{npcID=175907}},coords={x=0.486,y=0.626,source="quest_giver",zoneID=11012},questType="standard"},
[63054] = {id=63054,name="Strength in Numbers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="Every soul in Maldraxxus has the potential for greatness, and we will need all we can muster if we hope to restore order to the Shadowlands. With this addition to the sanctum, we can mobilize our forces and give them the chance to prove themselves on the field of battle. Seek out Merick Feldscar . He will see to the deployment of our soldiers.",objectivesText="Activate the Command Table.",rewardGold=128700,rewardXP=4085,starts={{npcID=161909}},ends={{npcID=165321}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[63055] = {id=63055,name="Powering the Portals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="The Primus once maintained a network of portals that linked the necropoli of Maldraxxus directly to the Seat of the Primus. The lack of anima and recent destruction of many of the necropoli have rendered those connections inactive. With the anima you have provided us, we have managed to reconnect one of those portals. You shall once more be able to travel to one of our great necropoli... assuming it still exists.",objectivesText="Activate the Transportation Network.",rewardGold=25740,rewardXP=1020,starts={{npcID=161909}},ends={{npcID=175963}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[63056] = {id=63056,name="Sanctum Upgrade: Mirror Network",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Right. So, we got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Thing is, after you going to need a proper mirror maker to get 'em up an' workin'. Prince Renathal might know a fang with the right skills. Best speak with him.",objectivesText="Use the Scroll of Dark Empowerment to conjure a Mirror Network. Progress: Enough anima in the right hands and we can construct whatever is needed in Revendreth .",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=158653}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[63057] = {id=63057,name="Restoring Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="Anima is power, ! When it was plentiful, the Primus ensured that his soldiers received all of the anima they required. Now, in the midst of this drought, the Maldraxxi fight amongst themselves for any anima they can find. As our stockpile of anima grows, we can distribute it throughout Maldraxxus. It falls to us Necrolords to carry out the Primus's duty in his absence. Speak to Yondare Hex . She will show you how to do so.",objectivesText="Activate the Anima Conductor. Progress: Yes, yes, you! You can help!",rewardGold=170800,rewardXP=4085,starts={{npcID=161909}},ends={{npcID=167205}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[63058] = {id=63058,name="Abominable Stitching and Me",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Constructs have formed the backbone of Maldraxxi armies in more wars than anyone can count. A well-constructed body can turn any soul into a potent frontline weapon. There is an old abominable stitching table outside of the sanctum that could be used to build our own constructs. With the anima you've secured for our covenant, we should be able to restore it. Report to Miggsie once the work has begun. You can find her at Butchers Block.",objectivesText="Activate the Abomination Factory. Progress: You made the right choice.",rewardGold=128700,rewardXP=4085,starts={{npcID=161909}},ends={{npcID=175967}},coords={x=0.524,y=0.382,source="quest_giver",zoneID=12876},questType="standard"},
[63059] = {id=63059,name="Blink of an Eye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,description="This was once a long tauralus ride, but not anymore! By simply stepping through this portal, you can now journey to the House of Eyes in an instant. The House of Eyes may not be what it once was, but valuable allies can still be found in the ruins of their once great necropolis. Travel there now to test the portal's functionality.",objectivesText="Travel through the Nurakkir, House of Eyes portal, then use the Seat of the Primus portal to return. Progress: It worked! That was most unexpected.",rewardGold=128700,rewardXP=4085,starts={{npcID=175963}},ends={{npcID=175963}},coords={x=0.594,y=0.324,source="quest_giver",zoneID=12876},questType="standard"},
[63060] = {id=63060,name="Rule 6 Footnote: Don't Forget Anything",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="In the Maw , you must never forget to take everything with you. Many things crawl within the Beastwarrens. The runes you brought back indicate that something of interest may have been left behind by the brokers who were taken there. See if you can find it.",objectivesText="Look for whatever was left behind by the brokers in the Beastwarrens.",rewardGold=25740,rewardXP=1020,rewardItems={182955},starts={{npcID=162804}},ends={{npcID=175703}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[63062] = {id=63062,name="Torment for the Taking",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,rewardCurrencies={{id=1767,amount=400}},starts={{npcID=364937,x=0.28,y=0.47,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.28,y=0.47,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Torment for the Taking"},
[63063] = {id=63063,name="Sanctum Upgrade: Mirror Network",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Once you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.",objectivesText="Use the Scroll of Dark Empowerment to conjure a Mirror Network.",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=167160}},coords={x=0.558,y=0.272,source="quest_giver",mapID=1525},questType="standard"},
[63064] = {id=63064,name="Sanctum Upgrade: Command Table",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="We got a Scroll of Dark Empowerment ready for youz that should manifest a command table for you. Not just any command table, but one of 'em magic ones that lets you issue orders from afar. Tactician Sakaa insisted she be your wing for that one. Never much trusted 'em wings as they ain't too kind to us dredgers but put 'em in charge of war and even Maldraxxus flinches.",objectivesText="Use the Scroll of Dark Empowerment to conjure a Command Table. Progress: Maw Walker.",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=164741}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[63065] = {id=63065,name="Sanctum Upgrade: The Ember Court",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="We got a Scroll of Dark Empowerment ready for youz that should provide you with enough resources to get one of 'em fancy parties the fangs are fond of. The Mad Duke is the one you should chat with 'bout this one. He used to run all the court parties back before he got roasted.",objectivesText="Use the Scroll of Dark Empowerment to begin the Ember Court.",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=161979}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[63066] = {id=63066,name="Sanctum Upgrade: Anima Conductor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,description="Right. So we got all this anima you been collecting. Thing is, all that anima originally got squeezed out of the other realms. The Master, he was big on drainin' anything that weren't him. So, we set up a Scroll of Dark Empowerment for you on the lower level. Should conjure somefin' strong enough for you to channel anima back into the Shadowlands, by way of Revendreth Wards. Seems to me there'd be some fringe benefits from somefin like that.",objectivesText="Use the Scroll of Dark Empowerment to conjure an Anima Conductor.",rewardGold=25740,rewardXP=1020,starts={{npcID=172605}},ends={{npcID=164739}},coords={x=0.558,y=0.272,source="quest_giver",zoneID=10986},questType="standard"},
[63067] = {id=63067,name="Root Restoration",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="Anima once flowed freely, but we have been thirsting. You bring us nourishment in times of trouble. We grow. We may now help others and share our bounty. Watch our growth, then speak with Sesselie . They will guide you further.",objectivesText="Activate the Anima Conductor, then seek out Sesselie . Progress: Ah. You're here. Good.",rewardGold=25740,rewardXP=1020,starts={{npcID=165702}},ends={{npcID=165702}},questType="standard"},
[63068] = {id=63068,name="Settling Disputes",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11012,mapID=1533,description="In my search to find kyrian that would fit our purposes here, I have landed on two in particular -- Pelodis and Nemea . However, the two are involved in quite the rivalry, and struggle to focus their attention elsewhere. I propose that you aid them in settling their dispute so that they may focus on the task at hand. I doubt they shall work together, however, so you will need to pick one to aid us.",objectivesText="Meet with Pelodis at Forgefire Outpost or Nemea at Nemea 's Retreat.",rewardGold=23870,rewardXP=175,starts={{npcID=160389}},ends={{npcID=157696},{npcID=158765}},coords={x=0.648,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63069] = {id=63069,name="What They Know",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari would likely be very interested in what he found. Unfortunately, his notes look to have been scattered far and wide by the local beasts.>",rewardItems={184579},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=364987,x=0.464,y=0.622,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.464,y=0.622,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="What They Know"},
[63072] = {id=63072,name="Acquisition: Stygic Ore",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could certainly find use for some of this ore, if you can manage to mine it.>",rewardItems={184585},rewardCurrencies={{id=1767,amount=400}},starts={{npcID=364994,x=0.472,y=0.826,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.472,y=0.826,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Stygic Ore"},
[63073] = {id=63073,name="A Mycelial Network",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,description="Anima flows into the deepest of roots, feeding the mushrooms. Long has it been since we used the rings to travel across Ardenweald. Restore our connection to the mushroom network.",objectivesText="Activate the Transportation Network.",rewardGold=25740,rewardXP=1020,starts={{npcID=165702}},ends={{npcID=165702}},questType="standard"},
[63100] = {id=63100,name="Misery's Company",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,starts={{npcID=176069,x=0.246,y=0.454,zoneID=11400}},coords={x=0.246,y=0.454,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Misery's Company"},
[63101] = {id=63101,name="XX REUSEME",level=60,requiredLevel=60,faction="none",expansion=8,description="As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. Seek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.",objectivesText="Seek out Laurel the Heart of the Forest.",rewardGold=25270,rewardXP=1020,questType="standard"},
[63132] = {id=63132,name="Constellan Writ",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari may find intriguing.>",objectivesText="Bring the Constellan Writ to Ve'nari at Ve'nari 's Refuge. Provided item:",rewardGold=257400,rewardXP=8165,ends={{npcID=162804}},coords={mapID=1543,source="quest_giver",x=0.468,y=0.416},questType="standard"},
