[63166] = {id=63166,name="A Shadowed Fate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn... torture and torment souls within Ruin's Cradle. I... barely escaped, but I'm afraid I won't last long. Their twisted rituals... breaking souls to serve as wretched shades. Spare them this fate!",rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=176029,x=0.298,y=0.208,zoneID=11400}},ends={{npcID=176029,x=0.298,y=0.208,zoneID=11400}},coords={x=0.298,y=0.208,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Shadowed Fate"},
[63168] = {id=63168,name="Path of Ascension: Echthra",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Echthra , that they may learn from the lessons her memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Echthra to prove their growth.",objectivesText="Defeat Echthra in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63169] = {id=63169,name="Path of Ascension: Alderyn and Myn'ir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Alderyn and Myn'ir, that they may learn from the lessons their memories teach. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Alderyn and Myn'ir to prove their growth.",objectivesText="Defeat Alderyn and Myn'ir in the Path of Ascension with any soulbind. Progress: Alderyn and Myn'ir's dedication and focus can teach us much.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63170] = {id=63170,name="Path of Ascension: Nuuminuuru",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Nuuminuuru , that they may learn from the lessons their memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Nuuminuuru to prove their growth.",objectivesText="Defeat Nuuminuuru in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63171] = {id=63171,name="Path of Ascension: Craven Corinth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Craven Corinth , that they may learn from the lessons his memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Craven Corinth to prove their growth.",objectivesText="Defeat Craven Corinth in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63172] = {id=63172,name="Path of Ascension: Splinterbark Nightmare",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Splinterbark Nightmare , that they may learn from the lessons its memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Splinterbark Nightmare to prove their growth.",objectivesText="Defeat Splinterbark Nightmare in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63173] = {id=63173,name="Path of Ascension: Thran'tiok",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Thran'tiok , that they may learn from the lessons her memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Thran'tiok to prove their growth.",objectivesText="Defeat Thran'tiok in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63174] = {id=63174,name="Path of Ascension: Mad Mortimer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Mad Mortimer, that they may learn from the lessons his memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Mad Mortimer to prove their growth.",objectivesText="Defeat Mad Mortimer in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63175] = {id=63175,name="Path of Ascension: Athanos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Athanos , that they may learn from the lessons his memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Athanos to prove their growth.",objectivesText="Defeat Athanos in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63176] = {id=63176,name="Path of Ascension: Azaruux",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Your soulbinds request your strategic mind in another trial. Their sights this week are set on Azaruux , that they may learn from the lessons their memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Azaruux to prove their growth.",objectivesText="Defeat Azaruux in the Path of Ascension with any soulbind.",rewardItems={184812},starts={{npcID=168485}},ends={{npcID=168485}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63179] = {id=63179,name="Drowned and Torn Asunder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Maw Walker! I am relieved to see you in this place. A dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen. This... Helya, I believe they called her... seems determined to break us so that we might also join her ranks. Please, if you can, save my brethren.",rewardCurrencies={{id=1880,amount=175}},starts={{npcID=176144,x=0.388,y=0.236,zoneID=11400}},ends={{npcID=176144,x=0.388,y=0.236,zoneID=11400}},coords={x=0.388,y=0.236,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Drowned and Torn Asunder"},
[63181] = {id=63181,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? It seems Pelagos has been struggling with his trials. I believe, with your guidance, some extra training on the Path is just what he needs! Athanos has many lessons to teach. With your aid, Pelagos can achieve victory and new experience to meditate on.",objectivesText="Defeat Athanos as Pelagos in a Trial of Loyalty or higher in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63182] = {id=63182,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Pelagos's time spent in Ardenweald taught him many lessons. I would like to witness what he has learned. A trial against Nuuminuuru should allow him this chance. With your aid, Pelagos can achieve victory and new experience to meditate on.",objectivesText="Defeat Nuuminuuru as Pelagos in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63184] = {id=63184,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Mikanikos has requested an additional trial to train Bron. Splinterbark Nightmare's memory was captured with the help of his praetors, and should prove a worthy challenge for his goliath. With your guidance, Mikanikos and Bron can overcome another trial.",objectivesText="Defeat Splinterbark Nightmare as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63185] = {id=63185,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. Echthra's memory shall provide her with new lessons. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.",objectivesText="Defeat Echthra as Kleia in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63186] = {id=63186,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. If she is to bear souls across the veil, she will need be prepared to contend against devourers like Azaruux. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.",objectivesText="Defeat Azaruux as Kleia in a Trial of Loyalty or higher in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63187] = {id=63187,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Mikanikos has requested an additional trial to train Bron. Mad Mortimer's memory should prove a good challenge, as he and Mikanikos share a mind with a passion to further their research. With your guidance, Mikanikos and Bron can overcome another trial.",objectivesText="Defeat Mad Mortimer as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63188] = {id=63188,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Thenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities. A trial against Alderyn and Myn'ir shall suffice. Let us see you and your soulbinds can do.",objectivesText="Defeat Alderyn and Myn'ir in a Trial of Wisdom in the Path of Ascension. Progress: Are you up for the challenge?",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63189] = {id=63189,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Thenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities. A trial against Thran'tiok shall suffice. Let us see you and your soulbinds can do.",objectivesText="Defeat Thran'tiok in a Trial of Wisdom in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63190] = {id=63190,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Though most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed. Let us see how your soulbinds fare against the memory of Craven Corinth while utilizing the Ring of Warding.",objectivesText="Defeat Craven Corinth with the Ring of Warding in a Trial of Loyalty or higher in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63191] = {id=63191,name="Path of Ascension: Artemede's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Though most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed. Let us see how your soulbinds fare against the memory of Kalisthene while utilizing the Spiritforged Aegis.",objectivesText="Defeat Kalisthene with the Spiritforged Aegis in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63192] = {id=63192,name="Path of Ascension: Trial of Humility",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Are you prepared for a challenge, ? Many kyrian struggle with their trials of humility at some point along their path. It is important to remember that we can always be learning and improving, no matter how far we have come. But as we continue training, we can overcome more obstacles than before. It is time for your soulbinds to be reminded of this lesson. Let us witness you all succeed in a Trial of Humility.",objectivesText="Overcome a Trial of Humility in the Path of Ascension.",rewardItems={184811},starts={{npcID=168427}},ends={{npcID=168427}},coords={x=0.628,y=0.164,source="quest_giver",zoneID=10534},questType="standard"},
[63206] = {id=63206,name="Soulless Husks",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Some of the Mawsworn begin as inanimate suits of armor, forged by the stygian smiths of Zovaal's Cauldron. Once fashioned, they await infusion of a decrepit shade to complete their genesis. It is at this time they are the most vulnerable, and so it is then you should strike. The hammers wielded by the Mawsworn runesmiths hold the power to break as well as they shape. Procure one of them and smash our foes to dust before they can rise against us.",objectivesText="Obtain a Stygian Hammer from a Stygian Runesmith and destroy 10 Armored Husks in Zovaal's Cauldron. Progress: Have you satisfactorily dismantled our enemies?",rewardItems={184622},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},starts={{npcID=162804}},ends={{npcID=162804}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard",worldTaskTitle="Soulless Husks"},
[63208] = {id=63208,name="The Next Step",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="Your efforts have not gone unnoticed, but there are other realms that still require your aid. Consider the next step in your journey, mortal.",objectivesText="Choose where to go in the Shadowlands.",rewardGold=128700,rewardXP=3410,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63209] = {id=63209,name="Furthering the Purpose",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="There are realms which still require your aid, mortal. You must journey to one of their realms and ensure they stand strong. Where will you go next?",objectivesText="Choose where to go in the Shadowlands.",rewardGold=128700,rewardXP=3410,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63210] = {id=63210,name="The Last Step",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="Just one realm remains which requires your aid, mortal. Speak with me when you are ready, and I shall inform you further. Such is the Purpose.",objectivesText="Choose where to go in the Shadowlands.",rewardGold=128700,rewardXP=3410,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63211] = {id=63211,name="Report to Adrestes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have chosen well. The Kyrian have long ferried souls across the veil into the Shadowlands, ensuring a steady supply of anima for all the realms. Their sacred purpose must be kept strong. Speak with Polemarch Adrestes and begin your future with your covenant.",objectivesText="Report to Polemarch Adrestes .",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63212] = {id=63212,name="Report to Mevix",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have chosen well. The Necrolords, eternal protectors of the Shadowlands, must remain strong to ensure we may continue to fulfill the Purpose. Aid them as best you can. Speak with Secutor Mevix and begin your future with your covenant.",objectivesText="Report to Secutor Mevix .",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63213] = {id=63213,name="Naladu the Elder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,rewardItems={184627,184628},starts={{npcID=176253}},ends={{npcID=176253}},coords={x=0.616,y=0.602,source="quest_giver",mapID=1525},questType="standard"},
[63214] = {id=63214,name="Report to Moonberry",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have chosen well. The Night Fae fill a critical role in the eternal cycle of nature spirits. The balance of many worlds depends on their work. Speak with Lady Moonberry and begin your future with your covenant.",objectivesText="Report to Lady Moonberry .",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63215] = {id=63215,name="Report to Draven",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have chosen well. The Venthyr must return to their duty helping souls atone for their sins, saving them from an eternity in the Maw. Denathrius's treachery must be righted. Speak with General Draven and begin your future with your covenant.",objectivesText="Report to General Draven .",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63340] = {id=63340,name="Sinfall Veteran",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Sinfall's influence grows thanks to your triumphs, ! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175772}},ends={{npcID=175772}},coords={x=0.546,y=0.268,source="quest_giver",zoneID=10986},questType="standard"},
[63341] = {id=63341,name="Sinfall Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, . Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175772}},ends={{npcID=175772}},coords={x=0.546,y=0.268,source="quest_giver",zoneID=10986},questType="standard"},
[63342] = {id=63342,name="Necrolord Veteran",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="The might of the Necrolords grows thanks to you, . Your accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175998}},ends={{npcID=175998}},coords={x=0.468,y=0.402,source="quest_giver",zoneID=12876},questType="standard"},
[63343] = {id=63343,name="Necrolord Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175998}},ends={{npcID=175998}},coords={x=0.468,y=0.402,source="quest_giver",zoneID=12876},questType="standard"},
[63344] = {id=63344,name="Kyrian Veteran",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="Bastion is healing thanks to you, . The path is clear. Your accomplishments have not gone unnoticed, even beyond the borders of Bastion. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176100}},ends={{npcID=176100}},coords={x=0.648,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[63345] = {id=63345,name="Kyrian Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="Look around you, . Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176100}},ends={{npcID=176100}},coords={x=0.648,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[63346] = {id=63346,name="Night Fae Veteran",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176096}},ends={{npcID=176096}},coords={x=0.34,y=0.37,source="quest_giver",zoneID=12858},questType="standard"},
[63347] = {id=63347,name="Night Fae Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176096}},ends={{npcID=176096}},coords={x=0.34,y=0.37,source="quest_giver",zoneID=12858},questType="standard"},
[63418] = {id=63418,name="Exploited Explorers",level=10,requiredLevel=10,faction="none",expansion=8,description="Chuck explains that something weird is happening in the jungle, and that his group has been captured by wild fungarians. He asks you to rescue his friends to help find out what's going on with the jungle.",objectivesText="Rescue Chuck's friends",rewardGold=169800,rewardXP=1415,questType="standard"},
[63419] = {id=63419,name="Spores Galore",level=10,requiredLevel=10,faction="none",expansion=8,description="Chuck goes over again how the jungle seems to be alive and all wrong. He asks you to recover the spores that are on the fungarians and the beasts they've infected. Chuck is worried whatever is happening isn't natural.",objectivesText="Collect 12 strange",rewardGold=169800,rewardXP=1415,questType="standard"},
[63435] = {id=63435,name="Temple Throwdown",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=5841,mapID=379,description="My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here. They told me I could train with the big white cat! I'm going to be a ninja! Anthea kicks several times in your direction.> Ya! Kya! You better watch out! ... I'm bored, do you want to pet battle? I brought all of my favorite pets with me.",objectivesText="Defeat Anthea in a pet battle. Progress: I'm gonna get you! < Anthea punches the air several times.> Biff! Pow!",rewardGold=341600,rewardXP=200,rewardItems={89587,184866,184867},starts={{npcID=176655}},ends={{npcID=176655}},coords={x=0.704,y=0.514,source="quest_giver",zoneID=5841},questType="standard"},
[63447] = {id=63447,name="Fear No Evil",level=1,requiredLevel=1,faction="alliance",expansion=8,zoneID=6170,mapID=37,description="Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.",objectivesText="Revive 4 Injured Stormwind Soldiers.",rewardItems={57256,57257,57258,131874},starts={{npcID=951}},ends={{npcID=951}},questType="standard"},
[63455] = {id=63455,name="Dead On Their Feet",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="As the Jailer twists the souls here to his will, there are still some that continue to resist him. I shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom! Bind the Zealous souls and build us an army!",objectivesText="Use the Cohesion Crystal to create bodies for 10 Defiant Souls .",rewardItems={184876},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=177076}},ends={{npcID=177072},{npcID=177685}},coords={x=0.336,y=0.548,source="quest_giver",zoneID=11400},questType="standard"},
[63479] = {id=63479,name="Summons from the Matriarch",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3487,mapID=110,description="Greetings, . Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.",objectivesText="Meet Lady Liadrin in Silvermoon.",rewardGold=25740,starts={{npcID=176789}},ends={{npcID=176796}},questType="standard"},
[63480] = {id=63480,name="Briefing",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3487,mapID=110,description="We haven't much time. The Scourge have attacked Tranquillien, and there's nothing to hold them back. We must take decisive action.",objectivesText="Listen to the briefing. Progress: We will find a way.",starts={{npcID=176796}},ends={{npcID=176796}},questType="standard"},
[63481] = {id=63481,name="Tranquillien Besieged",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=110,description="Rommath has opened the way for us to quickly travel to Tranquillien. I warn you, it's already a bloody battlefield. Take the portal, and I will be along right after you. And ... keep an eye on Salandria. She may have excelled in her training thus far, but she has yet to be tested like this.",objectivesText="Take the portal to Tranquillien.",rewardGold=25740,starts={{npcID=176796}},ends={{npcID=176826}},coords={x=0.898,y=0.374,source="quest_giver",zoneID=3487},questType="standard"},
[63482] = {id=63482,name="Death to the Scourge",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=95,description="I haven't seen Scourge mustering in numbers like this since... Never mind. There's no use dwelling in the past. Our first priority is thinning their numbers enough that we can find out what--or who--is really behind this attack. Slay as many of the undead as you can.",objectivesText="Slay Scourge in Tranquillien. Progress: Once we've thinned out the numbers of the Scourge, we can strike at Vorath in his lair.",rewardGold=257400,starts={{npcID=176826}},ends={{npcID=176826}},coords={x=0.484,y=0.32,source="quest_giver",zoneID=3433},questType="standard"},
[63483] = {id=63483,name="Magus Installation",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=95,description="This is no mindless strike... I have a strong suspicion that some powerful entity is manipulating the Scourge. Ever since the Helm of Domination was shattered, there has been a conceivable risk that someone else could exert their will and assume control over the undead--at least temporarily. Rommath and I can help defend Tranquillien, but we need to break those lines. Clear a spot for us. Let us see if we can draw out their leader.",objectivesText="Help Aethas and Rommath set up defenses in Tranquillien. Progress: Rommath and I are ready to help set up the wards, once you clear out a spot for us.",rewardGold=257400,starts={{npcID=176829}},ends={{npcID=176829}},coords={x=0.486,y=0.322,source="quest_giver",zoneID=3433},questType="standard"},
[63484] = {id=63484,name="A Knight's Weapon",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=95,description="It's clear that this san'layn has decided to use the Scourge to empower himself somehow. We can keep taking him out, but he will just keep coming back. We need a weapon that can break him for good. I think I have a solution. Upstairs, you will find a newly forged ranseur . It has yet to be tempered with magic--we will need to unlock its full potential. It will be our instrument of the Light.",objectivesText="Collect the Ranseur from upstairs in Tranquillien. Progress: Have you acquired the ranseur?",rewardGold=25740,rewardItems={184895},starts={{npcID=176826}},ends={{npcID=176826}},coords={x=0.484,y=0.32,source="quest_giver",zoneID=3433},questType="standard"},
[63485] = {id=63485,name="An Honest Heart",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=10534,mapID=95,description="If we are to defeat Vorath, we need to amplify the power of the ranseur. But we will not cut corners or impose our will to do it. That lesson has been learned. However, the kyrian of Bastion are masters of ushering souls to their proper places. Perhaps they would lend a fragment of their power to our cause. Go to Bastion , and find a way to empower the ranseur.",objectivesText="Travel to Agthia's Repose in Bastion .",rewardGold=25740,starts={{npcID=176826}},ends={{npcID=176930}},coords={x=0.484,y=0.32,source="quest_giver",zoneID=3433},questType="standard"},
[63486] = {id=63486,name="An Unbreakable Will",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=11462,mapID=95,description="We're clearly dealing with someone who is using terrible magic to suspend his own death. There's another force we know of that uses magic in this fashion. The Maldraxxi are intimately familiar with the trappings of death, and equally familiar with how to subvert it. Perhaps one of the Houses knows of a way to help us. Go there, and seek out power that can break this unnatural loop.",objectivesText="Travel to the Theater of Pain in Maldraxxus .",rewardGold=25740,starts={{npcID=176826}},ends={{npcID=176914}},coords={x=0.484,y=0.32,source="quest_giver",zoneID=3433},questType="standard"},
[63487] = {id=63487,name="Return to the Ghostlands",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=1536,description="Such power! Surely not even Vorath can withstand the might of this weapon now. We have what we came to the Shadowlands for. The ranseur is ready. Let's get back to Lady Liadrin in Tranquillien. I hope we're not too late to make a difference!",objectivesText="Return to Lady Liadrin in Tranquillien.",rewardGold=25740,starts={{npcID=176914},{npcID=176930}},ends={{npcID=176826}},coords={x=0.466,y=0.458,source="quest_giver",zoneID=11462},questType="standard"},
[63488] = {id=63488,name="I Am the Blade of the Light",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=95,description="It's time to put all that power and training into the field. Take the empowered ranseur, and cut a swath of destruction through the Scourge! We'll meet you at the doorstep of Deatholme.",objectivesText="Use the empowered ranseur to slay Scourge in the Dead Scar.",rewardGold=257400,starts={{npcID=176826}},ends={{npcID=176882}},coords={x=0.484,y=0.32,source="quest_giver",zoneID=3433},questType="standard"},
[63489] = {id=63489,name="Justice Long Overdue",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3433,mapID=95,description="You made short work of the Scourge in the Dead Scar, but we've a bigger target to face. It's time to test the mettle of your weapon against Vorath . Let us finish this, together.",objectivesText="Slay Vorath . Progress: We will protect our homeland.",rewardGold=514800,rewardItems={191604},starts={{npcID=176882}},ends={{npcID=176882}},coords={x=0.356,y=0.728,source="quest_giver",zoneID=3433},questType="standard"},
[63490] = {id=63490,name="Blood Knight",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=3487,mapID=95,description="The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you. Meet me back in Silvermoon. Your efforts and heroism today will not go unrecognized.",objectivesText="Receive accolades from Lady Liadrin in Silvermoon City.",rewardGold=25740,rewardItems={191566},starts={{npcID=176882}},ends={{npcID=176796}},coords={x=0.356,y=0.728,source="quest_giver",zoneID=3433},questType="standard"},
[63494] = {id=63494,name="The Anvil-Thane's Designs",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,mapID=84,description="I see you eyein' our weapons here. Wouldnae ye know, I forged them myself! So far, I've got designs for a staff, a one-handed axe, and a shield... I could make ye some, if you'd like! O' course, that's what I'd normally say. Unfortunately I lost the designs in a bet down at the Grim Guzzler. If ye could get them back, as well as gather the materials, I'd be happy to forge ye some weapons!",rewardGold=31200,rewardXP=850,starts={{npcID=144154}},ends={{npcID=176828}},coords={x=0.57,y=0.318,source="quest_giver",mapID=84},questType="standard"},
[63498] = {id=63498,name="Brawl or Brew",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,description="Ach, Thurgaden sent ye did he? Ye'd think the Anvil-Thane would be made o' tougher stuff than the rest of this drunken lot, but I guess I was mistaken! If ye want tae win back his designs, yer gonna have tae win 'em fair and square. I've only got one question left fer ye. Brawl? Or Brew?",objectivesText="Defeat Strongarm Jarden in one of her competitions. Progress: Not a single dwarf in 'ere has beaten me. What makes ye different?",rewardGold=341600,rewardXP=6815,rewardItems={184894},starts={{npcID=176828}},ends={{npcID=176828}},coords={x=0.516,y=0.33,source="quest_giver",zoneID=1584},questType="standard"},
[63501] = {id=63501,name="It's Called Borrowing",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,mapID=84,description="Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself. Two notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>",objectivesText="Find 5 Darkforged Ingot , a Boiling Flamecore , and the Flamepoint Engraver around Shadowforge City. Progress: <Thurgaden is mumbling and cursing under his breath about how he will defeat Jarden in their next competition.>",rewardGold=341600,rewardXP=6815,rewardItems={184915,184916,184917},ends={{npcID=144154}},questType="standard"},
[63502] = {id=63502,name="Weapons o' the Dark Iron",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,description="One step left, friend. Lend me a hand in my craftin', then you'll have yer hands on the most powerful weapons forged in the deepest fires of Blackrock Mountain!",objectivesText="Aid Anvil-Thane Thurgaden in crafting your new weapons. Progress: These weapons shall rival even my own!",rewardGold=309800,rewardXP=6815,rewardItems={184922},starts={{npcID=144154}},ends={{npcID=144154}},coords={x=0.57,y=0.318,source="quest_giver",zoneID=1584},questType="standard"},
[63519] = {id=63519,name="Unfair Fight",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=11462,mapID=1536,description="A cowardly pest that cheats his way out of the glory of death? Bah! I have something that'll cut him down where he stands. But such an enhancement requires one who is strong enough to wield it properly. Show me your mettle and fight! If you can prove yourself, I'll empower that ranseur of yours.",objectivesText="Prove your strength to Fightlord San .",rewardGold=257400,starts={{npcID=176915}},ends={{npcID=176915}},coords={x=0.466,y=0.458,source="quest_giver",zoneID=11462},questType="standard"},
[63522] = {id=63522,name="A Fair Race",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=10534,mapID=1533,description="A soul that refuses to cross the veil is a problem we kyrian are familiar with. I can help you. But before I grant your weapon this power, I must know that you will not abuse it, and that your heart is true. Let us run a race. Along the course, ring the bells. If your heart is pure, they will aid your speed. You must have at least five bells recently rung in order to complete the race. Do not be distracted by shortcuts. And do not try to cheat to get ahead, it will not work. Are you ready?",objectivesText="Run an honest race with Vandellor .",rewardGold=257400,starts={{npcID=176932}},ends={{npcID=176932}},coords={x=0.45,y=0.688,source="quest_giver",zoneID=10534},questType="standard"},
[63543] = {id=63543,name="Necrolord Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!",rewardItems={185720,185992,186103,186557,186600,186602,186603,186604,187011,187015,187021,187023,187026,187240},questType="world",db2Objectives={{orderIndex=1,type=14,amount=1,objectID=92362,text="Help Maldraxxi forces assault Perdition Hold"},{orderIndex=3,type=0,amount=1,objectID=177532,text="Advance to the Altar of Domination"},{orderIndex=0,type=0,amount=1,objectID=177674,text="Report to Draka at the gates of Perdition Hold"},{orderIndex=2,type=0,amount=1,objectID=177290,text="Use Draka's Battlehorn to signal the advance"}},worldTaskTitle="Necrolord Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63545] = {id=63545,name="Putting A Plan Together",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions. The remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault. See if you can locate the parts we need to build a new Centurion.",objectivesText="Deliver 3 Centurion Parts and 15 Automaton Bolts to Mikanikos Progress: Have you found the parts I requested?",rewardItems={184513,185685},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177175}},ends={{npcID=177175}},coords={x=0.37,y=0.634,source="quest_giver",zoneID=11400},questType="standard"},
[63576] = {id=63576,name="The First Move",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion. Polemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive. Make haste. I fear that time grows short.",objectivesText="Speak with Polemarch Adrestes in Oribos . Progress: We will continue to fight.",rewardGold=25740,rewardXP=1020,questType="standard"},
[63578] = {id=63578,name="The Battle of Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="With the betrayal of Sire Denathrius, and the absence of the Primus of Maldraxxus, we must assume that the Winter Queen is the Jailer's next target. And we won't let anyone take her sigil! Ardenweald has endured much, but it is a realm of great and mysterious power. Things aren't always what they seem. We'll use this to our advantage, no matter who comes for the Queen!",objectivesText="Protect the Winter Queen's sigil in the Battle of Ardenweald.",rewardGold=772200,rewardXP=12250,rewardItems={179498,179511,179515,179531,179536,179546,179564,179583,182322,182323},rewardChoices={179511,179515,179531,179536,179546,179564,182322,182323},rewardCurrencies={{id=1822,amount=2}},starts={{npcID=177141}},ends={{npcID=177148}},questType="standard"},
[63579] = {id=63579,name="A Paladin's Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13575,mapID=1961,description="Bolvar Fordragon has seen visions of a vault hidden deep within Torghast where the Jailer keeps souls he deems valuable. Uther was struck down by a mourneblade. When such a weapon is wielded with rage, it can shatter a soul into fragments. If the Jailer holds a part of Uther's soul, it cannot be fully mended until the lost piece is restored. Take this attuned shard to Torghast, $p. It should guide you to the vault's location. Find the lost fragment of Uther's soul so that he can be made whole.",objectivesText="Reclaim the Remnant of Justice from the Ossuary of the Banished in Torghast. Progress: Greetings Maw Walker. Your arrival is fortuitous.",rewardGold=257400,rewardXP=8165,rewardItems={185679,185680},starts={{npcID=179356}},ends={{npcID=154629}},coords={x=0.628,y=0.254,source="quest_giver",zoneID=13570},questType="standard"},
[63580] = {id=63580,name="Wounded Memories",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The arrival of Uther's wounded soul was the impetus for many events that led us to our current struggles. Devos's broken trust. Her involvement with Helya. The rise of the Forsworn. Bastion needs to change, but we struggle to find a solution. Perhaps this soul fragment will provide valuable insight.",objectivesText="Help Uther forge a connection to the Remnant of Justice. Progress: I have never seen a soul torn as Uther's has been.",rewardGold=128700,rewardXP=4085,starts={{npcID=177116}},ends={{npcID=154629}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63581] = {id=63581,name="Step Into the Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8556,mapID=1533,description="It is as I feared. This fragment of Uther's soul was darkened by the mourneblade that slew him. His memories are shattered and twisted. For Uther to move past his pain, to move past his grief, he must experience his past once again. But he does not have to do this alone. Using my soul mirror, we can aid Uther in walking through these memories. He can then come to terms with the emotions they contain. We must help him see past the distortions and understand the truths they hold.",objectivesText="Use the Soul Mirror to aid Uther in reliving his past. Progress: We can learn from this.",rewardGold=257400,rewardXP=8165,starts={{npcID=154629}},ends={{npcID=177116}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63582] = {id=63582,name="He Was My Student",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=1519,mapID=1533,description="Uther's memories of this Prince Arthas haunt him deeply. He is the reason Uther's soul was fragmented, why Devos fell the way she did. The pain in these memories is palpable. We have to dig deeper. Uther must face the source of this darkness. Once again, you need to enter his past to protect his future.",objectivesText="Aid Uther in reliving his second memory. Progress: Uther needs our support.",rewardGold=257400,rewardXP=8165,starts={{npcID=177116}},ends={{npcID=177123}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63583] = {id=63583,name="I Intend to Live Forever",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=28,mapID=1533,description="Please, . I am not finished. There is one more memory that I must see. One more that must be faced. It... it will not be easy. I will need support from all of you. But it must be done.",objectivesText="Aid Uther in reliving his final memory. Progress: <Adrestes is deep in thought.>",rewardGold=257400,rewardXP=8165,starts={{npcID=180733}},ends={{npcID=177116}},coords={x=0.402,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[63584] = {id=63584,name="A Triumphant Return",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="This temple represents a new dawn for Bastion, . The Temple of Devotion will stand as a place of fellowship. We will work with the Forsworn, as well as aspirants and kyrian of all experience and backgrounds, to forge a future of which all can be proud. Let us return to Elysian Hold. I request that you join us for a momentous occasion--the ascension of a new Paragon and the creation of a new sigil.",objectivesText="Meet Kalisthene at Elysian Hold. The Kyrian Courier can provide a flight.",rewardGold=25740,rewardXP=1020,starts={{npcID=177116}},ends={{npcID=168517}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63585] = {id=63585,name="Blind Loyalty",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="The path forward for the kyrian is clear to me now. First we will speak with Nikolon. I urge you to stay and listen. Afterward, we must return to Elysian Hold. There I will request an audience with the Archon, and I need you all by my side as I do so.",objectivesText="Join Polemarch Adrestes at Elysian Hold for an audience with the Archon. Progress: The kyrian must forge a new path.",rewardGold=25740,rewardXP=1020,starts={{npcID=177116}},ends={{npcID=160037}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63586] = {id=63586,name="Compassion in Devotion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="Our first order of business is to rededicate the Temple of Loyalty. Pelagos has volunteered to stay here and help prepare for the ceremony. I requested that Nikolon bring his companions to meet us at Steward's Rest, to aid us in convincing some of the Forsworn of our new path. Meet us there when you are able.",objectivesText="Meet Adrestes at Steward's Rest.",rewardGold=25740,rewardXP=1020,starts={{npcID=160037}},ends={{npcID=177116}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="standard"},
[63587] = {id=63587,name="Reclaimable Anima",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Mikanikos has explained much about Forsworn centurions to me, . I cannot say that I understood all of it, but it seems he has not yet found a reliable way to return them to their proper operating standards. Their anima can still be useful, though! Adrestes has focused on how to rededicate the temple, but not on his own safety. I worry the process will drain much of his anima. If you can reclaim cores from the Forsworn centurions, we can use them as anima stores for Adrestes.",objectivesText="Collect 5 Tainted Centurion Cores from Forsworn centurions. Progress: I've been working with Mikanikos on methods to reuse anima from Forsworn centurions. I can handle this!",rewardGold=257400,rewardXP=8165,rewardItems={185853},starts={{npcID=177123}},ends={{npcID=177123}},coords={x=0.402,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[63588] = {id=63588,name="Rebuilding Faith",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The Forsworn are lost, . They are like ghosts, haunting the Temple of Loyalty. Nowhere else to go. Leaderless, purposeless, abandoned. We must show them that there is a path forward. Let me accompany you into the temple. Allow me to talk to them, speak to their sensibilities. Perhaps we can convince them to give Adrestes's new path a chance.",objectivesText="Convince 10 Forsworn to return to the Path. Progress: The Forsworn may have abandoned the Path, but we had good reason.",rewardGold=257400,rewardXP=8165,starts={{npcID=177300}},ends={{npcID=177978}},coords={x=0.244,y=0.3,source="quest_giver",zoneID=10534},questType="standard"},
[63589] = {id=63589,name="Directing Dedication",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="The five temples of Bastion have stood strong since its very creation. The idea of rededicating one has never been broached before, and will no doubt require a significant amount of anima. Underneath this temple are stores of anima we rationed for the drought. Now that anima is returning, we can use these reserves for our purposes. You will need to use channelers and collectors throughout the grounds to redirect anima to the top. That should give me the power I need.",objectivesText="Redirect anima from the Citadel of Loyalty to the temple. Progress: We endeavor to perform a monumental feat, one that has never been attempted before.",rewardGold=257400,rewardXP=8165,starts={{npcID=177116}},ends={{npcID=177116}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63590] = {id=63590,name="The Vesper Rings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Loyalty shall no longer be a demanded tenet of the Path, but rather a virtue that is earned. A choice. We must show devotion to those who struggle, whether they are recently arrived souls or peers who need our aid. It will take all the anima at hand to rededicate this temple. And in so doing, to ring in a new age for the kyrian. I fear the Mawsworn may attempt to thwart our plans. Protect me during this ritual, . We must see this through.",objectivesText="Protect Polemarch Adrestes as he rededicates the Temple of Loyalty. Progress: <Adrestes cannot be distracted as he uses every ounce of himself for the task at hand.>",rewardGold=257400,rewardXP=8165,starts={{npcID=177116}},ends={{npcID=177116}},coords={x=0.4,y=0.2,source="quest_giver",zoneID=10534},questType="standard"},
[63591] = {id=63591,name="The Grand Reception",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13699,mapID=2017,description=", you have aided the kyrian in the most trying of times. Your devotion to our cause has helped usher in a new beginning for all of us. We would be honored if you would join us for a gathering prior to the ceremony. Many members of our covenant wish to express their appreciation for all you have done. This is a day of great joy. I am so pleased that you are here to witness it!",objectivesText="Speak to Kalisthene to attend the gathering, then mingle with your soulbinds and the other kyrian.",rewardGold=25740,rewardXP=1020,starts={{npcID=168517}},ends={{npcID=180189}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="standard"},
[63592] = {id=63592,name="The New Path",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13699,mapID=1695,description="Today, a new paragon is anointed. And for the first time since the dawn of our realm, a temple is rededicated to represent our devotion to one another. A new paragon, a new sigil, and a new path for all kyrian. This ceremony shall be glorious indeed!",objectivesText="Speak to Kalisthene to take part in the ceremony at the Seat of the Archon.",rewardGold=257400,rewardXP=8165,rewardItems={181743},starts={{npcID=168517},{npcID=180189}},ends={{npcID=179379}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="standard"},
[63593] = {id=63593,name="New Sigil of the Kyrian",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="With a future of kinship and devotion secured for Bastion, a new sigil is born to represent our path forward. Please report all that you have done to the Primus . When he is ready, we will deliver the sigil to him. Let us hope he can use it to thwart the Jailer's plan and save the Shadowlands.",objectivesText="Report back to the Primus in Korthia .",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=179379}},ends={{npcID=177194}},coords={x=0.594,y=0.316,source="quest_giver",zoneID=11012},questType="standard"},
[63594] = {id=63594,name="Clearing the Walls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="<This scroll shows the locations of a series of pylons, that protect Perdition Hold from assault. Destroying these Pylons could aid in the success of our attack>",objectivesText="Use the Overcharged Champion to destroy 6 Deadsoul Pylons along the walls of Perdition Hold. Progress: Have you cleared the walls?",rewardGold=257400,rewardXP=8165,rewardItems={186601},rewardCurrencies={{id=1767,amount=400},{id=1880,amount=175}},ends={{npcID=177175}},coords={mapID=1543,source="quest_giver",x=0.3975,y=0.5425},questType="standard"},
[63603] = {id=63603,name="Yak Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Yak Soul is cordial and resilient. The shape of the yak will be yours to call upon.>",objectivesText="Bring the Yak Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63604] = {id=63604,name="Shoveltusk Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Shoveltusk Soul is protective and determined. The shape of the shoveltusk will be yours to call upon.>",objectivesText="Bring the Shoveltusk Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63605] = {id=63605,name="Saurolisk Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Saurolisk Soul is agile and clever. The shape of the saurolisk will be yours to call upon.>",objectivesText="Bring the Saurolisk Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63606] = {id=63606,name="Spider Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Spider Soul is nimble and cunning. The shape of the spider will be yours to call upon.>",objectivesText="Bring the Spider Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63607] = {id=63607,name="Direhorn Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Direhorn Soul is brutal and tenacious. The shape of the direhorn will be yours to call upon.>",objectivesText="Bring the Direhorn Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63608] = {id=63608,name="Hippo Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Hippo Soul is ferocious. The shape of the hippo will be yours to call upon.>",objectivesText="Bring the Hippo Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63609] = {id=63609,name="Kodo Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Kodo Soul is calm and loyal. The shape of the kodo will be yours to call upon.>",objectivesText="Bring the Kodo Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63610] = {id=63610,name="Mammoth Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Mammoth Soul is brave and protective. The shape of the mammoth will be yours to call upon.>",objectivesText="Bring the Mammoth Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[63612] = {id=63612,name="The Chains of Command",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1961,description="If we must hold a position so near to the Jailer's lands, we need to provide some assurances. Vyraz and Helya have retreated within the walls of Desmotaeron. They have grown lax in their expected safety, which provides us with an opportunity. We will take them by surprise. Strike swiftly and without mercy, and perhaps we can cut the heads off those snakes.",objectivesText="Meet Draka near Desmotaeron.",rewardGold=25740,rewardXP=1020,starts={{npcID=177194}},ends={{npcID=177560}},coords={x=0.628,y=0.262,source="quest_giver",zoneID=13570},questType="standard"},
[63613] = {id=63613,name="Gates of the Damned",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="We need to prepare for the assault before we signal Zerekriss. Once it is in place, our allies will use death gates to assault the area. We will need to summon the death gates on this side. Find strategic locations for them.",objectivesText="Summon 4 Death Gates. Progress: Once we have all of these death gates summoned, then the real fight can begin.",rewardGold=257400,rewardXP=8165,starts={{npcID=177560}},ends={{npcID=177560}},coords={x=0.628,y=0.66,source="quest_giver",zoneID=11400},questType="standard"},
[63614] = {id=63614,name="Weapon in Hand",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="A moment, <name>. I threw my axe Dra'gora at Helya during our first encounter in the Maw, and I haven't seen it since. If this is truly where she commands her forces, then perhaps it's held here. I crafted that weapon in Nagrand, and it reminds me of many good days spent beside my family there. I want to feel its weight in my hands once again.",objectivesText="Find Thrall's axe, Dra'gora . Progress: I threw my axe in the heat of the moment...",rewardItems={185772},starts={{npcID=177589}},ends={{npcID=177589}},questType="standard"},
[63615] = {id=63615,name="Clip Their Wings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="The skies are dark with Helya's kyrian followers. If we do not thin their numbers, Zerekriss and our aerial allies may have difficulties pushing forward. I've noticed that the Mawsworn often use magical chains. We could turn their equipment against them and tear them down from the sky.",objectivesText="Use Mawsworn Chains to kill 6 Helsworn Soulbreakers . Progress: We need to clear out the skies before we can begin the real assault.",rewardGold=257400,rewardXP=8165,rewardItems={185742},starts={{npcID=177586}},ends={{npcID=177586}},questType="standard"},
[63616] = {id=63616,name="A Job Done Right",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="We should be clear to start the assault. Signal the Zerekriss. Let us show them the might of a Maldraxxian necropolis and the combined armies of the Shadowlands!",objectivesText="Signal the Zerekriss and start the assault. Progress: Nothing can stand against the might of Maldraxxus!",rewardGold=257400,rewardXP=8165,starts={{npcID=177586}},questType="standard"},
[63617] = {id=63617,name="Bending Bars",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="In all the chaos, the gates of the upper hold have been left open. If we slip through, they might not even notice us until it is too late. One of Helya's lieutenants stands between us and Helgarde Keep. End them.",objectivesText="Slay Ironkeeper Salryx . Progress: We need to get through that gate.",starts={{npcID=177586}},ends={{npcID=177586}},questType="standard"},
[63618] = {id=63618,name="What Maldraxxus Does Best",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Every enemy we vanquish here is one our army does not have to contend with. We will make sure they will not soon forget the true purpose of Maldraxxus. Show them what happens to those we deem a threat towards the Shadowlands. Kill every Mawsworn in sight.",objectivesText="Slay 10 Mawsworn in upper Desmotaeron. Progress: Each Mawsworn we defeat is one less that will bother our forces in Korthia .",rewardGold=257400,rewardXP=8165,starts={{npcID=177586}},ends={{npcID=177586}},questType="standard"},
[63619] = {id=63619,name="Forsworn and Forgotten",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Wait... I know you! The Maw Walker! My brothers and sisters have been twisted... tainted. Some took power willingly from Helya, but others resisted. Now all of us are forced to submit to her power. I escaped when the fighting started, but most of the remaining Forsworn are being subjected to horrific rituals. Please, I beg you to free them. Then we will return to Bastion and submit to the Archon's judgment.",objectivesText="Free 5 Forsworn Prisoners .",rewardGold=257400,rewardXP=8165,starts={{npcID=177288}},ends={{npcID=177288}},coords={x=0.656,y=0.462,source="quest_giver",zoneID=11400},questType="standard"},
[63620] = {id=63620,name="A Traitor's Due",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Vyraz has been a constant thorn in Maldraxxus's side since he betrayed us. As Baroness of the House of the Chosen, it is my duty to see this threat eliminated... and the murder of Margrave Krexus avenged. As the Primus said, we must remove the head from this snake. The time to strike is now!",objectivesText="Kill Vyraz. Progress: Vyraz is a stain upon Maldraxxus as long as he still draws breath.",rewardGold=514800,rewardXP=10205,starts={{npcID=177586}},ends={{npcID=178103}},questType="standard"},
[63621] = {id=63621,name="Pulling His Chain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="They call this one the Keeper of Chains . Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position. I need you to eliminate this threat, Maw Walker, before it moves against our forces.",objectivesText="Eliminate the Keeper of Chains . Progress: Have you eliminated this threat?",rewardItems={184513},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177226}},ends={{npcID=177226}},coords={x=0.37,y=0.632,source="quest_giver",zoneID=11400},questType="group"},
[63622] = {id=63622,name="Victory in Our Name",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="With Helya and Vyraz taken care of, we have achieved a major victory against the Mawsworn today. It is also a showing of what the combined might of the Shadowlands looks like. We should return to Korthia before something else arises.",objectivesText="Return to the Primus at Korthia . Progress: We have struck a blow against the Jailer's forces. Take your time to recover before the next strike.",rewardGold=25740,rewardXP=1020,rewardItems={181648},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=178103}},ends={{npcID=177194}},coords={x=0.618,y=0.414,source="quest_giver",zoneID=11400},questType="standard"},
[63623] = {id=63623,name="Filling an Empty Throne",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1961,description="Maw Walker. In my long absence, you have done much to bring order and strength back to the necrolord covenant. In recognition, I invite you to witness a ceremony. Return with me to my seat of power in Maldraxxus. It is time I rewarded one who was most loyal to our cause.",objectivesText="Return to the Seat of the Primus .",rewardGold=25740,rewardXP=1020,starts={{npcID=177194}},ends={{npcID=177975}},coords={x=0.628,y=0.262,source="quest_giver",zoneID=13570},questType="standard"},
[63624] = {id=63624,name="The Roads We Walk",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The armies of Maldraxxus are strong. They will recover from Vyraz's transgression. The first thing we must do is rebuild. Maw Walker, stand witness to a new era for Maldraxxus!",objectivesText="Witness Draka's promotion ceremony. Progress: Did you speak with each of our leaders? The army has much to celebrate.",rewardGold=25740,rewardXP=1020,starts={{npcID=177975}},ends={{npcID=177975}},coords={x=0.49,y=0.5,source="quest_giver",zoneID=12876},questType="standard"},
[63625] = {id=63625,name="Here's an Axe, Get to Work!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Our troops are meeting stiff resistance! Maw Walker, grab a weapon and take the fight to them! Eliminate the Mawsworn forces and their commander defending these gates.",objectivesText="Eliminate 15 Mawsworn forces and Commander Mallamort .",rewardItems={184513},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=177072}},ends={{npcID=177685}},coords={x=0.338,y=0.548,source="quest_giver",zoneID=11400},questType="standard"},
[63638] = {id=63638,name="Can't Turn Our Backs",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="That's Sylvanas and her Mawsworn dealt with... for now. But we need to hurry and make sure that the Queen and her sigil are safe! The Winter Queen was just outside the Heart of the Forest, protecting the stolen wildseeds from the Maw.",objectivesText="Check on the Winter Queen . Progress: The forest answers.",rewardGold=25740,rewardXP=1020,starts={{npcID=177148}},ends={{npcID=177460}},coords={x=0.486,y=0.432,source="quest_giver",zoneID=11510},questType="standard"},
[63639] = {id=63639,name="Report to Oribos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1565,description="Ardenweald has withstood the unrelenting force of the Maw. But it was still not enough. Return to our allies in Oribos. There must be an answer for this loss, and action taken.",objectivesText="Return to Tal-Inara in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=177460}},ends={{npcID=177460}},coords={x=0.47,y=0.486,source="quest_giver",zoneID=11510},questType="standard"},
[63644] = {id=63644,name="Dread Tidings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1961,description="The threat the nathrezim pose to our forces must not be underestimated. They are cunning, rivaling the best veterans of the House of Eyes, and we do not know their full plan. Among the venthyr there is one whose wrath scourged the nathrezim from the Shadowlands for many thousands of years. I ask you travel to Sinfall, seek out Prince Renathal , and deliver to him this missive. I shall send one of my own spies, the Baroness Vashj , to meet you there. Make use of her experience with the nathrezim.",objectivesText="Speak with Prince Renathal at Dawnkeep in Revendreth. Progress: Dread tidings indeed.",rewardGold=128700,rewardXP=4085,rewardItems={185762},starts={{npcID=177194}},ends={{npcID=168898}},coords={x=0.628,y=0.262,source="quest_giver",zoneID=13570},questType="standard"},
[63645] = {id=63645,name="The Dawnkeep Prisoner",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh, you have not heard the news yet. We have him. Sire Denathrius, Master of Revendreth, imprisoned within his own blade. We managed to best him during one of our recent raids of Castle Nathria. It took an army of unparalleled valor and preparation. It took skill and wealth. It took a miracle. And so the redeemer shall be redeemed. Would you like to know more?",objectivesText="Learn of Sire Denathrius' fate from Prince Renathal . Progress: Never underestimate bravery when it is backed by weapons and armor of legendary make.",rewardGold=25740,rewardXP=1020,starts={{npcID=168898}},ends={{npcID=168898}},coords={x=0.23,y=0.438,source="quest_giver",zoneID=10413},questType="standard"},
[63646] = {id=63646,name="Convoy of the Covenants",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="A new sigil for the Venthyr would require all seven medallions to forge. The Primus was correct. The person we need is the Stonewright . Her grievances against the Unseen could fill a library and she holds the last of the medallions we need. I believe you and I are long overdue in convincing her to join our cause. I will make the arrangements. We shall go properly this time, with gifts and diplomacy. You should warn Chelra, she will want to arrange an escort.",objectivesText="Gather the Envoys and ride to Dominance Gate. Progress: What do you bring me, Maw Walker? Be advised I have no patience for deception and am not above feeding messengers to the gargons.",rewardGold=128700,rewardXP=4085,rewardItems={185762},starts={{npcID=168898}},ends={{npcID=165866}},coords={x=0.23,y=0.438,source="quest_giver",zoneID=10413},questType="standard"},
[63647] = {id=63647,name="The Unseen Guests",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Dreadlords. Of course. Of course they would come back now of all times. I half suspected they returned during the drought. I was not entirely convinced you were not one, the first time I saw you. They have gotten more clever over the eons since they fled Revendreth. But not clever enough... I think. Come, Maw Walker. Follow me and do not make a fuss. Keep your weapon ready. The envoy you brought is not as well intentioned as you might have thought.",objectivesText="Join the Stonewright as she investigates the Envoy.",rewardGold=128700,rewardXP=4085,starts={{npcID=165866}},ends={{npcID=165866}},coords={x=0.342,y=0.22,source="quest_giver",zoneID=10413},questType="standard"},
[63648] = {id=63648,name="Nal'ragas",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Stonewright's medallion must not stay in the hands of the nathrezim. From what the Accuser explained of our mission, the medallion is required if we wish to forge a new sigil for the Venthyr. I have no doubt that is why Nal'ragas and her ilk executed their ambush now. The medallions are not subtle magic, and their affect on this realm is easily tracked. I suggest we give chase and eliminate this Nal'ragas before she can be reinforced.",objectivesText="Track down and defeat Nal'ragas .",rewardGold=257400,rewardXP=8165,starts={{npcID=177628}},ends={{npcID=177644}},questType="standard"},
[63649] = {id=63649,name="Spy vs Spy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1525,description="Nathrezim. Dreadlords. The Unseen Guests. Call them what you will, they are a race that was crafted to be the greatest collection of spies and infiltrators in all of reality, once upon a time. Their intrusion has underestimated three things. Kael'thas Sunstrider, Baroness Vashj, and ! I have brought a tool Kael'thas and I used to detect nathrezim when we served under Illidan. And I am the matron of spies! Let us hunt these intruders down.",objectivesText="Track down and defeat 5 Dreadlord Infiltrators . Progress: Who says death is without its little pleasures.",rewardGold=257400,rewardXP=8165,rewardItems={185734},starts={{npcID=177637}},ends={{npcID=177637}},questType="standard"},
[63650] = {id=63650,name="De-Infiltration",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Mal'Ganis. It has been many ages since I have said his name. And now I find we must hunt him down. If he has the Medallion of Wrath then there is nowhere he can hide. We can use the other medallions we have recovered to locate him. Join me in Sinfall and bring your dreadlord hunting party. I suspect we will have need of them.",objectivesText="Meet Prince Renathal in Sinfall.",rewardGold=128700,rewardXP=4085,starts={{npcID=177644}},ends={{npcID=158653}},coords={x=0.25,y=0.278,source="quest_giver",zoneID=10413},questType="standard"},
[63651] = {id=63651,name="Cryptograms",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="If the nathrezim have infiltrated Sinfall they will be communicating, and not just through hand gestures or spoken words. They like to use magical written messages concealed by a simple cantrip, invisible to the average observer. However, I have developed an incantation that should allow you to see these messages. Find these cryptograms and bring me their contents. I can translate them if they are beyond your understanding.",objectivesText="Transcribe 10 Infernal Cryptograms . Progress: If the nathrezim have a flaw it is that they assume they are the only ones who get better over time.",rewardGold=257400,rewardXP=8165,rewardItems={185917,185918},starts={{npcID=178260}},ends={{npcID=178260}},coords={x=0.544,y=0.396,source="quest_giver",zoneID=10986},questType="standard"},
[63652] = {id=63652,name="The \"Unwelcome\" Guests",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Chelra, I mean Nal'ragas, would not have been working alone. We must assume the worst, that not all of our friends and allies are who they seem to be. It will take time for the Court of Harvesters to render our detection ritual. While we do so we will be exposed. I ask that you use the techniques you employed at Dominance Gate within Sinfall to root out any nathrezim within our ranks. Good hunting.",objectivesText="Eliminate 3 nathrezim inside Sinfall.",rewardGold=257400,rewardXP=8165,rewardItems={185734},starts={{npcID=158653}},ends={{npcID=158653}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[63653] = {id=63653,name="The Power of a Crown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We are ready. The Court of Harvesters shall use the power of the medallions we have gathered thus far to locate the Medallion of Wrath. So long as they have not removed it from the realm we should be able to divine its presence. This is not an easy ritual--the nathrezim specialize in avoiding detection. When you see the path, take it and move with speed. And when you find them, wait for us before you engage.",objectivesText="Track the path to the Medallion of Wrath.",rewardGold=257400,rewardXP=8165,starts={{npcID=158653}},ends={{npcID=178337}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="standard"},
[63654] = {id=63654,name="The Nathrezim",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Medallion of Wrath is more than just a powerful artifact. In the hands of a nathrezim it could be used to shape this realm to their dark purpose. What is more, while they hold it we are denied the ability to forge a new sigil. They already nearly destroyed the Ember Ward with their reckless schemes. I will not have my medallion used for their ends. Come, let us get it back.",objectivesText="Recover the Medallion of Wrath from the nathrezim.",rewardGold=514800,rewardXP=10205,rewardItems={181549},starts={{npcID=178337}},ends={{npcID=178413}},coords={x=0.252,y=0.45,source="quest_giver",zoneID=10413},questType="standard"},
[63655] = {id=63655,name="Medallion of Wrath",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Maw Walker. I will march with my stoneborn into the depths of the Maw and rend the head off every nathrezim I find there. However, Revendreth is still too strategic in this war to lose out of misplaced vanity. Therefore, as Harvester of Wrath, the second of that title, I offer you my medallion for safe keeping and utilization while I wage this war. Use it to empower the Harvesters so they can prevent Denathrius from simply returning and regaining control with a snap of his fingers.",objectivesText="Bring the Medallion of Wrath to the dais in Sinfall. Progress: <The platform surges with power as it feels the proximity of the medallion.>",rewardGold=128700,rewardXP=4085,rewardItems={187124},starts={{npcID=179978}},ends={{npcID=353953}},coords={x=0.23,y=0.458,source="quest_giver",zoneID=10413},questType="standard"},
[63656] = {id=63656,name="The Meaning of Wrath",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1525,description="I will gather my forces and dispense a portion to Korthia immediately. I will also see to it that they are provided the tools Baroness Vashj and Kael'thas were able to conjure so that we might further defend against nathrezim incursions. Other duties require my attention before I can descend on Korthia . I must secure Dominance Keep against further infiltrators. I suppose the Primus will want an update. You may tell him you were successful.",objectivesText="Report to the Primus .",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=179978}},ends={{npcID=177194}},coords={x=0.23,y=0.458,source="quest_giver",zoneID=10413},questType="standard"},
[63659] = {id=63659,name="Dreadlords!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="This is the fifth dreadlord I have found infiltrating our forces this week. Unchecked they can cause tremendous damage to our foothold here. In life I learned how to identify these creatures from a demon hunter. It makes it far easier for me to locate them, but I cannot be in all places at once. We must report these findings to the Primus .",objectivesText="Speak with the Primus in Korthia .",rewardGold=25740,rewardXP=1020,starts={{npcID=177167}},ends={{npcID=177194}},coords={x=0.606,y=0.278,source="quest_giver",zoneID=13570},questType="standard"},
[63660] = {id=63660,name="Opening the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="The Jailer has gained another sigil, and his forces actively assault Oribos . Bolvar Fordragon and Draka of Maldraxxus suggest taking the fight to the Jailer. To do so, we need a way for their forces to safely come and go from the Maw. This was considered impossible before you arrived, but now I believe we have a chance. I must examine your anima to see if this is truly what the Purpose wills.",objectivesText="Allow Tal-Inara to examine your anima. Progress: I do not do this lightly, Maw Walker.",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63661] = {id=63661,name="Link to the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Fatescribe is certain that a second waystone has emerged in the Maw. It falls to you to locate it. I will create an anchor here in Oribos that links to your anima. Once you attune yourself to the waystone, this anchor will be bound to it. If you are successful, the covenants will be able to send their forces inside and safely leave the Maw again. Use what resources you have within the Maw to find this waystone. Good luck, mortal. May the Purpose guide us all.",objectivesText="Ask Ve'nari about the location of a second waystone. Progress: You have that look about you, Maw Walker. The one that tells me you are about to ask for my help.",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=162804}},questType="standard"},
[63662] = {id=63662,name="Mysteries of the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="The Maw is changing, mortal. And with change comes opportunity. The Jailer has pulled a realm that was hidden deep within the Shadowlands into the Maw. It is a location of some interest to me, but I do not wish to approach it alone. The Mawsworn are swarming the area, you see. There must be something of value that they seek. I have a safe enclave nearby. Accompany me there and I may be able to help you find that waystone you're looking for. Do we have a deal?",objectivesText="Travel with Ve'nari to the site of the new landmass within the Maw",rewardGold=257400,rewardXP=8165,starts={{npcID=162804}},ends={{npcID=177202}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[63663] = {id=63663,name="Korthia, the City of Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We are on the threshold of attaining our desires, Maw Walker. Your grand waystone cannot be far off. Of course, my needs are much more modest. A bit of useful information here, a priceless relic there... I will survey the area to see if there is anything useful--or hazardous--nearby. Then we can proceed.",objectivesText="Have Ve'nari scan the area, then investigate whatever is found.",rewardGold=128700,rewardXP=4085,starts={{npcID=177202}},ends={{npcID=177227}},coords={x=0.584,y=0.144,source="quest_giver",zoneID=13570},questType="standard"},
[63664] = {id=63664,name="Get to the Point",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Our position near the bridge to the Altar of Domination is under heavy attack! We can not afford to lose the ballista we have set up there. Maw Walker, I need you to defend that position till our troops can push forward!",objectivesText="Defend the forward position inside Perdition Hold. Progress: Is our position safe?",rewardGold=257400,rewardXP=8165,rewardItems={180896,181501,181502,181625,181647,181649,181651,181652,181654,181656,181671,181672,181673,181674,182464,184305,184772,184773,184774,184775},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=177126}},ends={{npcID=177685}},coords={x=0.332,y=0.57,source="quest_giver",zoneID=11400},questType="standard"},
[63665] = {id=63665,name="Opening to Oribos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1961,description="The prophecies told us that one day this dormant waystone would be needed by a Maw Walker. That it would prove crucial to the fate of the Shadowlands. It seems that day has come. Draw upon the anima within you to activate this waystone. It will then be usable by all those who aid your cause. If, as you say, Tal-Inara has created an anchor in Oribos , then that anchor will bring you back to us. Go, . Inform your allies that the Maw awaits... and that Korthia needs their help.",objectivesText="Activate the waystone and travel to Oribos .",rewardGold=128700,rewardXP=4085,starts={{npcID=177227}},ends={{npcID=177227}},coords={x=0.638,y=0.236,source="quest_giver",zoneID=13570},questType="standard"},
[63669] = {id=63669,name="Somebody Feed Kevin",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source! The more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family. Take Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!",objectivesText="Consume 8 fallen enemies to grow Kevin to full size.",rewardGold=341600,rewardXP=8165,rewardItems={181503,181645,181647,181649,181651,181660,181661,181662,181663,181664,181665,181666,181675,181676,181677,181678,181679,181680,181681,181686,181689,181734,181864,182470,182667,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=163295}},ends={{npcID=177072},{npcID=177685}},coords={x=0.328,y=0.568,source="quest_giver",zoneID=11400},questType="standard"},
[63671] = {id=63671,name="Favor: The Nathrezim Documents",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera. You will be fairly compensated.",objectivesText="Bring The Nathrezim Documents to Ta'xera at The Night Market in Revendreth . Provided item:",rewardGold=772200,rewardXP=2125,questType="standard"},
[63672] = {id=63672,name="A Cry From the Heart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ysera emanates from the scroll as you read the words.> , There is a matter of great importance which requires your help. Please meet me at the Heart of the Forest as soon as you can.",objectivesText="Meet Ysera at the Heart of the Forest.",rewardGold=25740,rewardXP=1020,starts={{npcID=177919}},ends={{npcID=160262},{npcID=177434}},questType="standard"},
[63673] = {id=63673,name="Hunting Amid Houses",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I have good news, . With the covenants working more closely together, Huln's hunt has found greater success. He has solid leads on two more Night Warriors here in the Shadowlands. He wishes for you to meet him in Maldraxxus about the first. Huln awaits you at the Sepulcher of Knowledge. Hurry, . Elune's power rips at Tyrande's essence. I do not know how much longer she can hold on.",objectivesText="Find Huln Highmountain in Maldraxxus. Progress: I am glad to hunt by your side once more, <name>.",rewardGold=25740,rewardXP=1020,starts={{npcID=160262}},ends={{npcID=177471}},coords={x=0.442,y=0.388,source="quest_giver",zoneID=12858},questType="standard"},
[63674] = {id=63674,name="By Your Leave",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I have a task set before me by my Baroness, Lady Vashj. With assistance, my vengeance would be swift. But she must approve of your help as well as my release to assist you with your task. Go to the Seat of the Primus. There we will speak with her.",objectivesText="Meet with Lady Vashj at the Seat of the Primus, and request Khaliiq 's help. Progress: Good. You move swiftly.",rewardGold=128700,rewardXP=4085,starts={{npcID=177435}},ends={{npcID=177435}},coords={x=0.528,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[63675] = {id=63675,name="You Cannot Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Zelmany was integral in the fall of my Margrave. Sin'Dane believes he is trying to gather forces loyal to Kel'Thuzad so they might help him in his next plot. We should look for clues to his location and then slay him.",objectivesText="Collect clues and then slay Zelmany . Progress: The traitors cannot run!",rewardGold=257400,rewardXP=8165,rewardItems={185761,185767,185768,185769,185770},starts={{npcID=177435}},ends={{npcID=177435}},coords={x=0.528,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[63676] = {id=63676,name="You Cannot Hide",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="There are those who held their affiliation with Kel'Thuzad secret even after he made his move. They too were involved in the fall of my Margrave, and they too shall die. I have one name, Drava'ora , but there are more. Sin'dane had indicated these traitors carry marks of favor. She doesn't know who has them so we'll start killing until we find them. The rest will see the example made.",objectivesText="Recover Marks of Kel'Thuzad's favor and slay Drava'ora . Progress: Those that remain will be scared into line.",rewardGold=257400,rewardXP=8165,rewardItems={185773},starts={{npcID=177435}},ends={{npcID=177435}},coords={x=0.528,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[63677] = {id=63677,name="You Can Only Die",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The last name on my list is a lich named Fal'zinge . Sin'Dane has been keeping a close eye on him to learn more of what Kel'Thuzad is planning next. She wishes for Fal'zinge 's execution to be brutal. We will find him in the Exoramas in the House of Rituals.",objectivesText="Slay Fa'zinge on the Exoramas. Progress: Another name for the list.",rewardGold=257400,rewardXP=8165,starts={{npcID=177435}},ends={{npcID=177435}},coords={x=0.528,y=0.686,source="quest_giver",zoneID=11462},questType="standard"},
[63678] = {id=63678,name="Akarek Avenged",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The last of those traitors involved in taking down Margrave Akarek are dead. It will not bring our Margrave back, but I am still pleased. My Baroness wished for us to inform Margrave Sin'dane that the job was done before departing for Ardenweald.",objectivesText="Meet with Margrave Sin'Dane in the Exoramas in the House of Rituals.",rewardGold=25740,rewardXP=1020,starts={{npcID=177437}},ends={{npcID=177782}},questType="standard"},
[63679] = {id=63679,name="Magical Mystery Tour!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Lady Moonberry 's voice rises from the scroll.> ! It seems Huln got into some trouble. And--well--it's complicated. We could really use your help in Revendreth! Please meet me at Dominance Keep. See you soon!",objectivesText="Find Lady Moonberry in Revendreth.",rewardGold=25740,rewardXP=1020,starts={{npcID=177919}},ends={{npcID=177962}},questType="standard"},
[63680] = {id=63680,name="Out On the Edge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It sounds like Huln was taken elsewhere, and by the Stonewright herself! We should look for signs she came through the area. Hopefully that will lead us to Huln!",objectivesText="Track down Huln Highmountain .",rewardGold=257400,rewardXP=8165,starts={{npcID=177967}},ends={{npcID=177962}},coords={x=0.356,y=0.226,source="quest_giver",zoneID=10413},questType="standard"},
[63681] = {id=63681,name="Back to The Heart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1525,description="We should hurry back to Ardenweald! You go on ahead and find Ysera . I'll escort the Stonewright there and make sure Huln gets back.",objectivesText="Return to Ysera in front of the Heart of the Forest in Ardenweald.",rewardGold=25740,rewardXP=1020,starts={{npcID=177962}},ends={{npcID=177434}},coords={x=0.34,y=0.096,source="quest_giver",zoneID=10413},questType="standard"},
[63682] = {id=63682,name="The Power of Elune",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="We have done as much as we can with the time we had. Now we must lend our power to Thiernax and the others, and hope Tyrande survives.",objectivesText="Assist with the ritual.",rewardGold=257400,rewardXP=8165,rewardItems={182171},starts={{npcID=177434}},ends={{npcID=178669}},coords={x=0.452,y=0.648,source="quest_giver",zoneID=11510},questType="standard"},
[63683] = {id=63683,name="Winter's Sigil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="My sister... After all this time... She did not abandon me... Winter Queen 's face before it is gone. She turns her attention to you with the weight of eons.> Attend me, . Take my sister's tear, and come to the Heart of the Forest.",objectivesText="Bring the Sisters' Tear to Ysera at the Heart of the Forest. Progress: Well done.",rewardGold=257400,rewardXP=8165,rewardItems={184380},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=178669}},ends={{npcID=177434},{npcID=160262}},coords={x=0.452,y=0.65,source="quest_giver",zoneID=11510},questType="standard"},
[63684] = {id=63684,name="Feral Shadehound",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="feral shadehound and bind it to you.>",objectivesText="Summon and bind your Feral Shadehound .",rewardItems={184168,185616},questType="standard"},
[63685] = {id=63685,name="Cryptkeeper Kassir's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,rewardGold=257400,rewardXP=8165,starts={{npcID=163073,x=0.702,y=0.562,mapID=1525}},ends={{npcID=163073,x=0.702,y=0.562,mapID=1525}},coords={x=0.702,y=0.562,source="quest_giver",mapID=1525},questType="world",worldTaskTitle="Cryptkeeper Kassir's Best Friend"},
[63686] = {id=63686,name="Baroness Vashj's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,rewardGold=257400,rewardXP=8165,starts={{npcID=162487,x=0.676,y=0.46,mapID=1536}},ends={{npcID=162487,x=0.676,y=0.46,mapID=1536}},coords={x=0.676,y=0.46,source="quest_giver",mapID=1536},questType="world",worldTaskTitle="Baroness Vashj's Best Friend"},
[63687] = {id=63687,name="Lady Moonberry's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,rewardGold=257400,rewardXP=8165,starts={{npcID=172098,x=0.49,y=0.51,mapID=1565}},ends={{npcID=172098,x=0.49,y=0.51,mapID=1565}},coords={x=0.49,y=0.51,source="quest_giver",mapID=1565},questType="world",worldTaskTitle="Lady Moonberry's Best Friend"},
[63688] = {id=63688,name="Mikanikos's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,rewardGold=257400,rewardXP=8165,starts={{npcID=171647,x=0.502,y=0.212,mapID=1533}},ends={{npcID=171647,x=0.502,y=0.212,mapID=1533}},coords={x=0.502,y=0.212,source="quest_giver",mapID=1533},questType="world",worldTaskTitle="Mikanikos's Best Friend"},
[63689] = {id=63689,name="The Countess's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,rewardGold=257400,rewardXP=8165,starts={{npcID=171106,x=0.58,y=0.276,mapID=1525}},ends={{npcID=171106,x=0.58,y=0.276,mapID=1525}},coords={x=0.58,y=0.276,source="quest_giver",mapID=1525},questType="world",worldTaskTitle="The Countess's Best Friend"},
[63690] = {id=63690,name="Alexandros Mograine's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1698,rewardGold=257400,rewardXP=8165,starts={{npcID=171933,x=0.504,y=0.674,mapID=1536}},ends={{npcID=171933,x=0.504,y=0.674,mapID=1536}},coords={x=0.504,y=0.674,source="quest_giver",mapID=1536},questType="world",worldTaskTitle="Alexandros Mograine's Best Friend"},
[63691] = {id=63691,name="Hunt-Captain Korayn's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,rewardGold=257400,rewardXP=8165,starts={{npcID=171319,x=0.508,y=0.704,mapID=1565}},ends={{npcID=171319,x=0.508,y=0.704,mapID=1565}},coords={x=0.508,y=0.704,source="quest_giver",mapID=1565},questType="world",worldTaskTitle="Hunt-Captain Korayn's Best Friend"},
[63692] = {id=63692,name="Polemarch Adrestes's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,rewardGold=257400,rewardXP=8165,starts={{npcID=171385,x=0.69,y=0.406,mapID=1533}},ends={{npcID=171385,x=0.69,y=0.406,mapID=1533}},coords={x=0.69,y=0.406,source="quest_giver",mapID=1533},questType="world",worldTaskTitle="Polemarch Adrestes's Best Friend"},
[63693] = {id=63693,name="Rendle and Cudgelface's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,rewardGold=257400,rewardXP=8165,questType="world",worldTaskTitle="Rendle and Cudgelface's Best Friend"},
[63694] = {id=63694,name="Choofa's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,rewardGold=257400,rewardXP=8165,starts={{npcID=160814,x=0.636,y=0.366,mapID=1565}},ends={{npcID=160814,x=0.636,y=0.366,mapID=1565}},coords={x=0.636,y=0.366,source="quest_giver",mapID=1565},questType="world",worldTaskTitle="Choofa's Best Friend"},
[63695] = {id=63695,name="Droman Aliothe's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,rewardGold=257400,rewardXP=8165,starts={{npcID=160894,x=0.6,y=0.538,mapID=1565}},ends={{npcID=160894,x=0.6,y=0.538,mapID=1565}},coords={x=0.6,y=0.538,source="quest_giver",mapID=1565},questType="world",worldTaskTitle="Droman Aliothe's Best Friend"},
[63696] = {id=63696,name="Grandmaster Vole's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,rewardGold=257400,rewardXP=8165,starts={{npcID=163019,x=0.528,y=0.492,mapID=1536}},ends={{npcID=163019,x=0.528,y=0.492,mapID=1536}},coords={x=0.528,y=0.492,source="quest_giver",mapID=1536},questType="world",worldTaskTitle="Grandmaster Vole's Best Friend"},
[63697] = {id=63697,name="Kleia and Pelagos's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,rewardGold=257400,rewardXP=8165,starts={{npcID=174916,x=0.558,y=0.864,mapID=1533}},ends={{npcID=174916,x=0.558,y=0.864,mapID=1533}},coords={x=0.558,y=0.864,source="quest_giver",mapID=1533},questType="world",worldTaskTitle="Kleia and Pelagos's Best Friend"},
[63698] = {id=63698,name="Plague Deviser Marileth's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,rewardGold=257400,rewardXP=8165,starts={{npcID=159930,x=0.604,y=0.716,mapID=1536}},ends={{npcID=159930,x=0.604,y=0.716,mapID=1536}},coords={x=0.604,y=0.716,source="quest_giver",mapID=1536},questType="world",worldTaskTitle="Plague Deviser Marileth's Best Friend"},
[63699] = {id=63699,name="Sika's Best Friend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,rewardGold=257400,rewardXP=8165,starts={{npcID=166577,x=0.526,y=0.826,mapID=1533}},ends={{npcID=166577,x=0.526,y=0.826,mapID=1533}},coords={x=0.526,y=0.826,source="quest_giver",mapID=1533},questType="world",worldTaskTitle="Sika's Best Friend"},
[63700] = {id=63700,name="Stonehead's Best Friend",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10413,mapID=1525,rewardGold=257400,rewardXP=8165,ends={{npcID=157199,x=0.39,y=0.66,mapID=1525}},questType="world",worldTaskTitle="Stonehead's Best Friend"},
[63703] = {id=63703,name="Vault of Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="You've helped us regain a semblance of order, Maw Walker, but the outlook is dire. The Jailer's forces have launched an all-out assault upon the ruins of our vault at the outer reaches of Korthia . Clearly the Banished One seeks something of value inside. The vault's defenses activate when the structure is threatened, so getting inside won't be easy. But we must recover whatever the Jailer is seeking before his Mawsworn do. I've enlisted the aid of a necrolord who can help open the vault.",objectivesText="Meet with Tal-Galan outside of Scholar's Den.",rewardGold=25740,rewardXP=1020,starts={{npcID=177927}},ends={{npcID=177423}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[63704] = {id=63704,name="Vengeance for Korthia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="While opening the vault is our priority, I must ask a favor. When Korthia was pulled into the Maw, my people were terrified. We fled to the area you see before you, a place of peace called the Scholar's Den. The Mawsworn soon descended upon us. Most of my kind were slaughtered. Others were taken captive. If I could claim vengeance myself, I would. But I... I am ill-equipped for battle. Not like you. Please. Show these monsters that their defilement of Korthia will not stand!",objectivesText="Slay 15 Mawsworn in Scholar's Den.",rewardGold=257400,rewardXP=8165,starts={{npcID=177423}},ends={{npcID=177423}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=13570},questType="standard"},
[63705] = {id=63705,name="The Knowledge Keepers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our vault was built to store countless secrets and artifacts. Even if we gain entrance, we can't be certain of what the Jailer is looking for. Certain attendants are given the title of record keeper . They track items stored in the vault, and are known for their utmost discretion. A number of keepers have been taken captive by the Mawsworn and are being tortured for information. Save the record keepers , . They can help us determine what the Banished One seeks.",objectivesText="Rescue 5 record keepers from Scholar's Den.",rewardGold=257400,rewardXP=8165,starts={{npcID=177423}},ends={{npcID=177423}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=13570},questType="standard"},
[63706] = {id=63706,name="Let the Anima Flow",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Tal-Galan briefed me on the situation and explained the vault's workings. As well as any scholarly type could, at least. First we need to ensure the vault is getting power. They use underground conduits to feed it anima. The attendant says that one of these conduits is tucked away in a cave in Scholar's Den. You get me there and I'll find a way to fix it. Just watch my back while I figure out how these Korthian devices work.",objectivesText="Help Bonesmith Heirmir repair the Anima Conduit.",rewardGold=257400,rewardXP=8165,starts={{npcID=177449}},ends={{npcID=177449}},coords={x=0.572,y=0.3,source="quest_giver",zoneID=13570},questType="standard"},
[63708] = {id=63708,name="Phantasmagoria",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari may find it of interest.>",objectivesText="Bring the Warped Phantasma to Ve'nari at Ve'nari 's Refuge. Provided item:",rewardGold=514800,rewardXP=10205,ends={{npcID=162804}},coords={mapID=1543,source="quest_giver",x=0.468,y=0.416},questType="standard"},
[63709] = {id=63709,name="Secrets of the Vault",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="What fortune! You rescued the record keepers before the Mawsworn could steal their knowledge of the vault's relics. But their records are fragmented. Incomplete. I pray there's enough left to learn the truth. I will attempt to coalesce the knowledge that remains into a message. If the Purpose wills it, we will learn what the Jailer wants and to whom this item originally belonged. I must focus for a moment. Let me know when you are ready to begin.",objectivesText="Examine the recovered recordings with Tal-Galan . Progress: Are you ready to begin?",rewardGold=257400,rewardXP=8165,starts={{npcID=177423}},ends={{npcID=177423}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=13570},questType="standard"},
[63710] = {id=63710,name="The Anima Trail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="So the Jailer seeks the Primus's sigil. We must beat the Mawsworn to it. To open the vault, we need to power it with anima. You helped the Bonesmith repair the first conduit. The trail of anima in front of us leads to the next. If we can activate it, then there should be enough anima flowing into Korthia to get us inside the vault. Come, we must make haste!",objectivesText="Follow the anima trail to the next conduit.",rewardGold=257400,rewardXP=8165,starts={{npcID=177423}},ends={{npcID=177451}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=13570},questType="standard"},
[63711] = {id=63711,name="Bone Tools",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="So the device we need to open this vault is stuck on a floating island, eh? Not a problem. I see plenty of sturdy creatures around here. Like I always say, no bone goes to waste! Bring me a pile of their bones. I'll use them to craft hookshot points for us to use to grapple over there.",objectivesText="Salvage 50 anima-infused bones from wildlife Progress: Remember, I just need the bones. Flesh only gets in the way.",rewardGold=257400,rewardXP=8165,rewardItems={185719},starts={{npcID=177452}},ends={{npcID=177452}},coords={x=0.348,y=0.354,source="quest_giver",zoneID=13570},questType="standard"},
[63712] = {id=63712,name="Lost Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Some of the record keepers fled to this mountain when Korthia was pulled into the Maw. I see no sign of them, but they may have left records behind. Take this beacon. I fashioned it using information from the previous record keepers you rescued. It will lead you to any intact records that are on this mountain.",objectivesText="Use the Matrix Beacon to recover 3 Lost Recordings. Progress: Have you recovered the records?",rewardGold=257400,rewardXP=8165,rewardItems={185716,185921},starts={{npcID=177451}},ends={{npcID=177451}},coords={x=0.35,y=0.352,source="quest_giver",zoneID=13570},questType="standard"},
[63713] = {id=63713,name="Hooking Over",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I've made some solid hookshots and grapple points. Don't worry--if they hold my weight, they'll hold yours! They can get us across the chasm to the next anima conduit. I'll go on ahead and wait for you. No telling what might be lurking over there. The sooner we get the anima conduit working, the sooner we get into the vault and claim the Primus's sigil.",objectivesText="Travel to the floating island with a hookshot, then repair the anima conduit.",rewardGold=257400,rewardXP=8165,starts={{npcID=177452}},ends={{npcID=177452}},coords={x=0.348,y=0.354,source="quest_giver",zoneID=13570},questType="standard"},
[63714] = {id=63714,name="To the Vault",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Thanks to the Bonesmith's repairs of both conduits, anima should now be flowing to the vault. That gives us a chance to get inside--assuming we can reach it. Our Maldraxxi allies have wrangled transportation to get us to and from the vault. I suggest we make haste. If the Jailer's minions obtain the sigil of the Primus before we do, it won't just be Korthia that suffers. All the Shadowlands may be forfeit. Let's go, Maw Walker. Our forces will be awaiting us.",rewardGold=257400,rewardXP=8165,starts={{npcID=177451}},ends={{npcID=177459}},coords={x=0.35,y=0.352,source="quest_giver",mapID=1961},questType="standard"},
[63717] = {id=63717,name="Defending the Vault",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="To reach the vault, we'll need to carve a path through the attacking Mawsworn. The covenants are doing their best to drive off these monstrosities, but our allies can't hold out forever. The Mawsworn are intent on reaching the prize before you. We could use your help fighting against the Jailer's forces, Maw Walker. Purpose guide us all.",objectivesText="Help Protector Kah-Rev defeat the invading Mawsworn. Progress: Purpose guide your blade!",rewardGold=257400,rewardXP=8165,starts={{npcID=177459}},ends={{npcID=178647}},coords={x=0.49,y=0.642,source="quest_giver",zoneID=13570},questType="standard"},
[63718] = {id=63718,name="Theotar's Egg",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: Like true love, my egg is always within sight but often out of reach...",starts={{npcID=165196}},ends={{npcID=165196}},coords={x=0.54,y=0.202,source="quest_giver",zoneID=10413},questType="standard"},
[63719] = {id=63719,name="Temel's Egg",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: I hid my egg where I keep all of our important party supplies...",starts={{npcID=165149}},ends={{npcID=165149}},coords={x=0.412,y=0.454,source="quest_giver",zoneID=10413},questType="standard"},
[63720] = {id=63720,name="Prince Renathal's Egg",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: My egg is the center of attention, as I hope to be...",starts={{npcID=164965}},ends={{npcID=164965}},coords={x=0.474,y=0.41,source="quest_giver",zoneID=10413},questType="standard"},
[63721] = {id=63721,name="Lord Garridan's Egg",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,objectivesText="Progress: I always say, keep your friends close and your eggs closer...",starts={{npcID=165454}},ends={{npcID=165454}},coords={x=0.376,y=0.326,source="quest_giver",zoneID=10413},questType="standard"},
[63722] = {id=63722,name="Keepers of Korthia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We've barely held out against the Jailer's forces. Now that you're here, we can finally make some progress. I know your priority is to enter the vault, but our record keepers must also be recovered. They are the authorities about everything kept in the vault. We can't let the Jailer learn what they know.",objectivesText="Rescue 3 record keepers around the Vault of Secrets.",rewardGold=257400,rewardXP=8165,starts={{npcID=177459}},ends={{npcID=178647}},coords={x=0.49,y=0.642,source="quest_giver",zoneID=13570},questType="standard"},
[63725] = {id=63725,name="Into the Vault",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The destruction here is... overwhelming. Tal-Galan quietly utters a prayer.> Anima flows into what remains of the vault. We should now be able to enter. Once inside, I will work on recovering the Primus's sigil. Please show reverence within the vault. It is a sacred place that few are allowed to see. Even the prophecies did not foretell that a living mortal would gaze upon the secrets within.",objectivesText="Recover the Primus's Sigil within the vault of Korthia .",rewardGold=257400,rewardXP=8165,starts={{npcID=178676}},ends={{npcID=177228}},coords={x=0.502,y=0.758,source="quest_giver",zoneID=13570},questType="standard"},
[63726] = {id=63726,name="Untangling the Sigil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16641,mapID=1961,description="The Primus 's sigil is bound together with the magic of memory. It reminds me of something you have encountered before. You made an ally of the Runecarver, that poor soul trapped in the bowels of Torghast. He took those memories you found and helped you forge them into weapons and armor. Perhaps he can separate the sigil from this tangle of memories. It's our best chance to secure the sigil. But the way will be perilous.",objectivesText="Speak with Bolvar to discuss what to do with the sigil.",rewardGold=257400,rewardXP=8165,rewardItems={187218},starts={{npcID=177228}},ends={{npcID=177228}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[63727] = {id=63727,name="The Primus Returns",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Jailer has four of the five sigils required for what he is planning. He is a fool for allowing us to live. His desire to see us bend to his will shall be his undoing. All is not lost, if you are willing to put in the work. There is still something that can be done. Come. I will meet with the rest of your forces and formulate our next attack.",objectivesText="Meet with the Primus within Keeper's Respite to form a new plan of attack.",rewardGold=772200,rewardXP=12250,rewardItems={185965},rewardChoices={185965},rewardCurrencies={{id=1906,amount=100}},starts={{npcID=177569}},ends={{npcID=177194}},questType="standard"},
[63728] = {id=63728,name="Hunting Amid Houses",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1565,description="I have dreamed that Tyrande Whisperwind is crucial to the survival of Ardenweald. The night fae have been searching for others like her who were once Night Warriors. We have recruited an ancient ally of Azeroth, Huln Highmountain , in order to look for them. Elune's power is too much for any mortal to contain--even Tyrande. I do not know how much longer she can hold on. Allow me to explain further, then you must hurry to meet Huln in Maldraxxus.",objectivesText="Speak with Ysera to learn more, then find Huln Highmountain in the Sepulcher of Knowledge. Progress: Ardenweald appreciates your help.",rewardGold=25740,rewardXP=1020,starts={{npcID=177434}},ends={{npcID=177471}},coords={x=0.452,y=0.648,source="quest_giver",zoneID=11510},questType="standard"},
[63731] = {id=63731,name="Researching Korthian Relics",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<You find a torn book regarding relics that were being kept within Korthia. A name written within its pages begins to glow: \"Roh-Suir.\" The book spins in your hand and points in a direction while Roh-Suir's name pulses. Perhaps this Roh-Suir could help you discover more about the relics you've found.>",objectivesText="Find Scholar Roh-Suir to learn more about relics. Provided item:",rewardGold=25740,ends={{npcID=178694}},coords={mapID=1961,source="quest_giver",x=0.59,y=0.58},questType="standard"},
[63732] = {id=63732,name="Interrupt the Interrogations",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Shhh... quietly! The invaders will kill me if they find me here, just as they have killed so many others! They're torturing the Archivist! You must find a way to rescue her. We cannot allow the Mawsworn to learn all that she knows!",objectivesText="Rescue Archivist Roh-Senara. Progress: There is no hope until and unless Archivist Roh-Senara is safe.",rewardGold=128700,rewardXP=4085,rewardItems={186101},starts={{npcID=178694}},ends={{npcID=178694}},coords={x=0.59,y=0.58,source="quest_giver",zoneID=13570},questType="standard"},
[63733] = {id=63733,name="Carving Out a Path",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="While I abhor violence and prefer a reasoned response to conflict, there is no alternative here. In order for Roh-Suir and I to escape safely, you must deliver a decisive strike to the Mawsworn who have invaded Seeker's Quorum. Carve out a path so that we may escape.",objectivesText="Defeat 15 Mawsworn invaders. Progress: Attacking the Mawsworn is risky, but necessary. I pray they did not follow us.",rewardGold=257400,rewardXP=8165,starts={{npcID=178713}},ends={{npcID=177928}},coords={x=0.59,y=0.58,source="quest_giver",zoneID=13570},questType="standard"},
[63734] = {id=63734,name="The Sundered Staff",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I have no choice but to trust you with the secrets of the Lodestaff. In the right hands, such as those of a trained Archivist, the staff can locate influential relics from the afterlives of the Shadowlands. It was split into three segments to ensure that it would not fall into the wrong hands. The invaders have found the pieces, but they are yet not aware of their significance. Recover the pieces of the staff. Each segment is held by a different member of the Mawsworn.",objectivesText="Recover the three segments of the Lodestaff. Progress: Were you able to recover all three segments of the Lodestaff?",rewardGold=257400,rewardXP=8165,rewardItems={185735,185759,185760},starts={{npcID=178713}},ends={{npcID=177928}},coords={x=0.59,y=0.58,source="quest_giver",zoneID=13570},questType="standard"},
[63735] = {id=63735,name="Recover the Research",level=60,requiredLevel=60,faction="none",expansion=8,description="Though the circumstances are grim, we cannot neglect the Purpose. On the bodies of the attendants in the Seeker's Quorum, you will find scrolls detailing our ongoing research. What is written on each of these scrolls represents efforts equal to many of your lifetimes. Retrieve them, before they are destroyed and lost forever.",objectivesText="Recover 6 Scholars' Research Scrolls.",rewardGold=257400,rewardXP=8165,questType="standard"},
[63736] = {id=63736,name="An Infusion of Anima",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Normally we would infuse the Lodestaff with energy from the Netherstar, another relic of note. Regrettably, that is not an option. But, in a pinch, anima is an acceptable substitute. Take the Lodestaff . Brandish it near recently slain devourers in the estuary below us. The staff should draw in and absorb their anima.",objectivesText="Infuse the Lodestaff with anima.",rewardGold=257400,rewardXP=8165,rewardItems={186157},starts={{npcID=177928}},ends={{npcID=177928}},coords={x=0.394,y=0.512,source="quest_giver",zoneID=13570},questType="standard"},
[63737] = {id=63737,name="Finding One's True Purpose",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="All our efforts have led us here. With the combined wisdom of the Archivists, and a little help from a , we will attune the Lodestaff to the relics that we seek. Should we succeed, we will have what we need to re-establish the Archive. Our sacred work can then continue.",objectivesText="Participate in the ritual to attune the Lodestaff. Progress: Is it over? Was the attuning a success?",rewardGold=514800,rewardXP=10205,starts={{npcID=178991}},ends={{npcID=178992}},coords={x=0.358,y=0.322,source="quest_giver",zoneID=13570},questType="standard"},
[63738] = {id=63738,name="Establishing the Archive",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I will head to Keeper's Respite, where there is some small semblance of safety. There, we will establish a new archive. Meet me there when you are able. I hope we can count on you again. We will have need of your assistance there in the future.",objectivesText="Meet Scholar Roh-Suir at Keeper's Respite.",rewardGold=25740,rewardXP=1020,starts={{npcID=178992}},ends={{npcID=178313}},coords={x=0.36,y=0.322,source="quest_giver",zoneID=13570},questType="standard"},
[63739] = {id=63739,name="Hope Ascending",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There is one final thing we must do. Meet us atop the peak of Hope's Ascent.",objectivesText="Meet Archivist Roh-Senara and Scholar Roh-Suir near the top of Hope's Ascent.",rewardGold=25740,rewardXP=1020,starts={{npcID=177928}},ends={{npcID=178991}},coords={x=0.394,y=0.512,source="quest_giver",zoneID=13570},questType="standard"},
[63740] = {id=63740,name="Consulting the Experts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We can restore the functions of the Lodestaff, but it will require the wisdom of the Archivists. Not just me, but the Archivists who have come before. They were laid to rest near here. Given the scale of the destruction of Korthia and the likely possibility that this destruction will continue, this may be our last chance to visit their memorials before they are irrevocably ruined. Visit the Archivists' memorials. Take Roh-Suir with you, so that he may take note of their messages before they are lost.",objectivesText="Commune with the Archivists' memorials. Progress: Do not fear the Archivists of old. They are here to help.",rewardGold=193050,rewardXP=6125,starts={{npcID=177928}},ends={{npcID=177928}},coords={x=0.394,y=0.512,source="quest_giver",zoneID=13570},questType="standard"},
[63751] = {id=63751,name="A Terrible Power",level=60,requiredLevel=60,faction="none",expansion=8,description="This strange shard pulses in your hand. An aura of dread radiates forth from it like a chill wind, sending a shiver down your spine. Perhaps the Primus could tell you more about this... if you could find him.",rewardGold=257400,rewardXP=8165,questType="standard"},
[63753] = {id=63753,name="Centurions March!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Three of our Centurions have broken through the side gate. They need additional anima to continue their assault. Several of my assistants tried to deliver anima to them, but failed. Please get recover the anima and assist the Centurions in the attack.",objectivesText="Collect 5 Anima Motes to empower and assist the Centurion in combat. Progress: Have the Centurions succeeded?",rewardItems={185733},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177175}},ends={{npcID=177175}},coords={x=0.37,y=0.634,source="quest_giver",zoneID=11400},questType="standard"},
[63754] = {id=63754,name="The Caged Bird",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Remain quiet. We must not attract attention. Many of my sisters have already been lost. It will soon be my turn to perish in that witch's vile ritual. Release me from this cage and I can see us both to safety. Keeper Odyn must be warned of this foul betrayal! The Mawsworn called Kjellrun holds the seal that can free me. You can find her gloating in the nearby hall.",objectivesText="Acquire the Helwrought Seal from Kjellrun and release Danica from her captivity. Progress: This is no fate for a Val'kyr!",rewardGold=257400,rewardXP=8165,rewardItems={185738},starts={{npcID=177597}},ends={{npcID=177597}},coords={x=0.672,y=0.558,source="quest_giver",zoneID=11400},questType="standard"},
[63755] = {id=63755,name="A Matter of Urgency",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Maw Walker, there is a matter of urgency that has not been addressed. Our Fatescribe is missing. They have not found their way here. They would have been in Seeker's Quorum before... Pathscribe Roh-Vess pauses.> Can you look for the Fatescribe? Many attendants used the caves near the ruins to hide from the mawsworn.",objectivesText="Search for the Fatescribe of Korthia .",rewardGold=25740,rewardXP=1020,starts={{npcID=177155}},ends={{npcID=177610}},coords={x=0.642,y=0.23,source="quest_giver",zoneID=13570},questType="standard"},
[63756] = {id=63756,name="Rescued from Torment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Mawsworn are not only killing those they find in the Seeker's Quorum. They are interrogating the survivors. We should help save those we can. It's possible one of them might have seen the Fatescribe.",objectivesText="Rescue 6 Tortured Attendants in Seeker's Quorum.",rewardGold=257400,rewardXP=8165,starts={{npcID=177610}},ends={{npcID=177610}},coords={x=0.562,y=0.388,source="quest_giver",zoneID=13570},questType="standard"},
[63757] = {id=63757,name="Looting the Looters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<The Mawsworn was carrying a Korthian artifact. It's unclear what the enemy wants with such relics, but you suspect the attendants in Keeper's Respite would want to see them returned.>",objectivesText="Retrieve 4 Korthian Artifacts from the Mawsworn.",rewardGold=257400,rewardXP=8165,rewardItems={185771,185827,185830,185831},questType="standard"},
[63758] = {id=63758,name="The Last Place You Look",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I came here hoping to locate the Fatescribe or something to help me find him. Evidence shows he was here and survived a Mawsworn attack. The only other place I haven't looked is a meditation chamber on the opposite side of the ruins. It's too dangerous for me to head back into the Seeker's Quorum alone. Could you help me? I must find the Fatescribe. It's a matter of great importance.",objectivesText="Search the Seeker's Quorum for the missing Fatescribe.",rewardGold=257400,rewardXP=8165,starts={{npcID=177610}},ends={{npcID=177610}},coords={x=0.562,y=0.388,source="quest_giver",zoneID=13570},questType="standard"},
[63759] = {id=63759,name="Redirect the Search",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I believe the Fatescribe was headed to the Sanctuary of Guidance. A holy place for the attendants of Korthia . Fortunately, because you seem to be in the habit of picking up every piece of trash you find, we have the Fatescribe's Implement! I'm sure that will prove useful in locating him. But first, on to the Sanctuary.",objectivesText="Meet Caretaker Kah-Than at the entrance to the Sanctuary of Guidance in Korthia .",rewardGold=25740,rewardXP=1020,starts={{npcID=177924}},ends={{npcID=177610}},questType="standard"},
[63760] = {id=63760,name="Echoes of Fate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The devourers have swarmed this place, but our focus must remain on finding the Fatescribe. Attendants who worshipped here would leave offerings of anima at the shrines. The implement you found will resonate if the Fatescribe has been nearby. With any luck, it will give us insight into where he has gone.",objectivesText="Resonate the Fatescribe's Implement at the shrines in the Sanctuary of Guidance.",rewardGold=257400,rewardXP=8165,rewardItems={185828},starts={{npcID=177610}},ends={{npcID=177610}},coords={x=0.562,y=0.388,source="quest_giver",zoneID=13570},questType="standard"},
[63761] = {id=63761,name="Revenge Delayed",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Devourers... swarmed the sanctuary. Too few of us... My duty... incomplete. The Purpose... I...",objectivesText="Kill 10 Devourers in the Sanctuary of Guidance.",rewardGold=257400,rewardXP=8165,starts={{npcID=177850}},ends={{npcID=177155}},coords={x=0.556,y=0.222,source="quest_giver",zoneID=13570},questType="standard"},
[63762] = {id=63762,name="Under the Illusion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Fatescribe has collected the necessary items to create an illusion in this chamber. Fortunately, we can use his own implement to dispel it and reveal him. He will be grateful to see a friendly face, I'm sure. I must say, you've proven to be incredibly helpful in this task. I truly couldn't have done it without you.",objectivesText="Use the Fatescribe's Implement to dispel the illusion.",rewardGold=257400,rewardXP=8165,rewardItems={185847},starts={{npcID=177610}},ends={{npcID=177610}},coords={x=0.562,y=0.388,source="quest_giver",zoneID=13570},questType="standard"},
[63763] = {id=63763,name="They Could Be Anyone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<The still-warm head of the dreadlord Azodius grimaces at you. The attendants at Keeper's Respite should be told of the Fatescribe's abduction. No doubt Highlord Fordragon will want to hear of this unexpected threat.>",objectivesText="Take the head of Azodius to Bolvar Fordragon in Keeper's Respite. Provided item:",rewardGold=514800,rewardXP=10205,ends={{npcID=177228}},coords={mapID=1961,source="quest_giver",x=0.629,y=0.246},questType="standard"},
[63764] = {id=63764,name="Claim the Sky",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I mourn the loss of my sisters and desire nothing more than to avenge them. Yet I know that I am no match for the witch's magics or her army of Mawsworn. We must let wisdom guide us and fly from here. Though I am weak from my captivity, I have the strength to bear you from this place. Let us go, friend.",objectivesText="Fly with Danica to Odyn's halls in Skyhold.",rewardGold=257400,rewardXP=8165,starts={{npcID=177597}},ends={{npcID=177597}},coords={x=0.672,y=0.558,source="quest_giver",zoneID=11400},questType="standard"},
[63765] = {id=63765,name="Unseen Hero of the Party",level=60,requiredLevel=60,faction="both",expansion=8,objectivesText="Progress: Oooh, this book looks long, I bet it is incredibly important.",starts={{npcID=172854}},questType="standard"},
[63771] = {id=63771,name="Fate's Reminder",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Fatescribe Roh-Tahl awaits you within Oribos , should you ever wish to change the course of fate. You may speak with him at your leisure.",objectivesText="Meet Fatescribe Roh-Tahl in Oribos if you wish to enter the Threads of Fate.",rewardGold=25975,rewardXP=850,questType="standard"},
[63772] = {id=63772,name="Waiting in the Wings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Kyrian forces have arrived to assist in the assault. They have secured our flank and will lay siege to the south gate of Perdition Hold. Report to Artemede and assist the Kyrians however you can!",objectivesText="Assist Artemede and the Kyrian forces outside the southern gate of Perdition Hold.",rewardGold=25740,rewardXP=1020,rewardItems={184513},starts={{npcID=177072}},ends={{npcID=177226}},coords={x=0.338,y=0.548,source="quest_giver",zoneID=11400},questType="standard"},
[63773] = {id=63773,name="You and What Army",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Jailer has dispatched a force of elite troops to strike our rear lines. Their attack threatens our whole assault! I need you and one other soldier to eliminate these enemies. A volunteer from each of the five houses of Maldraxxus has requested to assist you, . Pick one and give them the honor of serving alongside you.",objectivesText="Select a champion and Eliminate 3 Mawchained Rampagers and 5 Mawchained Demolishers .",rewardItems={181501,181503,181507,181625,181626,181645,181647,181649,181651,181652,181653,181654,181655,181660,181661,181662,181663,181664,181665,181666,181667,181668,181669,181670,181671,181673,181676,181679,181680,181681,181682,181686,181864,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=177072}},ends={{npcID=177072},{npcID=177685}},coords={x=0.338,y=0.548,source="quest_giver",zoneID=11400},questType="standard"},
[63774] = {id=63774,name="An Embarrassment of Corpses",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Look around us, $p. Everywhere you turn there are corpses piling up like mountains. These disembodied souls are desperate to return to battle. We will use their fervor to turn the tide. Rally the disembodied souls around the battlefield and bring them to my stitchers at the corpse piles to build them new bodies!",objectivesText="Deliver 4 Disembodied Souls to Front-Line Stitchers who will craft them new bodies. Progress: Find the disembodied souls and bring them to my stitchers!",rewardItems={181498,181626,181645,181647,181649,181651,181656,181658,181659,181661,181664,181665,181666,181667,181672,181673,181674,181675,181676,181677,181678,181679,181680,181681,181682,181688,181842,182110,182338,182584,183470,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=177720}},ends={{npcID=177720}},coords={x=0.334,y=0.556,source="quest_giver",zoneID=11400},questType="standard"},
[63775] = {id=63775,name="Cryptograms and Keys",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The repositories of knowledge within Korthia have layers of security--for very good reasons. Each vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret. Search outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.",rewardItems={185746},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=179082,x=0.64,y=0.23,zoneID=13570}},ends={{npcID=179082,x=0.64,y=0.23,zoneID=13570}},coords={x=0.64,y=0.23,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Cryptograms and Keys"},
[63776] = {id=63776,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Be sure to check in the caverns below ground, as well! Bring those data to me, and I will reward you handsomely.",rewardItems={185758},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63777] = {id=63777,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Scholar's Den. Don't worry: they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",rewardItems={185763},starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63778] = {id=63778,name="We Move Forward",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="It breaks my heart to see another land so utterly obliterated. I can imagine how beautiful Korthia must have been, once. But we must not wallow in what we've lost. Like Ara'lon taught me: we don't have to stand still. We can choose to fight. You can help by taking anima back from those Mawsworn. We can put it to use, building up our own forces and defenses.",rewardItems={185749},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178840,x=0.61,y=0.212,mapID=1961}},ends={{npcID=178840,x=0.61,y=0.212,mapID=1961}},coords={x=0.61,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="We Move Forward"},
[63779] = {id=63779,name="A Semblance of Normalcy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p, we have to help the attendants of Korthia . They have lost so much, so suddenly. Nearby, in the Sanctuary of Guidance, they would take offerings and leave them at shrines. Since the mawsworn invaded, they haven't been able to enter the Sanctuary or retrieve their precious offerings. If you could collect the offerings and retrieve them. It might allow the attendants some semblance of their normal lives.",rewardItems={185750},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=179134,x=0.618,y=0.24,mapID=1961}},ends={{npcID=179134,x=0.618,y=0.24,mapID=1961}},coords={x=0.618,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="A Semblance of Normalcy"},
[63780] = {id=63780,name="See How THEY Like It!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Just thinking about how the Jailer's forces breached Ardenweald makes me so mad! And when I get mad, I get even. Or rather, I get your help with getting even! Slay those Mawsworn and bring back their emblems to show me how many you killed. I don't really care where you get them, as long as they come from those Maw jerks!",rewardItems={185751},rewardCurrencies={{id=1806,amount=175},{id=1907,amount=175}},starts={{npcID=178838,x=0.612,y=0.212,mapID=1961}},ends={{npcID=178838,x=0.612,y=0.212,mapID=1961}},coords={x=0.612,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="See How THEY Like It!"},
[63781] = {id=63781,name="Mawsworn Battle Plans",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Which is more damaging to the enemy, destroying a contingent of their forces or interrupting their communications? Better yet, what if that communication allows you to best place your forces to ambush their reinforcements? I see you understand. There will be a Mawsworn lieutenant, Voxiferus, traveling from the Maw into Korthia , by way of the northern road. Find them, kill them, and bring me the battle plans.",rewardItems={185752},rewardCurrencies={{id=1807,amount=175},{id=1907,amount=175}},starts={{npcID=178795,x=0.618,y=0.252,mapID=1961}},ends={{npcID=178795,x=0.618,y=0.252,mapID=1961}},coords={x=0.618,y=0.252,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Mawsworn Battle Plans"},
[63782] = {id=63782,name="Mawsworn Rituals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Mawsworn have a myriad of magic users among their forces. Their magic is unknown to us and that makes it deadly. We need to learn what they are capable of to properly prepare a defense. My own curiosity about their methods and rituals is secondary. Hunt down these vile casters and bring me their grimoires.",rewardItems={185753},rewardCurrencies={{id=1804,amount=175},{id=1907,amount=175}},starts={{npcID=178799,x=0.616,y=0.234,mapID=1961}},ends={{npcID=178799,x=0.616,y=0.234,mapID=1961}},coords={x=0.616,y=0.234,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Mawsworn Rituals"},
[63783] = {id=63783,name="Anima Reclamation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?",rewardItems={185754},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178793,x=0.618,y=0.256,mapID=1961}},ends={{npcID=178793,x=0.618,y=0.256,mapID=1961}},coords={x=0.618,y=0.256,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Anima Reclamation"},
[63784] = {id=63784,name="Gold's No Object",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p! How's things? We 'eard there was all kinds of interestin' stuff out 'ere. So, 'em sneakin' hoppers? Hard to see, innit? They've got 'emselves a shiny pelt as me 'n' the lads could use to stay out of sight, as it were. You know, avoid the bosses n' such. I need ya to capture a bundle of 'em. Gold's no object, just bring me the little pests alive.",rewardItems={186680,186688,186690,186691,186692,186693,186705,186706,186707,186708},rewardCurrencies={{id=1807,amount=175},{id=1907,amount=175}},starts={{npcID=179221,x=0.616,y=0.26,mapID=1961}},ends={{npcID=179221,x=0.616,y=0.26,mapID=1961}},coords={x=0.616,y=0.26,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Gold's No Object"},
[63785] = {id=63785,name="Continued Efforts: Seeker's Quorum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The onslaught from Zovaal's forces continues to devastate these lands. We must send them a message. Show them we will not back down, . The might of Ardenweald stands with you.",rewardItems={182180,184948,184949,184950,184951,184952,184953,184954,184955,184956,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1806,amount=175},{id=1907,amount=175}},starts={{npcID=178841,x=0.61,y=0.216,mapID=1961}},ends={{npcID=178841,x=0.61,y=0.216,mapID=1961}},coords={x=0.61,y=0.216,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Seeker's Quorum"},
[63786] = {id=63786,name="Sweep the Windswept Aerie",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The skies over Korthia are a dangerous place. Not only do the Mawsworn threaten our forces; the native creatures are also openly hostile. We must keep the skies safe for our own winged allies and beasts. The source of the native flyers is the Windswept Aerie. Go there and clear the aerie of aggressive creatures. Then, we shall have aerial supremacy.",rewardItems={185073,185074,185075,185076,185077,185078,185079,185080,185107,185108,185109,185110,185111,185112,185113,185114,185115,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1807,amount=175},{id=1907,amount=175}},starts={{npcID=178794,x=0.614,y=0.25,mapID=1961}},ends={{npcID=178794,x=0.614,y=0.25,mapID=1961}},coords={x=0.614,y=0.25,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Sweep the Windswept Aerie"},
[63787] = {id=63787,name="Continued Efforts: Mauler's Outlook",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="My Eyes tell me that the Mauler's Outlook is near the newly formed road from the Maw into Korthia . It would provide a strategic and tactical advantage. Unfortunately, the area is overrun with shardhides. If we can secure the area, it will provide us with a clear path to the west, as well as a point of observation to monitor the Jailer's forces.",rewardItems={185011,185012,185013,185014,185015,185016,185017,185018,185019,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1805,amount=175},{id=1907,amount=175}},starts={{npcID=179149,x=0.608,y=0.28,mapID=1961}},ends={{npcID=179149,x=0.608,y=0.28,mapID=1961}},coords={x=0.608,y=0.28,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Mauler's Outlook"},
[63788] = {id=63788,name="Continued Efforts: Sanctuary of Guidance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The attendant's home has been destroyed by the Jailer, but we can help them in this trying time. Nearby is the Sanctuary of Guidance. They speak of it with reverence and great sadness. It is a place they go to pray and seek truth. It's currently infested with devourers. Clear out the devourers, so they may once more seek solace in their rituals and prayers.",rewardItems={184983,184984,184985,184986,184987,184988,184989,184990,185009,186201,186205,186206,187184,187328,187334,187336,187466},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178800,x=0.616,y=0.236,mapID=1961}},ends={{npcID=178800,x=0.616,y=0.236,mapID=1961}},coords={x=0.616,y=0.236,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Sanctuary of Guidance"},
[63789] = {id=63789,name="Continued Efforts: Scholar's Den",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We cannot allow the mawsworn a foothold so close to our own encampment. The attendants say they keep this place hidden from eyes, but I will not rest easy while I can see them. Enter the Scholar's Den and cleanse the Jailer's forces from it.",rewardItems={185011,185012,185013,185014,185015,185016,185017,185018,185019,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178807,x=0.604,y=0.284,mapID=1961}},ends={{npcID=178807,x=0.604,y=0.284,mapID=1961}},coords={x=0.604,y=0.284,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Scholar's Den"},
[63790] = {id=63790,name="Broker's Bounty: Lord Azzorak",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A powerful dreadlord named Lord Azzorak is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Azzorak is a powerful foe. You may require several allies to slay him.",rewardItems={184374,185855,185856,185859,185860,185861,185862,185863,185865,185866,185867,185868,185869,185870,185872,185875,185877,185878,185880,185883,185884,185887,185888,185889,185890,185891,185893,185894,185895,185896,185897,185898,185899,185900,185901,185903,185905,185941,185944,186017,186156,186201,186205,186206,186664,186665,186666,186667,186668,186669,186670,186734,186735,186736,186737,186738,186739,186740,186741,186742,186743,186744,186745,186746,186747,186748,186750,186751,186752,186753,186754,186755,186757,186758,186759,186760,186761,186762,186763,186764,186765,186766,186767,186768,186769,186770,186771,186976,187506},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Lord Azzorak",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63791] = {id=63791,name="Broker's Bounty: Valdinar the Curseborn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A spike-armored Mawsworn named Valdinar the Curseborn is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Valdinar is a powerful foe. You may require several allies to defeat him.",rewardItems={184374,185855,185857,185859,185861,185863,185865,185867,185868,185870,185872,185873,185875,185877,185879,185880,185881,185883,185884,185885,185886,185887,185888,185893,185894,185896,185897,185898,185899,185900,185901,185903,185905,185941,185944,186017,186201,186205,186206,186664,186665,186666,186667,186668,186669,186670,186734,186735,186736,186737,186738,186739,186741,186742,186743,186744,186745,186746,186747,186748,186750,186751,186752,186753,186754,186755,186757,186758,186759,186760,186761,186765,186766,186769,186770,186771,187506},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Valdinar the Curseborn",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63792] = {id=63792,name="Broker's Bounty: Nocturnus the Unraveler",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A nefarious Maw magus named Nocturnus the Unraveler is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Nocturnus is a powerful foe. You may require several allies to defeat him.",rewardItems={184374,185856,185860,185861,185862,185866,185867,185868,185869,185873,185874,185875,185878,185879,185881,185882,185883,185884,185885,185886,185887,185888,185889,185890,185891,185894,185895,185896,185897,185898,185899,185900,185901,185903,185905,185941,185944,186017,186155,186156,186201,186205,186206,186663,186664,186665,186666,186667,186669,186670,186734,186735,186736,186737,186739,186740,186741,186742,186743,186744,186745,186747,186748,186749,186750,186751,186752,186753,186755,186756,186757,186758,186759,186760,186762,186763,186765,186766,186767,186768,186769,186770,186771,186976,187506},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Nocturnus the Unraveler",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63793] = {id=63793,name="Broker's Bounty: Ensydius the Defiler",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A winged Mawsworn named Ensydius the Defiler is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Ensydius is a powerful foe. You may require several allies to defeat him.",rewardItems={184374,185855,185857,185858,185859,185860,185861,185863,185864,185865,185866,185867,185868,185870,185871,185872,185873,185874,185875,185876,185877,185879,185880,185881,185882,185883,185884,185885,185886,185887,185888,185894,185895,185897,185898,185900,185901,185903,185905,185944,186017,186155,186156,186201,186205,186206,186663,186664,186666,186667,186668,186669,186734,186735,186736,186737,186738,186739,186740,186741,186742,186743,186744,186746,186747,186748,186749,186750,186751,186752,186754,186755,186756,186758,186759,186760,186762,186763,186765,186766,186767,186768,186769,186770,186771,186976,187506,187507},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Ensydius the Defiler",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63794] = {id=63794,name="Broker's Bounty: Hungering Behemoth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. We will provide a quantity of valuables to any interested party in return for a substantial amount of devourer blood , preferably the goliath kind. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",rewardItems={186245},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Hungering Behemoth",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63810] = {id=63810,name="Birds of a Feather",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have seen many ebon wings in the Maw, but never brilliant golden ones. Now that the aural sequencers are relaying information reliably, we should discover the source of these feathers. Follow the trail, Maw Walker. There is a mystery here... and very likely profit. Gold has value where you come from, does it not?",objectivesText="Follow the trail of golden feathers to find what dropped them.",rewardGold=257400,rewardXP=8165,starts={{npcID=179078}},ends={{npcID=177597}},coords={x=0.616,y=0.59,source="quest_giver",zoneID=11400},questType="standard"},
[63811] = {id=63811,name="A Hate-Hate Relationship",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1971,description="When the first of my sisters went missing, we were concerned. Those sent to find her did not return. Nor did the next. What we have discovered is a dreadful betrayal by someone we once trusted. Come, we must tell Odyn what we have witnessed in the Maw. His wrath will be great.",objectivesText="Accompany Danica to the Great Mead Hall and inform Odyn of Helya's actions. Progress: I do not fault the messenger, <name>.",rewardGold=257400,rewardXP=8165,starts={{npcID=177603}},ends={{npcID=177603}},questType="standard"},
[63822] = {id=63822,name="Venthyr Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13587,mapID=1543,rewardItems={185990,185996},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=177926,text="Report to Prince Renathal on top of the Tremaculum wall"},{orderIndex=0,type=0,amount=1,objectID=178164,text="Ask Burly Hurly to throw you"},{orderIndex=2,type=14,amount=1,objectID=92340,text="Help Venthyr and Night Fae forces assault the Tremaculum"},{orderIndex=3,type=0,amount=1,objectID=178242,text="Help Draven secure the upper platform"},{orderIndex=4,type=0,amount=1,objectID=178243,text="Travel through a Maw Mirror"},{orderIndex=6,type=0,amount=1,objectID=178245,text="Mirror 1"},{orderIndex=7,type=0,amount=1,objectID=178246,text="Mirror 2"},{orderIndex=8,type=0,amount=1,objectID=178247,text="Mirror 3"},{orderIndex=9,type=0,amount=1,objectID=178248,text="Mirror 4"},{orderIndex=10,type=0,amount=1,objectID=178249,text="Gothra the Trembler slain"},{orderIndex=5,type=0,amount=4,objectID=178244,text="Light directed into Maw Mirrors"}},worldTaskTitle="Venthyr Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63823] = {id=63823,name="Night Fae Assault",expansion=8,mapID=1543,rewardItems={185052,185991,186000,186190,186547},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=178847,text="Report to Lord Herne"},{orderIndex=1,type=14,amount=1,objectID=92329,text="Help Night Fae forces assault Crucible of the Damned"},{orderIndex=2,type=0,amount=1,objectID=178848,text="Listen to Lord Herne's plan"},{orderIndex=3,type=0,amount=1,objectID=178872,text="Ask Lady Moonberry for help"},{orderIndex=7,type=0,amount=1,objectID=178947,text="Bonesmith Heirmir rescued"},{orderIndex=6,type=0,amount=1,objectID=178983,text="Lord Herne rescued"},{orderIndex=8,type=0,amount=1,objectID=178984,text="Margrave Sin'dane rescued"},{orderIndex=9,type=0,amount=1,objectID=178985,text="Thiernax rescued"},{orderIndex=4,type=0,amount=1,objectID=179118,text="Use Distracting Illusion to turn the guard away from you"},{orderIndex=5,type=0,amount=1,objectID=179119,text="Sneak past the distracted guard into the darkness"}},worldTaskTitle="Night Fae Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63824] = {id=63824,name="Kyrian Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!",rewardItems={185720,185993,186546,187185},questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=178411,text="Fly with Xandria to attack Zovaal's Cauldron"},{orderIndex=3,type=15,amount=1,objectID=0,text="Summoning Ritual disrupted"},{orderIndex=9,type=0,amount=1,objectID=178460,text="Return to Cocyrus with Xandria"},{orderIndex=0,type=0,amount=1,objectID=177901,text="Report to Xandria in Cocyrus"},{orderIndex=1,type=14,amount=1,objectID=92351,text="Help Kyrian forces in Cocyrus and Zovaal's Cauldron"}},worldTaskTitle="Kyrian Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63827] = {id=63827,name="Encouraging Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Our forces have been battling relentlessly for hours. No doubt they grow tired and disheartened. Take this codex and recite the words within to our troops. Do not be fooled. Though the prose may seem meaningless, it holds immense power. Hearing these words will reinvigorate our exhausted Protectors with hope.",objectivesText="Recite the words within the codex to 8 Exhausted Protectors .",rewardItems={185775},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177900}},ends={{npcID=177900}},coords={x=0.428,y=0.448,source="quest_giver",zoneID=11400},questType="standard"},
[63828] = {id=63828,name="Mine's Bigger",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Jailer has deployed a large number of newly forged constructs to oppose our forces. Fortunately, I was completely prepared for this possibility. I have readied our largest Centurion to repel this threat. Please Maw Walker, ride with our Centurion and direct it in combat.",objectivesText="Use the Centurion Demolisher to eliminate the Jailer's constructs. Progress: Have we driven back their constructs?",rewardItems={181368,181377,181455,181509,181569,181570,181571,181574,181576,181577,181580,181589,181591,181596,181601,181604,181605,181608,181610,181614,181709,181745,182139,182304,182608,182769,183184,183488,183514,184294,184362,184363,184765,184766,184767,184768,184839,184840,190641},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177175}},ends={{npcID=177175}},coords={x=0.37,y=0.634,source="quest_giver",zoneID=11400},questType="standard"},
[63829] = {id=63829,name="No One Floats Down Here",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Now is our chance to free those we had assumed were lost! Many of our aspirants were seized by the Jailer to make troops for his army. Those that resisted him are locked in the cages that float above us, left there till their souls are broken. Shatter the Chains of Domination and free the Trapped Aspirants from the cages.",objectivesText="8 Trapped Aspirants rescued.",rewardItems={181368,181377,181569,181576,181577,181589,181591,181603,181612,181703,184294,184363,184765,184767,184768,184839},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177900}},ends={{npcID=177900}},coords={x=0.428,y=0.448,source="quest_giver",zoneID=11400},questType="standard"},
[63831] = {id=63831,name="Fury Given Voice",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1971,description="I will answer this attack upon my val'kyr with relentless fury! You have a vital role to play in this, <class>. You will muster the courage that you have demonstrated this day to lure my Eye to battle. But first, a simpler task ... the creation of the horn that will summon my wrath. Master Smith Helgar will guide you.",objectivesText="Assist Master Smith Helgar at the Forge of Odyn . Progress: Where is the horn that you have forged?",rewardItems={185967},starts={{npcID=177726}},ends={{npcID=177726}},questType="standard"},
[63833] = {id=63833,name="Terrorizing the Tremaculum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13587,mapID=1543,description="I am certain that my compatriots and generals have more specific tasks they require of you. But my request is simple. Our enemies currently surround us on all sides. Push them back and give us more room to operate.",objectivesText="Kill 30 enemies in the Tremaculum. Progress: Our enemies surround us on all sides. You need not search far.",rewardItems={181176,181179,181185,181186,181199,181200,181202,181211,181212,181224,181504,181545,181546,181547,181548,181550,182724,184147,184150,184777,185854},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178006}},ends={{npcID=178228}},coords={x=0.3,y=0.17,source="quest_giver",zoneID=11400},questType="standard"},
[63834] = {id=63834,name="Weapons of the Tremaculum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="The venthyr of Sinfall do not waste souls, and her stoneborn do not waste armaments. Retrieve the tools of our enemies so that we may repurpose them for our army.",objectivesText="Collect 6 Mawsworn Weapons , 6 Ghastly Crowns , and 6 Shade Eyes . Progress: Every weapon can be made to serve.",rewardItems={185911,185912,185913},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178066}},ends={{npcID=178228}},coords={x=0.3,y=0.17,source="quest_giver",zoneID=11400},questType="standard"},
[63835] = {id=63835,name="Wrath of the Party Herald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Oh, you're back so soon, $p! ...Or have we not already met? It is difficult to remember at times... Regardless, I trust you are making progress with Cryptkeeper Kassir's plan to weaken our adversaries. Details of the plan escape me, but I am certain Temel was involved. I hear he fancies himself a \"party herald\" nowadays... The Curator looks beyond you for a moment.> \"Party herald\"... I must have been gone from Revendreth for longer than I thought.",objectivesText="Help Temel, the Party Herald, throw poison bombs at 50 enemies in the Tremaculum. Progress: You can find Temel on the ramparts near the Curator .",rewardItems={180847,181175,181185,181192,181193,181200,181201,181205,181206,181217,181467,181510,181545,181546,181547,181548,181550,181708,181827,181836,182109,182325,182448,182449,182480,183469,183499,184147,184150,184777,185942},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178078}},ends={{npcID=178006},{npcID=178228}},coords={x=0.302,y=0.168,source="quest_giver",zoneID=11400},questType="standard"},
[63836] = {id=63836,name="Fangcrack's Fan Club",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Fangcrack is the strongest dredger I e'er seen! He's incredible! He's down there, reaching into dat big Torghast portal, pulling the baddies right out o' their home! They don't even know what's happenin' half the time, ha ha! Me and Cudgelface joined his fan club soon as we got here. You want in? You gotta earn your membership same as everyone else: go down there and fight whatever he pulls out of the portal!",objectivesText="Kill 12 Torghast enemies pulled out of the portal by Fangcrack. Progress: Looking for Fangcrack? Follow the cheering of his fans.",rewardItems={181175,181176,181180,181182,181185,181188,181194,181197,181198,181200,181204,181205,181206,181545,181546,181547,181548,181550,181708,184147,184150,184777},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178112}},ends={{npcID=178228}},coords={x=0.312,y=0.154,source="quest_giver",zoneID=11400},questType="standard"},
[63837] = {id=63837,name="A Tea for Every Occasion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="My dear $p! I knew you would arrive in the nick of time to save us all from the brink of boredom! I was just telling Niya here about the time you saved me from the Ember Ward through the healing power of tea! She is a bit skeptical. Perhaps you can help Tubbins and Gubbins show her that, through tea, all things are possible!",objectivesText="Help Tubbins and Gubbins deliver tea to 15 allies in the Tremaculum. Progress: Tubbins is up on the ramparts with Theotar .",rewardItems={181176,181177,181182,181183,181190,181192,181193,181198,181199,181205,181206,181210,181211,181545,181546,181547,181548,181550,184147,184150,184777,185942},rewardCurrencies={{id=1807,amount=175},{id=1877,amount=1}},starts={{npcID=178178}},ends={{npcID=178006},{npcID=178228}},coords={x=0.296,y=0.178,source="quest_giver",zoneID=11400},questType="standard"},
[63838] = {id=63838,name="Duelist's Challenge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="As you can see, we have our hands full here on the barricade. I will hold the line while you challenge the champions of the Mawsworn army. Defeat them in full view of their underlings. No mercy, $p. Demoralize them.",objectivesText="Ask Boot the Beaut to throw you to the upper ramparts, then duel the champions of the Mawsworn army. Progress: Boot the Beaut can throw you up to the ramparts if needed.",rewardItems={181179,181181,181186,181187,181192,181195,181202,181203,181211,181217,181469,181545,181546,181547,181548,181550,181866,182127,182667,182724,183132,184147,184150,184777,185854},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178105}},ends={{npcID=178228}},coords={x=0.314,y=0.15,source="quest_giver",zoneID=11400},questType="standard"},
[63839] = {id=63839,name="If Even One is Worthy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have seen firsthand that worthy souls have been unjustly cast into the Maw. Gresit here was almost cast in himself by the Lord Chamberlain's minion. He has more than proven himself under my care. Look among the souls that the Jailer's filth have deemed \"unworthy\". Inspect each to confirm that they deserve their fate. Even if we examine every soul in the Tremaculum and find only a single worthy one to bring back to Revendreth, it will still be valuable.",objectivesText="Inspect Unworthy Souls in the Tremaculum until you find one that is truly worthy.",rewardItems={180847,180943,181176,181177,181178,181181,181182,181183,181184,181187,181189,181192,181193,181195,181196,181198,181200,181203,181204,181212,181215,181218,181334,181467,181498,181506,181545,181546,181547,181548,181550,181708,181842,182126,182338,182460,182480,182584,182648,182736,182750,183476,183482,183500,183502,184147,184150,184587,184777},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178063}},ends={{npcID=178228}},coords={x=0.308,y=0.16,source="quest_giver",zoneID=11400},questType="standard"},
[63840] = {id=63840,name="They Grow Up So Quickly",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I know what you're thinking, but I have these gormlings completely under control! I picked up a trick or two at the venthyr's Ember Court for suppressing and controlling these troublemakers. If you wish to use their power to aid our battle, I will loan you my staff. With it you can choose a gormling that can be ordered to feed on the corpses of our enemies and grow in strength and size. You won't need many. Gormling grow quickly.",objectivesText="Grow a gormling by feeding it corpses and ride it to victory! Progress: If you have lost your gormling, Niya up on the ramparts will have found it.",rewardItems={186089},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178179}},ends={{npcID=178715}},coords={x=0.296,y=0.18,source="quest_giver",zoneID=11400},questType="standard"},
[63841] = {id=63841,name="The Skyhunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Boot the Beaut and the other large dredgers are being hit hard from air assaults. The dredgers may not be able to reach them, but the Wild Hunt can reach any prey. Take my spear and use it to ground the Mawsworn in the sky above the western bridge. Once they are grounded, they will be easy to dispatch. My trappers will help slow them down for you.",objectivesText="Use Korayn's Spear to pull 8 Mawsworn Skylurkers to the ground and kill them. Progress: The Mawsworn flyers appear to be focusing their attention on the western bridge.",rewardItems={185949},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178180}},ends={{npcID=178228}},coords={x=0.294,y=0.18,source="quest_giver",zoneID=11400},questType="standard"},
[63842] = {id=63842,name="That's a Good Trick",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="These cruel tormentors make me so mad... The Jailer's bullies torture good souls sent here unjustly because no one will stand up to them! Well, I am here now, and I have the perfect plan to make them pay. What do you say? Want to help me turn the tables on these bullies?",objectivesText="Shrink 15 enemies and enlarge 4 Mawrats to eat them in the Tremaculum! Progress: Well, if Lady Moonberry thinks it wise...",rewardItems={186102},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178172}},ends={{npcID=178228}},coords={x=0.298,y=0.17,source="quest_giver",zoneID=11400},questType="standard"},
[63843] = {id=63843,name="Heart and Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Forsworn that serve the Jailer dominate the skies above, but we know their weakness and shall use it against them. Under my direction Mikanikos has created a supply of Trueheart Spears for our Protectors. When hit by these spears the Mawsworn will be weakened with their soul laid bare as they face their true self. Collect the Trueheart Spears and use them to defeat the Mawsworn Myrmidons that fly above us.",objectivesText="Collect 6 Trueheart Spears and defeat 6 Mawsworn Myrmidons . Progress: Have the Forsworn been defeated?",rewardItems={185829},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177226}},ends={{npcID=177900}},coords={x=0.37,y=0.632,source="quest_giver",zoneID=11400},questType="standard"},
[63844] = {id=63844,name="The Chosen Few",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1971,description="I have need of more val'kyr to join Danica in the battle to come. , you are granted the honor of choosing the most worthy. The strongest will present themselves in challenge at the Circle of Glory. Fight hard, , and do honor to your weapons.",objectivesText="Go to the Circle of Glory and fight the val'kyr to determine which are most worthy. Progress: Have the worthy been selected?",rewardGold=257400,rewardXP=8165,starts={{npcID=177726}},ends={{npcID=177726}},questType="standard"},
[63845] = {id=63845,name="Wrath of Odyn",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1971,description="The horn has been forged and the worthy have been selected. Now, <name>, we have only to bind my chosen val'kyr to the horn and infuse them with my power that they may strike with my fury. Come, bear witness.",objectivesText="Bear witness to the empowerment of the chosen val'kyr and the binding of the Ilskahorn Progress: Yes? Did you have a question?",starts={{npcID=177726}},ends={{npcID=177726}},questType="standard"},
[63846] = {id=63846,name="The Ember Count",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Theotar's brilliance is undeniable, but far too many overlook the ingenuity of his dredger helpers, Gubbins and Tubbins. Look to that ridge beyond us. The Jailer's forges over there are spewing out Soulsteel Embers . We could accomplish many things with a mirror made from them... Gubbins has already crafted a special parasol, capable of shielding its wielder from any falling embers. Meet him by the forges and obtain some of those Soulsteel Embers !",objectivesText="Slay 4 Enraged Forgeshard and Collect 4 Soulsteel Embers . Progress: Have you acquired the embers?",rewardItems={185839},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178091}},ends={{npcID=178091}},coords={x=0.43,y=0.442,source="quest_giver",zoneID=11400},questType="standard"},
[63848] = {id=63848,name="A Show of Gratitude",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Your presence here fulfils an ancient prophecy, Maw Walker. I am certain you and your allies will save us. Perhaps I judged your broker friend too harshly. She did escort you to Korthia , after all. Please extend our thanks to Ve'nari , and let her know we are happy to answer her questions. She... does seem to have quite a number of them.",objectivesText="Speak with Ve'nari at Keeper's Respite in Korthia .",rewardGold=25740,rewardXP=1020,starts={{npcID=177927}},ends={{npcID=178470}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[63849] = {id=63849,name="Hearing Aid",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="How fortuitous! You just happened to be transferred to a location in which I have a certain... interest. Place the aural sequencers I gave you and I will attempt to establish a functional signal. Such a perilous location will require the utmost discretion. You will want to use your ethereal cloak to avoid being seen.",objectivesText="Place the Aural Sequencers in Desmotaeron to help Ve'nari eavesdrop on the inhabitants.",rewardGold=257400,rewardXP=8165,starts={{npcID=179078}},ends={{npcID=179078}},coords={x=0.616,y=0.59,source="quest_giver",zoneID=11400},questType="standard"},
[63853] = {id=63853,name="Kill the Flame",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Can you see it? Just out of the corner of my eye, it's always there... glowing so brightly! How is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around. Please Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!",objectivesText="Kill Infernus the Infinite for Theotar . Progress: Have you killed that dreadful creature?",rewardItems={180943,181178,181184,181191,181193,181196,181545,181546,181547,181548,181550,181640,181708,181842,182338,182584,183468,183470,184147,184150,184587,185942},rewardCurrencies={{id=1807,amount=175}},starts={{npcID=178005}},ends={{npcID=178005}},coords={x=0.43,y=0.444,source="quest_giver",zoneID=11400},questType="standard"},
[63855] = {id=63855,name="Ease of Passage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1961,description="Korthia is ripe with opportunity. Look at all of these intriguing objects. In anticipation of such wonders, I have come prepared. Let us find a suitable location and establish a more permanent connection between this place and my refuge. Our work together is not yet finished.",objectivesText="Establish a connection between Korthia and Ve'nari 's Refuge. Progress: I'll take my bag now, if you have it.",rewardItems={185966},starts={{npcID=178470}},ends={{npcID=162804}},coords={x=0.658,y=0.23,source="quest_giver",zoneID=13570},questType="standard"},
[63856] = {id=63856,name="A Gathering of Covenants",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1673,description="Though the Jailer remains confined to the Maw, his cruelty extends beyond the bounds of his prison. Thankfully, the Archon is recovering from the attack. Though I am told her wound has an... unsettling quality. The Eternal Ones and their allies await you and Highlord Fordragon in the Arbiter's chamber. I shall open the way. With her voice have I spoken.",objectivesText="Speak to Tal-Inara to enter the Arbiter's chambers.",rewardGold=25740,rewardXP=1020,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[63857] = {id=63857,name="Voices of the Eternal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="This chamber is... truly wondrous. Yet there is no time to be awestruck. The Honored Voice must begin this meeting at once.",objectivesText="Listen to the plan.",rewardGold=128700,rewardXP=4085,starts={{npcID=159475}},ends={{npcID=159475}},questType="standard"},
[63858] = {id=63858,name="Courage of the Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="In this time of conflict, we are all tested, Maw Walker. It takes great bravery and strength of soul to confront our enemies without fear. Wade into their lines and show them the power of your courage.",objectivesText="Eliminate 15 of the Jailer's forces in Cocyrus and Zovaal's Cauldron.",rewardItems={181368,181377,181435,181569,181571,181572,181574,181577,181580,181581,181585,181589,181591,181594,181596,181599,181602,181604,181605,181606,181608,181609,181611,181614,181627,181630,181632,181633,181635,181636,181637,181702,181703,181704,181745,182584,183476,184294,184362,184765,184766,184767,184768,184839,190641},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=178227}},ends={{npcID=177900}},coords={x=0.424,y=0.44,source="quest_giver",zoneID=11400},questType="standard"},
[63859] = {id=63859,name="Saved By The Bells",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Our stewards are preparing Reinforcement Bells to summon additional Kyrian to aid in our assault. However, the Mawsworn have been attacking the stewards in order to disrupt their efforts. We need you to defend our stewards while they complete their work, then ring each bell to call in reinforcements.",objectivesText="Defend and ring the Reinforcement Bell West , East, and South.",rewardItems={181377,181573,181574,181575,181576,181583,181585,181587,181601,181602,181603,181609,181610,181611,181612,181614,181627,181628,181629,181630,181631,181632,181634,181636,181637,181745,182336,182441,184294,184362,184363,184765,184766,184767,184768,184839,184840},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=177900}},ends={{npcID=177900}},coords={x=0.428,y=0.448,source="quest_giver",zoneID=11400},questType="standard"},
[63860] = {id=63860,name="Talisman of the Eternal Scholar",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this talisman in the Reliquary of Remembrance.>",objectivesText="Bring the Damaged Talisman to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={185914},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=368302}},ends={{npcID=178257}},coords={x=0.406,y=0.414,source="quest_giver",zoneID=13570},questType="standard"},
[63861] = {id=63861,name="Beginning the Collection",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Let us continue our work by retrieving the most important item of any scholarly study--the lost codex. It will take some time, but as we continue our work the pages of this work will continue to grow and flourish, just as Korthia has itself for eons. As for its location, it previously resided deep within the underbelly of Korthia itself inside the Cavern of Contemplation to the south. We can only hope the Jailer's forces have yet to locate it.",objectivesText="Recover the Codex of Memories for Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Have you found the codex? I hope we're not too late.",rewardItems={185636,185916},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=178257}},ends={{npcID=178257}},coords={x=0.626,y=0.224,source="quest_giver",zoneID=13570},questType="standard"},
[63863] = {id=63863,name="United In Pride",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Despite our competitive differences, Nemea and I work as a team when faced with greater threats. The pride and the phalynx are both fierce fighters upon the battlefield. We would both be honored to assist you in the battle that lies ahead. Please allow either Andira or Gatamatos to assist you in defeating the Jailer's champions that threaten our forces.",objectivesText="Defeat Malfestus , Domonous , and Furis. Progress: With those champions defeated our forces can push forward.",rewardItems={181368,181377,181569,181573,181574,181583,181585,181602,181610,181611,181628,181629,181630,181631,181632,181634,181745,182107,182307,182469,182743,183467,183479,183483,184294,184362,184363,184765,184766,184767,184768},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=178353}},ends={{npcID=177900}},coords={x=0.428,y=0.454,source="quest_giver",zoneID=11400},questType="standard"},
[63864] = {id=63864,name="The Dreadful Blend",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Gravedust and Stipple Weed is a dreadful flavor combination, and Tubbins made a very large batch of tea with those ingredients. It was so horrid that I tossed the entire pot of tea on the fire. It turns out to be very wet, and an excellent extinguisher of flames! Tubbins will haul the entire batch with you. Put it to good use, by tossing it on the Volatile Embersparks around Zovaal's Cauldron.",objectivesText="Extinguish 30 Volatile Embersparks . Progress: Please, I hope you did not drink that.",rewardItems={181175,181177,181183,181184,181185,181190,181191,181192,181193,181199,181200,181201,181205,181206,181211,181224,181545,181546,181547,181550,184147,184150,184777},rewardCurrencies={{id=1807,amount=175},{id=1877,amount=1}},starts={{npcID=178005}},ends={{npcID=178005}},coords={x=0.43,y=0.444,source="quest_giver",zoneID=11400},questType="standard"},
[63867] = {id=63867,name="Anger Management",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I am no musician, though I've spent many an hour enjoying the entertainment in Tazavesh. Giving this horn a voice will require the harvest of strong emotions. Anger seethes unrestrained within the damned unfortunates consigned to the River of Souls. Use this siphoning device to drain the rage of these furious shades into your instrument. The shrieks of fury that you acquire should allow you to pierce the Maw and reach your allies. The tune, I suspect, will not be a popular one.",objectivesText="Use the siphoning device to drain rage from the Furious Shades in the River of Souls.",rewardGold=257400,rewardXP=8165,rewardItems={186094},starts={{npcID=162804}},ends={{npcID=179078}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[63892] = {id=63892,name="Diviner's Rune Chits",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="rune chit . It rotates and flips as if moved by an unseen hand. Runes vaguely reminiscent of the Vrykul language are delicately carved into the stone. On the back of the chit is an indication that it is part of a set.>",objectivesText="Collect 20 rune chits , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Goodness, is that a pouch of rune chits ? How many do you have?",rewardItems={185962,185963,187154},rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63895] = {id=63895,name="Grab Bag",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Interesting. Aural sequencers and an ethereal cloak. You hang on to those, . I have a suspicion they will prove useful. Ah, and something special for me as well. If I'm not mistaken--and I so rarely am--this is a projection mechanism. Very handy! And what's this? A transportation device of some kind. We should test it immediately. By \"we,\" of course I mean you.",objectivesText="Test the transportation device from Ve'nari 's bag.",rewardGold=257400,rewardXP=8165,rewardItems={186201},starts={{npcID=162804}},ends={{npcID=179078}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[63896] = {id=63896,name="Tears of the Damned",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="To anchor the instrument to the Maw and make it capable of the effect you seek, it must be imbued with the raw, unfiltered agony endured by the souls trapped in this cursed prison. Sorrow is abundant here, and therefore simple to obtain. You need only travel to Gorgoa. The damned shed copious tears that fall as crystalized grief as they are swept along the River of Souls. Be careful that their sadness does not overwhelm you.",objectivesText="Collect 10 Tears of the Damned from Gorgoa: The River of Souls. Progress: Have you collected the tears?",rewardGold=257400,rewardXP=8165,starts={{npcID=162804}},ends={{npcID=179078}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="standard"},
[63899] = {id=63899,name="Book of Binding: The Mad Witch",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="crimson pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>",objectivesText="Collect 12 Crimson Pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that book... speaking?",rewardItems={185971,187206},rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63901] = {id=63901,name="Focusing the Eye",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="The combination of grief and rage you have harvested is sufficient for your needs. Most likely. If you insist on seeing this ill-advised endeavor through, use the horn at the Terminus Platform, where the River of Souls flows upward to Torghast. The energies there are most potent indeed. The presence of your golden allies should draw the Jailer's Eye. I only hope this does not prove to be the end of you. I hate to see an investment wasted.",objectivesText="Go to the Terminus Platform and use the Ilskahorn to summon the Wrath of Odyn.",rewardGold=257400,rewardXP=8165,starts={{npcID=179078}},ends={{npcID=178950}},coords={x=0.616,y=0.59,source="quest_giver",zoneID=11400},questType="standard"},
[63902] = {id=63902,name="Good News, Everyone!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="Come, friend. Let us be rid of this foul place. No doubt your comrades will be eager to hear the news of the defeat of the Eye. I will bear you to them. Give the word when you are ready to depart, .",objectivesText="Fly with Danica to Korthia to give Bolvar the news. Progress: What has happened?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=178950}},ends={{npcID=177228}},coords={x=0.37,y=0.194,source="quest_giver",zoneID=11400},questType="standard"},
[63903] = {id=63903,name="Storming the Sanctum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Jailer has seized the sigils of all four covenants. It is clear he means to escape the Maw and steal the Arbiter's sigil from Oribos. We cannot allow this to happen. Atop Torghast sits the Sanctum of Domination , the Jailer's seat of power. The time has come to enter this dark domain. No doubt Sylvanas Windrunner will command the forces that will attempt to thwart us. We must defeat her... and save Anduin Wrynn from her grasp. Gather your forces, . The Ebon Blade will stand with you.",objectivesText="Defeat Sylvanas Windrunner in the Sanctum of Domination . Progress: How fares the battle in the Sanctum?",rewardGold=772200,rewardXP=12250,rewardItems={187175},starts={{npcID=177228}},ends={{npcID=177228}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="raid"},
[63904] = {id=63904,name="The Heart of Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I hid my sigil in the Heart of the Forest, to keep it safe from the forces of the Maw. But the horn has called for aid. You and your allies go, see what has prompted the call.",objectivesText="Investigate the Heart of the Forest. Progress: Is my sigil safe?",rewardGold=128700,rewardXP=4085,rewardItems={184379},starts={{npcID=177460}},ends={{npcID=177460}},coords={x=0.47,y=0.486,source="quest_giver",zoneID=11510},questType="standard"},
[63908] = {id=63908,name="Bulwark of Divine Intent",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this shield in the Reliquary of Remembrance.>",objectivesText="Bring the Bulwark of Divine Intent to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={186014},rewardCurrencies={{id=1931,amount=750}},starts={{npcID=368438}},ends={{npcID=178257}},coords={x=0.179,y=0.356,source="quest_giver",zoneID=13570},questType="standard"},
[63909] = {id=63909,name="Guise of the Changeling",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this mask in the Reliquary of Remembrance.>",objectivesText="Bring the Guise of the Changeling to Archivist Roh-Suir in the Reliquary of Remembrance.",rewardItems={187155},rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63910] = {id=63910,name="The Netherstar",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<You recognize this relic from the Archivists' Codex. The power source is nearly empty. However, it could be restored with exposure to raw, unfiltered anima. Nearby fissures would do the trick.>",objectivesText="Recharge the Netherstar , then bring it to Archivist Roh-Suir in the Reliquary of Remembrance.",rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63911] = {id=63911,name="Singing Steel Ingot",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Woe! These ruffians hammer upon me with nary a care, bending my body to suit their ill aims. Fie! Fie upon them. Take the hammering to these mawsworn!",objectivesText="Defeat mawsworn invaders, then bring the Singing Steel Ingot to Archivist Roh-Suir in the Reliquary of Remembrance.",rewardItems={187200},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=369254}},ends={{npcID=178257}},coords={x=0.621,y=0.569,source="quest_giver",zoneID=13570},questType="standard"},
[63912] = {id=63912,name="Celestial Shadowlands Chart",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<You recognize this relic from the Archivists' Codex. The mawsworn discarded it, believing it to be useless. And the chart is useless, without the accompanying data to plot the relative locations of Shadowlands afterlives. If the research were retrieved from deceased scholars, the chart could be returned to the Archivist, fully functional.>",objectivesText="Collect 6 Afterlife Navigation Research scrolls, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that the missing chart?",rewardItems={185757,187201},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=369257}},ends={{npcID=178257}},coords={x=0.455,y=0.56,source="quest_giver",zoneID=13570},questType="standard"},
[63913] = {id=63913,name="Unstable Explosive Orb",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>",objectivesText="Bring the Unstable Explosive Orb to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187202},rewardCurrencies={{id=1931,amount=500}},starts={{npcID=179902}},ends={{npcID=178257}},coords={x=0.514,y=0.202,source="quest_giver",zoneID=13570},questType="standard"},
[63914] = {id=63914,name="Cipher of Understanding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for the cipher in the Reliquary of Remembrance.>",objectivesText="Bring the Cipher of Understanding to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187203},rewardCurrencies={{id=1931,amount=500}},starts={{npcID=179922}},ends={{npcID=178257}},coords={x=0.288,y=0.542,source="quest_giver",zoneID=13570},questType="standard"},
[63915] = {id=63915,name="Drum of the Death Loa",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this drum in the Reliquary of Remembrance.>",objectivesText="Bring the Drum of the Death Loa to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187204},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=369287}},ends={{npcID=178257}},coords={x=0.523,y=0.341,source="quest_giver",zoneID=13570},questType="standard"},
[63916] = {id=63916,name="Sack of Strange Soil",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this soil in the Reliquary of Remembrance.>",objectivesText="Bring the Sack of Strange Soil to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187205},rewardCurrencies={{id=1931,amount=250}},starts={{npcID=369288}},ends={{npcID=178257}},coords={x=0.553,y=0.286,source="quest_giver",zoneID=13570},questType="standard"},
[63917] = {id=63917,name="Everliving Statuette",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this statuette in the Reliquary of Remembrance.>",objectivesText="Bring the Everliving Statuette to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63918] = {id=63918,name="Obelisk of Dark Tidings",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this obelisk in the Reliquary of Remembrance.>",objectivesText="Bring the Obelisk of Dark Tidings to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63919] = {id=63919,name="Book of Binding: The Tormented Sorcerer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="azure pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>",objectivesText="Collect 10 azure pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: I find these strange speaking tomes... discomfiting.",rewardItems={187117,187210},rewardCurrencies={{id=1931,amount=500}},starts={{npcID=179956}},ends={{npcID=178257}},coords={x=0.608,y=0.348,source="quest_giver",zoneID=13570},questType="standard"},
[63920] = {id=63920,name="Enigmatic Decrypting Device",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>",objectivesText="Bring the Enigmatic Decrypting Device to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187207},rewardCurrencies={{id=1931,amount=500}},starts={{npcID=179968}},ends={{npcID=178257}},coords={x=0.518,y=0.524,source="quest_giver",zoneID=13570},questType="standard"},
[63921] = {id=63921,name="Ring of Self-Reflection",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this ring in the Reliquary of Remembrance.>",objectivesText="Bring the Ring of Self-Reflection to Archivist Roh-Suir in the Reliquary of Remembrance.",rewardItems={187140},rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63922] = {id=63922,name="Shadow Slicing Shortsword",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this shortsword in the Reliquary of Remembrance.>",objectivesText="Bring the Shadow Slicing Shortsword to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187159,187208},rewardCurrencies={{id=1931,amount=750}},starts={{npcID=369319}},ends={{npcID=178257}},coords={x=0.365,y=0.461,source="quest_giver",zoneID=13570},questType="standard"},
[63923] = {id=63923,name="Lang Family Wood-Carving",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this wood-carving in the Reliquary of Remembrance.>",objectivesText="Bring the Lang Family Wood-Carving to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:",rewardItems={187209},rewardCurrencies={{id=1931,amount=750}},starts={{npcID=369342}},ends={{npcID=178257}},coords={x=0.256,y=0.604,source="quest_giver",zoneID=13570},questType="standard"},
[63924] = {id=63924,name="Gorak Claw Fetish",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Archivist Roh-Suir has a spot for this fetish in the Reliquary of Remembrance.>",objectivesText="Bring the Gorak Claw Fetish to Archivist Roh-Suir in the Reliquary of Remembrance.",rewardCurrencies={{id=1931,amount=250}},ends={{npcID=178257}},coords={mapID=1961,source="quest_giver",x=0.6205,y=0.2215},questType="standard"},
[63934] = {id=63934,name="Assail Mail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, mortal! I am on a mission to deliver messages to our allies here in exciting Korthia . However, I was unable to complete my task. The messages I was programmed to transport were stolen by Mawsworn, and then incorrectly stored all over the ground. Would you collect the messages and return them to me? I will then see them delivered to their intended recipients. Thank you!",rewardItems={186164},rewardCurrencies={{id=1804,amount=175}},starts={{npcID=178802,x=0.614,y=0.224,mapID=1961}},ends={{npcID=178802,x=0.614,y=0.224,mapID=1961}},coords={x=0.614,y=0.224,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Assail Mail"},
[63935] = {id=63935,name="Precious Roots",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Korthia . A sister forest, stricken. But in the throes of destruction, there is still hope. Gather the anima, and build anew.",rewardItems={186165},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178842,x=0.61,y=0.214,mapID=1961}},ends={{npcID=178842,x=0.61,y=0.214,mapID=1961}},coords={x=0.61,y=0.214,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Precious Roots"},
[63936] = {id=63936,name="Devoured Anima",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Sika has idea! Devourers... devour. They eat anything! So they eat anima, too. If we take anima from devourers, then that anima is ours!",rewardItems={186166},rewardCurrencies={{id=1804,amount=175},{id=1907,amount=175}},starts={{npcID=178797,x=0.616,y=0.238,mapID=1961}},ends={{npcID=178797,x=0.616,y=0.238,mapID=1961}},coords={x=0.616,y=0.238,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Devoured Anima"},
[63937] = {id=63937,name="Nasty, Big, Pointy Teeth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There's tons of interesting things to kill out here! Bears, birds, mawsworn, and gromits! Let's start with the gromits shall we? Go slaughter the fierce gromits in the Mauler's Outlook and bring me their FANGS! I can always use more teeth.",rewardItems={186095},rewardCurrencies={{id=1805,amount=175},{id=1907,amount=175}},starts={{npcID=178805,x=0.6,y=0.274,mapID=1961}},ends={{npcID=178805,x=0.6,y=0.274,mapID=1961}},coords={x=0.6,y=0.274,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Nasty, Big, Pointy Teeth"},
[63944] = {id=63944,name="Korthia Awaits",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ready yourself, . Our allies await your arrival in Korthia .",objectivesText="Report to Tal-Galan at Keeper's Respite in Korthia .",rewardGold=25740,rewardXP=1020,starts={{npcID=164079}},ends={{npcID=177927}},questType="standard"},
[63945] = {id=63945,name="The Soul Blade",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The runeblade of a Necrolord can be a potent weapon in this realm. An abundance of souls are willing to contribute their anima to end their own suffering and bring defeat to the Jailer. Take one of my runeblades and charge it with the anima of the willing souls you find here. Once charged, use it lay waste to their forces here.",objectivesText="Charge Heirmir's Runeblade with Willing Souls and use it to slay the Eye of Gorgoa . Progress: Has my blade tasted victory?",rewardItems={186097},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=178690}},ends={{npcID=178887}},coords={x=0.222,y=0.436,source="quest_giver",zoneID=11400},questType="standard"},
[63949] = {id=63949,name="Shaping Fate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1961,description="The Jailer's power and malevolence continue to grow. So must our resilience. Stand amongst your allies, . Push back against the darkness that would consume us all. Together, we will yet prevail. May the Purpose guide your hand.",rewardItems={186196,187506},rewardCurrencies={{id=1822,amount=1},{id=1977,amount=10}},starts={{npcID=177927,x=0.628,y=0.248,zoneID=13570}},ends={{npcID=177927,x=0.628,y=0.248,zoneID=13570}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Shaping Fate"},
[63950] = {id=63950,name="Razorwing Talons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="These lands are not well known yet by my hunters, but we have discovered formidable beasts that reside here. Among these are the Razorwing: vicious predators with terrible talons... and the temper of a vorkai. Bring me some of their talons to help teach our newest hunters about the kinds of beasts they will face.",rewardItems={186105},rewardCurrencies={{id=1806,amount=175},{id=1907,amount=175}},starts={{npcID=178837,x=0.614,y=0.212,mapID=1961}},ends={{npcID=178837,x=0.614,y=0.212,mapID=1961}},coords={x=0.614,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Razorwing Talons"},
[63951] = {id=63951,name="A Shady Place",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1543,description="Existence is not a simple thing, $p. It is layers upon layers of realities. The Jailer's traps are pulling our troops into one such rift, hidden from normal sight. I have obtained an Unbalanced Riftstone . It will give you the ability to enter the rift and destroy the traps keeping our troops trapped inside, before they are lost forever. After you've destroyed the Rift-Veiled Traps , exit the rift and pull the trapped soldiers back into our reality.",objectivesText="Use the Unbalanced Riftstone to enter the rift and break Rift-Veiled Traps to free $1a Riftbound Vorkai . Progress: There is much we cannot see.",rewardItems={187012},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=178890}},ends={{npcID=178890},{npcID=178891}},coords={x=0.224,y=0.432,source="quest_giver",zoneID=11400},questType="standard"},
[63952] = {id=63952,name="Heavy-Handed Tactics",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="We need more constructs on the front lines, but we have no bodies, heads, or legs! Rathan's making the best constructs possible with what we DO have... a lot of hands. Don't ask questions! There are enemies in Calcis that we need dead. Take the hands and kill things!",objectivesText="Slay 8 Mawsworn Soulbreakers , 4 Crystalline Guardians , Lady Nalis , and Glassmaker . Progress: Rathan is nothing if not resourceful.",rewardItems={181503,181507,181625,181647,181649,181656,181657,181658,181659,181685,181688,181691,184305,184772,184773,184774,184775,184776},rewardCurrencies={{id=1805,amount=175}},starts={{npcID=178745}},ends={{npcID=178891}},coords={x=0.228,y=0.424,source="quest_giver",zoneID=11400},questType="standard"},
[63953] = {id=63953,name="Korrak's Revenge",level=1,requiredLevel=1,faction="none",expansion=8,rewardItems={172022,172023},rewardCurrencies={{id=1166,amount=200}},questType="standard",worldTaskTitle="Korrak's Revenge",db2QuestInfoID=283,db2QuestInfoName="Bonus Objective with Completion Toast"},
[63954] = {id=63954,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in Seeker's Quorum. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",rewardItems={186167},starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63955] = {id=63955,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup outside of the Vault. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",rewardItems={186174},starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63956] = {id=63956,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Windswept Aerie. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",rewardItems={186173},starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63957] = {id=63957,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Seeker's Quorum records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",rewardItems={186168},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63958] = {id=63958,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from outside the Vault should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring that data to me, and I will reward you handsomely.",rewardItems={186169},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63959] = {id=63959,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Sanctuary of Guidance records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",rewardItems={186171},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63960] = {id=63960,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. And don't forget to look below ground! Bring those data to me, and I will reward you handsomely.",rewardItems={186170},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63961] = {id=63961,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in Mauler's Outlook. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",rewardItems={186175},starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63962] = {id=63962,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records at Mauler's Outlook should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",rewardItems={186172},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63963] = {id=63963,name="Broker's Bounty: Ripmaul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",rewardItems={187238},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Ripmaul",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63964] = {id=63964,name="Broker's Bounty: Grimtalon",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for an intact boney beak from the beast known as Grimtalon. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",rewardItems={187239},starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Grimtalon",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63965] = {id=63965,name="Razorwing Egg Rescue",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I'm amazed by the wildlife here in Korthia ! So many interesting creatures... Say, you know those flying beasts with the claws, the Razorwing? They sometimes knock their eggs out of their nests, and then they completely ignore them! If you find any abandoned eggs, could you bring them to me? Gently, of course. I wonder if they can be raised to be friendly? If not, well, it wouldn't be the first time I've had my antennae chewed on.",rewardItems={182180,184948,184949,184950,184951,184952,184953,184954,184955,184956,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178839,x=0.614,y=0.214,mapID=1961}},ends={{npcID=178839,x=0.614,y=0.214,mapID=1961}},coords={x=0.614,y=0.214,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Razorwing Egg Rescue"},
[63968] = {id=63968,name="Clean Out the Crucible",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Winter Queen has called a hunt. We will ensure that the Crucible of the Damned is rid of the Jailer's forces today. Do your part and hunt down any enemies you find.",objectivesText="Kill 30 enemies in the Crucible of the Damned and Calcis.",rewardItems={175713,175728,175740,179500,179508,179537,179562,179584,179604,181402,181403,181411,181412,181414,181415,181416,181417,181419,181426,181427,181428,181429,181430,181457,181459,181477,181479,181541,182110,182338,183470,184378,184381,184382,184383,184384,184519},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=178828}},ends={{npcID=178828},{npcID=178829}},coords={x=0.224,y=0.432,source="quest_giver",zoneID=11400},questType="standard"},
[63969] = {id=63969,name="Looming Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Winter Queen called for a hunt in this location due to reports of a massive, unnatural darkness swelling in its upper regions. The Wild Hunt is brave, but not foolish. We must learn what we can about this darkness before we charge into it. Search the bodies of our enemies nearby for clues.",objectivesText="Collect 1 Mawsworn Ritual Book , 10 Mawsworn Missive Scraps , and 15 Dark Marrow . Progress: Have you learned anything regarding the darkness yet?",rewardItems={186300,186309,186310},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178828}},ends={{npcID=178828},{npcID=178829}},coords={x=0.224,y=0.432,source="quest_giver",zoneID=11400},questType="standard"},
[63970] = {id=63970,name="No Soul Left Behind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Do you hear the cries of tormented souls trapped in Gorgoa? The twisted river of souls flows before us, swelling with cruelty and the torment of undeserving victims. Our brave regiment of druid spirits led the charge into the river to seek out those lost souls, but I fear many have instead joined in their suffering. Summon your courage and take my cradle with you into the river. Load the lost souls you find onto the cradle, then order the cradle to come back to me.",objectivesText="Use Thiernax 's Rescue Cradle to rescue 12 Lost Druids in Gorgoa and send them back to Thiernax . Progress: I admire Thiernax 's dedication to even the least among us.",rewardItems={179508,179513,179517,179532,179537,179547,181405,181426,181427,181428,181429,181455,181477,181479,181541,181735,181736,182136,182657,182769,183487,183488,184378,184381,184382,184383,184384,184519},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178884}},ends={{npcID=178884},{npcID=178892}},coords={x=0.228,y=0.432,source="quest_giver",zoneID=11400},questType="standard"},
[63971] = {id=63971,name="Snail Stomping",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Careful where you step. You wouldn't want to accidentally squish a Mawsworn, would you? Of course you would! It's so fun! Lady Moonberry giggles and points at the snails around her.> It's so much easier to squish Mawsworn after you've transformed them into stinky little snails. Here, take my wand and try it out on whatever you like. You may need to weaken them a bit first, but it'll work on almost anything!",objectivesText="Use Lady Moonberry's Wand to transform 15 weakened enemies into snails, and then squish them! Progress: Lady Moonberry never ceases to surprise me.",rewardItems={186199},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=178885}},ends={{npcID=178829}},coords={x=0.226,y=0.436,source="quest_giver",zoneID=11400},questType="standard"},
[63972] = {id=63972,name="Just Don't Ask Me to Spell It",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="It's getting dangerous out there for druid spirits! Thankfully, we always have room for another friend in our group, and this fine tirnenn has offered to help me and the gang get around the battlefield safely. Choofa begins speaking slowly, but Choofa just talks louder.> Good ol' Kirriprkar- I mean, Karripkraker- I mean, Krackerkrisp... Choofa laughs.> Let's just call her \"Big K\"! Hop on, everybody!",objectivesText="Help Krrprripripkraak and her friends sow chaos in the Crucible of the Damned. Progress: Krrprripripkraak and Choofa are teaming up? This, I must see.",rewardItems={175740,179508,179513,179517,179532,179547,181398,181399,181403,181404,181405,181406,181407,181408,181409,181410,181411,181412,181413,181421,181458,181459,181477,181479,181541,184378,184381,184382,184383,184384,184519},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=179066}},ends={{npcID=178828},{npcID=178829}},coords={x=0.22,y=0.432,source="quest_giver",zoneID=11400},questType="standard"},
[63973] = {id=63973,name="Double Dromans",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Relax, $p. Breathe. Dreamweaver inhales and exhales slowly.> Things are getting tense around here, but that doesn't mean YOU need to be tense. Everything is going to be okay. If you don't believe me, let the mighty deeds of Droman Aliothe and Droman Tashmur reassure you. They headed up the hill together to clear a path for the rest of us. They'll have everything taken care of in no time.",objectivesText="Help Droman Aliothe defeat enemies along her path and kill Lord Dretnal . Progress: You can find the droman up the hill from here.",rewardItems={175713,175740,179500,179508,179513,179517,179532,179537,179547,179562,179584,179604,181399,181400,181401,181402,181403,181404,181405,181406,181413,181477,181479,181541,182456,182686,183484,184378,184381,184382,184383,184384,184519},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=179067}},ends={{npcID=178829}},coords={x=0.226,y=0.436,source="quest_giver",zoneID=11400},questType="standard"},
[63974] = {id=63974,name="That's Going to Sting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Niya speaks loudly to be heard over the buzzing coming from the collection of needler nests behind her.> I've caught Moonberry trying to steal these nests for her pranks over ten times already! The other faeries said I was crazy to bring the needlers out here. Too wild! Too unpredictable! But that's exactly why we need them. Lord Herne 's scouts report powerful Heralds among our enemy's forces. Take one of these nests, and use it to surprise the Heralds!",objectivesText="Use an Angry Needler Nest to weaken and kill Herald Gkeca , Herald Throgtu , and Herald Duarri . Progress: Niya is proving to be quite the clever tactician...",rewardItems={186569},rewardCurrencies={{id=1806,amount=175}},starts={{npcID=179065}},ends={{npcID=178828},{npcID=178829}},coords={x=0.222,y=0.436,source="quest_giver",zoneID=11400},questType="standard"},
[63976] = {id=63976,name="The Al'ley Cat of Oribos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13672,mapID=1672,description="Ah, Maw Walker. I have a message. An individual has a proposition for you, specifically. I know nothing of the details, only that they asked you meet them towards the back of the Idyllia.",objectivesText="Meet with the mysterious contact in Oribos.",rewardGold=25740,rewardXP=1020,starts={{npcID=156688}},ends={{npcID=178908}},questType="standard"},
[63977] = {id=63977,name="Insider Trading",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13672,mapID=1672,description="I am the foremost expert on broker culture. However, relationships between cartels are complicated and unstable. Cartel So holds a small presence here in Oribos, which means the other cartels may have knowledge that I do not. Ask around--with your renown, surely they'll have whatever information that we are missing.",objectivesText="Speak with various broker cartels around Oribos. Progress: Have you had a chance to speak with the other cartels?",rewardGold=257400,rewardXP=8165,starts={{npcID=178908}},ends={{npcID=178908}},coords={x=0.568,y=0.308,source="quest_giver",zoneID=10565},questType="standard"},
[63979] = {id=63979,name="Things Best Kept Dark",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13672,mapID=1672,description="The leader of Cartel So represents a grave danger to the Shadowlands, Maw Walker. Her name is So'leah. She seeks to assemble an artifact of the First Ones and use its power for selfish ends. Pieces of the relic are said to be hidden on your homeworld. Brokers have never before found our way there. But if So'leah does, then Azeroth too is imperiled. We must intercept her. There is cargo nearby marked for Cartel So. Perhaps the manifest will give us clues as to their leader's whereabouts.",objectivesText="Find a shipping manifest belonging to Cartel So. Progress: Have you found anything?",rewardGold=257400,rewardXP=8165,starts={{npcID=178908}},ends={{npcID=178908}},coords={x=0.568,y=0.308,source="quest_giver",zoneID=10565},questType="standard"},
[63980] = {id=63980,name="Seeking Smugglers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="We brokers have found that it is in our best interests to remain mobile. And discreet. A number of our cities and outposts are tucked away in the In-Between, capable of moving from place to place. Much to my chagrin, it seems I have lost track of Tazavesh. I believe our best course of action is to ask Cartel Ta for access. They pride themselves on keeping track of such things. Let's try our luck with those at the Night Market in Revendreth. They may be more forthcoming than their Oribos kin.",objectivesText="Speak with Ta'nla the Identifier at the Night Market.",rewardGold=25740,rewardXP=1020,starts={{npcID=178908}},ends={{npcID=160090}},coords={x=0.568,y=0.308,source="quest_giver",zoneID=10565},questType="standard"},
[63982] = {id=63982,name="Above My Station",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1525,description="While I indeed know the location of the Veiled Market, I fear I can do little in terms of providing you with transportation to it. In return for your assistance with a task, I can send you to someone who can assist us both. There is a bounty hunter at Transfer Station Ta--a broker enclave in Bastion. He is better suited to help you... and he owes me a shipment. Meet with Ta'oku and tell him that Ta'nla sent you. For your convenience, I can offer use of a portal. After all, we are partners, yes?",objectivesText="Take the portal at the Night Market and speak with Ta'oku.",rewardGold=25740,rewardXP=1020,starts={{npcID=160090}},ends={{npcID=158890}},coords={x=0.514,y=0.828,source="quest_giver",zoneID=10413},questType="standard"},
[63983] = {id=63983,name="Dead Drop",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ta'nla requested something very... specific... on behalf of a client. The kyrian have been working on a new type of centurion they call an aquilon. I sent some of our trade specialists to retrieve the prototype in question, but they have yet to return. Until I have the item, there is obviously no way I can ship it to Ta'nla. Perhaps we can help one another. If you can locate the aquilon and bring it here, I will help you reach Tazavesh.",objectivesText="Retrieve the Prototype Aquilon . Progress: Have you acquired the... item?",rewardGold=257400,rewardXP=8165,starts={{npcID=158890}},ends={{npcID=158890}},coords={x=0.324,y=0.324,source="quest_giver",zoneID=10534},questType="standard"},
[63984] = {id=63984,name="Coins for the Ferryman",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="Your side of the deal is done, Maw Walker. Now for your payment. My cartel runs a ferry that travels between Oribos and Tazavesh. Its purpose is to transport cargo, but as in all things, there are... exceptions. Take this coin to Ta'meri and you will be provided safe passage to the market. What happens after that is up to you.",objectivesText="Speak with Ta'meri in Oribos. Provided item:",rewardGold=25740,rewardXP=1020,rewardItems={186696},starts={{npcID=158890}},ends={{npcID=158890}},coords={x=0.324,y=0.324,source="quest_giver",zoneID=10534},questType="standard"},
[63985] = {id=63985,name="The Veiled Market",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13672,mapID=2016,description="Let me guess... Ta'oku sent you my way, yes? Ta'meri looks at the coin you offer.> So, you seek travel to Tazavesh. Not something we'd typically offer an outsider, but since payment has been accounted for, it would be my pleasure to assist you. Step aboard, and do remember to keep any appendages inside the craft at all times. The currents of the In-Between can be fickle.",objectivesText="Ride the barge to Tazavesh.",rewardGold=25740,rewardXP=1020,starts={{npcID=178792}},ends={{npcID=178908}},questType="standard"},
[63986] = {id=63986,name="Tazavesh: Raiders of the Lost Artifact",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13577,mapID=2016,description="It looks like you may need to show a bit of force once more, my dear friend. Tazavesh security will not let us simply walk in. But So'leah needs to be stopped. If that requires a bit of physical... persuasion... then it is a necessary evil. Bring some friends. I have a feeling the security here has tricks up their sleeves.",objectivesText="Enter Tazavesh and defeat So'leah .",rewardGold=2574000,rewardXP=16330,rewardItems={184315},starts={{npcID=178908}},ends={{npcID=178908}},coords={x=0.568,y=0.308,source="quest_giver",zoneID=10565},questType="dungeon"},
[63987] = {id=63987,name="Ve'lor's Lost Parcel",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[63989] = {id=63989,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! Can you take Plaguey with you and test their ability to infect organic life forms?",rewardItems={187000},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[63990] = {id=63990,name="The Blade in the Night",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Though my hunt has been arduous, I have two promising leads on additional Night Warriors. The first is here in Maldraxxus. This tower contains records of those who arrived in Maldraxxus, including someone referred to as \"The Blade in the Night.\" I believe this to be our next Night Warrior. I encountered many traps on the way here. Doubtless we will find more within the tower. Someone is trying to stop us. We will not let them succeed.",objectivesText="Search the Sepulcher of Knowledge for clues. Progress: Hmm.",rewardGold=128700,rewardXP=4085,starts={{npcID=177471}},ends={{npcID=177435}},coords={x=0.428,y=0.252,source="quest_giver",zoneID=11462},questType="standard"},
[63994] = {id=63994,name="Who is the Maw Walker?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Korthian prophecies foretell the arrival of a Maw Walker who can save us from disaster. Perhaps this is that day. But perhaps not. I must test your anima to verify your claim. If you speak the truth, then I have a solemn duty to empower your anima before we proceed.",objectivesText="Participate in Tal-Galan 's Maw Walker trial. Progress: Let us proceed, Maw Walker.",rewardGold=128700,rewardXP=4085,starts={{npcID=177227}},ends={{npcID=177227}},coords={x=0.638,y=0.236,source="quest_giver",zoneID=13570},questType="standard"},
[64007] = {id=64007,name="Charge of the Covenants",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Thanks to the efforts of you and other heroes of Azeroth, the covenants have grown strong. But we can no longer afford to wait for the Jailer to make his next move. The way to the Maw is open. Our forces stand ready. The covenants await your signal, .",objectivesText="Rally the covenant forces to go into the Maw.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=177230}},ends={{npcID=177228}},questType="standard"},
[64012] = {id=64012,name="Supplies from Death's Advance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.",objectivesText="Speak with Duchess Mynx at Keeper's Respite in Korthia .",rewardItems={186541,186644,186649,186650},ends={{npcID=179321}},coords={mapID=1961,source="quest_giver",x=0.634,y=0.235},questType="standard"},
[64014] = {id=64014,name="Mawsplaining",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="There remains one task now before the glorious battle can begin. The horn must be anchored to the Maw so that its voice may pierce the barrier that surrounds that foul realm. How this can be done, I do not know. Seek out one that understands the mysteries of that place. Surely they can guide your hand. Danica and her sisters will listen for Ilskahorn's call. They will answer when you need them, .",objectivesText="Ask Ve'nari 's help to bind the Ilskahorn to the Maw. Progress: Have you bound the horn to the Maw?",rewardGold=257400,rewardXP=8165,starts={{npcID=177726}},ends={{npcID=162804}},questType="standard"},
[64015] = {id=64015,name="Into the Meat Grinder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="All these mawsworn have got me excited for some slaughter! I've got a plan that probably won't end in you dying. Are you in?",rewardItems={185011,185012,185013,185014,185015,185016,185017,185018,185019,186201,186205,186206,187329,187330,187331,187467},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178805,x=0.6,y=0.274,zoneID=13570}},ends={{npcID=178805,x=0.6,y=0.274,zoneID=13570}},coords={x=0.6,y=0.274,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Into the Meat Grinder"},
[64016] = {id=64016,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Ooz, I'd like to know if they are able to consume organic material and increase in size.",rewardItems={187000},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[64017] = {id=64017,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.",rewardItems={187000},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[64018] = {id=64018,name="The Weight of Stone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The campaign continues, $p. The Stone Legion is here to turn the tide of battle. First, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied. Second, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.",rewardItems={185073,185074,185075,185076,185077,185078,185079,185080,185107,185108,185109,185110,185111,185112,185113,185114,185115,186201,186205,186206,187329,187330,187331,187467},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178794,x=0.614,y=0.25,zoneID=13570}},ends={{npcID=178794,x=0.614,y=0.25,zoneID=13570}},coords={x=0.614,y=0.25,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="The Weight of Stone"},
[64040] = {id=64040,name="Once More, with Healing",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The mawsworn continue to engage our forces at the Vault. There are heavy casualties on both sides. We must help! Take this and restore any wounded covenant allies you find. Mikanikos helped me create it. It runs on anima and should help patch up anyone. Even the Stoneborn or Maldraxxi.",rewardItems={186445},rewardCurrencies={{id=1804,amount=175},{id=1907,amount=175}},starts={{npcID=179194,x=0.616,y=0.24,mapID=1961}},ends={{npcID=179194,x=0.616,y=0.24,mapID=1961}},coords={x=0.616,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Once More, with Healing"},
[64042] = {id=64042,name="Rituals of Night",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Tyrande's time grows short, so we must act quickly. Ysera frowns in concern.> We had hoped to gather more Night Warriors, but we will have to proceed with who we have and hope it is enough. Ysera shakes her head, then looks more resolute.> Before we can begin, we must finish preparations for the ritual. Please bring these last few items with you and meet us at the grove.",objectivesText="Assist with the preparations and ritual. Progress: Good, we may begin.",rewardGold=257400,rewardXP=8165,starts={{npcID=177434}},ends={{npcID=177434}},coords={x=0.452,y=0.648,source="quest_giver",zoneID=11510},questType="standard"},
[64043] = {id=64043,name="We Need a Healer - You!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You: take my device and get our wounded back on their feet!",rewardItems={186448},rewardCurrencies={{id=1804,amount=175},{id=1907,amount=175}},starts={{npcID=179216,x=0.614,y=0.24,mapID=1961}},ends={{npcID=179216,x=0.614,y=0.24,mapID=1961}},coords={x=0.614,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="We Need a Healer - You!"},
[64065] = {id=64065,name="Local Reagents",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Korthia is an odd place. The wildlife here is different, likely due to years of exposure to the Vault and everything it contains. Are you ready to try some experiments? We'll need a good stock of reagents first. Near the Seeker's Quorum, you should be able to find shardhides, gromits, and razorwings. Watch out for their needles!",rewardItems={186455,186456,186457,187000},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178806,x=0.604,y=0.278,mapID=1961}},ends={{npcID=178806,x=0.604,y=0.278,mapID=1961}},coords={x=0.604,y=0.278,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Local Reagents"},
[64070] = {id=64070,name="Staying Scrappy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our army always need more weapons, armor, and troops. Always. We're getting reinforcements, but I can't keep everyone properly armed at this rate. Especially without a full forge and assistants. We'll have to make do with the next best thing. I need you to go get me any kind of scrap metal from the Mawsworn you can find. I'll figure out how to turn it into usable weapons.",rewardItems={186458},rewardCurrencies={{id=1805,amount=175},{id=1907,amount=175}},starts={{npcID=179214,x=0.632,y=0.252,mapID=1961}},ends={{npcID=179214,x=0.632,y=0.252,mapID=1961}},coords={x=0.632,y=0.252,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Staying Scrappy"},
[64080] = {id=64080,name="Down to Earth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I can hear the wings of the Mawsworn in the sky up above, taunting us. But a bird in the hand can be crushed. Take my spear and prove your aim. Pull a few down and smite them. Be sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point. I want to see you drag them out of the sky.",rewardItems={186474},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178841,x=0.61,y=0.216,zoneID=13570}},ends={{npcID=178841,x=0.61,y=0.216,zoneID=13570}},coords={x=0.61,y=0.216,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Down to Earth"},
[64083] = {id=64083,name="Sinfall Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, . Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175772}},ends={{npcID=175772}},coords={x=0.546,y=0.268,source="quest_giver",zoneID=10986},questType="standard"},
[64084] = {id=64084,name="Necrolord Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=175998}},ends={{npcID=175998}},coords={x=0.468,y=0.402,source="quest_giver",zoneID=12876},questType="standard"},
[64085] = {id=64085,name="Night Fae Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176096}},ends={{npcID=176096}},coords={x=0.34,y=0.37,source="quest_giver",zoneID=12858},questType="standard"},
[64086] = {id=64086,name="Kyrian Tactician",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1533,description="Look around you, . Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg has once again requested your presence in Oribos. Go at once. The favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained. Perhaps they have more rewards to bestow upon you.",objectivesText="Meet with Zo'sorg in the Enclave in Oribos.",starts={{npcID=176100}},ends={{npcID=176100}},coords={x=0.648,y=0.202,source="quest_giver",zoneID=10534},questType="standard"},
[64089] = {id=64089,name="Teas and Tinctures",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="How delightful! What a lovely little spot of nature. Have you tried the local brews? Perhaps a nice herbal tea? No? Well, let's try it together! Search about this place and bring back any herbs that look... interesting. A good spot of tea, and then we shall get to work. I'll wait here.",rewardItems={186486},rewardCurrencies={{id=1807,amount=175},{id=1907,amount=175}},starts={{npcID=179218,x=0.616,y=0.258,mapID=1961}},ends={{npcID=179218,x=0.616,y=0.258,mapID=1961}},coords={x=0.616,y=0.258,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Teas and Tinctures"},
[64090] = {id=64090,name="The Big Squeeze",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="So our missin' blue got 'imself dragged off to the big squeeze. Fortunately I am wise to the prise. We'll soft foot it in like we work there, find your moose, avoid eye contact with the fangs, and chisel out of 'ere like we're masons. Follow?",objectivesText="Head to where Cudgelface thinks Huln was taken, and blend in. Progress: Well, this is exciting!",rewardGold=257400,rewardXP=8165,starts={{npcID=177968}},ends={{npcID=177967}},questType="standard"},
[64091] = {id=64091,name="Mal'appropriated",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Free me from this prison, mortal, and you will have my favor. I am aligned with powers greater than these pathetic puppets or their masters. They have no concept of the true forces at work. All I need are the sigils of binding which hold me. The rest I can... take care of. Free me, and you will be granted untold power.",objectivesText="Collect the Sigils of Binding Progress: Hmmm.",rewardGold=257400,rewardXP=8165,starts={{npcID=179327}},ends={{npcID=179327}},coords={x=0.378,y=0.234,source="quest_giver",zoneID=10413},questType="standard"},
[64092] = {id=64092,name="Hunting Huln",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Huln is somewhere in the area, but the Stonewright isn't letting anyone in to her territory because of the recent, ah, troubles with Dreadlords. The guards won't let anyone in, and they're kicking out anyone who doesn't look like they belong. Luckily for Huln, Cudgelface and I came up with a foolproof plan! We just need to look like we belong and then we can ask around and find Huln. Easy!",objectivesText="Don a disguise then search Dominance Keep for Huln Highmountain while avoiding the guards.",rewardGold=257400,rewardXP=8165,starts={{npcID=177962}},ends={{npcID=178254}},coords={x=0.34,y=0.096,source="quest_giver",zoneID=10413},questType="standard"},
[64101] = {id=64101,name="The Proper Procedures",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I came here to observe the actions of those from Revendreth. However I have been met with news that concerns me. $p, the attendants tell me that they stored anima in canisters and that anima is being looted, by our own people. That's not how this should be done. Can I entrust you to retrieve the anima, so I might see it returned to its proper place?",rewardItems={185073,185074,185075,185076,185077,185078,185079,185080,185107,185108,185109,185110,185111,185112,185113,185114,185115,186201,186205,186206,187328,187334,187336,187466},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178790,x=0.618,y=0.254,mapID=1961}},ends={{npcID=178790,x=0.618,y=0.254,mapID=1961}},coords={x=0.618,y=0.254,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="The Proper Procedures"},
[64103] = {id=64103,name="Old Tricks Work Best",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p. Here we are again, fighting alongside each other to protect the Shadowlands. We're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole. Our Eyes have brought us the names. Now I just need you to kill them.",rewardItems={185011,185012,185013,185014,185015,185016,185017,185018,185019,186201,186205,186206,187329,187330,187331,187467},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178808,x=0.606,y=0.28,zoneID=13570}},ends={{npcID=178808,x=0.606,y=0.28,zoneID=13570}},coords={x=0.606,y=0.28,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Old Tricks Work Best"},
[64104] = {id=64104,name="Think of the Critters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat. I've saved some extra food that we can share with them. But I'm worried that they might be too shy to trust us, and I don't blame them! Here. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.",rewardItems={186561},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178839,x=0.614,y=0.214,zoneID=13570}},ends={{npcID=178839,x=0.614,y=0.214,zoneID=13570}},coords={x=0.614,y=0.214,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Think of the Critters"},
[64106] = {id=64106,name="A Unified Effort",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="You have made strong allies within your covenant as well as the others within the Shadowlands. This bond is why they have decided to loan aid to our cause. They are ready to fight alongside us as we begin our advance into the Maw. Each covenant will strike at the Jailer from a different area. Help them scour this treacherous land for any who serve Zovaal so that we may put an end to his growing influence.",objectivesText="Aid the covenants in assaulting the Jailer's forces in the Maw.",rewardGold=514800,rewardXP=10205,rewardItems={187347},starts={{npcID=177228}},ends={{npcID=177228}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[64129] = {id=64129,name="Charge of the Wild Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. I admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh . Aldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?",rewardItems={182180,184948,184949,184950,184951,184952,184953,184954,184955,184956,186201,186205,186206,187329,187330,187331,187467},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=178840,x=0.61,y=0.212,zoneID=13570}},ends={{npcID=178840,x=0.61,y=0.212,zoneID=13570}},coords={x=0.61,y=0.212,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Charge of the Wild Hunt"},
[64131] = {id=64131,name="Tracking Quest",level=50,requiredLevel=50,faction="none",expansion=8,rewardItems={186476},questType="standard",worldTaskTitle="Tracking Quest",db2QuestInfoID=265,db2QuestInfoName="Hidden Quest"},
[64159] = {id=64159,name="Repatriate Rare Supplies",level=0,requiredLevel=0,faction="none",expansion=8,description="The rebels have stolen supplies from surrounding camps. You have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.",objectivesText="Recover supplies from the makeshift camps across the river.",rewardGold=312800,questType="standard"},
[64162] = {id=64162,name="Ritual Rival",level=0,requiredLevel=0,faction="none",expansion=8,description="Yet another rival Kahn has risen out of the rebel tribes. I'd take care of then myself, but I'm busy overseeing things here. I trust you can teach them the error of their ways?",objectivesText="Find and defeat the Rebel Kahn in the makeshift camps across the river.",rewardGold=312800,questType="standard"},
[64163] = {id=64163,name="Revenge Against Renegades",level=0,requiredLevel=0,faction="none",expansion=8,description="Rebel clans have laid claims to some of our camps across the river. Such rebellious rabble need dealing with. I trust that you are capable of teaching these rebels a lesson on my behalf? The camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.",objectivesText="Find and defeat Rebel Centaur Warriors in the makeshift camps across the river.",rewardGold=312800,questType="standard"},
[64166] = {id=64166,name="Random Memory Access",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too. Those people had lives, hopes, memories. I have to think that they can't all be gone, and we might be able to save something of them that lingers. Here, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. No one should be forgotten.",rewardItems={186672},rewardCurrencies={{id=1907,amount=175}},starts={{npcID=179134,x=0.618,y=0.24,zoneID=13570}},ends={{npcID=179134,x=0.618,y=0.24,zoneID=13570}},coords={x=0.618,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Random Memory Access"},
[64167] = {id=64167,name="Pets Detective",level=0,requiredLevel=0,faction="both",expansion=8,zoneID=7502,description="I'm so glad you're here, ! I've been expecting a delivery of pet supplies and some new pets. But my distribution manager, Zantini has not reported in. I suspect foul play. There's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can. Take my pet cat, Fiona, and find these well hidden spies.",objectivesText="Investigate the city of Dalaran with Breanni 's special spy catching cat, Fiona. Progress: What have you learned, <name>?",rewardGold=34100,rewardItems={187128},starts={{npcID=96479}},ends={{npcID=96479}},questType="standard"},
[64168] = {id=64168,name="Champion: Spore of Marasmius",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
