[64554] = {id=64554,name="Venthyr Assault",expansion=8,mapID=1543,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=178164,text="Ask Burly Hurly to throw you"},{orderIndex=1,type=0,amount=1,objectID=177926,text="Report to Prince Renathal on top of the Tremaculum wall"},{orderIndex=2,type=0,amount=4,objectID=177524,text="Help Venthyr and Night Fae forces assault the Tremaculum"},{orderIndex=3,type=0,amount=1,objectID=178242,text="Help Draven secure the upper platform"},{orderIndex=4,type=0,amount=1,objectID=178243,text="Travel through a Maw Mirror"},{orderIndex=5,type=0,amount=4,objectID=178244,text="Light directed into Maw Mirrors"},{orderIndex=6,type=0,amount=1,objectID=178245,text="Mirror 1"},{orderIndex=7,type=0,amount=1,objectID=178246,text="Mirror 2"},{orderIndex=8,type=0,amount=1,objectID=178247,text="Mirror 3"},{orderIndex=9,type=0,amount=1,objectID=178248,text="Mirror 4"},{orderIndex=10,type=0,amount=1,objectID=178249,text="Gothra the Trembler slain"},{orderIndex=11,type=0,amount=1,objectID=180519,text="NEVER COMPLETE"}},worldTaskTitle="Venthyr Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[64555] = {id=64555,name="Surveying Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Each of the covenants have provided their own specialists in their areas of expertise. A few of them have taken to the field to scout this unknown land. Speak with them. They should all be keeping a report of their survey. Return them to me.",objectivesText="Speak with the forward scouts in Korthia . Progress: Have you found all of the scouts?",rewardGold=257400,rewardXP=8165,rewardItems={187436,187437,187438,187439},starts={{npcID=177228}},ends={{npcID=177228}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[64556] = {id=64556,name="In Need of Assistance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The inhabitants of Korthia have been through much. Were it not for our arrival, the Jailer's forces would have rampaged through the remainder of the City of Secrets, leaving destruction in their wake. To continue our efforts, we must assist those in need. Heed the call of our allies, Maw Walker. See to it no stone is left unturned and no ally of the Jailer left alive.",objectivesText="Complete 3 Daily Quests from Mikanikos, Ta'nasi, and Kael'thas throughout Korthia .",rewardGold=514800,rewardXP=10205,rewardItems={187543},rewardCurrencies={{id=1977,amount=10}},starts={{npcID=177228}},ends={{npcID=177228}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[64557] = {id=64557,name="In Darkness, Found",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13575,mapID=1961,description="Cartel Ve has a reputation for creeping around dangerous places in search of treasure. If they had any sense, they would leave the acquisition and sale of goods to the Xy. Alas. One Ve member disappeared into Torghast with a plundered box of powerful items that he assumed would help him explore in safety. Madness!",objectivesText="Find Ve'nish in Torghast, Tower of the Damned .",rewardGold=25740,rewardXP=1020,starts={{npcID=178845}},ends={{npcID=178845}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="standard"},
[64560] = {id=64560,name="Anima Reclamation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?",rewardGold=257400,rewardXP=8165,rewardItems={185754},starts={{npcID=178793,x=0.618,y=0.256,zoneID=13570}},ends={{npcID=178793,x=0.618,y=0.256,zoneID=13570}},coords={x=0.618,y=0.256,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Anima Reclamation"},
[64561] = {id=64561,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. And don't forget to look below ground! Bring those data to me, and I will reward you handsomely.",rewardGold=257400,rewardXP=8165,rewardItems={186170},starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[64562] = {id=64562,name="We Need a Healer - You!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You, take my device and get our wounded back on their feet!",rewardGold=257400,rewardXP=8165,rewardItems={187504},starts={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},ends={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},coords={x=0.614,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="We Need a Healer - You!"},
[64567] = {id=64567,name="The Missing Scholar",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Maw Walker. Your return blesses us with great optimism, and much needed assistance. Several scholars remain unaccounted for. We believe they were last seen studying in the great court. We fear they may be lost, or worse, taken by those who seek to disrupt our way of life. Return to me when you have answers. May the path guide you.",objectivesText="Locate Scholar Roh-Suir in Korthia.",rewardGold=25740,starts={{npcID=177927}},ends={{npcID=178694}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="standard"},
[64571] = {id=64571,name="Tazavesh: Seek and Do Not Destroy",level=60,requiredLevel=60,faction="none",expansion=8,rewardGold=1029600,rewardItems={185954},questType="dungeon"},
[64579] = {id=64579,name="Hollow Efforts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. These empty metal husks still contain residual materials of creation that may be useful to us. Use my Forge-Tap near these metal spheres to harvest any Remnant Neomotes . You may also find other useful proto-materials!",rewardXP=8165,rewardItems={187516,187519},rewardCurrencies={{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Hollow Efforts"},
[64581] = {id=64581,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={128768,187422},starts={{npcID=180746}},ends={{npcID=180746}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[64592] = {id=64592,name="Historic Protection",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The outsiders have disrupted the sands. We cannot reach the terraforming records we need in order to collect necessary historical information. Will you assist us? Help Mai Obet collect historical records in the Endless Sands.",rewardXP=8165,rewardItems={189544,190189,190341,190342,190343,190344,190347,190348,190349,190350,190351,190354,190355,190357,190358,190359,190362,190363,190365,190366,190367,190370,190371,190605,190633,190634,190635,192423,192424,192425,192427,192429,192430,192440,192449,192450,192451},rewardCurrencies={{id=2009,amount=75}},starts={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Historic Protection",db2QuestInfoID=1,db2QuestInfoName="Group"},
[64597] = {id=64597,name="Sanctum of Domination - Damned If You Don't",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13561,description="I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers. Four shards should be enough. We wouldn't want him coming back again would we?",objectivesText="Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Normal Difficulty. Progress: Four shards should allow us to access his chamber.",rewardGold=514800,rewardXP=10205,starts={{npcID=178592}},ends={{npcID=178592}},questType="raid"},
[64598] = {id=64598,name="Sanctum of Domination - Damned If You Don't",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13561,description="I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers. Four shards should be enough. We wouldn't want him coming back again would we?",objectivesText="Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Heroic Difficulty. Progress: Four shards should allow us to access his chamber.",rewardGold=514800,rewardXP=10205,starts={{npcID=178592}},ends={{npcID=178592}},questType="raid"},
[64599] = {id=64599,name="Sanctum of Domination - Damned If You Don't",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13561,description="I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers. Four shards should be enough. We wouldn't want him coming back again would we?",objectivesText="Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Mythic Difficulty. Progress: Four shards should allow us to access his chamber.",rewardGold=514800,rewardXP=10205,starts={{npcID=178592}},ends={{npcID=178592}},questType="raid"},
[64607] = {id=64607,name="Tazavesh: A Hard Bargain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13577,description="Ah, my work looks marvelous on you. You are the very image of legitimacy! And now that I've provided you with my talents, you shall provide me with yours. Seek out my business associate, Fe'tajid , at the Gilded Landing and offer him your assistance. I look forward to hearing of your success.",objectivesText="Seek out Au'manal 's business associate and offer your assistance. Progress: Have you spoken with my associate?",rewardGold=1029600,rewardXP=16330,rewardItems={187552},starts={{npcID=180750}},questType="dungeon"},
[64639] = {id=64639,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,rewardItems={187561},starts={{npcID=187236}},ends={{npcID=187236}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[64641] = {id=64641,name="Mysterious Greenery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="There's a bright power emanating from the place above. I'm drawn towards it, like a moth to a light! I want to check it out, whatever it is. Won't you join me, please? It'll be so fun!",rewardGold=128700,rewardXP=8165,starts={{npcID=180799,x=0.552,y=0.644,mapID=1970}},ends={{npcID=179900,x=0.604,y=0.7,mapID=1970}},coords={x=0.552,y=0.644,source="quest_giver",mapID=1970},questType="world",worldTaskTitle="Mysterious Greenery"},
[64642] = {id=64642,name="Clearing the Ruins",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="This place was abandoned for too long. The vegetation has overtaken the land. We must enter the Blooming Foundry to fix it. Until then: clear the area. Remove the deviants who have grown twisted over time.",objectivesText="Kill 15 creatures within the Untamed Verdure.",rewardGold=257400,rewardXP=8165,starts={{npcID=179900}},ends={{npcID=179900}},coords={x=0.604,y=0.7,source="quest_giver",zoneID=13536},questType="standard"},
[64643] = {id=64643,name="Scavenging a Solution",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The Blooming Foundry created this area. It maintains the automa, the creatures, and the plants. The overgrowth is its fault. We need to enter the Foundry to fix this land. This constructor can break through when it is working. Many automa in this area stopped moving long ago. Find usable pieces inside them.",objectivesText="Find 8 Automa Internals from Abandoned Automa in the Untamed Verdure. Progress: With your help, we will restore this place to its glory.",rewardGold=257400,rewardXP=8165,rewardItems={187131},starts={{npcID=179923}},ends={{npcID=179923}},coords={x=0.604,y=0.7,source="quest_giver",zoneID=13536},questType="standard"},
[64644] = {id=64644,name="A Splash of the Eternal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I don't really know much about this place or its inhabitants, but what I do know is magic! I can sense ancient power from the waters near us. Maybe that can help? Let's check out that pond!",objectivesText="Help Glimmercane extract water from the pool in the Untamed Verdure. Progress: <The automa lies inert.>",rewardGold=257400,rewardXP=8165,rewardItems={187925},starts={{npcID=180702}},ends={{npcID=182579}},coords={x=0.606,y=0.698,source="quest_giver",zoneID=13536},questType="standard"},
[64645] = {id=64645,name="Moment of Truth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Our constructor is ready. We shall start the process to open the Blooming Foundry and reset this land. We can start over.",objectivesText="Follow the Koh jiro in the Untamed Verdure.",rewardGold=128700,rewardXP=8165,starts={{npcID=179900}},ends={{npcID=180797}},coords={x=0.604,y=0.7,source="quest_giver",zoneID=13536},questType="standard"},
[64646] = {id=64646,name="Ramping Up",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13928,mapID=1970,description="We must restore the Foundry's power to use it. Conductors will channel power so we can use it. We know how to use the conductors. Clear the way, and we shall start over.",objectivesText="Activate 4 conductors within the Blooming Foundry.",rewardGold=257400,rewardXP=8165,starts={{npcID=180797}},ends={{npcID=180800}},coords={x=0.604,y=0.7,source="quest_giver",zoneID=13536},questType="standard"},
[64647] = {id=64647,name="Strange Gears",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="<Oddly, the seed within the automa's innards is still very much alive. Are they all like this?>",objectivesText="Collect 3 Winding Seeds from the automa in the Blooming Foundry. Progress: These are very unusual.",rewardGold=257400,rewardXP=8165,rewardItems={187619,187620},starts={{npcID=375021}},ends={{npcID=180800}},coords={x=0.295,y=0.142,source="quest_giver",zoneID=13928},questType="standard"},
[64648] = {id=64648,name="Reap What We Have Sown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13928,mapID=1970,description="We told the constructor that we will use the Foundry to reset this land. We must stop it and protect the new automa.",objectivesText="Defeat the Charged Constructor .",rewardGold=257400,rewardXP=8165,rewardItems={190977,190978,190979,190983,190984,190985,190989,190990,190991,190995,190996,190997},rewardChoices={190977,190978,190979,190983,190984,190985,190989,190990,190991,190995,190996,190997},starts={{npcID=180800}},ends={{npcID=180799}},coords={x=0.636,y=0.73,source="quest_giver",zoneID=13536},questType="standard"},
[64650] = {id=64650,name="Hyena Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Hyena Soul is fiery and spry. The shape of the hyena will be yours to call upon.>",objectivesText="Bring the Hyena Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[64651] = {id=64651,name="Cobra Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Cobra Soul is covetous and protective. The shape of the cobra will be yours to call upon.>",objectivesText="Bring the Cobra Soul to Lady Muunn in the Heart of the Forest. Provided item:",ends={{npcID=174209}},questType="standard"},
[64706] = {id=64706,name="A Matter Of Motivation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Giants litter these sands, mortal. But I believe we can revitalize them. The smaller automa that are hiding in the desert can be utilized here. Use my Motivator to rally them to our cause. If we can gather enough, their energy can replenish these defeated behemoths to bolster our forces. Return as many as you can to me, and we will put them to work!",objectivesText="Return 6 Motivated Automa to Firim . Progress: Have they been suitably motivated?",rewardGold=257400,rewardXP=8165,rewardItems={188678},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=180903}},ends={{npcID=180903}},coords={x=0.568,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64710] = {id=64710,name="Whispering Felflame Crystal",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=7502,mapID=627,description="The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran . Perhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.",objectivesText="Bring the Whispering Felflame Crystal to Aridormi in Dalaran , floating above the Broken Isles.",rewardGold=309800,rewardXP=200,rewardCurrencies={{currencyID=1166,quantity=1}},questType="standard"},
[64713] = {id=64713,name="Picking Up the Pieces... Literally",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Orbs help us develop terrain for the Forge. Magic within the orbs draws the devourers. They tear apart the metal to reach it. We must collect the remains. Look for the fragments around the orbs. Bring them to us.",objectivesText="Collect 30 Orb Fragments . Progress: Did you find the fragments? We need many pieces.",rewardGold=257400,rewardXP=8165,rewardItems={187615},starts={{npcID=180919}},ends={{npcID=180919}},coords={x=0.366,y=0.378,source="quest_giver",zoneID=13536},questType="standard"},
[64717] = {id=64717,name="Materials of Creation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. The spheres near the Forge of Afterlives contain trace amounts of materials unique to that location. I have modified my Forge-Tap to harvest those materials. Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges .",rewardXP=8165,rewardItems={187516,187779,187782},rewardCurrencies={{id=1979,amount=20},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Materials of Creation"},
[64718] = {id=64718,name="Keys To Victory",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="The song... incomplete. Harmony is needed. Seek those who scry. Send them to serve the cycle. Mawsworn hold the keys that bind. Take the keys, set them free.",objectivesText="Free 6 Automa Scryers from their cells.",rewardGold=257400,rewardXP=8165,rewardItems={187809},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64720] = {id=64720,name="Cleaving A Path",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Maw Walker! My scouts report that the Mawsworn have dominated two automa Oracles to aid them in battle. These Oracles will most certainly predict our strategy and our ultimate goal, if given the chance. We need to eliminate both Oracles before we enter the Crypts. With them out of the way, the Mawsworn troops won't know what we're doing until we're finished with it. Take Emeni with you. She's eager for battle.",objectivesText="Slay Oracle Zoketh and Oracle Voraxxi .",rewardGold=514800,rewardXP=10205,rewardItems={187602},rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=180928}},ends={{npcID=180928}},coords={x=0.564,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64722] = {id=64722,name="Knocking On Death's Door",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="This is it, mortal. The forces you have assembled should be enough to break through the Mawsworn and reach the Crypts. Getting inside, however, will require more effort. The Mawsworn have barricaded the entrance. Kbato will carry you into battle. Eliminate the Mawsworn, and destroy the devices that power the barrier.",objectivesText="Riding Kbato, defeat the Mawsworn forces in the Endless Sands and open the way to the Crypts of the Eternal.",rewardGold=257400,rewardXP=8165,rewardItems={188008,188014,188021,188030},starts={{npcID=180903}},ends={{npcID=180965}},coords={x=0.568,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64723] = {id=64723,name="Restoration Project",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Without an Arbiter, the very purpose of the Shadowlands has been compromised. Souls flood the Maw with no direction. As Saezurah noted, Zereth Mortis would ordinarily craft a new being to take the Arbiter's place. I suspect the Jailer's forces have disrupted the land to the point where this is no longer possible. It is time to take action ourselves, and bring stability again to the Shadowlands! Speak to Saezurah, and see where we must begin.",objectivesText="Speak with Saezurah. Progress: Have you spoken with them?",rewardGold=257400,rewardXP=8165,rewardItems={187602},starts={{npcID=177958}},ends={{npcID=181545}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[64725] = {id=64725,name="Unforgivable Intrusion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="Darkness spreads dissonance throughout these halls. Mawsworn drain life from the air, and give only suffering in return. This must not be. If the song is to be restored, silence is needed. The Mawsworn must be destroyed.",objectivesText="Eliminate 6 Dominated Automa and 3 Darkseer Corrupters . Progress: When the halls are silent, we may proceed.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64726] = {id=64726,name="The Order Of Things",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="Essences of ancient souls, tampered with--they bleed from each room. The halls must be restored, the flow of souls redirected. The spheres hold the key. Seal the breaches, restore the flow, then the vessel may be filled.",objectivesText="Use $13oa Containment Spheres to seal the breaches. Progress: Seal the breach, restore the flow.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64727] = {id=64727,name="The Infinite Circle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="Creation calls--can you hear it? Yet darkness lingers below, taints the ancient melody. To forge anew, peace must be restored. The Walker must walk, and protect. There is much to be done. Lead the way.",objectivesText="Escort Saezurah to the center of the Crypts of the Eternal.",rewardGold=25740,rewardXP=1020,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64728] = {id=64728,name="Acquaintances Forgotten",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="It is time. The song shall bring life anew. Tell me when you are ready to begin.",objectivesText="Complete the Ritual. Progress: The ritual must be completed.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64729] = {id=64729,name="Lifetimes To Consider",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="This song has been completed, and harmony has been restored. Yet Zereth Mortis remains haunted by discord. Dissonance lingers still, outside these walls. We must leave before it finds us. Speak with the one you call Firim--he will open the way.",objectivesText="Return to Exile's Hollow.",rewardGold=257400,rewardXP=8165,rewardItems={190980,190981,190982,190986,190987,190988,190992,190993,190994,190998,190999,191000},rewardChoices={190980,190981,190982,190986,190987,190988},starts={{npcID=180942}},ends={{npcID=181545}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64730] = {id=64730,name="The Turning Point",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="A pause, devoid of breath. A melody lingers on. The cycle awaits a voice. Saezurah means. Perhaps you should try to set up the ritual again, starting with the Vessel and the scryers.>",objectivesText="Examine the Vessel and the Automa Scryers. Progress: Have you tried everything?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=180942}},ends={{npcID=180915}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64731] = {id=64731,name="For Every Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="Without the Arbiter to stem the flow of souls to the Maw, the Shadowlands will never be fully repaired. This cannot be the end. Surely you can think of something?",objectivesText="Find a way to create a new Arbiter. Progress: This moment is of great importance.",rewardGold=257400,rewardXP=8165,starts={{npcID=180915}},ends={{npcID=180942}},coords={x=0.566,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64733] = {id=64733,name="Help From Beyond",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="If we stand any chance of breaking through the Mawsworn forces, we will need the help of all of the covenants. I will speak with the Kyrian. You and Pelagos can speak with the others. But before you go, ask Firim if there is any way we can gain the support of the Enlightened as well.",objectivesText="Speak with representatives from the Enlightened, Venthyr, Necrolord, and Night Fae.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181545}},ends={{npcID=180914}},coords={x=0.342,y=0.484,source="quest_giver",zoneID=13536},questType="standard"},
[64739] = {id=64739,name="Zovaal's Grasp",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I remember this metal. I saw it when I was touched by Maw magic. When I was severed... I will show you where this happened. Follow me. I will tell you my story.",objectivesText="Follow Hanoa the Exile and listen to her story.",rewardGold=64350,rewardXP=8165,starts={{npcID=184469}},ends={{npcID=180989}},coords={x=0.394,y=0.322,source="quest_giver",zoneID=13536},questType="standard"},
[64741] = {id=64741,name="Security Check",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I do not understand--these are my brethren! How can they be so careless, so unconcerned with both greedy cartels and the Mawsworn at their doorstep? Their protective technology is antiquated. It will not keep danger out. If I cannot persuade them to leave, I can at least ensure they are safe where they insist on staying. I do not want to lose my friends again. There should be four hidden conduits around the edge of the shield. Take this kit. It will allow you to inspect and repair them, if needed.",rewardGold=257400,rewardXP=8165,starts={{npcID=181003}},ends={{npcID=181003}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64742] = {id=64742,name="Traces of Tampering",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="So the shield has been sabotaged. Of course the ruthless Cartel Xy are the first to attempt to profit off this land. Their greed has put us all in even more danger. We must stop them. Let us search together for signs of their passage.",rewardGold=128700,rewardXP=8165,starts={{npcID=181003}},ends={{npcID=181003}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64743] = {id=64743,name="Xy Are You Doing This?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We cannot see them, but I am certain this is where Cartel Xy has established their base. Something must have drawn Xy to this area of Zereth Mortis specifically, and we must discover what it is if we are to protect our friends here. Their cloaks do not cover their supplies very well. See what information you can gather from their belongings.",rewardGold=257400,rewardXP=8165,rewardItems={187626},starts={{npcID=181003}},ends={{npcID=181003}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64744] = {id=64744,name="Broker Decloaker",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Do you sense a shift in the air? They may be hidden, but Cartel Xy is near. Fortunately, the devices they use to cloak themselves are familiar to me. Here; take this. Place it on the ground and it will reveal nearby agents... for a time. Stop them, even if you must take their lives.",rewardGold=257400,rewardXP=8165,rewardItems={187736},starts={{npcID=181003}},ends={{npcID=181003}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64745] = {id=64745,name="Selfless Preservation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The automa were once abundant here, singing, constructing various things, carrying out the purpose of the First Ones. Then, invaders from the Maw slaughtered them all. The last automa to fall were protecting something important in a nearby structure. I witnessed one of the cursed Mawsworn steal a device by the door. The Elders say we should not meddle with artifacts, but would it be a transgression to recover what was stolen?",objectivesText="Recover the Stolen Artifact in the Arrangement Index and restore it to its rightful place.",rewardGold=128700,rewardXP=4085,rewardItems={188798},starts={{npcID=181273}},ends={{npcID=181273}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="group"},
[64758] = {id=64758,name="Following the Leader",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We sealed the door to the Slumbering Vault when we first arrived. It is a sanctum, a cradle of all that is precious here. The power that sleeps within should not be touched by us. If the Xy leader made it past the shields while we were distracted by the beauty of this place, I shudder to think of what they have already disturbed. Hurry! We must go to the Slumbering Vault and ensure its safety.",rewardGold=128700,rewardXP=8165,starts={{npcID=180936}},ends={{npcID=180936}},coords={x=0.336,y=0.598,source="quest_giver",mapID=1970},questType="standard"},
[64759] = {id=64759,name="Junk's Not Dead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="This automa has been hiding here! I suspect it will not be receptive to our help. I am hesitant to suggest this, but if the servitor were to associate you with this facility, it might be more amenable. If you have the means, copy the glyphs inscribed on similar automa outside. Those that the Maw have touched will be tainted, but I saw from my vantage point a few fallen automa in the sands with untarnished glyphs.",objectivesText="Obtain glyphs from 6 Depleted Servitors around the Arrangement Index.",rewardGold=257400,rewardXP=8165,starts={{npcID=181273}},ends={{npcID=181273}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="group"},
[64760] = {id=64760,name="Technical Difficulties",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The console is going haywire! We have to fix it! Maybe these buttons do something?",rewardGold=257400,rewardXP=8165,rewardItems={190582,190597,190602},rewardChoices={190597},starts={{npcID=180936}},ends={{npcID=181003}},coords={x=0.336,y=0.598,source="quest_giver",mapID=1970},questType="standard"},
[64761] = {id=64761,name="Core Competency",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The poor thing. The sacred should not be disturbed, but... will the elders judge us if we help it survive? This is preservation, not interference. ...I hope. We can power it back up. Use this depleted core as a conduit. Perhaps the larger wild animates in the nearby sands have enough energy to charge it.",objectivesText="Charge a Depleted Automa Core by draining slain wild creatures in the Arrangement Index.",rewardGold=257400,rewardXP=8165,rewardItems={187941},starts={{npcID=181273}},ends={{npcID=181273}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="group"},
[64762] = {id=64762,name="Revival of the Fittest",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="This core is brimming with energy! Use the charged core to revive the automa. Hopefully, it will no longer see us as a threat. Do be careful. The power of the First Ones is not meant for us to control.",objectivesText="Revive the Hidden Servitor in the Arrangement Index.",rewardGold=25740,rewardXP=1020,starts={{npcID=181273}},ends={{npcID=180610}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="standard"},
[64763] = {id=64763,name="Maintenance Mode",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The architect set forth these tasks: Stay safe. Restore the Protoform Repository when danger passes. The mortal knows the cyphers. The mortal will help with the tasks. Attuning of the energy terminals is required. Each terminal requires a codex. Invaders pilfered the necessary codices. Go.",objectivesText="Attune 4 Energy Terminals in the Arrangement Index.",rewardGold=257400,rewardXP=8165,rewardItems={189492},starts={{npcID=180610}},ends={{npcID=180610}},coords={x=0.612,y=0.374,source="quest_giver",zoneID=13536},questType="group"},
[64766] = {id=64766,name="Access Request",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The architect alone possesses the Restoration Matrix required for the restoration. The architect will restore the Protoform Repository. The mortal will gain access to the Chamber of Shaping and inform the architect of recent progress. The architect will restore the repository. Fulfillment of the task is imminent.",objectivesText="Find the Proto Architect in the Chamber of Shaping and retrieve a Restoration Matrix . Progress: The architect will assist us.",rewardGold=514800,rewardXP=10205,rewardItems={187628},starts={{npcID=180610}},ends={{npcID=180610}},coords={x=0.612,y=0.374,source="quest_giver",zoneID=13536},questType="group"},
[64767] = {id=64767,name="The Final Song",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Servitors do not possess the strength to restore the repositories. Nevertheless, the task must be completed. The mortal must stay close to protect the restoration process. Come.",objectivesText="Stay near Kodah while keeping enemies away to capture the Protoform Repository.",rewardGold=514800,rewardXP=10205,starts={{npcID=180610}},ends={{npcID=181273}},coords={x=0.612,y=0.374,source="quest_giver",zoneID=13536},questType="group"},
[64771] = {id=64771,name="Enlightened Exodus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Hello, my friend! An expedition of Cartel Al was sent in search of this place long ago, and was believed lost. I entered Zereth Mortis in hopes of saving my splintered cartel from the dangers of the Maw that have preceded me. At last, I have found my old friend! And yet, she refuses to return to safety. Perhaps others can be convinced. Will you try?",rewardGold=193050,rewardXP=8165,starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="world",worldTaskTitle="Enlightened Exodus"},
[64772] = {id=64772,name="Broken Circle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The jiro of Circle Olea work here. We make... They... make new lands and creatures for the Forge. Devourers attacked, but some jiro still survive. You must find them. Tell them to gather outside the cave to the north. I will clear the way. Do not tell them I sent you. They will not want to see me.",objectivesText="Find any surviving jiro and convince them to meet outside the cave.",rewardGold=257400,rewardXP=8165,starts={{npcID=181091}},ends={{npcID=180984}},coords={x=0.4,y=0.42,source="quest_giver",zoneID=13536},questType="standard"},
[64773] = {id=64773,name="A Jiro Guide to Not Being Eaten",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Devourers attacked. They overran the guardians. They still search for food. We are not safe. Reduce the devourers' numbers. This is how not to be eaten.",objectivesText="Reduce the devourer presence at the Terrace of Formation. Progress: Is it safe? There are so many devourers...",rewardGold=257400,rewardXP=8165,starts={{npcID=181098}},ends={{npcID=181098}},coords={x=0.38,y=0.398,source="quest_giver",zoneID=13536},questType="standard"},
[64775] = {id=64775,name="Mawdified Behavior",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="There is a devourer in the cave. It creates a rift. This should not be possible in Zereth Mortis . Enter the cave and destroy the devourer. Search for clues. See how it can open a rift. Be careful. This one is different from others. It has absorbed the magic of the First Ones. This has never happened before. Be ready for anything. I will stay here and protect the jiro.",objectivesText="Kill the Unraveller and search it for clues. Progress: Is the devourer destroyed? Did you find any clues?",rewardGold=257400,rewardXP=8165,rewardItems={189493},starts={{npcID=180984}},ends={{npcID=184469}},coords={x=0.394,y=0.318,source="quest_giver",zoneID=13536},questType="standard"},
[64778] = {id=64778,name="Rift Recon",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Devourers are a problem. Rifts are a bigger problem. They will keep bringing devourers. We must close them. To do this, we need information. Take the crescendal. Use it to analyze the rifts. Bring the information back to us.",objectivesText="Analyze 6 Warped Rifts. Progress: Do not break the crescendal. It can be... difficult to use.",rewardGold=257400,rewardXP=8165,starts={{npcID=181170}},ends={{npcID=181170}},coords={x=0.426,y=0.316,source="quest_giver",zoneID=13536},questType="standard"},
[64779] = {id=64779,name="Pound of Flesh",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Automa remove threats to us. But there are no more automa. We must help ourselves. We need magic. Devourers ate the orb magic. Now they are warped and twisted. But also full of magic. Bring us devourer flesh. We will extract the magic. We will need it to defeat the devourers.",objectivesText="Collect 30 Warped Flesh from devourers at Zovaal's Grasp. Progress: Devourers were not meant to eat this magic.",rewardGold=257400,rewardXP=8165,rewardItems={187950},starts={{npcID=181174}},ends={{npcID=181174}},coords={x=0.426,y=0.314,source="quest_giver",zoneID=13536},questType="standard"},
[64780] = {id=64780,name="Mawsteel, Maw Problems",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Zereth Mortis is sacred. Rifts should not form here. Something creates them. The metal you found has Maw magic. Devourers use it to make rifts. This is how they skirt our protections. Mawsteel shards are strewn across the area. Take these shards. Throw them off our cliffs. Make sure devourers do not use them to create rifts.",objectivesText="Lift 4 Mawsteel Shards and throw them off the cliffs.",rewardGold=257400,rewardXP=8165,starts={{npcID=181177}},ends={{npcID=181177}},coords={x=0.426,y=0.316,source="quest_giver",zoneID=13536},questType="standard"},
[64783] = {id=64783,name="Dance Dance Darkmoon",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=5861,description="Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, <class>. The rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em. Earn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn. Simon says, \"Are you up for the challenge?\"",objectivesText="Earn accolades by competing in the dance competition. Progress: Simon says, \"Show me what you got.\"",rewardItems={93724},starts={{npcID=181097}},ends={{npcID=181097}},questType="standard"},
[64785] = {id=64785,name="Overgrown Story",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose. There could be valuable research data to be obtained from these creatures. Use a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.",rewardXP=8165,rewardItems={187684},rewardCurrencies={{id=1979,amount=18},{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Overgrown Story"},
[64794] = {id=64794,name="Knowing is Half the Battle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description=", you should join Shandris and infiltrate the Mawsworn forces from the east. Whatever information you two uncover will inform us of your next course of action. Take care. We have no information on what you may find.",objectivesText="Meet Shandris near the Provis Strata.",rewardGold=25740,rewardXP=1020,starts={{npcID=181183}},ends={{npcID=181180}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64796] = {id=64796,name="Scour the Sands",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The little I have seen so far has given me almost no information about our enemies. We will have to take a closer look. I can hide the both of us from sight on your command. But stay away from the dreadlords--their eyes are sharp enough to spy even a hidden huntress.",objectivesText="Scout Provis Strata with Shandris Feathermoon . Progress: The less attention we draw, the better.",rewardGold=257400,rewardXP=8165,starts={{npcID=181180}},ends={{npcID=181180}},coords={x=0.486,y=0.492,source="quest_giver",zoneID=13536},questType="standard"},
[64797] = {id=64797,name="Harmony and Discord",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="These obelisks must be key to Zovaal's plans. Even without full knowledge of their purpose, we should stop the Mawsworn from meddling with them. I will bring this information to Highlord Bolvar. Head to Darion Mograine and do the same. He will need to plan his defenses around this.",objectivesText="Speak with Darion Mograine at Provis Terra.",rewardGold=128700,rewardXP=1020,rewardItems={188024,188032,188036,188037},rewardChoices={188032,188036},starts={{npcID=182046}},ends={{npcID=181193}},questType="standard"},
[64798] = {id=64798,name="What We Overcome",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=10534,mapID=1533,description="I understand now. All of us that were touched by Domination were able to tap into something. Whether nobility or vengeance, it gave the strength to resist. With all that I have faced, I have to remember that I am still here. And if there are those willing to stand with Sylvanas, I have to believe they will stand with me as well. I'm ready to try again. This time, I will overcome whatever I face.",objectivesText="Defeat the Mawbound Monstrosity and infuse the final shard. Progress: We will not fail. There is no other choice but oblivion.",rewardGold=257400,rewardXP=10205,rewardItems={188009,188015,188020,188027},starts={{npcID=181284}},ends={{npcID=181280}},coords={x=0.592,y=0.884,source="quest_giver",zoneID=10534},questType="standard"},
[64799] = {id=64799,name="The Broken Crown",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Our friends have returned from the Sepulcher of the First Ones with a familiar face. Anduin... What terrible things he has endured. But as difficult and painful as it is, we must uncover what he knows. The Jailer has blocked our way within the Sepulcher, and we risk falling victim to Domination ourselves if we blindly follow. He is our best hope.",objectivesText="Speak to Anduin Wrynn in the Geometric Cavern. Progress: We must defeat Zovaal, or all is lost.",rewardGold=25740,rewardXP=1020,starts={{npcID=181183}},ends={{npcID=181229}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64800] = {id=64800,name="Our Last Option",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Zovaal has blocked our pursuit. If we are to defeat him, we must find a way to withstand Domination. But to overcome it, we need to understand how it works. The Primus of Maldraxxus created Domination, he will be able to tell us more. I asked Taelia to bring a piece of the Helm of Domination to Zereth Mortis. I dread to think of what might happen were I to try to carry it again... Let us discuss the way forward.",objectivesText="Listen to the plan. Progress: We can never turn things back to the time that was. We can only live with the choices made, and move forward.",rewardGold=25740,rewardXP=1020,starts={{npcID=181229}},ends={{npcID=181229}},coords={x=0.332,y=0.69,source="quest_giver",zoneID=13536},questType="standard"},
[64801] = {id=64801,name="Elder Eru",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Since we have earned the trust of the Enlightened, I have learned more about their explorations into Zereth Mortis . They know more than they are willing to tell, but often do not act on that knowledge. Perhaps where they observe, we can be a catalyst for action. In a secluded corner called the Lexical Glade, there is an elder named Eru. She may be able to give us insight on how we might use the language of the First Ones. Seek her out, and see if she will help us.",objectivesText="Find Elder Eru outside the Lexical Glade.",rewardGold=25740,rewardXP=1020,starts={{npcID=181229}},ends={{npcID=181266}},coords={x=0.332,y=0.69,source="quest_giver",zoneID=13536},questType="standard"},
[64802] = {id=64802,name="Hello, Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I created Domination as a tool to punish Zovaal. My anger informed that creation, and now we pay the price for my hubris. Even Eternal Ones err on occasion. But we are not without hope. Take the half of the broken Helm of Domination, and test it upon one of your own. If it retains enough power, it can then be used to test it elsewhere in Zereth Mortis .",objectivesText="Test the broken Helm of Domination on Darion Mograine. Progress: We will not give up until we have stopped Zovaal.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181245}},ends={{npcID=181245}},coords={x=0.332,y=0.688,source="quest_giver",zoneID=13536},questType="standard"},
[64803] = {id=64803,name="Testing One Two",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The creatures of Zereth Mortis have existed here since well before I created Domination. We have seen the effects that Zovaal's forces have had on them, but I believe there is more to be learned. Use the helm on the denizens of Zereth Mortis and see what you can uncover about a natural resistance.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181245}},ends={{npcID=181266},{npcID=184182}},coords={x=0.332,y=0.688,source="quest_giver",mapID=1970},questType="standard"},
[64804] = {id=64804,name="Cryptic Catalogue",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="This area is a repository of various texts. Hmmm? What do they say? I have no idea! I have dedicated myself to their catalogue and organization. This is more important than ever, with invaders destroying the balance in Zereth Mortis ! We must preserve what we have found so far. You can help. Go into the glade and memorize the phrases there, then meet me down in the grotto. There is something in it that might help you test that helm of yours further.",objectivesText="Memorize Phrases in the Lexical Glade. Progress: Think how much we could learn if we understood the intentions of the First Ones.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181266}},ends={{npcID=184182}},coords={x=0.562,y=0.832,source="quest_giver",zoneID=13536},questType="standard"},
[64805] = {id=64805,name="The Not-Scientific Method",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The language of the First Ones is not static like most others. It evolves. Creatures like the sentries are more advanced than your average poultrid, obviously. Their more complex thought processes give them an innate resistance to the invaders' overriding magic. But you should not take my word for it. We can actually test this! In the grotto there is a librarian. Take those phrases you memorized and infuse them into it. Then try out your helm.",objectivesText="Test the Broken Helm on an activated Lexicon Librarian and observe the results.",rewardGold=257400,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=184182}},ends={{npcID=184182}},coords={x=0.592,y=0.788,source="quest_giver",zoneID=13536},questType="standard"},
[64806] = {id=64806,name="Where the Memory Resides",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1970,description="I think I know what will be asked of us in Bastion . It will not be easy. With this half of the Helm, we have collected the first part of what is needed to resist Domination. But there are those of us who have also suffered from it. Lived through it. In a way, it has marked us. All of us. There must be something in those experiences that will help us break free from Zovaal's influence. Let us go to the Chamber of First Reflection in Bastion .",objectivesText="Meet Highlord Bolvar inside the Chamber of First Reflection in Bastion .",rewardGold=25740,rewardXP=1020,starts={{npcID=181367}},ends={{npcID=181280}},coords={x=0.572,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64807] = {id=64807,name="What We Wish to Forget",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="While the language of the Progenitors will aid us, there is another trait that will help break Domination's hold on us. An indomitable will. Those of us who have endured before, and survived, have that inherent resistance, which we will offer up to be infused into each of the shards. The Primus has assured me that this will work. With no other options, this is the only way. I trust that it will be worth the suffering.",objectivesText="Assist with the ritual and infuse the Shards of Domination . Progress: We will do whatever it takes.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181280}},ends={{npcID=181280}},coords={x=0.592,y=0.882,source="quest_giver",zoneID=10534},questType="standard"},
[64808] = {id=64808,name="What Makes Us Strong",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=10534,mapID=1533,description="I wish that I knew of this place sooner. Where terrible darkness could be purged from oneself, memories examined and expunged... I am willing to do whatever it takes to help defeat Zovaal, no matter the cost. This is the only way.",objectivesText="Assist with the ritual and infuse the Shards of Domination . Progress: It takes more than raw strength to do what must be done.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181284}},ends={{npcID=181284}},coords={x=0.592,y=0.884,source="quest_giver",zoneID=10534},questType="standard"},
[64809] = {id=64809,name="One Half of the Equation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The Primus's theory about the language of the First Ones has borne out. Still, it may not be enough. While the Primus finalizes his plans, let us go deep into the Endless Sands to find pieces of this power to infuse the helm. Darion, Taelia, and I will meet you there to help with the Mawsworn.",objectivesText="Travel to the Deserted Overlook.",rewardGold=25740,rewardXP=1020,starts={{npcID=181229}},ends={{npcID=181367}},coords={x=0.332,y=0.69,source="quest_giver",zoneID=13536},questType="standard"},
[64810] = {id=64810,name="Oppress and Destroy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="What we seek is in the vaults of the Endless Sands. To reach them will require strength and numbers. Together we will destroy the Mawsworn. I look forward to taking the fight directly to them. Remember, they will be vulnerable to the broken shard from the Helm of Domination.",objectivesText="Slay Mawsworn in the Endless Sands. Progress: Such magnificent desolation.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181367}},ends={{npcID=181367}},coords={x=0.572,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64811] = {id=64811,name="Aggressive Excavation",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=13536,mapID=1970,description="Elder Eru said that we could find the most complex examples of the First Ones' language out here. We'll need to fight our way to the vaults, and then infuse the helm once we find those phrases. On a personal note, I never thought I'd have the chance to fight alongside my father. Though with the stakes this high, it somehow feels like exactly the place I'm supposed to be. I am ready when you are.",objectivesText="Collect the Inscrutible Phrases.",rewardGold=257400,rewardXP=10205,rewardItems={190980,190981,190982,190986,190987,190988,190992,190993,190994,190998,190999,191000},rewardChoices={190980,190981,190982,190986,190987,190988,190992,190993,190994},starts={{npcID=181372}},ends={{npcID=181367}},coords={x=0.572,y=0.312,source="quest_giver",zoneID=13536},questType="standard"},
[64812] = {id=64812,name="Forge of Domination",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="We have all of the pieces we need. The broken half of the helm has been augmented with the complexity of the language of the First Ones, and the shards bear our memories. Our will to resist Domination. All that remains is for the Primus to reforge the Helm, then we will be able to draw upon that combined power for ourselves. I know that it is dangerous, but it is our only hope.",objectivesText="Travel to The Runecarver's Oubliette in Torghast.",rewardGold=25740,rewardXP=1020,starts={{npcID=181280}},ends={{npcID=181280}},coords={x=0.592,y=0.882,source="quest_giver",zoneID=10534},questType="standard"},
[64813] = {id=64813,name="The Crown of Wills",level=60,requiredLevel=60,faction="both",expansion=8,mapID=1912,description="When I created Domination, I did not foresee how much pain it would cause the realms. Not only the Shadowlands, but yours as well. It is time we take this helm, this symbol of that magic, and reforge it anew. But, not for the same purpose it once had. Let it represent the strength of will that you and your kind possess, so that it may help us overcome and defeat Zovaal at last.",objectivesText="Reforge the Helm of Domination. Progress: There is no going back.",rewardItems={187785},starts={{npcID=181384}},ends={{npcID=181384}},questType="standard"},
[64814] = {id=64814,name="Battle for the Forge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Our forces have been holding out so far, but we have not secured the area. We could use some assistance cutting down the enemy's numbers. This should be a simple task for you, Maw Walker.",objectivesText="Kill 8 Mawsworn forces. Progress: Is it done?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181193}},ends={{npcID=181193}},coords={x=0.42,y=0.48,source="quest_giver",zoneID=13536},questType="standard"},
[64815] = {id=64815,name="Together, We Ride",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The four covenants are working together here along with the automa. Unfortunately, some of our soldiers have been separated or wounded and are unable to return back here. If you could aid them, that would help tremendously.",objectivesText="Aid 5 covenant forces.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181193}},ends={{npcID=181193}},coords={x=0.42,y=0.48,source="quest_giver",zoneID=13536},questType="standard"},
[64816] = {id=64816,name="Reality's Doorstep",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The time has come to follow Zovaal into the very heart of the Shadowlands. We must return to Zereth Mortis and finish this.",objectivesText="Return to Zereth Mortis .",rewardGold=25740,rewardXP=1020,starts={{npcID=181379}},ends={{npcID=181183}},questType="standard"},
[64817] = {id=64817,name="In Plain Sight",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="That sound! It came from the direction of the obelisk at Provis Flora. Impossible. We've let no one through. Hurry, . Follow me!",objectivesText="Defend the obelisk at Provis Flora. Progress: We must hurry!",rewardGold=514800,rewardXP=10205,starts={{npcID=181193}},ends={{npcID=183615}},coords={x=0.42,y=0.48,source="quest_giver",zoneID=13536},questType="standard"},
[64818] = {id=64818,name="Reinforcements May Be Necessary",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The dreadlords infiltrated deep into our ranks. Bolvar must know what has happened. I cannot leave my position here. Quickly, give him the news. Perhaps the Enlightened council will have advice as well.",objectivesText="Speak with Bolvar Fordragon at Haven.",rewardGold=25740,rewardXP=1020,starts={{npcID=183615}},ends={{npcID=181183}},coords={x=0.414,y=0.534,source="quest_giver",zoneID=13536},questType="standard"},
[64820] = {id=64820,name="This is Your Fault, Fix It",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Provis Fauna is normally regulated by autonomous constructs, but there have been reports that they are no longer working. According to the reports, you are the one responsible for the tampering of these nodes. Which means it is on you to fix them. Take this tuner, it should help--and once they are repaired, do not meddle with them again.",objectivesText="Fix 5 defense nodes.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=177486}},ends={{npcID=177486}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64821] = {id=64821,name="Nothing is True",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="If we are dealing with dreadlords, they could be disguised as anything... including the denizens of Zereth Mortis . Fortunately we have just the thing for dispelling their illusions. Search the fields and test the automa. If you find any dreadlords, take care of them.",objectivesText="Find and kill 4 Dreadlord Saboteurs .",rewardGold=257400,rewardXP=8165,rewardItems={187839},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181183}},ends={{npcID=181183}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64822] = {id=64822,name="A Break in Communication",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Mograine's request for reinforcements is unusual. We were already planning on reinforcing the area, and sent three different outfits his way. From the sound of it, none of them have arrived. See if you can find their commanders and make sure they make it to Mograine.",objectivesText="Reassign orders to three covenant commanders. Progress: Have you found them?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181183}},ends={{npcID=181183}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64823] = {id=64823,name="Doppelganger Duel",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=13536,mapID=1970,description="Something about this doesn't sit right with me. From what you reported, this seems like intentional sabotage from within our ranks... or the work of more dreadlords. If dreadlords are involved, then the obelisk may be at risk! Get to it--if we linger on this it may be too late!",objectivesText="Find the Mawsworn presence at the Circle of Thought. Progress: Time is of the essence here.",rewardGold=514800,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181183}},ends={{npcID=183724}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64824] = {id=64824,name="Fighting for the Forge",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=13536,mapID=1970,description="We made our way here as soon as we could. Anduin has been sighted near the structure in the middle of this land, referred to as the Forge of Afterlives. No doubt the Jailer will join him soon. We need to leave immediately.",objectivesText="Head to the Forge of Afterlives with Jaina.",rewardGold=257400,rewardXP=10205,starts={{npcID=183724}},ends={{npcID=183717}},coords={x=0.472,y=0.636,source="quest_giver",zoneID=13536},questType="standard"},
[64825] = {id=64825,name="Seeking Haven",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=13536,mapID=1970,description="I am at a loss. We have no way to follow Zovaal and Anduin. I'll open a portal back to Haven. We will discuss our next steps there.",objectivesText="Return to Haven with Jaina and Baine.",rewardGold=257400,rewardXP=1020,rewardItems={190742,190745,190748,190751},starts={{npcID=183717}},ends={{npcID=181183}},coords={x=0.574,y=0.534,source="quest_giver",zoneID=13536},questType="standard"},
[64829] = {id=64829,name="Finding Tahli",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="After eons of tranquility, the Maw's influence has brought sorrow to Zereth Mortis . One of our acolytes, Tahli , has found it particularly difficult to process recent events. She left some time ago and has not returned. Will you check on her? She was last seen heading toward the ruins that are buried under the sands.",objectivesText="Find Tahli near the Arrangement Index.",rewardGold=25740,rewardXP=1020,starts={{npcID=180630}},ends={{npcID=181273}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="group"},
[64830] = {id=64830,name="Enlisting the Enlightened",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The fate of Sylvanas is not my immediate priority. The Jailer has destroyed the Harmonic Channels, ensuring that we cannot follow him. Perhaps the studious Enlightened Brokers know something about these channels that will help us--but broker cooperation comes often with strings attached. Do whatever they demand. We must learn more.",objectivesText="Persuade the Elders of Haven to offer their assistance.",rewardGold=25740,rewardXP=1020,starts={{npcID=181183}},ends={{npcID=184532}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64831] = {id=64831,name="Remnants of the First Ones",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Some evidence of the Mawsworn's destruction may remain in Provis Esper. Recovering that evidence will provide some clue as to how to follow this Jailer. Let us hunt together. I will know the sign of the First Ones's magic when we are in its vicinity.",objectivesText="Collect 3 Conduction Remnants . Progress: Have we found all of the remnants?",rewardGold=257400,rewardXP=8165,rewardItems={187730,187731,187732},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=183139}},ends={{npcID=183168}},coords={x=0.562,y=0.578,source="quest_giver",zoneID=13536},questType="standard"},
[64832] = {id=64832,name="Reclaiming Provis Esper",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Provis Esper is overrun with devourers, buzzing around like hungry vespoids. They are destroying the local automa, which is not at all what the First Ones intended. A cleansing is in order. For our safety and to restore the natural order, clear some of them out.",objectivesText="Kill 20 Insatiable Mites , 5 Soul-Parched Gorgers , and 2 Reality Breachers . Progress: Have you cleansed Provis Esper?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=183139}},ends={{npcID=183168}},coords={x=0.562,y=0.578,source="quest_giver",zoneID=13536},questType="standard"},
[64833] = {id=64833,name="Forging Unity from Diversity",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The other Elders follow a strict interpretation of how best to honor the works of the First Ones. I am not so inflexible. Our end goal is the same. Let us return to the area where you last saw the Jailer.",objectivesText="Meet Elder Ara above Provis Esper.",rewardGold=29200,rewardXP=1020,starts={{npcID=184532}},ends={{npcID=183139}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64834] = {id=64834,name="Glow and Behold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Look, . The remnants are faintly glowing! They must be reacting to something in Pilgrim's Grace. Find out what is causing this reaction!",objectivesText="Locate what is causing the Conduction Remnants to react. Progress: The remnants reacted to this translocator? Incredible!",rewardGold=128700,rewardXP=4085,starts={{npcID=183251}},ends={{npcID=183252}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="standard"},
[64835] = {id=64835,name="Pluck from the Vines",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I ran, scrambling through the thorny foliage, the lashers snapping at my heels. My fellow pilgrims were not so lucky. I could hear their screams of pain and horror as I fled. You must find a way inside. Rescue them, !",objectivesText="Rescue 5 missing pilgrims. Progress: Have you rescued the missing pilgrims?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181771}},ends={{npcID=184323}},coords={x=0.48,y=0.75,source="quest_giver",zoneID=13536},questType="standard"},
[64836] = {id=64836,name="Nip It in the Bud",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13898,mapID=1970,description="The Catalyst Wards used to be peaceful. Pilgrims have been coming here for ages to observe the wonders of the First Ones. But this place is no longer safe. The Cultivator showed no mercy and no reason as it slew several of our brethren. You must destroy it. Other Elders would disagree with me. The other Elders are wrong.",objectivesText="Kill the Cultivator . Progress: What could have caused the Cultivator to behave so irrationally... so violently?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=183338}},ends={{npcID=183338},{npcID=183359}},coords={x=0.48,y=0.75,source="quest_giver",zoneID=13536},questType="standard"},
[64837] = {id=64837,name="The Pilgrim's Journey",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Pilgrim's Grace is a sacred site for the Enlightened. The Elders there have an intimate understanding of the creations of the First Ones. We will find answers there about these strange remnants we have found. Meet me at Pilgrim's Grace. It is not far.",objectivesText="Meet Elder Ara at Pilgrim's Grace.",rewardGold=25740,rewardXP=1020,starts={{npcID=183168}},ends={{npcID=183251}},coords={x=0.548,y=0.494,source="quest_giver",zoneID=13536},questType="standard"},
[64838] = {id=64838,name="Where There's a Pilgrim, There's a Way",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="If the remnants can be restored, someone in Pilgrim's Grace may know how. Begin with Elder Nirav. I hope he is willing to help. He seems anxious and distracted today. Find me in town when you are done.",objectivesText="Speak to the inhabitants of Pilgrim's Grace. Progress: Have you spoken to the Enlightened in Pilgrim's Grace?",rewardGold=128700,rewardXP=4085,starts={{npcID=183252}},ends={{npcID=183530}},coords={x=0.646,y=0.536,source="quest_giver",zoneID=13536},questType="standard"},
[64839] = {id=64839,name="Root of the Problem",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13898,mapID=1970,description="I suspect we can harness the growth energy present in these plants for our own purposes, but I will need fresh samples. You can harvest energized plant matter from any of the lashers or vine-choked automa nearby, or those inside the Catalyst Wards.",objectivesText="Collect energized plant matter. Progress: Have you recovered the energized plant matter?",rewardGold=257400,rewardXP=8165,rewardItems={188276},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181771}},ends={{npcID=181771},{npcID=184323}},coords={x=0.48,y=0.75,source="quest_giver",zoneID=13536},questType="standard"},
[64840] = {id=64840,name="Unchecked Growth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="This growth energy is highly unusual. I would like to know more about how it affects the local automa. Harvest replicating essence from deceased automa in the Catalyst Gardens. Bring it back to me for study.",objectivesText="Collect 12 Replicating Essence . Progress: Do you have the replicating essence ?",rewardGold=257400,rewardXP=8165,rewardItems={187835},rewardCurrencies={{id=1822,amount=1}},starts={{npcID=184323}},ends={{npcID=184323}},coords={x=0.476,y=0.798,source="quest_giver",zoneID=13536},questType="standard"},
[64841] = {id=64841,name="Take Charge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="That floating structure looming overhead is the Creation Catalyst. I cannot get close to it. The tower is overloaded with an excess of Progenitor energy. To travel there now would be suicide. There are consoles in the gardens that can be used to discharge that energy. Do so.",objectivesText="Discharge the excess energy of the Creation Catalyst. Progress: Is it safe to fly up to the Creation Catalyst?",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=181814}},ends={{npcID=181814}},coords={x=0.476,y=0.802,source="quest_giver",zoneID=13536},questType="standard"},
[64842] = {id=64842,name="Flora Frenzy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Those guardian automa will shoot down anything that attempts to reach the Creation Catalyst. May I suggest fighting fire with fire? Or rather, fighting the creations of the First Ones with the creation energy of the First Ones? I have had little time to adequately test my theory, but this potion should provide the boost you need to destroy them... ideally without dying from exposure to the creation energy in the process.",objectivesText="Drink Feroz 's solution and destroy the automa of the Catalyst Gardens. Progress: Your safety is probable, but not guaranteed.",rewardGold=257400,rewardXP=8165,rewardChoices={190977,190978,190979,190983,190984,190985,190989,190990,190991,190995,190996,190997},starts={{npcID=184442}},ends={{npcID=184442}},coords={x=0.476,y=0.798,source="quest_giver",zoneID=13536},questType="standard"},
[64843] = {id=64843,name="Key Crafting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="With those agitated automa quelled, there is but one task ahead. We shall ferry you and your Enlightened companion up to the Creation Catalyst. The rest is up to you.",objectivesText="Restore the Translocator Key at the Creation Catalyst. Progress: It is incredible to see the Creation Catalyst up close.",rewardGold=257400,rewardXP=10205,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181814}},ends={{npcID=184153}},coords={x=0.476,y=0.802,source="quest_giver",zoneID=13536},questType="standard"},
[64844] = {id=64844,name="The Pilgrimage Ends",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="You have rescued many pilgrims, and I have restored your entrance to the Sepulcher. With that, our bargain is concluded--and so, too, is my pilgrimage. But your journey continues. Return to the overlook behind Pilgrim's Grace and open the translocator. My thanks, . This adventure has been... enlightening.",objectivesText="Return to the overlook behind Pilgrim's Grace. Progress: Let us listen to what they have to say.",rewardGold=25740,rewardXP=1020,rewardItems={188010,188016,188023,188028},rewardChoices={188010,188016,188023,188028},starts={{npcID=184153}},ends={{npcID=181948}},coords={x=0.474,y=0.884,source="quest_giver",zoneID=13536},questType="standard"},
[64846] = {id=64846,name="Torghast",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,description="Countless souls are tortured in the halls of Torghast. They need your help!",objectivesText="Speak with Tal-Inara .",rewardGold=25740,rewardXP=850,starts={{npcID=167486}},ends={{npcID=167486}},questType="standard"},
[64849] = {id=64849,name="Tower of the Damned",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13400,description="We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there. He believes there is a path for you to reach this place... and that someone there requires your aid. Do what you must to reach Torghast and aid anyone who is within.",objectivesText="Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.",rewardGold=25740,rewardXP=850,starts={{npcID=159478}},ends={{npcID=159478}},questType="standard"},
[64850] = {id=64850,name="Traversing Torghast",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1911,description="I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish . I am here to find great treasures within Torghast with the aid of my box. I can see you admiring it. Perhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead? I shall even reward you for anything you discover within.",rewardGold=772200,rewardXP=13630,rewardCurrencies={{id=1828,amount=150},{id=1877,amount=6}},questType="world",worldTaskTitle="Traversing Torghast"},
[64852] = {id=64852,name="Aeon Matrix",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Firim could make use of this item>",objectivesText="Deliver the item to Firim . Provided item:",rewardGold=257400,rewardXP=8165,ends={{npcID=177958}},coords={mapID=1970,source="quest_giver",x=0.342,y=0.485},questType="standard"},
[64853] = {id=64853,name="Two Paths to Tread",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Did that answer your question? Oh, you wanted a way to completely resist Domination magic? That I'm afraid I do not know. The First Ones' language will only delay the inevitable. What I can tell you is that if you want to find more deliciously complex phrases of the First Ones' language, you should go to the Endless Sands and search the vaults. I wish I could go myself, but it has been overrun by those nasty Mawsworn. Good luck with the rest of your studies!",objectivesText="Report to the Primus in the Geometric Cavern.",rewardGold=25740,rewardXP=1020,starts={{npcID=184182}},ends={{npcID=181245}},coords={x=0.592,y=0.788,source="quest_giver",zoneID=13536},questType="standard"},
[64854] = {id=64854,name="Trappings of Success",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The wildlife of Zereth Mortis are attracted to the frenetic creation energy that flows throughout the land. When the wildlife finds something charged with that energy... they eat it! The Mawsworn Cryptoseers have become aware of this and are attempting to find such wildlife to extract any remnants of that energy. Eliminate the Cryptoseers, and use the Containment Trap to subdue and examine the wildlife for our research.",rewardXP=8165,rewardItems={187684},rewardCurrencies={{id=1979,amount=20},{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Trappings of Success"},
[64860] = {id=64860,name="Aetheric Lattice",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Firim could make use of this item>",objectivesText="Deliver the item to Firim . Provided item:",rewardGold=257400,rewardXP=8165,ends={{npcID=177958}},coords={mapID=1970,source="quest_giver",x=0.342,y=0.485},questType="standard"},
[64861] = {id=64861,name="Kismetric Disc",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Firim could make use of this item>",objectivesText="Deliver the item to Firim . Provided item:",rewardGold=257400,rewardXP=8165,rewardItems={190062},rewardCurrencies={{id=2009,amount=200}},ends={{npcID=177958}},coords={mapID=1970,source="quest_giver",x=0.342,y=0.485},questType="standard",worldTaskTitle="Kismetric Disc"},
[64867] = {id=64867,name="Supplies from The Enlightened",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Ah, yes. How I've looked forward to this moment for quite some time! Come, visit me. Let us share this achievement together. I've prepared something special just for you.",objectivesText="Speak with Vilo at Haven in Zereth Mortis .",rewardItems={187780,189471,189973,190177,190928,190929,190930,190931,190932,190933,190934,190935,190937,190939},starts={{npcID=182257}},ends={{npcID=182257}},questType="standard"},
[64870] = {id=64870,name="Paragon of Enlightened Brokers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="My, my. You've been busy, haven't you?",objectivesText="Speak with Vilo at Haven in Zereth Mortis .",ends={{npcID=182257}},coords={mapID=1970,source="quest_giver",x=0.348,y=0.642},questType="standard"},
[64871] = {id=64871,name="The Dragon at the Door",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13769,mapID=85,description="That blue dragon will collapse the creche and trap us inside! He claims to serve Malygos. That name is familiar, but... why would any dragon want to keep us prisoner? Listen, $p. We were trained to fight beside the dragons, not against them. But we have been left with no choice. Time to do what must be done, evoker.",rewardGold=14300,rewardXP=1770,rewardItems={193914},ends={{npcID=184269}},questType="standard"},
[64872] = {id=64872,name="The Fire Within",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=14433,mapID=2151,description="You are an evoker, . The best of the best. An elite soldier who has mastered the skills of each of our weyrns. I expect a lot of you. Your memories may be broken, but the might of dragons courses through your veins. Harness it. One of your most potent weapons is your breath attack. The fire within becomes more powerful the longer you inhale. These insects swarming over our training grounds should make fine targets.",rewardGold=7150,rewardXP=1415,starts={{npcID=184269}},ends={{npcID=184269}},coords={x=0.442,y=0.614,source="quest_giver",mapID=2151},questType="standard"},
[64873] = {id=64873,name="Stretch Your Wings",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13769,mapID=85,description="I am heartened to see that so many escaped the War Creche. My own weyrn... was not as fortunate. There are other creches throughout the Reach, filled with dracthyr in peril. Strong wings will be needed to reach them. Focus. Remember your training. Get a feel for the wind again. You must regain your strength and fly to the other creches. The time for rest is over.",rewardGold=241020,rewardXP=1415,rewardItems={195044},starts={{npcID=181054}},ends={{npcID=192889}},coords={x=0.444,y=0.61,source="quest_giver",mapID=85},questType="standard"},
[64875] = {id=64875,name="Something Wonderful",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description=", I am so glad you are here! Firim sent me to find you. It's the oracle, it... well... it's hard to describe. You should come see it for yourself. Hurry!",objectivesText="Travel to Exile's Hollow to witness for yourself what is happening to Saezurah. Progress: We must hurry, <name>. We do not know how long this will last.",rewardGold=64350,rewardXP=2040,starts={{npcID=182556}},ends={{npcID=177958}},coords={x=0.354,y=0.65,source="quest_giver",zoneID=13536},questType="standard"},
[64876] = {id=64876,name="Music of the Spheres",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="It started gradually, the energy emanating from the oracle in increasing amounts, until the grand design you see before you took shape. The terrible clamor ringing in our ears began shortly afterward. My attempts to approach the fractals have been... unsuccessful. But they appear to resonate with Pocopoc. You share a special bond with it; perhaps you shall have better luck than I.",objectivesText="Examine the fractals that surround Saezurah's body.",rewardGold=257400,rewardXP=8165,starts={{npcID=177958}},ends={{npcID=177958}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[64878] = {id=64878,name="What a Long Strange Trip",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Pocopoc , albeit distant and distorted.> I... am Saezurah. Oracle. This automa... speaks with my voice. Acts with my will. For now. The pattern... is torn. Disrupted. Mending must be done. A great hunger swarms the sands. What it seeks must not be consumed. Journey with me. Follow my voice.",objectivesText="Go with Pocopoc to make sense of your vision. Progress: Pocopoc has not reached the destination yet.",rewardGold=257400,rewardXP=8165,rewardChoices={190977,190978,190979,190983,190984,190985},starts={{npcID=181706}},ends={{npcID=181706}},coords={x=0.34,y=0.474,source="quest_giver",zoneID=13536},questType="standard"},
[64879] = {id=64879,name="A Monumental Discovery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Maw Walker--Pelagos stopped by earlier to give a report and said that the oracle's preparations were complete, and you were urgently needed. If this is something that can help our efforts, I want you involved. Head to Exile's Hollow and see what they need.",objectivesText="Meet Firim in Exile's Hollow.",rewardGold=64350,rewardXP=2040,starts={{npcID=181183}},ends={{npcID=177958}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64888] = {id=64888,name="Borrowed Power",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The land provides. The land thirsts. Invaders devour what we require. Reclaim what has been consumed. Absorb what remains abundant. Wings need wind to fly. We need power to ascend.",objectivesText="Defeat volatile lured enemies or soak power from pools to reclaim Cosmic Energy to empower Pocopoc . Progress: More power to Pocopoc .",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=181706}},ends={{npcID=181706}},coords={x=0.34,y=0.474,source="quest_giver",zoneID=13536},questType="standard"},
[64889] = {id=64889,name="Match Made in Zereth Mortis",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The cyphers are the key. Each one, a step along the path. You must find them all. Enter the inner chamber. The Prime Locus Arrangement awaits. The first step toward ascension. Toward the vessel.",objectivesText="Study the Locus Arrangements and use the Locus Shift to reach the Ultimus Locus. Progress: Need to gather the cyphers to reach the door where the vessel waits.",rewardGold=514800,rewardXP=10205,starts={{npcID=181706}},ends={{npcID=181706}},questType="standard"},
[64935] = {id=64935,name="Between a Rock & a Rock",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="<Piles of rock are scattered around the area. The devourers have done enough damage to obscure the cypher you seek. Perhaps one of the nearby servitors could be made to clear the rubble.>",objectivesText="Smash the rubble barring access to the secundus locus arrangement. Progress: Until we discover the cypher, we need to keep smashing rubble.",rewardGold=257400,rewardXP=8165,starts={{npcID=375517}},coords={x=0.484,y=0.271,source="quest_giver",zoneID=13536},questType="standard"},
[64936] = {id=64936,name="Searching High and Low",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Three locks upon the door, three keys hidden atop the zenith. Find the phrases. Speak the words. Secure the vessel.",objectivesText="Gather the Ingress Phrases on the Ultimus Locus that are needed to claim the Vessel. Progress: The vessel slumbers high above.",rewardGold=128700,rewardXP=8165,starts={{npcID=183701}},ends={{npcID=184949}},questType="standard"},
[64937] = {id=64937,name="You Light Up My Life",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Great power entices great hunger. The insatiable devourers scale the cliffs in search of sustenance. Soon they will swarm the plateau. They seek to consume all they encounter. The vessel. Its power. Us. This must not come to pass. Wield this automa. Silence their slavering howls.",objectivesText="Use Pocopoc to defend the vessel against the devourers.",rewardGold=514800,rewardXP=10205,rewardItems={188009,188013,188022,188029},starts={{npcID=184949}},ends={{npcID=181706}},coords={x=0.478,y=0.34,source="quest_giver",zoneID=13536},questType="standard"},
[64941] = {id=64941,name="Chicken Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>",objectivesText="Bring the Chicken Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
[64942] = {id=64942,name="Call of the Primus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis . The time has come to follow him. Within the Arbiter's Chamber, we will forge our own path. Hurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.",objectivesText="Speak with Tal-Inara in Oribos to travel to the Arbiter's Chamber.",rewardGold=25740,rewardXP=1020,ends={{npcID=181655}},questType="standard"},
[64944] = {id=64944,name="A Hasty Voyage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The path to Zereth Mortis is open. We must part ways here. The Eternal Ones are forbidden from returning to the place of our creation. Zovaal has defied the most sacred laws of the Progenitors. You must undertake this journey alone. Go. Find a foothold in Zereth Mortis so that we can send the covenant forces through. Then we will pursue the Jailer and end his madness.",rewardGold=257400,rewardXP=8165,rewardCurrencies={{id=1822,amount=2}},starts={{npcID=181655}},ends={{npcID=181931}},coords={x=0.332,y=0.504,source="quest_giver",mapID=1970},questType="standard"},
[64945] = {id=64945,name="Strangers in a Strange Land",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Did we... did we reach Zereth Mortis ? And are we walking on water? What a wondrous place! At least, from what I can tell through this fog. I think I can make out a structure in the distance. Perhaps we will find answers there.",objectivesText="Accompany Pelagos and explore your surroundings.",rewardGold=257400,rewardXP=8165,starts={{npcID=181931}},ends={{npcID=181561}},coords={x=0.34,y=0.608,source="quest_giver",zoneID=13536},questType="standard"},
[64947] = {id=64947,name="Give Me A Hand",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="To drive the Jailer from Zereth Mortis , we must direct all our resources against the enemy. An object of potential power lies in a nearby repository, but the chamber's defenses respond only to automa. I would never harm their kind, but I have encountered one that no longer functions. If you extract its hand, we could use the inert appendage to gain access to the repository. I find such use of the First Ones' creations unsavory, but we cannot abide the presence of Mawsworn in this realm.",objectivesText="Assist Firim .",rewardGold=257400,rewardXP=8165,rewardItems={188954},starts={{npcID=181561}},ends={{npcID=184062}},coords={x=0.34,y=0.608,source="quest_giver",zoneID=13536},questType="standard"},
[64949] = {id=64949,name="For Research Purposes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I have taken pains not to disturb the automa during my time in Zereth Mortis , and so far they have paid little attention to me. It seems recent events have changed that. Again, let me be clear that I have no wish to harm the creations of the First Ones. But if, in the course of your efforts, conflict with the automa becomes inevitable, we must ensure that some good can come of it. If I can examine fragments of fallen automa, it may provide knowledge to use against the Mawsworn. Go carefully.",objectivesText="Collect 12 Intact Automa Fragments from Alerted Automa within Genesis Vestibule Progress: Did you find any useful fragments?",rewardGold=257400,rewardXP=8165,rewardItems={188956},starts={{npcID=184062}},ends={{npcID=184062}},coords={x=0.312,y=0.512,source="quest_giver",zoneID=13536},questType="standard"},
[64950] = {id=64950,name="A Mutual Exchange",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="It seems the other automa did not appreciate our appropriation of their colleague's hand. They have become hostile. Unfortunate, but we cannot allow this to impede our progress. The automa's hand should activate a console within the Genesis Repository. I believe it holds an object of great potential. After you acquire it, I will guide you to a place that may provide a means to reach the allies you left behind. Do we have an accord?",objectivesText="Use the Automa Hand to activate an Automa Console and obtain the Repository Treasure. Progress: Did you acquire the object from the console?",rewardGold=257400,rewardXP=1020,rewardItems={188955},starts={{npcID=184062}},ends={{npcID=184062}},coords={x=0.312,y=0.512,source="quest_giver",zoneID=13536},questType="standard"},
[64951] = {id=64951,name="The Road to Haven",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I did not expect to encounter a living mortal and a kyrian this day, but your assistance has been valuable. Before I begin my studies of this automa core, I will guide you to Haven, the settlement founded by my expedition upon our arrival. Though my colleagues saw fit to exile me for challenging their \"Enlightened\" dogma, I have no wish to see Haven wiped from existence by the Jailer. Aid them and they may assist your efforts to return to your allies. We brokers are nothing if not transactional.",objectivesText="Ride with Firim out of the Genesis Repository.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=184062}},ends={{npcID=181561}},coords={x=0.312,y=0.512,source="quest_giver",zoneID=13536},questType="standard"},
[64952] = {id=64952,name="Destroying the Destructors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The Mawsworn possess terrible weapons that gather dark magic and hurl it against our gates. The defensive barrier around Haven will not hold much longer. All that we are, all that we hold dear, will soon be erased from existence. If you are who you claim to be, then prove it to us. Destroy the enemy's armaments and help defend our home. I pray to the First Ones that you succeed.",objectivesText="Destroy 4 Maw Destructors.",rewardGold=128700,starts={{npcID=178016}},ends={{npcID=178016}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64953] = {id=64953,name="Defending Haven",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The Mawsworn are gathering in force outside our very gates. It is clear they mean to overrun our home! The Enlightened wish only to honor the marvels of the First Ones in peace. Haven's defensive barrier was put in place to shield us from minor threats. We did not imagine the Jailer would send his forces against us. You claim to be our ally, mortal? Then help us defend this sacred land.",objectivesText="Defeat 13 Mawsworn in the Great Veldt. Progress: Our pilgrims cannot continue like this.",rewardGold=257400,rewardCurrencies={{id=1822,amount=1},{id=1822,amount=2}},starts={{npcID=177486}},ends={{npcID=177486}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64957] = {id=64957,name="This Old Waystone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1970,description="The Jailer has withdrawn his forces. I should be relieved, but I fear this means he has found a way into the Sepulcher. Elder Ara trembles.> Despite Elder Kreth's doubts, you have proven to be an ally. Something we need more of. When our expedition arrived in Zereth Mortis , we discovered a dormant waystone. If you are indeed a Maw Walker, then the prophecies tell us that you will be able to activate it. If your allies can save this sacred place, then the path to them must be opened. Come.",objectivesText="Open the Waystone to Oribos.",rewardGold=128700,rewardXP=4085,starts={{npcID=178016}},ends={{npcID=178016}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[64958] = {id=64958,name="The Forces Gather",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I am relieved that you survived the passage to Zereth Mortis . From what I've overheard of Pelagos's conversation with Kleia, it sounds like you had an incredible journey. These Enlightened brokers could make valuable allies. Their knowledge of the automa and the land itself should help us against the Jailer. Our forces are gathered and ready to follow you to Zereth Mortis . The final battle lies before us, $p.",rewardGold=257400,rewardXP=1020,rewardItems={188038,188039,188040,188041,188042,188043,188046,188047,188048,188049,188050,188051,188056,189544},rewardChoices={188038,188039,188041,188043,188046,188049,188050,188056},ends={{npcID=177486}},questType="standard"},
[64959] = {id=64959,name="Otter Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Otter Soul is swift and boastful. The shape of the otter will be yours to call upon.>",objectivesText="Bring the Otter Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
[64960] = {id=64960,name="Feed the Annelids",expansion=8,mapID=1970,rewardItems={187816,187820},questType="world",db2Objectives={{orderIndex=2,type=0,amount=10,objectID=181703,text="Hungry Annelid fed with Mawsworn"}},worldTaskTitle="Feed the Annelids",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[64961] = {id=64961,name="Cat Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Cat Soul is elegant and inquisitive. The shape of the cat will be yours to call upon.>",objectivesText="Bring the Cat Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
[64962] = {id=64962,name="As Foretold",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13753,mapID=1970,description="The spheres are in place. A melody builds. Go--bring forth the chorus of Scryers, that the cycle of rebirth may begin.",objectivesText="Bring Firim and the Scryers to the center. Progress: The song awaits its chorus.",rewardGold=128700,rewardXP=4085,rewardCurrencies={{id=1822,amount=1}},starts={{npcID=180942}},ends={{npcID=180942}},coords={x=0.57,y=0.31,source="quest_giver",zoneID=13536},questType="standard"},
[64963] = {id=64963,name="A Defector's Request",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="<Unrolling the scroll, you can make out that it's a coded arms requisition from the Maldraxxi of Death's End to their venthyr allies... all servants of the Jailer. Surely someone among the Death's Advance in Korthia will be able to help you fully break the code and learn exactly what they were planning.>",objectivesText="Deliver the missive to Duchess Mynx in Keeper's Respite in Korthia. Provided item:",ends={{npcID=179321}},coords={mapID=1961,source="quest_giver",x=0.634,y=0.235},questType="standard"},
[64964] = {id=64964,name="Choose Your Fighter",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The presence of the Jailer's forces at Provis Strata have been causing untold damage to the region. If left unchecked, we will lose all knowledge in the area. One of our kin has prepared some automa to deal with the Mawsworn. Meet with them, and fight back against those who would disrespect Zereth Mortis in this manner.",rewardXP=8165,rewardItems={189544,190189,190342,190343,190344,190345,190347,190348,190350,190351,190352,190353,190354,190355,190356,190357,190358,190360,190362,190363,190364,190365,190366,190368,190370,190371,190372,190605,190632,190633,190634,190635,192422,192423,192424,192425,192427,192428,192430,192450,192451},rewardCurrencies={{id=2009,amount=75}},starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Choose Your Fighter"},
[64969] = {id=64969,name="In the Weeds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I understand now why Elder Nirav is filled with worry. Many of the pilgrims who have journeyed to the Catalyst Wards have not returned. This includes Feroz, who is most likely to have information we need to restore the remnants. Prepare yourself. The First Ones's newest creations are prevalent at the Catalyst. If something has gone wrong there, it could be tragically dangerous.",objectivesText="Meet Elder Ara outside the Catalyst Wards.",rewardGold=25740,rewardXP=1020,starts={{npcID=183530}},ends={{npcID=183338}},coords={x=0.61,y=0.506,source="quest_giver",zoneID=13536},questType="standard"},
[64970] = {id=64970,name="Timeworn Keystone: The Broken Isles",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,description="I recently came into possession of a unique keystone. It may look old and worn, but I believe it still has a story to tell. Take it with you. Perhaps it will serve as a reminder of adventures long past. Adventures I hope you will tell me about, of course.",objectivesText="Complete a Timeworn Keystone dungeon.",rewardItems={184315},starts={{npcID=178804}},ends={{npcID=178804}},questType="standard"},
[64974] = {id=64974,name="Clean Up, Automa Aisle",expansion=8,mapID=1970,rewardItems={187841},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Plain of Actualization cleared"}},worldTaskTitle="Clean Up, Automa Aisle",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[64977] = {id=64977,name="Step Into the Ring",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13708,mapID=1970,description="One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary. In the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible. Go there, challenge what the forge creates and report back to me.",rewardItems={189544,190189,190341,190342,190343,190345,190346,190347,190349,190350,190351,190352,190353,190354,190357,190359,190360,190361,190362,190365,190368,190369,190370,190605,190632,190633,190634,190635,192422,192423,192424,192428,192430,192449,192450,192451},rewardCurrencies={{id=1979,amount=18},{id=1979,amount=22},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Step Into the Ring"},
[64984] = {id=64984,name="Bunny Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Bunny Soul is clever and quick. The shape of the bunny will be yours to call upon.>",objectivesText="Bring the Bunny Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
