[64989] = {id=64989,name="Porcupine Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Porcupine Soul is cautious and shy. The shape of the porcupine will be yours to call upon.>",objectivesText="Bring the Porcupine Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
[64990] = {id=64990,name="Cricket Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Cricket Soul is a lucky one. The shape of the cricket will be yours to call upon.>",objectivesText="Bring the Cricket Soul to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
