[64993] = {id=64993,name="Saurolisk Hatchling Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Saurolisk Hatchling Soul is tenacious and fierce. The shape of the saurolisk hatchling will be yours to call upon.>",objectivesText="Bring the Saurolisk Hatchling Soull to Choofa in the Heart of the Forest. Provided item:",questType="standard"},
