[65072] = {id=65072,name="Not Safe for Work",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis . Rana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics. Please travel to the Ageless Shards, and help Rana collect the relics.",rewardXP=8165,rewardItems={187944},rewardCurrencies={{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Not Safe for Work"},
[65081] = {id=65081,name="An Apple A Day",expansion=8,mapID=1970,rewardItems={187949},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182409,text="Attack Crispin to dislodge apples"}},worldTaskTitle="An Apple A Day",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65089] = {id=65089,name="Frog'it",expansion=8,mapID=1970,rewardItems={187987},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182444,text="Bounding Bufonid mounted"},{orderIndex=1,type=0,amount=30,objectID=181052,text="Stolen Amocite Symbols recovered"}},worldTaskTitle="Frog'it",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65096] = {id=65096,name="Your Death Or Mine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We have obtained a wealth of information from relics discovered at the Ageless Shards. The Mawsworn are aware of our discoveries, and are trying to stop us. They have placed traps around the area to block access to the relics. We cannot allow the Jailer to cut off our access to those relics. Please eliminate this Mawsworn threat, and recover as many relics as possible.",rewardXP=8165,rewardItems={187996},rewardCurrencies={{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Your Death Or Mine"},
[65102] = {id=65102,name="Fish Eyes",expansion=8,mapID=1970,rewardItems={187999},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182701,text="Use Fishing Portal to capture Souldrinker"}},worldTaskTitle="Fish Eyes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
