[65117] = {id=65117,name="Bad Samples",expansion=8,mapID=1970,questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=182719,text="Injured Enlightened rescued"},{orderIndex=0,type=1,amount=20,objectID=188121,text="Warped Anima Sample"},{orderIndex=2,type=0,amount=1,objectID=182774,text="Sample Container recovered"}},worldTaskTitle="Bad Samples",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65119] = {id=65119,name="Automa Ops",expansion=8,mapID=1970,rewardItems={188137},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182850,text="Meet up with Rana"},{orderIndex=1,type=1,amount=1,objectID=188137,text="Targeting Relic obtained"},{orderIndex=2,type=15,amount=1,objectID=0,text="Mawsworn forces destroyed"},{orderIndex=3,type=0,amount=17,objectID=182858,text="Elite Value"},{orderIndex=5,type=0,amount=40,objectID=181063,text="Eric's Area"},{orderIndex=6,type=0,amount=40,objectID=182858,text="1/1"}},worldTaskTitle="Automa Ops",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65142] = {id=65142,name="Portal Play",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="To aid in my studies, I have used a network of travel portals to install monitoring devices all over Zereth Mortis . My devices have been quite successful at collecting large amounts of research data. It's time now to collect the data they have obtained. Use my portal network to locate my Prying Eyes and collect any data they have gathered. I'll give you a portal initiator as well, allowing you to re-enter the portal network, incase you find yourself lost!",rewardXP=8165,rewardItems={188170},rewardCurrencies={{id=1979,amount=21},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Portal Play"},
[65143] = {id=65143,name="Antros",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,rewardXP=8165,questType="world",worldTaskTitle="Antros",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[65152] = {id=65152,name="A Hardened Bond",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,rewardGold=128700,rewardXP=4085,questType="world",worldTaskTitle="A Hardened Bond"},
[65177] = {id=65177,name="Fruit of the Bloom",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We never know when something new may emerge from the confluence of creation and energy. The Catalyst Gardens have blossomed with a new crop of fruit. Their seeds may have special properties, and we wish to understand them. Please gather what you can find, and make the gardens safer for the future.",rewardItems={188230},rewardCurrencies={{id=1979,amount=20},{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Fruit of the Bloom"},
[65226] = {id=65226,name="Fleet-Footed and Fastidious",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="When the Mawsworn came to Zereth Mortis , they brought mawrats with them! A swarm of their mawrats overran my cave, making off with many of our research items! Rana is assembling a team to help recover the items. Meet up with her and aid in the effort.",rewardXP=8165,rewardItems={188121},rewardCurrencies={{id=2009,amount=75}},starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Fleet-Footed and Fastidious"},
[65230] = {id=65230,name="Bot-any",expansion=8,mapID=1970,questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=183537,text="Vine-Choked or Overgrown creatures slain"}},worldTaskTitle="Bot-any",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
